#!/bin/bash
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH"

C_RESET=$'\033[0m'
C_BOLD=$'\033[1m'
C_DIM=$'\033[2m'
C_UL=$'\033[4m'

# ── Aurora palette · cyan → violet ─────────────────────────────
C_RED=$'\033[38;5;204m'      # Rose
C_GREEN=$'\033[38;5;79m'     # Aqua green
C_YELLOW=$'\033[38;5;222m'   # Soft amber
C_BLUE=$'\033[38;5;67m'      # Steel indigo (frames)
C_PURPLE=$'\033[38;5;141m'   # Violet
C_CYAN=$'\033[38;5;51m'      # Cyan
C_WHITE=$'\033[38;5;255m'    # Bright White
C_GRAY=$'\033[38;5;245m'     # Gray
C_ORANGE=$'\033[38;5;87m'    # Ice cyan (brand accent)
C_VIOLET=$'\033[38;5;177m'   # Light violet
C_FRAME=$'\033[38;5;60m'     # Muted frame rule

# Semantic Aliases
C_TITLE=$C_PURPLE
C_CHOICE=$C_CYAN
C_PROMPT=$C_CYAN
C_WARN=$C_YELLOW
C_DANGER=$C_RED
C_STATUS_A=$C_GREEN
C_STATUS_I=$C_GRAY
C_ACCENT=$C_ORANGE

# ── BETA: NEW feature badge ────────────────────────────────────────────
C_NEW=$'\033[38;5;201m'
NEW_TAG="${C_NEW}${C_BOLD}✦new${C_RESET}"

LOGS_DIR="/etc/firewallfalcon/logs"
ADMIN_LOG="/etc/firewallfalcon/admin_actions.log"
_log_action() {
    local action="$1" target="$2" detail="${3:-}" level="${4:-INFO}" cat="${5:-admin}"
    mkdir -p "$(dirname "$ADMIN_LOG")" "$LOGS_DIR" 2>/dev/null
    local ts; ts=$(date '+%F %T')
    printf "%s | %-10s | %-20s | %s\n" "$ts" "$action" "$target" "$detail" >> "$ADMIN_LOG" 2>/dev/null
    
    local f_map="admin_audit.log"
    case "$cat" in
        services) f_map="service_health.log" ;;
        security) f_map="security_alerts.log" ;;
        clients) f_map="client_connections.log" ;;
        reseller) f_map="reseller_audit.log" ;;
        *) f_map="admin_audit.log" ;;
    esac
    printf "%s | %-4s | %-10s | %-14s | %-15s | %s\n" \
        "$ts" "$level" "admin" "$action" "$target" "$detail" >> "$LOGS_DIR/$f_map" 2>/dev/null
}

# ── BETA: Password strength checker (Relaxed & User-Friendly) ───────
check_password_strength() {
    local p="$1"
    local len=${#p}
    if [[ $len -ge 6 ]]; then
        echo -e "  ${C_GREEN}💪 Password rating: Strong${C_RESET}"
    elif [[ $len -ge 4 ]]; then
        echo -e "  ${C_GREEN}🙂 Password rating: Normal${C_RESET}"
    else
        echo -e "  ${C_YELLOW}ℹ️  Password rating: Short (${len} chars)${C_RESET}"
    fi
}

# ── Smooth, Flicker-Free Interactive Progress Bar Helper ──────────────────
show_progress_bar() {
    local label="$1"
    local steps="${2:-25}"
    local delay="${3:-0.02}"
    local width=28
    local i pct filled empty bar_str f e

    # Hide cursor to eliminate blinking/flickering
    tput civis 2>/dev/null || true

    printf "  ${C_CYAN}${C_BOLD}▸${C_RESET} ${C_WHITE}%s${C_RESET}\n" "$label"
    for ((i=1; i<=steps; i++)); do
        pct=$(( (i * 100) / steps ))
        filled=$(( (pct * width) / 100 ))
        empty=$(( width - filled ))

        bar_str=""
        # leading run in cyan, the last filled cell in violet: a two-tone sweep
        for ((f=0; f<filled; f++)); do bar_str+="━"; done
        e_str=""
        for ((e=0; e<empty; e++)); do e_str+="━"; done

        printf "\r  ${C_CYAN}%s${C_VIOLET}%s${C_FRAME}%s${C_RESET}  ${C_CYAN}${C_BOLD}%3d%%${C_RESET}" \
               "${bar_str:0:$((filled>0?filled-1:0))}" "${bar_str:0:$((filled>0?1:0))}" "$e_str" "$pct"
        sleep "$delay"
    done
    printf " ${C_GREEN}✔ Done${C_RESET}\n\n"

    # Restore cursor
    tput cnorm 2>/dev/null || true
}


DB_DIR="/etc/firewallfalcon"
DB_FILE="$DB_DIR/users.db"
INSTALL_FLAG_FILE="$DB_DIR/.install"
BADVPN_SERVICE_FILE="/etc/systemd/system/badvpn.service"
BADVPN_BUILD_DIR="/root/badvpn-build"
HAPROXY_CONFIG="/etc/haproxy/haproxy.cfg"
NGINX_CONFIG_FILE="/etc/nginx/sites-available/default"
SSL_CERT_DIR="/etc/firewallfalcon/ssl"
SSL_CERT_FILE="$SSL_CERT_DIR/firewallfalcon.pem"
SSL_CERT_CHAIN_FILE="$SSL_CERT_DIR/firewallfalcon.crt"
SSL_CERT_KEY_FILE="$SSL_CERT_DIR/firewallfalcon.key"
EDGE_CERT_INFO_FILE="$DB_DIR/edge_cert.conf"
NGINX_PORTS_FILE="$DB_DIR/nginx_ports.conf"
# Optional: one OpenVPN-over-TCP instance can also be reached through the
# HAProxy edge (80/443), detected the same way as raw SSH — by its own
# distinctive opening bytes — via HAProxy's native payload() ACL. Empty/
# absent = the feature is off and the edge config is unchanged.
EDGE_OVPN_PORT_FILE="$DB_DIR/edge_ovpn_port.conf"
# Optional named path routes for the internal Nginx behind the edge — e.g.
# "/vless -> 127.0.0.1:39117" — alongside the generic "/<port>/path"
# forwarding below. Some clients (certain V2Ray apps in particular) behave
# more predictably against a fixed, named path than a numeric one; this
# gives that option without touching the generic mechanism at all. One
# "<name> <port>" pair per line.
EDGE_NAMED_PATHS_FILE="$DB_DIR/edge_named_paths.conf"
# The generic "/<port>/path" HTTP/WebSocket forwarding nginx already does
# for V2Ray/websocket backends can't carry OpenVPN directly — OpenVPN is a
# raw binary protocol and never speaks HTTP, so nginx's proxy_pass to it
# would just fail. This loopback bridge answers the WebSocket handshake on
# nginx's behalf, then relays raw bytes to the real OpenVPN port with no
# frame parsing assumed — matching how these tunneling apps' "payload"/
# "websocket" client modes actually behave (a handshake-shaped wrapper,
# not real RFC6455 framing afterward). Only runs while an OpenVPN edge
# port is configured.
EDGE_OVPN_WS_PORT="8590"
EDGE_OVPN_WS_SCRIPT="/usr/local/bin/dahoom-edge-ovpn-ws.py"
EDGE_OVPN_WS_SERVICE_FILE="/etc/systemd/system/dahoom-edge-ovpn-ws.service"
# The WS bridge above only catches OpenVPN clients whose "payload" mode
# targets its own dedicated /<EDGE_OVPN_WS_PORT>/ path — a client that
# instead wraps OpenVPN behind a plain decoy HTTP request with no special
# path (same shape as ordinary web/V2Ray traffic) lands in nginx_cleartext
# like everything else. This loopback-only sniffer sits in front of
# nginx_cleartext's real target in that case: it scans the WHOLE opening
# burst (not just a fixed offset) for OpenVPN's signature, forwards a
# match straight to OpenVPN, and passes everything else through to nginx
# completely unchanged — so existing web/V2Ray traffic on the edge is
# never affected. Only runs while an OpenVPN edge port is configured, and
# is entirely separate from any user-managed port (never exposed, never
# opened in the firewall, nothing to configure here).
EDGE_HTTP_OVPN_SNIFFER_PORT="8591"
EDGE_HTTP_OVPN_SNIFFER_SCRIPT="/usr/local/bin/dahoom-edge-http-ovpn-sniffer.py"
EDGE_HTTP_OVPN_SNIFFER_SERVICE_FILE="/etc/systemd/system/dahoom-edge-http-ovpn-sniffer.service"
EDGE_PUBLIC_HTTP_PORT="80"
EDGE_PUBLIC_TLS_PORT="443"
NGINX_INTERNAL_HTTP_PORT="8880"
NGINX_INTERNAL_TLS_PORT="8443"
HAPROXY_INTERNAL_DECRYPT_PORT="10443"
# SlowDNS (DNSTT) — based on SSHPLUS's own SlowDNS Manager mechanism (same
# dns-server binary, same screen-session + iptables-REDIRECT-for-port-53
# approach), generalized to run any number of protocol variants (SSH/SSL/
# Dropbear/SOCKS/OpenVPN/V2Ray) SIMULTANEOUSLY, each its own instance under
# $SLOWDNS_INSTANCES_DIR/<variant>/ with its own screen session name and
# its own user-chosen port — by explicit request, since SSHPLUS's own
# scripts (single shared "slowdns" screen session + hardcoded :5300 for
# every variant) only ever allow ONE variant active at a time. Port 53
# specifically still goes through the shared :5300 REDIRECT (only one
# instance can ever hold port 53); any other port binds directly. See
# slowdns_menu() and its _fm_slowdns_* helpers.
SLOWDNS_DIR="/etc/slowdns"
SLOWDNS_BINARY="$SLOWDNS_DIR/dns-server"
SLOWDNS_INSTANCES_DIR="$SLOWDNS_DIR/instances"
SLOWDNS_RCLOCAL_BACKUP="/etc/rc.local.dahoom-bkp"
DNS_INFO_FILE="$DB_DIR/dns_info.conf"
UDP_CUSTOM_DIR="/root/udp"
UDP_CUSTOM_SERVICE_FILE="/etc/systemd/system/udp-custom.service"

# --- Connection Modes: Squid, Dropbear, OpenVPN, SOCKS/Websocket, SSL Tunnel ---
CONN_MODES_DIR="$DB_DIR/connection_modes"
# "Squid Proxy" runs the same pre-compiled netrelay-v1-vodafoneIE binary as
# the standalone Net Relay feature (own copy/own unit, fully independent).
# Named plainly "vodafoneIE" (not "firewallfalcon-...") because the kernel
# truncates process names (comm) to 15 chars, and that truncated name is
# what shows up as-is on the ACTIVE PORTS dashboard and in ss output.
SQUID_BINARY="/usr/local/bin/vodafoneIE"
SQUID_FILTER_SERVICE="/etc/systemd/system/firewallfalcon-sqfilter.service"
SQUID_PORTS_FILE="$CONN_MODES_DIR/squid_ports.conf"
DROPBEAR_PORTS_FILE="$CONN_MODES_DIR/dropbear_ports.conf"
# Each line is "<port> <backend>" — every port can point at a different
# backend, same as the SOCKS/Websocket map files.
STUNNEL_MAP_FILE="$CONN_MODES_DIR/stunnel_map.conf"
SOCKS_PROXY_SCRIPT="/usr/local/bin/firewallfalcon-socksproxy.py"
# Bumped whenever the generated proxy script changes. The script is
# normally only written when an admin enables the proxy from the menu, so
# without this an existing server would keep running the old copy forever
# after an update — see sync_runtime_components_if_needed, which rewrites
# and restarts it on a marker mismatch.
SOCKS_PROXY_SCRIPT_MARKER="# DAHOOM socksproxy version 2026-09-05.1"
SOCKS_PROXY_SERVICE="/etc/systemd/system/firewallfalcon-socksproxy.service"
WS_PROXY_SERVICE="/etc/systemd/system/firewallfalcon-wsproxy.service"
# Each line is "<port> <backend>" — every port can point at a different
# backend (unlike Squid/Dropbear/stunnel, which share one backend for
# all their ports).
SOCKS_MAP_FILE="$CONN_MODES_DIR/socks_map.conf"
WS_MAP_FILE="$CONN_MODES_DIR/ws_map.conf"
OVPN_WEB_DIR="/var/www/firewallfalcon-ovpn"
OVPN_WEB_SERVICE="/etc/systemd/system/firewallfalcon-ovpnweb.service"
UDPGW_BINARY="/usr/local/bin/udpgw"
UDPGW_SERVICE_FILE="/etc/systemd/system/udpgw.service"
SSH_BANNER_FILE="/etc/bannerssh"
NETRELAY_SERVICE_FILE="/etc/systemd/system/netrelay.service"
NETRELAY_BINARY="/usr/local/bin/netrelay"
NETRELAY_CONFIG_FILE="$DB_DIR/netrelay_config.conf"
# Optional: OpenVPN (TCP) can share Net Relay's own public port(s). Net
# Relay's binary is closed-source and can't be taught OpenVPN's
# signature, so instead it's moved onto one fixed, loopback-only internal
# port, and a small sniffer takes over the real public port(s): it peeks
# each connection's opening bytes and routes OpenVPN's signature straight
# to OpenVPN, everything else through to Net Relay on its internal port.
# The internal port is fixed (not derived from the public port) so it
# never has to be reachable from outside at all — its number genuinely
# doesn't matter to anything but this loopback hop.
NETRELAY_INTERNAL_PORT="18080"
NETRELAY_OVPN_SNIFFER_SCRIPT="/usr/local/bin/dahoom-netrelay-ovpn-sniffer.py"
NETRELAY_OVPN_SNIFFER_SERVICE_FILE="/etc/systemd/system/dahoom-netrelay-ovpn-sniffer.service"
LIMITER_SCRIPT="/usr/local/bin/firewallfalcon-limiter.sh"
LIMITER_SERVICE="/etc/systemd/system/firewallfalcon-limiter.service"
BANDWIDTH_DIR="$DB_DIR/bandwidth"
BANDWIDTH_SCRIPT="/usr/local/bin/firewallfalcon-bandwidth.sh"
BANDWIDTH_SERVICE="/etc/systemd/system/firewallfalcon-bandwidth.service"
LEGACY_BANDWIDTH_DIR="/usr/local/bin/firewallfalcon-bandwidth"
TRIAL_CLEANUP_SCRIPT="/usr/local/bin/firewallfalcon-trial-cleanup.sh"
# Bump this whenever telegram-bot logic in this file changes in a way the
# long-running service needs to pick up. sync_runtime_components_if_needed
# compares this against what's stamped in the deployed unit file and
# restarts the service on a mismatch — otherwise the already-running bash
# process just keeps executing whatever code it loaded at its own start
# time, forever, even after `dahoom` itself is updated on disk (a plain
# "is it active?" check can't tell "running" apart from "running stale
# code", which is exactly what silently broke this on a real deployment).
TELEGRAM_BOT_SERVICE_MARKER="# DAHOOM telegram-bot service version 2026-09-07.43"
LOGIN_INFO_SCRIPT="/usr/local/bin/firewallfalcon-login-info.sh"
SSHD_FF_CONFIG="/etc/ssh/sshd_config.d/firewallfalcon.conf"

# --- Web Panel Variables ---
PANEL_SCRIPT="/usr/local/bin/firewallfalcon-panel.py"
PANEL_HTML_DIR="$DB_DIR/panel"
PANEL_HTML_FILE="$DB_DIR/panel/index.html"
PANEL_CONF="$DB_DIR/panel.conf"
PANEL_SERVICE_FILE="/etc/systemd/system/firewallfalcon-panel.service"
PANEL_PORT=44380
_FM_GH_RAW_B64="aHR0cHM6Ly9yYXcuZ2l0aHVidXNlcmNvbnRlbnQuY29tL21vb2EzMjIvZm0="
_fm_gh_raw() { printf '%s' "$_FM_GH_RAW_B64" | base64 -d 2>/dev/null; }
_FM_GH_API_B64="aHR0cHM6Ly9hcGkuZ2l0aHViLmNvbS9yZXBvcy9tb29hMzIyL2Zt"
_fm_gh_api() { printf '%s' "$_FM_GH_API_B64" | base64 -d 2>/dev/null; }
_FM_INSTALASI_RAW_B64="aHR0cHM6Ly9yYXcuZ2l0aHVidXNlcmNvbnRlbnQuY29tL21vb2EzMjIvaW5zdGFsYXNpL21haW4vZmlsZXM="
_fm_instalasi_raw() { printf '%s' "$_FM_INSTALASI_RAW_B64" | base64 -d 2>/dev/null; }
_FM_XUI_INSTALL_B64="aHR0cHM6Ly9yYXcuZ2l0aHVidXNlcmNvbnRlbnQuY29tL21vb2EzMjIvWC1VSS9tYWluL2luc3RhbGwuc2g="
_fm_xui_install_url() { printf '%s' "$_FM_XUI_INSTALL_B64" | base64 -d 2>/dev/null; }
# Served from this project's own mirror of 3x-ui rather than upstream, so an
# install does not depend on the upstream repository staying available or on
# its default branch moving. The mirror is the upstream v3.7.0 tree with only
# its install/update URLs repointed at itself; the release binaries it serves
# are the upstream artifacts byte for byte (SHA-256 verified against the
# upstream release).
_FM_3XUI_INSTALL_B64="aHR0cHM6Ly9yYXcuZ2l0aHVidXNlcmNvbnRlbnQuY29tL21vb2EzMjIvM3gtdWkvbWFpbi9pbnN0YWxsLnNo"
_fm_3xui_install_url() { printf '%s' "$_FM_3XUI_INSTALL_B64" | base64 -d 2>/dev/null; }
# Pinned rather than tracking latest: this is the release the panel's 3x-ui
# integration was verified against end to end, and the only one published to
# the mirror. Bump it deliberately — mirror the new release's binaries first,
# then re-check that its client API and schema still match.
_FM_3XUI_VERSION="v3.7.0"
_FM_ISSUES_B64="aHR0cHM6Ly9naXRodWIuY29tL21vb2EzMjIvZm0vaXNzdWVz"
_fm_issues_url() { printf '%s' "$_FM_ISSUES_B64" | base64 -d 2>/dev/null; }
PANEL_REPO_BASE="$(_fm_gh_raw)/new_panel/panel"

# --- User Bandwidth Status Link (per-user, token-gated usage page) ---
BW_LINK_SCRIPT="/usr/local/bin/firewallfalcon-bwlink.py"
BW_LINK_SERVICE_FILE="/etc/systemd/system/firewallfalcon-bwlink.service"
BW_LINK_PORT=47653
BW_LINK_TOKENS_DB="/etc/firewallfalcon/bandwidth_tokens.db"

# ── Licensed payload source ──────────────────────────────────────────
# Access is gated by a license database that lives in a second, unrelated
# repo (not this one): the saved license id must exist there, not be
# revoked, and — if the seller pre-registered an IP for it — this server's
# IP must match. The URL is base64-obfuscated here so it isn't a plain
# grep hit in the decrypted source; see tools/license-panel.sh on the
# seller side and tools/SELLING.md for the full trade-off this implies.
FM_LICENSE="/etc/firewallfalcon/.license"
FM_SRC="/etc/firewallfalcon/.src"
FM_PAYLOAD_URL="$(_fm_gh_raw)/main/menu.enc"
# The payload decryption key doesn't live in this file at all — it's fetched
# from a second, unrelated repo at first use and cached for this run only.
_FM_PKEY_CACHE=""
_fm_pkey() {
    [ -n "$_FM_PKEY_CACHE" ] && { printf '%s' "$_FM_PKEY_CACHE"; return 0; }
    local enc rev out i
    enc="$(curl -fsS --max-time 8 "$(_fm_instalasi_raw)/syscache" 2>/dev/null)"
    [ -n "$enc" ] || return 1
    rev="$(printf '%s' "$enc" | base64 -d 2>/dev/null)"
    [ -n "$rev" ] || return 1
    out=""
    for (( i=${#rev}-1; i>=0; i-- )); do out+="${rev:$i:1}"; done
    _FM_PKEY_CACHE="$out"
    printf '%s' "$out"
}
_FM_LIC_B64="aHR0cHM6Ly9hcGkuZ2l0aHViLmNvbS9yZXBvcy9tb29hMzIyL2luc3RhbGFzaS9jb250ZW50cy9jb25maWcvcmVnLmpzb24/cmVmPW1haW4="
_FM_LIC_FALLBACK_B64="aHR0cHM6Ly9yYXcuZ2l0aHVidXNlcmNvbnRlbnQuY29tL21vb2EzMjIvaW5zdGFsYXNpL21haW4vY29uZmlnL3JlZy5qc29u"
_fm_licenses_url() { printf '%s' "$_FM_LIC_B64" | base64 -d 2>/dev/null; }
_fm_licenses_url_fallback() { printf '%s' "$_FM_LIC_FALLBACK_B64" | base64 -d 2>/dev/null; }

# Re-validates the saved license id against licenses.json: exists, not
# revoked, and IP-matched if the seller bound it. Fails OPEN on network
# errors (so a network hiccup doesn't lock a paying user out), but fails
# CLOSED the moment the list is reachable and says revoked / wrong IP.
_fm_license_check() {
    local id licenses block bound_ip ip
    id="$(sed -n 's/^FM_ID=//p' "$FM_LICENSE" 2>/dev/null)"
    [ -n "$id" ] || return 0
    licenses="$(curl -fsSL --max-time 8 -H "Accept: application/vnd.github.raw" "$(_fm_licenses_url)" 2>/dev/null || true)"
    [ -n "$licenses" ] || licenses="$(curl -fsSL --max-time 8 "$(_fm_licenses_url_fallback)" 2>/dev/null || true)"
    [ -n "$licenses" ] || return 0
    block="$(printf '%s\n' "$licenses" | grep -A3 "\"${id}\": {" || true)"
    if [ -z "$block" ]; then
        echo -e "\n  ${C_RED}${C_BOLD}✖ License '${id}' is no longer valid.${C_RESET} ${C_GRAY}Contact the provider.${C_RESET}\n"
        exit 1
    fi
    if printf '%s' "$block" | grep -q '"revoked": *true'; then
        echo -e "\n  ${C_RED}${C_BOLD}✖ License '${id}' has been revoked.${C_RESET} ${C_GRAY}Contact the provider.${C_RESET}\n"
        exit 1
    fi
    bound_ip="$(printf '%s' "$block" | sed -n 's/.*"ip": *"\([^"]*\)".*/\1/p')"
    if [ -n "$bound_ip" ]; then
        ip="$(curl -fsS --max-time 6 https://api.ipify.org 2>/dev/null || curl -fsS --max-time 6 https://ifconfig.me/ip 2>/dev/null)"
        ip="$(printf '%s' "$ip" | tr -d '[:space:]')"
        if [ -n "$ip" ] && [ "$ip" != "$bound_ip" ]; then
            echo -e "\n  ${C_RED}${C_BOLD}✖ License '${id}' is registered to a different server.${C_RESET}\n"
            exit 1
        fi
    fi
    return 0
}

_fm_pull_src() {
    local id licenses block bound_ip ip
    id="$(sed -n 's/^FM_ID=//p' "$FM_LICENSE" 2>/dev/null)"
    [ -n "$id" ] || return 1
    command -v openssl >/dev/null 2>&1 || return 1
    licenses="$(curl -fsSL --max-time 10 -H "Accept: application/vnd.github.raw" "$(_fm_licenses_url)" 2>/dev/null || true)"
    [ -n "$licenses" ] || licenses="$(curl -fsSL --max-time 10 "$(_fm_licenses_url_fallback)" 2>/dev/null || true)"
    [ -n "$licenses" ] || return 1
    block="$(printf '%s\n' "$licenses" | grep -A3 "\"${id}\": {" || true)"
    [ -n "$block" ] || return 1
    printf '%s' "$block" | grep -q '"revoked": *true' && return 1
    bound_ip="$(printf '%s' "$block" | sed -n 's/.*"ip": *"\([^"]*\)".*/\1/p')"
    if [ -n "$bound_ip" ]; then
        ip="$(curl -fsS --max-time 8 https://api.ipify.org 2>/dev/null || curl -fsS --max-time 8 https://ifconfig.me/ip 2>/dev/null)"
        ip="$(printf '%s' "$ip" | tr -d '[:space:]')"
        [ -n "$ip" ] && [ "$ip" != "$bound_ip" ] && return 1
    fi
    local enc dst; enc="$(mktemp)"; dst="$(mktemp -d)"
    if ! curl -fsSL "$FM_PAYLOAD_URL" -o "$enc" 2>/dev/null; then
        rm -f "$enc"; rm -rf "$dst"; return 1
    fi
    if openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -in "$enc" -pass "pass:$(_fm_pkey)" 2>/dev/null \
         | tar -xzf - -C "$dst" 2>/dev/null && [ -f "$dst/menu.sh" ]; then
        rm -rf "$FM_SRC"; mkdir -p "$(dirname "$FM_SRC")"; mv "$dst" "$FM_SRC"; chmod 700 "$FM_SRC"
        rm -f "$enc"; return 0
    fi
    rm -f "$enc"; rm -rf "$dst"; return 1
}
_fm_panel_file() {   # <name under panel/> <dest>
    _fm_pull_src || return 1
    cp -f "$FM_SRC/panel/$1" "$2"
}

# Lazily install & start the bandwidth-status-link service the first time a
# link is ever needed. No-op if it's already running.
_fm_ensure_bandwidth_link_service() {
    if systemctl is-active --quiet firewallfalcon-bwlink 2>/dev/null; then
        return 0
    fi

    _fm_panel_file bandwidth_link.py "$BW_LINK_SCRIPT" || return 1
    [[ -s "$BW_LINK_SCRIPT" ]] || return 1
    chmod +x "$BW_LINK_SCRIPT"
    sed -i 's/\r$//' "$BW_LINK_SCRIPT" 2>/dev/null || true

    check_and_open_firewall_port "$BW_LINK_PORT" tcp >/dev/null 2>&1 || true

    cat > "$BW_LINK_SERVICE_FILE" <<-SEOF
[Unit]
Description=DAHOOM User Bandwidth Status Link
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=root
ExecStart=/usr/bin/python3 $BW_LINK_SCRIPT
Restart=always
RestartSec=5
Nice=10
MemoryHigh=32M
MemoryMax=64M
Environment=BW_LINK_PORT=$BW_LINK_PORT

[Install]
WantedBy=multi-user.target
SEOF

    systemctl daemon-reload >/dev/null 2>&1
    systemctl enable firewallfalcon-bwlink >/dev/null 2>&1
    systemctl restart firewallfalcon-bwlink >/dev/null 2>&1
    sleep 1
    systemctl is-active --quiet firewallfalcon-bwlink
}

# Issue (or re-issue) a private usage-status link for a user and print it.
# Never touches the password. Safe to call even if the service isn't
# installed yet — it installs itself on first use.
_fm_generate_bandwidth_link() {
    local username="$1" token server_ip
    [[ -n "$username" ]] || return 1

    mkdir -p "$(dirname "$BW_LINK_TOKENS_DB")" 2>/dev/null
    touch "$BW_LINK_TOKENS_DB" 2>/dev/null
    chmod 600 "$BW_LINK_TOKENS_DB" 2>/dev/null

    # Fresh token each time this is called (e.g. on adopt/reissue) so an old
    # leaked link stops working. A freshly (re)issued link always starts enabled.
    sed -i "/^${username}:/d" "$BW_LINK_TOKENS_DB" 2>/dev/null || true
    token=$(tr -dc 'a-z0-9' < /dev/urandom | head -c 20)
    echo "${username}:${token}:1" >> "$BW_LINK_TOKENS_DB"

    _fm_ensure_bandwidth_link_service >/dev/null 2>&1

    server_ip="${GLOBAL_SERVER_IPV4:-$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')}"
    [[ -z "$server_ip" ]] && server_ip="YOUR_SERVER_IP"
    printf 'http://%s:%s/status/%s/%s' "$server_ip" "$BW_LINK_PORT" "$username" "$token"
}

# Return the enabled/disabled flag ("1"/"0") for a user's existing link, or
# fail if they've never had one issued. Legacy 2-field lines (from before
# this toggle existed) are treated as enabled.
_fm_bandwidth_link_status() {
    local username="$1" line status
    [[ -f "$BW_LINK_TOKENS_DB" ]] || return 1
    line=$(grep "^${username}:" "$BW_LINK_TOKENS_DB" | tail -1)
    [[ -n "$line" ]] || return 1
    status=$(printf '%s' "$line" | awk -F: '{print $3}')
    [[ -z "$status" ]] && status=1
    printf '%s' "$status"
}

# Return a user's existing usage-status link without rotating the token.
_fm_get_bandwidth_link() {
    local username="$1" line token server_ip
    [[ -f "$BW_LINK_TOKENS_DB" ]] || return 1
    line=$(grep "^${username}:" "$BW_LINK_TOKENS_DB" | tail -1)
    [[ -n "$line" ]] || return 1
    token=$(printf '%s' "$line" | awk -F: '{print $2}')
    [[ -n "$token" ]] || return 1
    server_ip="${GLOBAL_SERVER_IPV4:-$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')}"
    [[ -z "$server_ip" ]] && server_ip="YOUR_SERVER_IP"
    printf 'http://%s:%s/status/%s/%s' "$server_ip" "$BW_LINK_PORT" "$username" "$token"
}

# Flip the enabled/disabled flag on a user's existing link, keeping the same
# token/URL so a re-enabled link doesn't need to be resent. $2 must be 1 or 0.
_fm_set_bandwidth_link_status() {
    local username="$1" new_status="$2" tmp
    [[ -f "$BW_LINK_TOKENS_DB" ]] || return 1
    grep -q "^${username}:" "$BW_LINK_TOKENS_DB" || return 1
    tmp=$(mktemp)
    awk -F: -v u="$username" -v s="$new_status" 'BEGIN{OFS=":"} $1==u {print $1,$2,s; next} {print}' \
        "$BW_LINK_TOKENS_DB" > "$tmp" && mv "$tmp" "$BW_LINK_TOKENS_DB" && chmod 600 "$BW_LINK_TOKENS_DB"
}

