# --- Package Manager Abstraction ---
FF_PKG_MGR=""
_detect_pkg_manager() {
    if command -v apt-get &>/dev/null; then
        FF_PKG_MGR="apt"
    elif command -v dnf &>/dev/null; then
        FF_PKG_MGR="dnf"
    elif command -v yum &>/dev/null; then
        FF_PKG_MGR="yum"
    elif command -v zypper &>/dev/null; then
        FF_PKG_MGR="zypper"
    elif command -v pacman &>/dev/null; then
        FF_PKG_MGR="pacman"
    else
        echo -e "${C_RED}❌ No supported package manager found (apt/dnf/yum/zypper/pacman).${C_RESET}"
        exit 1
    fi
}
_detect_pkg_manager

_map_pkg_names() {
    local -a result=()
    local pkg
    for pkg in "$@"; do
        case "$FF_PKG_MGR" in
            dnf|yum)
                case "$pkg" in
                    build-essential) result+=(gcc gcc-c++ make) ;;
                    libssl-dev) result+=(openssl-devel) ;;
                    libnspr4-dev) result+=(nspr-devel) ;;
                    libnss3-dev) result+=(nss-devel) ;;
                    nginx-common) result+=(nginx) ;;
                    pkg-config) result+=(pkgconf) ;;
                    stunnel4) result+=(stunnel) ;;
                    *) result+=("$pkg") ;;
                esac ;;
            zypper)
                case "$pkg" in
                    build-essential) result+=(gcc gcc-c++ make) ;;
                    libssl-dev) result+=(libopenssl-devel) ;;
                    libnspr4-dev) result+=(mozilla-nspr-devel) ;;
                    libnss3-dev) result+=(mozilla-nss-devel) ;;
                    nginx-common) result+=(nginx) ;;
                    stunnel4) result+=(stunnel) ;;
                    *) result+=("$pkg") ;;
                esac ;;
            pacman)
                case "$pkg" in
                    build-essential) result+=(base-devel) ;;
                    libssl-dev) result+=(openssl) ;;
                    libnspr4-dev) result+=(nspr) ;;
                    libnss3-dev) result+=(nss) ;;
                    nginx-common) result+=(nginx) ;;
                    bc) result+=(bc) ;;
                    stunnel4) result+=(stunnel) ;;
                    *) result+=("$pkg") ;;
                esac ;;
            *) result+=("$pkg") ;;
        esac
    done
    printf '%s\n' "${result[@]}"
}

if [[ $EUID -ne 0 ]]; then
   echo -e "${C_RED}❌ Error: This script requires root privileges to run.${C_RESET}"
   exit 1
fi

get_ubuntu_codename() {
    local codename=""

    if [[ -r /etc/os-release ]]; then
        codename=$(awk -F= '/^(VERSION_CODENAME|UBUNTU_CODENAME)=/{gsub(/"/, "", $2); if ($2 != "") { print $2; exit }}' /etc/os-release 2>/dev/null)
    fi

    if [[ -z "$codename" ]] && command -v lsb_release &>/dev/null; then
        codename=$(lsb_release -sc 2>/dev/null)
    fi

    echo "$codename"
}

is_known_eol_ubuntu_codename() {
    case "$1" in
        yakkety|zesty|artful|cosmic|disco|eoan|groovy|hirsute|impish|kinetic|lunar|mantic|oracular|plucky)
            return 0
            ;;
        *)
            return 1
            ;;
    esac
}

rewrite_ubuntu_apt_sources() {
    local mode="$1"
    local os_id=""
    local changed=false
    local file backup_file
    local from_archive to_archive from_security to_security from_ports to_ports
    local -a source_files=("/etc/apt/sources.list" /etc/apt/sources.list.d/*.list /etc/apt/sources.list.d/*.sources)

    if [[ -r /etc/os-release ]]; then
        os_id=$(awk -F= '/^ID=/{gsub(/"/, "", $2); print $2; exit}' /etc/os-release 2>/dev/null)
    fi
    [[ "$os_id" == "ubuntu" ]] || return 1

    case "$mode" in
        primary)
            from_archive='https?://([A-Za-z0-9-]+\.)?archive\.ubuntu\.com/ubuntu'
            to_archive='http://archive.ubuntu.com/ubuntu'
            from_security='https?://security\.ubuntu\.com/ubuntu'
            to_security='http://security.ubuntu.com/ubuntu'
            from_ports='https?://ports\.ubuntu\.com/ubuntu-ports'
            to_ports='http://ports.ubuntu.com/ubuntu-ports'
            ;;
        old-releases)
            from_archive='https?://([A-Za-z0-9-]+\.)?archive\.ubuntu\.com/ubuntu'
            to_archive='http://old-releases.ubuntu.com/ubuntu'
            from_security='https?://security\.ubuntu\.com/ubuntu'
            to_security='http://old-releases.ubuntu.com/ubuntu'
            from_ports='https?://ports\.ubuntu\.com/ubuntu-ports'
            to_ports='http://old-releases.ubuntu.com/ubuntu'
            ;;
        *)
            return 1
            ;;
    esac

    for file in "${source_files[@]}"; do
        [[ -f "$file" ]] || continue
        if grep -Eq "$from_archive|$from_security|$from_ports" "$file" 2>/dev/null; then
            backup_file="${file}.bak.firewallfalcon"
            [[ -f "$backup_file" ]] || cp "$file" "$backup_file" 2>/dev/null || true
            sed -i -E \
                -e "s|$from_archive|$to_archive|g" \
                -e "s|$from_security|$to_security|g" \
                -e "s|$from_ports|$to_ports|g" \
                "$file" 2>/dev/null
            changed=true
        fi
    done

    $changed
}

repair_ubuntu_apt_mirrors() {
    rewrite_ubuntu_apt_sources "primary"
}

switch_ubuntu_to_old_releases() {
    local codename
    codename=$(get_ubuntu_codename)
    [[ -n "$codename" ]] || return 1
    is_known_eol_ubuntu_codename "$codename" || return 1
    rewrite_ubuntu_apt_sources "old-releases"
}

ff_apt_update() {
    local -a apt_opts=(
        -o Acquire::Retries=3
        -o Acquire::ForceIPv4=true
        -o Acquire::http::Timeout=20
        -o Acquire::https::Timeout=20
        -o Acquire::http::Pipeline-Depth=0
    )

    if (( APT_CACHE_READY == 1 )); then
        return 0
    fi

    if DEBIAN_FRONTEND=noninteractive apt-get "${apt_opts[@]}" update; then
        APT_CACHE_READY=1
        return 0
    fi

    if repair_ubuntu_apt_mirrors; then
        echo -e "${C_YELLOW}⚠️ APT mirror timed out. Switching Ubuntu sources to archive.ubuntu.com and retrying...${C_RESET}"
        apt-get clean >/dev/null 2>&1 || true
        if DEBIAN_FRONTEND=noninteractive apt-get "${apt_opts[@]}" update; then
            APT_CACHE_READY=1
            return 0
        fi
    fi

    if switch_ubuntu_to_old_releases; then
        echo -e "${C_YELLOW}⚠️ Detected an end-of-life Ubuntu release. Switching APT sources to old-releases.ubuntu.com and retrying...${C_RESET}"
        apt-get clean >/dev/null 2>&1 || true
        if DEBIAN_FRONTEND=noninteractive apt-get "${apt_opts[@]}" update; then
            APT_CACHE_READY=1
            return 0
        fi
    fi

    echo -e "${C_RED}❌ Failed to refresh package lists. Please check VPS network, DNS, or blocked Ubuntu mirrors.${C_RESET}"
    return 1
}

ff_apt_install() {
    local -a packages=("$@")
    (( ${#packages[@]} > 0 )) || return 0

    ff_apt_update || return 1
    DEBIAN_FRONTEND=noninteractive apt-get -y -o Dpkg::Use-Pty=0 install "${packages[@]}"
}

ff_apt_purge() {
    local -a packages=("$@")
    (( ${#packages[@]} > 0 )) || return 0
    DEBIAN_FRONTEND=noninteractive apt-get -y -o Dpkg::Use-Pty=0 purge "${packages[@]}"
}

ff_pkg_install() {
    local -a packages=("$@")
    (( ${#packages[@]} > 0 )) || return 0
    local -a mapped=()
    mapfile -t mapped < <(_map_pkg_names "${packages[@]}")
    case "$FF_PKG_MGR" in
        apt) ff_apt_install "${mapped[@]}" ;;
        dnf) dnf install -y -q "${mapped[@]}" ;;
        yum) yum install -y -q "${mapped[@]}" ;;
        zypper) zypper install -y -q "${mapped[@]}" ;;
        pacman) pacman -S --noconfirm --needed "${mapped[@]}" ;;
        *) echo -e "${C_RED}❌ Unsupported package manager.${C_RESET}"; return 1 ;;
    esac
}

ff_pkg_purge() {
    local -a packages=("$@")
    (( ${#packages[@]} > 0 )) || return 0
    local -a mapped=()
    mapfile -t mapped < <(_map_pkg_names "${packages[@]}")
    case "$FF_PKG_MGR" in
        apt) ff_apt_purge "${mapped[@]}" ;;
        dnf) dnf remove -y -q "${mapped[@]}" ;;
        yum) yum remove -y -q "${mapped[@]}" ;;
        zypper) zypper remove -y "${mapped[@]}" ;;
        pacman) pacman -Rns --noconfirm "${mapped[@]}" 2>/dev/null ;;
        *) echo -e "${C_RED}❌ Unsupported package manager.${C_RESET}"; return 1 ;;
    esac
}

ff_pkg_autoremove() {
    case "$FF_PKG_MGR" in
        apt) apt-get autoremove -y >/dev/null 2>&1 ;;
        dnf) dnf autoremove -y -q >/dev/null 2>&1 ;;
        yum) yum autoremove -y -q >/dev/null 2>&1 ;;
        zypper) zypper packages --unneeded 2>/dev/null | awk -F'|' 'NR>3{print $3}' | xargs -r zypper remove -y >/dev/null 2>&1 ;;
        pacman) pacman -Qdtq 2>/dev/null | xargs -r pacman -Rns --noconfirm >/dev/null 2>&1 ;;
    esac
    return 0
}

ff_pkg_is_installed() {
    local pkg="$1"
    case "$FF_PKG_MGR" in
        apt) dpkg -s "$pkg" &>/dev/null ;;
        dnf|yum) rpm -q "$pkg" &>/dev/null ;;
        zypper) rpm -q "$pkg" &>/dev/null ;;
        pacman) pacman -Q "$pkg" &>/dev/null ;;
    esac
}

# Mandatory Dependency Check (Added jq and curl)
check_environment() {
    local missing_packages=()
    local cmd

    for cmd in bc jq curl wget; do
        if ! command -v "$cmd" &> /dev/null; then
            missing_packages+=("$cmd")
        fi
    done

    if (( ${#missing_packages[@]} > 0 )); then
        echo -e "${C_YELLOW}⚠️ Installing missing dependencies: ${missing_packages[*]}${C_RESET}"
        ff_pkg_install "${missing_packages[@]}" >/dev/null 2>&1 || {
            echo -e "${C_RED}❌ Error: Failed to install required dependencies: ${missing_packages[*]}.${C_RESET}"
            exit 1
        }
    fi
}

ensure_firewallfalcon_dirs() {
    mkdir -p "$DB_DIR" "$SSL_CERT_DIR" "$BANDWIDTH_DIR" /etc/ssh/sshd_config.d
    touch "$DB_FILE"
}

ensure_firewallfalcon_system_group() {
    getent group "$FF_USERS_GROUP" >/dev/null 2>&1 || groupadd "$FF_USERS_GROUP" >/dev/null 2>&1 || true
}

# Finds the first unused id in [UID_MIN, UID_MAX] (per /etc/login.defs,
# 1000-60000 by default) that is free in BOTH /etc/passwd and /etc/group,
# so it is safe to use as a matching uid:gid pair. Reads both files once
# instead of shelling out to `getent` per candidate, since HWID-length
# device IDs can require scanning past thousands of existing accounts.
_fm_next_free_id() {
    local lo hi
    lo=$(awk '/^UID_MIN[ \t]/{print $2}' /etc/login.defs 2>/dev/null); lo=${lo:-1000}
    hi=$(awk '/^UID_MAX[ \t]/{print $2}' /etc/login.defs 2>/dev/null); hi=${hi:-60000}
    awk -F: -v lo="$lo" -v hi="$hi" '
        { if ($3 >= lo && $3 <= hi) used[$3] = 1 }
        END { for (i = lo; i <= hi; i++) if (!(i in used)) { print i; exit } }
    ' /etc/passwd /etc/group
}

# Creates a Linux system account for $1 (nologin shell, home dir under
# /home), transparently handling names longer than 32 characters — HWID
# login (see create_user()) routinely produces device IDs well past that.
# useradd/groupadd both hard-reject any name over 32 chars; --badname only
# relaxes the character-set check, not the length cap baked into
# shadow-utils' is_valid_name(). The OS itself has no such limit (glibc's
# LOGIN_NAME_MAX is 256, and a live SSH login with a 64-char user+pass was
# verified end-to-end), so on a length-only rejection this falls back to
# appending the passwd/group lines by hand and letting pwconv/grpconv fill
# in the matching shadow/gshadow entries instead of writing them itself —
# they reconcile the whole file rather than one hand-written line, which
# costs more as the account count grows (measured ~0.6s at 5,000 existing
# accounts) but is the deliberate choice here: this project caps at ~500
# users, where that cost is imperceptible, in exchange for the guarantee
# that shadow/gshadow are fully consistent with passwd/group.
# Returns 0 on success (including "already exists"), 1 on a real failure —
# callers must check this instead of assuming useradd always worked.
_fm_create_system_user() {
    local uname="$1" err
    err=$(useradd -m -s /usr/sbin/nologin "$uname" 2>&1)
    if [[ $? -eq 0 ]]; then
        return 0
    fi
    if [[ "$err" != *"invalid user name"* ]]; then
        echo -e "${C_RED}❌ System error creating '$uname': $err${C_RESET}" >&2
        return 1
    fi
    if getent passwd "$uname" &>/dev/null; then
        return 0
    fi
    local id; id=$(_fm_next_free_id)
    if [[ -z "$id" ]]; then
        echo -e "${C_RED}❌ No free UID available for '$uname'.${C_RESET}" >&2
        return 1
    fi
    echo "${uname}:x:${id}:${id}::/home/${uname}:/usr/sbin/nologin" >> /etc/passwd
    echo "${uname}:x:${id}:" >> /etc/group
    pwconv &>/dev/null; grpconv &>/dev/null
    mkdir -p "/home/${uname}"
    chown "${id}:${id}" "/home/${uname}" 2>/dev/null
    chmod 700 "/home/${uname}" 2>/dev/null
    return 0
}

# Sanitizes a raw device-ID (HWID) string for safe use as a Linux username
# AND as a users.db field: trims outer whitespace, then rejects (rather
# than silently mangling) anything containing ':', '/', or embedded
# whitespace — those would corrupt the colon-delimited db line or are
# simply invalid in a username — and anything empty or over 128 chars.
# Prints the sanitized value on success; prints nothing and returns 1 on
# any violation, so callers can re-prompt.
_fm_validate_hwid() {
    local v
    v=$(echo "$1" | xargs 2>/dev/null)
    [[ -z "$v" ]] && return 1
    [[ "$v" =~ [[:space:]] ]] && return 1
    [[ "$v" == *:* || "$v" == */* ]] && return 1
    (( ${#v} > 128 )) && return 1
    printf '%s' "$v"
}

# Sidecar file tracking which SSH accounts log in via a single HWID value
# (username == password) instead of separate credentials. Deliberately a
# flat "username:mode" file — same style as users.db — rather than adding
# a column to users.db itself, so the existing db format, every reader of
# it (panel.py included), and backup/restore are completely unaffected.
# Lives under DB_DIR so it rides along with the existing backup archive
# automatically. Absence of an entry means "normal" (default, no migration
# needed for accounts created before this feature existed).
LOGIN_MODES_FILE="$DB_DIR/login_modes.db"

_fm_set_login_mode() {
    local u="$1" m="$2"
    touch "$LOGIN_MODES_FILE"
    sed -i "/^${u}:/d" "$LOGIN_MODES_FILE"
    [[ "$m" != "normal" && -n "$m" ]] && echo "${u}:${m}" >> "$LOGIN_MODES_FILE"
}

_fm_get_login_mode() {
    [[ -f "$LOGIN_MODES_FILE" ]] || { echo "normal"; return; }
    local m; m=$(grep "^${1}:" "$LOGIN_MODES_FILE" | tail -1 | cut -d: -f2)
    echo "${m:-normal}"
}

_fm_clear_login_mode() {
    [[ -f "$LOGIN_MODES_FILE" ]] && sed -i "/^${1}:/d" "$LOGIN_MODES_FILE"
}

# Renames a Linux system account from $1 to $2 — username, matching
# private group, shadow/gshadow entries, and home directory — used when a
# device's HWID changes (see edit_user()'s "Change Device ID" option) and
# the account underneath needs the same treatment. usermod -l has the same
# 32-char name-length limit as useradd (verified), so on that specific
# rejection this falls back to renaming the fields by hand in all four
# files instead of failing the whole operation.
# Returns 0 on success, 1 on failure (new name already taken, or a real
# usermod error unrelated to length).
_fm_rename_system_user() {
    local old="$1" new="$2" err
    if getent passwd "$new" &>/dev/null; then
        echo -e "${C_RED}❌ '$new' is already a system account.${C_RESET}" >&2
        return 1
    fi
    err=$(usermod -l "$new" "$old" 2>&1)
    if [[ $? -eq 0 ]]; then
        usermod -m -d "/home/$new" "$new" &>/dev/null
        getent group "$old" &>/dev/null && groupmod -n "$new" "$old" &>/dev/null
        return 0
    fi
    if [[ "$err" != *"invalid user name"* ]]; then
        echo -e "${C_RED}❌ System error renaming '$old': $err${C_RESET}" >&2
        return 1
    fi
    sed -i "s|^${old}:|${new}:|" /etc/passwd /etc/shadow
    if getent group "${old}" &>/dev/null; then
        sed -i "s|^${old}:|${new}:|" /etc/group /etc/gshadow
    fi
    if [[ -d "/home/${old}" && ! -e "/home/${new}" ]]; then
        mv "/home/${old}" "/home/${new}"
        sed -i "s|:/home/${old}:|:/home/${new}:|" /etc/passwd
    fi
    return 0
}

# Full HWID-account rename: the system account plus every sidecar store
# keyed by username (users.db row, login mode, admin notes, bandwidth
# usage/lock state, per-user speed cap, and the usage-link token). Used
# when a client's device ID changes (OS/app update) and the admin needs
# to update it while keeping everything else about the account — data
# used, expiry, notes — exactly as it was. The public usage-status link
# can't survive as the same URL (it embeds the username in its path), so
# the token row is carried over but the admin should re-share a fresh
# link afterward. Returns 0 on success, 1 on failure (nothing is changed
# on failure — the rename is attempted first, before any sidecar store).
_fm_rename_hwid_account() {
    local old="$1" new="$2"
    _fm_rename_system_user "$old" "$new" || return 1
    echo "${new}:${new}" | chpasswd

    [[ -f "$DB_FILE" ]] && sed -i "s|^${old}:[^:]*:|${new}:${new}:|" "$DB_FILE"
    _fm_set_login_mode "$new" "hwid"
    _fm_clear_login_mode "$old"

    for suffix in usage daily_usage conn_locked daily_locked; do
        [[ -f "$BANDWIDTH_DIR/${old}.${suffix}" ]] && mv "$BANDWIDTH_DIR/${old}.${suffix}" "$BANDWIDTH_DIR/${new}.${suffix}"
    done
    [[ -d "$BANDWIDTH_DIR/pidtrack/${old}" ]] && mv "$BANDWIDTH_DIR/pidtrack/${old}" "$BANDWIDTH_DIR/pidtrack/${new}"

    if [[ -f "$USER_SPEED_CONF" ]] && grep -q "^${old}:" "$USER_SPEED_CONF" 2>/dev/null; then
        local speed; speed=$(grep "^${old}:" "$USER_SPEED_CONF" | tail -1 | cut -d: -f2)
        sed -i "/^${old}:/d" "$USER_SPEED_CONF"
        echo "${new}:${speed}" >> "$USER_SPEED_CONF"
    fi

    if [[ -f "$BW_LINK_TOKENS_DB" ]] && grep -q "^${old}:" "$BW_LINK_TOKENS_DB" 2>/dev/null; then
        local link_rest; link_rest=$(grep "^${old}:" "$BW_LINK_TOKENS_DB" | tail -1 | cut -d: -f2-)
        sed -i "/^${old}:/d" "$BW_LINK_TOKENS_DB"
        echo "${new}:${link_rest}" >> "$BW_LINK_TOKENS_DB"
    fi

    # user_notes.json is a JSON map the web panel manages — menu.sh has no
    # JSON tooling of its own, so shell out to python3 (already a hard
    # dependency of this project's panel) rather than hand-parse it.
    local notes_file="/etc/firewallfalcon/user_notes.json"
    if [[ -f "$notes_file" ]] && command -v python3 &>/dev/null; then
        python3 - "$notes_file" "$old" "$new" <<'PYEOF' 2>/dev/null
import json, sys
path, old, new = sys.argv[1], sys.argv[2], sys.argv[3]
try:
    with open(path, encoding="utf-8") as f:
        notes = json.load(f)
except Exception:
    sys.exit(0)
if old in notes:
    notes[new] = notes.pop(old)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(notes, f)
PYEOF
    fi

    return 0
}

# Replacing a row in one of the small line-oriented stores used to be two
# steps — delete the old line, then append the new one — with a real
# window between them where the row simply does not exist. Anything that
# stops the shell in between, or an append that fails on a full disk,
# leaves it gone for good: a wallet balance, an NPV device mapping, or
# the record of which node an account lives on. One temp file swapped in
# with mv makes it a single step, so the store holds either the old row
# or the new one and never neither. Matching is on an exact field value,
# not a regex, so a key carrying a regex metacharacter cannot take
# unrelated rows with it either.
_fm_db_replace_row() {
    local file="$1" delim="$2" field="$3" key="$4" new_line="$5"
    [[ -n "$file" && -n "$field" ]] || return 1
    mkdir -p "$(dirname "$file")" 2>/dev/null
    touch "$file" 2>/dev/null || return 1
    local tmp; tmp=$(mktemp "${file}.XXXXXX" 2>/dev/null) || return 1
    if [[ -s "$file" ]]; then
        awk -F"$delim" -v f="$field" -v k="$key" '$f != k' "$file" > "$tmp" 2>/dev/null
    fi
    [[ -n "$new_line" ]] && printf '%s\n' "$new_line" >> "$tmp"
    chmod --reference="$file" "$tmp" 2>/dev/null
    if ! mv -f "$tmp" "$file" 2>/dev/null; then
        rm -f "$tmp" 2>/dev/null
        return 1
    fi
    return 0
}

# Every store on this box keyed by an account's NAME, in one place.
# Changing a customer's device means the account has to come back under a
# new name, and anything not carried across is lost silently — the
# consumed-GB counter most painfully, since losing it hands the customer
# a fresh quota mid-subscription. Snapshot first, restore after, so the
# list can only ever be extended in one spot.
_fm_account_snapshot() {
    local acct="$1" dir="$2" sfx
    [[ -n "$acct" && -n "$dir" ]] || return 1
    mkdir -p "$dir" 2>/dev/null || return 1

    [[ -f "$DB_FILE" ]] && awk -F: -v u="$acct" '$1==u{print; exit}' "$DB_FILE" > "$dir/row" 2>/dev/null
    for sfx in usage daily_usage conn_locked daily_locked; do
        [[ -f "$BANDWIDTH_DIR/${acct}.${sfx}" ]] && cp -p "$BANDWIDTH_DIR/${acct}.${sfx}" "$dir/bw.${sfx}" 2>/dev/null
    done
    [[ -d "$BANDWIDTH_DIR/pidtrack/${acct}" ]] && cp -a "$BANDWIDTH_DIR/pidtrack/${acct}" "$dir/pidtrack" 2>/dev/null
    [[ -f "$LOGIN_MODES_FILE" ]] && grep "^${acct}:" "$LOGIN_MODES_FILE" 2>/dev/null | tail -1 | cut -d: -f2 > "$dir/loginmode"
    [[ -f "$USER_SPEED_CONF" ]] && grep "^${acct}:" "$USER_SPEED_CONF" 2>/dev/null | tail -1 | cut -d: -f2- > "$dir/speed"
    [[ -f "$BW_LINK_TOKENS_DB" ]] && grep "^${acct}:" "$BW_LINK_TOKENS_DB" 2>/dev/null | tail -1 | cut -d: -f2- > "$dir/bwtoken"

    local ddb="${BOT_DELIVERY_DB:-/etc/firewallfalcon/bot_delivery.db}"
    [[ -f "$ddb" ]] && awk -F'\t' -v a="$acct" '$1==a{print; exit}' "$ddb" 2>/dev/null > "$dir/delivery"

    local notes_file="/etc/firewallfalcon/user_notes.json"
    if [[ -f "$notes_file" ]] && command -v python3 &>/dev/null; then
        python3 - "$notes_file" "$acct" <<'PYNOTES' > "$dir/note" 2>/dev/null
import json, sys
try:
    with open(sys.argv[1], encoding="utf-8") as f:
        notes = json.load(f)
except Exception:
    raise SystemExit
v = notes.get(sys.argv[2])
if v:
    sys.stdout.write(json.dumps(v))
PYNOTES
    fi
    return 0
}

# Puts a snapshot back under (possibly) a different name. The device
# recorded alongside a delivered file follows the new name too, so the
# customer's "resend my file" button rebuilds for the device they are
# actually on now.
_fm_account_restore() {
    local dir="$1" acct="$2" sfx
    [[ -d "$dir" && -n "$acct" ]] || return 1

    if [[ -s "$dir/row" ]]; then
        local rest; rest=$(cut -d: -f3- < "$dir/row")
        [[ -f "$DB_FILE" ]] && sed -i "/^${acct}:/d" "$DB_FILE" 2>/dev/null
        mkdir -p "$(dirname "$DB_FILE")" 2>/dev/null
        echo "${acct}:${acct}:${rest}" >> "$DB_FILE"
    fi

    mkdir -p "$BANDWIDTH_DIR" 2>/dev/null
    for sfx in usage daily_usage conn_locked daily_locked; do
        [[ -f "$dir/bw.${sfx}" ]] && cp -p "$dir/bw.${sfx}" "$BANDWIDTH_DIR/${acct}.${sfx}" 2>/dev/null
    done
    if [[ -d "$dir/pidtrack" ]]; then
        mkdir -p "$BANDWIDTH_DIR/pidtrack" 2>/dev/null
        rm -rf "$BANDWIDTH_DIR/pidtrack/${acct}" 2>/dev/null
        cp -a "$dir/pidtrack" "$BANDWIDTH_DIR/pidtrack/${acct}" 2>/dev/null
    fi

    [[ -s "$dir/loginmode" ]] && _fm_set_login_mode "$acct" "$(cat "$dir/loginmode")"

    if [[ -s "$dir/speed" ]]; then
        [[ -f "$USER_SPEED_CONF" ]] && sed -i "/^${acct}:/d" "$USER_SPEED_CONF" 2>/dev/null
        echo "${acct}:$(cat "$dir/speed")" >> "$USER_SPEED_CONF"
    fi
    if [[ -s "$dir/bwtoken" ]]; then
        [[ -f "$BW_LINK_TOKENS_DB" ]] && sed -i "/^${acct}:/d" "$BW_LINK_TOKENS_DB" 2>/dev/null
        echo "${acct}:$(cat "$dir/bwtoken")" >> "$BW_LINK_TOKENS_DB"
    fi

    if [[ -s "$dir/delivery" ]]; then
        local dapp dtype
        dapp=$(cut -d$'\t' -f2 < "$dir/delivery")
        dtype=$(cut -d$'\t' -f3 < "$dir/delivery")
        _fm_bot_delivery_set "$acct" "$dapp" "$dtype" "$acct"
    fi

    local notes_file="/etc/firewallfalcon/user_notes.json"
    if [[ -s "$dir/note" ]] && command -v python3 &>/dev/null; then
        python3 - "$notes_file" "$acct" "$(cat "$dir/note")" <<'PYNOTES' 2>/dev/null
import json, sys
path, acct, raw = sys.argv[1], sys.argv[2], sys.argv[3]
try:
    with open(path, encoding="utf-8") as f:
        notes = json.load(f)
except Exception:
    notes = {}
try:
    notes[acct] = json.loads(raw)
except Exception:
    raise SystemExit
with open(path, "w", encoding="utf-8") as f:
    json.dump(notes, f)
PYNOTES
    fi
    return 0
}

db_has_user() {
    [[ -f "$DB_FILE" ]] || return 1
    awk -F: -v target="$1" '$1 == target { found=1; exit } END { exit(found ? 0 : 1) }' "$DB_FILE"
}

is_firewallfalcon_orphan_user() {
    local username="$1"
    local passwd_line system_user _ uid _ home shell

    passwd_line=$(getent passwd "$username" 2>/dev/null) || return 1
    IFS=: read -r system_user _ uid _ _ home shell <<< "$passwd_line"
    [[ "$uid" =~ ^[0-9]+$ ]] || return 1
    db_has_user "$username" && return 1

    if id -nG "$username" 2>/dev/null | tr ' ' '\n' | grep -Fxq "$FF_USERS_GROUP"; then
        return 0
    fi

    (( uid >= 1000 )) || return 1
    [[ "$home" == "/home/$username" || "$home" == /home/* ]] || return 1

    case "$shell" in
        /usr/sbin/nologin|/usr/bin/false|/bin/false) return 0 ;;
    esac

    return 1
}

get_firewallfalcon_orphan_users() {
    local username
    while IFS=: read -r username _rest; do
        [[ -n "$username" ]] || continue
        if is_firewallfalcon_orphan_user "$username"; then
            echo "$username"
        fi
    done < /etc/passwd
}

get_firewallfalcon_known_users() {
    local username
    local -A seen_users=()

    if [[ -f "$DB_FILE" ]]; then
        while IFS=: read -r username _rest; do
            [[ -n "$username" && "$username" != \#* ]] || continue
            seen_users["$username"]=1
        done < "$DB_FILE"
    fi

    while IFS= read -r username; do
        [[ -n "$username" ]] && seen_users["$username"]=1
    done < <(get_firewallfalcon_orphan_users)

    (( ${#seen_users[@]} > 0 )) || return 0
    printf "%s\n" "${!seen_users[@]}" | sort
}

# Kill every currently-running session/process owned by a user, using
# several methods together instead of relying on killall -u alone (which
# has been unreliable at actually dropping an already-open session on some
# setups, silently leaving it connected even though the account is locked).
# pkill -u is a more dependable primary method; the /proc/*/loginuid sweep
# is a last-resort fallback that kills by kernel login UID directly,
# bypassing process-name matching entirely.
_fm_kill_user_sessions() {
    local username="$1" uid lp lu
    [[ -n "$username" ]] || return 0
    pkill -9 -u "$username" &>/dev/null
    killall -u "$username" -9 &>/dev/null
    uid=$(id -u "$username" 2>/dev/null)
    if [[ "$uid" =~ ^[0-9]+$ ]]; then
        for lp in /proc/[0-9]*/loginuid; do
            [[ -f "$lp" ]] || continue
            lu=""
            read -r lu < "$lp" 2>/dev/null || lu=""
            [[ "$lu" == "$uid" ]] || continue
            kill -9 "$(basename "$(dirname "$lp")")" &>/dev/null
        done
    fi
}

# Disables a system account WITHOUT ever attempting to remove it. userdel
# can fail for reasons entirely outside this project's control (a home
# directory still busy/mounted, a session some distros still refuse to
# force through, mail-spool quirks) — and when it does, the code used to
# carry on as if the account were gone: its DB row and bandwidth counters
# were wiped while the real system account kept working untouched, right
# as a brand-new account was created under a different name. The result,
# reported live: the old account never disappears and a second one
# starts existing alongside it.
#
# Locking the password and forcing an already-past expiry are both plain
# attribute writes to /etc/shadow — neither can fail because the account
# happens to be busy, and PAM (pam_unix) rejects both independently, so
# one surviving a quirky config doesn't leave the account reachable. Kept
# distinct from delete_firewallfalcon_user_accounts on purpose: that one
# is for an admin or a cleanup sweep permanently retiring an account
# on its own, not for a live rebuild that must not be able to half-fail.
_fm_disable_system_user() {
    local username="$1"
    [[ -n "$username" ]] || return 1
    id "$username" &>/dev/null || return 0
    usermod -L "$username" &>/dev/null
    chage -E 1 "$username" &>/dev/null
    _fm_kill_user_sessions "$username"
    return 0
}

delete_firewallfalcon_user_accounts() {
    local -a users_to_delete=("$@")
    local username

    [[ ${#users_to_delete[@]} -gt 0 ]] || return 0

    for username in "${users_to_delete[@]}"; do
        [[ -n "$username" ]] || continue
        killall -u "$username" -9 &>/dev/null
        pkill -9 -u "$username" &>/dev/null
        sleep 0.5
        if id "$username" &>/dev/null; then
            if userdel -rf "$username" &>/dev/null; then
                echo -e " ✅ System user '${C_YELLOW}$username${C_RESET}' deleted."
            else
                # Retry after harder kill
                pkill -9 -u "$username" &>/dev/null
                sleep 1
                if userdel -rf "$username" &>/dev/null; then
                    echo -e " ✅ System user '${C_YELLOW}$username${C_RESET}' deleted (retry)."
                else
                    echo -e " ❌ Failed to delete system user '${C_YELLOW}$username${C_RESET}'."
                fi
            fi
        else
            echo -e " ℹ️ System user '${C_YELLOW}$username${C_RESET}' was already missing. Removing manager data only."
        fi
        rm -f "$BANDWIDTH_DIR/${username}.usage"
        rm -f "$BANDWIDTH_DIR/${username}.daily_usage"
        rm -f "$BANDWIDTH_DIR/${username}.conn_locked"
        rm -f "$BANDWIDTH_DIR/${username}.daily_locked"
        rm -rf "$BANDWIDTH_DIR/pidtrack/${username}"
        _fm_clear_login_mode "$username"
    done

    if [[ -f "$DB_FILE" ]]; then
        local db_tmp
        db_tmp=$(mktemp)
        awk -F: 'NR==FNR { drop[$1]=1; next } !($1 in drop)' <(printf "%s\n" "${users_to_delete[@]}") "$DB_FILE" > "$db_tmp" && mv "$db_tmp" "$DB_FILE"
        rm -f "$db_tmp" 2>/dev/null
    fi

    invalidate_banner_cache
    refresh_dynamic_banner_routing_if_enabled
}

require_interactive_terminal() {
    if [[ ! -t 0 || ! -t 1 ]]; then
        echo -e "${C_RED}❌ Error: The DAHOOM menu must be run from an interactive terminal.${C_RESET}"
        exit 1
    fi
}

initial_setup() {
    echo -e "${C_BLUE}⚙️ Initializing DAHOOM setup...${C_RESET}"
    check_environment
    
    ensure_firewallfalcon_dirs
    ensure_firewallfalcon_system_group
    
    echo -e "${C_BLUE}🔹 Configuring user limiter service...${C_RESET}"
    setup_limiter_service
    
    echo -e "${C_BLUE}🔹 Configuring bandwidth monitoring service...${C_RESET}"
    setup_bandwidth_service
    
    echo -e "${C_BLUE}🔹 Installing trial account cleanup script...${C_RESET}"
    setup_trial_cleanup_script
    
    echo -e "${C_BLUE}🔹 Configuring health guard service...${C_RESET}"
    setup_health_service
    
    echo -e "${C_BLUE}🔹 Deploying dynamic DAHOOM server login banner (MOTD)...${C_RESET}"
    setup_falcon_server_motd

    echo -e "${C_BLUE}🔹 Applying system optimization (BBR, swap, log rotation, fail2ban)...${C_RESET}"
    _fm_system_optimization_silent

    echo -e "${C_BLUE}🔹 Linking 'dahoom' command shortcut...${C_RESET}"
    ln -sf "/usr/local/bin/dahoom" "/usr/bin/dahoom" 2>/dev/null || true
    # Retire the old 'fm' / 'menu' command names entirely (not just this
    # install's own launcher — any legacy copy left over from before this
    # rename too), so only 'dahoom' works from here on.
    rm -f "/usr/local/bin/menu" "/usr/local/bin/fm" "/usr/bin/menu" "/usr/bin/fm" 2>/dev/null || true
    
    echo -e "${C_BLUE}🔹 Cleaning legacy dynamic SSH banner hooks...${C_RESET}"
    disable_dynamic_ssh_banner_system
    systemctl reload sshd 2>/dev/null || systemctl reload ssh 2>/dev/null || true
    
    if [ ! -f "$INSTALL_FLAG_FILE" ]; then
        touch "$INSTALL_FLAG_FILE"
    fi
    echo -e "${C_GREEN}✅ Setup finished.${C_RESET}"
}

_is_valid_ipv4() {
    local ip=$1
    if [[ $ip =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$ ]]; then
        return 0
    else
        return 1
    fi
}

check_and_open_firewall_port() {
    local port="$1"
    local protocol="${2:-tcp}"
    local firewall_detected=false

    if command -v ufw &> /dev/null && ufw status | grep -q "Status: active"; then
        firewall_detected=true
        if ! ufw status | grep -qw "$port/$protocol"; then
            echo -e "${C_YELLOW}🔥 UFW firewall is active and port ${port}/${protocol} is closed.${C_RESET}"
            read -p "👉 Do you want to open this port now? (y/n): " confirm
            if [[ "$confirm" == "y" || "$confirm" == "Y" ]]; then
                ufw allow "$port/$protocol"
                echo -e "${C_GREEN}✅ Port ${port}/${protocol} has been opened in UFW.${C_RESET}"
            else
                echo -e "${C_RED}❌ Warning: Port ${port}/${protocol} was not opened. The service may not work correctly.${C_RESET}"
                return 1
            fi
        else
             echo -e "${C_GREEN}✅ Port ${port}/${protocol} is already open in UFW.${C_RESET}"
        fi
    fi

    if command -v firewall-cmd &> /dev/null && systemctl is-active --quiet firewalld; then
        firewall_detected=true
        if ! firewall-cmd --list-ports --permanent | grep -qw "$port/$protocol"; then
            echo -e "${C_YELLOW}🔥 firewalld is active and port ${port}/${protocol} is not open.${C_RESET}"
            read -p "👉 Do you want to open this port now? (y/n): " confirm
            if [[ "$confirm" == "y" || "$confirm" == "Y" ]]; then
                firewall-cmd --add-port="$port/$protocol" --permanent
                firewall-cmd --reload
                echo -e "${C_GREEN}✅ Port ${port}/${protocol} has been opened in firewalld.${C_RESET}"
            else
                echo -e "${C_RED}❌ Warning: Port ${port}/${protocol} was not opened. The service may not work correctly.${C_RESET}"
                return 1
            fi
        else
            echo -e "${C_GREEN}✅ Port ${port}/${protocol} is already open in firewalld.${C_RESET}"
        fi
    fi

    if ! $firewall_detected; then
        echo -e "${C_BLUE}ℹ️ No active firewall (UFW or firewalld) detected. Assuming ports are open.${C_RESET}"
    fi
    return 0
}

check_and_open_firewall_port_range() {
    local port_range="$1"
    local protocol="${2:-tcp}"
    local firewall_detected=false

    if command -v ufw &> /dev/null && ufw status | grep -q "Status: active"; then
        firewall_detected=true
        if ! ufw status | grep -Fq "$port_range/$protocol"; then
            echo -e "${C_YELLOW}🔥 UFW firewall is active and range ${port_range}/${protocol} is closed.${C_RESET}"
            read -p "👉 Do you want to open this port range now? (y/n): " confirm
            if [[ "$confirm" == "y" || "$confirm" == "Y" ]]; then
                ufw allow "$port_range/$protocol"
                echo -e "${C_GREEN}✅ Range ${port_range}/${protocol} has been opened in UFW.${C_RESET}"
            else
                echo -e "${C_RED}❌ Warning: Range ${port_range}/${protocol} was not opened. The service may not work correctly.${C_RESET}"
                return 1
            fi
        else
            echo -e "${C_GREEN}✅ Range ${port_range}/${protocol} is already open in UFW.${C_RESET}"
        fi
    fi

    if command -v firewall-cmd &> /dev/null && systemctl is-active --quiet firewalld; then
        firewall_detected=true
        if ! firewall-cmd --quiet --query-port="$port_range/$protocol"; then
            echo -e "${C_YELLOW}🔥 firewalld is active and range ${port_range}/${protocol} is not open.${C_RESET}"
            read -p "👉 Do you want to open this port range now? (y/n): " confirm
            if [[ "$confirm" == "y" || "$confirm" == "Y" ]]; then
                firewall-cmd --add-port="$port_range/$protocol" --permanent
                firewall-cmd --reload
                echo -e "${C_GREEN}✅ Range ${port_range}/${protocol} has been opened in firewalld.${C_RESET}"
            else
                echo -e "${C_RED}❌ Warning: Range ${port_range}/${protocol} was not opened. The service may not work correctly.${C_RESET}"
                return 1
            fi
        else
            echo -e "${C_GREEN}✅ Range ${port_range}/${protocol} is already open in firewalld.${C_RESET}"
        fi
    fi

    if ! $firewall_detected; then
        echo -e "${C_BLUE}ℹ️ No active firewall (UFW or firewalld) detected. Assuming range ${port_range}/${protocol} is open.${C_RESET}"
    fi
    return 0
}

check_and_free_ports() {
    local ports_to_check=("$@")
    for port in "${ports_to_check[@]}"; do
        echo -e "\n${C_BLUE}🔎 Checking if port $port is available...${C_RESET}"
        local conflicting_process_info
        conflicting_process_info=$(
            ss -H -lntp "( sport = :$port )" 2>/dev/null
            ss -H -lunp "( sport = :$port )" 2>/dev/null
        )
        
        if [[ -n "$conflicting_process_info" ]]; then
            local conflicting_pid
            conflicting_pid=$(echo "$conflicting_process_info" | grep -oP 'pid=\K[0-9]+' | head -n 1)
            local conflicting_name
            conflicting_name=$(echo "$conflicting_process_info" | grep -oP 'users:\(\("(\K[^"]+)' | head -n 1)
            
            echo -e "${C_YELLOW}⚠️ Warning: Port $port is in use by process '${conflicting_name:-unknown}' (PID: ${conflicting_pid:-N/A}).${C_RESET}"
            read -p "👉 Do you want to attempt to stop this process? (y/n): " kill_confirm
            if [[ "$kill_confirm" == "y" || "$kill_confirm" == "Y" ]]; then
                if [[ -z "$conflicting_pid" ]]; then
                    echo -e "${C_RED}❌ Could not determine which PID owns port $port. Please free it manually.${C_RESET}"
                    return 1
                fi
                echo -e "${C_GREEN}🛑 Stopping process PID $conflicting_pid...${C_RESET}"
                systemctl stop "$(ps -p "$conflicting_pid" -o comm=)" &>/dev/null || kill -9 "$conflicting_pid"
                sleep 2
                
                if ss -H -lntp "( sport = :$port )" 2>/dev/null | grep -q . || ss -H -lunp "( sport = :$port )" 2>/dev/null | grep -q .; then
                     echo -e "${C_RED}❌ Failed to free port $port. Please handle it manually. Aborting.${C_RESET}"
                     return 1
                else
                     echo -e "${C_GREEN}✅ Port $port has been successfully freed.${C_RESET}"
                fi
            else
                echo -e "${C_RED}❌ Cannot proceed without freeing port $port. Aborting.${C_RESET}"
                return 1
            fi
        else
            echo -e "${C_GREEN}✅ Port $port is free to use.${C_RESET}"
        fi
    done
    return 0
}

# HAProxy Edge restarts the shared system Nginx. A plain `systemctl
# restart nginx` can lose a race on a live box: if the previous worker
# still has active connections when told
# to stop, its socket can still be bound for a moment after systemd reports
# the unit "stopped" — the new instance's bind() then fails with "Address
# already in use" for a few seconds (nginx retries a handful of times, then
# gives up). Wait for the actual process to be gone, not just the unit
# state, before starting a fresh one — and force it if it overruns.
_fm_safe_restart_nginx() {
    systemctl stop nginx 2>/dev/null
    local waited=0
    while (( waited < 10 )) && pgrep -x nginx >/dev/null 2>&1; do
        sleep 1
        ((waited++))
    done
    if pgrep -x nginx >/dev/null 2>&1; then
        pkill -9 -x nginx 2>/dev/null
        sleep 1
    fi
    systemctl start nginx
}

setup_limiter_service() {
    # Combined limiter + bandwidth monitoring
    cat > "$LIMITER_SCRIPT" << 'EOF'
#!/bin/bash
# DAHOOM limiter version 2026-07-23.10
DB_FILE="/etc/firewallfalcon/users.db"
BW_DIR="/etc/firewallfalcon/bandwidth"
PID_DIR="$BW_DIR/pidtrack"
BANNER_DIR="/etc/firewallfalcon/banners"
SCAN_INTERVAL=10
CONN_LOCK_DURATION=60

mkdir -p "$BW_DIR" "$PID_DIR"
shopt -s nullglob

write_banner_if_changed() {
    local user="$1"
    local content="$2"
    local banner_file="$BANNER_DIR/${user}.txt"
    local tmp_file="${banner_file}.tmp"

    printf "%s" "$content" > "$tmp_file"
    if ! cmp -s "$tmp_file" "$banner_file" 2>/dev/null; then
        mv "$tmp_file" "$banner_file"
    else
        rm -f "$tmp_file"
    fi
}

# Excess sessions are killed immediately every scan cycle. No account locking.

while true; do
    if [[ ! -s "$DB_FILE" ]]; then
        sleep "$SCAN_INTERVAL"
        continue
    fi
    
    # Daily reset logic
    today=$(date +%Y-%m-%d)
    if [[ ! -f "$BW_DIR/current_date" ]]; then
        echo "$today" > "$BW_DIR/current_date"
    fi
    saved_date=$(cat "$BW_DIR/current_date" 2>/dev/null || echo "$today")
    if [[ "$today" != "$saved_date" ]]; then
        # New day! Reset daily usage and unlock users locked due to daily limit
        rm -f "$BW_DIR/"*.daily_usage 2>/dev/null
        for locked_file in "$BW_DIR/"*.daily_locked; do
            [[ -f "$locked_file" ]] || continue
            locked_user=$(basename "$locked_file" .daily_locked)
            usermod -U "$locked_user" &>/dev/null
            rm -f "$locked_file"
        done
        echo "$today" > "$BW_DIR/current_date"
    fi

    # Connection limit auto-unlock: check marker files and unlock after CONN_LOCK_DURATION seconds
    for conn_lock_file in "$BW_DIR/"*.conn_locked; do
        [[ -f "$conn_lock_file" ]] || continue
        lock_ts=0
        read -r lock_ts < "$conn_lock_file" 2>/dev/null || lock_ts=0
        [[ "$lock_ts" =~ ^[0-9]+$ ]] || lock_ts=0
        printf -v now_ts '%(%s)T' -1
        if (( now_ts - lock_ts >= CONN_LOCK_DURATION )); then
            conn_locked_user=$(basename "$conn_lock_file" .conn_locked)
            usermod -U "$conn_locked_user" &>/dev/null
            rm -f "$conn_lock_file"
        fi
    done

    printf -v current_ts '%(%s)T' -1
    dynamic_banners_enabled=false

    # Trial-expiry safety net, independent of atd: the primary cleanup
    # path (firewallfalcon-trial-cleanup.sh) only runs if the `at now +
    # N hours` job scheduled when the trial was issued actually fires —
    # which never happens at all if atd isn't installed/running, or if
    # the server rebooted in between. This loop already runs every
    # SCAN_INTERVAL seconds as root regardless of atd, so it double-
    # checks every trial account's real issue time (from
    # bot_trial_log.db) against the configured trial duration and
    # force-cleans anything clearly overdue — a 10-minute grace window
    # keeps it from ever racing the normal on-time cleanup.
    BOT_TRIAL_LOG="/etc/firewallfalcon/bot_trial_log.db"
    BOT_PLANS_CONF="/etc/firewallfalcon/bot_plans.conf"
    if [[ -f "$BOT_TRIAL_LOG" && -s "$DB_FILE" ]]; then
        trial_hours=1
        if [[ -f "$BOT_PLANS_CONF" ]]; then
            plan_hours=$(grep -m1 '^TRIAL_HOURS=' "$BOT_PLANS_CONF" 2>/dev/null | cut -d'"' -f2)
            [[ "$plan_hours" =~ ^[0-9]+$ ]] && trial_hours="$plan_hours"
        fi
        overdue_trials=()
        while IFS=: read -r db_user _ _ _ _ _ db_type _; do
            [[ "$db_type" == "trial" ]] || continue
            issued=$(awk -F: -v h="$db_user" '$2==h{t=$3} END{print t+0}' "$BOT_TRIAL_LOG" 2>/dev/null)
            [[ "$issued" =~ ^[0-9]+$ && "$issued" -gt 0 ]] || continue
            (( current_ts > issued + trial_hours * 3600 + 600 )) && overdue_trials+=("$db_user")
        done < "$DB_FILE"
        for ot_user in "${overdue_trials[@]}"; do
            killall -u "$ot_user" -9 &>/dev/null
            pkill -9 -u "$ot_user" &>/dev/null
            userdel -rf "$ot_user" &>/dev/null
            sed -i "/^${ot_user}:/d" "$DB_FILE"
            rm -f "$BW_DIR/${ot_user}.usage" "$BW_DIR/${ot_user}.daily_usage" "$BW_DIR/${ot_user}.conn_locked" "$BW_DIR/${ot_user}.daily_locked"
            rm -rf "$PID_DIR/${ot_user}"
            sed -i "/^${ot_user}:/d" "/etc/firewallfalcon/login_modes.db" 2>/dev/null
        done
    fi

    # Reset associative arrays each cycle (unset first to avoid stale data)
    unset session_pids locked_users uid_to_user loginuid_pids
    declare -A session_pids=()
    declare -A locked_users=()
    declare -A uid_to_user=()
    declare -A loginuid_pids=()

    while IFS=: read -r username _ uid _rest; do
        [[ -n "$username" && "$uid" =~ ^[0-9]+$ ]] && uid_to_user["$uid"]="$username"
    done < /etc/passwd

    # Method 1: process owner from ps (primary source for connection counting)
    # sshd-session is the user-owned process on Ubuntu 24.04+ (OpenSSH 9.8+)
    # On Ubuntu 22, the per-session sshd is user-owned instead.
    # Either way, exactly 1 user-owned process exists per SSH session.
    while read -r ssh_pid ssh_owner; do
        [[ "$ssh_pid" =~ ^[0-9]+$ ]] || continue
        if [[ -n "$ssh_owner" && "$ssh_owner" != "root" && "$ssh_owner" != "sshd" ]]; then
            session_pids["$ssh_owner"]+="$ssh_pid "
        fi
    done < <(ps -C sshd,sshd-session -o pid=,user= 2>/dev/null)

    # Method 2: kernel loginuid (reliable even when sshd runs as root)
    for p in /proc/[0-9]*/loginuid; do
        [[ -f "$p" ]] || continue
        login_uid=""
        read -r login_uid < "$p" || login_uid=""
        [[ "$login_uid" =~ ^[0-9]+$ && "$login_uid" != "4294967295" ]] || continue

        session_user="${uid_to_user[$login_uid]}"
        [[ -n "$session_user" ]] || continue

        pid_dir=$(dirname "$p")
        pid_num=$(basename "$pid_dir")
        comm=""
        read -r comm < "$pid_dir/comm" || comm=""
        [[ "$comm" == "sshd" ]] || continue

        ppid_val=""
        while read -r key value; do
            if [[ "$key" == "PPid:" ]]; then
                ppid_val="${value:-}"
                break
            fi
        done < "$pid_dir/status"
        [[ "$ppid_val" == "1" ]] && continue

        loginuid_pids["$session_user"]+="$pid_num "
    done

    # Detect locked users via /etc/shadow (cheaper than passwd -Sa)
    if [[ -r /etc/shadow ]]; then
        while IFS=: read -r shadow_user shadow_hash _rest; do
            [[ -n "$shadow_user" && "${shadow_hash:0:1}" == "!" ]] && locked_users["$shadow_user"]=1
        done < /etc/shadow
    else
        while read -r passwd_user _ passwd_status _rest; do
            [[ "$passwd_status" == "L" ]] && locked_users["$passwd_user"]=1
        done < <(passwd -Sa 2>/dev/null)
    fi

    if [[ -f "/etc/firewallfalcon/banners_enabled" ]]; then
        mkdir -p "$BANNER_DIR"
        dynamic_banners_enabled=true
    fi

    while IFS=: read -r user pass expiry limit bandwidth_gb daily_bandwidth_gb _extra; do
        [[ -z "$user" || "$user" == \#* ]] && continue
        
        [[ ! "$daily_bandwidth_gb" =~ ^[0-9]+\.?[0-9]*$ ]] && daily_bandwidth_gb=0

        # CRITICAL: unset before declare to reset per-user (bash declare is function-scoped)
        unset unique_pids
        declare -A unique_pids=()

        # Use ONLY ps-based session_pids for connection counting.
        # loginuid_pids can double-count (root-owned sshd has user's loginuid on Ubuntu 24)
        for pid in ${session_pids[$user]}; do
            [[ "$pid" =~ ^[0-9]+$ ]] && unique_pids["$pid"]=1
        done

        online_count=${#unique_pids[@]}
        user_locked=false
        if [[ -n "${locked_users[$user]+x}" ]]; then
            user_locked=true
        fi

        expiry_ts=0
        if [[ "$expiry" != "Never" && -n "$expiry" && "$expiry" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
            expiry_ts=$(date -d "$expiry" +%s 2>/dev/null || echo 0)
            if [[ "$expiry_ts" =~ ^[0-9]+$ ]] && (( expiry_ts > 0 && expiry_ts < current_ts )); then
                if ! $user_locked; then
                    usermod -L "$user" &>/dev/null
                    # Belt-and-suspenders session kill: killall -u alone has
                    # been unreliable at actually dropping an already-open
                    # session on some setups, silently leaving it connected
                    # even though the account is now locked. pkill -u is a
                    # more dependable primary method; the /proc/*/loginuid
                    # sweep is a last-resort fallback that kills by kernel
                    # login UID directly, bypassing process-name matching.
                    pkill -9 -u "$user" &>/dev/null
                    killall -u "$user" -9 &>/dev/null
                    _kill_uid=$(id -u "$user" 2>/dev/null)
                    if [[ "$_kill_uid" =~ ^[0-9]+$ ]]; then
                        for _kill_lp in /proc/[0-9]*/loginuid; do
                            [[ -f "$_kill_lp" ]] || continue
                            _kill_lu=""
                            read -r _kill_lu < "$_kill_lp" 2>/dev/null || _kill_lu=""
                            [[ "$_kill_lu" == "$_kill_uid" ]] || continue
                            kill -9 "$(basename "$(dirname "$_kill_lp")")" &>/dev/null
                        done
                    fi
                    locked_users["$user"]=1
                fi
                continue
            fi
        fi

        [[ "$limit" =~ ^[0-9]+$ ]] || limit=1
        if (( online_count > limit )); then
            # Kill only the EXCESS sessions, keep the oldest ones alive
            sorted_pids=()
            for pid in "${!unique_pids[@]}"; do
                sorted_pids+=("$pid")
            done
            IFS=$'\n' sorted_pids=($(sort -n <<<"${sorted_pids[*]}")); unset IFS

            for (( i=limit; i<${#sorted_pids[@]}; i++ )); do
                kill -9 "${sorted_pids[$i]}" &>/dev/null
            done

            # Remove killed PIDs from unique_pids so bandwidth tracking is correct
            for (( i=limit; i<${#sorted_pids[@]}; i++ )); do
                unset unique_pids["${sorted_pids[$i]}"]
            done
            online_count=${#unique_pids[@]}
        fi

        if $dynamic_banners_enabled; then
            days_left="N/A"
            if [[ "$expiry" != "Never" && -n "$expiry" && "$expiry_ts" =~ ^[0-9]+$ && $expiry_ts -gt 0 ]]; then
                diff_secs=$((expiry_ts - current_ts))
                if (( diff_secs <= 0 )); then
                    days_left="EXPIRED"
                else
                    d_l=$(( diff_secs / 86400 ))
                    h_l=$(( (diff_secs % 86400) / 3600 ))
                    if (( d_l == 0 )); then
                        days_left="${h_l}h left"
                    else
                        days_left="${d_l}d ${h_l}h"
                    fi
                fi
            fi

            bw_info="Unlimited"
            if [[ "$bandwidth_gb" != "0" && -n "$bandwidth_gb" ]]; then
                usagefile="$BW_DIR/${user}.usage"
                accum_disp=0
                if [[ -f "$usagefile" ]]; then
                    read -r accum_disp < "$usagefile"
                    [[ "$accum_disp" =~ ^[0-9]+$ ]] || accum_disp=0
                fi
                used_gb_int=$((accum_disp / 1073741824))
                used_gb_frac=$(( (accum_disp % 1073741824) * 100 / 1073741824 ))
                printf -v used_gb "%d.%02d" "$used_gb_int" "$used_gb_frac"
                quota_b=$(( ${bandwidth_gb%%.*} * 1073741824 ))
                remain_b=$(( quota_b - accum_disp ))
                (( remain_b < 0 )) && remain_b=0
                remain_gb_int=$((remain_b / 1073741824))
                remain_gb_frac=$(( (remain_b % 1073741824) * 100 / 1073741824 ))
                printf -v remain_gb "%d.%02d" "$remain_gb_int" "$remain_gb_frac"
                bw_info="${used_gb}/${bandwidth_gb} GB used | ${remain_gb} GB left"
            fi

            banner_content="<br><font color=\"yellow\"><b>      ✨ ACCOUNT STATUS ✨      </b></font><br><br>"
            banner_content+="<font color=\"white\">👤 <b>Username   :</b> $user</font><br>"
            banner_content+="<font color=\"white\">📅 <b>Expiration :</b> $expiry ($days_left)</font><br>"
            
            if [[ "$bandwidth_gb" != "0" ]]; then
                banner_content+="<font color=\"white\">📊 <b>Total BW   :</b> $bw_info</font><br>"
            fi
            
            if [[ "$daily_bandwidth_gb" != "0" ]]; then
                daily_usagefile="$BW_DIR/${user}.daily_usage"
                accum_disp=0
                if [[ -f "$daily_usagefile" ]]; then
                    read -r accum_disp < "$daily_usagefile"
                    [[ "$accum_disp" =~ ^[0-9]+$ ]] || accum_disp=0
                fi
                used_gb_int=$((accum_disp / 1073741824))
                used_gb_frac=$(( (accum_disp % 1073741824) * 100 / 1073741824 ))
                printf -v used_gb "%d.%02d" "$used_gb_int" "$used_gb_frac"
                quota_b=$(( ${daily_bandwidth_gb%%.*} * 1073741824 ))
                remain_b=$(( quota_b - accum_disp ))
                (( remain_b < 0 )) && remain_b=0
                remain_gb_int=$((remain_b / 1073741824))
                remain_gb_frac=$(( (remain_b % 1073741824) * 100 / 1073741824 ))
                printf -v remain_gb "%d.%02d" "$remain_gb_int" "$remain_gb_frac"
                daily_bw_info="${used_gb}/${daily_bandwidth_gb} GB used | ${remain_gb} GB left"
                banner_content+="<font color=\"white\">📊 <b>Daily BW   :</b> $daily_bw_info</font><br>"
            fi
            
            banner_content+="<font color=\"white\">🔌 <b>Sessions   :</b> $online_count/$limit</font><br><br>"
            write_banner_if_changed "$user" "$banner_content"
        fi

        # Usage is always measured and accumulated below, even for an
        # "unlimited" account (bandwidth_gb/daily_bandwidth_gb == "0")
        # — the accumulated .usage/.daily_usage totals are also what the
        # customer-facing usage-tracking link and the panel's account
        # view read, so they need to keep counting up whether or not
        # there's actually a cap to enforce. Only the lock-on-quota
        # checks further below stay conditional on an actual cap.
        usagefile="$BW_DIR/${user}.usage"
        accumulated=0
        if [[ -f "$usagefile" ]]; then
            read -r accumulated < "$usagefile"
            [[ "$accumulated" =~ ^[0-9]+$ ]] || accumulated=0
        fi

        if (( ${#unique_pids[@]} == 0 )); then
            for f in "$PID_DIR/${user}__"*.last; do
                [[ -f "$f" ]] || continue
                fpid=${f##*__}
                fpid=${fpid%.last}
                ts=$(date '+%Y-%m-%d %H:%M:%S')
                printf "%s | INFO | system | LOGOUT | %s | PID: %s\n" "$ts" "$user" "$fpid" >> "/etc/firewallfalcon/logs/client_connections.log" 2>/dev/null
                rm -f "$f"
            done
            continue
        fi

        delta_total=0
        for pid in "${!unique_pids[@]}"; do
            io_file="/proc/$pid/io"
            cur=0
            if [[ -r "$io_file" ]]; then
                rchar=0
                wchar=0
                while read -r key value; do
                    case "$key" in
                        rchar:) rchar=${value:-0} ;;
                        wchar:) wchar=${value:-0} ;;
                    esac
                done < "$io_file"
                cur=$((rchar + wchar))
            fi

            pidfile="$PID_DIR/${user}__${pid}.last"
            if [[ ! -f "$pidfile" ]]; then
                ip=$(ss -tp 2>/dev/null | grep -E "\b(pid|ppid)=$pid\b" | awk '{print $5}' | cut -d: -f1 | head -n 1)
                [[ -z "$ip" ]] && ip=$(ss -tp 2>/dev/null | grep -F "$pid" | awk '{print $5}' | cut -d: -f1 | head -n 1)
                [[ -z "$ip" ]] && ip="unknown"
                ts=$(date '+%Y-%m-%d %H:%M:%S')
                printf "%s | INFO | system | LOGIN | %s | PID: %s IP: %s\n" "$ts" "$user" "$pid" "$ip" >> "/etc/firewallfalcon/logs/client_connections.log" 2>/dev/null
            fi

            if [[ -f "$pidfile" ]]; then
                read -r prev < "$pidfile"
                [[ "$prev" =~ ^[0-9]+$ ]] || prev=0
                if (( cur >= prev )); then
                    d=$((cur - prev))
                else
                    d=$cur
                fi
                delta_total=$((delta_total + d))
            fi
            printf "%s\n" "$cur" > "$pidfile"
        done

        for f in "$PID_DIR/${user}__"*.last; do
            [[ -f "$f" ]] || continue
            fpid=${f##*__}
            fpid=${fpid%.last}
            if [[ ! -d "/proc/$fpid" ]]; then
                ts=$(date '+%Y-%m-%d %H:%M:%S')
                printf "%s | INFO | system | LOGOUT | %s | PID: %s\n" "$ts" "$user" "$fpid" >> "/etc/firewallfalcon/logs/client_connections.log" 2>/dev/null
                rm -f "$f"
            fi
        done

        new_total=$((accumulated + delta_total))
        printf "%s\n" "$new_total" > "$usagefile"

        if awk "BEGIN{exit(!($bandwidth_gb > 0))}" 2>/dev/null; then
            quota_bytes=$(awk "BEGIN{printf \"%.0f\", $bandwidth_gb * 1073741824}")
            if [[ "$quota_bytes" =~ ^[0-9]+$ ]] && (( quota_bytes > 0 && new_total >= quota_bytes )); then
                if ! $user_locked; then
                    usermod -L "$user" &>/dev/null
                    locked_users["$user"]=1
                    user_locked=true
                fi
            fi
        fi
        
        daily_usagefile="$BW_DIR/${user}.daily_usage"
        daily_accumulated=0
        if [[ -f "$daily_usagefile" ]]; then
            read -r daily_accumulated < "$daily_usagefile"
            [[ "$daily_accumulated" =~ ^[0-9]+$ ]] || daily_accumulated=0
        fi
        new_daily_total=$((daily_accumulated + delta_total))
        printf "%s\n" "$new_daily_total" > "$daily_usagefile"
        
        if awk "BEGIN{exit(!($daily_bandwidth_gb > 0))}" 2>/dev/null; then
            d_quota_bytes=$(awk "BEGIN{printf \"%.0f\", $daily_bandwidth_gb * 1073741824}")
            if [[ "$d_quota_bytes" =~ ^[0-9]+$ ]] && (( d_quota_bytes > 0 && new_daily_total >= d_quota_bytes )); then
                if ! $user_locked; then
                    usermod -L "$user" &>/dev/null
                    locked_users["$user"]=1
                    user_locked=true
                    touch "$BW_DIR/${user}.daily_locked"
                fi
            fi
        fi
    done < "$DB_FILE"

    sleep "$SCAN_INTERVAL"
done
EOF
    chmod +x "$LIMITER_SCRIPT"
    # Strip DOS line endings in case menu.sh was uploaded from Windows
    sed -i 's/\r$//' "$LIMITER_SCRIPT" 2>/dev/null

    cat > "$LIMITER_SERVICE" << EOF
[Unit]
Description=DAHOOM Active User Limiter
After=network.target

[Service]
Type=simple
ExecStart=$LIMITER_SCRIPT
Restart=always
RestartSec=10
Nice=10
IOSchedulingClass=best-effort
IOSchedulingPriority=7
MemoryHigh=48M
MemoryMax=64M

[Install]
WantedBy=multi-user.target
EOF
    sed -i 's/\r$//' "$LIMITER_SERVICE" 2>/dev/null

    pkill -f "firewallfalcon-limiter" 2>/dev/null

    if ! systemctl is-active --quiet firewallfalcon-limiter; then
        systemctl daemon-reload
        systemctl enable firewallfalcon-limiter &>/dev/null
        systemctl start firewallfalcon-limiter --no-block &>/dev/null
        
    else
        systemctl restart firewallfalcon-limiter --no-block &>/dev/null
        
    fi
}

sync_runtime_components_if_needed() {
    local limiter_marker="# DAHOOM limiter version 2026-07-23.10"
    cleanup_legacy_bandwidth_runtime
    setup_trial_cleanup_script >/dev/null 2>&1
    setup_falcon_server_motd >/dev/null 2>&1
    # Ensure the 'dahoom' command symlink is always available, and keep
    # retiring the old 'fm' / 'menu' names on every run (covers servers
    # that were installed before this rename).
    if [[ -f "/usr/local/bin/dahoom" ]]; then
        ln -sf "/usr/local/bin/dahoom" "/usr/bin/dahoom" 2>/dev/null || true
        rm -f "/usr/local/bin/menu" "/usr/local/bin/fm" "/usr/bin/menu" "/usr/bin/fm" 2>/dev/null || true
    fi
    if [[ ! -f "$LIMITER_SCRIPT" ]] || ! grep -Fqx "$limiter_marker" "$LIMITER_SCRIPT" 2>/dev/null; then
        setup_limiter_service >/dev/null 2>&1
    fi
    if [[ -f "$BADVPN_SERVICE_FILE" ]]; then
        ensure_badvpn_service_is_quiet
    fi
    if [[ -f "/etc/firewallfalcon/banners_enabled" ]]; then
        update_ssh_banners_config
    elif [[ -f "$SSHD_FF_CONFIG" ]]; then
        disable_dynamic_ssh_banner_system
        systemctl reload sshd 2>/dev/null || systemctl reload ssh 2>/dev/null || true
    fi
    # Self-heal: servers that already had the bot configured before the
    # long-poll service existed (or where it was somehow stopped/removed)
    # get it installed/restarted automatically, no re-configuration needed.
    # Also restarts it whenever TELEGRAM_BOT_SERVICE_MARKER doesn't match
    # what's stamped in the deployed unit file — the service is just a
    # long-running `bash dahoom`, so it keeps executing whatever bot code
    # it loaded at its own start time even after `dahoom` is updated on
    # disk; without this version check, an update to the bot's logic would
    # silently never reach an already-running instance.
    # BOT_SERVICE_ENABLED="false" means the admin deliberately stopped the
    # bot entirely (telegram_bot_menu's own stop/start option) — without
    # this check, self-heal would silently start it right back up on the
    # very next menu run, defeating that choice.
    if [[ -f "$TELEGRAM_CONF" ]] && grep -q "^BOT_TOKEN=" "$TELEGRAM_CONF" 2>/dev/null \
       && ! grep -Fqx 'BOT_SERVICE_ENABLED="false"' "$TELEGRAM_CONF" 2>/dev/null; then
        if ! systemctl is-active --quiet firewallfalcon-telegram-bot 2>/dev/null || \
           ! grep -Fqx "$TELEGRAM_BOT_SERVICE_MARKER" "/etc/systemd/system/firewallfalcon-telegram-bot.service" 2>/dev/null || \
           _fm_bot_service_is_stale; then
            setup_telegram_bot_service >/dev/null 2>&1
        fi
    fi
    _fm_sync_socksproxy_script
    _fm_migrate_falconproxy_to_netrelay
    _fm_ensure_xui_iplimit_ready
    _fm_ensure_xray_api_inbound
}

# The connection proxy's script is normally written only when an admin
# enables the proxy from the menu, so a server that enabled it months ago
# keeps running that old copy through every update. It now carries the
# real client address across to sshd (see publish_realip inside it), which
# is worthless if the running copy predates that — hence this: on a marker
# mismatch, rewrite the script and restart whichever of the two proxy
# services is actually up. Nothing is enabled that wasn't already enabled;
# a server that never turned the proxy on is left completely untouched.
_fm_sync_socksproxy_script() {
    local svc running=0
    for svc in firewallfalcon-socksproxy firewallfalcon-wsproxy; do
        systemctl is-active --quiet "$svc" 2>/dev/null && running=1
    done
    [[ "$running" == "1" ]] || return 0
    grep -Fqx "$SOCKS_PROXY_SCRIPT_MARKER" "$SOCKS_PROXY_SCRIPT" 2>/dev/null && return 0
    _fm_write_socksproxy_script
    for svc in firewallfalcon-socksproxy firewallfalcon-wsproxy; do
        systemctl is-active --quiet "$svc" 2>/dev/null && systemctl restart "$svc" >/dev/null 2>&1
    done
}

# 3x-ui's per-client "device/IP limit" field only ever actually disconnects
# anyone through a dedicated fail2ban jail (3x-ipl) that 3x-ui's own CLI sets
# up via `x-ui setup-fail2ban` — nothing in x-ui's install/update path runs
# this on its own, and nothing on our side ever prompted for it either. So an
# admin can set a client's device limit to 1, connect two devices, and both
# stay connected forever with zero error anywhere: 3x-ui's own enforcement
# job (check_client_ip_job.go) skips the entire enforcement pass whenever
# this jail isn't present, no matter how the limit is configured. This makes
# that prerequisite automatic: idempotent (safe to call every run), a no-op
# on any server where x-ui isn't installed/running, and self-healing for
# every server that already exists — no admin action needed.
_fm_ensure_xui_iplimit_ready() {
    command -v x-ui &>/dev/null || return 0
    systemctl is-active --quiet x-ui 2>/dev/null || return 0
    if [[ -f /etc/fail2ban/jail.d/3x-ipl.conf ]] && systemctl is-active --quiet fail2ban 2>/dev/null; then
        return 0
    fi
    x-ui setup-fail2ban >/dev/null 2>&1
}

# 3x-ui talks to Xray internally over one gRPC channel (an Xray inbound
# tagged "api", loopback-only) both to pull per-client traffic (the GB
# counters shown in the panel) and to observe which IPs are currently
# connected (what the device/IP-limit enforcement above depends on). That
# inbound is declared inside the admin's own Xray Advanced Template — not
# injected by 3x-ui itself — so a custom template pasted in from an unrelated
# guide (to add one rule, e.g. blocking bittorrent) can silently drop it if
# it replaced the whole template instead of extending it. The failure is
# invisible: no error anywhere, traffic just never counts and no limit is
# ever enforced, on any server, regardless of what's configured. This
# restores just that one inbound into whatever template is actually saved
# — nothing else in it is touched — and only when it's genuinely missing;
# an unreadable or unparseable template is left completely alone rather than
# risk corrupting it.
_fm_ensure_xray_api_inbound() {
    command -v x-ui &>/dev/null || return 0
    systemctl is-active --quiet x-ui 2>/dev/null || return 0
    command -v python3 &>/dev/null || return 0
    [[ -f /etc/x-ui/x-ui.db ]] || return 0

    local result
    result=$(python3 - <<'PYEOF' 2>/dev/null
import json
import sqlite3

DB = "/etc/x-ui/x-ui.db"
API_INBOUND = {
    "listen": "127.0.0.1",
    "port": 62789,
    "protocol": "tunnel",
    "settings": {"rewriteAddress": "127.0.0.1"},
    "tag": "api",
}


def main():
    try:
        conn = sqlite3.connect(DB, timeout=5)
        cur = conn.cursor()
        row = cur.execute(
            "SELECT value FROM settings WHERE key='xrayTemplateConfig'"
        ).fetchone()
    except Exception:
        return "SKIP"

    if not row or not (row[0] or "").strip():
        # No custom template saved at all: 3x-ui's own embedded default
        # already carries the api inbound, so there's nothing to fix.
        conn.close()
        return "SKIP"

    try:
        cfg = json.loads(row[0])
    except Exception:
        conn.close()
        return "SKIP"

    inbounds = cfg.get("inbounds")
    if not isinstance(inbounds, list):
        inbounds = []
    if any(isinstance(ib, dict) and ib.get("tag") == "api" for ib in inbounds):
        conn.close()
        return "SKIP"

    inbounds.append(API_INBOUND)
    cfg["inbounds"] = inbounds

    try:
        cur.execute("DELETE FROM settings WHERE key='xrayTemplateConfig'")
        cur.execute(
            "INSERT INTO settings (key, value) VALUES (?, ?)",
            ("xrayTemplateConfig", json.dumps(cfg)),
        )
        conn.commit()
        conn.close()
        return "FIXED"
    except Exception:
        conn.close()
        return "SKIP"


print(main())
PYEOF
)
    [[ "$result" == "FIXED" ]] || return 0
    systemctl restart x-ui >/dev/null 2>&1
}

# One-time, silent migration for servers that already have the old
# "falconproxy" identity installed: stop/remove it and reinstall the exact
# same running proxy under the new "netrelay" name/paths, on the same
# ports, so nothing breaks and nothing keeps calling itself falconproxy.
_fm_migrate_falconproxy_to_netrelay() {
    local old_service="/etc/systemd/system/falconproxy.service"
    local old_binary="/usr/local/bin/falconproxy"
    local old_conf="$DB_DIR/falconproxy_config.conf"

    [[ -f "$old_service" ]] || return 0
    [[ -f "$NETRELAY_SERVICE_FILE" ]] && { rm -f "$old_service" "$old_binary" "$old_conf" 2>/dev/null; return 0; }

    local ports="8080" installed_version="v2-Stable"
    [[ -f "$old_conf" ]] && source "$old_conf" 2>/dev/null
    ports="${PORTS:-8080}"
    installed_version="${INSTALLED_VERSION:-v2-Stable}"
    [[ "$installed_version" == "DAHOOM" ]] && installed_version="v2-Stable"

    systemctl stop falconproxy.service >/dev/null 2>&1
    systemctl disable falconproxy.service >/dev/null 2>&1
    rm -f "$old_service" "$old_binary" "$old_conf" 2>/dev/null

    local download_url="$(_fm_instalasi_raw)/netrelay-${installed_version}"
    curl -fsSL "$download_url" -o "$NETRELAY_BINARY" 2>/dev/null || return 0
    chmod +x "$NETRELAY_BINARY" 2>/dev/null

    cat > "$NETRELAY_SERVICE_FILE" <<EOF
[Unit]
Description=Net Relay ($installed_version)
After=network.target

[Service]
User=root
Type=simple
ExecStart=$NETRELAY_BINARY -p $ports
Restart=always
RestartSec=2s

[Install]
WantedBy=default.target
EOF
    cat > "$NETRELAY_CONFIG_FILE" <<EOF
PORTS="$ports"
INSTALLED_VERSION="$installed_version"
EOF
    systemctl daemon-reload
    systemctl enable netrelay.service >/dev/null 2>&1
    systemctl restart netrelay.service >/dev/null 2>&1
}

setup_bandwidth_service() {
    mkdir -p "$BANDWIDTH_DIR"
    # Bandwidth monitoring is now integrated into the limiter service above.
    cleanup_legacy_bandwidth_runtime
}

cleanup_legacy_bandwidth_runtime() {
    local needs_reload=false

    systemctl stop firewallfalcon-bandwidth &>/dev/null || true
    systemctl disable firewallfalcon-bandwidth &>/dev/null || true
    pkill -f "firewallfalcon-bandwidth" &>/dev/null || true

    if [[ -e "$BANDWIDTH_SERVICE" || -e "$BANDWIDTH_SCRIPT" || -e "$LEGACY_BANDWIDTH_DIR" ]]; then
        rm -f "$BANDWIDTH_SERVICE" "$BANDWIDTH_SCRIPT" 2>/dev/null
        rm -rf "$LEGACY_BANDWIDTH_DIR" 2>/dev/null
        needs_reload=true
    fi

    if $needs_reload; then
        systemctl daemon-reload &>/dev/null || true
    fi
}

setup_trial_cleanup_script() {
    cat > "$TRIAL_CLEANUP_SCRIPT" << 'TREOF'
#!/bin/bash
# DAHOOM Trial Account Auto-Cleanup
# Usage: firewallfalcon-trial-cleanup.sh <username>
DB_FILE="/etc/firewallfalcon/users.db"
BW_DIR="/etc/firewallfalcon/bandwidth"

username="$1"
if [[ -z "$username" ]]; then exit 1; fi

db_line=$(grep "^${username}:" "$DB_FILE" 2>/dev/null | head -n 1)
if [[ -z "$db_line" ]]; then exit 0; fi

IFS=: read -r _ _ _ _ _ _ trial_marker _rest <<< "$db_line"
if [[ "$trial_marker" != "trial" ]]; then
    exit 0
fi

# Kill active sessions
killall -u "$username" -9 &>/dev/null
pkill -9 -u "$username" &>/dev/null
sleep 1

# Delete system user
userdel -rf "$username" &>/dev/null

# Remove from DB
sed -i "/^${username}:/d" "$DB_FILE"

# Remove bandwidth tracking
rm -f "$BW_DIR/${username}.usage"
rm -rf "$BW_DIR/pidtrack/${username}"

# Remove HWID login-mode marker, if this was an HWID trial account
sed -i "/^${username}:/d" "/etc/firewallfalcon/login_modes.db" 2>/dev/null
TREOF
    chmod +x "$TRIAL_CLEANUP_SCRIPT"
}

setup_health_service() {
    local health_script="/usr/local/bin/firewallfalcon-health.py"
    local health_service="/etc/systemd/system/firewallfalcon-health.service"

    cat > "$health_script" << 'EOF'
#!/usr/bin/env python3
import os
import sys
import time
import subprocess
from datetime import datetime

LOGS_DIR = "/etc/firewallfalcon/logs"
SERVICE_LOG = os.path.join(LOGS_DIR, "service_health.log")

SERVICES = [
    ("badvpn", "BadVPN UDP Gateway"),
    ("udp-custom", "UDP Custom Daemon"),
    ("haproxy", "HAProxy SSL Frontend"),
    ("nginx", "Nginx Web Server"),
    ("netrelay", "Net Relay HTTP/WS Proxy"),
    ("zivpn", "ZiVPN Service"),
    ("xray", "VLESS Reality Service"),
    ("x-ui", "X-UI Web Panel"),
    ("firewallfalcon-panel", "Web Control Panel")
]

def log_event(level, service, action, details):
    os.makedirs(LOGS_DIR, exist_ok=True)
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts} | {level:<4} | system     | {action:<14} | {service:<15} | {details}\n"
    try:
        with open(SERVICE_LOG, "a", encoding="utf-8") as f:
            f.write(line)
    except Exception:
        pass

def is_service_active(svc_name):
    try:
        res = subprocess.run(["systemctl", "is-active", "--quiet", svc_name], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return res.returncode == 0
    except Exception:
        return False

def restart_service(svc_name):
    try:
        res = subprocess.run(["systemctl", "restart", svc_name], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return res.returncode == 0
    except Exception:
        return False

def check_resources():
    try:
        df = subprocess.check_output(["df", "-h", "/"]).decode("utf-8").splitlines()
        if len(df) >= 2:
            parts = df[1].split()
            pct_str = parts[4].replace("%", "")
            if pct_str.isdigit() and int(pct_str) >= 90:
                log_event("WARN", "Disk Space", "RESOURCE_ALERT", f"Disk usage critical: {pct_str}% used ({parts[2]}/{parts[1]})")

        mem = subprocess.check_output(["free", "-m"]).decode("utf-8").splitlines()
        if len(mem) >= 2:
            parts = mem[1].split()
            total = float(parts[1]) if parts[1].isdigit() else 1.0
            used = float(parts[2]) if parts[2].isdigit() else 0.0
            pct = (used / total) * 100.0
            if pct >= 90.0:
                log_event("WARN", "RAM Memory", "RESOURCE_ALERT", f"Memory usage critical: {pct:.1f}% used ({int(used)}MB/{int(total)}MB)")
    except Exception:
        pass

def main():
    service_status = {}
    print("DAHOOM Health & Outage Detector started.", flush=True)
    log_event("INFO", "HealthMonitor", "MONITOR_START", "Service Outage & Health Guard active")

    resource_check_counter = 0

    while True:
        try:
            for svc, title in SERVICES:
                svc_path = f"/etc/systemd/system/{svc}.service"
                alt_path = f"/lib/systemd/system/{svc}.service"
                if not os.path.exists(svc_path) and not os.path.exists(alt_path):
                    continue

                active = is_service_active(svc)
                prev_active = service_status.get(svc)

                if prev_active is not None and not active and prev_active:
                    log_event("CRIT", svc, "SERVICE_CRASH", f"CRITICAL: {title} stopped unexpectedly! Attempting auto-healing restart...")
                    restarted = restart_service(svc)
                    if restarted:
                        log_event("INFO", svc, "AUTO_HEAL_OK", f"SUCCESS: {title} auto-restarted and restored successfully.")
                        service_status[svc] = True
                    else:
                        log_event("CRIT", svc, "AUTO_HEAL_FAIL", f"ERROR: Failed to auto-restart {title}. Intervention required.")
                        service_status[svc] = False
                else:
                    service_status[svc] = active

            resource_check_counter += 1
            if resource_check_counter >= 10:
                check_resources()
                resource_check_counter = 0

        except Exception as e:
            print(f"Error in health monitor: {e}", file=sys.stderr)

        time.sleep(30)

if __name__ == "__main__":
    main()
EOF

    chmod +x "$health_script"
    sed -i 's/\r$//' "$health_script" 2>/dev/null

    cat > "$health_service" << EOF
[Unit]
Description=DAHOOM Service Health Guard
After=network.target

[Service]
Type=simple
User=root
ExecStart=/usr/bin/python3 $health_script
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload &>/dev/null || true
    systemctl enable firewallfalcon-health &>/dev/null || true
    systemctl restart firewallfalcon-health &>/dev/null || true
}

# Persistent long-poll service for the Telegram bot. Without this, updates
# were only picked up once a minute by cron (_run_telegram_poll with
# timeout=0), so a customer's message could sit unseen for up to 60s —
# this service keeps a long-poll connection open (~25s per call, looping
# forever) so messages are handled within roughly a second of being sent.
# The once-a-minute cron job (see telegram_bot_menu, option 1) is kept as
# a self-healing fallback in case this service is ever down.
# Is the running bot older than the script it runs?
#
# The marker above only works if a human remembers to bump it, and a
# forgotten bump is invisible: the update lands on disk, the admin sees
# the new version everywhere EXCEPT the bot, and nothing anywhere says
# why. That has now happened for real. This asks the question the marker
# was only ever approximating — "did /usr/local/bin/dahoom change after
# this service started?" — which cannot go stale because nobody has to
# remember anything.
#
# The marker is kept alongside it, not replaced: it still forces a
# restart when the unit file itself needs rewriting, which a timestamp
# comparison would never notice.
_fm_bot_service_is_stale() {
    local script="/usr/local/bin/dahoom"
    [[ -f "$script" ]] || return 1
    local script_mtime started started_ts
    script_mtime=$(stat -c %Y "$script" 2>/dev/null) || return 1
    started=$(systemctl show -p ActiveEnterTimestamp --value firewallfalcon-telegram-bot 2>/dev/null)
    # Never started, or systemd reports no timestamp: the "is-active"
    # check above already covers that case, so say "not stale" and let it
    # decide rather than restarting twice.
    [[ -n "$started" ]] || return 1
    started_ts=$(date -d "$started" +%s 2>/dev/null) || return 1
    [[ "$started_ts" =~ ^[0-9]+$ && "$script_mtime" =~ ^[0-9]+$ ]] || return 1
    (( script_mtime > started_ts ))
}

setup_telegram_bot_service() {
    local bot_service="/etc/systemd/system/firewallfalcon-telegram-bot.service"

    cat > "$bot_service" << EOF
${TELEGRAM_BOT_SERVICE_MARKER}
[Unit]
Description=DAHOOM Telegram Bot (long-poll)
After=network.target

[Service]
Type=simple
User=root
ExecStart=/bin/bash /usr/local/bin/dahoom _run_telegram_bot_service
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload &>/dev/null || true
    systemctl enable firewallfalcon-telegram-bot &>/dev/null || true
    systemctl restart firewallfalcon-telegram-bot &>/dev/null || true
    _fm_setup_bot_watchdog_timer

    # The once-a-minute cron poller exists only for boxes with no systemd.
    # With this service running it is pure duplication — a second full
    # `bash dahoom` every 60 seconds, each one sourcing this entire file,
    # racing the service for the same update offset. Retire it the moment
    # the service is confirmed up; the unit's own Restart=always is the
    # real safety net, and _fm_run_locked covers the overlap either way.
    if command -v crontab >/dev/null 2>&1 \
       && systemctl is-active --quiet firewallfalcon-telegram-bot 2>/dev/null \
       && crontab -l 2>/dev/null | grep -q '_run_telegram_poll'; then
        crontab -l 2>/dev/null | grep -v '_run_telegram_poll' | crontab - 2>/dev/null || true
        _log_action "BOT_CRON_POLLER_REMOVED" "cron" "systemd service active" "INFO" "bot" 2>/dev/null
    fi
}

