setup_falcon_server_motd() {
    mkdir -p "/etc/update-motd.d" "/etc/firewallfalcon" "/etc/profile.d" 2>/dev/null

    # 1. Disable ALL other default Ubuntu / Debian scripts in /etc/update-motd.d/
    if [[ -d "/etc/update-motd.d" ]]; then
        for s in /etc/update-motd.d/*; do
            [[ -e "$s" && "$s" != *"/01-falcon-banner" ]] && chmod -x "$s" 2>/dev/null || true
        done
        chmod -x /etc/update-motd.d/00-header 2>/dev/null || true
        chmod -x /etc/update-motd.d/10-help-text 2>/dev/null || true
        chmod -x /etc/update-motd.d/50-landscape-sysinfo 2>/dev/null || true
        chmod -x /etc/update-motd.d/50-motd-news 2>/dev/null || true
        chmod -x /etc/update-motd.d/85-fwupd 2>/dev/null || true
        chmod -x /etc/update-motd.d/88-esm-announce 2>/dev/null || true
        chmod -x /etc/update-motd.d/90-updates-available 2>/dev/null || true
        chmod -x /etc/update-motd.d/91-contract-ua-esm-status 2>/dev/null || true
        chmod -x /etc/update-motd.d/91-release-upgrade 2>/dev/null || true
        chmod -x /etc/update-motd.d/92-unattended-upgrades 2>/dev/null || true
        chmod -x /etc/update-motd.d/95-hwe-eol 2>/dev/null || true
        chmod -x /etc/update-motd.d/97-overlayroot 2>/dev/null || true
        chmod -x /etc/update-motd.d/98-fsck-at-reboot 2>/dev/null || true
        chmod -x /etc/update-motd.d/98-reboot-required 2>/dev/null || true
    fi

    # 2. Disable Canonical motd-news & Ubuntu Advantage ESM hooks
    if [[ -f "/etc/default/motd-news" ]]; then
        sed -i 's/ENABLED=1/ENABLED=0/' /etc/default/motd-news 2>/dev/null || true
    fi
    chmod -x /usr/lib/ubuntu-advantage/apt-esm-hook 2>/dev/null || true
    chmod -x /usr/share/landscape/landscape-sysinfo.wrapper 2>/dev/null || true

    # 3. Clear dynamic and static motd cache files completely
    > /run/motd.dynamic 2>/dev/null || true
    > /var/run/motd.dynamic 2>/dev/null || true
    > /etc/motd 2>/dev/null || true
    > /etc/legal 2>/dev/null || true
    > /etc/issue.net 2>/dev/null || true

    # 4. Deploy DAHOOM clean dynamic login banner
    cat > "/etc/update-motd.d/01-falcon-banner" << 'EOF'
#!/usr/bin/env bash
# Ⓓ DAHOOM Clean Login Banner

C_RESET="\033[0m"
C_BOLD="\033[1m"
C_CYAN="\033[38;5;51m"
C_VIOLET="\033[38;5;177m"
C_GREEN="\033[38;5;79m"
C_YELLOW="\033[38;5;222m"
C_BLUE="\033[38;5;67m"
C_ORANGE="\033[38;5;87m"
C_FRAME="\033[38;5;60m"
C_GRAY="\033[38;5;245m"
C_WHITE="\033[38;5;255m"

# 1. OS & Uptime
os_name="Linux"
if [[ -f /etc/os-release ]]; then
    os_name=$(grep -E '^PRETTY_NAME=' /etc/os-release | cut -d'=' -f2 | tr -d '"')
fi
uptime_str=$(uptime -p 2>/dev/null | sed 's/up //')
[[ -z "$uptime_str" ]] && uptime_str="N/A"

# 2. Hostname & IP
server_ip=$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')
[[ -z "$server_ip" ]] && server_ip=$(hostname -I 2>/dev/null | awk '{print $1}')
[[ -z "$server_ip" ]] && server_ip="127.0.0.1"

# 3. Memory & Load
mem_info=$(free -m 2>/dev/null | awk 'NR==2{printf "%.2f", ($2>0 ? $3*100/$2 : 0) }')
mem_pct="${mem_info:-0.00}%"
load_avg=$(cat /proc/loadavg 2>/dev/null | awk '{print $1}' || echo "0.00")

# 4. Version
ver="4.9.0"
if [[ -f "/etc/firewallfalcon/.version" ]]; then
    ver="4.9.0_$(cat /etc/firewallfalcon/.version 2>/dev/null | tr -d '[:space:]')"
fi

# 5. User statistics
total_u=0 active_u=0 locked_u=0 exp_u=0
if [[ -s "/etc/firewallfalcon/users.db" ]]; then
    now_ts=$(date +%s)
    declare -A s_locked=()
    if [[ -r /etc/shadow ]]; then
        while IFS=: read -r _su _sh_h _r; do
            [[ -n "$_su" && "${_sh_h:0:1}" == "!" ]] && s_locked["$_su"]=1
        done < /etc/shadow
    fi
    while IFS=: read -r _u _p exp _r; do
        [[ -z "$_u" || "$_u" == \#* ]] && continue
        (( total_u++ ))
        e_ts=0
        [[ -n "$exp" && "$exp" != "Never" ]] && e_ts=$(date -d "$exp" +%s 2>/dev/null || echo 0)
        if [[ -n "${s_locked[$_u]+x}" ]]; then
            (( locked_u++ ))
        elif (( e_ts > 0 && e_ts < now_ts )); then
            (( exp_u++ ))
        else
            (( active_u++ ))
        fi
    done < "/etc/firewallfalcon/users.db"
fi

len_title=$(( 12 + ${#ver} ))
pad_title=$(( 58 - len_title ))
[[ $pad_title -lt 1 ]] && pad_title=1

len_badge=$(( 51 + ${#active_u} + ${#locked_u} + ${#exp_u} + ${#total_u} ))
pad_badge=$(( 58 - len_badge ))
[[ $pad_badge -lt 1 ]] && pad_badge=1

echo
echo -e "  ${C_BOLD}${C_BLUE}╭──────────────────────────────────────────────────────────╮${C_RESET}"
echo -e "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_BOLD}${C_ORANGE}Ⓓ DAHOOM${C_RESET}  ${C_GRAY}${ver}${C_RESET}$(printf '%*s' "$pad_title" '')${C_BOLD}${C_BLUE}│${C_RESET}"
echo -e "  ${C_BOLD}${C_BLUE}├──────────────────────────────────────────────────────────┤${C_RESET}"
printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_WHITE}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
    "OS" "${os_name:0:17}" "Uptime" "${uptime_str:0:18}"
printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_GREEN}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
    "Memory" "${mem_pct} Used" "Load" "$load_avg"
printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_CYAN}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
    "IPv4" "${server_ip:0:17}" "Mode" "Multi-Protocol"
echo -e "  ${C_BOLD}${C_BLUE}├──────────────────────────────────────────────────────────┤${C_RESET}"
echo -e "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GREEN}🟢 ${active_u} Active${C_RESET} ${C_GRAY}│${C_RESET} ${C_YELLOW}🟡 ${locked_u} Locked${C_RESET} ${C_GRAY}│${C_RESET} ${C_RED}🔴 ${exp_u} Expired${C_RESET} ${C_GRAY}│${C_RESET} ${C_WHITE}👥 ${total_u} Total${C_RESET}$(printf '%*s' "$pad_badge" '')${C_BOLD}${C_BLUE}│${C_RESET}"
echo -e "  ${C_BOLD}${C_BLUE}╰──────────────────────────────────────────────────────────╯${C_RESET}"
echo -e "  ${C_GRAY}💡 Quick Launch:${C_RESET} Type ${C_GREEN}'dahoom'${C_RESET} to access DAHOOM.\n"
EOF

    chmod +x "/etc/update-motd.d/01-falcon-banner" 2>/dev/null || true
    sed -i 's/\r$//' "/etc/update-motd.d/01-falcon-banner" 2>/dev/null || true
    ln -sf "/etc/update-motd.d/01-falcon-banner" "/usr/local/bin/falcon-motd" 2>/dev/null || true

    # 5. Multi-Distro profile hook (RHEL, AlmaLinux, RockyLinux, CentOS, Fedora, openSUSE, Arch)
    cat > "/etc/profile.d/falcon_motd.sh" << 'EOF'
# DAHOOM interactive login banner
if [[ $- == *i* ]] && [ -z "$DAHOOM_MOTD_SHOWN" ] && [ -x "/usr/local/bin/falcon-motd" ] && [ ! -d "/etc/update-motd.d" ]; then
    export DAHOOM_MOTD_SHOWN=1
    /usr/local/bin/falcon-motd
fi
EOF
    chmod +x "/etc/profile.d/falcon_motd.sh" 2>/dev/null || true

    touch "/etc/firewallfalcon/.motd_enabled" 2>/dev/null || true
    return 0
}

restore_default_server_motd() {
    if [[ -d "/etc/update-motd.d" ]]; then
        for s in /etc/update-motd.d/*; do
            [[ -e "$s" && "$s" != *"/01-falcon-banner" ]] && chmod +x "$s" 2>/dev/null || true
        done
    fi
    if [[ -f "/etc/default/motd-news" ]]; then
        sed -i 's/ENABLED=0/ENABLED=1/' /etc/default/motd-news 2>/dev/null || true
    fi
    rm -f "/etc/update-motd.d/01-falcon-banner" "/usr/local/bin/falcon-motd" "/etc/profile.d/falcon_motd.sh" "/etc/firewallfalcon/.motd_enabled" 2>/dev/null || true
}

is_falcon_server_motd_enabled() {
    [[ -f "/etc/update-motd.d/01-falcon-banner" && -x "/etc/update-motd.d/01-falcon-banner" ]] || [[ -f "/etc/profile.d/falcon_motd.sh" && -f "/etc/firewallfalcon/.motd_enabled" ]]
}

disable_static_ssh_banner_in_sshd_config() {
    sed -i.bak -E "s|^[[:space:]]*Banner[[:space:]]+$SSH_BANNER_FILE[[:space:]]*$|# Banner $SSH_BANNER_FILE|" /etc/ssh/sshd_config 2>/dev/null
}

is_static_ssh_banner_enabled() {
    grep -q -E "^[[:space:]]*Banner[[:space:]]+$SSH_BANNER_FILE[[:space:]]*$" /etc/ssh/sshd_config 2>/dev/null && [ -f "$SSH_BANNER_FILE" ]
}

is_dynamic_ssh_banner_enabled() {
    [[ -f "/etc/firewallfalcon/banners_enabled" && -f "$SSHD_FF_CONFIG" ]]
}

get_ssh_banner_mode() {
    if is_dynamic_ssh_banner_enabled; then
        echo "dynamic"
    elif is_static_ssh_banner_enabled; then
        echo "static"
    else
        echo "disabled"
    fi
}

refresh_dynamic_banner_routing_if_enabled() {
    if is_dynamic_ssh_banner_enabled; then
        update_ssh_banners_config
    fi
}

update_ssh_banners_config() {
    local tmp_conf

    if [[ ! -f "/etc/firewallfalcon/banners_enabled" ]]; then
        if [[ -f "$SSHD_FF_CONFIG" ]]; then
            rm -f "$SSHD_FF_CONFIG" 2>/dev/null
            systemctl reload sshd 2>/dev/null || systemctl reload ssh 2>/dev/null
        fi
        return
    fi

    ensure_firewallfalcon_dirs
    tmp_conf="/tmp/ff_banners_new.conf"
    echo "# DAHOOM - Dynamic per-user SSH banners" > "$tmp_conf"

    if [[ -f "$DB_FILE" ]]; then
        while IFS=: read -r u _rest; do
            [[ -z "$u" || "$u" == \#* ]] && continue
            echo "Match User $u" >> "$tmp_conf"
            echo "    Banner /etc/firewallfalcon/banners/${u}.txt" >> "$tmp_conf"
        done < "$DB_FILE"
    fi

    if ! cmp -s "$tmp_conf" "$SSHD_FF_CONFIG" 2>/dev/null; then
        mv "$tmp_conf" "$SSHD_FF_CONFIG"
        if ! grep -q "^Include /etc/ssh/sshd_config.d/" /etc/ssh/sshd_config 2>/dev/null; then
            echo "Include /etc/ssh/sshd_config.d/*.conf" >> /etc/ssh/sshd_config
        fi
        systemctl reload sshd 2>/dev/null || systemctl reload ssh 2>/dev/null
    else
        rm -f "$tmp_conf"
    fi
}

setup_ssh_login_info() {
    ensure_firewallfalcon_dirs || return 1
    if ! touch "/etc/firewallfalcon/banners_enabled"; then
        echo -e "${C_RED}❌ Failed to enable dynamic SSH banners.${C_RESET}"
        return 1
    fi
    disable_static_ssh_banner_in_sshd_config
    update_ssh_banners_config
    return 0
}


generate_dns_record() {
    local target_domain="$1"
    local target_token="$2"

    # Only one free root domain is offered now, so there's nothing to pick —
    # just use it directly instead of prompting for a choice of one.
    if [[ -z "$target_domain" || -z "$target_token" ]]; then
        target_domain="$DESEC_DOMAIN"
        target_token="$DESEC_TOKEN"
    fi

    echo -e "\n${C_BLUE}⚙️ Generating a random subdomain under ${C_YELLOW}${target_domain}${C_BLUE}...${C_RESET}"
    if ! command -v jq &> /dev/null; then
        echo -e "${C_YELLOW}⚠️ jq not found, attempting to install...${C_RESET}"
        ff_pkg_install jq >/dev/null 2>&1 || {
            echo -e "${C_RED}❌ Failed to install jq. Cannot manage DNS records.${C_RESET}"
            return 1
        }
    fi
    local SERVER_IPV4
    SERVER_IPV4=$(curl -s -4 icanhazip.com)
    if ! _is_valid_ipv4 "$SERVER_IPV4"; then
        echo -e "\n${C_RED}❌ Error: Could not retrieve a valid public IPv4 address from icanhazip.com.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Please check your server's network connection and DNS resolver settings.${C_RESET}"
        echo -e "   Output received: '$SERVER_IPV4'"
        return 1
    fi

    local SERVER_IPV6
    SERVER_IPV6=$(curl -s -6 icanhazip.com --max-time 5)

    local RANDOM_SUBDOMAIN="dh-$(tr -dc a-z0-9 < /dev/urandom | head -c 6)"
    local FULL_DOMAIN="$RANDOM_SUBDOMAIN.$target_domain"
    local HAS_IPV6="false"

    local API_DATA
    API_DATA=$(printf '[{"subname": "%s", "type": "A", "ttl": 3600, "records": ["%s"]}]' "$RANDOM_SUBDOMAIN" "$SERVER_IPV4")

    if [[ -n "$SERVER_IPV6" ]]; then
        local aaaa_record
        aaaa_record=$(printf ',{"subname": "%s", "type": "AAAA", "ttl": 3600, "records": ["%s"]}' "$RANDOM_SUBDOMAIN" "$SERVER_IPV6")
        API_DATA="${API_DATA%?}${aaaa_record}]"
        HAS_IPV6="true"
    fi

    local CREATE_RESPONSE
    CREATE_RESPONSE=$(curl -s -w "%{http_code}" -X POST "https://desec.io/api/v1/domains/$target_domain/rrsets/" \
        -H "Authorization: Token $target_token" -H "Content-Type: application/json" \
        --data "$API_DATA")
    
    local HTTP_CODE=${CREATE_RESPONSE: -3}
    local RESPONSE_BODY=${CREATE_RESPONSE:0:${#CREATE_RESPONSE}-3}

    if [[ "$HTTP_CODE" -ne 201 ]]; then
        echo -e "${C_RED}❌ Failed to create DNS records. API returned HTTP $HTTP_CODE.${C_RESET}"
        if [[ -n "$RESPONSE_BODY" ]]; then
            echo -e "${C_YELLOW}Response: $(echo "$RESPONSE_BODY" | jq -r '.detail // .' 2>/dev/null || echo "$RESPONSE_BODY")${C_RESET}"
        fi
        return 1
    fi
    
    cat > "$DNS_INFO_FILE" <<-EOF
SUBDOMAIN="$RANDOM_SUBDOMAIN"
ROOT_DOMAIN="$target_domain"
FULL_DOMAIN="$FULL_DOMAIN"
DESEC_TOKEN="$target_token"
HAS_IPV6="$HAS_IPV6"
EOF
    echo -e "\n${C_GREEN}✅ Successfully created domain: ${C_YELLOW}$FULL_DOMAIN${C_RESET}"
}

delete_dns_record() {
    if [ ! -f "$DNS_INFO_FILE" ]; then
        echo -e "\n${C_YELLOW}ℹ️ No domain to delete.${C_RESET}"
        return
    fi
    echo -e "\n${C_BLUE}🗑️ Deleting DNS records...${C_RESET}"
    local ROOT_DOMAIN="" SUBDOMAIN="" DESEC_TOKEN="" HAS_IPV6="false" FULL_DOMAIN=""
    source "$DNS_INFO_FILE" 2>/dev/null
    ROOT_DOMAIN="${ROOT_DOMAIN:-$DESEC_DOMAIN}"
    DESEC_TOKEN="${DESEC_TOKEN:-DCB8n39CTvzX8Cx7zAJPUBVUjfJz}"

    if [[ -z "$SUBDOMAIN" ]]; then
        echo -e "${C_RED}❌ Could not read record details from config file. Skipping deletion.${C_RESET}"
        return
    fi

    curl -s --max-time 4 -X DELETE "https://desec.io/api/v1/domains/$ROOT_DOMAIN/rrsets/$SUBDOMAIN/A/" \
         -H "Authorization: Token $DESEC_TOKEN" > /dev/null 2>&1 || true

    if [[ "$HAS_IPV6" == "true" ]]; then
        curl -s --max-time 4 -X DELETE "https://desec.io/api/v1/domains/$ROOT_DOMAIN/rrsets/$SUBDOMAIN/AAAA/" \
             -H "Authorization: Token $DESEC_TOKEN" > /dev/null 2>&1 || true
    fi

    echo -e "\n${C_GREEN}✅ Deleted domain: ${C_YELLOW}$FULL_DOMAIN${C_RESET}"
    rm -f "$DNS_INFO_FILE"
}

desec_subdomain_menu() {
    clear; show_banner
    echo
    menu_section "FREE SUBDOMAIN (deSEC)" "$C_TITLE"
    echo
    if [ -f "$DNS_INFO_FILE" ]; then
        source "$DNS_INFO_FILE" 2>/dev/null
        local root_show="${ROOT_DOMAIN:-$DESEC_DOMAIN}"
        echo -e "  ${C_CYAN}Active Domain:${C_RESET} ${C_YELLOW}$FULL_DOMAIN${C_RESET} (${C_GRAY}Root: ${root_show}${C_RESET})"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Delete Free Subdomain"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Generate New Subdomain"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" act
        case "$act" in
            1) delete_dns_record; press_enter ;;
            2) generate_dns_record; press_enter ;;
            *) ;;
        esac
    else
        echo -e "  ${C_CYAN}Status:${C_RESET} ${C_RED}No free subdomain configured${C_RESET}"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Generate Free Subdomain"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" act
        if [[ "$act" == "1" ]]; then
            generate_dns_record
            press_enter
        fi
    fi
}

custom_domain_menu() {
    clear; show_banner
    echo
    menu_section "CUSTOM DOMAIN SETUP" "$C_TITLE"
    echo
    local cur_cust=""
    if [ -f "/etc/firewallfalcon/custom_domain.info" ]; then
        source "/etc/firewallfalcon/custom_domain.info" 2>/dev/null
        cur_cust="$CUSTOM_DOMAIN"
        echo -e "  ${C_CYAN}Current Domain:${C_RESET} ${C_YELLOW}$CUSTOM_DOMAIN${C_RESET}"
        echo
    fi
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Set Custom Domain"
    if [[ -n "$cur_cust" ]]; then
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove Custom Domain"
    fi
    echo
    printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" act
    case "$act" in
        1)
            read -r -p "$(echo -e "${C_BLUE}👉 Enter custom domain (e.g. vpn.domain.com): ${C_RESET}")" new_dom
            if [[ -n "$new_dom" ]]; then
                mkdir -p "/etc/firewallfalcon" 2>/dev/null
                echo "CUSTOM_DOMAIN=\"$new_dom\"" > "/etc/firewallfalcon/custom_domain.info"
                echo -e "\n${C_GREEN}✅ Custom domain set to: ${C_YELLOW}$new_dom${C_RESET}"
            fi
            press_enter
            ;;
        2)
            rm -f "/etc/firewallfalcon/custom_domain.info"
            echo -e "\n${C_GREEN}✅ Custom domain removed.${C_RESET}"
            press_enter
            ;;
        *) ;;
    esac
}

update_domain_ip() {
    echo -e "\n${C_BLUE}Updating IP for active domain...${C_RESET}"
    local new_ip; new_ip=$(curl -s -4 icanhazip.com --max-time 5 2>/dev/null)
    if [[ -z "$new_ip" ]]; then
        echo -e "${C_RED}❌ Could not detect server public IP.${C_RESET}"
        press_enter
        return
    fi

    if [ -f "$CLOUDFLARE_INFO_FILE" ]; then
        source "$CLOUDFLARE_INFO_FILE" 2>/dev/null
        if [[ -n "$CF_API_TOKEN" && -n "$CF_ZONE_ID" && -n "$CF_DOMAIN" ]]; then
            local prox_bool="false"
            [[ "$CF_PROXIED" == "1" || "$CF_PROXIED" == "true" ]] && prox_bool="true"
            local rec_check; rec_check=$(curl -s -X GET "https://api.cloudflare.com/client/v4/zones/$CF_ZONE_ID/dns_records?type=A&name=$CF_DOMAIN" \
                -H "Authorization: Bearer $CF_API_TOKEN" \
                -H "Content-Type: application/json" --max-time 10)
            local rec_id; rec_id=$(echo "$rec_check" | grep -Po '"id":"\K[^"]*' | head -1)
            if [[ -n "$rec_id" ]]; then
                curl -s -X PATCH "https://api.cloudflare.com/client/v4/zones/$CF_ZONE_ID/dns_records/$rec_id" \
                    -H "Authorization: Bearer $CF_API_TOKEN" \
                    -H "Content-Type: application/json" \
                    --data "{\"content\":\"$new_ip\",\"proxied\":$prox_bool}" > /dev/null
                echo -e "${C_GREEN}✅ Cloudflare Domain ($CF_DOMAIN) IP updated to: ${C_CYAN}$new_ip${C_RESET}"
            fi
        fi
    elif [ -f "$DNS_INFO_FILE" ]; then
        local ROOT_DOMAIN="" SUBDOMAIN="" DESEC_TOKEN=""
        source "$DNS_INFO_FILE" 2>/dev/null
        ROOT_DOMAIN="${ROOT_DOMAIN:-$DESEC_DOMAIN}"
        DESEC_TOKEN="${DESEC_TOKEN:-DCB8n39CTvzX8Cx7zAJPUBVUjfJz}"
        if [[ -n "$ROOT_DOMAIN" && -n "$SUBDOMAIN" && -n "$DESEC_TOKEN" ]]; then
            curl -s -X PATCH "https://desec.io/api/v1/domains/$ROOT_DOMAIN/rrsets/$SUBDOMAIN/A/" \
                -H "Authorization: Token $DESEC_TOKEN" \
                -H "Content-Type: application/json" \
                --data "{\"records\": [\"$new_ip\"], \"ttl\": 3600}" > /dev/null
            echo -e "${C_GREEN}✅ deSEC Subdomain IP updated to: ${C_CYAN}$new_ip${C_RESET}"
        fi
    else
        echo -e "${C_GREEN}✅ Server IP verified: ${C_CYAN}$new_ip${C_RESET}"
    fi
    press_enter
}

inspect_dns_resolution() {
    clear; show_banner
    echo
    menu_section "DNS RESOLUTION INSPECTOR" "$C_TITLE"
    echo
    local active_domain=""
    if [ -f "$DNS_INFO_FILE" ]; then
        source "$DNS_INFO_FILE" 2>/dev/null
        active_domain="$FULL_DOMAIN"
    elif [ -f "/etc/firewallfalcon/custom_domain.info" ]; then
        source "/etc/firewallfalcon/custom_domain.info" 2>/dev/null
        active_domain="$CUSTOM_DOMAIN"
    fi

    if [[ -z "$active_domain" ]]; then
        echo -e "  ${C_RED}❌ No domain configured to inspect.${C_RESET}"
        press_enter
        return
    fi

    local server_ip; server_ip=$(curl -s -4 icanhazip.com --max-time 5 2>/dev/null)
    echo -e "  ${C_CYAN}Domain   :${C_RESET} ${C_YELLOW}$active_domain${C_RESET}"
    echo -e "  ${C_CYAN}Server IP:${C_RESET} ${C_WHITE}$server_ip${C_RESET}"
    echo
    echo -e "  ${C_BLUE}Inspecting DNS resolution...${C_RESET}"

    local resolved_ip=""
    if command -v getent &>/dev/null; then
        resolved_ip=$(getent ahostsv4 "$active_domain" 2>/dev/null | head -1 | awk '{print $1}')
    fi
    [[ -z "$resolved_ip" ]] && resolved_ip=$(ping -c1 "$active_domain" 2>/dev/null | head -1 | grep -Po '(?<=\().*?(?=\))')

    if [[ "$resolved_ip" == "$server_ip" ]]; then
        echo -e "\n  ${C_GREEN}✅ RESOLVED MATCH:${C_RESET} $active_domain -> ${C_GREEN}$resolved_ip${C_RESET}"
        echo -e "  ${C_DIM}Domain is correctly pointed to this server.${C_RESET}"
    elif [[ -n "$resolved_ip" ]]; then
        echo -e "\n  ${C_RED}⚠️ RESOLVED MISMATCH:${C_RESET} $active_domain -> ${C_RED}$resolved_ip${C_RESET}"
        echo -e "  ${C_DIM}Domain points to $resolved_ip but server IP is $server_ip.${C_RESET}"
    else
        echo -e "\n  ${C_YELLOW}⚠️ RESOLUTION PENDING:${C_RESET} Could not resolve $active_domain yet."
        echo -e "  ${C_DIM}DNS propagation may take a few minutes.${C_RESET}"
    fi
    echo
    press_enter
}

ssl_cert_manager_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "SSL CERTIFICATE MANAGER" "$C_TITLE"
        echo
        local active_domain=""
        if [ -f "$DNS_INFO_FILE" ]; then
            source "$DNS_INFO_FILE" 2>/dev/null
            active_domain="$FULL_DOMAIN"
        elif [ -f "/etc/firewallfalcon/custom_domain.info" ]; then
            source "/etc/firewallfalcon/custom_domain.info" 2>/dev/null
            active_domain="$CUSTOM_DOMAIN"
        fi

        if [[ -n "$active_domain" && -d "/etc/letsencrypt/live/$active_domain" ]]; then
            echo -e "  ${C_CYAN}Domain    :${C_RESET} ${C_YELLOW}$active_domain${C_RESET}"
            echo -e "  ${C_CYAN}SSL Status:${C_RESET} ${C_GREEN}Active (Let's Encrypt)${C_RESET}"
        else
            echo -e "  ${C_CYAN}Domain    :${C_RESET} ${C_YELLOW}${active_domain:-None}${C_RESET}"
            echo -e "  ${C_CYAN}SSL Status:${C_RESET} ${C_RED}Not Issued${C_RESET}"
        fi
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Issue Let's Encrypt SSL Cert"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "View SSL Certificate Details"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" ssl_act; then
            return
        fi
        case "$ssl_act" in
            1)
                if [[ -z "$active_domain" ]]; then
                    echo -e "\n${C_RED}❌ Please configure a domain first before issuing SSL.${C_RESET}"
                    press_enter
                    continue
                fi
                echo -e "\n${C_BLUE}Installing Certbot and issuing SSL certificate for $active_domain...${C_RESET}"
                if ! command -v certbot &>/dev/null; then
                    apt-get update &>/dev/null && apt-get install -y certbot &>/dev/null || yum install -y certbot &>/dev/null
                fi
                certbot certonly --standalone --non-interactive --agree-tos --register-unsafely-without-email -d "$active_domain"
                if [[ -d "/etc/letsencrypt/live/$active_domain" ]]; then
                    echo -e "\n${C_GREEN}✅ SSL Certificate issued successfully for $active_domain!${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ Certbot failed to issue certificate. Ensure port 80 is open and domain points to server IP.${C_RESET}"
                fi
                press_enter
                ;;
            2)
                if [[ -n "$active_domain" && -f "/etc/letsencrypt/live/$active_domain/cert.pem" ]]; then
                    echo -e "\n${C_CYAN}Certificate Info:${C_RESET}"
                    openssl x509 -in "/etc/letsencrypt/live/$active_domain/cert.pem" -noout -dates -issuer 2>/dev/null
                else
                    echo -e "\n${C_YELLOW}ℹ️ No SSL certificate active for $active_domain.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

CLOUDFLARE_INFO_FILE="/etc/firewallfalcon/cloudflare.info"

cloudflare_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "CLOUDFLARE INTEGRATION" "$C_TITLE"
        echo

        local cf_token="" cf_zone="" cf_domain="" cf_proxied="0"
        if [ -f "$CLOUDFLARE_INFO_FILE" ]; then
            source "$CLOUDFLARE_INFO_FILE" 2>/dev/null
            cf_token="$CF_API_TOKEN"
            cf_zone="$CF_ZONE_ID"
            cf_domain="$CF_DOMAIN"
            cf_proxied="${CF_PROXIED:-0}"
        fi

        local masked_token="None"
        if [[ -n "$cf_token" ]]; then
            if [ ${#cf_token} -ge 8 ]; then
                masked_token="${cf_token:0:4}••••••••${cf_token: -4}"
            else
                masked_token="••••••••"
            fi
        fi

        local proxy_badge
        if [[ "$cf_proxied" == "1" || "$cf_proxied" == "true" ]]; then
            proxy_badge="${C_YELLOW}🟠 Proxied (CDN On)${C_RESET}"
        else
            proxy_badge="${C_WHITE}⚪ DNS Only (Direct)${C_RESET}"
        fi

        echo -e "  ${C_CYAN}Active Domain:${C_RESET} ${C_YELLOW}${cf_domain:-Not Set}${C_RESET}"
        echo -e "  ${C_CYAN}Zone ID      :${C_RESET} ${C_WHITE}${cf_zone:-Not Set}${C_RESET}"
        echo -e "  ${C_CYAN}API Token    :${C_RESET} ${C_DIM}${masked_token}${C_RESET}"
        echo -e "  ${C_CYAN}Default Proxy:${C_RESET} ${proxy_badge}"
        echo

        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Setup / Update API Token (Auto-Discover Domains)"
        if [[ -n "$cf_token" && -n "$cf_zone" ]]; then
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Sync Server IP (Create / Update A Record)"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Switch Active Domain"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Toggle Default Proxy Mode"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "List & Inspect DNS Records"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "Remove Cloudflare Configuration"
        fi
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo

        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" cf_act; then
            return
        fi

        case "$cf_act" in
            1|3)
                local in_token="$cf_token"
                if [[ "$cf_act" == "1" || -z "$in_token" ]]; then
                    echo -e "\n${C_BLUE}--- Cloudflare API Setup ---${C_RESET}"
                    echo -e "${C_DIM}• Enter your Cloudflare API Token (with Zone.DNS permissions).${C_RESET}"
                    echo -e "${C_DIM}• All domains linked to your account will be automatically discovered.${C_RESET}"
                    echo -e "${C_DIM}• Enter 0 to cancel and return.${C_RESET}\n"
                    
                    read -r -p "$(echo -e "${C_BLUE}👉 Enter API Token [${masked_token} | 0 to cancel]: ${C_RESET}")" user_token
                    if [[ "$user_token" == "0" || "$user_token" == "q" || "$user_token" == "Q" ]]; then
                        echo -e "\n${C_YELLOW}↩️ Canceled.${C_RESET}"
                        sleep 0.8
                        continue
                    fi
                    user_token=${user_token:-$cf_token}
                    if [[ -z "$user_token" ]]; then
                        echo -e "\n${C_YELLOW}↩️ API Token not provided. Operation canceled.${C_RESET}"
                        press_enter
                        continue
                    fi
                    in_token="$user_token"
                fi

                echo -e "\n${C_BLUE}Connecting to Cloudflare and fetching available domains...${C_RESET}"
                local zones_res; zones_res=$(curl -s -X GET "https://api.cloudflare.com/client/v4/zones?per_page=50" \
                    -H "Authorization: Bearer $in_token" \
                    -H "Content-Type: application/json" --max-time 12)

                local is_success; is_success=$(echo "$zones_res" | grep -o '"success":true')
                if [[ -z "$is_success" ]]; then
                    echo -e "\n${C_RED}❌ Failed to connect to Cloudflare API.${C_RESET}"
                    local err_msg; err_msg=$(echo "$zones_res" | grep -Po '"message":"\K[^"]*' | head -1)
                    [[ -n "$err_msg" ]] && echo -e "   • Error: ${C_YELLOW}$err_msg${C_RESET}"
                    press_enter
                    continue
                fi

                local NUM_ZONES=0
                if command -v python3 &>/dev/null; then
                    eval "$(python3 -c "
import sys, json
try:
    d = json.loads('''$zones_res''')
    zones = d.get('result', [])
    print(f'NUM_ZONES={len(zones)}')
    for i, z in enumerate(zones):
        zid = z.get('id', '')
        zname = z.get('name', '')
        zst = z.get('status', 'active')
        print(f'Z_ID_{i}=\"{zid}\"')
        print(f'Z_NAME_{i}=\"{zname}\"')
        print(f'Z_STATUS_{i}=\"{zst}\"')
except Exception:
    print('NUM_ZONES=0')
")"
                fi

                if [[ "$NUM_ZONES" -le 0 ]]; then
                    echo -e "\n${C_YELLOW}⚠️ No zones (domains) found in this Cloudflare account.${C_RESET}"
                    press_enter
                    continue
                fi

                echo -e "\n${C_GREEN}✅ Connected successfully! Found $NUM_ZONES domain(s):${C_RESET}\n"
                local idx
                for ((idx=0; idx<NUM_ZONES; idx++)); do
                    local zid_var="Z_ID_$idx"
                    local zname_var="Z_NAME_$idx"
                    local zst_var="Z_STATUS_$idx"
                    local zn="${!zname_var}"
                    local zs="${!zst_var}"
                    local mark=""
                    [[ "$zn" == "$cf_domain" ]] && mark="${C_GREEN} (Current Default)${C_RESET}"
                    printf "  ${C_CHOICE}[%2d]${C_RESET} %-30s ${C_DIM}(%s)${C_RESET}%b\n" "$((idx+1))" "$zn" "$zs" "$mark"
                done
                echo
                printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[ 0]" "Cancel"
                echo

                read -r -p "$(echo -e ${C_PROMPT}"> Select domain number to set as active default [1]: "${C_RESET})" z_sel
                if [[ "$z_sel" == "0" || "$z_sel" == "q" || "$z_sel" == "Q" ]]; then
                    echo -e "\n${C_YELLOW}↩️ Canceled.${C_RESET}"
                    sleep 0.8
                    continue
                fi
                z_sel=${z_sel:-1}
                if ! [[ "$z_sel" =~ ^[0-9]+$ ]] || [ "$z_sel" -lt 1 ] || [ "$z_sel" -gt "$NUM_ZONES" ]; then
                    echo -e "\n${C_RED}❌ Invalid selection.${C_RESET}"
                    press_enter
                    continue
                fi

                local sel_idx=$((z_sel - 1))
                local zid_var="Z_ID_$sel_idx"
                local zname_var="Z_NAME_$sel_idx"
                local chosen_zone="${!zid_var}"
                local chosen_domain="${!zname_var}"

                mkdir -p "/etc/firewallfalcon" 2>/dev/null
                cat > "$CLOUDFLARE_INFO_FILE" <<EOF
CF_API_TOKEN="$in_token"
CF_ZONE_ID="$chosen_zone"
CF_DOMAIN="$chosen_domain"
CF_PROXIED="${cf_proxied:-0}"
EOF
                chmod 600 "$CLOUDFLARE_INFO_FILE" 2>/dev/null

                echo -e "\n${C_GREEN}✅ Active default domain set to: ${C_YELLOW}$chosen_domain${C_RESET}"
                echo -e "   • Zone ID: ${C_CYAN}$chosen_zone${C_RESET}"
                press_enter
                ;;
            2)
                if [[ -z "$cf_token" || -z "$cf_zone" ]]; then
                    echo -e "\n${C_RED}❌ Please configure API Token first.${C_RESET}"
                    press_enter; continue
                fi
                local server_ip; server_ip=$(curl -s -4 icanhazip.com --max-time 5 2>/dev/null)
                if [[ -z "$server_ip" ]]; then
                    echo -e "\n${C_RED}❌ Could not detect server public IP.${C_RESET}"
                    press_enter; continue
                fi

                read -r -p "$(echo -e "${C_BLUE}👉 Enter record name / subdomain to sync [${cf_domain} | 0 to cancel]: ${C_RESET}")" sync_dom
                if [[ "$sync_dom" == "0" || "$sync_dom" == "q" || "$sync_dom" == "Q" ]]; then
                    echo -e "\n${C_YELLOW}↩️ Canceled.${C_RESET}"
                    sleep 0.8
                    continue
                fi
                sync_dom=${sync_dom:-$cf_domain}

                local prox_bool="false"
                [[ "$cf_proxied" == "1" || "$cf_proxied" == "true" ]] && prox_bool="true"

                echo -e "\n${C_BLUE}Syncing A record '$sync_dom' -> '$server_ip' (Proxy: $prox_bool)...${C_RESET}"
                
                local rec_check; rec_check=$(curl -s -X GET "https://api.cloudflare.com/client/v4/zones/$cf_zone/dns_records?type=A&name=$sync_dom" \
                    -H "Authorization: Bearer $cf_token" \
                    -H "Content-Type: application/json" --max-time 10)
                
                local rec_id; rec_id=$(echo "$rec_check" | grep -Po '"id":"\K[^"]*' | head -1)

                if [[ -n "$rec_id" ]]; then
                    local upd_res; upd_res=$(curl -s -X PATCH "https://api.cloudflare.com/client/v4/zones/$cf_zone/dns_records/$rec_id" \
                        -H "Authorization: Bearer $cf_token" \
                        -H "Content-Type: application/json" \
                        --data "{\"content\":\"$server_ip\",\"proxied\":$prox_bool}" --max-time 10)
                    if echo "$upd_res" | grep -q '"success":true'; then
                        echo -e "\n${C_GREEN}✅ A Record updated successfully: ${C_YELLOW}$sync_dom${C_RESET} -> ${C_CYAN}$server_ip${C_RESET}"
                    else
                        echo -e "\n${C_RED}❌ Failed to update A record.${C_RESET}"
                    fi
                else
                    local create_res; create_res=$(curl -s -X POST "https://api.cloudflare.com/client/v4/zones/$cf_zone/dns_records" \
                        -H "Authorization: Bearer $cf_token" \
                        -H "Content-Type: application/json" \
                        --data "{\"type\":\"A\",\"name\":\"$sync_dom\",\"content\":\"$server_ip\",\"ttl\":1,\"proxied\":$prox_bool}" --max-time 10)
                    if echo "$create_res" | grep -q '"success":true'; then
                        echo -e "\n${C_GREEN}✅ A Record created successfully: ${C_YELLOW}$sync_dom${C_RESET} -> ${C_CYAN}$server_ip${C_RESET}"
                    else
                        echo -e "\n${C_RED}❌ Failed to create A record.${C_RESET}"
                    fi
                fi
                press_enter
                ;;
            4)
                local new_p="0"
                if [[ "$cf_proxied" == "0" || "$cf_proxied" == "false" ]]; then
                    new_p="1"
                fi
                sed -i "/CF_PROXIED=/d" "$CLOUDFLARE_INFO_FILE" 2>/dev/null
                echo "CF_PROXIED=\"$new_p\"" >> "$CLOUDFLARE_INFO_FILE"
                echo -e "\n${C_GREEN}✅ Default Proxy Mode updated to: $([ "$new_p" == "1" ] && echo "🟠 Proxied" || echo "⚪ DNS Only")${C_RESET}"
                press_enter
                ;;
            5)
                echo -e "\n${C_BLUE}Fetching DNS records from Cloudflare...${C_RESET}\n"
                local recs_json; recs_json=$(curl -s -X GET "https://api.cloudflare.com/client/v4/zones/$cf_zone/dns_records?per_page=50" \
                    -H "Authorization: Bearer $cf_token" \
                    -H "Content-Type: application/json" --max-time 10)
                
                if echo "$recs_json" | grep -q '"success":true'; then
                    echo -e "  ${C_BOLD}${C_CYAN}Type   Proxy   Name                                 Points To${C_RESET}"
                    echo -e "  ${C_DIM}-------------------------------------------------------------------------${C_RESET}"
                    
                    if command -v python3 &>/dev/null; then
                        python3 -c "
import sys, json
try:
    d = json.loads('''$recs_json''')
    for r in d.get('result', []):
        t = r.get('type', '')
        p = '🟠 ON ' if r.get('proxied') else '⚪ OFF'
        n = r.get('name', '')[:35]
        c = r.get('content', '')[:30]
        print(f'  {t:<6} {p:<7} {n:<36} {c}')
except Exception as e:
    print(e)
"
                    else
                        echo "$recs_json" | grep -Po '("type":"[^"]*"|"name":"[^"]*"|"content":"[^"]*")'
                    fi
                else
                    echo -e "${C_RED}❌ Failed to fetch DNS records.${C_RESET}"
                fi
                echo
                press_enter
                ;;
            6)
                read -r -p "$(echo -e "${C_RED}👉 Remove Cloudflare configuration? [y/N | 0 to cancel]: ${C_RESET}")" rm_cf
                if [[ "$rm_cf" == "y" || "$rm_cf" == "Y" ]]; then
                    rm -f "$CLOUDFLARE_INFO_FILE"
                    echo -e "\n${C_GREEN}✅ Cloudflare configuration removed.${C_RESET}"
                else
                    echo -e "\n${C_YELLOW}↩️ Canceled.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

dns_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "DOMAIN & DNS MANAGEMENT" "$C_TITLE"
        echo
        
        local active_domain="None" provider="None"
        if [ -f "$CLOUDFLARE_INFO_FILE" ]; then
            source "$CLOUDFLARE_INFO_FILE" 2>/dev/null
            active_domain="${CF_DOMAIN:-None}"
            provider="Cloudflare"
        elif [ -f "$DNS_INFO_FILE" ]; then
            source "$DNS_INFO_FILE" 2>/dev/null
            active_domain="${FULL_DOMAIN:-None}"
            provider="deSEC (Free)"
        elif [ -f "/etc/firewallfalcon/custom_domain.info" ]; then
            source "/etc/firewallfalcon/custom_domain.info" 2>/dev/null
            active_domain="${CUSTOM_DOMAIN:-None}"
            provider="Custom Domain"
        fi

        echo -e "  ${C_CYAN}Active Domain:${C_RESET} ${C_YELLOW}${active_domain}${C_RESET}"
        echo -e "  ${C_CYAN}Provider     :${C_RESET} ${C_CYAN}${provider}${C_RESET}"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Free Subdomain (deSEC)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Cloudflare Integration"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Custom Domain Setup"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Update IP (DDNS)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "DNS Resolution Inspector"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "SSL Certificate Manager"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" dns_act; then
            return
        fi
        case "$dns_act" in
            1) desec_subdomain_menu ;;
            2) cloudflare_menu ;;
            3) custom_domain_menu ;;
            4) update_domain_ip ;;
            5) inspect_dns_resolution ;;
            6) ssl_cert_manager_menu ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

_select_user_interface() {
    local title="$1"
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}${title}${C_RESET}\n"
    if [[ ! -s $DB_FILE ]]; then
        echo -e "${C_YELLOW}ℹ️ No users found in the database.${C_RESET}"
        SELECTED_USER="NO_USERS"; return
    fi
    
    mapfile -t all_users < <(cut -d: -f1 "$DB_FILE" | sort)
    local -A all_user_lookup=()
    local username
    for username in "${all_users[@]}"; do
        all_user_lookup["$username"]=1
    done
    
    if [ ${#all_users[@]} -ge 15 ]; then
        read -p "👉 Enter a search term (or press Enter to list all): " search_term
        if [[ -n "$search_term" ]]; then
            mapfile -t users < <(printf "%s\n" "${all_users[@]}" | grep -i "$search_term")
        else
            users=("${all_users[@]}")
        fi
    else
        users=("${all_users[@]}")
    fi

    if [ ${#users[@]} -eq 0 ]; then
        echo -e "\n${C_YELLOW}ℹ️ No users found matching your criteria.${C_RESET}"
        SELECTED_USER="NO_USERS"; return
    fi
    echo -e "\nPlease select a user:\n"
    for i in "${!users[@]}"; do
        printf "  ${C_GREEN}[%2d]${C_RESET} %s\n" "$((i+1))" "${users[$i]}"
    done
    echo -e "\n  ${C_RED} [ 0]${C_RESET} ↩️ Cancel"
    echo -e "${C_CYAN}💡 Tip: you can also type the exact username directly.${C_RESET}"
    echo
    local choice
    while true; do
        if ! read -r -p "👉 Enter the number or exact username (0 to cancel): " choice; then
            echo
            SELECTED_USER=""
            return
        fi
        choice=$(echo "$choice" | xargs 2>/dev/null || echo "$choice")
        if [[ -z "$choice" || "$choice" == "0" || "${choice,,}" == "cancel" || "${choice,,}" == "q" ]]; then
            SELECTED_USER=""
            return
        fi

        if [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -ge 1 ] && [ "$choice" -le "${#users[@]}" ]; then
            SELECTED_USER="${users[$((choice-1))]}"
            return
        else
            # Exact username lookup
            local matched=""
            for u in "${all_users[@]}"; do
                if [[ "$u" == "$choice" ]]; then
                    matched="$u"
                    break
                fi
            done
            if [[ -n "$matched" ]]; then
                SELECTED_USER="$matched"
                return
            else
                echo -e "${C_RED}❌ Invalid selection. Please try again or enter 0 to cancel.${C_RESET}"
            fi
        fi
    done
}

_select_multi_user_interface() {
    local title="$1"
    local include_orphan_users="${2:-false}"
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}${title}${C_RESET}\n"
    SELECTED_USERS=()
    local -a all_users=()
    local -a orphan_users=()
    local -A all_user_lookup=()
    local -A orphan_user_lookup=()
    local username

    if [[ -s $DB_FILE ]]; then
        mapfile -t all_users < <(cut -d: -f1 "$DB_FILE" | sort)
    fi

    if [[ "$include_orphan_users" == "true" ]]; then
        mapfile -t orphan_users < <(get_firewallfalcon_orphan_users)
        for username in "${orphan_users[@]}"; do
            orphan_user_lookup["$username"]=1
            if ! printf "%s\n" "${all_users[@]}" | grep -Fxq "$username"; then
                all_users+=("$username")
            fi
        done
        if [[ ${#all_users[@]} -gt 0 ]]; then
            mapfile -t all_users < <(printf "%s\n" "${all_users[@]}" | sort)
        fi
    fi

    if [[ ${#all_users[@]} -eq 0 ]]; then
        echo -e "${C_YELLOW}ℹ️ No users found in the manager database.${C_RESET}"
        if [[ "$include_orphan_users" == "true" ]]; then
            echo -e "${C_DIM}No orphan DAHOOM system users were found either.${C_RESET}"
        fi
        SELECTED_USERS=("NO_USERS"); return
    fi

    for username in "${all_users[@]}"; do
        all_user_lookup["$username"]=1
    done
    
    if [ ${#all_users[@]} -ge 15 ]; then
        read -p "👉 Enter a search term (or press Enter to list all): " search_term
        if [[ -n "$search_term" ]]; then
            mapfile -t users < <(printf "%s\n" "${all_users[@]}" | grep -i "$search_term")
        else
            users=("${all_users[@]}")
        fi
    else
        users=("${all_users[@]}")
    fi

    if [ ${#users[@]} -eq 0 ]; then
        echo -e "\n${C_YELLOW}ℹ️ No users found matching your criteria.${C_RESET}"
        SELECTED_USERS=("NO_USERS"); return
    fi
    echo -e "\nPlease select users:\n"
    for i in "${!users[@]}"; do
        local display_user="${users[$i]}"
        if [[ "$include_orphan_users" == "true" && -n "${orphan_user_lookup[${users[$i]}]+x}" ]]; then
            display_user="${display_user} ${C_DIM}(system-only)${C_RESET}"
        fi
        printf "  ${C_GREEN}[%2d]${C_RESET} %s\n" "$((i+1))" "$display_user"
    done
    echo -e "\n  ${C_GREEN}[all]${C_RESET} Select ALL listed users"
    echo -e "  ${C_RED}  [0]${C_RESET} ↩️ Cancel and return to main menu"
    echo -e "\n${C_CYAN}💡 You can select multiple by number, range, or exact username.${C_RESET}"
    echo -e "${C_CYAN}   Examples: '1 3 5' or '1,3' or '1-4' or 'alice bob'${C_RESET}"
    if [[ "$include_orphan_users" == "true" ]]; then
        echo -e "${C_CYAN}   Users marked '(system-only)' are old accounts still on the VPS but missing from users.db${C_RESET}"
    fi
    echo
    local choice
    while true; do
        if ! read -r -p "👉 Enter user numbers or usernames: " choice; then
            echo
            SELECTED_USERS=()
            return
        fi
        choice=${choice//,/ } # Replace commas with spaces
        
        if [[ -z "$choice" ]]; then
            echo -e "${C_RED}❌ Invalid selection. Please try again.${C_RESET}"
            continue
        fi

        if [[ "$choice" == "0" ]]; then
            SELECTED_USERS=(); return
        fi
        
        if [[ "${choice,,}" == "all" ]]; then
            SELECTED_USERS=("${users[@]}")
            return
        fi
        
        local valid=true
        local selected_indices=()
        local selected_names=()
        for token in $choice; do
            if [[ "$token" =~ ^[0-9]+-[0-9]+$ ]]; then
                local start=${token%-*}
                local end=${token#*-}
                if [ "$start" -le "$end" ]; then
                    for (( idx=start; idx<=end; idx++ )); do
                        if [ "$idx" -ge 1 ] && [ "$idx" -le "${#users[@]}" ]; then
                            selected_indices+=($idx)
                        else
                            valid=false; break
                        fi
                    done
                else
                    valid=false; break
                fi
            elif [[ "$token" =~ ^[0-9]+$ ]]; then
                if [ "$token" -ge 1 ] && [ "$token" -le "${#users[@]}" ]; then
                    selected_indices+=($token)
                else
                    # Check if numeric token is an exact username
                    local matched_num=""
                    for u in "${all_users[@]}"; do
                        if [[ "$u" == "$token" ]]; then matched_num="$u"; break; fi
                    done
                    if [[ -n "$matched_num" ]]; then
                        selected_names+=("$matched_num")
                    else
                        valid=false; break
                    fi
                fi
            else
                local matched_name=""
                for u in "${all_users[@]}"; do
                    if [[ "$u" == "$token" ]]; then matched_name="$u"; break; fi
                done
                if [[ -n "$matched_name" ]]; then
                    selected_names+=("$matched_name")
                else
                    valid=false; break
                fi
            fi
        done
        
        if [[ "$valid" == true && ( ${#selected_indices[@]} -gt 0 || ${#selected_names[@]} -gt 0 ) ]]; then
            mapfile -t unique_indices < <(printf "%s\n" "${selected_indices[@]}" | sort -u -n)
            for idx in "${unique_indices[@]}"; do
                SELECTED_USERS+=("${users[$((idx-1))]}")
            done
            if (( ${#selected_names[@]} > 0 )); then
                mapfile -t unique_names < <(printf "%s\n" "${selected_names[@]}" | sort -u)
                for username in "${unique_names[@]}"; do
                    if [[ -n "$username" ]] && ! printf "%s\n" "${SELECTED_USERS[@]}" | grep -Fxq "$username"; then
                        SELECTED_USERS+=("$username")
                    fi
                done
            fi
            return
        else
            echo -e "${C_RED}❌ Invalid selection. Please check your numbers or usernames.${C_RESET}"
            SELECTED_USERS=()
            selected_indices=()
            selected_names=()
        fi
    done
}

get_user_status() {
    local username="$1"
    if ! id "$username" &>/dev/null; then echo -e "${C_RED}Not Found${C_RESET}"; return; fi
    local expiry_date=$(grep "^$username:" "$DB_FILE" | cut -d: -f3)
    if passwd -S "$username" 2>/dev/null | grep -q " L "; then echo -e "${C_YELLOW}🔒 Locked${C_RESET}"; return; fi
    local expiry_ts=$(date -d "$expiry_date" +%s 2>/dev/null || echo 0)
    local current_ts=$(date +%s)
    if [[ $expiry_ts -lt $current_ts ]]; then echo -e "${C_RED}🗓️ Expired${C_RESET}"; return; fi
    echo -e "${C_GREEN}🟢 Active${C_RESET}"
}

create_user() {
    clear; show_banner
    echo
    menu_section "CREATE SSH USER" "$C_TITLE"
    echo
    echo -e "  ${C_CYAN}Login Method:${C_RESET}"
    echo -e "  ${C_GREEN}[1]${C_RESET} Username & Password ${C_DIM}(default)${C_RESET}"
    echo -e "  ${C_GREEN}[2]${C_RESET} Device ID ${C_DIM}(HWID — same value used as username & password, like HTTP Custom)${C_RESET}"
    read -p "$(echo -e "${C_BLUE}👉 Select method [1]: ${C_RESET}")" login_method
    login_method=${login_method:-1}
    local login_mode="normal"
    [[ "$login_method" == "2" ]] && login_mode="hwid"

    local username="" adopt_existing=false
    if [[ "$login_mode" == "hwid" ]]; then
        while true; do
            read -p "$(echo -e "${C_BLUE}👉 Device ID / HWID (Enter or 0 to cancel): ${C_RESET}")" hwid_in
            if [[ -z "$hwid_in" || "$hwid_in" == "0" || "${hwid_in,,}" == "cancel" ]]; then
                echo -e "\n${C_YELLOW}↩️ Creation cancelled.${C_RESET}"
                return
            fi
            username=$(_fm_validate_hwid "$hwid_in")
            if [[ -z "$username" ]]; then
                echo -e "${C_RED}❌ Invalid device ID — no spaces, ':' or '/', max 128 characters. Try again.${C_RESET}"
                continue
            fi
            break
        done
        if db_has_user "$username"; then
            echo -e "\n${C_RED}❌ Error: This device ID is already registered.${C_RESET}"
            return
        fi
        if id "$username" &>/dev/null; then
            echo -e "\n${C_RED}❌ Error: A system account already matches this device ID.${C_RESET}"
            return
        fi
    else
        read -p "$(echo -e "${C_BLUE}👉 Username (Enter or 0 to cancel): ${C_RESET}")" username
        username=$(echo "$username" | xargs 2>/dev/null || echo "$username")
        if [[ -z "$username" || "$username" == "0" || "${username,,}" == "cancel" || "${username,,}" == "q" ]]; then
            echo -e "\n${C_YELLOW}↩️ Creation cancelled.${C_RESET}"
            return
        fi
        if db_has_user "$username"; then
            echo -e "\n${C_RED}❌ Error: User '$username' already exists in database.${C_RESET}"
            return
        fi
        if id "$username" &>/dev/null; then
            if is_firewallfalcon_orphan_user "$username"; then
                echo -e "\n${C_YELLOW}⚠️ User '$username' exists on system (orphan account).${C_RESET}"
                read -p "$(echo -e "${C_BLUE}👉 Adopt and manage this user? (y/n) [y]: ${C_RESET}")" adopt_confirm
                adopt_confirm=${adopt_confirm:-y}
                if [[ "$adopt_confirm" == "y" || "$adopt_confirm" == "Y" ]]; then
                    adopt_existing=true
                else
                    echo -e "\n${C_YELLOW}❌ Creation cancelled.${C_RESET}"
                    return
                fi
            else
                echo -e "\n${C_RED}❌ Error: System user '$username' exists and is not a managed SSH account.${C_RESET}"
                return
            fi
        fi
    fi

    local password=""
    if [[ "$login_mode" == "hwid" ]]; then
        password="$username"
        echo -e "   ${C_GREEN}🔑 Login credential (device ID, used as both user & pass): ${C_YELLOW}$password${C_RESET}"
    else
        while true; do
            read -p "$(echo -e "${C_BLUE}👉 Password (Enter = auto-generate): ${C_RESET}")" password
            if [[ -z "$password" ]]; then
                password=$(tr -dc 'A-Za-z0-9' < /dev/urandom | head -c 8)
                echo -e "   ${C_GREEN}🔑 Auto Password: ${C_YELLOW}$password${C_RESET}"
                break
            else
                check_password_strength "$password"
                break
            fi
        done
    fi

    read -p "$(echo -e "${C_BLUE}👉 Duration in days (or 'never') [30]: ${C_RESET}")" days
    local expire_date
    if [[ "${days,,}" == "never" || "$days" == "0" ]]; then
        expire_date="Never"
    else
        days=${days:-30}
        if ! [[ "$days" =~ ^[0-9]+$ ]]; then echo -e "\n${C_RED}❌ Invalid duration number.${C_RESET}"; return; fi
        expire_date=$(date -d "+$days days" +%Y-%m-%d)
    fi

    read -p "$(echo -e "${C_BLUE}👉 Simultaneous Connections [1]: ${C_RESET}")" limit
    limit=${limit:-1}
    if ! [[ "$limit" =~ ^[0-9]+$ ]]; then echo -e "\n${C_RED}❌ Invalid limit number.${C_RESET}"; return; fi

    read -p "$(echo -e "${C_BLUE}👉 Total Bandwidth GB (0 = unlimited) [0]: ${C_RESET}")" bandwidth_gb
    bandwidth_gb=${bandwidth_gb:-0}
    if ! [[ "$bandwidth_gb" =~ ^[0-9]+\.?[0-9]*$ ]]; then echo -e "\n${C_RED}❌ Invalid bandwidth number.${C_RESET}"; return; fi

    read -p "$(echo -e "${C_BLUE}👉 Daily Bandwidth GB (0 = unlimited) [0]: ${C_RESET}")" daily_bandwidth_gb
    daily_bandwidth_gb=${daily_bandwidth_gb:-0}
    if ! [[ "$daily_bandwidth_gb" =~ ^[0-9]+\.?[0-9]*$ ]]; then echo -e "\n${C_RED}❌ Invalid daily bandwidth number.${C_RESET}"; return; fi

    local bw_display="Unlimited"
    if [[ "$bandwidth_gb" != "0" ]]; then bw_display="${bandwidth_gb} GB"; fi
    local daily_bw_display="Unlimited"
    if [[ "$daily_bandwidth_gb" != "0" ]]; then daily_bw_display="${daily_bandwidth_gb} GB/day"; fi

    echo
    echo -e "  ${C_CYAN}┌── Account Summary ─────────────────────────┐${C_RESET}"
    if [[ "$login_mode" == "hwid" ]]; then
        echo -e "  ${C_CYAN}│${C_RESET}  Device ID : ${C_YELLOW}$username${C_RESET} ${C_DIM}(HWID)${C_RESET}"
    else
        echo -e "  ${C_CYAN}│${C_RESET}  Username  : ${C_YELLOW}$username${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Password  : ${C_YELLOW}$password${C_RESET}"
    fi
    echo -e "  ${C_CYAN}│${C_RESET}  Expires   : ${C_YELLOW}$expire_date${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Sessions  : ${C_YELLOW}$limit${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Total BW  : ${C_YELLOW}$bw_display${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Daily BW  : ${C_YELLOW}$daily_bw_display${C_RESET}"
    echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"
    echo
    echo -e "  ${C_GREEN}[1]${C_RESET} Create user now"
    echo -e "  ${C_RED}[0]${C_RESET} Cancel"
    echo
    read -p "$(echo -e "${C_BLUE}👉 Select option [1]: ${C_RESET}")" confirm_create
    confirm_create=${confirm_create:-1}
    if [[ "$confirm_create" != "1" ]]; then
        echo -e "\n${C_YELLOW}❌ Creation cancelled.${C_RESET}"
        return
    fi

    ensure_firewallfalcon_system_group
    if [[ "$adopt_existing" == "true" ]]; then
        usermod -s /usr/sbin/nologin "$username" &>/dev/null
    else
        if ! _fm_create_system_user "$username"; then
            echo -e "\n${C_RED}❌ Failed to create the system account. Nothing was saved.${C_RESET}"
            return
        fi
    fi
    usermod -aG "$FF_USERS_GROUP" "$username" 2>/dev/null
    echo "$username:$password" | chpasswd
    [[ "$expire_date" != "Never" ]] && chage -E "$expire_date" "$username"
    echo "$username:$password:$expire_date:$limit:$bandwidth_gb:$daily_bandwidth_gb:trial" >> "$DB_FILE"
    _fm_set_login_mode "$username" "$login_mode"
    _log_action "CREATE" "$username" "exp=$expire_date conn=$limit bw=$bw_display"
    send_telegram_msg "👤 <b>New User Created</b>%0AUser: <b>$username</b>%0APassword: <b>$password</b>%0AExpires: $expire_date%0ALimit: $limit"

    clear; show_banner
    echo
    if [[ "$adopt_existing" == "true" ]]; then
        echo -e "${C_GREEN}✅ Existing user '$username' imported successfully!${C_RESET}\n"
    else
        echo -e "${C_GREEN}✅ User '$username' created successfully!${C_RESET}\n"
    fi
    echo -e "  ${C_CYAN}┌── Created Account ─────────────────────────┐${C_RESET}"
    if [[ "$login_mode" == "hwid" ]]; then
        echo -e "  ${C_CYAN}│${C_RESET}  Device ID : ${C_YELLOW}$username${C_RESET} ${C_DIM}(HWID)${C_RESET}"
    else
        echo -e "  ${C_CYAN}│${C_RESET}  Username  : ${C_YELLOW}$username${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Password  : ${C_YELLOW}$password${C_RESET}"
    fi
    echo -e "  ${C_CYAN}│${C_RESET}  Expires   : ${C_YELLOW}$expire_date${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Sessions  : ${C_YELLOW}$limit${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Total BW  : ${C_YELLOW}$bw_display${C_RESET}"
    echo -e "  ${C_CYAN}│${C_RESET}  Daily BW  : ${C_YELLOW}$daily_bw_display${C_RESET}"
    echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"

    local bw_status_link
    bw_status_link=$(_fm_generate_bandwidth_link "$username" 2>/dev/null)
    if [[ -n "$bw_status_link" ]]; then
        echo -e "  ${C_CYAN}📊 Usage Link:${C_RESET} ${C_YELLOW}${bw_status_link}${C_RESET}"
        echo -e "  ${C_DIM}   Share this with the client so they can check their own usage.${C_RESET}"
    fi
    echo
    read -p "$(echo -e "${C_BLUE}👉 Generate client config for this user? (y/n) [n]: ${C_RESET}")" gen_conf
    if [[ "$gen_conf" == "y" || "$gen_conf" == "Y" ]]; then
        generate_client_config "$username" "$password"
    fi

    invalidate_banner_cache
    refresh_dynamic_banner_routing_if_enabled
}

delete_user() {
    clear; show_banner
    echo
    menu_section "DELETE SSH USERS" "$C_TITLE"
    echo
    _select_multi_user_interface "Select User(s) to Delete" "true"
    if [[ ${#SELECTED_USERS[@]} -eq 0 || "${SELECTED_USERS[0]}" == "NO_USERS" ]]; then return; fi
    
    echo
    echo -e "  ${C_CYAN}┌── Selected Users ──────────────────────────┐${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        local line; line=$(grep "^$u:" "$DB_FILE" 2>/dev/null)
        if [[ -n "$line" ]]; then
            local _u2 _p2 expiry2 limit2 bw2
            IFS=: read -r _u2 _p2 expiry2 limit2 bw2 _ <<< "$line"
            echo -e "  ${C_CYAN}│${C_RESET}  ${C_YELLOW}$u${C_RESET} — Exp: ${C_RED}$expiry2${C_RESET} | Conn: ${C_CYAN}$limit2${C_RESET} | BW: ${C_ORANGE}${bw2:-0}GB${C_RESET}"
        else
            echo -e "  ${C_CYAN}│${C_RESET}  ${C_YELLOW}$u${C_RESET} ${C_DIM}(not in DB)${C_RESET}"
        fi
    done
    echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"
    echo
    echo -e "  ${C_GREEN}[1]${C_RESET} Export log before deleting"
    echo -e "  ${C_GREEN}[2]${C_RESET} Delete directly without log"
    echo -e "  ${C_RED}[0]${C_RESET} Cancel"
    echo
    read -p "$(echo -e "${C_BLUE}👉 Select action [2]: ${C_RESET}")" do_export
    do_export=${do_export:-2}
    if [[ "$do_export" == "0" ]]; then echo -e "\n${C_YELLOW}❌ Deletion cancelled.${C_RESET}"; return; fi
    if [[ "$do_export" == "1" ]]; then
        local export_file="/root/ff_deleted_$(date +%F).log"
        for u in "${SELECTED_USERS[@]}"; do
            grep "^$u:" "$DB_FILE" 2>/dev/null >> "$export_file"
        done
        echo -e "  ${C_GREEN}✅ Log saved: ${C_YELLOW}$export_file${C_RESET}"
    fi

    echo -e "\n${C_BLUE}🗑️ Deleting selected user(s)...${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        _log_action "DELETE" "$u" "by_admin"
        send_telegram_msg "🗑️ <b>User Deleted</b>%0AUser: <b>$u</b>"
    done
    delete_firewallfalcon_user_accounts "${SELECTED_USERS[@]}"
}

edit_user() {
    clear; show_banner
    echo
    menu_section "EDIT USER ACCOUNT" "$C_TITLE"
    echo
    _select_user_interface "Select User to Edit"
    local username=$SELECTED_USER
    if [[ "$username" == "NO_USERS" ]] || [[ -z "$username" ]]; then return; fi

    while true; do
        clear; show_banner
        echo
        menu_section "EDIT USER: $username" "$C_TITLE"
        
        local current_line; current_line=$(grep "^$username:" "$DB_FILE")
        local cur_pass cur_expiry cur_limit cur_bw cur_daily_bw
        IFS=: read -r _ cur_pass cur_expiry cur_limit cur_bw cur_daily_bw _ <<< "$current_line"
        [[ -z "$cur_bw" ]] && cur_bw="0"
        [[ ! "$cur_daily_bw" =~ ^[0-9]+\.?[0-9]*$ ]] && cur_daily_bw="0"
        local login_mode; login_mode=$(_fm_get_login_mode "$username")
        
        local cur_bw_display="Unlimited"; [[ "$cur_bw" != "0" ]] && cur_bw_display="${cur_bw} GB"
        local cur_daily_bw_display="Unlimited"; [[ "$cur_daily_bw" != "0" ]] && cur_daily_bw_display="${cur_daily_bw} GB/day"
        
        local bw_used_display="0.00 GB"
        if [[ -f "$BANDWIDTH_DIR/${username}.usage" ]]; then
            local used_bytes=0; read -r used_bytes < "$BANDWIDTH_DIR/${username}.usage" 2>/dev/null || used_bytes=0
            [[ -n "$used_bytes" && "$used_bytes" != "0" ]] && bw_used_display=$(awk "BEGIN {printf \"%.2f GB\", $used_bytes / 1073741824}")
        fi
        
        local daily_bw_used_display="0.00 GB"
        if [[ -f "$BANDWIDTH_DIR/${username}.daily_usage" ]]; then
            local d_used_bytes=0; read -r d_used_bytes < "$BANDWIDTH_DIR/${username}.daily_usage" 2>/dev/null || d_used_bytes=0
            [[ -n "$d_used_bytes" && "$d_used_bytes" != "0" ]] && daily_bw_used_display=$(awk "BEGIN {printf \"%.2f GB\", $d_used_bytes / 1073741824}")
        fi

        echo
        echo -e "  ${C_CYAN}┌── Account Settings ────────────────────────┐${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Password  : ${C_YELLOW}$cur_pass${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Expires   : ${C_YELLOW}$cur_expiry${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Sessions  : ${C_YELLOW}$cur_limit${C_RESET}"
        echo -e "  ${C_CYAN}│${C_RESET}  Total BW  : ${C_YELLOW}$cur_bw_display${C_RESET} (${C_CYAN}Used: $bw_used_display${C_RESET})"
        echo -e "  ${C_CYAN}│${C_RESET}  Daily BW  : ${C_YELLOW}$cur_daily_bw_display${C_RESET} (${C_CYAN}Used: $daily_bw_used_display${C_RESET})"
        echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %-28s ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Change Password" "[2]" "Change Expiry Date"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-28s ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Change Connection Limit" "[4]" "Change Total Bandwidth"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-28s ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Change Daily Bandwidth" "[6]" "Reset Bandwidth Counters"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "Copy Settings to User"
        if [[ "$login_mode" == "hwid" ]]; then
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[8]" "Change Device ID (HWID) — device updated, keep all data"
        fi
        echo
        printf "  ${C_WARN}%-4s${C_RESET} %s\n" "[0]" "Finish Editing"
        echo
        if ! read -r -p "$(echo -e "${C_BLUE}👉 Select detail to edit: ${C_RESET}")" edit_choice; then
            return
        fi
        case $edit_choice in
            1)
               local new_pass=""
               read -p "👉 Enter new password (Enter = auto-generate): " new_pass
               if [[ -z "$new_pass" ]]; then
                   new_pass=$(tr -dc 'A-Za-z0-9' < /dev/urandom | head -c 8)
                   echo -e "   ${C_GREEN}🔑 Auto Password: ${C_YELLOW}$new_pass${C_RESET}"
               else
                   check_password_strength "$new_pass"
               fi
               echo "$username:$new_pass" | chpasswd
               sed -i "s/^$username:.*/$username:$new_pass:$cur_expiry:$cur_limit:$cur_bw:$cur_daily_bw/" "$DB_FILE"
               echo -e "\n${C_GREEN}✅ Password changed to: ${C_YELLOW}$new_pass${C_RESET}"
               ;;
            2) read -p "👉 Days to add: " days
               if [[ "$days" =~ ^[0-9]+$ ]]; then
                   echo -e "  ${C_GREEN}[1]${C_RESET} Extend from Today  ${C_GREEN}[2]${C_RESET} Extend from Current Expiry"
                   read -p "👉 Mode [1]: " ext_mode
                   local new_expire_date
                   if [[ "${ext_mode}" == "2" && -n "$cur_expiry" && "$cur_expiry" != "Never" ]]; then
                       new_expire_date=$(date -d "$cur_expiry +$days days" +%Y-%m-%d 2>/dev/null || date -d "+$days days" +%Y-%m-%d)
                   else
                       new_expire_date=$(date -d "+$days days" +%Y-%m-%d)
                   fi
                   chage -E "$new_expire_date" "$username"
                   sed -i "s/^$username:.*/$username:$cur_pass:$new_expire_date:$cur_limit:$cur_bw:$cur_daily_bw/" "$DB_FILE"
                   echo -e "\n${C_GREEN}✅ Expiration: ${C_DIM}$cur_expiry${C_RESET} → ${C_GREEN}$new_expire_date${C_RESET}"
               else echo -e "\n${C_RED}❌ Invalid number of days.${C_RESET}"; fi ;;
            3) read -p "👉 New simultaneous connection limit: " new_limit
               if [[ "$new_limit" =~ ^[0-9]+$ ]]; then
                   sed -i "s/^$username:.*/$username:$cur_pass:$cur_expiry:$new_limit:$cur_bw:$cur_daily_bw/" "$DB_FILE"
                   echo -e "\n${C_GREEN}✅ Connection limit set to: ${C_YELLOW}$new_limit${C_RESET}"
               else echo -e "\n${C_RED}❌ Invalid limit.${C_RESET}"; fi ;;
            4) read -p "👉 New TOTAL bandwidth limit in GB (0 = unlimited): " new_bw
               if [[ "$new_bw" =~ ^[0-9]+\.?[0-9]*$ ]]; then
                   sed -i "s/^$username:.*/$username:$cur_pass:$cur_expiry:$cur_limit:$new_bw:$cur_daily_bw/" "$DB_FILE"
                   local bw_msg="Unlimited"; [[ "$new_bw" != "0" ]] && bw_msg="${new_bw} GB"
                   echo -e "\n${C_GREEN}✅ Total bandwidth limit set to: ${C_YELLOW}$bw_msg${C_RESET}"
                   if [[ "$new_bw" == "0" ]] || [[ -f "$BANDWIDTH_DIR/${username}.usage" ]]; then
                       local used_bytes; used_bytes=$(cat "$BANDWIDTH_DIR/${username}.usage" 2>/dev/null || echo 0)
                       local new_quota_bytes; new_quota_bytes=$(awk "BEGIN {printf \"%.0f\", $new_bw * 1073741824}")
                       if [[ "$new_bw" == "0" ]] || [[ "$used_bytes" -lt "$new_quota_bytes" ]]; then
                           usermod -U "$username" &>/dev/null
                       fi
                   fi
               else echo -e "\n${C_RED}❌ Invalid bandwidth value.${C_RESET}"; fi ;;
            5) read -p "👉 New DAILY bandwidth limit in GB (0 = unlimited): " new_daily_bw
               if [[ "$new_daily_bw" =~ ^[0-9]+\.?[0-9]*$ ]]; then
                   sed -i "s/^$username:.*/$username:$cur_pass:$cur_expiry:$cur_limit:$cur_bw:$new_daily_bw/" "$DB_FILE"
                   local daily_bw_msg="Unlimited"; [[ "$new_daily_bw" != "0" ]] && daily_bw_msg="${new_daily_bw} GB/day"
                   echo -e "\n${C_GREEN}✅ Daily bandwidth limit set to: ${C_YELLOW}$daily_bw_msg${C_RESET}"
                   if [[ "$new_daily_bw" == "0" ]] || [[ -f "$BANDWIDTH_DIR/${username}.daily_usage" ]]; then
                       local d_used_bytes; d_used_bytes=$(cat "$BANDWIDTH_DIR/${username}.daily_usage" 2>/dev/null || echo 0)
                       local new_d_quota_bytes; new_d_quota_bytes=$(awk "BEGIN {printf \"%.0f\", $new_daily_bw * 1073741824}")
                       if [[ "$new_daily_bw" == "0" ]] || [[ "$d_used_bytes" -lt "$new_d_quota_bytes" ]]; then
                           usermod -U "$username" &>/dev/null
                           rm -f "$BANDWIDTH_DIR/${username}.daily_locked"
                       fi
                   fi
               else echo -e "\n${C_RED}❌ Invalid bandwidth value.${C_RESET}"; fi ;;
            6)
               echo "0" > "$BANDWIDTH_DIR/${username}.usage"
               echo "0" > "$BANDWIDTH_DIR/${username}.daily_usage"
               rm -f "$BANDWIDTH_DIR/${username}.daily_locked"
               usermod -U "$username" &>/dev/null
               echo -e "\n${C_GREEN}✅ Bandwidth counters reset to 0.${C_RESET}"
               ;;
            7)
               read -p "👉 Enter target username to copy settings to: " copy_target
               if grep -q "^$copy_target:" "$DB_FILE" 2>/dev/null; then
                   local ct_pass; ct_pass=$(grep "^$copy_target:" "$DB_FILE" | cut -d: -f2)
                   sed -i "s/^$copy_target:.*/$copy_target:$ct_pass:$cur_expiry:$cur_limit:$cur_bw:$cur_daily_bw/" "$DB_FILE"
                   chage -E "$cur_expiry" "$copy_target" 2>/dev/null
                   echo -e "\n${C_GREEN}✅ Settings copied from ${C_YELLOW}$username${C_RESET}${C_GREEN} to ${C_YELLOW}$copy_target${C_RESET}"
               else
                   echo -e "\n${C_RED}❌ User '$copy_target' not found.${C_RESET}"
               fi
               ;;
            8)
               if [[ "$login_mode" != "hwid" ]]; then
                   echo -e "\n${C_RED}❌ Invalid option.${C_RESET}"
               else
                   local new_hwid_in new_hwid=""
                   while true; do
                       read -p "👉 New Device ID / HWID (Enter or 0 to cancel): " new_hwid_in
                       if [[ -z "$new_hwid_in" || "$new_hwid_in" == "0" || "${new_hwid_in,,}" == "cancel" ]]; then
                           break
                       fi
                       new_hwid=$(_fm_validate_hwid "$new_hwid_in")
                       if [[ -z "$new_hwid" ]]; then
                           echo -e "${C_RED}❌ Invalid device ID — no spaces, ':' or '/', max 128 characters. Try again.${C_RESET}"
                           continue
                       fi
                       if [[ "$new_hwid" == "$username" ]]; then
                           echo -e "${C_RED}❌ That's the current device ID.${C_RESET}"
                           new_hwid=""
                           continue
                       fi
                       if db_has_user "$new_hwid" || id "$new_hwid" &>/dev/null; then
                           echo -e "${C_RED}❌ This device ID is already registered.${C_RESET}"
                           new_hwid=""
                           continue
                       fi
                       break
                   done
                   if [[ -n "$new_hwid" ]]; then
                       echo -e "\n${C_BLUE}⚙️ Renaming ${C_YELLOW}$username${C_RESET}${C_BLUE} → ${C_YELLOW}$new_hwid${C_RESET}${C_BLUE}, keeping expiry, bandwidth, and notes...${C_RESET}"
                       if _fm_rename_hwid_account "$username" "$new_hwid"; then
                           _log_action "EDIT" "$new_hwid" "hwid changed from $username"
                           send_telegram_msg "🆔 <b>Device ID Changed</b>%0AOld: <b>$username</b>%0ANew: <b>$new_hwid</b>"
                           echo -e "\n${C_GREEN}✅ Device ID updated. All data (expiry, bandwidth, notes) preserved.${C_RESET}"
                           echo -e "${C_DIM}   Note: any previously shared usage-status link contained the old ID and no longer works — issue a new one.${C_RESET}"
                           username="$new_hwid"
                       else
                           echo -e "\n${C_RED}❌ Failed to rename the account. Nothing was changed.${C_RESET}"
                       fi
                   else
                       echo -e "\n${C_YELLOW}↩️ Cancelled.${C_RESET}"
                   fi
               fi
               ;;
            0) return ;;
            *) echo -e "\n${C_RED}❌ Invalid option.${C_RESET}" ;;
        esac
        echo -e "\nPress ${C_YELLOW}[Enter]${C_RESET} to continue..." && read -r || return
    done
}

lock_user() {
    clear; show_banner
    echo
    menu_section "LOCK USER ACCOUNTS" "$C_TITLE"
    echo
    _select_multi_user_interface "Select User(s) to Lock"
    if [[ ${#SELECTED_USERS[@]} -eq 0 || "${SELECTED_USERS[0]}" == "NO_USERS" ]]; then return; fi
    
    refresh_ssh_session_cache
    echo
    echo -e "  ${C_CYAN}┌── Active Sessions ─────────────────────────┐${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        local online_count="${SSH_SESSION_COUNTS[$u]:-0}"
        echo -e "  ${C_CYAN}│${C_RESET}  ${C_YELLOW}$u${C_RESET}: $online_count session(s) active"
    done
    echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"
    echo
    echo -e "  ${C_GREEN}[1]${C_RESET} Permanent lock"
    echo -e "  ${C_GREEN}[2]${C_RESET} Timed lock (auto-unlock in minutes)"
    echo -e "  ${C_RED}[0]${C_RESET} Cancel"
    echo
    read -p "$(echo -e "${C_BLUE}👉 Select lock type [1]: ${C_RESET}")" lock_type
    lock_type=${lock_type:-1}
    if [[ "$lock_type" == "0" ]]; then echo -e "\n${C_YELLOW}❌ Lock cancelled.${C_RESET}"; return; fi

    local lock_mins=0
    if [[ "$lock_type" == "2" ]]; then
        read -p "👉 Auto-unlock duration in minutes [60]: " lock_mins
        lock_mins=${lock_mins:-60}
    fi

    echo -e "\n${C_BLUE}🔒 Locking selected user(s)...${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        if ! id "$u" &>/dev/null; then
             echo -e " ❌ User '${C_YELLOW}$u${C_RESET}' does not exist."
             continue
        fi
        
        usermod -L "$u"
        if [ $? -eq 0 ]; then
            _fm_kill_user_sessions "$u"
            echo -e " ✅ ${C_YELLOW}$u${C_RESET} locked and sessions terminated."
            _log_action "LOCK" "$u" "timed=${lock_mins}min"
            if [[ "$lock_mins" =~ ^[0-9]+$ && "$lock_mins" -gt 0 ]]; then
                echo "usermod -U $u" | at now + ${lock_mins} minutes &>/dev/null
                echo -e "   ${C_DIM}⏰ Auto-unlock scheduled in ${lock_mins} minutes${C_RESET}"
            fi
        else
            echo -e " ❌ Failed to lock ${C_YELLOW}$u${C_RESET}."
        fi
    done
}

unlock_user() {
    clear; show_banner
    echo
    menu_section "UNLOCK USER ACCOUNTS" "$C_TITLE"
    echo
    _select_multi_user_interface "Select User(s) to Unlock"
    if [[ ${#SELECTED_USERS[@]} -eq 0 || "${SELECTED_USERS[0]}" == "NO_USERS" ]]; then return; fi
    
    echo
    echo -e "  ${C_CYAN}┌── Lock Reason Analysis ────────────────────┐${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        local reason="Manual"
        local line; line=$(grep "^$u:" "$DB_FILE" 2>/dev/null)
        if [[ -n "$line" ]]; then
            local _u _p exp lim bw dbw _extra
            IFS=: read -r _u _p exp lim bw dbw _extra <<< "$line"
            if [[ -n "$exp" && "$exp" != "Never" ]]; then
                local exp_ts; exp_ts=$(date -d "$exp" +%s 2>/dev/null || echo 0)
                local now_ts; now_ts=$(date +%s)
                if (( exp_ts > 0 && exp_ts < now_ts )); then reason="Expired on $exp"; fi
            fi
            if [[ -f "$BANDWIDTH_DIR/${u}.usage" && -n "$bw" && "$bw" != "0" ]]; then
                local used=0; read -r used < "$BANDWIDTH_DIR/${u}.usage" 2>/dev/null || used=0
                local limit_bytes; limit_bytes=$(awk "BEGIN {printf \"%.0f\", $bw * 1073741824}" 2>/dev/null || echo 0)
                if [[ "$limit_bytes" != "0" && "$used" -ge "$limit_bytes" ]]; then reason="Total BW Exceeded"; fi
            fi
            if [[ -f "$BANDWIDTH_DIR/${u}.daily_usage" && -n "$dbw" && "$dbw" != "0" ]]; then
                local dused=0; read -r dused < "$BANDWIDTH_DIR/${u}.daily_usage" 2>/dev/null || dused=0
                local dlimit_bytes; dlimit_bytes=$(awk "BEGIN {printf \"%.0f\", $dbw * 1073741824}" 2>/dev/null || echo 0)
                if [[ "$dlimit_bytes" != "0" && "$dused" -ge "$dlimit_bytes" ]]; then reason="Daily BW Exceeded"; fi
            fi
        fi
        echo -e "  ${C_CYAN}│${C_RESET}  ${C_YELLOW}$u${C_RESET}: $reason"
    done
    echo -e "  ${C_CYAN}└────────────────────────────────────────────┘${C_RESET}"
    echo
    echo -e "  ${C_GREEN}[1]${C_RESET} Unlock user(s) & reset bandwidth counters"
    echo -e "  ${C_GREEN}[2]${C_RESET} Unlock user(s) only"
    echo -e "  ${C_RED}[0]${C_RESET} Cancel"
    echo
    read -p "$(echo -e "${C_BLUE}👉 Select action [1]: ${C_RESET}")" unlock_action
    unlock_action=${unlock_action:-1}
    if [[ "$unlock_action" == "0" ]]; then echo -e "\n${C_YELLOW}❌ Unlock cancelled.${C_RESET}"; return; fi

    local reset_bw=false
    [[ "$unlock_action" == "1" ]] && reset_bw=true

    echo -e "\n${C_BLUE}🔓 Unlocking selected user(s)...${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        if ! id "$u" &>/dev/null; then
             echo -e " ❌ User '${C_YELLOW}$u${C_RESET}' does not exist."
             continue
        fi
        
        usermod -U "$u"
        if [ $? -eq 0 ]; then
            echo -e " ✅ ${C_YELLOW}$u${C_RESET} unlocked."
            _log_action "UNLOCK" "$u" "bw_reset=$reset_bw"
            if $reset_bw; then
                echo "0" > "$BANDWIDTH_DIR/${u}.usage" 2>/dev/null
                echo "0" > "$BANDWIDTH_DIR/${u}.daily_usage" 2>/dev/null
                rm -f "$BANDWIDTH_DIR/${u}.daily_locked" 2>/dev/null
                echo -e "   ${C_DIM}📦 Bandwidth counters reset to 0${C_RESET}"
            fi
        else
            echo -e " ❌ Failed to unlock ${C_YELLOW}$u${C_RESET}."
        fi
    done
}

list_users() {
    clear; show_banner
    echo
    menu_section "MANAGED USERS LIST" "$C_TITLE"
    echo
    if [[ ! -s "$DB_FILE" ]]; then
        echo -e "  ${C_YELLOW}ℹ️ No users are currently being managed.${C_RESET}\n"
        return
    fi
    echo -e "  ${C_CYAN}---------------------------------------------------------------------------------------------------${C_RESET}"
    printf "  ${C_BOLD}${C_WHITE}%-18s | %-12s | %-10s | %-25s | %-20s${C_RESET}\n" "USERNAME" "EXPIRATION" "SESSIONS" "BANDWIDTH" "STATUS"
    echo -e "  ${C_CYAN}---------------------------------------------------------------------------------------------------${C_RESET}"

    local current_ts
    printf -v current_ts '%(%s)T' -1
    local -A system_user_lookup=()
    local -A locked_user_lookup=()

    while IFS=: read -r system_user _rest; do
        [[ -n "$system_user" ]] && system_user_lookup["$system_user"]=1
    done < /etc/passwd

    if [[ -r /etc/shadow ]]; then
        while IFS=: read -r shadow_user shadow_hash _rest; do
            [[ -n "$shadow_user" && "${shadow_hash:0:1}" == "!" ]] && locked_user_lookup["$shadow_user"]=1
        done < /etc/shadow
    else
        while read -r passwd_user _ passwd_status _rest; do
            [[ -z "$passwd_user" ]] && continue
            [[ "$passwd_status" == "L" ]] && locked_user_lookup["$passwd_user"]=1
        done < <(passwd -Sa 2>/dev/null)
    fi
    refresh_ssh_session_cache

    local total_u=0 active_u=0 locked_u=0 expired_u=0
    while IFS=: read -r user pass expiry limit bandwidth_gb daily_bandwidth_gb _extra; do
        total_u=$((total_u+1))
        local online_count="${SSH_SESSION_COUNTS[$user]:-0}"
        local connection_string="$online_count / $limit"
        local plain_status="Active"
        local status="${C_GREEN}Active${C_RESET}"
        local quota_exceeded=false

        [[ -z "$bandwidth_gb" ]] && bandwidth_gb="0"
        [[ ! "$daily_bandwidth_gb" =~ ^[0-9]+\.?[0-9]*$ ]] && daily_bandwidth_gb="0"
        
        local bw_string="Unlimited"
        local total_str=""
        local daily_str=""
        
        if [[ "$bandwidth_gb" != "0" ]]; then
            local used_bytes=0
            if [[ -f "$BANDWIDTH_DIR/${user}.usage" ]]; then
                read -r used_bytes < "$BANDWIDTH_DIR/${user}.usage" 2>/dev/null || used_bytes=0
                [[ "$used_bytes" =~ ^[0-9]+$ ]] || used_bytes=0
            fi
            local used_gb
            used_gb=$(awk "BEGIN {printf \"%.1f\", $used_bytes / 1073741824}")
            total_str="${used_gb}/${bandwidth_gb}G"
            local quota_bytes
            quota_bytes=$(awk "BEGIN {printf \"%.0f\", $bandwidth_gb * 1073741824}")
            if [[ "$quota_bytes" =~ ^[0-9]+$ ]] && (( used_bytes >= quota_bytes )); then
                quota_exceeded=true
            fi
        fi
        
        if [[ "$daily_bandwidth_gb" != "0" ]]; then
            local d_used_bytes=0
            if [[ -f "$BANDWIDTH_DIR/${user}.daily_usage" ]]; then
                read -r d_used_bytes < "$BANDWIDTH_DIR/${user}.daily_usage" 2>/dev/null || d_used_bytes=0
                [[ "$d_used_bytes" =~ ^[0-9]+$ ]] || d_used_bytes=0
            fi
            local d_used_gb
            d_used_gb=$(awk "BEGIN {printf \"%.1f\", $d_used_bytes / 1073741824}")
            daily_str="${d_used_gb}/${daily_bandwidth_gb}G/d"
            local d_quota_bytes
            d_quota_bytes=$(awk "BEGIN {printf \"%.0f\", $daily_bandwidth_gb * 1073741824}")
            if [[ "$d_quota_bytes" =~ ^[0-9]+$ ]] && (( d_used_bytes >= d_quota_bytes )); then
                quota_exceeded=true
            fi
        fi
        
        if [[ -n "$total_str" && -n "$daily_str" ]]; then
            bw_string="$total_str | $daily_str"
        elif [[ -n "$total_str" ]]; then
            bw_string="$total_str"
        elif [[ -n "$daily_str" ]]; then
            bw_string="$daily_str"
        fi

        if [[ -z "${system_user_lookup[$user]+x}" ]]; then
            plain_status="Not Found"
            status="${C_RED}Not Found${C_RESET}"
        elif [[ -n "$expiry" && "$expiry" != "Never" ]]; then
            local expiry_ts
            expiry_ts=$(date -d "$expiry" +%s 2>/dev/null || echo 0)
            if [[ "$expiry_ts" =~ ^[0-9]+$ ]] && (( expiry_ts > 0 && expiry_ts < current_ts )); then
                plain_status="Expired"
                status="${C_RED}Expired${C_RESET}"
                expired_u=$((expired_u+1))
            fi
        fi

        if [[ "$plain_status" == "Active" && "$quota_exceeded" == true ]]; then
            if [[ -n "${locked_user_lookup[$user]+x}" ]]; then
                plain_status="BW Locked"
                status="${C_RED}BW Locked${C_RESET}"
                locked_u=$((locked_u+1))
            else
                plain_status="Quota Exceeded"
                status="${C_RED}Quota Exceeded${C_RESET}"
            fi
        elif [[ "$plain_status" == "Active" && -n "${locked_user_lookup[$user]+x}" ]]; then
            plain_status="Locked"
            status="${C_YELLOW}Locked${C_RESET}"
            locked_u=$((locked_u+1))
        elif [[ "$plain_status" == "Active" ]]; then
            active_u=$((active_u+1))
        fi

        local line_color="$C_WHITE"
        case "$plain_status" in
            "Active") line_color="$C_GREEN" ;;
            "Locked") line_color="$C_YELLOW" ;;
            "Expired") line_color="$C_RED" ;;
            "BW Locked") line_color="$C_RED" ;;
            "Quota Exceeded") line_color="$C_RED" ;;
            "Not Found") line_color="$C_DIM" ;;
        esac

        printf "  ${line_color}%-18s ${C_RESET}| ${C_YELLOW}%-12s ${C_RESET}| ${C_CYAN}%-10s ${C_RESET}| ${C_ORANGE}%-25s ${C_RESET}| %-20s\n" "$user" "$expiry" "$connection_string" "$bw_string" "$status"
    done < <(sort "$DB_FILE")
    echo -e "  ${C_CYAN}---------------------------------------------------------------------------------------------------${C_RESET}"
    echo -e "  ${C_DIM}Total: ${C_WHITE}$total_u${C_RESET} ${C_DIM}| Active: ${C_GREEN}$active_u${C_RESET} ${C_DIM}| Locked: ${C_YELLOW}$locked_u${C_RESET} ${C_DIM}| Expired: ${C_RED}$expired_u${C_RESET}\n"
}

renew_user() {
    clear; show_banner
    echo
    menu_section "RENEW USER ACCOUNTS" "$C_TITLE"
    echo
    _select_multi_user_interface "Select User(s) to Renew"
    if [[ ${#SELECTED_USERS[@]} -eq 0 || "${SELECTED_USERS[0]}" == "NO_USERS" ]]; then return; fi
    
    read -p "👉 Days to extend [30]: " days
    days=${days:-30}
    if ! [[ "$days" =~ ^[0-9]+$ ]]; then echo -e "\n${C_RED}❌ Invalid number of days.${C_RESET}"; return; fi
    
    echo
    echo -e "  ${C_GREEN}[1]${C_RESET} Extend from Today"
    echo -e "  ${C_GREEN}[2]${C_RESET} Extend from Current Expiry"
    echo -e "  ${C_RED}[0]${C_RESET} Cancel"
    echo
    read -p "$(echo -e "${C_BLUE}👉 Select renewal mode [1]: ${C_RESET}")" renew_mode
    renew_mode=${renew_mode:-1}
    if [[ "$renew_mode" == "0" ]]; then echo -e "\n${C_YELLOW}❌ Renewal cancelled.${C_RESET}"; return; fi
    
    echo -e "\n${C_BLUE}🔄 Renewing selected user(s)...${C_RESET}"
    for u in "${SELECTED_USERS[@]}"; do
        local line pass _expiry limit bw daily_bw
        line=$(grep "^$u:" "$DB_FILE")
        IFS=: read -r _ pass _expiry limit bw daily_bw _ <<< "$line"
        [[ -z "$bw" ]] && bw="0"
        [[ -z "$daily_bw" ]] && daily_bw="0"
        local new_expire_date
        if [[ "$renew_mode" == "2" && -n "$_expiry" && "$_expiry" != "Never" ]]; then
            new_expire_date=$(date -d "$_expiry +$days days" +%Y-%m-%d 2>/dev/null || date -d "+$days days" +%Y-%m-%d)
        else
            new_expire_date=$(date -d "+$days days" +%Y-%m-%d)
        fi
        chage -E "$new_expire_date" "$u"
        sed -i "s/^$u:.*/$u:$pass:$new_expire_date:$limit:$bw:$daily_bw/" "$DB_FILE"
        usermod -U "$u" &>/dev/null
        echo -e " ✅ ${C_YELLOW}$u${C_RESET}: ${C_DIM}${_expiry}${C_RESET} → ${C_GREEN}${new_expire_date}${C_RESET} (unlocked)"
        _log_action "RENEW_USER" "Renewed $u for $days days (mode $renew_mode). Unlocked."
    done
}

cleanup_expired() {
    clear; show_banner
    echo
    menu_section "CLEANUP EXPIRED USERS" "$C_TITLE"
    echo
    local expired_users=()
    local current_ts; current_ts=$(date +%s)

    if [[ -s "$DB_FILE" ]]; then
        while IFS=: read -r user pass expiry limit bandwidth_gb _extra; do
            local expiry_ts; expiry_ts=$(date -d "$expiry" +%s 2>/dev/null || echo 0)
            if [[ $expiry_ts -lt $current_ts && $expiry_ts -ne 0 ]]; then
                expired_users+=("$user")
            fi
        done < "$DB_FILE"
    fi

    if [ ${#expired_users[@]} -eq 0 ]; then
        echo -e "  ${C_CYAN}Status:${C_RESET} ${C_GREEN}No expired users found.${C_RESET}"
        return
    fi

    echo -e "  ${C_CYAN}Expired Users (${#expired_users[@]}):${C_RESET} ${C_RED}${expired_users[*]}${C_RESET}"
    echo
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Delete Expired Users"
    printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" confirm
    if [[ "$confirm" == "1" ]]; then
        echo -e "\n${C_BLUE}Deleting expired users...${C_RESET}"
        delete_firewallfalcon_user_accounts "${expired_users[@]}"
        echo -e "\n${C_GREEN}✅ Expired users cleaned up successfully.${C_RESET}"
    fi
}

# Builds one backup archive with everything needed to reproduce this
# server's accounts/state exactly on another machine: all of DAHOOM's own
# data (/etc/firewallfalcon — SSH users, resellers, bandwidth usage
# counters, usage-link tokens, connection log, panel config, X-UI client
# display prefs...) plus X-UI's own database (/etc/x-ui/x-ui.db — every
# V2ray/VLESS client, its expiry/bandwidth limits, and its live traffic
# counters) when X-UI is installed. Used by every backup path (manual and
# scheduled) so a fix here can't miss one of them.
# Flushes X-UI's write-ahead log into x-ui.db itself, so archiving that one
# file captures every committed row.
#
# This matters because the two X-UI variants open SQLite differently: the
# original alireza0 build uses the default rollback journal (the .db file is
# always complete on its own), while 3x-ui opens with _journal_mode=WAL. Under
# WAL, freshly committed rows live in the sibling x-ui.db-wal until a
# checkpoint — on a running 3x-ui the main file can hold almost nothing (a
# 4 KB .db against an 800 KB -wal was measured on a fresh install), so an
# archive of just x-ui.db can restore to a database with no tables at all and
# every V2ray client silently lost. A checkpoint first collapses the WAL back
# into the .db and makes the single-file archive whole again.
#
# Safe on both variants and on a stopped panel: a checkpoint against a
# non-WAL database is a no-op, and a busy_timeout lets it wait out any write
# X-UI has in flight instead of failing. Best-effort throughout — a server
# without sqlite3 still gets the archive it would have got before.
_fm_checkpoint_xui_db() {
    [[ -f /etc/x-ui/x-ui.db ]] || return 0
    if command -v sqlite3 &>/dev/null; then
        sqlite3 /etc/x-ui/x-ui.db \
            "PRAGMA busy_timeout=10000; PRAGMA wal_checkpoint(TRUNCATE);" &>/dev/null || true
    elif command -v python3 &>/dev/null; then
        python3 -c "
import sqlite3
try:
    c = sqlite3.connect('/etc/x-ui/x-ui.db', timeout=10)
    c.execute('PRAGMA busy_timeout=10000')
    c.execute('PRAGMA wal_checkpoint(TRUNCATE)')
    c.close()
except Exception:
    pass
" &>/dev/null || true
    fi
}

_fm_build_backup_archive() {
    local dest="$1"
    local -a paths=("$(basename "$DB_DIR")")
    if [[ -f /etc/x-ui/x-ui.db ]]; then
        _fm_checkpoint_xui_db
        paths+=("x-ui/x-ui.db")
    fi
    tar -czf "$dest" -C "$(dirname "$DB_DIR")" "${paths[@]}" 2>/dev/null
}

backup_user_data() {
    clear; show_banner
    echo
    menu_section "BACKUP USER DATA" "$C_TITLE"
    echo
    echo -e "  ${C_CYAN}Existing Backups:${C_RESET}"
    local count=0
    while read -r file size; do
        if [[ -n "$file" ]]; then
            echo -e "  • ${C_WHITE}$(basename "$file")${C_RESET} ${C_DIM}($size)${C_RESET}"
            count=$((count+1))
        fi
    done < <(ls -lh /root/ff_backup_*.tar.gz /root/firewallfalcon_users.tar.gz 2>/dev/null | awk '{print $NF, $5}')
    [[ $count -eq 0 ]] && echo -e "  ${C_DIM}(No backups found)${C_RESET}"
    echo
    local auto_bk_status="${C_GREEN}ON${C_RESET}"
    _fm_auto_backup_before_update_enabled || auto_bk_status="${C_RED}OFF${C_RESET}"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Create Backup Now"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Purge Old Backups (Keep Last 5)"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s [%b]\n" "[3]" "Toggle Automatic Backup Before Update" "$auto_bk_status"
    echo
    printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select an option [1]: "${C_RESET})" bk_act
    bk_act=${bk_act:-1}

    case "$bk_act" in
        1)
            local auto_name="/root/ff_backup_$(date +%F-%H%M).tar.gz"
            mkdir -p "$DB_DIR" 2>/dev/null
            touch "$DB_FILE" 2>/dev/null
            echo -e "\n${C_BLUE}Creating full backup (SSH accounts + X-UI/V2ray accounts)...${C_RESET}"
            _fm_build_backup_archive "$auto_name"
            if [ $? -eq 0 ]; then
                local bk_size; bk_size=$(du -sh "$auto_name" 2>/dev/null | cut -f1)
                echo -e "\n${C_GREEN}✅ Backup created: ${C_YELLOW}$auto_name ${C_CYAN}($bk_size)${C_RESET}"
            else
                echo -e "\n${C_RED}❌ ERROR: Backup failed.${C_RESET}"
            fi
            ;;
        2)
            ls -t /root/ff_backup_*.tar.gz 2>/dev/null | tail -n +6 | xargs -r rm -f
            echo -e "\n${C_GREEN}✅ Old backups purged (kept last 5).${C_RESET}"
            ;;
        3)
            if _fm_auto_backup_before_update_enabled; then
                _fm_set_auto_backup_before_update "false"
                echo -e "\n${C_YELLOW}⚠️ Automatic backup before update is now OFF.${C_RESET}"
            else
                _fm_set_auto_backup_before_update "true"
                echo -e "\n${C_GREEN}✅ Automatic backup before update is now ON.${C_RESET} A full backup will be taken and sent to Telegram (if configured) right before every self-update."
            fi
            ;;
        0|*) ;;
    esac
}

restore_user_data() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📥 Restore User Data ---${C_RESET}"
    
    # Collect list of files
    local backups=()
    while IFS= read -r line; do
        if [ -n "$line" ]; then
            backups+=("$line")
        fi
    done < <(ls -t /root/ff_backup_*.tar.gz /root/firewallfalcon_users.tar.gz 2>/dev/null)

    if (( ${#backups[@]} == 0 )); then
        echo -e "  ${C_RED}❌ No backups found in /root/.${C_RESET}"
        echo
        read -p "👉 Press Enter to return..."
        return
    fi

    echo -e "${C_CYAN}Select a backup to restore:${C_RESET}"
    local i=1
    for bk in "${backups[@]}"; do
        local size; size=$(du -sh "$bk" 2>/dev/null | awk '{print $1}')
        printf "  ${C_CHOICE}[%d]${C_RESET} %s (${C_YELLOW}%s${C_RESET})\n" "$i" "$bk" "$size"
        ((i++))
    done
    echo
    printf "  ${C_DANGER}[0]${C_RESET} Return/Cancel\n"
    echo

    local choice
    read -p "👉 Select option [0-$((${#backups[@]}))]: " choice
    choice=${choice:-0}

    if [[ "$choice" == "0" ]]; then
        echo -e "\n${C_YELLOW}❌ Restore cancelled.${C_RESET}"
        return
    fi

    if ! [[ "$choice" =~ ^[0-9]+$ ]] || (( choice < 1 || choice > ${#backups[@]} )); then
        echo -e "\n${C_RED}❌ ERROR: Invalid choice.${C_RESET}"
        return
    fi

    local backup_path="${backups[$((choice - 1))]}"
    # ── BETA: Archive preview ────────────────────────────────────── ✦new
    echo -e "\n${C_CYAN}Archive preview ${NEW_TAG}:${C_RESET}"   # ✦new
    tar -tzf "$backup_path" 2>/dev/null | head -15   # ✦new
    local bk_cnt; bk_cnt=$(tar -xzOf "$backup_path" firewallfalcon/users.db 2>/dev/null | wc -l)   # ✦new
    echo -e "\n  ${C_CYAN}Users (SSH) in backup: ${C_YELLOW}$bk_cnt${C_RESET} | Currently: ${C_YELLOW}$(wc -l < "$DB_FILE" 2>/dev/null)${C_RESET}"   # ✦new
    if tar -tzf "$backup_path" 2>/dev/null | grep -q '^x-ui/x-ui\.db$'; then   # ✦new
        echo -e "  ${C_CYAN}X-UI (V2ray) database: ${C_GREEN}✅ included${C_RESET} ${C_DIM}(clients, expiry, bandwidth limits & usage counters)${C_RESET}"   # ✦new
    else   # ✦new
        echo -e "  ${C_CYAN}X-UI (V2ray) database: ${C_DIM}not in this backup${C_RESET}"   # ✦new
    fi   # ✦new
    echo   # ✦new
    echo -e "\n${C_RED}${C_BOLD}⚠️ WARNING:${C_RESET} This will overwrite all current users and settings."
    echo -e "It will restore user accounts, passwords, limits, and expiration dates from the backup file."
    read -p "👉 Are you absolutely sure you want to proceed? (y/n): " confirm
    if [[ "$confirm" != "y" ]]; then echo -e "\n${C_YELLOW}❌ Restore cancelled.${C_RESET}"; return; fi
    # ── BETA: Safety backup ──────────────────────────────────────── ✦new
    echo -e "\n${C_BLUE}💾 Creating safety backup of current data ${NEW_TAG}...${C_RESET}"   # ✦new
    local safety_bk="/root/ff_pre_restore_$(date +%F-%H%M).tar.gz"   # ✦new
    _fm_build_backup_archive "$safety_bk"   # ✦new
    echo -e "  ${C_GREEN}✅ Safety backup: ${C_YELLOW}$safety_bk${C_RESET}"   # ✦new
    local temp_dir
    temp_dir=$(mktemp -d)
    echo -e "\n${C_BLUE}⚙️ Extracting backup file to a temporary location...${C_RESET}"
    tar -xzf "$backup_path" -C "$temp_dir"
    if [ $? -ne 0 ]; then
        echo -e "\n${C_RED}❌ ERROR: Failed to extract backup file. Aborting.${C_RESET}"
        rm -rf "$temp_dir"
        return
    fi
    local restored_db_file="$temp_dir/firewallfalcon/users.db"
    if [ ! -f "$restored_db_file" ]; then
        echo -e "\n${C_RED}❌ ERROR: users.db not found in the backup. Cannot restore user accounts.${C_RESET}"
        rm -rf "$temp_dir"
        return
    fi
    # Restore EVERYTHING the backup captured, not just users.db — this
    # brings back bandwidth usage counters (bandwidth/), usage-link tokens
    # and their enabled/disabled state (bandwidth_tokens.db), SSL, DNS,
    # panel config, and anything else under firewallfalcon/, in one pass
    # instead of a hand-maintained whitelist that silently drops new files.
    echo -e "${C_BLUE}⚙️ Restoring all saved data (users, bandwidth usage, usage-links, SSL, DNS, panel config...)...${C_RESET}"
    mkdir -p "$DB_DIR"
    cp -a "$temp_dir/firewallfalcon/." "$DB_DIR/"

    if [[ -f "$temp_dir/x-ui/x-ui.db" ]]; then
        echo -e "${C_BLUE}⚙️ Restoring X-UI (V2ray) accounts, expiry, bandwidth limits and usage counters...${C_RESET}"
        systemctl stop x-ui 2>/dev/null
        mkdir -p /etc/x-ui
        # Snapshot whatever X-UI data already exists on THIS server before
        # it gets overwritten — same safety-net idea as the firewallfalcon
        # backup above, just for the database restoring it can't touch.
        [[ -f /etc/x-ui/x-ui.db ]] && cp -a /etc/x-ui/x-ui.db "/etc/x-ui/x-ui.db.pre_restore_$(date +%F-%H%M)" 2>/dev/null
        cp -a "$temp_dir/x-ui/x-ui.db" /etc/x-ui/x-ui.db
        # Drop the outgoing database's write-ahead log alongside it. On a
        # 3x-ui install (which runs SQLite in WAL mode) these sidecar files
        # belong to the database just replaced, and leaving them next to a
        # different .db invites SQLite to reconcile the two. The archive is
        # checkpointed before it is written, so the restored .db is already
        # complete and needs no WAL of its own.
        rm -f /etc/x-ui/x-ui.db-wal /etc/x-ui/x-ui.db-shm 2>/dev/null
        systemctl start x-ui 2>/dev/null
        echo -e "  ${C_GREEN}✅ X-UI database restored.${C_RESET}"
    else
        echo -e "  ${C_DIM}(No X-UI data in this backup — it either predates this feature, or X-UI wasn't installed when it was made.)${C_RESET}"
    fi

    echo -e "${C_BLUE}⚙️ Re-synchronizing system accounts with the restored database...${C_RESET}"
    ensure_firewallfalcon_system_group
    
    while IFS=: read -r user pass expiry limit _rest; do
        echo "Processing user: ${C_YELLOW}$user${C_RESET}"
        if ! id "$user" &>/dev/null; then
            echo " - User does not exist in system. Creating..."
            _fm_create_system_user "$user"
        fi
        usermod -aG "$FF_USERS_GROUP" "$user" 2>/dev/null
        echo " - Setting password..."
        echo "$user:$pass" | chpasswd
        if [[ "$expiry" == "Never" ]]; then
            echo " - No expiration (Never)."
        else
            # users.db stores the expiry as either a bare "YYYY-MM-DD" or,
            # for hour-based/trial accounts, "YYYY-MM-DD HH:MM" — chage only
            # understands a whole date and silently mis-parses the HH:MM
            # form into the WRONG day if handed it directly (verified: it
            # can land a full day off, with no error). Every other place in
            # this codebase that hands chage an expiry already normalizes it
            # to a whole day the same way — round up one day when a
            # time-of-day was present, so a trial account that's still
            # valid later today isn't chage'd as already expired.
            local chage_date=""
            if [[ "$expiry" == *" "* ]]; then
                chage_date=$(date -d "$expiry +1 day" +%Y-%m-%d 2>/dev/null)
            else
                chage_date=$(date -d "$expiry" +%Y-%m-%d 2>/dev/null)
            fi
            if [[ -n "$chage_date" ]]; then
                echo " - Setting expiration to $chage_date..."
                chage -E "$chage_date" "$user"
            else
                echo -e " - ${C_RED}⚠️ Could not parse expiry '$expiry' — left unset, renew this account to fix it.${C_RESET}"
            fi
        fi
        echo " - Connection limit is $limit (enforced by PAM)"
    done < "$DB_FILE"
    rm -rf "$temp_dir"
    echo -e "\n${C_GREEN}✅ SUCCESS: User data restore completed.${C_RESET}"
    
    invalidate_banner_cache
    refresh_dynamic_banner_routing_if_enabled
}

_enable_banner_in_sshd_config() {
    echo -e "\n${C_BLUE}⚙️ Configuring sshd_config...${C_RESET}"
    disable_dynamic_ssh_banner_system
    sed -i.bak -E 's/^( *Banner *).*/#\1/' /etc/ssh/sshd_config
    if ! grep -q -E "^Banner $SSH_BANNER_FILE" /etc/ssh/sshd_config; then
        echo -e "\n# DAHOOM SSH Banner\nBanner $SSH_BANNER_FILE" >> /etc/ssh/sshd_config
    fi
    echo -e "${C_GREEN}✅ sshd_config updated.${C_RESET}"
}

_restart_ssh() {
    echo -e "\n${C_BLUE}🔄 Restarting SSH service to apply changes...${C_RESET}"
    local ssh_service_name=""
    if [ -f /lib/systemd/system/sshd.service ]; then
        ssh_service_name="sshd.service"
    elif [ -f /lib/systemd/system/ssh.service ]; then
        ssh_service_name="ssh.service"
    else
        echo -e "${C_RED}❌ Could not find sshd.service or ssh.service. Cannot restart SSH.${C_RESET}"
        return 1
    fi

    systemctl restart "${ssh_service_name}"
    if [ $? -eq 0 ]; then
        echo -e "${C_GREEN}✅ SSH service ('${ssh_service_name}') restarted successfully.${C_RESET}"
    else
        echo -e "${C_RED}❌ Failed to restart SSH service ('${ssh_service_name}'). Please check 'journalctl -u ${ssh_service_name}' for errors.${C_RESET}"
    fi
}

set_ssh_banner_paste() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📋 Paste Static SSH Banner ---${C_RESET}"
    echo -e "Paste your custom banner below. Press ${C_YELLOW}[Ctrl+D]${C_RESET} when you are finished."
    echo -e "${C_DIM}This will be shown to all SSH users through 'Banner $SSH_BANNER_FILE'.${C_RESET}"
    echo -e "${C_DIM}The current banner (if any) will be overwritten.${C_RESET}"
    echo -e "--------------------------------------------------"
    cat > "$SSH_BANNER_FILE"
    chmod 644 "$SSH_BANNER_FILE"
    echo -e "\n--------------------------------------------------"
    echo -e "\n${C_GREEN}✅ Static banner content saved.${C_RESET}"
    _enable_banner_in_sshd_config
    _restart_ssh
    echo -e "\nPress ${C_YELLOW}[Enter]${C_RESET} to return..." && read -r
}

view_ssh_banner() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 👁️ Current SSH Banner ---${C_RESET}"
    if [ -f "$SSH_BANNER_FILE" ]; then
        echo -e "\n${C_CYAN}--- BEGIN BANNER ---${C_RESET}"
        cat "$SSH_BANNER_FILE"
        echo -e "${C_CYAN}---- END BANNER ----${C_RESET}"
    else
        echo -e "\n${C_YELLOW}ℹ️ No banner file found at $SSH_BANNER_FILE.${C_RESET}"
    fi
    echo -e "\nPress ${C_YELLOW}[Enter]${C_RESET} to return..." && read -r
}

remove_ssh_banner() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🗑️ Disable SSH Banners ---${C_RESET}"
    read -p "👉 Are you sure you want to disable all SSH banners? (y/n): " confirm
    if [[ "$confirm" != "y" ]]; then
        echo -e "\n${C_YELLOW}❌ Action cancelled.${C_RESET}"
        echo -e "\nPress ${C_YELLOW}[Enter]${C_RESET} to return..." && read -r
        return
    fi
    if [ -f "$SSH_BANNER_FILE" ]; then
        rm -f "$SSH_BANNER_FILE"
        echo -e "\n${C_GREEN}✅ Removed banner file: $SSH_BANNER_FILE${C_RESET}"
    else
        echo -e "\n${C_YELLOW}ℹ️ No banner file to remove.${C_RESET}"
    fi
    disable_dynamic_ssh_banner_system
    echo -e "\n${C_BLUE}⚙️ Disabling banner in sshd_config...${C_RESET}"
    disable_static_ssh_banner_in_sshd_config
    echo -e "${C_GREEN}✅ Banner disabled in configuration.${C_RESET}"
    _restart_ssh
    echo -e "\nPress ${C_YELLOW}[Enter]${C_RESET} to return..." && read -r
}

preview_dynamic_ssh_banner() {
    if ! is_dynamic_ssh_banner_enabled; then
        echo -e "\n${C_RED}❌ Dynamic banners are not enabled right now.${C_RESET}"
        press_enter
        return
    fi

    echo -e "${C_DIM}Refreshing dynamic banner worker...${C_RESET}"
    setup_limiter_service >/dev/null 2>&1
    _select_user_interface "--- 📝 Preview Dynamic Banner ---"
    local u=$SELECTED_USER
    if [[ -z "$u" || "$u" == "NO_USERS" ]]; then
        return
    fi

    echo -e "\n${C_CYAN}--- Dynamic Banner Preview for user '$u' ---${C_RESET}\n"
    if [[ -f "/etc/firewallfalcon/banners/${u}.txt" ]]; then
        cat "/etc/firewallfalcon/banners/${u}.txt"
    else
        echo -e "${C_RED}Banner file not generated yet. Waiting up to 10s for the worker...${C_RESET}"
        sleep 5
        if ! cat "/etc/firewallfalcon/banners/${u}.txt" 2>/dev/null; then
            echo -e "\n${C_RED}Still not generated. Here are the last limiter logs:${C_RESET}"
            echo -e "----------------------------------------------------------------------"
            journalctl -u firewallfalcon-limiter -n 15 --no-pager
            echo -e "----------------------------------------------------------------------"
        fi
    fi
    press_enter
}

# NOTE: The full ssh_banner_menu() with dynamic/static support is defined later in the file.

install_udp_custom() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Installing udp-custom ---${C_RESET}"
    if [ -f "$UDP_CUSTOM_SERVICE_FILE" ] || [ -f "$UDPGW_SERVICE_FILE" ]; then
        echo -e "\n${C_YELLOW}ℹ️ udp-custom is already installed.${C_RESET}"
        return
    fi

    check_and_free_ports 36712 7800 || return
    check_and_open_firewall_port 36712 udp || return

    echo -e "\n${C_GREEN}⚙️ Creating directory for udp-custom...${C_RESET}"
    rm -rf "$UDP_CUSTOM_DIR"
    mkdir -p "$UDP_CUSTOM_DIR"

    echo -e "\n${C_GREEN}⚙️ Detecting system architecture...${C_RESET}"
    local arch
    arch=$(uname -m)
    local update_branch
    update_branch=$(get_update_branch)
    local binary_url=""
    if [[ "$arch" == "x86_64" ]]; then
        binary_url="$(_fm_gh_raw)/${update_branch}/udp/udp-custom-linux-amd64"
        echo -e "${C_BLUE}ℹ️ Detected x86_64 (amd64) architecture.${C_RESET}"
    elif [[ "$arch" == "aarch64" || "$arch" == "arm64" ]]; then
        binary_url="$(_fm_gh_raw)/${update_branch}/udp/udp-custom-linux-arm"
        echo -e "${C_BLUE}ℹ️ Detected ARM64 architecture.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Unsupported architecture: $arch. Cannot install udp-custom.${C_RESET}"
        rm -rf "$UDP_CUSTOM_DIR"
        return
    fi

    echo -e "\n${C_GREEN}📥 Downloading udp-custom binary...${C_RESET}"
    wget -q --show-progress -O "$UDP_CUSTOM_DIR/udp-custom" "$binary_url"
    if [ $? -ne 0 ]; then
        echo -e "\n${C_RED}❌ Failed to download the udp-custom binary.${C_RESET}"
        rm -rf "$UDP_CUSTOM_DIR"
        return
    fi
    chmod +x "$UDP_CUSTOM_DIR/udp-custom"

    echo -e "\n${C_GREEN}📦 Setting up udpgw helper...${C_RESET}"
    if [[ "$arch" == "x86_64" ]]; then
        wget -q --show-progress -O "$UDPGW_BINARY" "https://raw.githubusercontent.com/http-custom/udp-custom/main/module/udpgw"
        if [ $? -ne 0 ]; then
            echo -e "\n${C_RED}❌ Failed to download the udpgw helper binary.${C_RESET}"
            rm -rf "$UDP_CUSTOM_DIR"
            return
        fi
        chmod +x "$UDPGW_BINARY"
    else
        echo -e "${C_YELLOW}ℹ️ Architecture is $arch. Compiling udpgw from source (this may take a minute)...${C_RESET}"
        ff_pkg_install cmake g++ make git >/dev/null 2>&1
        local temp_build="/tmp/badvpn_build"
        rm -rf "$temp_build"
        git clone -q https://github.com/ambrop72/badvpn.git "$temp_build"
        (cd "$temp_build" && cmake . >/dev/null 2>&1 && make >/dev/null 2>&1)
        local compiled_bin=$(find "$temp_build" -name "badvpn-udpgw" -type f | head -n 1)
        if [[ -n "$compiled_bin" && -f "$compiled_bin" ]]; then
            cp "$compiled_bin" "$UDPGW_BINARY"
            chmod +x "$UDPGW_BINARY"
        else
            echo -e "\n${C_RED}❌ Failed to compile udpgw helper for $arch.${C_RESET}"
            rm -rf "$UDP_CUSTOM_DIR" "$temp_build"
            return
        fi
        rm -rf "$temp_build"
    fi

    echo -e "\n${C_GREEN}📝 Creating default config.json...${C_RESET}"
    cat > "$UDP_CUSTOM_DIR/config.json" <<EOF
{
  "listen": ":36712",
  "stream_buffer": 33554432,
  "receive_buffer": 83886080,
  "auth": {
    "mode": "passwords"
  }
}
EOF
    chmod 644 "$UDP_CUSTOM_DIR/config.json"

    echo -e "\n${C_GREEN}📝 Creating udpgw systemd service file...${C_RESET}"
    cat > "$UDPGW_SERVICE_FILE" <<EOF
[Unit]
Description=DAHOOM UDPGW Backend
After=network.target

[Service]
User=root
Type=simple
ExecStart=$UDPGW_BINARY --listen-addr 127.0.0.1:7800 --max-clients 1000 --max-connections-for-client 100
Restart=always
RestartSec=2s

[Install]
WantedBy=multi-user.target
EOF

    echo -e "\n${C_GREEN}📝 Creating systemd service file...${C_RESET}"
    cat > "$UDP_CUSTOM_SERVICE_FILE" <<EOF
[Unit]
Description=UDP Custom by DAHOOM
After=network.target

[Service]
User=root
Type=simple
ExecStart=$UDP_CUSTOM_DIR/udp-custom server
WorkingDirectory=$UDP_CUSTOM_DIR/
Restart=always
RestartSec=2s

[Install]
WantedBy=multi-user.target
EOF

    echo -e "\n${C_GREEN}▶️ Enabling and starting udp-custom service...${C_RESET}"
    systemctl daemon-reload
    systemctl enable udpgw.service
    systemctl start udpgw.service
    systemctl enable udp-custom.service
    systemctl start udp-custom.service
    sleep 2
    if systemctl is-active --quiet udpgw && systemctl is-active --quiet udp-custom; then
        echo -e "\n${C_GREEN}✅ SUCCESS: udp-custom is installed and active.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ ERROR: udp-custom service failed to start.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Displaying last 15 lines of the udp-custom and udpgw logs for diagnostics:${C_RESET}"
        journalctl -u udp-custom.service -n 15 --no-pager
        journalctl -u udpgw.service -n 15 --no-pager
    fi
}

uninstall_udp_custom() {
    echo -e "\n${C_BOLD}${C_PURPLE}--- 🗑️ Uninstalling udp-custom ---${C_RESET}"
    if [ ! -f "$UDP_CUSTOM_SERVICE_FILE" ] && [ ! -f "$UDPGW_SERVICE_FILE" ]; then
        echo -e "${C_YELLOW}ℹ️ udp-custom is not installed, skipping.${C_RESET}"
        return
    fi
    echo -e "${C_GREEN}🛑 Stopping and disabling udpgw service...${C_RESET}"
    systemctl stop udpgw.service >/dev/null 2>&1
    systemctl disable udpgw.service >/dev/null 2>&1
    echo -e "${C_GREEN}🛑 Stopping and disabling udp-custom service...${C_RESET}"
    systemctl stop udp-custom.service >/dev/null 2>&1
    systemctl disable udp-custom.service >/dev/null 2>&1
    echo -e "${C_GREEN}🗑️ Removing systemd service file...${C_RESET}"
    rm -f "$UDP_CUSTOM_SERVICE_FILE"
    rm -f "$UDPGW_SERVICE_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}🗑️ Removing udp-custom directory and files...${C_RESET}"
    rm -rf "$UDP_CUSTOM_DIR"
    rm -f "$UDPGW_BINARY"
    echo -e "${C_GREEN}✅ udp-custom has been uninstalled successfully.${C_RESET}"
}


ensure_badvpn_service_is_quiet() {
    if [[ ! -f "$BADVPN_SERVICE_FILE" ]] || grep -q "^StandardOutput=null$" "$BADVPN_SERVICE_FILE" 2>/dev/null; then
        return
    fi

    local tmp_service
    tmp_service=$(mktemp)
    awk '
        /^\[Service\]$/ {
            print
            print "StandardOutput=null"
            print "StandardError=null"
            next
        }
        { print }
    ' "$BADVPN_SERVICE_FILE" > "$tmp_service" && mv "$tmp_service" "$BADVPN_SERVICE_FILE"
    rm -f "$tmp_service" 2>/dev/null
    systemctl daemon-reload
    systemctl restart badvpn.service >/dev/null 2>&1 || true
}

install_badvpn() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Installing badvpn (udpgw) ---${C_RESET}"
    if [ -f "$BADVPN_SERVICE_FILE" ]; then
        echo -e "\n${C_YELLOW}ℹ️ badvpn is already installed.${C_RESET}"
        return
    fi
    check_and_open_firewall_port 7300 udp || return
    echo -e "\n${C_GREEN}🔄 Updating package lists...${C_RESET}"
    ff_apt_update || return
    echo -e "\n${C_GREEN}📦 Installing all required packages...${C_RESET}"
    ff_pkg_install cmake g++ make screen git build-essential libssl-dev libnspr4-dev libnss3-dev pkg-config || {
        echo -e "${C_RED}❌ Failed to install badvpn build dependencies.${C_RESET}"
        return
    }
    echo -e "\n${C_GREEN}📥 Cloning badvpn from github...${C_RESET}"
    git clone https://github.com/ambrop72/badvpn.git "$BADVPN_BUILD_DIR"
    cd "$BADVPN_BUILD_DIR" || { echo -e "${C_RED}❌ Failed to change directory to build folder.${C_RESET}"; return; }
    echo -e "\n${C_GREEN}⚙️ Running CMake...${C_RESET}"
    cmake . || { echo -e "${C_RED}❌ CMake configuration failed.${C_RESET}"; rm -rf "$BADVPN_BUILD_DIR"; return; }
    echo -e "\n${C_GREEN}🛠️ Compiling source...${C_RESET}"
    make || { echo -e "${C_RED}❌ Compilation (make) failed.${C_RESET}"; rm -rf "$BADVPN_BUILD_DIR"; return; }
    local badvpn_binary
    badvpn_binary=$(find "$BADVPN_BUILD_DIR" -name "badvpn-udpgw" -type f | head -n 1)
    if [[ -z "$badvpn_binary" || ! -f "$badvpn_binary" ]]; then
        echo -e "${C_RED}❌ ERROR: Could not find the compiled 'badvpn-udpgw' binary after compilation.${C_RESET}"
        rm -rf "$BADVPN_BUILD_DIR"
        return
    fi
    echo -e "${C_GREEN}ℹ️ Found binary at: $badvpn_binary${C_RESET}"
    chmod +x "$badvpn_binary"
    echo -e "\n${C_GREEN}📝 Creating systemd service file...${C_RESET}"
    cat > "$BADVPN_SERVICE_FILE" <<-EOF
[Unit]
Description=BadVPN UDP Gateway
After=network.target
[Service]
ExecStart=$badvpn_binary --listen-addr 0.0.0.0:7300 --max-clients 1000 --max-connections-for-client 8
User=root
Restart=always
RestartSec=3
StandardOutput=null
StandardError=null
[Install]
WantedBy=multi-user.target
EOF
    echo -e "\n${C_GREEN}▶️ Enabling and starting badvpn service...${C_RESET}"
    systemctl daemon-reload
    systemctl enable badvpn.service
    systemctl start badvpn.service
    sleep 2
    if systemctl is-active --quiet badvpn; then
        echo -e "\n${C_GREEN}✅ SUCCESS: badvpn (udpgw) is installed and active on port 7300.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ ERROR: badvpn service failed to start.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Displaying last 15 lines of the service log for diagnostics:${C_RESET}"
        journalctl -u badvpn.service -n 15 --no-pager
    fi
}

uninstall_badvpn() {
    echo -e "\n${C_BOLD}${C_PURPLE}--- 🗑️ Uninstalling badvpn (udpgw) ---${C_RESET}"
    if [ ! -f "$BADVPN_SERVICE_FILE" ]; then
        echo -e "${C_YELLOW}ℹ️ badvpn is not installed, skipping.${C_RESET}"
        return
    fi
    echo -e "${C_GREEN}🛑 Stopping and disabling badvpn service...${C_RESET}"
    systemctl stop badvpn.service >/dev/null 2>&1
    systemctl disable badvpn.service >/dev/null 2>&1
    echo -e "${C_GREEN}🗑️ Removing systemd service file...${C_RESET}"
    rm -f "$BADVPN_SERVICE_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}🗑️ Removing badvpn build directory...${C_RESET}"
    rm -rf "$BADVPN_BUILD_DIR"
    echo -e "${C_GREEN}✅ badvpn has been uninstalled successfully.${C_RESET}"
}

load_edge_cert_info() {
    EDGE_CERT_MODE=""
    EDGE_DOMAIN=""
    EDGE_EMAIL=""
    if [ -f "$EDGE_CERT_INFO_FILE" ]; then
        source "$EDGE_CERT_INFO_FILE"
    fi
}

save_edge_cert_info() {
    local cert_mode="$1"
    local cert_domain="$2"
    local cert_email="$3"
    mkdir -p "$DB_DIR"
    cat > "$EDGE_CERT_INFO_FILE" <<EOF
EDGE_CERT_MODE="$cert_mode"
EDGE_DOMAIN="$cert_domain"
EDGE_EMAIL="$cert_email"
EOF
}

detect_preferred_host() {
    local host_domain=""
    load_edge_cert_info
    if [[ -n "$EDGE_DOMAIN" ]]; then
        host_domain="$EDGE_DOMAIN"
    fi
    if [[ -z "$host_domain" && -f "$CLOUDFLARE_INFO_FILE" ]]; then
        host_domain=$(grep 'CF_DOMAIN' "$CLOUDFLARE_INFO_FILE" 2>/dev/null | cut -d'"' -f2)
    fi
    if [[ -z "$host_domain" && -f "$DNS_INFO_FILE" ]]; then
        host_domain=$(grep 'FULL_DOMAIN' "$DNS_INFO_FILE" | cut -d'"' -f2)
    fi
    if [[ -z "$host_domain" && -f "/etc/firewallfalcon/custom_domain.info" ]]; then
        host_domain=$(grep 'CUSTOM_DOMAIN' "/etc/firewallfalcon/custom_domain.info" 2>/dev/null | cut -d'"' -f2)
    fi
    if [[ -z "$host_domain" && -f "$NGINX_CONFIG_FILE" ]]; then
        local nginx_domain
        nginx_domain=$(grep -oP 'server_name \K[^\s;]+' "$NGINX_CONFIG_FILE" 2>/dev/null | head -n 1)
        if [[ "$nginx_domain" != "_" && -n "$nginx_domain" ]]; then
            host_domain="$nginx_domain"
        fi
    fi
    if [[ -z "$host_domain" ]]; then
        host_domain=$(curl -s -4 icanhazip.com)
    fi
    echo "$host_domain"
}

backup_edge_configs() {
    if [ -f "$NGINX_CONFIG_FILE" ] && [ ! -f "${NGINX_CONFIG_FILE}.bak.firewallfalcon" ]; then
        cp "$NGINX_CONFIG_FILE" "${NGINX_CONFIG_FILE}.bak.firewallfalcon" 2>/dev/null
    fi
    if [ -f "$HAPROXY_CONFIG" ] && [ ! -f "${HAPROXY_CONFIG}.bak.firewallfalcon" ]; then
        cp "$HAPROXY_CONFIG" "${HAPROXY_CONFIG}.bak.firewallfalcon" 2>/dev/null
    fi
}

ensure_edge_stack_packages() {
    local missing_packages=()
    if ! command -v haproxy &> /dev/null || [ ! -f "/etc/haproxy/haproxy.cfg" ]; then
        missing_packages+=("haproxy")
    fi
    if ! command -v nginx &> /dev/null || [ ! -f "/etc/nginx/nginx.conf" ]; then
        missing_packages+=("nginx")
    fi
    command -v openssl &> /dev/null || missing_packages+=("openssl")

    if (( ${#missing_packages[@]} > 0 )); then
        echo -e "\n${C_BLUE}📦 Installing required packages: ${missing_packages[*]}${C_RESET}"
        if ! ff_pkg_install "${missing_packages[@]}"; then
            echo -e "${C_YELLOW}⚠️ Package installation failed. Attempting to fix broken configurations...${C_RESET}"
            if command -v apt-get &>/dev/null; then
                apt-get purge -y nginx nginx-common haproxy >/dev/null 2>&1
            fi
            if ! ff_pkg_install "${missing_packages[@]}"; then
                echo -e "${C_RED}❌ Failed to install the required packages.${C_RESET}"
                return 1
            fi
        fi
    fi
    return 0
}

build_shared_tls_bundle() {
    if [ ! -s "$SSL_CERT_CHAIN_FILE" ] || [ ! -s "$SSL_CERT_KEY_FILE" ]; then
        echo -e "${C_RED}❌ Certificate chain or key is missing.${C_RESET}"
        return 1
    fi
    cat "$SSL_CERT_CHAIN_FILE" "$SSL_CERT_KEY_FILE" > "$SSL_CERT_FILE" || return 1
    chmod 644 "$SSL_CERT_CHAIN_FILE"
    chmod 600 "$SSL_CERT_KEY_FILE" "$SSL_CERT_FILE"
    return 0
}

generate_self_signed_edge_cert() {
    local common_name="$1"
    mkdir -p "$SSL_CERT_DIR"
    echo -e "\n${C_GREEN}🔐 Generating a shared self-signed certificate...${C_RESET}"
    openssl req -x509 -newkey rsa:2048 -nodes -days 3650 \
        -keyout "$SSL_CERT_KEY_FILE" \
        -out "$SSL_CERT_CHAIN_FILE" \
        -subj "/CN=$common_name" \
        >/dev/null 2>&1 || {
            echo -e "${C_RED}❌ Failed to generate the self-signed certificate.${C_RESET}"
            return 1
        }
    build_shared_tls_bundle || return 1
    save_edge_cert_info "self-signed" "$common_name" ""
    echo -e "${C_GREEN}✅ Shared certificate created for ${C_YELLOW}$common_name${C_RESET}"
    return 0
}

_install_certbot() {
    if command -v certbot &> /dev/null; then
        echo -e "${C_GREEN}✅ Certbot is already installed.${C_RESET}"
        return 0
    fi
    echo -e "${C_BLUE}📦 Installing Certbot...${C_RESET}"
    ff_pkg_install certbot || {
        echo -e "${C_RED}❌ Failed to install Certbot.${C_RESET}"
        return 1
    }
    echo -e "${C_GREEN}✅ Certbot installed successfully.${C_RESET}"
    return 0
}

obtain_certbot_edge_cert() {
    local domain_name="$1"
    local email="$2"
    local restart_haproxy=0
    local restart_nginx=0

    mkdir -p "$SSL_CERT_DIR"
    _install_certbot || return 1

    if systemctl is-active --quiet haproxy; then restart_haproxy=1; fi
    if systemctl is-active --quiet nginx; then restart_nginx=1; fi

    echo -e "\n${C_BLUE}🛑 Stopping HAProxy and Nginx for Certbot validation...${C_RESET}"
    systemctl stop haproxy >/dev/null 2>&1
    systemctl stop nginx >/dev/null 2>&1
    sleep 2

    check_and_free_ports "$EDGE_PUBLIC_HTTP_PORT" "$EDGE_PUBLIC_TLS_PORT" || {
        [[ "$restart_nginx" -eq 1 ]] && systemctl start nginx >/dev/null 2>&1
        [[ "$restart_haproxy" -eq 1 ]] && systemctl start haproxy >/dev/null 2>&1
        return 1
    }

    echo -e "\n${C_BLUE}🚀 Requesting a Certbot certificate for ${C_YELLOW}$domain_name${C_RESET}"
    certbot certonly --standalone -d "$domain_name" --non-interactive --agree-tos -m "$email"
    if [ $? -ne 0 ]; then
        echo -e "\n${C_RED}❌ Certbot failed to obtain a certificate.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Make sure the domain points to this server and port 80 is reachable.${C_RESET}"
        [[ "$restart_nginx" -eq 1 ]] && systemctl start nginx >/dev/null 2>&1
        [[ "$restart_haproxy" -eq 1 ]] && systemctl start haproxy >/dev/null 2>&1
        return 1
    fi

    local certbot_chain="/etc/letsencrypt/live/$domain_name/fullchain.pem"
    local certbot_key="/etc/letsencrypt/live/$domain_name/privkey.pem"
    if [ ! -f "$certbot_chain" ] || [ ! -f "$certbot_key" ]; then
        echo -e "\n${C_RED}❌ Certbot completed, but the certificate files were not found.${C_RESET}"
        [[ "$restart_nginx" -eq 1 ]] && systemctl start nginx >/dev/null 2>&1
        [[ "$restart_haproxy" -eq 1 ]] && systemctl start haproxy >/dev/null 2>&1
        return 1
    fi

    cp "$certbot_chain" "$SSL_CERT_CHAIN_FILE"
    cp "$certbot_key" "$SSL_CERT_KEY_FILE"
    build_shared_tls_bundle || {
        [[ "$restart_nginx" -eq 1 ]] && systemctl start nginx >/dev/null 2>&1
        [[ "$restart_haproxy" -eq 1 ]] && systemctl start haproxy >/dev/null 2>&1
        return 1
    }
    save_edge_cert_info "certbot" "$domain_name" "$email"
    echo -e "${C_GREEN}✅ Certbot certificate copied into ${C_YELLOW}$SSL_CERT_DIR${C_RESET}"
    return 0
}

# True only if cert_file and key_file are a real pair — compares each
# side's PUBLIC key rather than `openssl x509 -modulus` (RSA-only), so an
# imported ECDSA cert/key is checked correctly too, not just RSA ones.
_fm_edge_cert_pair_matches() {
    local chain_file="$1" key_file="$2"
    local cert_pub key_pub
    cert_pub=$(openssl x509 -in "$chain_file" -pubkey -noout 2>/dev/null | openssl md5 2>/dev/null)
    key_pub=$(openssl pkey -in "$key_file" -pubout 2>/dev/null | openssl md5 2>/dev/null)
    [[ -n "$cert_pub" && "$cert_pub" == "$key_pub" ]]
}

# Import a certificate the admin already has, typed/pasted straight into
# the terminal — for a cert issued elsewhere (another box, a CA's web
# portal, a Cloudflare Origin Certificate, ...) with no file already on
# this server to point at.
import_edge_cert_paste() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📋 Import an Existing Certificate (Paste) ---${C_RESET}"
    echo -e "${C_DIM}This will replace the shared certificate used by HAProxy on ${EDGE_PUBLIC_TLS_PORT} and internal Nginx on ${NGINX_INTERNAL_TLS_PORT}.${C_RESET}\n"

    mkdir -p "$DB_DIR" "$SSL_CERT_DIR"
    load_edge_cert_info
    local preferred_host default_domain domain_name
    preferred_host=$(detect_preferred_host)
    default_domain="${EDGE_DOMAIN:-$preferred_host}"
    read -p "👉 Domain / label this certificate is for [$default_domain]: " domain_name
    domain_name=${domain_name:-$default_domain}
    if [[ -z "$domain_name" ]]; then
        echo -e "\n${C_RED}❌ A label is required.${C_RESET}"
        return
    fi

    local tmp_chain tmp_key
    tmp_chain=$(mktemp) tmp_key=$(mktemp)

    echo -e "\n${C_CYAN}Paste the certificate (fullchain, PEM format). Press ${C_YELLOW}[Ctrl+D]${C_RESET}${C_CYAN} when done:${C_RESET}"
    echo -e "--------------------------------------------------"
    cat > "$tmp_chain"
    echo -e "--------------------------------------------------"

    echo -e "\n${C_CYAN}Now paste the matching private key (PEM format). Press ${C_YELLOW}[Ctrl+D]${C_RESET}${C_CYAN} when done:${C_RESET}"
    echo -e "--------------------------------------------------"
    cat > "$tmp_key"
    echo -e "--------------------------------------------------"

    if ! openssl x509 -in "$tmp_chain" -noout 2>/dev/null; then
        echo -e "\n${C_RED}❌ That doesn't look like a valid certificate (PEM).${C_RESET}"
        rm -f "$tmp_chain" "$tmp_key"; return
    fi
    if ! openssl pkey -in "$tmp_key" -noout 2>/dev/null; then
        echo -e "\n${C_RED}❌ That doesn't look like a valid private key (PEM).${C_RESET}"
        rm -f "$tmp_chain" "$tmp_key"; return
    fi
    if ! _fm_edge_cert_pair_matches "$tmp_chain" "$tmp_key"; then
        echo -e "\n${C_RED}❌ The certificate and private key don't match each other.${C_RESET}"
        rm -f "$tmp_chain" "$tmp_key"; return
    fi

    mv "$tmp_chain" "$SSL_CERT_CHAIN_FILE"
    mv "$tmp_key" "$SSL_CERT_KEY_FILE"
    if ! build_shared_tls_bundle; then
        echo -e "\n${C_RED}❌ Failed to build the certificate bundle.${C_RESET}"
        return
    fi
    save_edge_cert_info "imported" "$domain_name" ""

    configure_edge_stack "$domain_name" || return
    echo -e "\n${C_GREEN}✅ Imported certificate applied successfully.${C_RESET}"
}

# Point at certificate files ALREADY on this server's disk (e.g. one a
# different script issued, or one restored/copied in manually) — copies
# them in place of the shared one; nothing is issued, downloaded, or typed.
import_edge_cert_path() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📁 Use a Certificate Already on This Server ---${C_RESET}"
    echo -e "${C_DIM}Point at certificate files already present here — nothing is issued or downloaded.${C_RESET}\n"

    mkdir -p "$DB_DIR" "$SSL_CERT_DIR"
    load_edge_cert_info

    local chain_path key_path
    read -p "👉 Full path to the certificate/fullchain file: " chain_path
    read -p "👉 Full path to the private key file: " key_path

    if [[ ! -s "$chain_path" ]]; then
        echo -e "\n${C_RED}❌ File not found or empty: $chain_path${C_RESET}"; return
    fi
    if [[ ! -s "$key_path" ]]; then
        echo -e "\n${C_RED}❌ File not found or empty: $key_path${C_RESET}"; return
    fi
    if ! openssl x509 -in "$chain_path" -noout 2>/dev/null; then
        echo -e "\n${C_RED}❌ That doesn't look like a valid certificate (PEM): $chain_path${C_RESET}"; return
    fi
    if ! openssl pkey -in "$key_path" -noout 2>/dev/null; then
        echo -e "\n${C_RED}❌ That doesn't look like a valid private key (PEM): $key_path${C_RESET}"; return
    fi
    if ! _fm_edge_cert_pair_matches "$chain_path" "$key_path"; then
        echo -e "\n${C_RED}❌ The certificate and private key don't match each other.${C_RESET}"; return
    fi

    local preferred_host default_domain domain_name
    preferred_host=$(detect_preferred_host)
    default_domain=$(openssl x509 -in "$chain_path" -noout -subject 2>/dev/null | grep -oP 'CN\s*=\s*\K[^,/]+' | head -1)
    [[ -z "$default_domain" ]] && default_domain="${EDGE_DOMAIN:-$preferred_host}"
    read -p "👉 Domain / label this certificate is for [$default_domain]: " domain_name
    domain_name=${domain_name:-$default_domain}

    cp "$chain_path" "$SSL_CERT_CHAIN_FILE"
    cp "$key_path" "$SSL_CERT_KEY_FILE"
    if ! build_shared_tls_bundle; then
        echo -e "\n${C_RED}❌ Failed to build the certificate bundle.${C_RESET}"
        return
    fi
    save_edge_cert_info "imported-path" "$domain_name" ""

    configure_edge_stack "$domain_name" || return
    echo -e "\n${C_GREEN}✅ Certificate at ${C_YELLOW}$chain_path${C_GREEN} applied successfully.${C_RESET}"
}

delete_edge_ssl_cert() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🗑️ Delete the Shared Certificate ---${C_RESET}\n"

    load_edge_cert_info
    if [[ ! -s "$SSL_CERT_CHAIN_FILE" && ! -s "$SSL_CERT_KEY_FILE" ]]; then
        echo -e "${C_YELLOW}ℹ️ No shared certificate is currently installed.${C_RESET}"
        return
    fi

    local current_label="${EDGE_CERT_MODE:-existing}"
    [[ -n "$EDGE_DOMAIN" ]] && current_label="$current_label - $EDGE_DOMAIN"
    echo -e "${C_DIM}Current certificate: ${C_YELLOW}$current_label${C_RESET}"
    echo -e "${C_RED}⚠️  HAProxy's TLS port (${EDGE_PUBLIC_TLS_PORT}) will stop working until a new certificate is added.${C_RESET}\n"

    read -p "👉 Are you sure you want to delete it? (y/n): " confirm
    if [[ "${confirm,,}" != "y" ]]; then
        echo -e "\n${C_YELLOW}❌ Cancelled.${C_RESET}"
        return
    fi

    rm -f "$SSL_CERT_CHAIN_FILE" "$SSL_CERT_KEY_FILE" "$SSL_CERT_FILE" "$EDGE_CERT_INFO_FILE"
    echo -e "\n${C_GREEN}✅ Certificate deleted.${C_RESET}"

    read -p "👉 Generate a temporary self-signed certificate now so the edge stack keeps working? (y/n) [y]: " gen_temp
    gen_temp=${gen_temp:-y}
    if [[ "${gen_temp,,}" == "y" ]]; then
        local preferred_host
        preferred_host=$(detect_preferred_host)
        [[ -z "$preferred_host" ]] && preferred_host="firewallfalcon.local"
        generate_self_signed_edge_cert "$preferred_host" || return
        configure_edge_stack "$preferred_host" || return
        echo -e "${C_GREEN}✅ Temporary self-signed certificate applied.${C_RESET}"
    fi
}

# Groups every way to get/manage the shared HAProxy+Nginx certificate
# behind one screen — was a single "Switch/Renew (Certbot)" entry in
# nginx_proxy_menu, now covers Certbot, importing one the admin already
# has (pasted or from a path already on this server), a fresh self-signed
# one, and deleting the current one.
edge_certificate_menu() {
    while true; do
        show_banner
        echo -e "${C_BOLD}${C_PURPLE}--- 🔒 Shared Certificate Management (HAProxy + Nginx) ---${C_RESET}\n"
        load_edge_cert_info
        local cert_info="${EDGE_CERT_MODE:-Not configured}"
        [[ -n "$EDGE_DOMAIN" ]] && cert_info="${cert_info} - ${EDGE_DOMAIN}"
        echo -e "${C_DIM}Current: ${C_YELLOW}${cert_info}${C_RESET}\n"

        printf "  ${C_CHOICE}[ 1]${C_RESET} %s\n" "$(pad_right '🔒 Get / Renew via Certbot (Free SSL)' 48)"
        printf "  ${C_CHOICE}[ 2]${C_RESET} %s\n" "$(pad_right '📋 Import an Existing Certificate (Paste)' 48)"
        printf "  ${C_CHOICE}[ 3]${C_RESET} %s\n" "$(pad_right '📁 Use a Certificate Already on This Server' 48)"
        printf "  ${C_CHOICE}[ 4]${C_RESET} %s\n" "$(pad_right '🔏 Generate a Self-Signed Certificate' 48)"
        printf "  ${C_DANGER}[ 5]${C_RESET} %s\n" "$(pad_right '🗑️ Delete the Shared Certificate' 48)"
        echo
        printf "  ${C_WARN}[ 0]${C_RESET} ↩️ Return\n"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"👉 Select an option: "${C_RESET})" cchoice; then
            echo; return
        fi
        case "$cchoice" in
            1) request_certbot_ssl; press_enter ;;
            2) import_edge_cert_paste; press_enter ;;
            3) import_edge_cert_path; press_enter ;;
            4)
                local preferred_host common_name
                preferred_host=$(detect_preferred_host)
                [[ -z "$preferred_host" ]] && preferred_host="firewallfalcon.local"
                read -p "👉 Certificate Common Name / SNI label [$preferred_host]: " common_name
                common_name=${common_name:-$preferred_host}
                mkdir -p "$SSL_CERT_DIR"
                generate_self_signed_edge_cert "$common_name" && configure_edge_stack "$common_name"
                press_enter
                ;;
            5) delete_edge_ssl_cert; press_enter ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

select_edge_certificate() {
    local preferred_host
    local cert_choice
    local has_existing_cert=false

    preferred_host=$(detect_preferred_host)
    if [[ -z "$preferred_host" ]]; then
        preferred_host="firewallfalcon.local"
    fi

    if [ -s "$SSL_CERT_FILE" ] && [ -s "$SSL_CERT_CHAIN_FILE" ] && [ -s "$SSL_CERT_KEY_FILE" ]; then
        has_existing_cert=true
    fi

    load_edge_cert_info

    echo -e "\n${C_BOLD}${C_PURPLE}--- 🔐 Shared TLS Certificate ---${C_RESET}"
    echo -e "${C_DIM}The same certificate will be used by HAProxy and the internal Nginx proxy.${C_RESET}"

    if $has_existing_cert; then
        local existing_label="${EDGE_CERT_MODE:-existing}"
        if [[ -n "$EDGE_DOMAIN" ]]; then
            existing_label="$existing_label - $EDGE_DOMAIN"
        fi
        printf "  ${C_CHOICE}[ 1]${C_RESET} %-52s\n" "Reuse existing certificate (${existing_label})"
        printf "  ${C_CHOICE}[ 2]${C_RESET} %-52s\n" "Replace with a new self-signed certificate"
        printf "  ${C_CHOICE}[ 3]${C_RESET} %-52s\n" "Replace with a Certbot certificate"
        echo
        read -p "👉 Enter choice [1]: " cert_choice
        cert_choice=${cert_choice:-1}
    else
        printf "  ${C_CHOICE}[ 1]${C_RESET} %-52s\n" "Generate a self-signed certificate"
        printf "  ${C_CHOICE}[ 2]${C_RESET} %-52s\n" "Use a Certbot certificate"
        echo
        read -p "👉 Enter choice [1]: " cert_choice
        cert_choice=${cert_choice:-1}
    fi

    case "$cert_choice" in
        1)
            if $has_existing_cert; then
                echo -e "${C_GREEN}✅ Reusing the existing shared certificate.${C_RESET}"
                return 0
            fi
            local common_name
            read -p "👉 Enter the certificate Common Name / SNI label [$preferred_host]: " common_name
            common_name=${common_name:-$preferred_host}
            generate_self_signed_edge_cert "$common_name"
            ;;
        2)
            if $has_existing_cert; then
                local common_name
                read -p "👉 Enter the certificate Common Name / SNI label [$preferred_host]: " common_name
                common_name=${common_name:-$preferred_host}
                generate_self_signed_edge_cert "$common_name"
            else
                local default_domain=""
                local domain_name
                local email
                if ! _is_valid_ipv4 "$preferred_host"; then
                    default_domain="$preferred_host"
                fi
                if [[ -n "$default_domain" ]]; then
                    read -p "👉 Enter your domain name [$default_domain]: " domain_name
                    domain_name=${domain_name:-$default_domain}
                else
                    read -p "👉 Enter your domain name (e.g. vpn.example.com): " domain_name
                fi
                if [[ -z "$domain_name" ]]; then
                    echo -e "${C_RED}❌ Domain name cannot be empty.${C_RESET}"
                    return 1
                fi
                if _is_valid_ipv4 "$domain_name"; then
                    echo -e "${C_RED}❌ Certbot requires a real domain name, not a raw IP address.${C_RESET}"
                    return 1
                fi
                read -p "👉 Enter your email for Let's Encrypt: " email
                if [[ -z "$email" ]]; then
                    echo -e "${C_RED}❌ Email cannot be empty.${C_RESET}"
                    return 1
                fi
                obtain_certbot_edge_cert "$domain_name" "$email"
            fi
            ;;
        3)
            if ! $has_existing_cert; then
                echo -e "${C_RED}❌ Invalid option.${C_RESET}"
                return 1
            fi
            local default_domain=""
            local domain_name
            local email
            if [[ -n "$EDGE_DOMAIN" ]] && ! _is_valid_ipv4 "$EDGE_DOMAIN"; then
                default_domain="$EDGE_DOMAIN"
            fi
            if [[ -z "$default_domain" ]] && ! _is_valid_ipv4 "$preferred_host"; then
                default_domain="$preferred_host"
            fi
            if [[ -n "$default_domain" ]]; then
                read -p "👉 Enter your domain name [$default_domain]: " domain_name
                domain_name=${domain_name:-$default_domain}
            else
                read -p "👉 Enter your domain name (e.g. vpn.example.com): " domain_name
            fi
            if [[ -z "$domain_name" ]]; then
                echo -e "${C_RED}❌ Domain name cannot be empty.${C_RESET}"
                return 1
            fi
            if _is_valid_ipv4 "$domain_name"; then
                echo -e "${C_RED}❌ Certbot requires a real domain name, not a raw IP address.${C_RESET}"
                return 1
            fi
            read -p "👉 Enter your email for Let's Encrypt [${EDGE_EMAIL}]: " email
            email=${email:-$EDGE_EMAIL}
            if [[ -z "$email" ]]; then
                echo -e "${C_RED}❌ Email cannot be empty.${C_RESET}"
                return 1
            fi
            obtain_certbot_edge_cert "$domain_name" "$email"
            ;;
        *)
            echo -e "${C_RED}❌ Invalid option.${C_RESET}"
            return 1
            ;;
    esac
}

# Renders the optional fixed named-path locations (e.g. "/vless ->
# 127.0.0.1:39117") from $EDGE_NAMED_PATHS_FILE. Same proxy settings as the
# generic /<port>/ location, just addressed by a literal name instead of a
# captured number, and with no location-prefix stripped from the upstream
# request (matching how the generic one already forwards $is_args$args
# without touching the path itself).
_fm_edge_render_named_paths() {
    local name port
    [[ -f "$EDGE_NAMED_PATHS_FILE" ]] || return 0
    while read -r name port; do
        [[ -z "$name" || -z "$port" ]] && continue
        cat <<EOF

    location /${name} {
        client_max_body_size 0;
        proxy_read_timeout 1d;
        proxy_http_version 1.1;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_pass http://127.0.0.1:${port};
    }
EOF
    done < "$EDGE_NAMED_PATHS_FILE"
}

write_internal_nginx_config() {
    local server_name="$1"
    [[ -z "$server_name" ]] && server_name="_"
    local named_path_locations; named_path_locations=$(_fm_edge_render_named_paths)
    mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled
    cat > "$NGINX_CONFIG_FILE" <<EOF
server {
    listen 127.0.0.1:${NGINX_INTERNAL_HTTP_PORT} default_server;
    # Deliberately no "http2" here. If it's on and the client's ALPN offers
    # h2, this negotiates HTTP/2 with a client expecting a plain HTTP/1.1
    # WebSocket-style Upgrade — HTTP/2 doesn't have that mechanism at all
    # (a "101" status is meaningless there), so the connection breaks right
    # after the TLS handshake. Never enabling it here means ALPN
    # negotiation always settles on http/1.1 instead, regardless of what
    # the client also offers, and Upgrade-based traffic (V2Ray/WS in
    # particular) works unconditionally. Trade-off: gRPC transport (which
    # requires HTTP/2) won't work through this listener — SSH and OpenVPN
    # never route through it either way, so neither is affected.
    listen 127.0.0.1:${NGINX_INTERNAL_TLS_PORT} ssl default_server;
    server_tokens off;
    server_name ${server_name};

    ssl_certificate ${SSL_CERT_CHAIN_FILE};
    ssl_certificate_key ${SSL_CERT_KEY_FILE};
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!eNULL:!MD5:!DES:!RC4:!ADH:!SSLv3:!EXP:!PSK:!DSS;
    resolver 1.1.1.1 8.8.8.8 ipv6=off valid=300s;

    location ~ ^/(?<fwdport>\d+)/(?<fwdpath>.*)$ {
        client_max_body_size 0;
        client_body_timeout 1d;
        grpc_read_timeout 1d;
        grpc_socket_keepalive on;
        proxy_read_timeout 1d;
        proxy_http_version 1.1;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_socket_keepalive on;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        if (\$content_type ~* "GRPC") { grpc_pass grpc://127.0.0.1:\$fwdport\$is_args\$args; break; }
        proxy_pass http://127.0.0.1:\$fwdport\$is_args\$args;
        break;
    }
${named_path_locations}
    location / {
        proxy_read_timeout 3600s;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_http_version 1.1;
        proxy_socket_keepalive on;
        tcp_nodelay on;
        tcp_nopush off;
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
    }
}
EOF
    ln -sf "$NGINX_CONFIG_FILE" /etc/nginx/sites-enabled/default
}

# Lightweight add/remove for a single named path — unlike Reinstall/
# Reconfigure, this never touches the domain, certificate, or OpenVPN
# setup: it only edits $EDGE_NAMED_PATHS_FILE and regenerates+reloads the
# internal Nginx config. Requires Nginx to already be active (the edge
# stack must already be installed).
_fm_edge_add_named_path_interactive() {
    if ! systemctl is-active --quiet nginx; then
        echo -e "\n${C_YELLOW}⚠️ Nginx isn't active — install/configure the edge stack first.${C_RESET}"
        return
    fi
    local path_name path_port
    read -p "👉 Path name (e.g. vless, no slashes): " path_name
    path_name="${path_name#/}"; path_name="${path_name%/}"
    if [[ -z "$path_name" ]] || [[ "$path_name" =~ ^[0-9]+$ ]] || [[ "$path_name" =~ [/[:space:]] ]]; then
        echo -e "\n${C_RED}❌ Invalid name (no slashes/spaces, and not purely numeric — numeric paths already work via /<port>/).${C_RESET}"
        return
    fi
    if grep -qE "^${path_name} " "$EDGE_NAMED_PATHS_FILE" 2>/dev/null; then
        echo -e "\n${C_YELLOW}⚠️ /${path_name}/ already exists — remove it first if you want to point it elsewhere.${C_RESET}"
        return
    fi
    read -p "👉 Local port to forward /${path_name}/ to: " path_port
    if ! [[ "$path_port" =~ ^[0-9]+$ ]]; then
        echo -e "\n${C_RED}❌ Invalid port.${C_RESET}"
        return
    fi
    echo "${path_name} ${path_port}" >> "$EDGE_NAMED_PATHS_FILE"
    load_edge_cert_info
    write_internal_nginx_config "${EDGE_DOMAIN:-_}"
    if ! nginx -t >/dev/null 2>&1; then
        echo -e "\n${C_RED}❌ Nginx config validation failed after adding the path — reverting.${C_RESET}"
        sed -i '$d' "$EDGE_NAMED_PATHS_FILE"
        write_internal_nginx_config "${EDGE_DOMAIN:-_}"
        return
    fi
    _fm_safe_restart_nginx
    if systemctl is-active --quiet nginx; then
        echo -e "\n${C_GREEN}✅ /${path_name}/ now forwards to 127.0.0.1:${path_port} — works on both 80 and 443 right away.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Nginx failed to restart after adding the path. Check: journalctl -u nginx -n 15${C_RESET}"
    fi
}

_fm_edge_remove_named_path_interactive() {
    if [[ ! -s "$EDGE_NAMED_PATHS_FILE" ]]; then
        echo -e "\n${C_YELLOW}⚠️ No named paths configured.${C_RESET}"
        return
    fi
    echo -e "\n${C_CYAN}Current named paths:${C_RESET}"
    awk '{print "   /"$1"/ -> 127.0.0.1:"$2}' "$EDGE_NAMED_PATHS_FILE"
    local path_name
    read -p "👉 Path name to remove: " path_name
    path_name="${path_name#/}"; path_name="${path_name%/}"
    if ! grep -qE "^${path_name} " "$EDGE_NAMED_PATHS_FILE" 2>/dev/null; then
        echo -e "\n${C_RED}❌ /${path_name}/ isn't configured.${C_RESET}"
        return
    fi
    grep -vE "^${path_name} " "$EDGE_NAMED_PATHS_FILE" > "${EDGE_NAMED_PATHS_FILE}.tmp" 2>/dev/null
    mv "${EDGE_NAMED_PATHS_FILE}.tmp" "$EDGE_NAMED_PATHS_FILE"
    load_edge_cert_info
    write_internal_nginx_config "${EDGE_DOMAIN:-_}"
    if ! nginx -t >/dev/null 2>&1; then
        echo -e "\n${C_RED}❌ Nginx config validation failed after removing the path.${C_RESET}"
        return
    fi
    _fm_safe_restart_nginx
    if systemctl is-active --quiet nginx; then
        echo -e "\n${C_GREEN}✅ /${path_name}/ removed.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Nginx failed to restart after removing the path. Check: journalctl -u nginx -n 15${C_RESET}"
    fi
}

_fm_edge_load_ovpn_port() {
    EDGE_OVPN_PORT=""
    [[ -f "$EDGE_OVPN_PORT_FILE" ]] && source "$EDGE_OVPN_PORT_FILE" 2>/dev/null
}

_fm_edge_write_ovpn_ws_script() {
    cat > "$EDGE_OVPN_WS_SCRIPT" <<'EOF'
#!/usr/bin/env python3
import socket, sys, threading, hashlib, base64

WS_GUID = b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

def pipe(a, b):
    try:
        while True:
            data = a.recv(4096)
            if not data:
                break
            b.sendall(data)
    except Exception:
        pass
    finally:
        for s in (a, b):
            try:
                s.close()
            except Exception:
                pass

def handle(c, target_port):
    buf = b""
    try:
        while b"\r\n\r\n" not in buf and len(buf) < 8192:
            chunk = c.recv(1)
            if not chunk:
                c.close()
                return
            buf += chunk
    except Exception:
        c.close()
        return

    ws_key = None
    for line in buf.split(b"\r\n"):
        if line.lower().startswith(b"sec-websocket-key:"):
            ws_key = line.split(b":", 1)[1].strip()
            break

    try:
        target = socket.create_connection(("127.0.0.1", target_port), timeout=5)
    except Exception:
        try:
            c.sendall(b"HTTP/1.1 502 Bad Gateway\r\n\r\n")
        except Exception:
            pass
        c.close()
        return

    resp = b"HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
    if ws_key:
        accept = base64.b64encode(hashlib.sha1(ws_key + WS_GUID).digest())
        resp += b"Sec-WebSocket-Accept: " + accept + b"\r\n"
    resp += b"\r\n"
    try:
        c.sendall(resp)
    except Exception:
        c.close()
        target.close()
        return

    threading.Thread(target=pipe, args=(c, target), daemon=True).start()
    threading.Thread(target=pipe, args=(target, c), daemon=True).start()

def main():
    listen_port = int(sys.argv[1])
    target_port = int(sys.argv[2])
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("127.0.0.1", listen_port))
    s.listen(128)
    while True:
        c, _ = s.accept()
        threading.Thread(target=handle, args=(c, target_port), daemon=True).start()

if __name__ == "__main__":
    main()
EOF
    chmod +x "$EDGE_OVPN_WS_SCRIPT"
}

_fm_edge_write_ovpn_ws_service() {
    local target_port="$1"
    cat > "$EDGE_OVPN_WS_SERVICE_FILE" <<EOF
[Unit]
Description=DAHOOM HAProxy Edge OpenVPN WebSocket bridge
After=network.target

[Service]
ExecStart=/usr/bin/python3 ${EDGE_OVPN_WS_SCRIPT} ${EDGE_OVPN_WS_PORT} ${target_port}
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
}

# Same detection technique as the WS bridge above, but for OpenVPN clients
# whose "payload" mode wraps the connection in a plain decoy HTTP request
# with no special path — indistinguishable, at HAProxy's own ACL level,
# from ordinary web/V2Ray traffic, since OpenVPN's signature lands after
# the decoy bytes instead of at the very start of the connection. This
# sits in front of nginx_cleartext's real target: whole-buffer scan for
# OpenVPN's signature (not just a fixed offset), forward a match straight
# to OpenVPN, and pass everything else through to nginx completely
# unchanged. A fresh, independent copy — deliberately NOT shared with the
# Net Relay OpenVPN sniffer or the SOCKS/Websocket Proxy scripts, so this
# never risks touching anything already relied upon elsewhere.
_fm_edge_write_http_ovpn_sniffer_script() {
    cat > "$EDGE_HTTP_OVPN_SNIFFER_SCRIPT" <<'EOF'
#!/usr/bin/env python3
import socket, sys, threading

def pipe(a, b):
    try:
        while True:
            data = a.recv(4096)
            if not data:
                break
            b.sendall(data)
    except Exception:
        pass
    finally:
        for s in (a, b):
            try:
                s.close()
            except Exception:
                pass

def read_available(c, max_bytes, timeout):
    # Buffers whatever arrives within the window rather than stopping at
    # the first few bytes — a decoy HTTP-looking request sent first, with
    # OpenVPN's real opening bytes right behind it in the same burst, only
    # ever turns up if the whole window is scanned instead of just byte 0.
    c.settimeout(timeout)
    buf = b""
    try:
        while len(buf) < max_bytes:
            chunk = c.recv(max_bytes - len(buf))
            if not chunk:
                break
            buf += chunk
    except Exception:
        pass
    finally:
        c.settimeout(None)
    return buf

def contains_ovpn_open(buf):
    # A 2-byte big-endian length prefix short enough that its high byte is
    # 0x00, followed by an opcode byte whose top 5 bits are 7
    # (P_CONTROL_HARD_RESET_CLIENT_V2, any key_id) — same signature used
    # everywhere else in DAHOOM. A literal 0x00 byte essentially never
    # appears in ordinary HTTP/web/V2Ray traffic, so scanning the whole
    # buffer for it stays a safe, low false-positive check.
    for i in range(len(buf) - 2):
        if buf[i] == 0 and (buf[i + 2] & 0xF8) == 0x38:
            return True
    return False

def handle(c, ovpn_port, default_host, default_port):
    # A short peek window: OpenVPN's opening bytes (direct or behind a
    # decoy, sent as one burst) always arrive within milliseconds of the
    # TCP handshake, so this never adds a meaningful delay in front of the
    # ordinary web/V2Ray traffic that makes up the rest of this bucket.
    peek = read_available(c, 4096, 0.3)
    if contains_ovpn_open(peek):
        target_host, target_port = "127.0.0.1", ovpn_port
    else:
        target_host, target_port = default_host, default_port
    try:
        target = socket.create_connection((target_host, target_port), timeout=5)
    except Exception:
        c.close()
        return
    try:
        if peek:
            target.sendall(peek)
    except Exception:
        c.close()
        target.close()
        return
    threading.Thread(target=pipe, args=(c, target), daemon=True).start()
    threading.Thread(target=pipe, args=(target, c), daemon=True).start()

def main():
    listen_port = int(sys.argv[1])
    ovpn_port = int(sys.argv[2])
    default_host, default_port = sys.argv[3].split(":", 1)
    default_port = int(default_port)
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("127.0.0.1", listen_port))
    s.listen(128)
    while True:
        c, _ = s.accept()
        threading.Thread(target=handle, args=(c, ovpn_port, default_host, default_port), daemon=True).start()

if __name__ == "__main__":
    main()
EOF
    chmod +x "$EDGE_HTTP_OVPN_SNIFFER_SCRIPT"
}

_fm_edge_write_http_ovpn_sniffer_service() {
    local ovpn_port="$1" default_backend="$2"
    cat > "$EDGE_HTTP_OVPN_SNIFFER_SERVICE_FILE" <<EOF
[Unit]
Description=DAHOOM HAProxy Edge OpenVPN sniffer (decoy-wrapped, no special path)
After=network.target

[Service]
ExecStart=/usr/bin/python3 ${EDGE_HTTP_OVPN_SNIFFER_SCRIPT} ${EDGE_HTTP_OVPN_SNIFFER_PORT} ${ovpn_port} ${default_backend}
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
}

write_haproxy_edge_config() {
    mkdir -p /etc/haproxy
    _fm_edge_load_ovpn_port
    # OpenVPN-over-TCP's opening control packet (P_CONTROL_HARD_RESET_
    # CLIENT_V2) has its own distinctive byte signature — same technique
    # and same real packet capture already used to detect it in the Nginx
    # Multiplexer's njs script: a 2-byte big-endian length prefix (short
    # enough that its high byte is 0x00) followed by an opcode byte whose
    # top 5 bits are 7 (byte & 0xF8 == 0x38). HAProxy's own payload() ACL
    # can check this directly, no external module needed. Only one
    # specific OpenVPN instance can be reached this way — same limit as
    # raw SSH — since every instance's opening bytes look identical.
    local ovpn_acl_lines="" ovpn_accept_80="" ovpn_use_80="" ovpn_accept_443="" ovpn_use_443="" ovpn_backend=""
    # nginx_cleartext carries every "looks like HTTP, not real TLS" edge
    # connection — real web/V2Ray traffic AND a decoy-wrapped OpenVPN
    # client alike, since the raw ACLs above only catch OpenVPN at a fixed
    # offset. With an OpenVPN edge port configured, this backend's target
    # moves from nginx directly to the sniffer that tells the two apart;
    # with none configured, it's untouched — same target as always.
    local nginx_cleartext_target="$NGINX_INTERNAL_HTTP_PORT"
    if [[ -n "$EDGE_OVPN_PORT" ]]; then
        ovpn_acl_lines=$'    acl is_ovpn_len payload(0,1) -m bin 00\n    acl is_ovpn_op payload(2,1) -m bin 38'
        ovpn_accept_80="    tcp-request content accept if is_ovpn_len is_ovpn_op"
        ovpn_use_80="    use_backend direct_ovpn if is_ovpn_len is_ovpn_op"
        ovpn_accept_443="$ovpn_accept_80"
        ovpn_use_443="$ovpn_use_80"
        ovpn_backend=$'\nbackend direct_ovpn\n    mode tcp\n    server ovpn_server 127.0.0.1:'"${EDGE_OVPN_PORT}"
        nginx_cleartext_target="$EDGE_HTTP_OVPN_SNIFFER_PORT"
    fi
    cat > "$HAPROXY_CONFIG" <<EOF
global
    log /dev/log local0
    log /dev/log local1 notice
    chroot /var/lib/haproxy
    stats socket /run/haproxy/admin.sock mode 660 level admin expose-fd listeners
    stats timeout 30s
    user haproxy
    group haproxy
    daemon

defaults
    log     global
    mode    tcp
    option  tcplog
    option  dontlognull
    timeout connect 5s
    timeout client  24h
    timeout server  24h

# ====================================================================
# TIER 1: PORT ${EDGE_PUBLIC_HTTP_PORT} (Cleartext Payloads & Raw SSH)
# ====================================================================
frontend port_80_edge
    bind *:${EDGE_PUBLIC_HTTP_PORT}
    mode tcp
    tcp-request inspect-delay 2s

    acl is_ssh payload(0,7) -m bin 5353482d322e30
${ovpn_acl_lines}

    tcp-request content accept if is_ssh
${ovpn_accept_80}
    tcp-request content accept if HTTP

    use_backend direct_ssh if is_ssh
${ovpn_use_80}
    default_backend nginx_cleartext

# ====================================================================
# TIER 1: PORT ${EDGE_PUBLIC_TLS_PORT} (TLS v2ray, SSL Payloads, Raw SSH)
# ====================================================================
frontend port_443_edge
    bind *:${EDGE_PUBLIC_TLS_PORT}
    mode tcp
    tcp-request inspect-delay 2s

    acl is_ssh payload(0,7) -m bin 5353482d322e30
${ovpn_acl_lines}
    acl is_tls req.ssl_hello_type 1
    acl has_web_alpn req.ssl_alpn -m sub h2 http/1.1

    tcp-request content accept if is_ssh
${ovpn_accept_443}
    tcp-request content accept if HTTP
    tcp-request content accept if is_tls

    use_backend direct_ssh if is_ssh
${ovpn_use_443}
    use_backend nginx_cleartext if HTTP
    use_backend nginx_tls if is_tls has_web_alpn
    default_backend loopback_ssl_terminator

# ====================================================================
# TIER 2: INTERNAL DECRYPTOR (Only for Any-SNI SSH-TLS)
# ====================================================================
frontend internal_decryptor
    bind 127.0.0.1:${HAPROXY_INTERNAL_DECRYPT_PORT} ssl crt ${SSL_CERT_FILE}
    mode tcp
    tcp-request inspect-delay 2s

    acl is_ssh payload(0,7) -m bin 5353482d322e30
${ovpn_acl_lines}
    tcp-request content accept if is_ssh
${ovpn_accept_80}
    tcp-request content accept if HTTP

    use_backend direct_ssh if is_ssh
${ovpn_use_80}
    default_backend nginx_cleartext

# ====================================================================
# DESTINATION BACKENDS (Clean handoffs, no proxy headers)
# ====================================================================
backend direct_ssh
    mode tcp
    server ssh_server 127.0.0.1:22

backend nginx_cleartext
    mode tcp
    server nginx_8880 127.0.0.1:${nginx_cleartext_target}

backend nginx_tls
    mode tcp
    server nginx_8443 127.0.0.1:${NGINX_INTERNAL_TLS_PORT}

backend loopback_ssl_terminator
    mode tcp
    server haproxy_ssl 127.0.0.1:${HAPROXY_INTERNAL_DECRYPT_PORT}
${ovpn_backend}
EOF
}

save_edge_ports_info() {
    cat > "$NGINX_PORTS_FILE" <<EOF
EDGE_HTTP_PORT="${EDGE_PUBLIC_HTTP_PORT}"
EDGE_TLS_PORT="${EDGE_PUBLIC_TLS_PORT}"
HTTP_PORTS="${NGINX_INTERNAL_HTTP_PORT}"
TLS_PORTS="${NGINX_INTERNAL_TLS_PORT}"
EOF
}

configure_edge_stack() {
    local server_name="$1"
    [[ -z "$server_name" ]] && server_name="_"

    backup_edge_configs

    echo -e "\n${C_BLUE}📝 Writing internal Nginx config (127.0.0.1:${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT})...${C_RESET}"
    write_internal_nginx_config "$server_name"

    echo -e "${C_BLUE}📝 Writing HAProxy edge config (${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT})...${C_RESET}"
    write_haproxy_edge_config

    echo -e "\n${C_BLUE}🧪 Validating Nginx configuration...${C_RESET}"
    if ! nginx -t >/dev/null 2>&1; then
        echo -e "${C_RED}❌ Nginx configuration validation failed.${C_RESET}"
        nginx -t
        return 1
    fi

    echo -e "${C_BLUE}🧪 Validating HAProxy configuration...${C_RESET}"
    if ! haproxy -c -f "$HAPROXY_CONFIG" >/dev/null 2>&1; then
        echo -e "${C_RED}❌ HAProxy configuration validation failed.${C_RESET}"
        haproxy -c -f "$HAPROXY_CONFIG"
        return 1
    fi

    systemctl daemon-reload
    systemctl enable nginx >/dev/null 2>&1
    systemctl enable haproxy >/dev/null 2>&1

    echo -e "\n${C_BLUE}▶️ Restarting internal Nginx...${C_RESET}"
    _fm_safe_restart_nginx || {
        echo -e "${C_RED}❌ Nginx failed to restart.${C_RESET}"
        systemctl status nginx --no-pager
        return 1
    }

    echo -e "${C_BLUE}▶️ Restarting HAProxy edge...${C_RESET}"
    systemctl restart haproxy || {
        echo -e "${C_RED}❌ HAProxy failed to restart.${C_RESET}"
        systemctl status haproxy --no-pager
        return 1
    }

    sleep 2
    if ! systemctl is-active --quiet nginx; then
        echo -e "${C_RED}❌ Nginx is not active after restart.${C_RESET}"
        systemctl status nginx --no-pager
        return 1
    fi
    if ! systemctl is-active --quiet haproxy; then
        echo -e "${C_RED}❌ HAProxy is not active after restart.${C_RESET}"
        systemctl status haproxy --no-pager
        return 1
    fi

    save_edge_ports_info
    return 0
}

install_ssl_tunnel() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Installing HAProxy Edge Stack (80/443 -> 8880/8443) ---${C_RESET}"
    echo -e "\n${C_CYAN}This installer will configure:${C_RESET}"
    echo -e "   • HAProxy on ${C_WHITE}${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT}${C_RESET}"
    echo -e "   • Internal Nginx on ${C_WHITE}${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}${C_RESET}"
    echo -e "   • Loopback SSL decryptor on ${C_WHITE}${HAPROXY_INTERNAL_DECRYPT_PORT}${C_RESET}"

    if [ -f "$HAPROXY_CONFIG" ] || [ -f "$NGINX_CONFIG_FILE" ]; then
        echo -e "\n${C_YELLOW}⚠️ Existing HAProxy/Nginx configs will be replaced with the DAHOOM edge layout.${C_RESET}"
        read -p "👉 Continue with the replacement? (y/n): " confirm_replace
        if [[ "$confirm_replace" != "y" && "$confirm_replace" != "Y" ]]; then
            echo -e "${C_RED}❌ Installation cancelled.${C_RESET}"
            return
        fi
    fi

    mkdir -p "$DB_DIR" "$SSL_CERT_DIR"

    ensure_edge_stack_packages || return

    systemctl stop haproxy >/dev/null 2>&1
    systemctl stop nginx >/dev/null 2>&1
    sleep 1

    check_and_free_ports \
        "$EDGE_PUBLIC_HTTP_PORT" \
        "$EDGE_PUBLIC_TLS_PORT" \
        "$NGINX_INTERNAL_HTTP_PORT" \
        "$NGINX_INTERNAL_TLS_PORT" \
        "$HAPROXY_INTERNAL_DECRYPT_PORT" || return

    check_and_open_firewall_port "$EDGE_PUBLIC_HTTP_PORT" tcp || return
    check_and_open_firewall_port "$EDGE_PUBLIC_TLS_PORT" tcp || return

    select_edge_certificate || return

    load_edge_cert_info
    local server_name="${EDGE_DOMAIN:-$(detect_preferred_host)}"
    [[ -z "$server_name" ]] && server_name="_"

    _fm_edge_load_ovpn_port
    local ovpn_port keep_named path_name path_port
    echo -e "${C_DIM}Only ONE OpenVPN instance can share the edge (its opening packet looks identical to any other instance's) — it MUST be configured for TCP, not UDP.${C_RESET}"
    read -p "👉 OpenVPN backend port (TCP only) — leave empty to skip [${EDGE_OVPN_PORT}]: " ovpn_port
    ovpn_port=${ovpn_port:-$EDGE_OVPN_PORT}
    if [[ -n "$ovpn_port" ]] && ! [[ "$ovpn_port" =~ ^[0-9]+$ ]]; then
        echo -e "${C_RED}❌ Invalid port.${C_RESET}"; return
    fi
    echo "EDGE_OVPN_PORT=\"$ovpn_port\"" > "$EDGE_OVPN_PORT_FILE"

    # Optional fixed named-path routes (like "/vless") for the internal
    # Nginx, alongside the generic "/<port>/path" one above — some V2Ray
    # clients behave more predictably against a fixed, named path.
    if [[ -s "$EDGE_NAMED_PATHS_FILE" ]]; then
        echo -e "\n${C_CYAN}Existing named paths:${C_RESET}"
        awk '{print "   /"$1" -> 127.0.0.1:"$2}' "$EDGE_NAMED_PATHS_FILE"
        read -p "👉 Keep these as-is? (y/n) [y]: " keep_named
    else
        keep_named="n"
    fi
    if [[ "$keep_named" == "n" || "$keep_named" == "N" ]]; then
        : > "$EDGE_NAMED_PATHS_FILE"
        echo -e "${C_DIM}Add fixed named-path routes for the internal Nginx (e.g. vless -> 39117), one at a time. Leave the name empty when done.${C_RESET}"
        while true; do
            read -p "👉 Path name (e.g. vless), or empty to finish: " path_name
            [[ -z "$path_name" ]] && break
            path_name="${path_name#/}"; path_name="${path_name%/}"
            if [[ -z "$path_name" ]] || [[ "$path_name" =~ ^[0-9]+$ ]] || [[ "$path_name" =~ [/[:space:]] ]]; then
                echo -e "${C_RED}❌ Invalid name (no slashes/spaces, and not purely numeric — numeric paths already work via /<port>/).${C_RESET}"
                continue
            fi
            read -p "👉 Local port to forward /${path_name} to: " path_port
            if ! [[ "$path_port" =~ ^[0-9]+$ ]]; then
                echo -e "${C_RED}❌ Invalid port.${C_RESET}"
                continue
            fi
            echo "${path_name} ${path_port}" >> "$EDGE_NAMED_PATHS_FILE"
        done
    fi

    configure_edge_stack "$server_name" || return

    # The direct/raw OpenVPN edge above only catches native, unwrapped
    # OpenVPN-over-TCP. Clients whose "payload"/"SNI"/"websocket" mode
    # wraps the connection in an HTTP-looking handshake need this separate
    # bridge instead — nginx's existing "/<port>/path" forwarding can't
    # reach OpenVPN's own port directly since OpenVPN never speaks HTTP.
    if [[ -n "$ovpn_port" ]]; then
        _fm_edge_write_ovpn_ws_script
        _fm_edge_write_ovpn_ws_service "$ovpn_port"
        systemctl daemon-reload
        systemctl enable dahoom-edge-ovpn-ws.service >/dev/null 2>&1
        systemctl restart dahoom-edge-ovpn-ws.service
    else
        systemctl stop dahoom-edge-ovpn-ws.service >/dev/null 2>&1
        systemctl disable dahoom-edge-ovpn-ws.service >/dev/null 2>&1
    fi

    # Covers the OTHER OpenVPN client shape: a decoy plain-HTTP wrapper
    # with no special path at all, indistinguishable from ordinary
    # web/V2Ray traffic at HAProxy's own ACL level. write_haproxy_edge_config
    # already pointed nginx_cleartext at this sniffer above (since
    # EDGE_OVPN_PORT is now set); this just brings the sniffer itself up.
    if [[ -n "$ovpn_port" ]]; then
        check_and_free_ports "$EDGE_HTTP_OVPN_SNIFFER_PORT" || return
        _fm_edge_write_http_ovpn_sniffer_script
        _fm_edge_write_http_ovpn_sniffer_service "$ovpn_port" "127.0.0.1:${NGINX_INTERNAL_HTTP_PORT}"
        systemctl daemon-reload
        systemctl enable dahoom-edge-http-ovpn-sniffer.service >/dev/null 2>&1
        systemctl restart dahoom-edge-http-ovpn-sniffer.service
    else
        systemctl stop dahoom-edge-http-ovpn-sniffer.service >/dev/null 2>&1
        systemctl disable dahoom-edge-http-ovpn-sniffer.service >/dev/null 2>&1
        rm -f "$EDGE_HTTP_OVPN_SNIFFER_SERVICE_FILE" "$EDGE_HTTP_OVPN_SNIFFER_SCRIPT"
    fi

    echo -e "\n${C_GREEN}✅ SUCCESS: HAProxy edge stack is active.${C_RESET}"
    echo -e "   • Public edge ports: ${C_YELLOW}${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT}${C_RESET}"
    if [[ -n "$ovpn_port" ]]; then
        echo -e "   • OpenVPN (TCP) on the edge, direct/raw mode: reaches ${C_YELLOW}127.0.0.1:${ovpn_port}${C_RESET}."
        echo -e "   • OpenVPN via a payload/SNI/websocket client mode: set the request path to ${C_YELLOW}/${EDGE_OVPN_WS_PORT}/${C_RESET} (not the OpenVPN port itself)."
        echo -e "   • OpenVPN via a payload client mode with NO special path (plain decoy wrapper): works automatically now on 80/443 — nothing to set in the client beyond the domain/port."
    fi
    echo -e "   • Internal Nginx ports: ${C_YELLOW}${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}${C_RESET}"
    echo -e "   • Shared certificate: ${C_YELLOW}${EDGE_CERT_MODE:-unknown}${C_RESET}"
    if [[ -s "$EDGE_NAMED_PATHS_FILE" ]]; then
        echo -e "   • Named paths (80/443):"
        awk -v c="$C_YELLOW" -v r="$C_RESET" '{print "       " c "/"$1"/" r " -> 127.0.0.1:"$2}' "$EDGE_NAMED_PATHS_FILE"
    fi
}

uninstall_ssl_tunnel() {
    echo -e "\n${C_BOLD}${C_PURPLE}--- 🗑️ Uninstalling HAProxy Edge Stack ---${C_RESET}"
    if ! command -v haproxy &> /dev/null; then
        echo -e "${C_YELLOW}ℹ️ HAProxy is not installed, skipping service removal.${C_RESET}"
    else
        echo -e "${C_GREEN}🛑 Stopping and disabling HAProxy...${C_RESET}"
        systemctl stop haproxy >/dev/null 2>&1
        systemctl disable haproxy >/dev/null 2>&1
    fi

    if [ -f "${HAPROXY_CONFIG}.bak.firewallfalcon" ]; then
        mv "${HAPROXY_CONFIG}.bak.firewallfalcon" "$HAPROXY_CONFIG"
    elif [ -f "$HAPROXY_CONFIG" ]; then
        cat > "$HAPROXY_CONFIG" <<EOF
global
    log /dev/log local0
    log /dev/log local1 notice

defaults
    log     global
EOF
    fi
    rm -f "$EDGE_OVPN_PORT_FILE" "$EDGE_NAMED_PATHS_FILE"

    systemctl stop dahoom-edge-ovpn-ws.service >/dev/null 2>&1
    systemctl disable dahoom-edge-ovpn-ws.service >/dev/null 2>&1
    rm -f "$EDGE_OVPN_WS_SERVICE_FILE" "$EDGE_OVPN_WS_SCRIPT"

    systemctl stop dahoom-edge-http-ovpn-sniffer.service >/dev/null 2>&1
    systemctl disable dahoom-edge-http-ovpn-sniffer.service >/dev/null 2>&1
    rm -f "$EDGE_HTTP_OVPN_SNIFFER_SERVICE_FILE" "$EDGE_HTTP_OVPN_SNIFFER_SCRIPT"
    systemctl daemon-reload

    # write_internal_nginx_config only ever touches this one file, on
    # behalf of this feature alone. Leaving it in place after uninstall
    # is exactly why the
    # removal never felt complete: the 8880/8443 server blocks (and their
    # certificate references) stayed live indefinitely, which is also how
    # a later cert change can leave Nginx pointed at a file that no longer
    # exists. Put back whatever was there before HAProxy Edge was first
    # installed, or remove it outright if there was nothing to restore.
    local nginx_conf_changed=false
    if [ -f "${NGINX_CONFIG_FILE}.bak.firewallfalcon" ]; then
        mv "${NGINX_CONFIG_FILE}.bak.firewallfalcon" "$NGINX_CONFIG_FILE"
        nginx_conf_changed=true
        echo -e "${C_GREEN}🗑️ Restored Nginx's original default site config.${C_RESET}"
    elif [ -f "$NGINX_CONFIG_FILE" ]; then
        rm -f "$NGINX_CONFIG_FILE" "/etc/nginx/sites-enabled/default"
        nginx_conf_changed=true
        echo -e "${C_GREEN}🗑️ Removed the internal Nginx site config.${C_RESET}"
    fi

    local delete_cert="n"
    if [[ "$UNINSTALL_MODE" == "silent" ]]; then
        delete_cert="y"
    elif [ -f "$SSL_CERT_FILE" ] || [ -f "$SSL_CERT_CHAIN_FILE" ] || [ -f "$SSL_CERT_KEY_FILE" ]; then
        if systemctl is-active --quiet nginx; then
            echo -e "${C_YELLOW}⚠️ The shared certificate is also used by the internal Nginx proxy.${C_RESET}"
        fi
        read -p "👉 Delete the shared TLS certificate too? (y/n): " delete_cert
    fi

    if [[ "$delete_cert" == "y" || "$delete_cert" == "Y" ]]; then
        if systemctl is-active --quiet nginx; then
            echo -e "${C_GREEN}🛑 Stopping Nginx because the shared certificate is being removed...${C_RESET}"
            systemctl stop nginx >/dev/null 2>&1
        fi
        rm -f "$SSL_CERT_FILE" "$SSL_CERT_CHAIN_FILE" "$SSL_CERT_KEY_FILE" "$EDGE_CERT_INFO_FILE"
        rm -f "$NGINX_PORTS_FILE"
        echo -e "${C_GREEN}🗑️ Shared certificate files removed.${C_RESET}"
    fi

    # Apply the Nginx config change now instead of leaving it live with a
    # stale config until something else happens to restart the service.
    if $nginx_conf_changed && systemctl is-active --quiet nginx; then
        if nginx -t &>/dev/null; then
            _fm_safe_restart_nginx &>/dev/null
        else
            echo -e "${C_YELLOW}⚠️ Nginx config check failed after cleanup — run 'nginx -t' to see why.${C_RESET}"
        fi
    fi

    echo -e "${C_GREEN}✅ HAProxy Edge has been fully removed.${C_RESET}"
}

##############################################################################
# SlowDNS (DNSTT) — based on SSHPLUS's own SlowDNS Manager mechanism (same
# dns-server binary, same screen-session + iptables-REDIRECT-for-port-53
# approach), generalized to run any number of protocol variants (SSH/SSL/
# Dropbear/SOCKS/OpenVPN/V2Ray) SIMULTANEOUSLY, each its own instance with
# its own screen session name and its own user-chosen port — by explicit
# request. SSHPLUS's own scripts only ever run ONE variant at a time
# (verified directly in their files: every one of ssh/ssl/drop/socks/
# ovpn's startdns uses the identical `screen -dmS slowdns` session name
# and the identical hardcoded :5300 — installing any one kills and
# replaces whichever was running before).
#
# Port 53 is still a singular, real resource — only ONE instance can ever
# hold it, via the same shared iptables PREROUTING REDIRECT (udp/53 ->
# 5300) SSHPLUS itself uses. Any OTHER port an instance is given binds
# directly, no redirect needed, so any number of those can run together.
#
# Deliberate deviation from SSHPLUS: their "use a default, publicly-known
# key pair" install option is skipped — a shared private key defeats the
# tunnel's encryption for every server using it. "Use existing" / "generate
# new" are kept as-is, per-instance.
##############################################################################

_fm_slowdns_ensure_deps() {
    command -v screen &>/dev/null || ff_pkg_install screen &>/dev/null
}

# Fixed variant metadata: key -> (default backend, display label).
_fm_slowdns_variant_backend() {
    case "$1" in
        ssh)   echo "127.0.0.1:22" ;;
        ssl)   echo "127.0.0.1:443" ;;
        drop)  echo "127.0.0.1:8080" ;;
        socks) echo "127.0.0.1:80" ;;
        ovpn)  echo "127.0.0.1:1194" ;;
        v2ray) echo "127.0.0.1:8787" ;;
    esac
}
_fm_slowdns_variant_label() {
    case "$1" in
        ssh)   echo "SSH" ;;
        ssl)   echo "SSL" ;;
        drop)  echo "Dropbear" ;;
        socks) echo "SOCKS" ;;
        ovpn)  echo "OpenVPN" ;;
        v2ray) echo "V2Ray" ;;
    esac
}
_fm_slowdns_all_variants() { echo "ssh ssl drop socks ovpn v2ray"; }

_fm_slowdns_inst_dir() { echo "$SLOWDNS_INSTANCES_DIR/$1"; }
_fm_slowdns_screen_name() { echo "slowdns-$1"; }

_fm_slowdns_kill_instance() {
    local name; name=$(_fm_slowdns_screen_name "$1")
    screen -ls 2>/dev/null | grep -q "\.${name}[[:space:]]" && \
        screen -ls | grep "\.${name}[[:space:]]" | cut -d. -f1 | awk '{print $1}' | xargs -r kill
}

_fm_slowdns_instance_active() {
    local name; name=$(_fm_slowdns_screen_name "$1")
    screen -ls 2>/dev/null | grep -q "\.${name}[[:space:]]"
}

_fm_slowdns_instance_installed() {
    [[ -f "$(_fm_slowdns_inst_dir "$1")/ns" ]]
}

_fm_slowdns_any_installed() {
    local v
    for v in $(_fm_slowdns_all_variants); do
        _fm_slowdns_instance_installed "$v" && return 0
    done
    return 1
}

_fm_slowdns_download_binary() {
    mkdir -p "$SLOWDNS_DIR"
    local arch; arch=$(uname -m)
    if [[ "$arch" != "x86_64" ]]; then
        echo -e "${C_RED}❌ This SlowDNS build is x86_64-only.${C_RESET}"
        return 1
    fi
    local update_branch; update_branch=$(get_update_branch)
    local url="$(_fm_gh_raw)/${update_branch}/udp/slowdns-dns-server-linux-amd64"
    curl -sL "$url" -o "$SLOWDNS_BINARY" && chmod +x "$SLOWDNS_BINARY"
    [[ -x "$SLOWDNS_BINARY" ]]
}

# Same 2-choice idea SSHPLUS's slowdns-ssh offers ("use existing key" /
# "delete it and generate a new one"), minus the shared-default-key
# option. $1 = this instance's own directory (own separate keypair).
_fm_slowdns_pick_key() {
    local inst_dir="$1" key="$1/server.key" pub="$1/server.pub"
    if [[ -f "$key" && -f "$pub" ]]; then
        echo -e "${C_CYAN}An existing key was found for this instance.${C_RESET}"
        echo "  [1] Use the existing key (recommended)"
        echo "  [2] Delete it and generate a new one"
        read -r -p "👉 Choice [1]: " kc
        if [[ "$kc" == "2" ]]; then
            rm -f "$key" "$pub"
            "$SLOWDNS_BINARY" -gen-key -privkey-file "$key" -pubkey-file "$pub"
        fi
    else
        echo -e "${C_YELLOW}No existing key found for this instance — generating a new one.${C_RESET}"
        "$SLOWDNS_BINARY" -gen-key -privkey-file "$key" -pubkey-file "$pub"
    fi
    [[ -f "$key" ]]
}

# Regenerates /etc/rc.local so it re-applies the shared port-53 redirect
# (harmless no-op if nothing actually uses port 53 right now) and
# re-launches every currently-installed instance on boot. Called after
# every install/remove so it always reflects whichever instances exist —
# backs up whatever was already there the first time, same as before
# (nothing else in DAHOOM uses rc.local).
_fm_slowdns_regen_rclocal() {
    [[ -f "$SLOWDNS_RCLOCAL_BACKUP" ]] || cp -f /etc/rc.local "$SLOWDNS_RCLOCAL_BACKUP" 2>/dev/null
    cat > /etc/rc.local <<EOF
#!/bin/sh -e
iptables -I INPUT -p udp --dport 5300 -j ACCEPT 2>/dev/null
iptables -t nat -I PREROUTING -p udp --dport 53 -j REDIRECT --to-ports 5300 2>/dev/null
for d in $SLOWDNS_INSTANCES_DIR/*/; do
    [ -f "\${d}start.sh" ] && bash "\${d}start.sh"
done
exit 0
EOF
    chmod +x /etc/rc.local
    systemctl enable rc-local >/dev/null 2>&1
    systemctl start rc-local >/dev/null 2>&1
}

_fm_slowdns_restore_rclocal() {
    if [[ -f "$SLOWDNS_RCLOCAL_BACKUP" ]]; then
        mv -f "$SLOWDNS_RCLOCAL_BACKUP" /etc/rc.local
    else
        rm -f /etc/rc.local
    fi
}

# $1=variant key (ssh/ssl/drop/socks/ovpn/v2ray)
_fm_slowdns_install() {
    local variant="$1" backend label
    backend=$(_fm_slowdns_variant_backend "$variant")
    label=$(_fm_slowdns_variant_label "$variant")
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- Installing SlowDNS ($label) ---${C_RESET}"

    _fm_slowdns_ensure_deps
    mkdir -p "$SLOWDNS_DIR"
    if [[ ! -x "$SLOWDNS_BINARY" ]]; then
        echo -e "\n${C_BLUE}📥 Downloading SlowDNS server binary...${C_RESET}"
        _fm_slowdns_download_binary || { echo -e "${C_RED}❌ Download failed.${C_RESET}"; press_enter; return; }
    fi

    local inst_dir; inst_dir=$(_fm_slowdns_inst_dir "$variant")
    mkdir -p "$inst_dir"

    read -r -p "👉 Enter your NS (nameserver) domain: " ns_input
    if [[ -z "$ns_input" ]]; then echo -e "${C_RED}❌ Nameserver cannot be empty.${C_RESET}"; press_enter; return; fi

    read -r -p "👉 Public UDP port for this instance (any number of instances can run together, each on its own port) [53]: " pt
    pt=${pt:-53}
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi

    _fm_slowdns_pick_key "$inst_dir" || { echo -e "${C_RED}❌ Failed to obtain a SlowDNS key.${C_RESET}"; press_enter; return; }

    # This instance's own previous run (reinstalling/reconfiguring it) is
    # killed first — precise, by its own screen-session name — before any
    # port-conflict check, so it's never mistaken for "something else"
    # squatting on the port.
    _fm_slowdns_kill_instance "$variant"
    sleep 1

    check_and_open_firewall_port "$pt" udp
    local bind_port="$pt"
    if [[ "$pt" == "53" ]]; then
        bind_port="5300"
        iptables -C INPUT -p udp --dport 5300 -j ACCEPT 2>/dev/null || iptables -I INPUT -p udp --dport 5300 -j ACCEPT
        iptables -t nat -C PREROUTING -p udp --dport 53 -j REDIRECT --to-ports 5300 2>/dev/null || \
            iptables -t nat -I PREROUTING -p udp --dport 53 -j REDIRECT --to-ports 5300
    fi
    # Only ONE instance can ever hold a given port. If another SlowDNS
    # instance already owns this one (most commonly port 53, the shared
    # resource), stopping it here disables that instance too — the same
    # offer-to-stop treatment every other DAHOOM feature gives an
    # occupied port.
    check_and_free_ports "$bind_port" || { press_enter; return; }

    echo "$ns_input" > "$inst_dir/ns"
    echo "$pt" > "$inst_dir/port"

    # `screen -dmS slowdns-<variant> <binary> <args>` — same invocation
    # shape as SSHPLUS's own `screen -dmS slowdns ...`, just with a
    # variant-specific session name so multiple instances can coexist.
    # Log capture via a plain shell redirect inside the session, not
    # screen's own -L/-Logfile (see the commit history for why).
    cat > "$inst_dir/start.sh" <<EOF
#!/bin/bash
screen -dmS $(_fm_slowdns_screen_name "$variant") bash -c '$SLOWDNS_BINARY -udp :$bind_port -privkey-file $inst_dir/server.key "\$(cat $inst_dir/ns)" "$backend" > $inst_dir/dahoom.log 2>&1'
EOF
    chmod +x "$inst_dir/start.sh"

    _fm_slowdns_regen_rclocal

    rm -f "$inst_dir/dahoom.log"
    bash "$inst_dir/start.sh"
    sleep 1

    if _fm_slowdns_instance_active "$variant"; then
        echo -e "\n${C_GREEN}✅ SlowDNS ($label) installed and running on port ${pt}.${C_RESET}"
        _fm_slowdns_show_instance_info "$variant"
    else
        echo -e "\n${C_RED}❌ SlowDNS ($label) failed to start.${C_RESET}"
        if [[ -f "$inst_dir/dahoom.log" ]]; then
            echo -e "${C_YELLOW}Last log lines:${C_RESET}"
            tail -n 15 "$inst_dir/dahoom.log"
        fi
    fi
    press_enter
}

_fm_slowdns_install_ssh()   { _fm_slowdns_install ssh; }
_fm_slowdns_install_ssl()   { _fm_slowdns_install ssl; }
_fm_slowdns_install_drop()  { _fm_slowdns_install drop; }
_fm_slowdns_install_socks() { _fm_slowdns_install socks; }
_fm_slowdns_install_ovpn()  { _fm_slowdns_install ovpn; }
_fm_slowdns_install_v2ray() { _fm_slowdns_install v2ray; }

_fm_slowdns_show_instance_info() {
    local variant="$1" inst_dir; inst_dir=$(_fm_slowdns_inst_dir "$variant")
    local label; label=$(_fm_slowdns_variant_label "$variant")
    if [[ ! -f "$inst_dir/ns" ]]; then
        echo -e "${C_YELLOW}ℹ️ SlowDNS ($label) is not configured.${C_RESET}"
        return
    fi
    local status_str
    _fm_slowdns_instance_active "$variant" && status_str="${C_GREEN}Active${C_RESET}" || status_str="${C_RED}Inactive${C_RESET}"
    echo -e "${C_CYAN}[$label]${C_RESET} Status: ${status_str}  Port: ${C_YELLOW}$(cat "$inst_dir/port" 2>/dev/null)${C_RESET}  NS: ${C_YELLOW}$(cat "$inst_dir/ns")${C_RESET}  Key: ${C_YELLOW}$(cat "$inst_dir/server.pub" 2>/dev/null)${C_RESET}"
}

_fm_slowdns_show_all_info() {
    local v any=""
    for v in $(_fm_slowdns_all_variants); do
        if _fm_slowdns_instance_installed "$v"; then
            _fm_slowdns_show_instance_info "$v"
            any=1
        fi
    done
    [[ -z "$any" ]] && echo -e "${C_YELLOW}ℹ️ No SlowDNS instance is configured yet.${C_RESET}"
}

_fm_slowdns_start_instance() {
    local variant="$1" inst_dir; inst_dir=$(_fm_slowdns_inst_dir "$variant")
    local label; label=$(_fm_slowdns_variant_label "$variant")
    _fm_slowdns_kill_instance "$variant"
    sleep 1
    rm -f "$inst_dir/dahoom.log"
    bash "$inst_dir/start.sh"
    sleep 1
    if _fm_slowdns_instance_active "$variant"; then
        echo -e "${C_GREEN}✅ SlowDNS ($label) started.${C_RESET}"
    else
        echo -e "${C_RED}❌ SlowDNS ($label) failed to start.${C_RESET}"
        [[ -f "$inst_dir/dahoom.log" ]] && tail -n 15 "$inst_dir/dahoom.log"
    fi
}

_fm_slowdns_stop_instance() {
    local variant="$1" label; label=$(_fm_slowdns_variant_label "$variant")
    _fm_slowdns_kill_instance "$variant"
    echo -e "${C_YELLOW}⚠️ SlowDNS ($label) stopped.${C_RESET}"
}

_fm_slowdns_remove_instance() {
    local variant="$1" inst_dir; inst_dir=$(_fm_slowdns_inst_dir "$variant")
    local label; label=$(_fm_slowdns_variant_label "$variant")
    _fm_slowdns_kill_instance "$variant"
    local pt; pt=$(cat "$inst_dir/port" 2>/dev/null)
    rm -rf "$inst_dir"
    if [[ "$pt" == "53" ]]; then
        # Only drop the shared redirect if no OTHER instance still uses 53.
        local still_used="" d
        for d in "$SLOWDNS_INSTANCES_DIR"/*/; do
            [[ -f "${d}port" && "$(cat "${d}port" 2>/dev/null)" == "53" ]] && still_used=1
        done
        if [[ -z "$still_used" ]]; then
            iptables -D INPUT -p udp --dport 5300 -j ACCEPT 2>/dev/null
            iptables -t nat -D PREROUTING -p udp --dport 53 -j REDIRECT --to-ports 5300 2>/dev/null
        fi
    fi
    if _fm_slowdns_any_installed; then
        _fm_slowdns_regen_rclocal
    else
        _fm_slowdns_restore_rclocal
    fi
    echo -e "${C_GREEN}✅ SlowDNS ($label) removed.${C_RESET}"
}

# Silent, non-interactive full purge — used by the master "Uninstall
# DAHOOM entirely" routine.
_fm_slowdns_purge_all() {
    local v
    for v in $(_fm_slowdns_all_variants); do
        _fm_slowdns_instance_installed "$v" && _fm_slowdns_remove_instance "$v" >/dev/null 2>&1
    done
}

# Shared "pick an installed instance" prompt for Start/Restart/Stop/Remove.
# Echoes the chosen variant key(s) (space-separated for "all") on success;
# returns 1 on cancel/no selection/nothing installed.
_fm_slowdns_pick_installed() {
    local v i=0
    local -a keys=()
    for v in $(_fm_slowdns_all_variants); do
        if _fm_slowdns_instance_installed "$v"; then
            i=$((i+1))
            keys+=("$v")
            echo "  [$i] $(_fm_slowdns_variant_label "$v")" >&2
        fi
    done
    if (( i == 0 )); then
        echo -e "${C_YELLOW}ℹ️ No SlowDNS instance is installed yet.${C_RESET}" >&2
        return 1
    fi
    echo "  [a] All" >&2
    read -r -p "👉 Which one?: " pick
    if [[ "$pick" == "a" || "$pick" == "A" ]]; then
        echo "${keys[@]}"
        return 0
    fi
    if [[ "$pick" =~ ^[0-9]+$ ]] && (( pick >= 1 && pick <= i )); then
        echo "${keys[$((pick-1))]}"
        return 0
    fi
    echo -e "${C_RED}❌ Invalid choice.${C_RESET}" >&2
    return 1
}

_fm_slowdns_start_picked() {
    local picked; picked=$(_fm_slowdns_pick_installed) || { press_enter; return; }
    local v; for v in $picked; do _fm_slowdns_start_instance "$v"; done
    press_enter
}

_fm_slowdns_restart_picked() {
    local picked; picked=$(_fm_slowdns_pick_installed) || { press_enter; return; }
    local v; for v in $picked; do _fm_slowdns_start_instance "$v"; done
    press_enter
}

_fm_slowdns_stop_picked() {
    local picked; picked=$(_fm_slowdns_pick_installed) || { press_enter; return; }
    local v; for v in $picked; do _fm_slowdns_stop_instance "$v"; done
    press_enter
}

_fm_slowdns_remove_picked() {
    local picked; picked=$(_fm_slowdns_pick_installed) || { press_enter; return; }
    local confirm="y"
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        read -r -p "👉 Remove the selected instance(s)? (y/n): " confirm
    fi
    [[ "$confirm" == "y" || "$confirm" == "Y" ]] || { press_enter; return; }
    local v; for v in $picked; do _fm_slowdns_remove_instance "$v"; done
    press_enter
}

_fm_slowdns_any_active() {
    local v
    for v in $(_fm_slowdns_all_variants); do
        _fm_slowdns_instance_active "$v" && return 0
    done
    return 1
}

_fm_netrelay_write_ovpn_sniffer_script() {
    cat > "$NETRELAY_OVPN_SNIFFER_SCRIPT" <<'EOF'
#!/usr/bin/env python3
import socket, sys, threading, time

def pipe(a, b):
    try:
        while True:
            data = a.recv(4096)
            if not data:
                break
            b.sendall(data)
    except Exception:
        pass
    finally:
        for s in (a, b):
            try:
                s.close()
            except Exception:
                pass

def read_available(c, max_bytes, timeout):
    # Grabs whatever arrives within the window, not necessarily a fixed
    # count — a client wrapping the connection in a decoy HTTP-looking
    # request (a "payload"/"SNI" client mode) sends that first and then,
    # often with no wait for any reply, the real protocol bytes right
    # behind it. Buffering across the whole window instead of stopping at
    # the first few bytes lets the real signature turn up later in the
    # same burst instead of being missed entirely.
    c.settimeout(timeout)
    buf = b""
    try:
        while len(buf) < max_bytes:
            chunk = c.recv(max_bytes - len(buf))
            if not chunk:
                break
            buf += chunk
    except Exception:
        pass
    finally:
        c.settimeout(None)
    return buf

def contains_ovpn_open(buf):
    # Same signature used across DAHOOM: a 2-byte big-endian length prefix
    # short enough that its high byte is 0x00, followed by an opcode byte
    # whose top 5 bits are 7 (P_CONTROL_HARD_RESET_CLIENT_V2, any key_id).
    # A literal 0x00 byte essentially never appears in ordinary HTTP-style
    # header text, so scanning for the pattern anywhere in a buffer that
    # starts with a decoy request is still a safe, low false-positive check
    # — not just at position 0.
    for i in range(len(buf) - 2):
        if buf[i] == 0 and (buf[i + 2] & 0xF8) == 0x38:
            return True
    return False

def parse_hostport(s, default_port=22):
    if ":" in s:
        host, port_str = s.rsplit(":", 1)
        return host, int(port_str)
    return s, default_port

def handle(c, ovpn_port, default_host, default_port):
    # Real sshd speaks first — it sends its own banner unprompted, and a
    # real ssh client typically waits to receive that banner before
    # sending its own. A long peek window here waits on the client while
    # the client is simultaneously waiting on us: neither side ever sends
    # anything until the window expires, adding that whole delay in front
    # of every single SSH connection (long enough that a client's own
    # timeout can give up first). OpenVPN's opening bytes, by contrast,
    # are always client-initiated and arrive within milliseconds of the
    # TCP handshake — so a short window is enough to catch OpenVPN (direct
    # or payload-wrapped, sent as one burst) while no longer stalling SSH.
    peek = read_available(c, 4096, 0.3)
    if contains_ovpn_open(peek):
        target_host, target_port = "127.0.0.1", ovpn_port
    else:
        target_host, target_port = default_host, default_port
    try:
        target = socket.create_connection((target_host, target_port), timeout=5)
    except Exception:
        c.close()
        return
    try:
        if peek:
            target.sendall(peek)
    except Exception:
        c.close()
        target.close()
        return
    threading.Thread(target=pipe, args=(c, target), daemon=True).start()
    threading.Thread(target=pipe, args=(target, c), daemon=True).start()

def listen_one(public_port, ovpn_port, default_host, default_port):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    # The public port can still be transiently held right after install (a
    # leftover TIME_WAIT from whatever used it before, etc.) — retry for a
    # bit instead of dying on the first attempt and burning through
    # systemd's restart budget.
    for attempt in range(10):
        try:
            s.bind(("0.0.0.0", public_port))
            break
        except OSError:
            if attempt == 9:
                raise
            time.sleep(1)
    s.listen(128)
    while True:
        c, _ = s.accept()
        threading.Thread(target=handle, args=(c, ovpn_port, default_host, default_port), daemon=True).start()

def main():
    ovpn_port = int(sys.argv[1])
    default_host, default_port = parse_hostport(sys.argv[2])
    threads = []
    for pub in sys.argv[3:]:
        t = threading.Thread(target=listen_one, args=(int(pub), ovpn_port, default_host, default_port), daemon=True)
        t.start()
        threads.append(t)
    for t in threads:
        t.join()

if __name__ == "__main__":
    main()
EOF
    chmod +x "$NETRELAY_OVPN_SNIFFER_SCRIPT"
}

# $1 = ovpn backend port, $2 = default backend "host:port" (anything that
# isn't OpenVPN — here, Net Relay itself on its internal port), remaining
# args = public ports to listen on directly.
_fm_netrelay_write_ovpn_sniffer_service() {
    local ovpn_port="$1" default_backend="$2"; shift 2
    cat > "$NETRELAY_OVPN_SNIFFER_SERVICE_FILE" <<EOF
[Unit]
Description=DAHOOM Net Relay OpenVPN sniffer
After=network.target netrelay.service
StartLimitIntervalSec=0

[Service]
ExecStart=/usr/bin/python3 ${NETRELAY_OVPN_SNIFFER_SCRIPT} ${ovpn_port} ${default_backend} $*
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
}

install_net_relay() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- Ⓓ Installing Net Relay (Websockets/Socks) ---${C_RESET}"

    if [ -f "$NETRELAY_SERVICE_FILE" ]; then
        echo -e "\n${C_YELLOW}ℹ️ Net Relay is already installed.${C_RESET}"
        if [ -f "$NETRELAY_CONFIG_FILE" ]; then
            source "$NETRELAY_CONFIG_FILE"
            echo -e "   It is configured to run on port(s): ${C_YELLOW}$PORTS${C_RESET}"
            echo -e "   Installed Version: ${C_YELLOW}${INSTALLED_VERSION:-Unknown}${C_RESET}"
            [[ -n "$OVPN_PORT" ]] && echo -e "   OpenVPN sharing: ${C_YELLOW}enabled${C_RESET} (127.0.0.1:${OVPN_PORT})"
        fi
        read -p "👉 Do you want to reinstall/switch version? (y/n): " confirm_reinstall
        if [[ "$confirm_reinstall" != "y" ]]; then return; fi
        echo -e "\n${C_YELLOW}🔁 Removing the currently installed version first...${C_RESET}"
        uninstall_net_relay
    fi

    # ── Select Net Relay version ─────────────────────────────────────
    echo -e "\n${C_BOLD}${C_CYAN}Select Net Relay version:${C_RESET}"
    echo -e "  ${C_CHOICE}[1]${C_RESET} v2-Stable"
    echo -e "  ${C_CHOICE}[2]${C_RESET} v0-WebSockets"
    echo -e "  ${C_CHOICE}[3]${C_RESET} v1-vodafoneIE"
    echo -e "  ${C_CHOICE}[4]${C_RESET} v1.2-RustFast"
    local variant_choice SELECTED_VERSION
    read -p "👉 Choose [1-4] (default 1): " variant_choice
    case "$variant_choice" in
        2) SELECTED_VERSION="v0-WebSockets" ;;
        3) SELECTED_VERSION="v1-vodafoneIE" ;;
        4) SELECTED_VERSION="v1.2-RustFast" ;;
        *) SELECTED_VERSION="v2-Stable" ;;
    esac

    local ports
    read -p "👉 Enter port(s) for Net Relay (e.g., 8080 or 8080 8888) [8080]: " ports
    ports=${ports:-8080}

    local port_array=($ports)
    for port in "${port_array[@]}"; do
        if ! [[ "$port" =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]; then
            echo -e "\n${C_RED}❌ Invalid port number: $port. Aborting.${C_RESET}"
            return
        fi
        check_and_free_ports "$port" || return
        check_and_open_firewall_port "$port" tcp || return
    done

    # Net Relay's own binary is closed-source and can't be taught
    # OpenVPN's signature. If OpenVPN needs to share these exact ports
    # too, Net Relay itself moves to one fixed, loopback-only internal
    # port, and a small sniffer takes over the real public port(s) —
    # routing OpenVPN's signature straight to OpenVPN, everything else
    # through to Net Relay on its internal port.
    _fm_edge_load_ovpn_port
    local netrelay_ovpn_port ovpn_choice exec_ports="$ports"
    read -p "👉 Also make OpenVPN (TCP) share these same port(s)? (y/n) [n]: " ovpn_choice
    if [[ "$ovpn_choice" == "y" || "$ovpn_choice" == "Y" ]]; then
        read -p "👉 OpenVPN backend port (TCP only) [${EDGE_OVPN_PORT}]: " netrelay_ovpn_port
        netrelay_ovpn_port=${netrelay_ovpn_port:-$EDGE_OVPN_PORT}
        if [[ -z "$netrelay_ovpn_port" ]] || ! [[ "$netrelay_ovpn_port" =~ ^[0-9]+$ ]]; then
            echo -e "${C_RED}❌ Invalid or missing OpenVPN port.${C_RESET}"; return
        fi
        check_and_free_ports "$NETRELAY_INTERNAL_PORT" || return
        exec_ports="$NETRELAY_INTERNAL_PORT"
    fi

    local download_url="$(_fm_instalasi_raw)/netrelay-${SELECTED_VERSION}"

    echo -e "\n${C_GREEN}📥 Downloading Net Relay ($SELECTED_VERSION) binary...${C_RESET}"
    if ! wget -q --show-progress -O "$NETRELAY_BINARY" "$download_url"; then
        echo -e "\n${C_RED}❌ Failed to download Net Relay binary from $download_url.${C_RESET}"
        return 1
    fi
    chmod +x "$NETRELAY_BINARY"

    echo -e "\n${C_GREEN}📝 Creating systemd service file...${C_RESET}"
    cat > "$NETRELAY_SERVICE_FILE" <<EOF
[Unit]
Description=Net Relay ($SELECTED_VERSION)
After=network.target

[Service]
User=root
Type=simple
ExecStart=$NETRELAY_BINARY -p $exec_ports
Restart=always
RestartSec=2s

[Install]
WantedBy=default.target
EOF

    echo -e "\n${C_GREEN}💾 Saving configuration...${C_RESET}"
    cat > "$NETRELAY_CONFIG_FILE" <<EOF
PORTS="$ports"
INSTALLED_VERSION="$SELECTED_VERSION"
OVPN_PORT="$netrelay_ovpn_port"
EOF

    if [[ -n "$netrelay_ovpn_port" ]]; then
        _fm_netrelay_write_ovpn_sniffer_script
        _fm_netrelay_write_ovpn_sniffer_service "$netrelay_ovpn_port" "127.0.0.1:${NETRELAY_INTERNAL_PORT}" "${port_array[@]}"
        systemctl enable dahoom-netrelay-ovpn-sniffer.service >/dev/null 2>&1
    else
        systemctl stop dahoom-netrelay-ovpn-sniffer.service >/dev/null 2>&1
        systemctl disable dahoom-netrelay-ovpn-sniffer.service >/dev/null 2>&1
        rm -f "$NETRELAY_OVPN_SNIFFER_SERVICE_FILE" "$NETRELAY_OVPN_SNIFFER_SCRIPT"
    fi

    echo -e "\n${C_GREEN}▶️ Enabling and starting Net Relay service...${C_RESET}"
    systemctl daemon-reload
    systemctl enable netrelay.service
    systemctl restart netrelay.service
    if [[ -n "$netrelay_ovpn_port" ]]; then
        sleep 1
        systemctl restart dahoom-netrelay-ovpn-sniffer.service
    fi
    sleep 2

    if systemctl is-active --quiet netrelay; then
        echo -e "\n${C_GREEN}✅ SUCCESS: Net Relay $SELECTED_VERSION is installed and active.${C_RESET}"
        if [[ -n "$netrelay_ovpn_port" ]]; then
            echo -e "   Public port(s): ${C_YELLOW}$ports${C_RESET} (Net Relay itself now listens internally on ${C_YELLOW}127.0.0.1:${NETRELAY_INTERNAL_PORT}${C_RESET})"
            if systemctl is-active --quiet dahoom-netrelay-ovpn-sniffer.service; then
                echo -e "   OpenVPN (TCP) also reaches ${C_YELLOW}127.0.0.1:${netrelay_ovpn_port}${C_RESET} on the same port(s)."
            else
                echo -e "${C_YELLOW}⚠️ The OpenVPN sniffer failed to start — Net Relay itself is fine, but OpenVPN won't be reachable this way yet.${C_RESET}"
                journalctl -u dahoom-netrelay-ovpn-sniffer.service -n 15 --no-pager
            fi
        else
            echo -e "   Listening on port(s): ${C_YELLOW}$ports${C_RESET}"
        fi
    else
        echo -e "\n${C_RED}❌ ERROR: Net Relay service failed to start.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Displaying last 15 lines of the service log for diagnostics:${C_RESET}"
        journalctl -u netrelay.service -n 15 --no-pager
    fi
}

uninstall_net_relay() {
    echo -e "\n${C_BOLD}${C_PURPLE}--- 🗑️ Uninstalling Net Relay ---${C_RESET}"
    # The OpenVPN-sharing sniffer, when configured, only ever exists
    # alongside netrelay.service (Net Relay itself just moves to an
    # internal port instead of disappearing) — so this one guard still
    # correctly reflects whether anything is installed either way.
    if [ ! -f "$NETRELAY_SERVICE_FILE" ]; then
        echo -e "${C_YELLOW}ℹ️ Net Relay is not installed, skipping.${C_RESET}"
        return
    fi
    echo -e "${C_GREEN}🛑 Stopping and disabling Net Relay service...${C_RESET}"
    systemctl stop netrelay.service >/dev/null 2>&1
    systemctl disable netrelay.service >/dev/null 2>&1
    systemctl stop dahoom-netrelay-ovpn-sniffer.service >/dev/null 2>&1
    systemctl disable dahoom-netrelay-ovpn-sniffer.service >/dev/null 2>&1
    echo -e "${C_GREEN}🗑️ Removing service file...${C_RESET}"
    rm -f "$NETRELAY_SERVICE_FILE" "$NETRELAY_OVPN_SNIFFER_SERVICE_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}🗑️ Removing binary and config files...${C_RESET}"
    rm -f "$NETRELAY_BINARY" "$NETRELAY_OVPN_SNIFFER_SCRIPT"
    rm -f "$NETRELAY_CONFIG_FILE"
    echo -e "${C_GREEN}✅ Net Relay has been uninstalled successfully.${C_RESET}"
}

# --- ZiVPN Installation Logic ---
install_zivpn() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Installing ZiVPN (UDP/VPN) ---${C_RESET}"
    
    if [ -f "$ZIVPN_SERVICE_FILE" ]; then
        echo -e "\n${C_YELLOW}ℹ️ ZiVPN is already installed.${C_RESET}"
        return
    fi

    if [ ! -f "$BADVPN_SERVICE_FILE" ]; then
        echo -e "\n${C_YELLOW}⚠️ ZiVPN requires the badvpn (udpgw) backend to provide internet access.${C_RESET}"
        echo -e "${C_GREEN}📦 Automatically installing badvpn backend...${C_RESET}"
        sleep 2
        install_badvpn
        clear; show_banner
        echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Resuming ZiVPN Installation ---${C_RESET}"
    fi

    check_and_free_ports 5667 || return
    check_and_open_firewall_port 5667 udp || return
    check_and_open_firewall_port_range "6000:19999" udp || return

    echo -e "\n${C_GREEN}⚙️ Checking system architecture...${C_RESET}"
    local arch=$(uname -m)
    local update_branch; update_branch=$(get_update_branch)
    local zivpn_url=""
    
    if [[ "$arch" == "x86_64" ]]; then
        zivpn_url="$(_fm_gh_raw)/${update_branch}/udp/udp-zivpn-linux-amd64"
        echo -e "${C_BLUE}ℹ️ Detected AMD64/x86_64 architecture.${C_RESET}"
    elif [[ "$arch" == "aarch64" || "$arch" == "arm64" ]]; then
        zivpn_url="$(_fm_gh_raw)/${update_branch}/udp/udp-zivpn-linux-arm64"
        echo -e "${C_BLUE}ℹ️ Detected ARM64 architecture.${C_RESET}"
    elif [[ "$arch" == "armv7l" || "$arch" == "arm" ]]; then
         zivpn_url="$(_fm_gh_raw)/${update_branch}/udp/udp-zivpn-linux-arm"
         echo -e "${C_BLUE}ℹ️ Detected ARM architecture.${C_RESET}"
    else
        echo -e "${C_RED}❌ Unsupported architecture: $arch${C_RESET}"
        return
    fi

    echo -e "\n${C_GREEN}📦 Downloading ZiVPN binary...${C_RESET}"
    if ! wget -q --show-progress -O "$ZIVPN_BIN" "$zivpn_url"; then
        echo -e "${C_RED}❌ Download failed. Check internet connection.${C_RESET}"
        return
    fi
    chmod +x "$ZIVPN_BIN"

    echo -e "\n${C_GREEN}⚙️ Configuring ZIVPN...${C_RESET}"
    mkdir -p "$ZIVPN_DIR"
    
    # Generate Certificates
    echo -e "${C_BLUE}🔐 Generating self-signed certificates...${C_RESET}"
    if ! command -v openssl &>/dev/null; then
        ff_pkg_install openssl >/dev/null 2>&1 || {
            echo -e "${C_RED}❌ Failed to install openssl for ZiVPN certificate generation.${C_RESET}"
            return
        }
    fi
    
    openssl req -new -newkey rsa:4096 -days 365 -nodes -x509 \
        -subj "/C=US/ST=California/L=Los Angeles/O=Example Corp/OU=IT Department/CN=zivpn" \
        -keyout "$ZIVPN_KEY_FILE" -out "$ZIVPN_CERT_FILE" 2>/dev/null

    if [ ! -f "$ZIVPN_CERT_FILE" ]; then
        echo -e "${C_RED}❌ Failed to generate certificates.${C_RESET}"
        return
    fi

    # System Tuning
    echo -e "${C_BLUE}🔧 Tuning system network parameters...${C_RESET}"
    sysctl -w net.core.rmem_max=16777216 >/dev/null
    sysctl -w net.core.wmem_max=16777216 >/dev/null

    # Create Service
    echo -e "${C_BLUE}📝 Creating systemd service file...${C_RESET}"
    cat <<EOF > "$ZIVPN_SERVICE_FILE"
[Unit]
Description=zivpn VPN Server
After=network.target

[Service]
Type=simple
User=root
WorkingDirectory=$ZIVPN_DIR
ExecStart=$ZIVPN_BIN server -c $ZIVPN_CONFIG_FILE
Restart=always
RestartSec=3
Environment=ZIVPN_LOG_LEVEL=info
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
NoNewPrivileges=true

[Install]
WantedBy=multi-user.target
EOF

    # Configure Passwords
    echo -e "\n${C_YELLOW}🔑 ZiVPN Password Setup${C_RESET}"
    read -p "👉 Enter passwords separated by commas (e.g., user1,user2) [Default: 'zi']: " input_config
    
    if [ -n "$input_config" ]; then
        IFS=',' read -r -a config_array <<< "$input_config"
        # Ensure array format for JSON
        json_passwords=$(printf '"%s",' "${config_array[@]}")
        json_passwords="[${json_passwords%,}]"
    else
        json_passwords='["zi"]'
    fi

    # Create Config File
    cat <<EOF > "$ZIVPN_CONFIG_FILE"
{
  "listen": ":5667",
   "cert": "$ZIVPN_CERT_FILE",
   "key": "$ZIVPN_KEY_FILE",
   "obfs":"zivpn",
   "auth": {
    "mode": "passwords", 
    "config": $json_passwords
  }
}
EOF

    echo -e "\n${C_GREEN}🚀 Starting ZiVPN Service...${C_RESET}"
    systemctl daemon-reload
    systemctl enable zivpn.service
    systemctl start zivpn.service

    # Port Forwarding / Firewall
    echo -e "${C_BLUE}🔥 Configuring Firewall Rules (Redirecting 6000-19999 -> 5667)...${C_RESET}"
    
    # Determine primary interface
    local iface=$(ip -4 route ls | grep default | grep -Po '(?<=dev )(\S+)' | head -1)
    
    if [ -n "$iface" ]; then
        iptables -t nat -C PREROUTING -i "$iface" -p udp --dport 6000:19999 -j DNAT --to-destination :5667 2>/dev/null || \
            iptables -t nat -A PREROUTING -i "$iface" -p udp --dport 6000:19999 -j DNAT --to-destination :5667
        # Note: IPTables rules are not persistent by default without iptables-persistent package
    else
        echo -e "${C_YELLOW}⚠️ Could not detect default interface for IPTables redirection.${C_RESET}"
    fi

    # Cleanup
    rm -f zi.sh zi2.sh 2>/dev/null

    if systemctl is-active --quiet zivpn.service; then
        echo -e "\n${C_GREEN}✅ ZiVPN Installed Successfully!${C_RESET}"
        echo -e "   - UDP Port: 5667 (Direct)"
        echo -e "   - UDP Ports: 6000-19999 (Forwarded)"
    else
        echo -e "\n${C_RED}❌ ZiVPN Service failed to start. Check logs: journalctl -u zivpn.service${C_RESET}"
    fi
}

uninstall_zivpn() {
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        clear; show_banner
        echo -e "${C_BOLD}${C_PURPLE}--- 🗑️ Uninstall ZiVPN ---${C_RESET}"
    fi
    
    if [ ! -f "$ZIVPN_SERVICE_FILE" ] && [ ! -f "$ZIVPN_BIN" ]; then
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "\n${C_YELLOW}ℹ️ ZiVPN does not appear to be installed.${C_RESET}"
        fi
        return
    fi

    local confirm="y"
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        read -p "👉 Are you sure you want to uninstall ZiVPN? (y/n): " confirm
    fi
    if [[ "$confirm" != "y" && "$confirm" != "Y" ]]; then
        echo -e "${C_YELLOW}Cancelled.${C_RESET}"
        return
    fi

    echo -e "\n${C_BLUE}🛑 Stopping services...${C_RESET}"
    systemctl stop zivpn.service 2>/dev/null
    systemctl disable zivpn.service 2>/dev/null

    local iface
    iface=$(ip -4 route ls | grep default | grep -Po '(?<=dev )(\S+)' | head -1)
    if [ -n "$iface" ]; then
        iptables -t nat -D PREROUTING -i "$iface" -p udp --dport 6000:19999 -j DNAT --to-destination :5667 2>/dev/null || true
    fi
    
    echo -e "${C_BLUE}🗑️ Removing files...${C_RESET}"
    rm -f "$ZIVPN_SERVICE_FILE"
    rm -rf "$ZIVPN_DIR"
    rm -f "$ZIVPN_BIN"
    
    systemctl daemon-reload
    
    # Clean cache (from original uninstall script logic)
    echo -e "${C_BLUE}🧹 Cleaning memory cache...${C_RESET}"
    sync; echo 3 > /proc/sys/vm/drop_caches

    echo -e "\n${C_GREEN}✅ ZiVPN Uninstalled Successfully.${C_RESET}"
}

purge_nginx() {
    local mode="$1"
    if [[ "$mode" != "silent" ]]; then
        clear; show_banner
        echo -e "${C_BOLD}${C_PURPLE}--- 🔥 Purge Internal Nginx Proxy ---${C_RESET}"
        if ! command -v nginx &> /dev/null; then
            rm -f "$NGINX_PORTS_FILE"
            echo -e "\n${C_YELLOW}ℹ️ Nginx is not installed. Nothing to do.${C_RESET}"
            return
        fi
        echo -e "\n${C_YELLOW}⚠️ This removes the internal Nginx proxy on ${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}.${C_RESET}"
        if systemctl is-active --quiet haproxy; then
            echo -e "${C_YELLOW}⚠️ HAProxy will stay installed, but web payload routing from ${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT} will stop until you reinstall the stack.${C_RESET}"
        fi
        read -p "👉 Continue and purge Nginx? (y/n): " confirm
        if [[ "$confirm" != "y" && "$confirm" != "Y" ]]; then
            echo -e "\n${C_YELLOW}❌ Uninstallation cancelled.${C_RESET}"
            return
        fi
    fi
    echo -e "\n${C_BLUE}🛑 Stopping Nginx service...${C_RESET}"
    systemctl stop nginx >/dev/null 2>&1
    systemctl disable nginx >/dev/null 2>&1
    echo -e "\n${C_BLUE}🗑️ Purging Nginx packages...${C_RESET}"
    ff_pkg_purge nginx nginx-common >/dev/null 2>&1
    ff_pkg_autoremove
    echo -e "\n${C_BLUE}🗑️ Removing leftover files...${C_RESET}"
    rm -f /etc/ssl/certs/nginx-selfsigned.pem
    rm -f /etc/ssl/private/nginx-selfsigned.key
    rm -rf /etc/nginx
    rm -f "${NGINX_CONFIG_FILE}.bak"
    rm -f "${NGINX_CONFIG_FILE}.bak.certbot"
    rm -f "${NGINX_CONFIG_FILE}.bak.selfsigned"
    rm -f "${NGINX_CONFIG_FILE}.bak.firewallfalcon"
    rm -f "$NGINX_PORTS_FILE"
    if [[ "$mode" != "silent" ]]; then
        echo -e "\n${C_GREEN}✅ Internal Nginx proxy purged. Shared DAHOOM certificates were kept.${C_RESET}"
    fi
}

install_nginx_proxy() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🚀 Reconfiguring Internal Nginx Proxy (8880/8443) ---${C_RESET}"
    echo -e "\n${C_CYAN}This keeps HAProxy on ${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT} and rewrites the internal Nginx proxy on ${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}.${C_RESET}"

    if [ ! -s "$SSL_CERT_FILE" ] || [ ! -s "$SSL_CERT_CHAIN_FILE" ] || [ ! -s "$SSL_CERT_KEY_FILE" ]; then
        echo -e "\n${C_YELLOW}⚠️ No shared DAHOOM certificate was found.${C_RESET}"
        echo -e "${C_DIM}Running the full HAProxy edge installer so the certificate and both services stay aligned.${C_RESET}"
        install_ssl_tunnel
        return
    fi

    mkdir -p "$DB_DIR" "$SSL_CERT_DIR"
    ensure_edge_stack_packages || return

    systemctl stop haproxy >/dev/null 2>&1
    systemctl stop nginx >/dev/null 2>&1
    sleep 1

    check_and_free_ports \
        "$EDGE_PUBLIC_HTTP_PORT" \
        "$EDGE_PUBLIC_TLS_PORT" \
        "$NGINX_INTERNAL_HTTP_PORT" \
        "$NGINX_INTERNAL_TLS_PORT" \
        "$HAPROXY_INTERNAL_DECRYPT_PORT" || return

    check_and_open_firewall_port "$EDGE_PUBLIC_HTTP_PORT" tcp || return
    check_and_open_firewall_port "$EDGE_PUBLIC_TLS_PORT" tcp || return

    load_edge_cert_info
    local server_name="${EDGE_DOMAIN:-$(detect_preferred_host)}"
    [[ -z "$server_name" ]] && server_name="_"

    configure_edge_stack "$server_name" || return

    echo -e "\n${C_GREEN}✅ Internal Nginx proxy reconfigured successfully.${C_RESET}"
    echo -e "   • Public HAProxy edge: ${C_YELLOW}${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT}${C_RESET}"
    echo -e "   • Internal Nginx: ${C_YELLOW}${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}${C_RESET}"
}

request_certbot_ssl() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🔒 Shared Certbot Certificate (HAProxy + Nginx) ---${C_RESET}"
    echo -e "\n${C_DIM}This will replace the shared certificate used by HAProxy on ${EDGE_PUBLIC_TLS_PORT} and internal Nginx on ${NGINX_INTERNAL_TLS_PORT}.${C_RESET}"

    mkdir -p "$DB_DIR" "$SSL_CERT_DIR"
    ensure_edge_stack_packages || return
    load_edge_cert_info

    local preferred_host
    local default_domain=""
    local domain_name
    local email

    preferred_host=$(detect_preferred_host)
    if [[ -n "$EDGE_DOMAIN" ]] && ! _is_valid_ipv4 "$EDGE_DOMAIN"; then
        default_domain="$EDGE_DOMAIN"
    elif [[ -n "$preferred_host" ]] && ! _is_valid_ipv4 "$preferred_host"; then
        default_domain="$preferred_host"
    fi

    if [[ -n "$default_domain" ]]; then
        read -p "👉 Enter your domain name [$default_domain]: " domain_name
        domain_name=${domain_name:-$default_domain}
    else
        read -p "👉 Enter your domain name (e.g. vpn.example.com): " domain_name
    fi
    if [[ -z "$domain_name" ]]; then
        echo -e "\n${C_RED}❌ Domain name cannot be empty.${C_RESET}"
        return
    fi
    if _is_valid_ipv4 "$domain_name"; then
        echo -e "\n${C_RED}❌ Certbot requires a real domain name, not a raw IP address.${C_RESET}"
        return
    fi

    read -p "👉 Enter your email for Let's Encrypt [${EDGE_EMAIL}]: " email
    email=${email:-$EDGE_EMAIL}
    if [[ -z "$email" ]]; then
        echo -e "\n${C_RED}❌ Email address cannot be empty.${C_RESET}"
        return
    fi

    check_and_open_firewall_port "$EDGE_PUBLIC_HTTP_PORT" tcp || return
    check_and_open_firewall_port "$EDGE_PUBLIC_TLS_PORT" tcp || return

    obtain_certbot_edge_cert "$domain_name" "$email" || return
    configure_edge_stack "$domain_name" || return

    echo -e "\n${C_GREEN}✅ Shared Certbot certificate applied successfully.${C_RESET}"
    echo -e "   • Domain: ${C_YELLOW}${domain_name}${C_RESET}"
    echo -e "   • Public edge: ${C_YELLOW}${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT}${C_RESET}"
}

nginx_proxy_menu() {
    while true; do
    show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🌐 Internal Nginx Proxy Management ---${C_RESET}"

    local nginx_status="${C_STATUS_I}Inactive${C_RESET}"
    local haproxy_status="${C_STATUS_I}Inactive${C_RESET}"
    if systemctl is-active --quiet nginx; then
        nginx_status="${C_STATUS_A}Active${C_RESET}"
    fi
    if systemctl is-active --quiet haproxy; then
        haproxy_status="${C_STATUS_A}Active${C_RESET}"
    fi

    load_edge_cert_info
    local cert_info="${EDGE_CERT_MODE:-Not configured}"
    if [[ -n "$EDGE_DOMAIN" ]]; then
        cert_info="${cert_info} - ${EDGE_DOMAIN}"
    fi

    echo -e "\n${C_WHITE}Nginx:${C_RESET} ${nginx_status}"
    echo -e "${C_WHITE}HAProxy:${C_RESET} ${haproxy_status}"
    echo -e "${C_DIM}Public Edge: ${EDGE_PUBLIC_HTTP_PORT}/${EDGE_PUBLIC_TLS_PORT} | Internal Nginx: ${NGINX_INTERNAL_HTTP_PORT}/${NGINX_INTERNAL_TLS_PORT}${C_RESET}"
    echo -e "${C_DIM}Shared Certificate: ${cert_info}${C_RESET}"

    echo -e "\n${C_BOLD}Select an action:${C_RESET}\n"
    
    if systemctl is-active --quiet nginx; then
         printf "  ${C_CHOICE}[ 1]${C_RESET} %s\n" "$(pad_right '🛑 Stop Nginx Service' 40)"
         printf "  ${C_CHOICE}[ 2]${C_RESET} %s\n" "$(pad_right '🔄 Restart HAProxy + Nginx Stack' 40)"
         printf "  ${C_CHOICE}[ 3]${C_RESET} %s\n" "$(pad_right '⚙️ Re-install/Re-configure Edge Stack' 40)"
         printf "  ${C_CHOICE}[ 4]${C_RESET} %s\n" "$(pad_right '🔒 Certificate Management' 40)"
         printf "  ${C_CHOICE}[ 5]${C_RESET} %s\n" "$(pad_right '🔥 Uninstall/Purge Nginx' 40)"
         printf "  ${C_CHOICE}[ 6]${C_RESET} %s\n" "$(pad_right '➕ Add a Named Path (e.g. /vless)' 40)"
         printf "  ${C_CHOICE}[ 7]${C_RESET} %s\n" "$(pad_right '➖ Remove a Named Path' 40)"
    else
         printf "  ${C_CHOICE}[ 1]${C_RESET} %s\n" "$(pad_right '▶️ Start Nginx Service' 40)"
         printf "  ${C_CHOICE}[ 3]${C_RESET} %s\n" "$(pad_right '⚙️ Install/Configure Edge Stack' 40)"
         printf "  ${C_CHOICE}[ 4]${C_RESET} %s\n" "$(pad_right '🔒 Certificate Management' 40)"
         printf "  ${C_CHOICE}[ 5]${C_RESET} %s\n" "$(pad_right '🔥 Uninstall/Purge Nginx' 40)"
    fi

    echo -e "\n  ${C_WARN}[ 0]${C_RESET} ↩️ Return"
    echo
    if ! read -r -p "$(echo -e ${C_PROMPT}"👉 Select an option: "${C_RESET})" choice; then
        echo
        return
    fi
    
    case $choice in
        1) 
            if systemctl is-active --quiet nginx; then
                echo -e "\n${C_BLUE}🛑 Stopping Nginx...${C_RESET}"
                systemctl stop nginx
                echo -e "${C_GREEN}✅ Nginx stopped.${C_RESET}"
                if systemctl is-active --quiet haproxy; then
                    echo -e "${C_YELLOW}⚠️ HAProxy is still running, but web traffic that depends on internal Nginx will not work until Nginx starts again.${C_RESET}"
                fi
            else
                echo -e "\n${C_BLUE}▶️ Starting Nginx...${C_RESET}"
                systemctl start nginx
                if systemctl is-active --quiet nginx; then
                    echo -e "${C_GREEN}✅ Nginx started.${C_RESET}"
                else
                    echo -e "${C_RED}❌ Failed to start Nginx.${C_RESET}"
                fi
            fi
            press_enter
            ;;
        2)
            echo -e "\n${C_BLUE}🔄 Restarting Nginx and HAProxy...${C_RESET}"
            local restart_ok=true
            _fm_safe_restart_nginx || restart_ok=false
            if command -v haproxy &> /dev/null; then
                systemctl restart haproxy || restart_ok=false
            else
                restart_ok=false
            fi
            if $restart_ok && systemctl is-active --quiet nginx && systemctl is-active --quiet haproxy; then
                echo -e "${C_GREEN}✅ HAProxy + Nginx stack restarted.${C_RESET}"
            else
                echo -e "${C_RED}❌ One or more services failed to restart.${C_RESET}"
            fi
            press_enter
            ;;
        3)
             install_nginx_proxy; press_enter
             ;;
        4)
             edge_certificate_menu
             ;;
        5)
             purge_nginx; press_enter
             ;;
        6)
             _fm_edge_add_named_path_interactive; press_enter
             ;;
        7)
             _fm_edge_remove_named_path_interactive; press_enter
             ;;
        0) return ;;
        *) invalid_option ;;
    esac
    done
}

get_xui_installed_variant() {
    if [[ ! -f "/etc/systemd/system/x-ui.service" && ! -f "/lib/systemd/system/x-ui.service" && ! -f "/usr/local/x-ui/x-ui" && ! -d "/usr/local/x-ui" ]]; then
        echo "none"
        return
    fi
    # Both variants live at the same path under the same service name, so tell
    # them apart by their schema: the client_inbounds table exists only in
    # 3x-ui, which normalises clients out of inbounds.settings into tables of
    # its own. Detects an install made outside this menu too, and never lies
    # about an alireza0 install, which has no such table.
    if [[ -f /etc/x-ui/x-ui.db ]] && command -v sqlite3 &>/dev/null; then
        if sqlite3 /etc/x-ui/x-ui.db \
             "SELECT 1 FROM sqlite_master WHERE type='table' AND name='client_inbounds' LIMIT 1" \
             2>/dev/null | grep -q 1; then
            echo "3xui"
            return
        fi
    elif [[ -f /etc/x-ui/x-ui.db ]] && command -v python3 &>/dev/null; then
        if python3 -c "
import sqlite3, sys
try:
    c = sqlite3.connect('/etc/x-ui/x-ui.db', timeout=5)
    r = c.execute(\"SELECT 1 FROM sqlite_master WHERE type='table' AND name='client_inbounds' LIMIT 1\").fetchone()
    c.close()
    sys.exit(0 if r else 1)
except Exception:
    sys.exit(1)
" 2>/dev/null; then
            echo "3xui"
            return
        fi
    fi
    echo "x-ui"
}

get_panel_status() {
    local target_panel="$1" # "x-ui"
    if [[ ! -f "/etc/systemd/system/x-ui.service" && ! -f "/lib/systemd/system/x-ui.service" && ! -f "/usr/local/x-ui/x-ui" && ! -d "/usr/local/x-ui" ]]; then
        echo "${C_STATUS_I}(Not Installed)${C_RESET}"
        return
    fi

    if pgrep -x x-ui &>/dev/null; then
        echo "${C_STATUS_A}(Active)${C_RESET}"
    else
        echo "${C_YELLOW}(Stopped)${C_RESET}"
    fi
}

install_panel_menu() {
    install_xui_panel
}

install_xui_panel() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📦 Install X-UI Panel ---${C_RESET}"
    echo
    echo -e "  ${C_CYAN}Choose which panel to install:${C_RESET}\n"
    printf "  ${C_CHOICE}[ 1]${C_RESET} %s %s\n" "$(pad_right 'alireza0/x-ui  ·  Original build' 56)" ""
    printf "  ${C_CHOICE}[ 2]${C_RESET} %s %s\n" "$(pad_right 'MHSanaei/3x-ui  ·  More protocols & features' 56)" "${C_STATUS_A}⭐ Recommended${C_RESET}"
    echo
    echo -e "  ${C_GRAY}Both use the same install path and system service, so only one can be${C_RESET}"
    echo -e "  ${C_GRAY}installed at a time — installing one replaces the other. This panel${C_RESET}"
    echo -e "  ${C_GRAY}manages clients on either of them.${C_RESET}"
    echo
    printf "  ${C_DANGER}[ 0]${C_RESET} Cancel\n"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select panel [2]: "${C_RESET})" panel_choice
    panel_choice=${panel_choice:-2}

    case "$panel_choice" in
        1) install_xui_panel_alireza0 ;;
        2) install_xui_panel_3xui ;;
        0) echo -e "\n${C_YELLOW}❌ Installation cancelled.${C_RESET}"; return ;;
        *) invalid_option ;;
    esac
}

# 3x-ui is installed non-interactively on purpose, with the database engine
# pinned to SQLite. Its installer otherwise offers PostgreSQL, and on that
# backend there is no /etc/x-ui/x-ui.db at all — the web panel's inbound and
# client listings read that file directly, and the backup archives it, so a
# Postgres install would show an empty V2ray section and back up nothing.
# Everything else (username, password, secret web path) is left to 3x-ui's own
# generator; show_xui_access_info reads them back out of install-result.env.
install_xui_panel_3xui() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📦 Install 3X-UI Panel (MHSanaei ${_FM_3XUI_VERSION}) ---${C_RESET}\n"
    echo -e "  ${C_GRAY}Database: SQLite · Panel Port: 54321 · Subscription Server Port: 2087${C_RESET}\n"

    mkdir -p "/etc/firewallfalcon" 2>/dev/null
    echo "x-ui" > "/etc/firewallfalcon/.panel_type" 2>/dev/null || true

    echo -e "${C_BLUE}📦 Step 1/4: Installing 3X-UI core files...${C_RESET}"
    XUI_NONINTERACTIVE=1 XUI_DB_TYPE=sqlite XUI_PANEL_PORT=54321 \
        bash <(curl -Ls "$(_fm_3xui_install_url)") "$_FM_3XUI_VERSION" || true

    echo -e "\n${C_BLUE}⚙️ Step 2/4: Configuring Subscription Server Port (2087 to avoid conflicts)...${C_RESET}"
    if command -v python3 &>/dev/null && [ -f /etc/x-ui/x-ui.db ]; then
        python3 -c "
import sqlite3, os
db = '/etc/x-ui/x-ui.db'
if os.path.exists(db):
    try:
        conn = sqlite3.connect(db)
        c = conn.cursor()
        c.execute(\"DELETE FROM settings WHERE key='subPort'\")
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('subPort', '2087'))
        conn.commit()
        conn.close()
        print('OK')
    except Exception:
        pass
" 2>/dev/null && echo -e "  ${C_GREEN}✔ Subscription server port set to 2087${C_RESET}" || echo -e "  ${C_YELLOW}⚠ Could not configure subPort (will be auto-fixed if needed)${C_RESET}"
    fi

    echo -e "\n${C_BLUE}🔥 Step 3/4: Opening firewall...${C_RESET}"
    command -v ufw &>/dev/null && ufw allow 54321/tcp &>/dev/null && ufw allow 2087/tcp &>/dev/null && ufw allow 80/tcp &>/dev/null || true
    command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport 54321 -j ACCEPT 2>/dev/null || true
    command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport 2087 -j ACCEPT 2>/dev/null || true
    if command -v firewall-cmd &>/dev/null && systemctl is-active --quiet firewalld 2>/dev/null; then
        firewall-cmd --add-port=54321/tcp --permanent &>/dev/null || true
        firewall-cmd --add-port=2087/tcp --permanent &>/dev/null || true
        firewall-cmd --reload &>/dev/null || true
    fi

    echo -e "\n${C_BLUE}🔍 Step 4/4: Verifying service and access...${C_RESET}"
    repair_xui_access "3X-UI Panel"
}

install_xui_panel_alireza0() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 📦 Install X-UI Panel (alireza0) ---${C_RESET}"
    echo
    echo -e "  ${C_CYAN}Choose installation mode:${C_RESET}\n"
    printf "  ${C_CHOICE}[ 1]${C_RESET} %s %s\n" "$(pad_right '⚡ Automated Quick Install (Free deSEC SSL Domain + Port 54321)' 60)" "${C_STATUS_A}⭐ Recommended${C_RESET}"
    printf "  ${C_CHOICE}[ 2]${C_RESET} %s %s\n" "$(pad_right '🛠️  Standard Interactive Installation (Official Wizard)' 60)" ""
    echo
    printf "  ${C_DANGER}[ 0]${C_RESET} Cancel\n"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select mode [1]: "${C_RESET})" inst_mode
    inst_mode=${inst_mode:-1}

    case "$inst_mode" in
        1)
            echo -e "\n${C_BLUE}🌐 Step 1/4: Provisioning Free deSEC SSL Domain (*.dahoom.dedyn.io)...${C_RESET}"
            local panel_domain=""
            if [[ -f "$DNS_INFO_FILE" ]]; then
                source "$DNS_INFO_FILE" 2>/dev/null
                panel_domain="$FULL_DOMAIN"
            fi
            if [[ -z "$panel_domain" ]]; then
                generate_dns_record </dev/null 2>&1 || true
                if [[ -f "$DNS_INFO_FILE" ]]; then
                    source "$DNS_INFO_FILE" 2>/dev/null
                    panel_domain="$FULL_DOMAIN"
                fi
            fi
            if [[ -n "$panel_domain" ]]; then
                echo -e "  ${C_GREEN}✔ Dedicated Domain:${C_RESET} ${C_YELLOW}${panel_domain}${C_RESET}"
            fi

            echo -e "\n${C_BLUE}📦 Step 2/4: Installing X-UI Core Files...${C_RESET}"
            mkdir -p "/etc/firewallfalcon" 2>/dev/null
            echo "x-ui" > "/etc/firewallfalcon/.panel_type" 2>/dev/null || true
            printf "y\n54321\n" | bash <(curl -Ls "$(_fm_xui_install_url)") || true

            echo -e "\n${C_BLUE}🔒 Step 3/4: Configuring SSL Certificate & Panel Security...${C_RESET}"
            local cert_file="" key_file=""
            if [[ -n "$panel_domain" ]]; then
                if ! command -v certbot &>/dev/null; then
                    ff_pkg_install certbot >/dev/null 2>&1 || true
                fi
                if command -v certbot &>/dev/null; then
                    systemctl stop nginx &>/dev/null || true
                    systemctl stop haproxy &>/dev/null || true
                    command -v fuser &>/dev/null && fuser -k 80/tcp &>/dev/null || true
                    certbot certonly --standalone -d "$panel_domain" --agree-tos --register-unsafely-without-email --non-interactive >/dev/null 2>&1 || true
                    systemctl start nginx &>/dev/null || true
                    systemctl start haproxy &>/dev/null || true
                    if [[ -f "/etc/letsencrypt/live/$panel_domain/fullchain.pem" && -f "/etc/letsencrypt/live/$panel_domain/privkey.pem" ]]; then
                        cert_file="/etc/letsencrypt/live/$panel_domain/fullchain.pem"
                        key_file="/etc/letsencrypt/live/$panel_domain/privkey.pem"
                    fi
                fi
            fi

            if command -v python3 &>/dev/null && [[ -f "/etc/x-ui/x-ui.db" ]]; then
                python3 -c "
import sqlite3, os
db = '/etc/x-ui/x-ui.db'
if os.path.exists(db):
    try:
        conn = sqlite3.connect(db)
        c = conn.cursor()
        c.execute(\"DELETE FROM settings WHERE key IN ('webPort', 'port', 'webCertFile', 'webKeyFile')\")
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webPort', '54321'))
        if '$cert_file' and '$key_file' and os.path.isfile('$cert_file') and os.path.isfile('$key_file'):
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', '$cert_file'))
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', '$key_file'))
        else:
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', ''))
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', ''))
        conn.commit()
        conn.close()
    except Exception:
        pass
" 2>/dev/null || true
            fi

            echo -e "\n${C_BLUE}🔥 Step 4/4: Opening Firewall & Starting Service...${C_RESET}"
            command -v ufw &>/dev/null && ufw allow 54321/tcp &>/dev/null && ufw allow 80/tcp &>/dev/null || true
            command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport 54321 -j ACCEPT 2>/dev/null || true
            if command -v firewall-cmd &>/dev/null && systemctl is-active --quiet firewalld 2>/dev/null; then
                firewall-cmd --add-port=54321/tcp --permanent &>/dev/null || true
                firewall-cmd --reload &>/dev/null || true
            fi

            pkill -9 -f "x-ui" 2>/dev/null || true
            sleep 0.5
            systemctl daemon-reload 2>/dev/null || true
            systemctl enable x-ui 2>/dev/null || true
            systemctl restart x-ui 2>/dev/null || true
            sleep 1.5

            echo -e "\n${C_GREEN}✅ X-UI Installation Finished!${C_RESET}\n"
            show_xui_access_info "X-UI Panel"
            ;;
        2)
            echo -e "\n  Downloading and running official X-UI interactive installer..."
            mkdir -p "/etc/firewallfalcon" 2>/dev/null
            echo "x-ui" > "/etc/firewallfalcon/.panel_type" 2>/dev/null || true
            bash <(curl -Ls "$(_fm_xui_install_url)")
            repair_xui_access "X-UI Panel"
            ;;
        0)
            echo -e "\n${C_YELLOW}❌ Installation cancelled.${C_RESET}"
            return
            ;;
        *)
            invalid_option
            ;;
    esac
}

uninstall_xui_panel() {
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        clear; show_banner
        echo -e "${C_BOLD}${C_PURPLE}--- 🗑️ Uninstall X-UI Panel ---${C_RESET}"
    fi
    if ! command -v x-ui &>/dev/null && [ ! -d /usr/local/x-ui ] && [ ! -f /etc/systemd/system/x-ui.service ] && [ ! -f /lib/systemd/system/x-ui.service ]; then
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "\n${C_YELLOW}ℹ️ No X-UI panel appears to be installed.${C_RESET}"
        fi
        return
    fi
    local confirm="y"
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        read -p "👉 Are you sure you want to thoroughly uninstall X-UI? (y/n): " confirm
    fi
    if [[ "$confirm" == "y" || "$confirm" == "Y" ]]; then
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "\n${C_BLUE}⚙️ Running uninstaller and removing services...${C_RESET}"
        fi
        x-ui uninstall >/dev/null 2>&1 || true
        systemctl stop x-ui >/dev/null 2>&1 || true
        systemctl disable x-ui >/dev/null 2>&1 || true
        pkill -9 -f "x-ui" >/dev/null 2>&1 || true
        rm -f /etc/systemd/system/x-ui.service /lib/systemd/system/x-ui.service
        rm -f /usr/local/bin/x-ui /usr/bin/x-ui
        rm -rf /usr/local/x-ui/
        rm -rf /etc/x-ui/
        rm -f "/etc/firewallfalcon/.panel_type"
        systemctl daemon-reload 2>/dev/null || true
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "\n${C_GREEN}✅ X-UI has been thoroughly uninstalled.${C_RESET}"
        fi
    else
        echo -e "\n${C_YELLOW}❌ Uninstallation cancelled.${C_RESET}"
    fi
}

show_xui_access_info() {
    local panel_name="${1:-X-UI Panel}"
    local db_path="/etc/x-ui/x-ui.db"
    local env_path="/etc/x-ui/install-result.env"
    local server_ip="${GLOBAL_SERVER_IPV4:-}"
    if [[ -z "$server_ip" ]]; then
        if [[ -f "$DNS_INFO_FILE" ]]; then
            server_ip=$(grep -E '^SERVER_IPV4=' "$DNS_INFO_FILE" 2>/dev/null | cut -d'=' -f2 | tr -d '"')
        fi
        if [[ -z "$server_ip" ]]; then
            server_ip=$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')
        fi
        [[ -z "$server_ip" ]] && server_ip="127.0.0.1"
        GLOBAL_SERVER_IPV4="$server_ip"
    fi
    
    # Which domain the URLs below are built from. The certificate the panel
    # is ACTUALLY serving decides this — not whichever deSEC domain this
    # project may have provisioned earlier. An admin who installs a
    # certificate for their own domain gets valid HTTPS for that name only,
    # so naming the deSEC domain here would print an https:// URL that their
    # own browser rejects on a certificate-name mismatch. deSEC stays the
    # fallback, for when no certificate domain can be determined.
    local domain_name="" domain_label="Free SSL Domain"
    domain_name=$(_fm_xui_active_cert_domain)
    if [[ -n "$domain_name" ]]; then
        domain_label="SSL Domain"
    elif [[ -f "$DNS_INFO_FILE" ]]; then
        source "$DNS_INFO_FILE" 2>/dev/null
        domain_name="$FULL_DOMAIN"
    fi

    echo -e "  ${C_PURPLE}──────────────── ${panel_name^^} ACCESS INFO ────────────────${C_RESET}"
    
    local port="" base_path="" user="" pass="" has_cert="false"

    # 1. Parse install-result.env if present.
    #    Three shapes are accepted because the X-UI variants write different
    #    ones: "Key: value", bare "KEY=value", and 3x-ui's "XUI_KEY=value"
    #    (whose values go through printf %q, so they can carry surrounding
    #    quotes). Without the XUI_ shape a 3x-ui install shows no credentials
    #    at all — and it generates BOTH the password and an 18-character random
    #    web base path, so there is nothing to fall back on.
    if [[ -f "$env_path" ]]; then
        _xui_env_val() {
            grep -E "^$1=" "$env_path" 2>/dev/null | head -n1 | cut -d'=' -f2- | tr -d "\"'"
        }

        user=$(grep -E '^Username:' "$env_path" 2>/dev/null | awk '{print $2}')
        [[ -z "$user" ]] && user=$(_xui_env_val USERNAME)
        [[ -z "$user" ]] && user=$(_xui_env_val XUI_USERNAME)

        pass=$(grep -E '^Password:' "$env_path" 2>/dev/null | awk '{print $2}')
        [[ -z "$pass" ]] && pass=$(_xui_env_val PASSWORD)
        [[ -z "$pass" ]] && pass=$(_xui_env_val XUI_PASSWORD)

        port=$(grep -E '^Port:' "$env_path" 2>/dev/null | awk '{print $2}')
        [[ -z "$port" ]] && port=$(_xui_env_val PORT)
        [[ -z "$port" ]] && port=$(_xui_env_val XUI_PANEL_PORT)

        base_path=$(grep -E '^WebBasePath:' "$env_path" 2>/dev/null | awk '{print $2}')
        [[ -z "$base_path" ]] && base_path=$(_xui_env_val WEBBASEPATH)
        [[ -z "$base_path" ]] && base_path=$(_xui_env_val XUI_WEB_BASE_PATH)

        unset -f _xui_env_val
    fi

    # 2. Query SQLite database (always read real live settings from /etc/x-ui/x-ui.db)
    if [[ -f "$db_path" ]] && command -v python3 &>/dev/null; then
        local _xui_parsed
        _xui_parsed=$(python3 <<'EOF'
import sqlite3, os

db_file = "/etc/x-ui/x-ui.db"
res = {"port": "54321", "base_path": "", "user": "admin", "pass": "admin", "has_cert": False}

if os.path.exists(db_file):
    try:
        conn = sqlite3.connect(db_file)
        c = conn.cursor()
        c.execute("SELECT key, value FROM settings")
        cert_file = ""
        key_file = ""
        for k, v in c.fetchall():
            val = str(v).strip()
            if k in ("webPort", "port") and val and val != "0":
                res["port"] = val
            elif k in ("webBasePath", "basePath") and val:
                res["base_path"] = val
            elif k in ("webCertFile", "webCert") and val:
                cert_file = val
            elif k in ("webKeyFile", "webCertKey") and val:
                key_file = val

        if cert_file and key_file and os.path.isfile(cert_file) and os.path.isfile(key_file) and os.path.getsize(cert_file) > 0:
            res["has_cert"] = True
        else:
            live_dir = "/etc/letsencrypt/live"
            if os.path.isdir(live_dir):
                for d in sorted(os.listdir(live_dir)):
                    fc = os.path.join(live_dir, d, "fullchain.pem")
                    pk = os.path.join(live_dir, d, "privkey.pem")
                    if os.path.isfile(fc) and os.path.isfile(pk) and os.path.getsize(fc) > 0:
                        res["has_cert"] = True
                        break

        try:
            c.execute("SELECT username, password FROM users LIMIT 1")
            row = c.fetchone()
            if row:
                res["user"] = str(row[0])
                res["pass"] = str(row[1])
        except:
            pass

        conn.close()
    except Exception:
        pass

print(f"port='{res['port']}'; base_path='{res['base_path']}'; user='{res['user']}'; pass='{res['pass']}'; has_cert='{str(res['has_cert']).lower()}'")
EOF
)
        if [[ -n "$_xui_parsed" ]]; then
            eval "$_xui_parsed"
        fi
    fi

    # 3. Fallbacks and Port Sanitization
    if [[ -z "$port" || "$port" == "0" || ! "$port" =~ ^[0-9]+$ ]]; then
        port="54321"
    fi

    [[ -z "$user" ]] && user="admin"
    if [[ -z "$pass" || "$pass" == \$2* ]]; then
        pass="admin (or password set during installation)"
    fi

    # 4. Format URL
    base_path=$(echo "$base_path" | sed 's|^/||;s|/$||')
    local proto="http"
    [[ "$has_cert" == "true" ]] && proto="https"

    local domain_url="" ip_url="" domain_http_url="" ip_http_url=""
    if [[ -n "$base_path" ]]; then
        [[ -n "$domain_name" ]] && domain_url="${proto}://${domain_name}:${port}/${base_path}/"
        [[ -n "$domain_name" ]] && domain_http_url="http://${domain_name}:${port}/${base_path}/"
        ip_url="${proto}://${server_ip}:${port}/${base_path}/"
        ip_http_url="http://${server_ip}:${port}/${base_path}/"
    else
        [[ -n "$domain_name" ]] && domain_url="${proto}://${domain_name}:${port}/"
        [[ -n "$domain_name" ]] && domain_http_url="http://${domain_name}:${port}/"
        ip_url="${proto}://${server_ip}:${port}/"
        ip_http_url="http://${server_ip}:${port}/"
    fi

    local live_status="${C_GREEN}🟢 Active (Running)${C_RESET}"
    if ! pgrep -x x-ui &>/dev/null; then
        live_status="${C_RED}🔴 Stopped (Try Fix & Repair Access)${C_RESET}"
    fi

    echo -e "  ${C_CYAN}Service Status :${C_RESET} ${live_status}"
    echo -e "  ${C_CYAN}Server IP      :${C_RESET} ${C_YELLOW}${server_ip}${C_RESET}"
    if [[ -n "$domain_name" ]]; then
        printf "  ${C_CYAN}%-15s:${C_RESET} ${C_GREEN}%s${C_RESET}\n" "$domain_label" "$domain_name"
    fi
    echo -e "  ${C_CYAN}Dedicated Port :${C_RESET} ${C_YELLOW}${port}${C_RESET}"
    echo -e "  ${C_CYAN}Username       :${C_RESET} ${C_GREEN}${user}${C_RESET}"
    echo -e "  ${C_CYAN}Password       :${C_RESET} ${C_GREEN}${pass}${C_RESET}"
    if [[ -n "$base_path" ]]; then
        echo -e "  ${C_CYAN}Web Base Path  :${C_RESET} ${C_YELLOW}/${base_path}/${C_RESET}"
    fi
    echo -e "  ${C_CYAN}Protocol       :${C_RESET} ${C_YELLOW}${proto^^}${C_RESET}"
    if [[ -n "$domain_url" ]]; then
        echo -e "  ${C_CYAN}Direct Domain  :${C_RESET} ${C_GREEN}${domain_url}${C_RESET}"
    fi
    echo -e "  ${C_CYAN}Direct IP URL  :${C_RESET} ${C_GREEN}${ip_url}${C_RESET}"
    if [[ "$proto" == "https" ]]; then
        if [[ -n "$domain_http_url" ]]; then
            echo -e "  ${C_CYAN}HTTP Domain URL:${C_RESET} ${C_YELLOW}${domain_http_url}${C_RESET}"
        fi
        echo -e "  ${C_CYAN}HTTP IP URL    :${C_RESET} ${C_YELLOW}${ip_http_url}${C_RESET}"
    fi
    echo -e "  ${C_CYAN}Docs / Repo    :${C_RESET} https://github.com/mooa322/X-UI"
    echo -e "  ${C_PURPLE}────────────────────────────────────────────────────────${C_RESET}"
    echo
}

# Finds a TCP port in [start,end] nothing is using — checked two ways, not
# just `ss -ltn` (LISTENING only): a port can be unusable even without a
# listener on it, e.g. a socket sitting in ESTABLISHED state with that as
# its local port (confirmed in the wild: this project's own Net Relay
# feature routinely leaves one open on the very port 3x-ui's Sub Server
# defaults to). `lsof` sees that state too, `ss -ltn` alone does not.
_fm_find_free_port() {
    local start="$1" end="$2" exclude="${3:-}" p
    for ((p=start; p<=end; p++)); do
        [[ "$p" == "$exclude" ]] && continue
        if command -v ss &>/dev/null && ss -tln 2>/dev/null | grep -q ":${p} "; then
            continue
        fi
        if command -v lsof &>/dev/null && lsof -i ":${p}" &>/dev/null; then
            continue
        fi
        echo "$p"
        return 0
    done
    return 1
}

repair_xui_access() {
    local panel_name="${1:-X-UI Panel}"
    local db_path="/etc/x-ui/x-ui.db"
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🔧 Auto-Repair ${panel_name} Access & Ports ---${C_RESET}\n"

    echo -e "  ${C_CYAN}Step 1/5:${C_RESET} Inspecting x-ui installation..."
    if [[ ! -f "$db_path" && ! -d "/usr/local/x-ui" ]]; then
        echo -e "  ${C_RED}❌ x-ui installation files not found at /usr/local/x-ui.${C_RESET}"
        return
    fi

    echo -e "  ${C_CYAN}Step 2/5:${C_RESET} Reading, sanitizing and repairing panel settings..."
    local default_port="54321"
    local port="$default_port"
    if [[ -f "$db_path" ]] && command -v python3 &>/dev/null; then
        port=$(python3 -c "
import sqlite3, os
p = '$default_port'
try:
    if os.path.exists('/etc/x-ui/x-ui.db'):
        conn = sqlite3.connect('/etc/x-ui/x-ui.db')
        c = conn.cursor()
        c.execute(\"SELECT value FROM settings WHERE key IN ('webPort', 'port') LIMIT 1\")
        row = c.fetchone()
        if row and str(row[0]).strip() and str(row[0]).strip() != '0':
            p = str(row[0]).strip()
        c.execute(\"DELETE FROM settings WHERE key IN ('webPort', 'port')\")
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webPort', p))
        
        # Verify if SSL cert paths in DB exist. If broken, search for valid cert in /etc/letsencrypt/live/
        c.execute(\"SELECT key, value FROM settings WHERE key IN ('webCertFile', 'webKeyFile')\")
        cert_rows = dict(c.fetchall())
        c_file = cert_rows.get('webCertFile', '')
        k_file = cert_rows.get('webKeyFile', '')

        if not (c_file and k_file and os.path.isfile(c_file) and os.path.isfile(k_file)):
            found_cert, found_key = '', ''
            live_dir = '/etc/letsencrypt/live'
            if os.path.isdir(live_dir):
                for d in sorted(os.listdir(live_dir)):
                    cand_cert = os.path.join(live_dir, d, 'fullchain.pem')
                    cand_key = os.path.join(live_dir, d, 'privkey.pem')
                    if os.path.isfile(cand_cert) and os.path.isfile(cand_key):
                        found_cert, found_key = cand_cert, cand_key
                        break
            c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile')\")
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', found_cert))
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', found_key))
        
        conn.commit()
        conn.close()
except:
    pass
print(p)
" 2>/dev/null || echo "$default_port")
    fi
    echo -e "  ${C_GREEN}✔ Dedicated Port verified:${C_RESET} ${C_YELLOW}${port}${C_RESET}"

    echo -e "  ${C_CYAN}Step 3/5:${C_RESET} Unblocking firewall ports (UFW, Iptables, Firewalld)..."
    command -v ufw &>/dev/null && ufw allow "${port}/tcp" &>/dev/null || true
    command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport "${port}" -j ACCEPT 2>/dev/null || true
    if command -v firewall-cmd &>/dev/null && systemctl is-active --quiet firewalld 2>/dev/null; then
        firewall-cmd --add-port="${port}/tcp" --permanent &>/dev/null || true
        firewall-cmd --reload &>/dev/null || true
    fi
    echo -e "  ${C_GREEN}✔ Port ${port} opened across all firewall layers.${C_RESET}"

    echo -e "  ${C_CYAN}Step 4/5:${C_RESET} Killing hanging processes & restarting x-ui daemon..."
    pkill -9 -f "x-ui" 2>/dev/null || true
    sleep 0.5
    systemctl daemon-reload 2>/dev/null || true
    systemctl enable x-ui 2>/dev/null || true
    systemctl restart x-ui 2>/dev/null || true
    sleep 1.5

    echo -e "  ${C_CYAN}Step 5/5:${C_RESET} Checking listening status..."
    local is_listening=false
    if command -v ss &>/dev/null; then
        ss -tulpn 2>/dev/null | grep -q ":${port} " && is_listening=true
    elif command -v netstat &>/dev/null; then
        netstat -tulpn 2>/dev/null | grep -q ":${port} " && is_listening=true
    fi

    if $is_listening || systemctl is-active --quiet x-ui 2>/dev/null; then
        echo -e "  ${C_GREEN}✅ Success! ${panel_name} service is running and listening on port ${port}.${C_RESET}"
    else
        echo -e "  ${C_RED}❌ The service did NOT come back up — it is still stopped/crashing.${C_RESET}"
        local recent_log
        recent_log=$(journalctl -u x-ui -n 15 --no-pager 2>/dev/null)
        echo -e "  ${C_GRAY}Recent log lines:${C_RESET}"
        echo "$recent_log" | sed 's/^/    /'

        # 3x-ui only: on top of the panel's own port (handled above), it
        # runs a separate "Sub Server" for subscription links that binds
        # its own port at startup (subPort, 2087 by default as of this
        # version) — and the WHOLE process exits if that one bind fails,
        # taking the panel and xray down with it too. This can collide with
        # other services like this project's Net Relay feature. Auto-detect
        # that specific failure and move the sub server to a free port
        # instead of just logging a mystery crash.
        local stuck_port
        stuck_port=$(grep -oP 'Error starting sub server: listen tcp :\K[0-9]+' <<<"$recent_log" | tail -1)
        if [[ -n "$stuck_port" ]]; then
            echo
            echo -e "  ${C_YELLOW}⚠️  Found the real cause: 3x-ui's subscription-link server can't${C_RESET}"
            echo -e "  ${C_YELLOW}     bind port ${stuck_port} — something else on this server is already${C_RESET}"
            echo -e "  ${C_YELLOW}     using it, which crashes the whole panel, not just that feature.${C_RESET}"
            if command -v lsof &>/dev/null; then
                local holder
                holder=$(lsof -i ":${stuck_port}" 2>/dev/null | awk 'NR==2{print $1" (PID "$2")"}')
                [[ -n "$holder" ]] && echo -e "  ${C_GRAY}     Held by: ${C_YELLOW}${holder}${C_RESET}"
            fi

            local new_sub_port
            new_sub_port=$(_fm_find_free_port 2087 2200 "$stuck_port")
            if [[ -n "$new_sub_port" ]] && command -v python3 &>/dev/null; then
                echo -e "  ${C_BLUE}     Moving the subscription server to port ${new_sub_port} instead...${C_RESET}"
                python3 -c "
import sqlite3
try:
    conn = sqlite3.connect('$db_path')
    c = conn.cursor()
    c.execute(\"DELETE FROM settings WHERE key='subPort'\")
    c.execute(\"INSERT INTO settings (key, value) VALUES ('subPort', ?)\", ('$new_sub_port',))
    conn.commit()
    conn.close()
except Exception:
    pass
" 2>/dev/null || true
                command -v ufw &>/dev/null && ufw allow "${new_sub_port}/tcp" &>/dev/null || true
                command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport "${new_sub_port}" -j ACCEPT 2>/dev/null || true
                systemctl restart x-ui 2>/dev/null || true
                sleep 1.5
                if systemctl is-active --quiet x-ui 2>/dev/null; then
                    echo -e "  ${C_GREEN}✅ Fixed — ${panel_name} is now running (subscription server moved to port ${new_sub_port}).${C_RESET}"
                else
                    echo -e "  ${C_RED}❌ Still not running — run Fix & Repair Access again, or check the log above for a different error.${C_RESET}"
                fi
            else
                echo -e "  ${C_RED}     Could not find a free port to move it to automatically — free port ${stuck_port} yourself and try again.${C_RESET}"
            fi
        else
            echo -e "  ${C_YELLOW}If the log above doesn't explain it, try option [3] to reset port/credentials.${C_RESET}"
        fi
    fi

    show_xui_access_info "$panel_name"
}

reset_xui_credentials() {
    local panel_name="${1:-X-UI Panel}"
    local db_path="/etc/x-ui/x-ui.db"
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🔑 Reset ${panel_name} Port & Credentials ---${C_RESET}\n"

    read -r -p "$(echo -e ${C_PROMPT}"> Enter new Port [54321]: "${C_RESET})" new_port
    new_port=${new_port:-54321}
    if ! [[ "$new_port" =~ ^[0-9]+$ ]] || (( new_port < 1 || new_port > 65535 )); then
        echo -e "\n${C_RED}❌ Invalid port number. Must be between 1 and 65535.${C_RESET}"
        return
    fi

    # "admin"/"admin" used to be the silent default here on a bare Enter —
    # which is exactly what 3x-ui's OWN installer treats as "insecure
    # defaults detected" on its next run, quietly minting a replacement API
    # token that this reset never touches (see _xui_api's own retry logic
    # in panel.py, which recovers from that — but the factory-default
    # credentials it caused are a real hole in the meantime: literally
    # every 3x-ui install online is checked against "admin"/"admin" first
    # by anyone probing it). A random default closes that without changing
    # this menu's shape — still just press Enter to accept it.
    local rand_user rand_pass
    rand_user=$(tr -dc 'a-z0-9' < /dev/urandom | head -c 10)
    rand_pass=$(tr -dc 'A-Za-z0-9' < /dev/urandom | head -c 16)
    read -r -p "$(echo -e ${C_PROMPT}"> Enter new Username [${rand_user}]: "${C_RESET})" new_user
    new_user=${new_user:-$rand_user}

    read -r -p "$(echo -e ${C_PROMPT}"> Enter new Password [${rand_pass}]: "${C_RESET})" new_pass
    new_pass=${new_pass:-$rand_pass}

    read -r -p "$(echo -e ${C_PROMPT}"> Reset Base Path to root (/) ? (y/n) [y]: "${C_RESET})" reset_path
    reset_path=${reset_path:-y}

    echo -e "\n${C_BLUE}⚙️ Updating database settings...${C_RESET}"
    if command -v python3 &>/dev/null; then
        python3 -c "
import sqlite3, os
db = '$db_path'
if os.path.exists(db):
    try:
        conn = sqlite3.connect(db)
        c = conn.cursor()
        c.execute(\"DELETE FROM settings WHERE key IN ('webPort', 'port')\")
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webPort', '$new_port'))
        if '${reset_path,,}' == 'y':
            c.execute(\"DELETE FROM settings WHERE key IN ('webBasePath', 'basePath', 'webCertFile', 'webKeyFile')\")
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webBasePath', ''))
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', ''))
            c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', ''))
        c.execute(\"UPDATE users SET username=?, password=? WHERE id=1 OR rowid=1\", ('$new_user', '$new_pass'))
        if c.rowcount == 0:
            c.execute(\"INSERT OR REPLACE INTO users (id, username, password) VALUES (1, ?, ?)\", ('$new_user', '$new_pass'))
        conn.commit()
        conn.close()
        print('DB_OK')
    except Exception as e:
        print('ERR:' + str(e))
" 2>/dev/null
    fi

    # Unblock new port in firewall
    command -v ufw &>/dev/null && ufw allow "${new_port}/tcp" &>/dev/null || true
    command -v iptables &>/dev/null && iptables -I INPUT -p tcp --dport "${new_port}" -j ACCEPT 2>/dev/null || true
    if command -v firewall-cmd &>/dev/null && systemctl is-active --quiet firewalld 2>/dev/null; then
        firewall-cmd --add-port="${new_port}/tcp" --permanent &>/dev/null || true
        firewall-cmd --reload &>/dev/null || true
    fi

    # Restart x-ui
    systemctl restart x-ui 2>/dev/null || true
    sleep 1

    echo -e "${C_GREEN}✅ Credentials, Port & Firewall updated successfully!${C_RESET}\n"
    show_xui_access_info "$panel_name"
}

sync_xui_domain_ssl() {
    local panel_name="${1:-X-UI Panel}"
    local new_domain="$2"
    local db_path="/etc/x-ui/x-ui.db"

    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}--- 🔄 Rebuild & Sync SSL Certificate (${new_domain}) ---${C_RESET}\n"

    if [[ -z "$new_domain" ]]; then
        echo -e "${C_RED}❌ No active system domain provided.${C_RESET}"
        return 1
    fi

    echo -e "  ${C_BLUE}🌐 Step 1/3: Requesting Let's Encrypt SSL certificate for ${C_YELLOW}${new_domain}${C_BLUE}...${C_RESET}"
    if ! command -v certbot &>/dev/null; then
        ff_pkg_install certbot >/dev/null 2>&1 || true
    fi

    local cert_file="" key_file=""
    if command -v certbot &>/dev/null; then
        systemctl stop nginx &>/dev/null || true
        systemctl stop haproxy &>/dev/null || true
        command -v fuser &>/dev/null && fuser -k 80/tcp &>/dev/null || true
        certbot certonly --standalone -d "$new_domain" --agree-tos --register-unsafely-without-email --non-interactive >/dev/null 2>&1 || true
        systemctl start nginx &>/dev/null || true
        systemctl start haproxy &>/dev/null || true
        if [[ -f "/etc/letsencrypt/live/$new_domain/fullchain.pem" && -f "/etc/letsencrypt/live/$new_domain/privkey.pem" ]]; then
            cert_file="/etc/letsencrypt/live/$new_domain/fullchain.pem"
            key_file="/etc/letsencrypt/live/$new_domain/privkey.pem"
        fi
    fi

    if [[ -z "$cert_file" || -z "$key_file" ]]; then
        echo -e "  ${C_RED}❌ Failed to obtain SSL certificate for ${new_domain}.${C_RESET}"
        echo -e "  ${C_YELLOW}ℹ️ Ensure port 80 is reachable and DNS has propagated.${C_RESET}"
        return 1
    fi

    echo -e "  ${C_GREEN}✔ SSL Certificate obtained successfully!${C_RESET}"

    echo -e "\n  ${C_BLUE}🔒 Step 2/3: Mirroring certificates & updating ${panel_name} database...${C_RESET}"
    mkdir -p "/root/cert/${new_domain}" 2>/dev/null
    cp -f "$cert_file" "/root/cert/${new_domain}/fullchain.pem" 2>/dev/null || true
    cp -f "$key_file" "/root/cert/${new_domain}/privkey.pem" 2>/dev/null || true
    cp -f "$cert_file" "/root/cert.crt" 2>/dev/null || true
    cp -f "$key_file" "/root/private.key" 2>/dev/null || true

    if command -v python3 &>/dev/null && [[ -f "$db_path" ]]; then
        python3 -c "
import sqlite3, os
db = '$db_path'
if os.path.exists(db):
    try:
        conn = sqlite3.connect(db)
        c = conn.cursor()
        c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile', 'webCert', 'webCertKey')\")
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', '$cert_file'))
        c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', '$key_file'))
        conn.commit()
        conn.close()
    except Exception as e:
        print('DB_ERR:', e)
" 2>/dev/null || true
    fi

    echo -e "\n  ${C_BLUE}⚙️ Step 3/3: Restarting ${panel_name} service...${C_RESET}"
    systemctl daemon-reload 2>/dev/null || true
    systemctl restart x-ui 2>/dev/null || true
    sleep 1

    # Rebuilding onto this domain is itself a deliberate choice, so record it
    # the same way the SSL menu's own set/import actions do — otherwise the
    # pin would still name whatever domain was replaced here.
    _fm_xui_pin_domain "$new_domain"

    echo -e "\n  ${C_GREEN}✅ Domain & SSL Certificate synced and applied successfully!${C_RESET}\n"
    show_xui_access_info "$panel_name"
}

show_xui_client_configs() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}────────────────── 📡 X-UI CLIENT CONFIGURATIONS ──────────────────${C_RESET}\n"

    local db_path="/etc/x-ui/x-ui.db"
    if [[ ! -f "$db_path" ]]; then
        echo -e "  ${C_RED}❌ X-UI database not found at ${db_path}.${C_RESET}"
        return
    fi

    local server_ip="${GLOBAL_SERVER_IPV4:-}"
    if [[ -z "$server_ip" ]]; then
        if [[ -f "$DNS_INFO_FILE" ]]; then
            server_ip=$(grep -E '^SERVER_IPV4=' "$DNS_INFO_FILE" 2>/dev/null | cut -d'=' -f2 | tr -d '"')
        fi
        if [[ -z "$server_ip" ]]; then
            server_ip=$(ip route get 1.1.1.1 2>/dev/null | awk '{print $7; exit}')
        fi
        [[ -z "$server_ip" ]] && server_ip="127.0.0.1"
    fi
    local domain_name=""
    if [[ -f "$DNS_INFO_FILE" ]]; then
        source "$DNS_INFO_FILE" 2>/dev/null
        domain_name="$FULL_DOMAIN"
    fi

    python3 -c "
import sqlite3, json, base64, urllib.parse

db = '$db_path'
server_ip = '$server_ip'
domain = '$domain_name'
host = domain if domain else server_ip

try:
    conn = sqlite3.connect(db)
    cur = conn.cursor()
    cur.execute('SELECT id, remark, port, protocol, settings, stream_settings, enable FROM inbounds')
    rows = cur.fetchall()
    conn.close()

    if not rows:
        print('  \033[0;33m⚠️ No inbounds (configurations) found in X-UI database.\033[0m')
        print('  \033[0;36m👉 Create inbounds inside the X-UI Web Panel to generate config links here.\033[0m\n')
    else:
        print(f'  \033[0;32m✔ Found {len(rows)} inbound service(s) configured:\033[0m\n')
        for r in rows:
            inbound_id, remark, port, proto, settings_str, stream_str, enable = r
            status_tag = '\033[0;32m[Enabled]\033[0m' if enable else '\033[0;31m[Disabled]\033[0m'
            remark = remark if remark else f'Inbound-{inbound_id}'
            print(f'  \033[1;37m┌── #{inbound_id} {remark} ({proto.upper()}:{port}) {status_tag} ──┐\033[0m')
            
            try:
                settings = json.loads(settings_str) if settings_str else {}
            except:
                settings = {}
            try:
                stream = json.loads(stream_str) if stream_str else {}
            except:
                stream = {}

            net = stream.get('network', 'tcp')
            sec = stream.get('security', 'none')
            clients = settings.get('clients', [])

            print(f'  \033[0;36m│\033[0m Protocol : \033[0;33m{proto.upper()}\033[0m | Network: \033[0;33m{net}\033[0m | Security: \033[0;33m{sec}\033[0m')
            print(f'  \033[0;36m│\033[0m Address  : \033[0;32m{host}\033[0m | Port: \033[0;33m{port}\033[0m')

            if clients:
                for idx, c in enumerate(clients, 1):
                    uuid = c.get('id', c.get('password', ''))
                    email = c.get('email', f'client{idx}')
                    tag = f'{remark}-{email}'
                    encoded_tag = urllib.parse.quote(tag)

                    link = ''
                    if proto == 'vless':
                        flow = c.get('flow', '')
                        flow_param = f'&flow={flow}' if flow else ''
                        link = f'vless://{uuid}@{host}:{port}?type={net}&security={sec}{flow_param}#{encoded_tag}'
                    elif proto == 'vmess':
                        vmess_dict = {
                            'v': '2',
                            'ps': tag,
                            'add': host,
                            'port': port,
                            'id': uuid,
                            'aid': c.get('alterId', 0),
                            'net': net,
                            'type': 'none',
                            'host': '',
                            'path': '',
                            'tls': 'tls' if sec == 'tls' else ''
                        }
                        raw_b64 = base64.b64encode(json.dumps(vmess_dict).encode()).decode()
                        link = f'vmess://{raw_b64}'
                    elif proto == 'trojan':
                        link = f'trojan://{uuid}@{host}:{port}?security={sec}&type={net}#{encoded_tag}'
                    elif proto == 'shadowsocks':
                        method = settings.get('method', 'aes-256-gcm')
                        userpass = f'{method}:{uuid}'
                        b64_up = base64.b64encode(userpass.encode()).decode()
                        link = f'ss://{b64_up}@{host}:{port}#{encoded_tag}'

                    if link:
                        print(f'  \033[0;36m│\033[0m Client #{idx} ({email}):')
                        print(f'  \033[0;32m  {link}\033[0m')
            else:
                print('  \033[0;36m│\033[0m No individual client UUIDs defined.')

            print('  \033[1;37m└──────────────────────────────────────────────────────────┘\033[0m\n')

except Exception as e:
    print('  \033[0;31m❌ Error reading X-UI configurations:\033[0m', e)
" 2>/dev/null
}

show_xui_speed_wiki() {
    clear; show_banner
    echo -e "${C_BOLD}${C_PURPLE}──────────────── 🚀 X-UI SPEED & TUNING WIKI ────────────────${C_RESET}\n"

    echo -e "  ${C_CYAN}1. BBR Congestion Control (Google BBR v1/v3):${C_RESET}"
    echo -e "     • Maximizes throughput on lossy, high-latency wireless and mobile networks."
    local cur_cc; cur_cc=$(sysctl net.ipv4.tcp_congestion_control 2>/dev/null | awk '{print $3}')
    echo -e "     • Current TCP Alg : ${C_GREEN}${cur_cc:-cubic}${C_RESET}"
    if [[ "$cur_cc" != "bbr" ]]; then
        echo -e "     • ${C_YELLOW}Recommendation: Enable BBR from System Optimization menu [Option 38].${C_RESET}"
    fi

    echo -e "\n  ${C_CYAN}2. Protocol & Transport Performance Guide:${C_RESET}"
    echo -e "     • ${C_BOLD}VLESS + XTLS / REALITY (TCP)${C_RESET}: Fastest performance, lowest CPU overhead, zero TLS-in-TLS."
    echo -e "     • ${C_BOLD}VLESS + gRPC + TLS${C_RESET}: Multiplexed single-connection transport, great against aggressive SNI filters."
    echo -e "     • ${C_BOLD}VLESS + WebSocket + CDN (Cloudflare)${C_RESET}: Best for hiding origin server IP, slightly higher latency."
    echo -e "     • ${C_BOLD}Trojan + TCP + TLS${C_RESET}: Highly stable, standard HTTPS camouflage."

    echo -e "\n  ${C_CYAN}3. Recommended Client-Side Applications:${C_RESET}"
    echo -e "     • ${C_BOLD}Android:${C_RESET} v2rayNG, NekoBox, Sing-box"
    echo -e "     • ${C_BOLD}iOS / macOS:${C_RESET} Shadowrocket, Sing-box, V2Box, Streisand"
    echo -e "     • ${C_BOLD}Windows:${C_RESET} v2rayN, Nekoray, Clash Verge"

    echo -e "\n  ${C_CYAN}4. Network & Buffer Tweaks Applied by DAHOOM:${C_RESET}"
    echo -e "     • TCP Fast Open (TFO = 3)"
    echo -e "     • Enlarged socket read/write buffers (rmem_max/wmem_max = 67MB)"
    echo -e "     • TCP Keepalive intervals tuned for low power consumption & fast dead-link drop."
    echo -e "  ${C_PURPLE}────────────────────────────────────────────────────────────${C_RESET}\n"
}

# Remembers that an admin deliberately chose which domain the panel's
# certificate is for. Without it, the "Active Domain has changed" notice in
# xui_panel_management_menu has no way to tell a domain the admin meant to
# use apart from a stale one left behind by a deSEC re-provision — so it
# fires forever on a perfectly good custom domain and tells the admin to
# "fix" it by reverting to the deSEC one, undoing their own choice.
XUI_DOMAIN_PIN_FILE="$DB_DIR/.xui_domain_pin"

_fm_xui_pin_domain() {
    local d="$1"
    [[ -z "$d" ]] && return 0
    mkdir -p "$DB_DIR" 2>/dev/null
    printf '%s\n' "$d" > "$XUI_DOMAIN_PIN_FILE" 2>/dev/null || true
}

_fm_xui_unpin_domain() {
    rm -f "$XUI_DOMAIN_PIN_FILE" 2>/dev/null || true
}

_fm_xui_pinned_domain() {
    [[ -f "$XUI_DOMAIN_PIN_FILE" ]] || return 0
    head -n1 "$XUI_DOMAIN_PIN_FILE" 2>/dev/null | tr -d '[:space:]'
}

# Every domain this menu can act on lives under /root/cert/<domain>/ — the
# same convention both DAHOOM's own certbot-based issuing (sync_xui_domain_ssl)
# and the native x-ui CLI's acme.sh-based issuing already copy their final
# certs into, so a domain obtained through either path shows up here.
_fm_xui_cert_domains() {
    find /root/cert/ -mindepth 1 -maxdepth 1 -type d 2>/dev/null -exec basename {} \;
}

# Reads the domain the panel's currently-active certificate belongs to,
# straight from x-ui's own settings table — same lookup xui_panel_management_menu
# already uses to detect a stale/mismatched domain.
_fm_xui_active_cert_domain() {
    [[ -f /etc/x-ui/x-ui.db ]] && command -v python3 &>/dev/null || return 0
    python3 -c "
import sqlite3
try:
    conn = sqlite3.connect('/etc/x-ui/x-ui.db')
    c = conn.cursor()
    c.execute(\"SELECT value FROM settings WHERE key IN ('webCertFile', 'webCert') LIMIT 1\")
    row = c.fetchone()
    if row and row[0]:
        val = str(row[0])
        if '/live/' in val:
            print(val.split('/live/')[1].split('/')[0].strip())
        elif '/cert/' in val:
            print(val.split('/cert/')[1].split('/')[0].strip())
    conn.close()
except Exception:
    pass
" 2>/dev/null
}

xui_ssl_cert_management_menu() {
    while true; do
        clear; show_banner
        echo -e "${C_BOLD}${C_PURPLE}──────────────── 🔐 SSL CERTIFICATE MANAGEMENT ────────────────${C_RESET}\n"

        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Get SSL (issue a new certificate)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Revoke a certificate"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Force Renew a certificate"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Show existing domains & cert paths"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Set cert paths for the panel"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[6]" "Delete a certificate permanently (everywhere)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "Import an Existing Certificate (Paste)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[8]" "Import a Certificate by Path + Domain"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[9]" "Keep the current domain (stop the 'domain changed' notice)"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" ssl_act; then
            return
        fi
        case "$ssl_act" in
            1)
                read -r -p "$(echo -e "\n${C_CYAN}> Enter the domain to issue a certificate for: ${C_RESET}")" ssl_domain
                if [[ -z "$ssl_domain" ]]; then
                    echo -e "\n${C_RED}❌ No domain entered.${C_RESET}"
                else
                    echo -e "\n${C_BLUE}🌐 Requesting Let's Encrypt certificate for ${C_YELLOW}${ssl_domain}${C_BLUE}...${C_RESET}"
                    command -v certbot &>/dev/null || ff_pkg_install certbot >/dev/null 2>&1 || true
                    if command -v certbot &>/dev/null; then
                        systemctl stop nginx &>/dev/null || true
                        systemctl stop haproxy &>/dev/null || true
                        command -v fuser &>/dev/null && fuser -k 80/tcp &>/dev/null || true
                        certbot certonly --standalone -d "$ssl_domain" --agree-tos --register-unsafely-without-email --non-interactive >/dev/null 2>&1
                        local cb_rc=$?
                        systemctl start nginx &>/dev/null || true
                        systemctl start haproxy &>/dev/null || true
                        if [[ $cb_rc -eq 0 && -f "/etc/letsencrypt/live/$ssl_domain/fullchain.pem" ]]; then
                            mkdir -p "/root/cert/${ssl_domain}"
                            cp -f "/etc/letsencrypt/live/$ssl_domain/fullchain.pem" "/root/cert/${ssl_domain}/fullchain.pem"
                            cp -f "/etc/letsencrypt/live/$ssl_domain/privkey.pem" "/root/cert/${ssl_domain}/privkey.pem"
                            _log_action "XUI_SSL" "issue" "domain=$ssl_domain status=ok"
                            echo -e "${C_GREEN}✅ Certificate issued for ${ssl_domain}.${C_RESET}"
                            echo -e "${C_GRAY}ℹ️ Use [5] Set cert paths for the panel to make the panel use it.${C_RESET}"
                        else
                            echo -e "${C_RED}❌ Failed to obtain a certificate — ensure port 80 is reachable and DNS has propagated.${C_RESET}"
                        fi
                    else
                        echo -e "${C_RED}❌ certbot could not be installed on this system.${C_RESET}"
                    fi
                fi
                press_enter
                ;;
            2)
                local rv_domains; rv_domains=$(_fm_xui_cert_domains)
                if [[ -z "$rv_domains" ]]; then
                    echo -e "\n${C_YELLOW}No certificates found to revoke.${C_RESET}"
                else
                    echo -e "\n${C_CYAN}Existing domains:${C_RESET}"; echo "$rv_domains"
                    read -r -p "$(echo -e "\n${C_CYAN}> Enter a domain from the list to revoke: ${C_RESET}")" rv_domain
                    if echo "$rv_domains" | grep -qwF "$rv_domain"; then
                        if [[ -d "/etc/letsencrypt/live/$rv_domain" ]] && command -v certbot &>/dev/null; then
                            certbot revoke --cert-path "/etc/letsencrypt/live/$rv_domain/fullchain.pem" --no-delete-after-revoke --non-interactive >/dev/null 2>&1 \
                                && echo -e "${C_GREEN}✅ Certificate revoked for ${rv_domain}.${C_RESET}" \
                                || echo -e "${C_RED}❌ Revoke failed — check that the domain was issued via this menu's [1] Get SSL.${C_RESET}"
                        else
                            echo -e "${C_YELLOW}⚠️ No certbot-managed certificate found for ${rv_domain} — nothing to revoke (files in /root/cert/ are unaffected; use [6] to delete them).${C_RESET}"
                        fi
                        _log_action "XUI_SSL" "revoke" "domain=$rv_domain"
                    else
                        echo -e "${C_RED}❌ Invalid domain.${C_RESET}"
                    fi
                fi
                press_enter
                ;;
            3)
                local rn_domains; rn_domains=$(_fm_xui_cert_domains)
                if [[ -z "$rn_domains" ]]; then
                    echo -e "\n${C_YELLOW}No certificates found to renew.${C_RESET}"
                else
                    echo -e "\n${C_CYAN}Existing domains:${C_RESET}"; echo "$rn_domains"
                    read -r -p "$(echo -e "\n${C_CYAN}> Enter a domain from the list to force-renew: ${C_RESET}")" rn_domain
                    if echo "$rn_domains" | grep -qwF "$rn_domain"; then
                        if command -v certbot &>/dev/null && [[ -d "/etc/letsencrypt/live/$rn_domain" ]]; then
                            certbot renew --cert-name "$rn_domain" --force-renewal --non-interactive >/dev/null 2>&1
                            if [[ -f "/etc/letsencrypt/live/$rn_domain/fullchain.pem" ]]; then
                                cp -f "/etc/letsencrypt/live/$rn_domain/fullchain.pem" "/root/cert/${rn_domain}/fullchain.pem"
                                cp -f "/etc/letsencrypt/live/$rn_domain/privkey.pem" "/root/cert/${rn_domain}/privkey.pem"
                                echo -e "${C_GREEN}✅ Certificate renewed for ${rn_domain}.${C_RESET}"
                                _log_action "XUI_SSL" "force_renew" "domain=$rn_domain status=ok"
                            else
                                echo -e "${C_RED}❌ Renewal failed for ${rn_domain}.${C_RESET}"
                            fi
                        else
                            echo -e "${C_YELLOW}⚠️ No certbot-managed certificate found for ${rn_domain} — it wasn't issued via this menu's [1] Get SSL.${C_RESET}"
                        fi
                    else
                        echo -e "${C_RED}❌ Invalid domain.${C_RESET}"
                    fi
                fi
                press_enter
                ;;
            4)
                local sh_domains; sh_domains=$(_fm_xui_cert_domains)
                if [[ -z "$sh_domains" ]]; then
                    echo -e "\n${C_YELLOW}No certificates found.${C_RESET}"
                else
                    echo -e "\n${C_CYAN}Existing domains and their paths:${C_RESET}"
                    for d in $sh_domains; do
                        if [[ -f "/root/cert/${d}/fullchain.pem" && -f "/root/cert/${d}/privkey.pem" ]]; then
                            echo -e "  ${C_GREEN}${d}${C_RESET}"
                            echo -e "    Certificate: /root/cert/${d}/fullchain.pem"
                            echo -e "    Private Key: /root/cert/${d}/privkey.pem"
                        else
                            echo -e "  ${C_YELLOW}${d}${C_RESET} — certificate or key file missing"
                        fi
                    done
                fi
                press_enter
                ;;
            5)
                local sp_domains; sp_domains=$(_fm_xui_cert_domains)
                if [[ -z "$sp_domains" ]]; then
                    echo -e "\n${C_YELLOW}No certificates found.${C_RESET}"
                else
                    echo -e "\n${C_CYAN}Available domains:${C_RESET}"; echo "$sp_domains"
                    read -r -p "$(echo -e "\n${C_CYAN}> Choose a domain to set as the panel's certificate: ${C_RESET}")" sp_domain
                    if echo "$sp_domains" | grep -qwF "$sp_domain" && [[ -f "/root/cert/${sp_domain}/fullchain.pem" && -f "/root/cert/${sp_domain}/privkey.pem" ]]; then
                        if command -v python3 &>/dev/null; then
                            python3 -c "
import sqlite3
conn = sqlite3.connect('/etc/x-ui/x-ui.db')
c = conn.cursor()
c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile', 'webCert', 'webCertKey')\")
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', '/root/cert/${sp_domain}/fullchain.pem'))
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', '/root/cert/${sp_domain}/privkey.pem'))
conn.commit(); conn.close()
" 2>/dev/null
                            systemctl restart x-ui &>/dev/null
                            sleep 1
                            echo -e "${C_GREEN}✅ Panel certificate set to ${sp_domain} and the service restarted.${C_RESET}"
                            _fm_xui_pin_domain "$sp_domain"
                            _log_action "XUI_SSL" "set_panel_cert" "domain=$sp_domain"
                        else
                            echo -e "${C_RED}❌ python3 is required for this action.${C_RESET}"
                        fi
                    else
                        echo -e "${C_RED}❌ Invalid domain, or its certificate/key file is missing.${C_RESET}"
                    fi
                fi
                press_enter
                ;;
            6)
                local del_domains; del_domains=$(_fm_xui_cert_domains)
                if [[ -z "$del_domains" ]]; then
                    echo -e "\n${C_YELLOW}No certificates found.${C_RESET}"
                    press_enter
                else
                    echo -e "\n${C_CYAN}Existing domains:${C_RESET}"; echo "$del_domains"
                    read -r -p "$(echo -e "\n${C_CYAN}> Enter a domain to delete PERMANENTLY: ${C_RESET}")" del_domain
                    if ! echo "$del_domains" | grep -qwF "$del_domain"; then
                        echo -e "${C_RED}❌ Invalid domain.${C_RESET}"
                        press_enter
                    else
                        local active_dom; active_dom=$(_fm_xui_active_cert_domain)
                        local is_active=false
                        [[ -n "$active_dom" && "$active_dom" == "$del_domain" ]] && is_active=true

                        echo -e "\n${C_WARN}⚠️  This will PERMANENTLY delete every trace of '${del_domain}':${C_RESET}"
                        echo -e "  ${C_YELLOW}•${C_RESET} Revoke it and remove it from certbot's / acme.sh's auto-renewal"
                        echo -e "  ${C_YELLOW}•${C_RESET} Delete /root/cert/${del_domain}/ and its Let's Encrypt / acme.sh archives"
                        echo -e "  ${C_RED}•${C_RESET} This cannot be undone — a new certificate for this domain must be re-issued from scratch"

                        local del_conf=""
                        if $is_active; then
                            echo -e "\n${C_DANGER}🚨 '${del_domain}' is the PANEL'S CURRENTLY ACTIVE CERTIFICATE.${C_RESET}"
                            echo -e "${C_DANGER}   Deleting it will break HTTPS access to the panel immediately.${C_RESET}"
                            read -r -p "$(echo -e "\n${C_WARN}> Type the domain name exactly ('${del_domain}') to confirm you understand: ${C_RESET}")" del_conf1
                            if [[ "$del_conf1" != "$del_domain" ]]; then
                                echo -e "\n${C_YELLOW}❌ Cancelled — domain name did not match.${C_RESET}"
                                press_enter
                                continue
                            fi
                            read -r -p "$(echo -e "${C_WARN}> Type 'yes' to permanently delete it anyway: ${C_RESET}")" del_conf
                        else
                            read -r -p "$(echo -e "\n${C_WARN}> Type 'yes' to confirm permanent deletion: ${C_RESET}")" del_conf
                        fi

                        if [[ "$del_conf" != "yes" ]]; then
                            echo -e "\n${C_YELLOW}❌ Cancelled — nothing was deleted.${C_RESET}"
                            press_enter
                            continue
                        fi

                        if command -v certbot &>/dev/null && [[ -d "/etc/letsencrypt/live/$del_domain" ]]; then
                            certbot delete --cert-name "$del_domain" --non-interactive >/dev/null 2>&1
                        fi
                        if [[ -x ~/.acme.sh/acme.sh ]]; then
                            ~/.acme.sh/acme.sh --revoke -d "$del_domain" &>/dev/null
                            ~/.acme.sh/acme.sh --remove -d "$del_domain" &>/dev/null
                            rm -rf ~/.acme.sh/"${del_domain}" ~/.acme.sh/"${del_domain}_ecc" 2>/dev/null
                        fi
                        rm -rf "/root/cert/${del_domain}"

                        if $is_active && command -v python3 &>/dev/null; then
                            python3 -c "
import sqlite3
conn = sqlite3.connect('/etc/x-ui/x-ui.db')
c = conn.cursor()
c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile', 'webCert', 'webCertKey')\")
conn.commit(); conn.close()
" 2>/dev/null
                            systemctl restart x-ui &>/dev/null
                            echo -e "\n${C_YELLOW}ℹ️ The panel no longer has an active certificate — issue and set a new one to restore HTTPS.${C_RESET}"
                        fi

                        [[ "$(_fm_xui_pinned_domain)" == "$del_domain" ]] && _fm_xui_unpin_domain
                        _log_action "XUI_SSL" "delete_forever" "domain=$del_domain was_active=$is_active"
                        echo -e "\n${C_GREEN}✅ '${del_domain}' has been permanently deleted.${C_RESET}"
                        press_enter
                    fi
                fi
                ;;
            7)
                echo -e "\n${C_BOLD}${C_PURPLE}--- 📋 Import an Existing Certificate (Paste) ---${C_RESET}"
                read -r -p "$(echo -e "\n${C_CYAN}> Domain this certificate is for: ${C_RESET}")" imp_domain
                if [[ -z "$imp_domain" ]]; then
                    echo -e "\n${C_RED}❌ A domain is required.${C_RESET}"
                    press_enter; continue
                fi

                local tmp_chain tmp_key
                tmp_chain=$(mktemp) tmp_key=$(mktemp)
                echo -e "\n${C_CYAN}Paste the certificate (fullchain, PEM format). Press ${C_YELLOW}[Ctrl+D]${C_RESET}${C_CYAN} when done:${C_RESET}"
                echo -e "--------------------------------------------------"
                cat > "$tmp_chain"
                echo -e "--------------------------------------------------"
                echo -e "\n${C_CYAN}Now paste the matching private key (PEM format). Press ${C_YELLOW}[Ctrl+D]${C_RESET}${C_CYAN} when done:${C_RESET}"
                echo -e "--------------------------------------------------"
                cat > "$tmp_key"
                echo -e "--------------------------------------------------"

                if ! openssl x509 -in "$tmp_chain" -noout 2>/dev/null; then
                    echo -e "\n${C_RED}❌ That doesn't look like a valid certificate (PEM).${C_RESET}"
                    rm -f "$tmp_chain" "$tmp_key"; press_enter; continue
                fi
                if ! openssl pkey -in "$tmp_key" -noout 2>/dev/null; then
                    echo -e "\n${C_RED}❌ That doesn't look like a valid private key (PEM).${C_RESET}"
                    rm -f "$tmp_chain" "$tmp_key"; press_enter; continue
                fi
                if ! _fm_edge_cert_pair_matches "$tmp_chain" "$tmp_key"; then
                    echo -e "\n${C_RED}❌ The certificate and private key don't match each other.${C_RESET}"
                    rm -f "$tmp_chain" "$tmp_key"; press_enter; continue
                fi

                mkdir -p "/root/cert/${imp_domain}"
                mv "$tmp_chain" "/root/cert/${imp_domain}/fullchain.pem"
                mv "$tmp_key" "/root/cert/${imp_domain}/privkey.pem"
                if command -v python3 &>/dev/null; then
                    python3 -c "
import sqlite3
conn = sqlite3.connect('/etc/x-ui/x-ui.db')
c = conn.cursor()
c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile', 'webCert', 'webCertKey')\")
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', '/root/cert/${imp_domain}/fullchain.pem'))
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', '/root/cert/${imp_domain}/privkey.pem'))
conn.commit(); conn.close()
" 2>/dev/null
                    systemctl restart x-ui &>/dev/null
                    sleep 1
                    _fm_xui_pin_domain "$imp_domain"
                    _log_action "XUI_SSL" "import_paste" "domain=$imp_domain"
                    echo -e "\n${C_GREEN}✅ Imported and applied — the panel is now using the certificate for ${imp_domain}.${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ python3 is required for this action.${C_RESET}"
                fi
                press_enter
                ;;
            8)
                echo -e "\n${C_BOLD}${C_PURPLE}--- 📁 Import a Certificate by Path + Domain ---${C_RESET}"
                read -r -p "$(echo -e "\n${C_CYAN}> Domain this certificate is for: ${C_RESET}")" pth_domain
                read -r -p "$(echo -e "${C_CYAN}> Full path to the certificate/fullchain file: ${C_RESET}")" pth_chain
                read -r -p "$(echo -e "${C_CYAN}> Full path to the private key file: ${C_RESET}")" pth_key

                if [[ -z "$pth_domain" ]]; then
                    echo -e "\n${C_RED}❌ A domain is required.${C_RESET}"
                    press_enter; continue
                fi
                if [[ ! -s "$pth_chain" ]]; then
                    echo -e "\n${C_RED}❌ File not found or empty: $pth_chain${C_RESET}"
                    press_enter; continue
                fi
                if [[ ! -s "$pth_key" ]]; then
                    echo -e "\n${C_RED}❌ File not found or empty: $pth_key${C_RESET}"
                    press_enter; continue
                fi
                if ! openssl x509 -in "$pth_chain" -noout 2>/dev/null; then
                    echo -e "\n${C_RED}❌ That doesn't look like a valid certificate (PEM): $pth_chain${C_RESET}"
                    press_enter; continue
                fi
                if ! openssl pkey -in "$pth_key" -noout 2>/dev/null; then
                    echo -e "\n${C_RED}❌ That doesn't look like a valid private key (PEM): $pth_key${C_RESET}"
                    press_enter; continue
                fi
                if ! _fm_edge_cert_pair_matches "$pth_chain" "$pth_key"; then
                    echo -e "\n${C_RED}❌ The certificate and private key don't match each other.${C_RESET}"
                    press_enter; continue
                fi

                mkdir -p "/root/cert/${pth_domain}"
                cp -f "$pth_chain" "/root/cert/${pth_domain}/fullchain.pem"
                cp -f "$pth_key" "/root/cert/${pth_domain}/privkey.pem"
                if command -v python3 &>/dev/null; then
                    python3 -c "
import sqlite3
conn = sqlite3.connect('/etc/x-ui/x-ui.db')
c = conn.cursor()
c.execute(\"DELETE FROM settings WHERE key IN ('webCertFile', 'webKeyFile', 'webCert', 'webCertKey')\")
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webCertFile', '/root/cert/${pth_domain}/fullchain.pem'))
c.execute(\"INSERT INTO settings (key, value) VALUES (?, ?)\", ('webKeyFile', '/root/cert/${pth_domain}/privkey.pem'))
conn.commit(); conn.close()
" 2>/dev/null
                    systemctl restart x-ui &>/dev/null
                    sleep 1
                    _fm_xui_pin_domain "$pth_domain"
                    _log_action "XUI_SSL" "import_path" "domain=$pth_domain src=$pth_chain"
                    echo -e "\n${C_GREEN}✅ Imported and applied — the panel is now using the certificate for ${pth_domain}.${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ python3 is required for this action.${C_RESET}"
                fi
                press_enter
                ;;
            9)
                # For a domain that got set outside this menu (the x-ui CLI's
                # own acme.sh flow, a hand-edited database) and is therefore
                # unpinned: confirm it as deliberate so the panel screen stops
                # advising a rebuild onto the deSEC domain.
                local keep_dom; keep_dom=$(_fm_xui_active_cert_domain)
                if [[ -z "$keep_dom" ]]; then
                    echo -e "\n${C_YELLOW}ℹ️ The panel has no certificate domain configured — nothing to keep.${C_RESET}"
                else
                    _fm_xui_pin_domain "$keep_dom"
                    _log_action "XUI_SSL" "pin_domain" "domain=$keep_dom"
                    echo -e "\n${C_GREEN}✅ '${keep_dom}' is now kept as the panel's intended domain.${C_RESET}"
                    echo -e "${C_GRAY}   The 'Active Domain has changed' notice will no longer appear for it.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

xui_panel_management_menu() {
    local panel_name="${1:-X-UI Panel}"
    local install_fn="install_xui_panel"
    local xui_variant; xui_variant=$(get_xui_installed_variant)

    while true; do
        show_banner
        echo
        menu_section "$panel_name" "$C_TITLE"

        local is_installed=false
        local curr_status=""

        if [[ -f "/etc/systemd/system/x-ui.service" || -f "/lib/systemd/system/x-ui.service" || -f "/usr/local/x-ui/x-ui" || -d "/usr/local/x-ui" ]]; then
            is_installed=true
            if systemctl is-active --quiet x-ui 2>/dev/null || pgrep -x x-ui &>/dev/null; then
                curr_status="${C_GREEN}🟢 Active (Running)${C_RESET}"
            else
                curr_status="${C_YELLOW}🟡 Installed (Stopped)${C_RESET}"
            fi
        else
            curr_status="${C_GRAY}⚪ Not Installed${C_RESET}"
        fi

        echo -e "      ${C_GRAY}Status:${C_RESET} $curr_status"
        echo

        if $is_installed; then
            # Display Full Access Information Box
            show_xui_access_info "$panel_name"

            # Check if active system domain has changed from X-UI configured certificate domain
            local sys_domain=""
            if [[ -f "$DNS_INFO_FILE" ]]; then
                source "$DNS_INFO_FILE" 2>/dev/null
                sys_domain="$FULL_DOMAIN"
            fi
            local xui_cert_dom=""
            if [[ -f "/etc/x-ui/x-ui.db" ]] && command -v python3 &>/dev/null; then
                xui_cert_dom=$(python3 -c "
import sqlite3, os
try:
    conn = sqlite3.connect('/etc/x-ui/x-ui.db')
    c = conn.cursor()
    c.execute(\"SELECT value FROM settings WHERE key IN ('webCertFile', 'webCert') LIMIT 1\")
    row = c.fetchone()
    if row and row[0]:
        val = str(row[0])
        # Extract domain name if stored inside /etc/letsencrypt/live/<domain>/...
        if '/live/' in val:
            parts = val.split('/live/')[1].split('/')
            print(parts[0].strip())
        elif '/cert/' in val:
            parts = val.split('/cert/')[1].split('/')
            print(parts[0].strip())
    conn.close()
except:
    pass
" 2>/dev/null)
            fi

            # A domain different from the deSEC one is only a PROBLEM when it
            # wasn't chosen on purpose. An admin who installed a certificate
            # for their own domain through the SSL menu has it pinned, and
            # nagging them to "rebuild SSL with the new domain" would talk
            # them into reverting their own deliberate setup — so say nothing
            # in that case. The notice still fires for what it was written
            # for: a deSEC re-provision leaving the panel on a stale domain
            # nobody picked.
            local domain_mismatch=false
            local pinned_domain; pinned_domain=$(_fm_xui_pinned_domain)
            if [[ -n "$sys_domain" && -n "$xui_cert_dom" && "$sys_domain" != "$xui_cert_dom" \
                  && "$pinned_domain" != "$xui_cert_dom" ]]; then
                domain_mismatch=true
                echo -e "  ${C_ORANGE}⚠️  NOTICE: Active Domain has changed!${C_RESET}"
                echo -e "  ${C_GRAY}Current System Domain:${C_RESET} ${C_GREEN}${sys_domain}${C_RESET}"
                echo -e "  ${C_GRAY}X-UI Configured Domain:${C_RESET} ${C_RED}${xui_cert_dom}${C_RESET}"
                echo -e "  ${C_YELLOW}👉 Use option [8] below to rebuild SSL & apply the new domain,${C_RESET}"
                echo -e "  ${C_YELLOW}   or keep this domain deliberately via [7] SSL Certificate${C_RESET}"
                echo -e "  ${C_YELLOW}   Management → [9] Keep the current domain (stop this notice).${C_RESET}\n"
            fi

            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Restart Service"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Fix & Repair Access (Ports & Firewall)"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Reset Port & Credentials (Username/Password)"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Launch x-ui CLI Manager"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "View Client Inbound Configurations (Links & Keys)"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "Speed & Performance Tuning Wiki"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "SSL Certificate Management"
            if $domain_mismatch; then
                printf "      ${C_NEW}%-4s${C_RESET} %s\n" "[8]" "Sync & Rebuild SSL Certificate with New Domain (${sys_domain})"
            fi
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[9]" "Uninstall $panel_name"
            if [[ "$xui_variant" == "3xui" ]]; then
                printf "      ${C_NEW}%-4s${C_RESET} %s\n" "[10]" "Full 3X-UI Management Menu (28 tools, grouped)"
            fi
            echo
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an action: "${C_RESET})" choice; then
                echo; return
            fi
            case $choice in
                1)
                    echo -e "\n${C_BLUE}🔄 Restarting x-ui service...${C_RESET}"
                    systemctl daemon-reload 2>/dev/null || true
                    systemctl reset-failed x-ui 2>/dev/null || true
                    systemctl restart x-ui 2>/dev/null || true
                    sleep 1
                    if systemctl is-active --quiet x-ui 2>/dev/null; then
                        echo -e "${C_GREEN}✅ x-ui service restarted successfully.${C_RESET}"
                    else
                        echo -e "${C_RED}❌ Failed to start x-ui service. Checking logs:${C_RESET}"
                        journalctl -u x-ui -n 8 --no-pager 2>/dev/null || true
                    fi
                    press_enter
                    ;;
                2)
                    repair_xui_access "$panel_name"
                    press_enter
                    ;;
                3)
                    reset_xui_credentials "$panel_name"
                    press_enter
                    ;;
                4)
                    if command -v x-ui &>/dev/null; then
                        x-ui
                    else
                        echo -e "\n${C_RED}❌ x-ui binary not found in PATH.${C_RESET}"
                    fi
                    press_enter
                    ;;
                5)
                    show_xui_client_configs
                    press_enter
                    ;;
                6)
                    show_xui_speed_wiki
                    press_enter
                    ;;
                7)
                    xui_ssl_cert_management_menu
                    ;;
                8)
                    if $domain_mismatch; then
                        sync_xui_domain_ssl "$panel_name" "$sys_domain"
                        press_enter
                    else
                        invalid_option
                    fi
                    ;;
                9)
                    read -r -p "$(echo -e "${C_WARN}> Are you sure you want to uninstall ${panel_name}? (y/n) [n]: ${C_RESET}")" conf_un
                    if [[ "${conf_un,,}" == "y" ]]; then
                        uninstall_xui_panel
                    else
                        echo -e "\n${C_YELLOW}❌ Uninstall cancelled.${C_RESET}"
                    fi
                    press_enter
                    return
                    ;;
                10)
                    if [[ "$xui_variant" == "3xui" ]]; then
                        xui_3xui_full_menu
                    else
                        invalid_option
                    fi
                    ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install $panel_name"
            echo
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an action: "${C_RESET})" choice; then
                echo; return
            fi
            case $choice in
                1)
                    "$install_fn"
                    press_enter
                    ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# ====================================================================
# --- 3X-UI Full Native Management Menu ------------------------------
# ====================================================================
# Only reachable when get_xui_installed_variant says "3xui" (see the
# [10] option inside xui_panel_management_menu above). Wraps every
# tool MHSanaei/3x-ui's own x-ui.sh CLI offers (its "0-28" menu),
# grouped into the SAME 6 blocks that script's own show_menu() already
# separates them into with blank rules — just shown as 6 categories to
# pick from instead of one 28-line dump. Install(1) and Uninstall(6)
# are left out on purpose: this panel already has its own install/
# uninstall flow one level up ([1]/[9]), so offering a second path to
# the same action here would just be confusing, not "more complete".
#
# Two ways an item actually runs — neither reimplements 3x-ui's logic:
#   - Settings changes (Access & Settings box) call the x-ui BINARY's
#     own "setting" flags directly — the exact command x-ui.sh's own
#     reset_user()/set_port()/reset_webbasepath()/reset_config() run
#     internally (confirmed by reading x-ui.sh itself), just fronted
#     by this panel's own prompt instead of x-ui.sh's, and without a
#     restart afterward: x-ui.sh doesn't need one, and its Go binary
#     that these calls run just applies the same behavior directly.
#   - Anything with no direct CLI flag is reached by feeding its menu
#     number into the real interactive x-ui.sh and handing the
#     terminal straight to it: `{ echo N; cat; } | x-ui` sends "N" as
#     the first line x-ui.sh's `read` gets, then relays every further
#     keystroke from this same terminal — so whatever x-ui.sh asks
#     next (a domain, a y/n, ...) is answered by the admin exactly as
#     if they'd typed the number themselves at its own menu.
_xui3_bin="/usr/local/x-ui/x-ui"

# Runs one of 3x-ui's own menu actions BY NAME, with the terminal still
# attached.
#
# This used to pipe the menu number into `x-ui` instead
# ({ printf '%s\n' "$1"; cat; } | x-ui), which broke these entries in
# several ways at once: stdin was a pipe, so every one of these functions
# (they all prompt — certificates, firewall rules, IP limits, PostgreSQL,
# speedtest) read through `cat` instead of the terminal, anything testing
# for a TTY took its non-interactive path, and worst of all x-ui returned
# to its OWN main menu afterwards and read the customer's next keystroke
# as a main-menu number — so the admin silently ended up inside x-ui's
# menu rather than back here. It also hard-coded x-ui's numbering, which
# is not a stable interface between versions.
#
# Sourcing with an argument x-ui does not recognise makes it define every
# function and then fall through to show_usage instead of starting its
# menu, so the exact upstream function can be called directly. Done in a
# subshell so x-ui's own names (install, update, status, LOGE, colour
# vars...) never leak into this script's namespace, while stdin/stdout
# stay the real terminal — which is the whole point.
_xui3_call() {
    local fn="$1" bin
    bin=$(command -v x-ui 2>/dev/null)
    if [[ -z "$bin" ]]; then
        echo -e "${C_RED}❌ x-ui command not found on this server.${C_RESET}"
        return 1
    fi
    (
        # 3x-ui's script is written for a plain shell: it reads variables
        # that may be unset and lets commands fail on purpose. Sourcing it
        # under `set -u`/`set -e` aborts halfway through, silently, leaving
        # none of its functions defined — so the strict options are dropped
        # for this subshell only.
        set +u +e
        # shellcheck disable=SC1090
        source "$bin" __fm_load_only >/dev/null 2>&1
        if ! declare -F "$fn" >/dev/null; then
            echo -e "${C_RED}❌ This 3x-ui version has no \"${fn}\" action.${C_RESET}"
            echo -e "${C_YELLOW}   Run ${C_RESET}x-ui${C_YELLOW} directly and pick it from its own menu.${C_RESET}"
            exit 1
        fi
        "$fn"
    )
}

xui_3xui_full_menu() {
    while true; do
        show_banner
        echo
        menu_section "3X-UI FULL MANAGEMENT MENU" "$C_TITLE"
        echo -e "  ${C_GRAY}Every tool 3x-ui's own CLI offers, grouped for easier browsing.${C_RESET}\n"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "🚀 Updates & Version"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "🔐 Access & Settings"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "⚙️  Service Control"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "🔄 Autostart"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "🛡️  Security & Network"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "⚡ Performance & Tools"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select a category: "${C_RESET})" cat_choice; then
            echo; return
        fi
        case "$cat_choice" in
            1) _xui3_cat_updates ;;
            2) _xui3_cat_access ;;
            3) _xui3_cat_service ;;
            4) _xui3_cat_autostart ;;
            5) _xui3_cat_security ;;
            6) _xui3_cat_performance ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

_xui3_cat_updates() {
    while true; do
        clear; show_banner
        menu_section "🚀 Updates & Version" "$C_TITLE"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Update"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Update to Dev Channel (latest commit)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Update Menu"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Legacy Version"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Back"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select: "${C_RESET})" c; then echo; return; fi
        case "$c" in
            1) x-ui update; press_enter ;;
            2) x-ui update-dev; press_enter ;;
            3) _xui3_call update_menu; press_enter ;;
            4) x-ui legacy; press_enter ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

_xui3_cat_access() {
    while true; do
        clear; show_banner
        menu_section "🔐 Access & Settings" "$C_TITLE"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Reset Username & Password"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Reset Web Base Path"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Reset Settings"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Change Port"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "View Current Settings"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Back"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select: "${C_RESET})" c; then echo; return; fi
        # Each of these is 3x-ui's OWN function, not a re-implementation of
        # it. Reproducing them here meant quietly drifting from upstream on
        # every 3x-ui release — and losing the extras their versions do
        # (validating the port is free, warning about an in-use base path,
        # printing the full new access URL afterwards). Calling them keeps
        # this menu a different arrangement of 3x-ui's tools, never a
        # different implementation of them.
        case "$c" in
            1) _xui3_call reset_user; press_enter ;;
            2) _xui3_call reset_webbasepath; press_enter ;;
            3) _xui3_call reset_config; press_enter ;;
            4)
                _xui3_call set_port
                # 3x-ui changes the port but never touches the firewall, so
                # a new port would be set and then unreachable. Read back
                # what it actually stored rather than trusting anything
                # typed here.
                local nowport
                nowport=$("$_xui3_bin" setting -show 2>/dev/null | grep -iE '^port:' | grep -oE '[0-9]+' | head -1)
                if [[ "$nowport" =~ ^[0-9]+$ ]]; then
                    check_and_open_firewall_port "$nowport" tcp 2>/dev/null || true
                    echo -e "${C_GREEN}✅ Firewall opened for port ${nowport}.${C_RESET}"
                fi
                press_enter
                ;;
            5) _xui3_call check_config; press_enter ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

