_xui3_cat_security() {
    while true; do
        clear; show_banner
        menu_section "🛡️  Security & Network" "$C_TITLE"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "SSL Certificate Management"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Cloudflare SSL Certificate"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "IP Limit Management"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Firewall Management"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "SSH Port Forwarding Management"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "PostgreSQL Management"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Back"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select: "${C_RESET})" c; then echo; return; fi
        case "$c" in
            1) _xui3_call ssl_cert_issue_main; press_enter ;;
            2) _xui3_call ssl_cert_issue_CF; press_enter ;;
            3) _xui3_call iplimit_main; press_enter ;;
            4) _xui3_call firewall_menu; press_enter ;;
            5) _xui3_call SSH_port_forwarding; press_enter ;;
