refresh_ssh_session_cache() {
    local now db_mtime
    printf -v now '%(%s)T' -1
    db_mtime=$(stat -c %Y "$DB_FILE" 2>/dev/null || echo 0)

    if (( SSH_SESSION_CACHE_TS > 0 && now - SSH_SESSION_CACHE_TS < SSH_SESSION_CACHE_TTL && db_mtime == SSH_SESSION_CACHE_DB_MTIME )); then
        return
    fi

    SSH_SESSION_COUNTS=()
    SSH_SESSION_PIDS=()
    SSH_SESSION_TOTAL=0
    SSH_SESSION_CACHE_DB_MTIME=$db_mtime

    if [[ ! -s "$DB_FILE" ]]; then
        SSH_SESSION_CACHE_TS=$now
        return
    fi

    local -A managed_user_lookup=()
    local -A uid_user_lookup=()
    local -A session_pids=()
    local -A loginuid_pids=()
    local managed_user system_user system_uid ssh_pid ssh_owner candidate_user login_uid

    while IFS=: read -r managed_user _rest; do
        [[ -n "$managed_user" && "$managed_user" != \#* ]] && managed_user_lookup["$managed_user"]=1
    done < "$DB_FILE"

    while IFS=: read -r system_user _ system_uid _rest; do
        [[ -n "$system_user" && "$system_uid" =~ ^[0-9]+$ ]] && uid_user_lookup["$system_uid"]="$system_user"
    done < /etc/passwd

    while read -r ssh_pid ssh_owner; do
        [[ "$ssh_pid" =~ ^[0-9]+$ ]] || continue
        if [[ -n "$ssh_owner" && "$ssh_owner" != "root" && "$ssh_owner" != "sshd" && -n "${managed_user_lookup[$ssh_owner]+x}" ]]; then
            session_pids["$ssh_owner"]+="$ssh_pid "
        fi
    done < <(ps -C sshd,sshd-session -o pid=,user= 2>/dev/null)

    local user pid
    for user in "${!managed_user_lookup[@]}"; do
        unset unique_pids
        local -A unique_pids=()

        for pid in ${session_pids[$user]}; do
            [[ "$pid" =~ ^[0-9]+$ ]] && unique_pids["$pid"]=1
        done

        SSH_SESSION_COUNTS["$user"]=${#unique_pids[@]}
        if (( ${#unique_pids[@]} > 0 )); then
            for pid in "${!unique_pids[@]}"; do
                SSH_SESSION_PIDS["$user"]+="$pid "
            done
            SSH_SESSION_TOTAL=$((SSH_SESSION_TOTAL + ${#unique_pids[@]}))
        fi
    done

    SSH_SESSION_CACHE_TS=$now
}

count_managed_online_sessions() {
    refresh_ssh_session_cache
    echo "$SSH_SESSION_TOTAL"
}

invalidate_banner_cache() {
    BANNER_CACHE_TS=0
    SSH_SESSION_CACHE_TS=0
}

# Build the pre-rendered, colored content lines for the "ACTIVE PORTS" box:
# scans real listening sockets (ss) and groups them by owning process, so the
# box only ever shows services that are genuinely up right now. Returns an
# empty string (no box) if `ss` is unavailable or nothing is listening.
_fm_build_active_ports_lines() {
    command -v ss &>/dev/null || { printf ''; return; }

    local ss_out
    ss_out=$(ss -H -tulnp 2>/dev/null)
    [[ -z "$ss_out" ]] && { printf ''; return; }

    local -A svc_ports=()
    local line port proc label
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        port=$(awk '{print $5}' <<< "$line")
        port="${port##*:}"
        [[ "$port" =~ ^[0-9]+$ ]] || continue

        proc=$(grep -oP 'users:\(\("\K[^"]+' <<< "$line" | head -n1)
        [[ -z "$proc" ]] && continue

        if [[ -n "${PANEL_PORT:-}" && "$port" == "$PANEL_PORT" ]]; then
            label="WEB PANEL"
        elif [[ -n "${BW_LINK_PORT:-}" && "$port" == "$BW_LINK_PORT" ]]; then
            label="BANDWIDTH LINK"
        else
            case "$proc" in
                sshd)                       label="OPENSSH" ;;
                dropbear)                   label="DROPBEAR" ;;
                haproxy)                    label="SSL TUNNEL" ;;
                nginx)                      label="NGINX PROXY" ;;
                netrelay)                   label="NET RELAY" ;;
                xray|v2ray)                 label="XRAY / V2RAY" ;;
                badvpn-udpgw|udpgw|badvpn)  label="BADVPN UDP" ;;
                udp-custom)                 label="UDP CUSTOM" ;;
                dns-server)                 label="DNSTT SLOWDNS" ;;
                zivpn|udp-zivpn*)           label="ZIVPN UDP" ;;
                x-ui)                       label="X-UI PANEL" ;;
                stunnel4|stunnel)           label="STUNNEL" ;;
                danted|ss-server|ssserver)  label="SOCKS PROXY" ;;
                openvpn)                    label="OPENVPN" ;;
                *)                          label="${proc^^}" ;;
            esac
        fi
        svc_ports["$label"]+=" $port"
    done <<< "$ss_out"

    (( ${#svc_ports[@]} == 0 )) && { printf ''; return; }

    local out="" l content ports_str pad
    local -a sorted_labels=()
    mapfile -t sorted_labels < <(printf '%s\n' "${!svc_ports[@]}" | sort)
    for l in "${sorted_labels[@]}"; do
        ports_str=$(tr ' ' '\n' <<< "${svc_ports[$l]}" | grep -E '^[0-9]+$' | sort -n -u | paste -sd',' - | sed 's/,/, /g')
        content="${l} PORT: ${ports_str}"
        if (( ${#content} > 54 )); then
            content="${content:0:51}..."
        fi
        pad=$(( 56 - ${#content} ))
        (( pad < 1 )) && pad=1
        out+="  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_WHITE}${content}${C_RESET}$(printf '%*s' "$pad" '')${C_BOLD}${C_BLUE}│${C_RESET}"$'\n'
    done
    printf '%s' "$out"
}

refresh_banner_cache() {
    local now
    printf -v now '%(%s)T' -1
    if (( BANNER_CACHE_TS > 0 && now - BANNER_CACHE_TS < BANNER_CACHE_TTL )); then
        return
    fi

    if [[ -z "$BANNER_CACHE_OS_NAME" ]]; then
        BANNER_CACHE_OS_NAME=$(grep -oP 'PRETTY_NAME="\K[^"]+' /etc/os-release 2>/dev/null || echo "Linux")
    fi
    BANNER_CACHE_UP_TIME=$(uptime -p 2>/dev/null | sed 's/up //' || echo "unknown")
    BANNER_CACHE_RAM_USAGE=$(free -m | awk '/^Mem:/{if($2>0){printf "%.2f", $3*100/$2}else{print "0.00"}}')
    BANNER_CACHE_CPU_LOAD=$(awk '{print $1}' /proc/loadavg 2>/dev/null)
    BANNER_CACHE_ACTIVE_USERS=0
    BANNER_CACHE_LOCKED_USERS=0
    BANNER_CACHE_EXPIRED_USERS=0
    BANNER_CACHE_TOTAL_USERS=0

    if [[ -s "$DB_FILE" ]]; then
        local now_ts; now_ts=$(date +%s)
        local -A shadow_locked=()
        if [[ -r /etc/shadow ]]; then
            while IFS=: read -r _su _sh_h _r; do
                [[ -n "$_su" && "${_sh_h:0:1}" == "!" ]] && shadow_locked["$_su"]=1
            done < /etc/shadow
        fi

        while IFS=: read -r _u _p exp _r; do
            [[ -z "$_u" || "$_u" == \#* ]] && continue
            (( BANNER_CACHE_TOTAL_USERS++ ))
            local e_ts=0
            [[ -n "$exp" && "$exp" != "Never" ]] && e_ts=$(date -d "$exp" +%s 2>/dev/null || echo 0)

            if [[ -n "${shadow_locked[$_u]+x}" ]]; then
                (( BANNER_CACHE_LOCKED_USERS++ ))
            elif (( e_ts > 0 && e_ts < now_ts )); then
                (( BANNER_CACHE_EXPIRED_USERS++ ))
            else
                (( BANNER_CACHE_ACTIVE_USERS++ ))
            fi
        done < "$DB_FILE"
    fi
    BANNER_CACHE_ONLINE_USERS=$(count_managed_online_sessions)
    BANNER_CACHE_PORTS_LINES=$(_fm_build_active_ports_lines)

    BANNER_CACHE_REMOTE_VER=""
    BANNER_CACHE_HAS_UPDATE=false
    # cur_sha is now guaranteed to be a clean 7-char SHA by get_installed_sha()
    local cur_sha; cur_sha=$(get_installed_sha 2>/dev/null || echo "")

    _check_remote_ver_bg

    if [[ -f "$UPDATE_CACHE_FILE" ]]; then
        local _t_ts raw_sha rem_sha
        read -r _t_ts raw_sha < "$UPDATE_CACHE_FILE" 2>/dev/null
        # cache file stores raw API SHA (7 chars) — strip any accidental prefix just in case
        rem_sha="${raw_sha##*beta_}"
        rem_sha="${rem_sha##*4.6.0_}"
        rem_sha="${rem_sha##*4.5.0_}"
        rem_sha="${rem_sha##*beta-}"
        rem_sha="${rem_sha:0:7}"

        if [[ -z "$raw_sha" || "$raw_sha" == *"2026"* || ${#rem_sha} -ne 7 ]]; then
            # invalid / stale cache — purge and re-trigger background fetch
            rm -f "$UPDATE_CACHE_FILE" 2>/dev/null
            _check_remote_ver_bg
        else
            BANNER_CACHE_REMOTE_VER="4.6.0_${rem_sha}"
            # Both cur_sha and rem_sha are clean 7-char SHAs — reliable comparison
            if [[ -n "$cur_sha" && ${#cur_sha} -eq 7 && "$cur_sha" != "$rem_sha" ]]; then
                BANNER_CACHE_HAS_UPDATE=true
            fi
        fi
    fi

    BANNER_CACHE_TS=$now
}

show_banner() {
    if [[ -t 1 ]]; then
        printf '\033[H\033[2J\033[3J'
        clear 2>/dev/null || true
    fi
    refresh_banner_cache

    local _VER _pad_title _pad_badge _len_title _len_badge
    _VER=$(get_current_version_tag 2>/dev/null || echo "dev")
    _len_title=$(( 12 + ${#_VER} ))
    _pad_title=$(( 58 - _len_title ))
    [[ $_pad_title -lt 1 ]] && _pad_title=1

    # ── Elegant Unified Frame ─────────────────────────────────────────────
    echo
    echo -e "  ${C_BOLD}${C_BLUE}╭──────────────────────────────────────────────────────────╮${C_RESET}"
    echo -e "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_BOLD}${C_ORANGE}Ⓓ DAHOOM${C_RESET}  ${C_DIM}${C_GRAY}${_VER}${C_RESET}$(printf '%*s' "$_pad_title" '')${C_BOLD}${C_BLUE}│${C_RESET}"
    echo -e "  ${C_BOLD}${C_BLUE}├──────────────────────────────────────────────────────────┤${C_RESET}"
    printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_WHITE}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
        "OS" "${BANNER_CACHE_OS_NAME:0:17}" "Uptime" "${BANNER_CACHE_UP_TIME:0:18}"
    printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_GREEN}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
        "Memory" "${BANNER_CACHE_RAM_USAGE}% Used" "Load" "$BANNER_CACHE_CPU_LOAD"
    printf "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GRAY}%-8s${C_RESET} ${C_WHITE}%-17s${C_RESET} ${C_GRAY}│${C_RESET}  ${C_GRAY}%-6s${C_RESET} ${C_CYAN}%-18s${C_RESET} ${C_BOLD}${C_BLUE}│${C_RESET}\n" \
        "Sessions" "${BANNER_CACHE_ONLINE_USERS} Online" "Mode" "Multi-Protocol"
    echo -e "  ${C_BOLD}${C_BLUE}├──────────────────────────────────────────────────────────┤${C_RESET}"

    # ── User Status Cards (Compact & Perfectly Framed) ────────────────────
    _len_badge=$(( 51 + ${#BANNER_CACHE_ACTIVE_USERS} + ${#BANNER_CACHE_LOCKED_USERS} + ${#BANNER_CACHE_EXPIRED_USERS} + ${#BANNER_CACHE_TOTAL_USERS} ))
    _pad_badge=$(( 58 - _len_badge ))
    [[ $_pad_badge -lt 1 ]] && _pad_badge=1

    echo -e "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_GREEN}🟢 ${BANNER_CACHE_ACTIVE_USERS} Active${C_RESET} ${C_GRAY}│${C_RESET} ${C_YELLOW}🟡 ${BANNER_CACHE_LOCKED_USERS} Locked${C_RESET} ${C_GRAY}│${C_RESET} ${C_RED}🔴 ${BANNER_CACHE_EXPIRED_USERS} Expired${C_RESET} ${C_GRAY}│${C_RESET} ${C_WHITE}👥 ${BANNER_CACHE_TOTAL_USERS} Total${C_RESET}$(printf '%*s' "$_pad_badge" '')${C_BOLD}${C_BLUE}│${C_RESET}"
    echo -e "  ${C_BOLD}${C_BLUE}╰──────────────────────────────────────────────────────────╯${C_RESET}"

    # ── Active Ports Box (only real, currently-listening services) ────────
    if [[ -n "$BANNER_CACHE_PORTS_LINES" ]]; then
        local _pt_content="ACTIVE PORTS" _pt_pad
        _pt_pad=$(( 56 - ${#_pt_content} ))
        echo
        echo -e "  ${C_BOLD}${C_BLUE}╭──────────────────────────────────────────────────────────╮${C_RESET}"
        echo -e "  ${C_BOLD}${C_BLUE}│${C_RESET}  ${C_BOLD}${C_CYAN}${_pt_content}${C_RESET}$(printf '%*s' "$_pt_pad" '')${C_BOLD}${C_BLUE}│${C_RESET}"
        echo -e "  ${C_BOLD}${C_BLUE}├──────────────────────────────────────────────────────────┤${C_RESET}"
        printf '%s\n' "$BANNER_CACHE_PORTS_LINES"
        echo -e "  ${C_BOLD}${C_BLUE}╰──────────────────────────────────────────────────────────╯${C_RESET}"
    fi
}

# --- Per-service Dynamic Action Menu (Install if not installed, Restart & Uninstall if installed) ---
service_action_menu() {
    local title="$1" status="$2" install_fn="$3" uninstall_fn="$4" svc_unit="${5:-}"
    local install_label="${6:-Install $title}" uninstall_label="${7:-Uninstall $title}"

    while true; do
        show_banner
        echo
        menu_section "$title" "$C_TITLE"

        local is_inst=false
        local is_act=false
        local curr_status=""

        # Check status dynamically (0ms)
        if [[ -n "$svc_unit" ]]; then
            if pgrep -x "$svc_unit" &>/dev/null || pgrep -f "$svc_unit" &>/dev/null; then
                is_inst=true
                is_act=true
                # HAProxy Edge's actual web/SSH decrypt-and-serve path runs
                # through the shared internal Nginx behind it — haproxy
                # alone being up doesn't mean the stack actually works.
                if [[ "$svc_unit" == "haproxy" ]] && ! systemctl is-active --quiet nginx; then
                    curr_status="${C_YELLOW}🟡 Partial (HAProxy up, internal Nginx down — traffic won't work)${C_RESET}"
                else
                    curr_status="${C_GREEN}🟢 Active (Running)${C_RESET}"
                fi
            elif [[ -f "/etc/systemd/system/${svc_unit}.service" || -f "/lib/systemd/system/${svc_unit}.service" ]] || command -v "$svc_unit" &>/dev/null || [[ "$svc_unit" == "x-ui" && -d "/usr/local/x-ui" ]]; then
                is_inst=true
                is_act=false
                curr_status="${C_YELLOW}🟡 Installed (Stopped)${C_RESET}"
            else
                is_inst=false
                is_act=false
                curr_status="${C_GRAY}⚪ Not Installed${C_RESET}"
            fi
        else
            if [[ "$status" =~ [Aa]ctive|[Ii]nstalled ]]; then
                is_inst=true
                curr_status="$status"
            else
                is_inst=false
                curr_status="${C_GRAY}⚪ Not Installed${C_RESET}"
            fi
        fi

        echo -e "      ${C_GRAY}Status:${C_RESET} $curr_status"
        echo

        if $is_inst; then
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Restart Service"
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Reinstall / Reconfigure"
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[3]" "$uninstall_label"
            echo
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an action: "${C_RESET})" choice; then
                echo; return
            fi
            case $choice in
                1)
                    if [[ "$svc_unit" == "haproxy" ]]; then
                        echo -e "\n${C_BLUE}🔄 Restarting internal Nginx + HAProxy...${C_RESET}"
                        _fm_safe_restart_nginx 2>/dev/null || true
                        systemctl restart haproxy 2>/dev/null || true
                        sleep 1
                        if systemctl is-active --quiet nginx 2>/dev/null && systemctl is-active --quiet haproxy 2>/dev/null; then
                            echo -e "${C_GREEN}✅ ${title} restarted successfully.${C_RESET}"
                        else
                            echo -e "${C_RED}❌ Failed to fully restart ${title}. Check logs: journalctl -u nginx -n 10 && journalctl -u haproxy -n 10${C_RESET}"
                        fi
                    elif [[ "$svc_unit" == "netrelay" ]]; then
                        echo -e "\n${C_BLUE}🔄 Restarting Net Relay...${C_RESET}"
                        systemctl restart netrelay 2>/dev/null || true
                        # The OpenVPN-sharing sniffer, when configured, only
                        # ever exists alongside Net Relay itself — restart
                        # it too so a stale sniffer isn't left pointed at a
                        # freshly-restarted Net Relay it never reconnects to.
                        if [ -f "$NETRELAY_OVPN_SNIFFER_SERVICE_FILE" ]; then
                            systemctl restart dahoom-netrelay-ovpn-sniffer 2>/dev/null || true
                        fi
                        sleep 1
                        if systemctl is-active --quiet netrelay 2>/dev/null; then
                            echo -e "${C_GREEN}✅ ${title} restarted successfully.${C_RESET}"
                        else
                            echo -e "${C_RED}❌ Failed to start ${title}. Check logs: journalctl -u netrelay -n 10${C_RESET}"
                        fi
                    elif [[ -n "$svc_unit" ]]; then
                        echo -e "\n${C_BLUE}🔄 Restarting ${title} (${svc_unit})...${C_RESET}"
                        systemctl restart "$svc_unit" 2>/dev/null || true
                        sleep 1
                        if systemctl is-active --quiet "$svc_unit" 2>/dev/null; then
                            echo -e "${C_GREEN}✅ ${title} restarted successfully.${C_RESET}"
                        else
                            echo -e "${C_RED}❌ Failed to start ${title}. Check logs: journalctl -u ${svc_unit} -n 10${C_RESET}"
                        fi
                    else
                        echo -e "\n${C_BLUE}🔄 Restarting ${title}...${C_RESET}"
                        "$install_fn"
                    fi
                    press_enter
                    ;;
                2)
                    # Just re-runs the same install function used for a
                    # fresh install. Several of these already know how to
                    # handle "already installed" on their own (HAProxy Edge
                    # asks to replace its configs and repairs missing
                    # packages along the way; Net Relay asks to
                    # reinstall/switch version) — this is the only way to
                    # reach that path once a service is no longer "Not
                    # Installed" in this menu. For installers that don't
                    # have that handling, it's a harmless no-op identical
                    # to pressing Install while already installed today.
                    "$install_fn"
                    press_enter
                    ;;
                3)
                    read -r -p "$(echo -e "${C_WARN}> Are you sure you want to uninstall ${title}? (y/n) [n]: ${C_RESET}")" conf_un
                    if [[ "${conf_un,,}" == "y" ]]; then
                        "$uninstall_fn"
                        echo -e "\n${C_GREEN}✅ ${title} uninstalled successfully.${C_RESET}"
                    else
                        echo -e "\n${C_YELLOW}❌ Uninstall cancelled.${C_RESET}"
                    fi
                    press_enter
                    return
                    ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            printf "      ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "$install_label"
            echo
            printf "      ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an action: "${C_RESET})" choice; then
                echo; return
            fi
            case $choice in
                1)
                    "$install_fn"
                    press_enter
                    ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# ── AUTO-HEALING SERVICE GUARD ─────────────────────────────────────────
AUTO_HEALING_CONF="/etc/firewallfalcon/auto_healing.conf"

run_auto_healing_check() {
    local services=("badvpn" "udp-custom" "haproxy" "nginx" "netrelay" "zivpn" "x-ui" "xray")
    local lock_file="/tmp/.ff_auto_healing.lock"
    [[ -f "$lock_file" ]] && return
    touch "$lock_file" 2>/dev/null

    for svc in "${services[@]}"; do
        if systemctl is-enabled "$svc" &>/dev/null; then
            if ! systemctl is-active --quiet "$svc" 2>/dev/null; then
                # nginx (shared by HAProxy Edge) is prone to the restart-race
                # EADDRINUSE covered by
                # _fm_safe_restart_nginx — use it here too instead of a plain
                # restart that can lose that race silently.
                if [[ "$svc" == "nginx" ]]; then
                    _fm_safe_restart_nginx &>/dev/null
                else
                    systemctl restart "$svc" &>/dev/null
                fi
                # Verify before claiming success — a restart that silently
                # failed (e.g. lost the port race) must not be reported as
                # "restarted successfully"; that just hides a real outage.
                if systemctl is-active --quiet "$svc" 2>/dev/null; then
                    _log_action "AUTO_HEAL_RESTART" "$svc" "status=restarted"
                    send_telegram_msg "⚡ <b>Auto-Healing Guard Alert</b>%0AService <b>$svc</b> was down and auto-restarted successfully!"
                else
                    _log_action "AUTO_HEAL_RESTART_FAILED" "$svc" "status=failed"
                    send_telegram_msg "🚨 <b>Auto-Healing Guard Alert</b>%0AService <b>$svc</b> was down and the automatic restart FAILED — needs manual attention."
                fi
            fi
        fi
    done

    # badvpn-udpgw (the UDP gateway games like PUBG rely on) is a known-flaky
    # upstream daemon: under bursty UDP load it can silently stop forwarding
    # traffic WITHOUT the process actually exiting. The is-active check above
    # can never catch that — systemd still sees it as "running" — so a hang
    # would otherwise sit there until someone notices and restarts it by
    # hand. Work around it with a periodic preventive restart instead.
    _fm_badvpn_periodic_restart

    # V2Ray/VLESS clients keep working past lock/expiry with no automatic
    # enforcement at all (unlike plain SSH users, who the limiter service
    # locks & kills within ~10s). See _fm_v2ray_enforce_expiry for why.
    _fm_v2ray_enforce_expiry

    # Proactive alerts — catch trouble before it becomes an outage.
    _fm_alert_disk_usage
    _fm_alert_cert_expiry
    _fm_alert_expiring_users

    rm -f "$lock_file" 2>/dev/null
}

# ── Proactive Telegram alerts: disk usage, SSL cert expiry, subscriptions
# expiring soon. Auto-Healing already restarts a downed service and alerts
# on that (below); these three catch trouble *before* something actually
# breaks. Each has its own cooldown stamp so a persisting condition doesn't
# re-alert every 2 minutes for as long as it lasts.
_fm_alert_disk_usage() {
    local stamp="/etc/firewallfalcon/.alert_disk_last"
    local cooldown=$((12 * 3600))
    local pct; pct=$(df -P / 2>/dev/null | awk 'NR==2{gsub("%","",$5); print $5}')
    [[ "$pct" =~ ^[0-9]+$ ]] || return 0
    (( pct < 90 )) && return 0

    local now last=0; now=$(date +%s)
    [[ -f "$stamp" ]] && last=$(cat "$stamp" 2>/dev/null)
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    (( now - last < cooldown )) && return 0

    send_telegram_msg "🛑 <b>Low Disk Space</b>%0ARoot partition is <b>${pct}%</b> full — free up space soon to avoid service failures."
    echo "$now" > "$stamp" 2>/dev/null
}

_fm_alert_cert_expiry() {
    [[ -f "$SSL_CERT_CHAIN_FILE" ]] || return 0
    local stamp="/etc/firewallfalcon/.alert_cert_last"
    local cooldown=$((24 * 3600))
    local end_date end_ts now_ts days_left
    end_date=$(openssl x509 -in "$SSL_CERT_CHAIN_FILE" -noout -enddate 2>/dev/null | cut -d= -f2)
    [[ -n "$end_date" ]] || return 0
    end_ts=$(date -d "$end_date" +%s 2>/dev/null) || return 0
    now_ts=$(date +%s)
    days_left=$(( (end_ts - now_ts) / 86400 ))
    (( days_left > 7 )) && return 0

    local last=0
    [[ -f "$stamp" ]] && last=$(cat "$stamp" 2>/dev/null)
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    (( now_ts - last < cooldown )) && return 0

    send_telegram_msg "🔒 <b>SSL Certificate Expiring Soon</b>%0A${days_left} day(s) left — renew it from the Domain and DNS menu."
    echo "$now_ts" > "$stamp" 2>/dev/null
}

_fm_alert_expiring_users() {
    [[ -s "$DB_FILE" ]] || return 0
    local stamp="/etc/firewallfalcon/.alert_expiry_last"
    local cooldown=$((24 * 3600))
    local now_ts last=0; now_ts=$(date +%s)
    [[ -f "$stamp" ]] && last=$(cat "$stamp" 2>/dev/null)
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    (( now_ts - last < cooldown )) && return 0

    local soon=() user pass expiry limit bandwidth_gb _extra expiry_ts days_left
    while IFS=: read -r user pass expiry limit bandwidth_gb _extra; do
        [[ -z "$user" ]] && continue
        expiry_ts=$(date -d "$expiry" +%s 2>/dev/null) || continue
        days_left=$(( (expiry_ts - now_ts) / 86400 ))
        (( days_left >= 0 && days_left <= 3 )) && soon+=("${user} (${days_left}d)")
    done < "$DB_FILE"
    (( ${#soon[@]} == 0 )) && return 0

    local list; list=$(printf '%s%%0A' "${soon[@]}")
    send_telegram_msg "⏳ <b>Subscriptions Expiring Soon</b>%0A${list}"
    echo "$now_ts" > "$stamp" 2>/dev/null
}

_fm_badvpn_periodic_restart() {
    [[ -f "$BADVPN_SERVICE_FILE" ]] || return 0
    systemctl is-enabled badvpn &>/dev/null || return 0

    local stamp_file="/etc/firewallfalcon/.badvpn_last_restart"
    local interval_sec=$((6 * 3600))   # every 6 hours
    local last=0 now
    [[ -f "$stamp_file" ]] && last=$(cat "$stamp_file" 2>/dev/null)
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    now=$(date +%s)
    (( now - last < interval_sec )) && return 0

    systemctl restart badvpn &>/dev/null
    echo "$now" > "$stamp_file" 2>/dev/null
    _log_action "AUTO_HEAL_RESTART" "badvpn" "status=periodic_preventive_restart"
}

# V2Ray/VLESS clients are UUIDs baked into Xray's own config.json — Xray
# doesn't know or care about /etc/shadow, so locking or expiring a user's
# SSH account (which the limiter service already handles within ~10s) has
# ZERO effect on a V2Ray client with the same username. build_xray_config()
# in v2ray_manager.py already excludes expired/inactive users correctly —
# the config it builds is right — but nothing ever calls it on a timer, so
# an already-loaded client keeps authenticating indefinitely past its
# expiry until some unrelated admin action (creating/editing another user)
# happens to regenerate the config as a side effect. This closes that gap.
#
# apply_xray_config_safe() unconditionally restarts xray (dropping every
# active connection), so this only calls it when a user newly crossed into
# "expired but still loaded" since the last check — never repeatedly for
# the same already-purged user.
_fm_v2ray_enforce_expiry() {
    command -v python3 >/dev/null 2>&1 || return 0
    [[ -f /etc/firewallfalcon/panel/v2ray_manager.py || -f /usr/local/bin/v2ray_manager.py ]] || return 0
    systemctl is-enabled xray &>/dev/null || return 0

    python3 - <<'PYEOF' 2>/dev/null
import sys
from datetime import datetime
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager

    MARKER = "/etc/firewallfalcon/.v2ray_expiry_purged"
    now = datetime.now()
    expired_active = set()
    for u in v2ray_manager.read_v2ray_users():
        if not u.get("is_active", True):
            continue
        exp = (u.get("expire_date") or "").strip()
        if not exp:
            continue
        try:
            exp_dt = datetime.strptime(exp.split()[0], "%Y-%m-%d")
        except Exception:
            continue
        if exp_dt < now:
            expired_active.add(u.get("uuid", ""))

    try:
        with open(MARKER) as f:
            already_purged = set(f.read().split())
    except Exception:
        already_purged = set()

    if expired_active - already_purged:
        v2ray_manager.apply_xray_config_safe()
        with open(MARKER, "w") as f:
            f.write("\n".join(sorted(expired_active)))
except Exception:
    pass
PYEOF
}

# Some minimal/stripped VPS images (common on cheap providers) ship without
# the cron package at all — `crontab` doesn't exist, so every `crontab -l`
# / `crontab -` call in this file used to fail with "command not found" and
# silently do nothing, while the menu still printed "✅ enabled". Install it
# on demand and make sure the daemon is actually running before trusting it.
_fm_ensure_crontab_available() {
    if ! command -v crontab >/dev/null 2>&1; then
        echo -e "${C_YELLOW}⚠️ 'crontab' is not installed — installing it now...${C_RESET}"
        if command -v apt-get &>/dev/null; then
            apt-get update -qq &>/dev/null; apt-get install -y -q cron &>/dev/null
        elif command -v dnf &>/dev/null; then
            dnf install -y -q cronie &>/dev/null
        elif command -v yum &>/dev/null; then
            yum install -y -q cronie &>/dev/null
        elif command -v apk &>/dev/null; then
            apk add --no-cache dcron &>/dev/null
        elif command -v pacman &>/dev/null; then
            pacman -Sy --noconfirm cronie &>/dev/null
        fi
    fi
    command -v crontab >/dev/null 2>&1 || return 1

    local svc
    for svc in cron crond cronie; do
        if systemctl list-unit-files 2>/dev/null | grep -q "^${svc}\.service"; then
            systemctl enable "$svc" &>/dev/null
            systemctl start "$svc" &>/dev/null
            systemctl is-active --quiet "$svc" && return 0
        fi
    done
    # No matching systemd unit found (e.g. sysvinit/openrc) — crontab exists,
    # assume the distro's own init already runs its cron daemon.
    return 0
}

# ── System Optimization: BBR, swap, network tuning, log rotation, fail2ban ──
# Bundled under one menu because they all serve the same goal — a faster,
# more stable long-running server — and every one of them is safe to re-run
# any time: each checks the current state first and leaves it alone if it's
# already applied, instead of blindly re-appending config on every run.
_FM_SYSCTL_CONF="/etc/sysctl.d/99-dahoom-network.conf"
_FM_SWAP_FILE="/swap/dahoom.swap"
_FM_LOGROTATE_CONF="/etc/logrotate.d/dahoom"

_fm_bbr_active() {
    [[ "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)" == "bbr" ]]
}

# Persists BBR (when the kernel supports it) plus a set of generic,
# well-known-safe network tuning values for a VPN/proxy server that expects
# many concurrent short-lived connections. Re-generating the file each run
# keeps it idempotent without needing to track which lines were ours.
_fm_apply_network_tuning() {
    modprobe tcp_bbr &>/dev/null || true
    local available cc_line=""
    available=$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)
    if [[ "$available" == *bbr* ]]; then
        cc_line="net.ipv4.tcp_congestion_control = bbr"
        [[ -f /etc/modules-load.d/dahoom-bbr.conf ]] || echo "tcp_bbr" > /etc/modules-load.d/dahoom-bbr.conf 2>/dev/null
    fi

    cat > "$_FM_SYSCTL_CONF" <<EOF
# DAHOOM — generic network/stability tuning for a VPN/proxy server.
# Re-generated by the System Optimization menu; edit at your own risk.
net.core.default_qdisc = fq
${cc_line}
net.core.somaxconn = 65535
net.ipv4.tcp_max_syn_backlog = 65535
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_fastopen = 3
net.ipv4.ip_local_port_range = 1024 65535
fs.file-max = 2097152
vm.swappiness = 10
EOF
    sysctl -p "$_FM_SYSCTL_CONF" &>/dev/null

    # System-wide open-file ceiling, complementing the per-service
    # LimitNOFILE already set on individual systemd units.
    if [[ ! -f /etc/security/limits.d/99-dahoom.conf ]]; then
        cat > /etc/security/limits.d/99-dahoom.conf <<'EOF'
* soft nofile 1000000
* hard nofile 1000000
EOF
    fi

    _log_action "SYSTEM_OPT" "network_tuning" "status=applied bbr=$([[ -n "$cc_line" ]] && echo yes || echo unavailable)"
    return 0
}

# Small/cheap VPS images (512MB-1GB RAM) commonly ship with zero swap —
# under memory pressure the kernel OOM-killer just silently kills whatever
# process it picks (xray, sshd, badvpn...), which looks exactly like the
# random "server just hangs" instability this whole menu exists to prevent.
# Skips cleanly if swap already exists (active, or merely configured in
# fstab) or if there isn't enough free disk to safely create one.
_fm_ensure_swap() {
    swapon --show 2>/dev/null | grep -q . && return 0
    grep -qE '^\s*[^#].*\sswap\s' /etc/fstab 2>/dev/null && return 0

    local mem_mb swap_mb free_mb
    mem_mb=$(awk '/MemTotal/{print int($2/1024)}' /proc/meminfo 2>/dev/null)
    [[ "$mem_mb" =~ ^[0-9]+$ ]] || mem_mb=1024

    if (( mem_mb <= 2048 )); then
        swap_mb=$mem_mb
    elif (( mem_mb <= 8192 )); then
        swap_mb=$(( mem_mb / 2 ))
    else
        swap_mb=4096
    fi
    (( swap_mb < 256 )) && swap_mb=256

    free_mb=$(df -Pm / 2>/dev/null | awk 'NR==2{print $4}')
    if [[ "$free_mb" =~ ^[0-9]+$ ]] && (( free_mb < swap_mb + 512 )); then
        return 1
    fi

    mkdir -p "$(dirname "$_FM_SWAP_FILE")" 2>/dev/null
    if command -v fallocate &>/dev/null && fallocate -l "${swap_mb}M" "$_FM_SWAP_FILE" 2>/dev/null; then
        :
    else
        dd if=/dev/zero of="$_FM_SWAP_FILE" bs=1M count="$swap_mb" status=none 2>/dev/null
    fi
    chmod 600 "$_FM_SWAP_FILE"
    mkswap "$_FM_SWAP_FILE" &>/dev/null
    if ! swapon "$_FM_SWAP_FILE" &>/dev/null; then
        rm -f "$_FM_SWAP_FILE"
        return 1
    fi
    grep -qF "$_FM_SWAP_FILE" /etc/fstab 2>/dev/null || echo "$_FM_SWAP_FILE none swap sw 0 0" >> /etc/fstab

    _log_action "SYSTEM_OPT" "swap" "status=created size_mb=${swap_mb}"
    return 0
}

# Admin/audit logs and Xray's access/error logs grow forever without this —
# eventually filling the disk, which causes its own cascade of service
# failures. copytruncate avoids needing to signal/restart anything.
_fm_setup_logrotate() {
    command -v logrotate &>/dev/null || ff_pkg_install logrotate &>/dev/null
    command -v logrotate &>/dev/null || return 1

    cat > "$_FM_LOGROTATE_CONF" <<EOF
$ADMIN_LOG
$LOGS_DIR/*.log
/var/log/xray/access.log
/var/log/xray/error.log
{
    weekly
    rotate 4
    size 20M
    compress
    delaycompress
    missingok
    notifempty
    copytruncate
}
EOF
    _log_action "SYSTEM_OPT" "logrotate" "status=configured"
    return 0
}

# Repeated failed SSH logins cost CPU/IO and file-descriptors for no
# legitimate reason — banning the source after a few tries frees that
# capacity back up for real users instead of the tool constantly fighting
# to stay responsive under a slow background brute-force scan.
_fm_setup_fail2ban() {
    if ! command -v fail2ban-client &>/dev/null; then
        echo -e "${C_BLUE}📦 Installing fail2ban...${C_RESET}"
        ff_pkg_install fail2ban &>/dev/null
    fi
    command -v fail2ban-client &>/dev/null || { echo -e "${C_YELLOW}⚠️ fail2ban is not available for this system — skipped.${C_RESET}"; return 1; }

    local backend="systemd"
    [[ -f /var/log/auth.log || -f /var/log/secure ]] && backend="auto"

    mkdir -p /etc/fail2ban/jail.d
    cat > /etc/fail2ban/jail.d/dahoom-sshd.conf <<EOF
[sshd]
enabled = true
backend = ${backend}
maxretry = 5
findtime = 10m
bantime = 1h
EOF

    systemctl enable fail2ban &>/dev/null
    systemctl restart fail2ban &>/dev/null
    systemctl is-active --quiet fail2ban || return 1

    _log_action "SYSTEM_OPT" "fail2ban" "status=enabled"
    return 0
}

# Reverts everything the four options above can turn on. Each step only
# touches what DAHOOM itself created (our own config file paths / our own
# swap file), and is skipped silently if that item was never enabled — this
# is safe to run even if only some of "Apply All" ever succeeded.
_fm_disable_all_optimizations() {
    echo -e "\n${C_BLUE}🔧 Reverting network tuning...${C_RESET}"
    if [[ -f "$_FM_SYSCTL_CONF" ]]; then
        rm -f "$_FM_SYSCTL_CONF"
        # Removing the file alone only takes effect on next boot — restore
        # the live values now too, back to the kernel's own stock defaults.
        sysctl -w net.ipv4.tcp_congestion_control=cubic &>/dev/null
        sysctl -w net.core.default_qdisc=fq_codel &>/dev/null
        sysctl --system &>/dev/null
        echo -e "${C_GREEN}✅ Network tuning reverted.${C_RESET}"
    else
        echo -e "${C_GRAY}— Network tuning was not active, skipped.${C_RESET}"
    fi
    rm -f /etc/modules-load.d/dahoom-bbr.conf /etc/security/limits.d/99-dahoom.conf 2>/dev/null

    echo -e "${C_BLUE}💾 Removing swap...${C_RESET}"
    if [[ -f "$_FM_SWAP_FILE" ]]; then
        swapoff "$_FM_SWAP_FILE" &>/dev/null
        sed -i "\|^${_FM_SWAP_FILE//\//\\/}[[:space:]]|d" /etc/fstab 2>/dev/null
        rm -f "$_FM_SWAP_FILE"
        echo -e "${C_GREEN}✅ Swap removed.${C_RESET}"
    else
        echo -e "${C_GRAY}— No DAHOOM-created swap found, skipped.${C_RESET}"
    fi

    echo -e "${C_BLUE}🗃 Removing log rotation config...${C_RESET}"
    if [[ -f "$_FM_LOGROTATE_CONF" ]]; then
        rm -f "$_FM_LOGROTATE_CONF"
        echo -e "${C_GREEN}✅ Log rotation config removed.${C_RESET}"
    else
        echo -e "${C_GRAY}— Log rotation was not configured, skipped.${C_RESET}"
    fi

    echo -e "${C_BLUE}🛡 Disabling fail2ban...${C_RESET}"
    if [[ -f /etc/fail2ban/jail.d/dahoom-sshd.conf ]]; then
        rm -f /etc/fail2ban/jail.d/dahoom-sshd.conf
        systemctl disable --now fail2ban &>/dev/null
        echo -e "${C_YELLOW}✅ fail2ban stopped and disabled — SSH has no brute-force ban protection now.${C_RESET}"
    else
        echo -e "${C_GRAY}— fail2ban was not enabled by DAHOOM, skipped.${C_RESET}"
    fi

    _log_action "SYSTEM_OPT" "disable_all" "status=reverted"
    echo -e "\n${C_GREEN}✅ All optimizations reverted.${C_RESET}"
}

# Runs every check silently (used from initial_setup so new installs get
# all of this by default) without printing anything or failing the caller.
_fm_system_optimization_silent() {
    _fm_apply_network_tuning
    _fm_ensure_swap
    _fm_setup_logrotate
    _fm_setup_fail2ban
    return 0
}

system_optimization_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "SYSTEM OPTIMIZATION & STABILITY" "$C_TITLE"
        echo

        local bbr_status swap_status logrotate_status f2b_status
        _fm_bbr_active && bbr_status="${C_GREEN}Active${C_RESET}" || bbr_status="${C_YELLOW}Not active${C_RESET}"
        if swapon --show 2>/dev/null | grep -q .; then
            swap_status="${C_GREEN}Active${C_RESET}"
        else
            swap_status="${C_YELLOW}Not configured${C_RESET}"
        fi
        [[ -f "$_FM_LOGROTATE_CONF" ]] && logrotate_status="${C_GREEN}Configured${C_RESET}" || logrotate_status="${C_YELLOW}Not configured${C_RESET}"
        if systemctl is-active --quiet fail2ban 2>/dev/null; then
            f2b_status="${C_GREEN}Active${C_RESET}"
        else
            f2b_status="${C_YELLOW}Not active${C_RESET}"
        fi

        echo -e "  ${C_CYAN}BBR Congestion Control:${C_RESET} $bbr_status"
        echo -e "  ${C_CYAN}Swap:${C_RESET}                    $swap_status"
        echo -e "  ${C_CYAN}Log Rotation:${C_RESET}            $logrotate_status"
        echo -e "  ${C_CYAN}fail2ban (SSH protection):${C_RESET} $f2b_status"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Apply All (recommended)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Enable BBR + Network Tuning only"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Create Swap only"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Configure Log Rotation only"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Enable fail2ban (SSH) only"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[6]" "Disable All Optimizations (revert everything)"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" so_act; then
            return
        fi
        case "$so_act" in
            1)
                echo -e "\n${C_BLUE}🔧 Applying network tuning (BBR)...${C_RESET}"
                _fm_apply_network_tuning
                echo -e "${C_BLUE}💾 Checking swap...${C_RESET}"
                if _fm_ensure_swap; then
                    echo -e "${C_GREEN}✅ Swap ready.${C_RESET}"
                else
                    echo -e "${C_YELLOW}⚠️ Swap skipped (already present, or not enough free disk).${C_RESET}"
                fi
                echo -e "${C_BLUE}🗃 Configuring log rotation...${C_RESET}"
                _fm_setup_logrotate
                echo -e "${C_BLUE}🛡 Enabling fail2ban...${C_RESET}"
                if _fm_setup_fail2ban; then
                    echo -e "${C_GREEN}✅ fail2ban active.${C_RESET}"
                else
                    echo -e "${C_YELLOW}⚠️ fail2ban could not be enabled on this system.${C_RESET}"
                fi
                echo -e "\n${C_GREEN}✅ System optimization applied.${C_RESET}"
                press_enter
                ;;
            2)
                _fm_apply_network_tuning
                if _fm_bbr_active; then
                    echo -e "\n${C_GREEN}✅ BBR is active, network tuning applied.${C_RESET}"
                else
                    echo -e "\n${C_YELLOW}⚠️ Network tuning applied, but this kernel doesn't support BBR — kept the current algorithm.${C_RESET}"
                fi
                press_enter
                ;;
            3)
                if _fm_ensure_swap; then
                    echo -e "\n${C_GREEN}✅ Swap ready.${C_RESET}"
                else
                    echo -e "\n${C_YELLOW}⚠️ Swap skipped (already present, or not enough free disk space).${C_RESET}"
                fi
                press_enter
                ;;
            4)
                if _fm_setup_logrotate; then
                    echo -e "\n${C_GREEN}✅ Log rotation configured.${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ Could not install/configure logrotate on this system.${C_RESET}"
                fi
                press_enter
                ;;
            5)
                if _fm_setup_fail2ban; then
                    echo -e "\n${C_GREEN}✅ fail2ban is active and guarding SSH.${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ fail2ban is not available on this system.${C_RESET}"
                fi
                press_enter
                ;;
            6)
                echo -e "\n${C_WARN}⚠️  This will revert everything 'Apply All' turned on:${C_RESET}"
                echo -e "  ${C_YELLOW}•${C_RESET} Network tuning / BBR — reverted to system defaults"
                echo -e "  ${C_YELLOW}•${C_RESET} Swap created by DAHOOM — removed and deleted"
                echo -e "  ${C_YELLOW}•${C_RESET} Log rotation config — removed"
                echo -e "  ${C_RED}•${C_RESET} fail2ban — STOPPED. SSH loses its brute-force ban protection."
                read -r -p "$(echo -e "\n${C_WARN}> Type 'yes' to confirm disabling everything: ${C_RESET}")" so_conf
                if [[ "$so_conf" == "yes" ]]; then
                    _fm_disable_all_optimizations
                else
                    echo -e "\n${C_YELLOW}❌ Cancelled — nothing was changed.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

# =====================================================================
# CONNECTION MODES: OpenSSH / Squid / Dropbear / OpenVPN / SOCKS+Websocket
# / SSL Tunnel (stunnel) / SlowDNS — a unified live-status hub for every
# way a client can reach this server.
# =====================================================================

_fm_openvpn_unit_for() {
    local name="$1"
    if systemctl list-unit-files 2>/dev/null | grep -q '^openvpn-server@'; then
        echo "openvpn-server@${name}"
    else
        echo "openvpn@${name}"
    fi
}

# The "openvpn-server@" template (shipped alongside "openvpn@" in modern
# Debian/Ubuntu packaging) expects its .conf files under /etc/openvpn/server/,
# not /etc/openvpn/ directly — writing server.conf to the wrong directory
# means the unit can't find its own config and fails to start immediately.
_fm_openvpn_conf_dir() {
    if systemctl list-unit-files 2>/dev/null | grep -q '^openvpn-server@'; then
        echo "/etc/openvpn/server"
    else
        echo "/etc/openvpn"
    fi
}

_fm_openvpn_conf_file() {
    echo "$(_fm_openvpn_conf_dir)/server.conf"
}

_fm_socks_backend_choice() {
    echo -e "${C_CYAN}Which local service should this tunnel connect to?${C_RESET}" >&2
    echo "  [1] OpenSSH (127.0.0.1:22) (recommended)" >&2
    echo "  [2] Dropbear" >&2
    echo "  [3] OpenVPN (TCP mode only)" >&2
    echo "  [4] Websocket Proxy" >&2
    echo "  [5] V2Ray/Xray (127.0.0.1:8787, no TLS)" >&2
    echo "  [6] Custom host:port" >&2
    read -r -p "👉 Choice [1]: " b
    case "$b" in
        2)
            # Check the actual running service first — it's the same
            # signal the Dropbear menu itself shows "Active" from. Only
            # fall back to the tracking file (and then to a live ss
            # lookup) for the port itself, so a Dropbear set up by an
            # older version of this menu (before the ports file existed)
            # still resolves correctly instead of reporting "not installed".
            if ! systemctl is-active --quiet "$_fm_dropbear_unit_name" 2>/dev/null; then
                echo -e "${C_RED}❌ Dropbear isn't installed.${C_RESET}" >&2
                return 1
            fi
            local ports; ports=$(cat "$DROPBEAR_PORTS_FILE" 2>/dev/null)
            [[ -z "$ports" ]] && ports=$(_fm_unit_bound_ports "$_fm_dropbear_unit_name")
            if [[ -z "$ports" ]]; then
                echo -e "${C_RED}❌ Could not determine Dropbear's port.${C_RESET}" >&2
                return 1
            fi
            local dpt="$ports"
            if [[ "$ports" == *" "* ]]; then
                echo -e "${C_CYAN}Dropbear is listening on: ${ports}${C_RESET}" >&2
                read -r -p "👉 Which one should this connect to?: " dpt
            fi
            echo "127.0.0.1:$dpt"
            ;;
        3)
            # A SOCKS/websocket/stunnel proxy here is a TCP-only relay
            # (plain HTTP CONNECT-style tunneling), so it can only reach
            # OpenVPN if OpenVPN itself is running in TCP mode — its
            # default is UDP, which this can't bridge to.
            local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
            if [[ ! -f "$conf_dir/server.conf" ]]; then
                echo -e "${C_RED}❌ OpenVPN isn't installed.${C_RESET}" >&2
                return 1
            fi
            local ovpn_proto ovpn_port
            ovpn_proto=$(grep '^proto ' "$conf_dir/server.conf" | awk '{print $2}')
            ovpn_port=$(grep '^port ' "$conf_dir/server.conf" | awk '{print $2}')
            if [[ "$ovpn_proto" != "tcp" ]]; then
                local _tcp_inst _found_tcp=""
                for _tcp_inst in $(_fm_openvpn_list_extra_instances); do
                    if grep -q '^proto tcp' "$conf_dir/${_tcp_inst}.conf" 2>/dev/null; then
                        _found_tcp="$_tcp_inst"
                        break
                    fi
                done
                if [[ -n "$_found_tcp" ]]; then
                    ovpn_port=$(grep '^port ' "$conf_dir/${_found_tcp}.conf" | awk '{print $2}')
                else
                    echo -e "${C_RED}❌ OpenVPN is running over UDP — this tunnel can't bridge to it.${C_RESET}" >&2
                    echo -e "${C_YELLOW}ℹ️ From the OpenVPN menu, use \"Add a Port\" and choose TCP, then retry.${C_RESET}" >&2
                    return 1
                fi
            fi
            echo "127.0.0.1:$ovpn_port"
            ;;
        4)
            # Same idea as Dropbear above: check the actual running unit
            # first, read its port(s) from the map file, and ask which one
            # if it's listening on more than one.
            if ! systemctl is-active --quiet firewallfalcon-wsproxy 2>/dev/null; then
                echo -e "${C_RED}❌ Websocket Proxy isn't installed.${C_RESET}" >&2
                return 1
            fi
            local wports; wports=$(awk '{print $1}' "$WS_MAP_FILE" 2>/dev/null | xargs)
            [[ -z "$wports" ]] && wports=$(_fm_unit_bound_ports firewallfalcon-wsproxy)
            if [[ -z "$wports" ]]; then
                echo -e "${C_RED}❌ Could not determine Websocket Proxy's port.${C_RESET}" >&2
                return 1
            fi
            local wpt="$wports"
            if [[ "$wports" == *" "* ]]; then
                echo -e "${C_CYAN}Websocket Proxy is listening on: ${wports}${C_RESET}" >&2
                read -r -p "👉 Which one should this connect to?: " wpt
            fi
            echo "127.0.0.1:$wpt"
            ;;
        5)
            # No single systemd unit/port file to verify against — Xray's
            # inbounds are configured freely, so this is just the
            # conventional plain (no-TLS) port DAHOOM's own DNSTT feature
            # already documents, not a live-checked value like the others.
            echo "127.0.0.1:8787"
            ;;
        6)
            read -r -p "👉 host:port: " hp
            [[ -z "$hp" ]] && return 1
            echo "$hp"
            ;;
        *) echo "127.0.0.1:22" ;;
    esac
}

# --- 1. OpenSSH ------------------------------------------------------
# Newer systemd (>=249) ships a generator that derives ssh.socket's
# ListenStream= addresses from sshd_config's Port directives, and
# socket-activates sshd per-connection instead of sshd binding the ports
# itself. Once ssh.socket is enabled, editing sshd_config and restarting
# ssh.service alone does NOT rebind anything — the socket was already
# bound before the edit and won't pick up a newly added Port until the
# generator re-runs (daemon-reload) and the socket itself restarts. This
# silently "worked" for us before only because some other menu action's
# own daemon-reload happened to catch it up afterwards.
_fm_ssh_apply_config() {
    systemctl daemon-reload
    if systemctl list-unit-files ssh.socket &>/dev/null && systemctl is-enabled --quiet ssh.socket 2>/dev/null; then
        systemctl restart ssh.socket 2>/dev/null
    fi
    systemctl restart sshd 2>/dev/null || systemctl restart ssh 2>/dev/null || service ssh restart 2>/dev/null
}


connection_openssh_menu() {
    while true; do
        clear; show_banner
        menu_section "OPENSSH" "$C_TITLE"
        echo
        local ports
        mkdir -p /run/sshd 2>/dev/null
        ports=$(sshd -T 2>/dev/null | awk '/^port /{print $2}' | xargs)
        [[ -z "$ports" ]] && ports=$(awk '/^[[:space:]]*Port[[:space:]]+[0-9]+/{print $2}' /etc/ssh/sshd_config 2>/dev/null | xargs)
        [[ -z "$ports" ]] && ports="22"
        echo -e "  ${C_CYAN}Active Ports:${C_RESET} ${C_GREEN}${ports}${C_RESET}"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Add a Port"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove a Port"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
        case "$op" in
            1)
                read -r -p "👉 Port to add: " pt
                if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; continue; fi
                check_and_free_ports "$pt" || { press_enter; continue; }
                echo "Port $pt" >> /etc/ssh/sshd_config
                # Validate the config BEFORE restarting — a bad line here
                # (duplicate, syntax error) would otherwise silently leave
                # sshd on its old config (or down), while we kept printing
                # a plain "success" regardless of what actually happened.
                local _sshd_test_err
                _sshd_test_err=$(sshd -t 2>&1)
                if [[ $? -ne 0 ]]; then
                    sed -i '$d' /etc/ssh/sshd_config
                    echo -e "${C_RED}❌ sshd rejected this config — reverted. Error:${C_RESET}"
                    echo "$_sshd_test_err"
                    press_enter; continue
                fi
                check_and_open_firewall_port "$pt" tcp
                _fm_ssh_apply_config
                sleep 1
                if ss -tlnp 2>/dev/null | awk '{print $4}' | grep -qE ":${pt}\$"; then
                    echo -e "${C_GREEN}✅ Port $pt confirmed listening.${C_RESET}"
                else
                    echo -e "${C_YELLOW}⚠️ Port $pt was added to sshd_config, but isn't actually listening yet. Last log lines:${C_RESET}"
                    journalctl -u ssh -u sshd -n 15 --no-pager 2>/dev/null
                fi
                press_enter
                ;;
            2)
                read -r -p "👉 Port to remove: " pt
                if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; continue; fi
                if [[ "$pt" == "22" ]]; then
                    echo -e "${C_YELLOW}⚠️ Port 22 is the default SSH port — removing it risks locking you out. Skipped.${C_RESET}"
                    press_enter; continue
                fi
                sed -i "/^Port $pt\$/d" /etc/ssh/sshd_config
                _fm_ssh_apply_config
                sleep 1
                if ss -tlnp 2>/dev/null | awk '{print $4}' | grep -qE ":${pt}\$"; then
                    echo -e "${C_YELLOW}⚠️ Removed from sshd_config, but something is still listening on $pt.${C_RESET}"
                else
                    echo -e "${C_GREEN}✅ Port $pt removed.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

# --- 2. Squid Proxy (DPI-Bypass) ---------------------------------------
# Runs the same pre-compiled netrelay-v1-vodafoneIE binary as the standalone
# Net Relay feature — its own copy under a different path/unit so the two
# stay fully independent (installing/removing one never touches the other).
_fm_squid_reload_filter() {
    local ports="$1"
    sed -i "s|^ExecStart=.*|ExecStart=$SQUID_BINARY -p ${ports}|" "$SQUID_FILTER_SERVICE"
    systemctl daemon-reload
    systemctl restart firewallfalcon-sqfilter
}

# Re-enter the whole port list in one line and replace it outright — same
# flow as Net Relay's "port(s) for ... (e.g., 8080 or 8080 8888)" prompt,
# for picking exactly which ports run instead of adding/removing one by one.
_fm_squid_reconfigure_ports() {
    local cur; cur=$(cat "$SQUID_PORTS_FILE" 2>/dev/null)
    echo -e "${C_CYAN}Current ports:${C_RESET} ${cur:-none}"
    read -r -p "👉 New port list (space-separated, e.g. 80 8080): " ports_in
    if [[ -z "$ports_in" ]]; then echo -e "${C_RED}❌ No ports given.${C_RESET}"; press_enter; return; fi
    local pt
    for pt in $ports_in; do
        if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port: $pt${C_RESET}"; press_enter; return; fi
        [[ " $cur " == *" $pt "* ]] || check_and_free_ports "$pt" || { press_enter; return; }
    done
    echo "$ports_in" > "$SQUID_PORTS_FILE"
    _fm_squid_reload_filter "$ports_in"
    for pt in $ports_in; do
        check_and_open_firewall_port "$pt" tcp
    done
    sleep 1
    if systemctl is-active --quiet firewallfalcon-sqfilter; then
        echo -e "\n${C_GREEN}✅ Squid Proxy now on: ${ports_in}${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Failed to start. Last log lines:${C_RESET}"
        journalctl -u firewallfalcon-sqfilter -n 15 --no-pager 2>/dev/null
    fi
    press_enter
}

_fm_squid_install() {
    echo
    read -r -p "👉 Public port(s) for Squid Proxy to accept on (space-separated, e.g. 80 8080): " ports_in
    if [[ -z "$ports_in" ]]; then echo -e "${C_RED}❌ No ports given.${C_RESET}"; press_enter; return; fi
    local pt
    for pt in $ports_in; do
        if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port: $pt${C_RESET}"; press_enter; return; fi
        check_and_free_ports "$pt" || { press_enter; return; }
    done

    mkdir -p "$CONN_MODES_DIR"

    local download_url="$(_fm_instalasi_raw)/netrelay-v1-vodafoneIE"
    echo -e "\n${C_GREEN}📥 Downloading Squid Proxy binary...${C_RESET}"
    if ! wget -q --show-progress -O "$SQUID_BINARY" "$download_url"; then
        echo -e "\n${C_RED}❌ Failed to download Squid Proxy binary from $download_url.${C_RESET}"
        press_enter; return
    fi
    chmod +x "$SQUID_BINARY"

    cat > "$SQUID_FILTER_SERVICE" <<EOF
[Unit]
Description=DAHOOM Squid Proxy (DPI-Bypass)
After=network.target

[Service]
Type=simple
ExecStart=$SQUID_BINARY -p ${ports_in}
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
EOF

    echo "$ports_in" > "$SQUID_PORTS_FILE"

    for pt in $ports_in; do
        check_and_open_firewall_port "$pt" tcp
    done

    systemctl daemon-reload
    systemctl enable firewallfalcon-sqfilter >/dev/null 2>&1
    systemctl restart firewallfalcon-sqfilter

    sleep 1
    if systemctl is-active --quiet firewallfalcon-sqfilter; then
        echo -e "\n${C_GREEN}✅ Squid Proxy installed. Public ports: ${ports_in}${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Failed to start. Last log lines:${C_RESET}"
        journalctl -u firewallfalcon-sqfilter -n 15 --no-pager 2>/dev/null
    fi
    press_enter
}

_fm_squid_add_port() {
    read -r -p "👉 Port to add: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    check_and_free_ports "$pt" || { press_enter; return; }
    local cur; cur=$(cat "$SQUID_PORTS_FILE" 2>/dev/null)
    if [[ " $cur " == *" $pt "* ]]; then
        echo -e "${C_YELLOW}⚠️ Port already in use by Squid.${C_RESET}"; press_enter; return
    fi
    cur="${cur} ${pt}"; cur="${cur# }"
    echo "$cur" > "$SQUID_PORTS_FILE"
    _fm_squid_reload_filter "$cur"
    check_and_open_firewall_port "$pt" tcp
    echo -e "${C_GREEN}✅ Port $pt added.${C_RESET}"
    press_enter
}

_fm_squid_remove_port() {
    read -r -p "👉 Port to remove: " pt
    local cur; cur=$(cat "$SQUID_PORTS_FILE" 2>/dev/null)
    local new="" p
    for p in $cur; do [[ "$p" != "$pt" ]] && new="${new} ${p}"; done
    new="${new# }"
    if [[ -z "$new" ]]; then
        echo -e "${C_YELLOW}⚠️ That would leave Squid with no ports — removing the whole proxy instead.${C_RESET}"
        _fm_squid_uninstall
        return
    fi
    echo "$new" > "$SQUID_PORTS_FILE"
    _fm_squid_reload_filter "$new"
    echo -e "${C_GREEN}✅ Port $pt removed.${C_RESET}"
    press_enter
}

_fm_squid_uninstall() {
    read -r -p "👉 Are you sure you want to remove Squid Proxy? (y/n): " c
    [[ "$c" == "y" || "$c" == "Y" ]] || { press_enter; return; }
    systemctl stop firewallfalcon-sqfilter 2>/dev/null
    systemctl disable firewallfalcon-sqfilter 2>/dev/null
    rm -f "$SQUID_FILTER_SERVICE" "$SQUID_BINARY" "$SQUID_PORTS_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}✅ Squid Proxy removed.${C_RESET}"
    press_enter
}

squid_proxy_menu() {
    while true; do
        clear; show_banner
        menu_section "SQUID PROXY (DPI-Bypass)" "$C_TITLE"
        echo
        if systemctl is-active --quiet firewallfalcon-sqfilter 2>/dev/null; then
            local pts; pts=$(cat "$SQUID_PORTS_FILE" 2>/dev/null)
            echo -e "  ${C_CYAN}Status:${C_RESET} ${C_GREEN}Active${C_RESET}"
            echo -e "  ${C_CYAN}Public Ports:${C_RESET} ${C_GREEN}${pts:-none}${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Add a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Reconfigure All Ports"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[4]" "Uninstall Squid Proxy"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_squid_add_port ;;
                2) _fm_squid_remove_port ;;
                3) _fm_squid_reconfigure_ports ;;
                4) _fm_squid_uninstall; return ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            echo -e "  ${C_YELLOW}Squid is not installed.${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install Squid Proxy"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_squid_install ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# --- 3. Dropbear -------------------------------------------------------
# We fully own our own unit (firewallfalcon-dropbear.service) instead of
# fighting the vendor-packaged dropbear.service/.socket, whose ExecStart
# wiring to /etc/default/dropbear (DROPBEAR_PORT vs DROPBEAR_EXTRA_ARGS,
# and drop-in merge order) turned out to vary and silently keep falling
# back to port 22 no matter what we wrote there. Only the `dropbear`
# package (for the binary + dropbearkey) and the port itself matter now —
# the packaged unit is stopped/disabled once and never touched again.
_fm_dropbear_unit_name="firewallfalcon-dropbear"
_fm_dropbear_unit_file="/etc/systemd/system/${_fm_dropbear_unit_name}.service"

# $DROPBEAR_PORTS_FILE holds the current space-separated port list;
# _fm_dropbear_write_unit rebuilds ExecStart with one "-p <port>" per
# entry, so Dropbear listens on all of them at once (it supports repeating
# -p natively).
_fm_dropbear_write_unit() {
    local ports="$1" execline="/usr/sbin/dropbear -R -F"
    local pt
    for pt in $ports; do execline="$execline -p $pt"; done
    cat > "$_fm_dropbear_unit_file" <<EOF
[Unit]
Description=DAHOOM Dropbear SSH Server
After=network.target

[Service]
Type=simple
ExecStart=${execline}
Restart=on-failure
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload
}

_fm_dropbear_restart_and_report() {
    local expect_ports="$1"
    systemctl restart "$_fm_dropbear_unit_name"
    sleep 1
    if ! systemctl is-active --quiet "$_fm_dropbear_unit_name"; then
        echo -e "\n${C_RED}❌ Dropbear failed to start. Last log lines:${C_RESET}"
        journalctl -u "$_fm_dropbear_unit_name" -n 15 --no-pager 2>/dev/null
        return 1
    fi
    local bound; bound=$(ss -tlnp 2>/dev/null | grep dropbear | awk '{print $4}' | awk -F: '{print $NF}' | sort -un | xargs)
    local expected_sorted; expected_sorted=$(echo "$expect_ports" | xargs -n1 | sort -un | xargs)
    if [[ "$bound" == "$expected_sorted" ]]; then
        echo -e "\n${C_GREEN}✅ Dropbear confirmed listening on: ${bound}${C_RESET}"
    else
        echo -e "\n${C_YELLOW}⚠️ Dropbear is active, but is actually bound to: ${bound:-unknown} (expected ${expected_sorted}).${C_RESET}"
    fi
}

_fm_dropbear_install() {
    read -r -p "👉 Which port should Dropbear listen on?: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    check_and_free_ports "$pt" || { press_enter; return; }

    echo -e "\n${C_BLUE}📦 Installing Dropbear...${C_RESET}"
    ff_pkg_install dropbear || { echo -e "${C_RED}❌ Failed to install Dropbear.${C_RESET}"; press_enter; return; }

    # Neutralize the package's own unit(s) so they can never auto-start
    # and fight our unit for the same port.
    systemctl stop dropbear dropbear.socket 2>/dev/null
    systemctl disable dropbear dropbear.socket 2>/dev/null
    systemctl mask dropbear.socket 2>/dev/null

    grep -q '^PasswordAuthentication yes' /etc/ssh/sshd_config || echo "PasswordAuthentication yes" >> /etc/ssh/sshd_config
    grep -q '^PermitTunnel yes' /etc/ssh/sshd_config || echo "PermitTunnel yes" >> /etc/ssh/sshd_config

    # DAHOOM creates every VPN-only account with shell /usr/sbin/nologin —
    # OpenSSH doesn't care, but Dropbear validates the account's shell
    # against /etc/shells via getusershell() and silently rejects the
    # login as a bad password if the shell isn't listed there.
    grep -qxF /usr/sbin/nologin /etc/shells 2>/dev/null || echo /usr/sbin/nologin >> /etc/shells
    grep -qxF /bin/false /etc/shells 2>/dev/null || echo /bin/false >> /etc/shells

    # A missing host key is a classic cause of "control process exited
    # with error code" on first start. (DSS/DSA is legacy and some builds
    # refuse to generate it — fine, dropbear still starts on the others.)
    mkdir -p /etc/dropbear
    [[ -f /etc/dropbear/dropbear_rsa_host_key ]] || dropbearkey -t rsa -f /etc/dropbear/dropbear_rsa_host_key >/dev/null 2>&1
    [[ -f /etc/dropbear/dropbear_ecdsa_host_key ]] || dropbearkey -t ecdsa -f /etc/dropbear/dropbear_ecdsa_host_key >/dev/null 2>&1
    [[ -f /etc/dropbear/dropbear_ed25519_host_key ]] || dropbearkey -t ed25519 -f /etc/dropbear/dropbear_ed25519_host_key >/dev/null 2>&1
    [[ -f /etc/dropbear/dropbear_dss_host_key ]] || dropbearkey -t dss -f /etc/dropbear/dropbear_dss_host_key >/dev/null 2>&1

    mkdir -p "$CONN_MODES_DIR"
    echo "$pt" > "$DROPBEAR_PORTS_FILE"
    _fm_dropbear_write_unit "$pt"

    check_and_open_firewall_port "$pt" tcp
    systemctl enable "$_fm_dropbear_unit_name" >/dev/null 2>&1
    echo -e "\n${C_BLUE}🚀 Starting Dropbear...${C_RESET}"
    _fm_dropbear_restart_and_report "$pt"
    press_enter
}

_fm_dropbear_add_port() {
    read -r -p "👉 Port to add: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    local cur; cur=$(cat "$DROPBEAR_PORTS_FILE" 2>/dev/null)
    if [[ " $cur " == *" $pt "* ]]; then
        echo -e "${C_YELLOW}⚠️ Dropbear is already listening on that port.${C_RESET}"; press_enter; return
    fi
    check_and_free_ports "$pt" || { press_enter; return; }
    cur="${cur} ${pt}"; cur="${cur# }"
    echo "$cur" > "$DROPBEAR_PORTS_FILE"
    _fm_dropbear_write_unit "$cur"
    check_and_open_firewall_port "$pt" tcp
    _fm_dropbear_restart_and_report "$cur"
    press_enter
}

_fm_dropbear_remove_port() {
    read -r -p "👉 Port to remove: " pt
    local cur; cur=$(cat "$DROPBEAR_PORTS_FILE" 2>/dev/null)
    local new="" p
    for p in $cur; do [[ "$p" != "$pt" ]] && new="${new} ${p}"; done
    new="${new# }"
    if [[ "$new" == "$cur" ]]; then
        echo -e "${C_YELLOW}⚠️ Dropbear isn't listening on that port.${C_RESET}"; press_enter; return
    fi
    if [[ -z "$new" ]]; then
        echo -e "${C_YELLOW}⚠️ That would leave Dropbear with no ports — removing it entirely instead.${C_RESET}"
        _fm_dropbear_uninstall
        return
    fi
    echo "$new" > "$DROPBEAR_PORTS_FILE"
    _fm_dropbear_write_unit "$new"
    _fm_dropbear_restart_and_report "$new"
    press_enter
}

_fm_dropbear_uninstall() {
    read -r -p "👉 Are you sure you want to remove Dropbear? (y/n): " c
    [[ "$c" == "y" || "$c" == "Y" ]] || { press_enter; return; }
    systemctl stop "$_fm_dropbear_unit_name" 2>/dev/null
    systemctl disable "$_fm_dropbear_unit_name" 2>/dev/null
    rm -f "$_fm_dropbear_unit_file" "$DROPBEAR_PORTS_FILE"
    ff_pkg_purge dropbear 2>/dev/null
    rm -f /etc/default/dropbear
    rm -rf /etc/systemd/system/dropbear.service.d
    systemctl unmask dropbear.socket 2>/dev/null
    systemctl daemon-reload
    echo -e "${C_GREEN}✅ Dropbear removed.${C_RESET}"
    press_enter
}

dropbear_menu() {
    while true; do
        clear; show_banner
        menu_section "DROPBEAR" "$C_TITLE"
        echo
        if systemctl is-active --quiet "$_fm_dropbear_unit_name" 2>/dev/null; then
            local dpt; dpt=$(ss -tlnp 2>/dev/null | grep dropbear | awk '{print $4}' | awk -F: '{print $NF}' | sort -un | xargs)
            echo -e "  ${C_CYAN}Status:${C_RESET} ${C_GREEN}Active${C_RESET}   ${C_CYAN}Ports:${C_RESET} ${C_GREEN}${dpt:-unknown}${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Add a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove a Port"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[3]" "Uninstall Dropbear"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_dropbear_add_port ;;
                2) _fm_dropbear_remove_port ;;
                3) _fm_dropbear_uninstall; return ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            echo -e "  ${C_YELLOW}Dropbear is not installed.${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install Dropbear"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_dropbear_install ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# --- 4. OpenVPN ---------------------------------------------------------
_fm_openvpn_install() {
    read -r -p "👉 Port for OpenVPN [1194]: " pt; pt=${pt:-1194}
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    echo -e "${C_CYAN}Protocol:${C_RESET}  [1] UDP (recommended)   [2] TCP"
    read -r -p "👉 Choice [1]: " protoc; protoc=${protoc:-1}
    local proto="udp"; [[ "$protoc" == "2" ]] && proto="tcp"

    check_and_free_ports "$pt" || { press_enter; return; }

    echo -e "\n${C_BLUE}📦 Installing OpenVPN + Easy-RSA...${C_RESET}"
    ff_pkg_install openvpn easy-rsa || { echo -e "${C_RED}❌ Failed to install OpenVPN.${C_RESET}"; press_enter; return; }

    local ip; ip=$(curl -s -4 icanhazip.com)
    local ext_if; ext_if=$(ip route show default 2>/dev/null | awk '/default/{print $5; exit}')
    [[ -z "$ext_if" ]] && ext_if="eth0"

    mkdir -p /etc/openvpn/easy-rsa
    if [[ -d /usr/share/easy-rsa ]]; then
        cp -r /usr/share/easy-rsa/. /etc/openvpn/easy-rsa/ 2>/dev/null
    fi
    cd /etc/openvpn/easy-rsa || { echo -e "${C_RED}❌ easy-rsa directory missing.${C_RESET}"; press_enter; return; }
    if [[ ! -x ./easyrsa ]]; then
        echo -e "${C_RED}❌ easy-rsa was not found after installation.${C_RESET}"
        press_enter; return
    fi

    echo -e "${C_BLUE}🔏 Building the certificate authority (this can take a minute)...${C_RESET}"
    ./easyrsa init-pki >/dev/null 2>&1
    EASYRSA_BATCH=1 ./easyrsa build-ca nopass >/dev/null 2>&1
    EASYRSA_BATCH=1 ./easyrsa build-server-full server nopass >/dev/null 2>&1
    EASYRSA_BATCH=1 ./easyrsa gen-crl >/dev/null 2>&1
    openvpn --genkey secret /etc/openvpn/ta.key >/dev/null 2>&1

    if [[ ! -f pki/private/server.key ]]; then
        echo -e "${C_RED}❌ Certificate generation failed.${C_RESET}"
        press_enter; return
    fi

    cp pki/ca.crt pki/issued/server.crt pki/private/server.key pki/crl.pem /etc/openvpn/
    chmod 644 /etc/openvpn/crl.pem

    # Write the config into whichever directory the resolved systemd unit
    # actually reads from, and reference every cert/key by absolute path —
    # relative paths only resolve correctly if the unit's WorkingDirectory
    # matches, which differs between the openvpn@ and openvpn-server@
    # templates. Absolute paths make this correct either way.
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    mkdir -p "$conf_dir"
    cat > "$conf_dir/server.conf" <<EOF
port ${pt}
proto ${proto}
dev tun
ca /etc/openvpn/ca.crt
cert /etc/openvpn/server.crt
key /etc/openvpn/server.key
dh none
ecdh-curve prime256v1
tls-crypt /etc/openvpn/ta.key
topology subnet
server 10.8.0.0 255.255.255.0
ifconfig-pool-persist /etc/openvpn/ipp.txt
push "redirect-gateway def1 bypass-dhcp"
push "dhcp-option DNS 1.1.1.1"
push "dhcp-option DNS 8.8.8.8"
keepalive 10 120
cipher AES-128-GCM
user nobody
group nogroup
persist-key
persist-tun
status /etc/openvpn/openvpn-status.log
verb 3
crl-verify /etc/openvpn/crl.pem
EOF

    cat > /etc/openvpn/client-common.txt <<EOF
client
dev tun
proto ${proto}
remote ${ip} ${pt}
resolv-retry infinite
nobind
persist-key
persist-tun
remote-cert-tls server
cipher AES-128-GCM
verb 3
EOF

    grep -q '^net.ipv4.ip_forward' /etc/sysctl.conf 2>/dev/null && sed -i 's/^net.ipv4.ip_forward.*/net.ipv4.ip_forward=1/' /etc/sysctl.conf || echo 'net.ipv4.ip_forward=1' >> /etc/sysctl.conf
    sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1

    iptables -t nat -A POSTROUTING -s 10.8.0.0/24 -o "$ext_if" -j MASQUERADE 2>/dev/null
    iptables -I INPUT -p "$proto" --dport "$pt" -j ACCEPT 2>/dev/null
    iptables -I FORWARD -s 10.8.0.0/24 -j ACCEPT 2>/dev/null
    iptables -I FORWARD -m state --state RELATED,ESTABLISHED -j ACCEPT 2>/dev/null

    check_and_open_firewall_port "$pt" "$proto"

    local unit; unit=$(_fm_openvpn_unit_for server)
    systemctl enable "$unit" >/dev/null 2>&1
    systemctl restart "$unit"
    sleep 1
    if systemctl is-active --quiet "$unit"; then
        echo -e "\n${C_GREEN}✅ OpenVPN installed and running on ${pt}/${proto}.${C_RESET}"
        echo -e "${C_CYAN}Use option [1] 'Create New Client' to generate a .ovpn file.${C_RESET}"
    else
        echo -e "\n${C_RED}❌ OpenVPN failed to start. Last log lines:${C_RESET}"
        journalctl -u "$unit" -n 20 --no-pager 2>/dev/null
    fi
    press_enter
}

_fm_openvpn_new_client() {
    read -r -p "👉 Client name (letters/numbers/underscore/dash only): " cname
    if [[ ! "$cname" =~ ^[A-Za-z0-9_-]+$ ]]; then echo -e "${C_RED}❌ Invalid name.${C_RESET}"; press_enter; return; fi
    cd /etc/openvpn/easy-rsa || { press_enter; return; }
    if [[ -f "pki/issued/${cname}.crt" ]]; then
        echo -e "${C_YELLOW}⚠️ A client with this name already exists.${C_RESET}"
        press_enter; return
    fi
    EASYRSA_BATCH=1 ./easyrsa build-client-full "$cname" nopass >/dev/null 2>&1
    if [[ ! -f "pki/issued/${cname}.crt" ]]; then
        echo -e "${C_RED}❌ Failed to generate the client certificate.${C_RESET}"
        press_enter; return
    fi

    local out="/root/${cname}.ovpn"
    {
        cat /etc/openvpn/client-common.txt
        echo "<ca>"; cat pki/ca.crt; echo "</ca>"
        echo "<cert>"; sed -ne '/BEGIN CERTIFICATE/,$ p' "pki/issued/${cname}.crt"; echo "</cert>"
        echo "<key>"; cat "pki/private/${cname}.key"; echo "</key>"
        echo "<tls-crypt>"; cat /etc/openvpn/ta.key; echo "</tls-crypt>"
    } > "$out"

    echo -e "${C_GREEN}✅ Client config created: ${C_YELLOW}${out}${C_RESET}"
    if [[ -d "$OVPN_WEB_DIR" ]]; then
        cp "$out" "$OVPN_WEB_DIR/"
        local web_port; web_port=$(grep -oP '(?<=http\.server )[0-9]+' "$OVPN_WEB_SERVICE" 2>/dev/null)
        local ip; ip=$(curl -s -4 icanhazip.com)
        echo -e "${C_CYAN}Download link:${C_RESET} http://${ip}:${web_port:-8081}/${cname}.ovpn"
    fi
    press_enter
}

_fm_openvpn_change_port() {
    read -r -p "👉 New port: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    check_and_free_ports "$pt" || { press_enter; return; }
    local conf_file; conf_file=$(_fm_openvpn_conf_file)
    local proto; proto=$(grep '^proto ' "$conf_file" | awk '{print $2}')
    local ip; ip=$(curl -s -4 icanhazip.com)
    sed -i "s/^port .*/port ${pt}/" "$conf_file"
    sed -i "s/^remote .*/remote ${ip} ${pt}/" /etc/openvpn/client-common.txt
    check_and_open_firewall_port "$pt" "$proto"
    local unit; unit=$(_fm_openvpn_unit_for server)
    systemctl restart "$unit"
    echo -e "${C_GREEN}✅ OpenVPN now listening on port ${pt}. (Already-issued .ovpn files still point at the old port — regenerate them for existing clients.)${C_RESET}"
    press_enter
}

_fm_openvpn_toggle_multilogin() {
    local conf_file; conf_file=$(_fm_openvpn_conf_file)
    if grep -q '^duplicate-cn' "$conf_file"; then
        sed -i '/^duplicate-cn/d' "$conf_file"
        echo -e "${C_YELLOW}⚠️ Multi-login blocked (one connection per certificate).${C_RESET}"
    else
        echo 'duplicate-cn' >> "$conf_file"
        echo -e "${C_GREEN}✅ Multi-login allowed.${C_RESET}"
    fi
    local unit; unit=$(_fm_openvpn_unit_for server)
    systemctl restart "$unit"
    press_enter
}

# Certificates alone let anyone holding a leaked .ovpn file connect. This
# bolts on a second, mandatory factor using the SAME Linux accounts every
# other DAHOOM feature already manages (the $FF_USERS_GROUP group) — via
# OpenVPN's auth-pam plugin (ships inside the openvpn package itself, no
# extra install needed) against a dedicated PAM service restricted to
# that group, so it's neither a brand-new user database nor a door open
# to every system/root account "login" would otherwise accept.
_fm_openvpn_authuserpass_active() {
    grep -q '^plugin .*openvpn-plugin-auth-pam\.so' "$(_fm_openvpn_conf_file)" 2>/dev/null
}

_fm_openvpn_toggle_authuserpass() {
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    local -a conf_files=("$conf_dir/server.conf")
    local inst
    for inst in $(_fm_openvpn_list_extra_instances); do
        conf_files+=("$conf_dir/${inst}.conf")
    done

    if _fm_openvpn_authuserpass_active; then
        local f
        for f in "${conf_files[@]}"; do
            sed -i '/^plugin .*openvpn-plugin-auth-pam\.so/d' "$f" 2>/dev/null
        done
        sed -i '/^auth-user-pass$/d' /etc/openvpn/client-common.txt 2>/dev/null
        echo -e "${C_YELLOW}⚠️ Username/password requirement disabled. Certificate alone is enough again.${C_RESET}"
    else
        local pam_plugin; pam_plugin=$(find /usr/lib /usr/lib64 -name 'openvpn-plugin-auth-pam.so' 2>/dev/null | head -n1)
        if [[ -z "$pam_plugin" ]]; then
            echo -e "${C_RED}❌ openvpn-plugin-auth-pam.so not found — is the 'openvpn' package installed?${C_RESET}"
            press_enter; return
        fi
        cat > /etc/pam.d/openvpn <<EOF
auth requisite pam_succeed_if.so user ingroup ${FF_USERS_GROUP}
auth required pam_unix.so
account required pam_unix.so
EOF
        local f
        for f in "${conf_files[@]}"; do
            grep -q '^plugin .*openvpn-plugin-auth-pam\.so' "$f" 2>/dev/null || echo "plugin $pam_plugin openvpn" >> "$f"
        done
        grep -q '^auth-user-pass$' /etc/openvpn/client-common.txt 2>/dev/null || echo 'auth-user-pass' >> /etc/openvpn/client-common.txt
        echo -e "${C_GREEN}✅ Username/password now required — only accounts in the '${FF_USERS_GROUP}' group can connect.${C_RESET}"
        echo -e "${C_YELLOW}ℹ️ Already-issued .ovpn files don't have \"auth-user-pass\" yet — reissue them (option 1) so client apps actually prompt for it; old ones will otherwise just fail to connect.${C_RESET}"
    fi

    local unit; unit=$(_fm_openvpn_unit_for server)
    systemctl restart "$unit"
    for inst in $(_fm_openvpn_list_extra_instances); do
        systemctl restart "$(_fm_openvpn_unit_for "$inst")" 2>/dev/null
    done
    press_enter
}

# Extra OpenVPN instances (beyond the primary "server") are named
# server2, server3, ... — each is its own real OpenVPN process/unit
# (one port+protocol per process is a hard OpenVPN limitation, unlike
# stunnel/SOCKS which can multiplex many ports in a single process),
# sharing the primary instance's CA/certs.
_fm_openvpn_list_extra_instances() {
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    local f
    for f in "$conf_dir"/server[0-9]*.conf; do
        [[ -f "$f" ]] && basename "$f" .conf
    done
}

_fm_openvpn_next_instance_name() {
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    local i=2
    while [[ -f "$conf_dir/server${i}.conf" ]]; do
        (( i++ ))
    done
    echo "server${i}"
}

_fm_openvpn_add_port() {
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    read -r -p "👉 New port to listen on: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    echo -e "${C_CYAN}Protocol:${C_RESET}  [1] UDP (recommended)   [2] TCP"
    read -r -p "👉 Choice [1]: " protoc; protoc=${protoc:-1}
    local proto="udp"; [[ "$protoc" == "2" ]] && proto="tcp"
    check_and_free_ports "$pt" || { press_enter; return; }

    local inst; inst=$(_fm_openvpn_next_instance_name)
    sed -e "s/^port .*/port ${pt}/" -e "s/^proto .*/proto ${proto}/" "$conf_dir/server.conf" > "$conf_dir/${inst}.conf"
    check_and_open_firewall_port "$pt" "$proto"
    local unit; unit=$(_fm_openvpn_unit_for "$inst")
    systemctl enable "$unit" >/dev/null 2>&1
    systemctl restart "$unit"
    sleep 1
    if systemctl is-active --quiet "$unit"; then
        echo -e "\n${C_GREEN}✅ New OpenVPN port active: ${pt}/${proto} (${inst}).${C_RESET}"
    else
        echo -e "\n${C_RED}❌ Failed to start. Last log lines:${C_RESET}"
        journalctl -u "$unit" -n 20 --no-pager 2>/dev/null
    fi
    press_enter
}

_fm_openvpn_remove_port() {
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    local -a insts=()
    mapfile -t insts < <(_fm_openvpn_list_extra_instances)
    if (( ${#insts[@]} == 0 )); then
        echo -e "${C_YELLOW}⚠️ No extra ports to remove — only the primary port exists (use Change Port for that one).${C_RESET}"
        press_enter; return
    fi
    echo -e "${C_CYAN}Extra ports:${C_RESET}"
    local inst pt proto
    for inst in "${insts[@]}"; do
        pt=$(grep '^port ' "$conf_dir/${inst}.conf" | awk '{print $2}')
        proto=$(grep '^proto ' "$conf_dir/${inst}.conf" | awk '{print $2}')
        echo "   • ${inst}: ${pt}/${proto}"
    done
    read -r -p "👉 Which one to remove? (e.g. server2): " inst
    if [[ ! -f "$conf_dir/${inst}.conf" ]]; then
        echo -e "${C_RED}❌ Not found.${C_RESET}"; press_enter; return
    fi
    pt=$(grep '^port ' "$conf_dir/${inst}.conf" | awk '{print $2}')
    proto=$(grep '^proto ' "$conf_dir/${inst}.conf" | awk '{print $2}')
    local unit; unit=$(_fm_openvpn_unit_for "$inst")
    systemctl stop "$unit" 2>/dev/null
    systemctl disable "$unit" 2>/dev/null
    rm -f "$conf_dir/${inst}.conf"
    echo -e "${C_GREEN}✅ Removed ${inst} (${pt}/${proto}).${C_RESET}"
    press_enter
}

_fm_openvpn_hosts_menu() {
    while true; do
        clear; show_banner
        menu_section "CUSTOM DNS HOSTS" "$C_TITLE"
        echo -e "  ${C_CYAN}Entries currently pointing at 127.0.0.1:${C_RESET}"
        grep '^127\.0\.0\.1' /etc/hosts | grep -v 'localhost' | awk '{print "   • "$2}'
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Add a Host"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove a Host"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
        case "$op" in
            1)
                read -r -p "👉 Host to add (e.g. myapp.local): " h
                [[ -z "$h" ]] && { press_enter; continue; }
                if grep -qw "$h" /etc/hosts; then echo -e "${C_YELLOW}⚠️ Already exists.${C_RESET}"; press_enter; continue; fi
                echo "127.0.0.1 $h" >> /etc/hosts
                echo -e "${C_GREEN}✅ Added.${C_RESET}"
                press_enter
                ;;
            2)
                read -r -p "👉 Host to remove: " h
                sed -i "/^127\.0\.0\.1 $h\$/d" /etc/hosts
                echo -e "${C_GREEN}✅ Removed.${C_RESET}"
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

_fm_openvpn_toggle_web() {
    if systemctl is-active --quiet firewallfalcon-ovpnweb 2>/dev/null; then
        systemctl stop firewallfalcon-ovpnweb
        systemctl disable firewallfalcon-ovpnweb >/dev/null 2>&1
        rm -f "$OVPN_WEB_SERVICE"; rm -rf "$OVPN_WEB_DIR"
        systemctl daemon-reload
        echo -e "${C_GREEN}✅ Web download link disabled.${C_RESET}"
    else
        read -r -p "👉 Port to serve .ovpn downloads on [8081]: " wp; wp=${wp:-8081}
        if [[ ! "$wp" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
        check_and_free_ports "$wp" || { press_enter; return; }
        mkdir -p "$OVPN_WEB_DIR"
        cat > "$OVPN_WEB_SERVICE" <<EOF
[Unit]
Description=DAHOOM OpenVPN Client Download Server
After=network.target

[Service]
Type=simple
WorkingDirectory=$OVPN_WEB_DIR
ExecStart=/usr/bin/python3 -m http.server ${wp} --bind 0.0.0.0
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
EOF
        check_and_open_firewall_port "$wp" tcp
        systemctl daemon-reload
        systemctl enable firewallfalcon-ovpnweb >/dev/null 2>&1
        systemctl restart firewallfalcon-ovpnweb
        echo -e "${C_GREEN}✅ Web download link enabled on port ${wp}. New clients you create will be copied there automatically.${C_RESET}"
    fi
    press_enter
}

_fm_openvpn_uninstall() {
    read -r -p "👉 Are you sure you want to remove OpenVPN completely? (y/n): " c
    [[ "$c" == "y" || "$c" == "Y" ]] || { press_enter; return; }
    local conf_dir; conf_dir=$(_fm_openvpn_conf_dir)
    local pt proto ext_if
    pt=$(grep '^port ' "$conf_dir/server.conf" 2>/dev/null | awk '{print $2}')
    proto=$(grep '^proto ' "$conf_dir/server.conf" 2>/dev/null | awk '{print $2}')
    ext_if=$(ip route show default 2>/dev/null | awk '/default/{print $5; exit}')

    local unit; unit=$(_fm_openvpn_unit_for server)
    systemctl stop "$unit" 2>/dev/null
    systemctl disable "$unit" 2>/dev/null
    local inst unit_n
    for inst in $(_fm_openvpn_list_extra_instances); do
        unit_n=$(_fm_openvpn_unit_for "$inst")
        systemctl stop "$unit_n" 2>/dev/null
        systemctl disable "$unit_n" 2>/dev/null
    done

    [[ -n "$ext_if" ]] && iptables -t nat -D POSTROUTING -s 10.8.0.0/24 -o "$ext_if" -j MASQUERADE 2>/dev/null
    [[ -n "$pt" && -n "$proto" ]] && iptables -D INPUT -p "$proto" --dport "$pt" -j ACCEPT 2>/dev/null
    iptables -D FORWARD -s 10.8.0.0/24 -j ACCEPT 2>/dev/null
    iptables -D FORWARD -m state --state RELATED,ESTABLISHED -j ACCEPT 2>/dev/null

    ff_pkg_purge openvpn 2>/dev/null
    rm -rf /etc/openvpn

    if [[ -d "$OVPN_WEB_DIR" ]]; then
        systemctl stop firewallfalcon-ovpnweb 2>/dev/null
        systemctl disable firewallfalcon-ovpnweb 2>/dev/null
        rm -f "$OVPN_WEB_SERVICE"
        rm -rf "$OVPN_WEB_DIR"
    fi
    systemctl daemon-reload
    echo -e "${C_GREEN}✅ OpenVPN removed.${C_RESET}"
    press_enter
}

openvpn_menu() {
    while true; do
        clear; show_banner
        menu_section "OPENVPN" "$C_TITLE"
        echo
        local _ovpn_conf_dir; _ovpn_conf_dir=$(_fm_openvpn_conf_dir)
        if [[ -f "$_ovpn_conf_dir/server.conf" ]]; then
            local pt proto ml unit status_str web_str extra_str
            pt=$(grep '^port ' "$_ovpn_conf_dir/server.conf" | awk '{print $2}')
            proto=$(grep '^proto ' "$_ovpn_conf_dir/server.conf" | awk '{print $2}')
            grep -q '^duplicate-cn' "$_ovpn_conf_dir/server.conf" && ml="${C_GREEN}Allowed${C_RESET}" || ml="${C_RED}Blocked${C_RESET}"
            unit=$(_fm_openvpn_unit_for server)
            systemctl is-active --quiet "$unit" 2>/dev/null && status_str="${C_GREEN}Active${C_RESET}" || status_str="${C_RED}Inactive${C_RESET}"
            systemctl is-active --quiet firewallfalcon-ovpnweb 2>/dev/null && web_str="${C_GREEN}Enabled${C_RESET}" || web_str="${C_RED}Disabled${C_RESET}"

            extra_str=""
            local inst ex_pt ex_proto
            for inst in $(_fm_openvpn_list_extra_instances); do
                ex_pt=$(grep '^port ' "$_ovpn_conf_dir/${inst}.conf" | awk '{print $2}')
                ex_proto=$(grep '^proto ' "$_ovpn_conf_dir/${inst}.conf" | awk '{print $2}')
                extra_str="${extra_str}, ${ex_pt}/${ex_proto}"
            done
            extra_str="${extra_str#, }"

            local aup_str
            _fm_openvpn_authuserpass_active && aup_str="${C_GREEN}Required${C_RESET}" || aup_str="${C_RED}Not required${C_RESET}"

            echo -e "  ${C_CYAN}Status:${C_RESET} ${status_str}   ${C_CYAN}Port:${C_RESET} ${C_GREEN}${pt}/${proto}${C_RESET}   ${C_CYAN}Extra Ports:${C_RESET} ${C_GREEN}${extra_str:-none}${C_RESET}"
            echo -e "  ${C_CYAN}Multi-Login:${C_RESET} ${ml}   ${C_CYAN}Web Link:${C_RESET} ${web_str}   ${C_CYAN}Username/Password:${C_RESET} ${aup_str}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Create New Client (.ovpn)"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Change Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Toggle Multi-Login"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Add a Port (choose TCP/UDP)"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Remove a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "Manage Custom DNS Hosts"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "Toggle Web Download Link"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[8]" "Toggle Username/Password Requirement"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[9]" "Uninstall OpenVPN"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_openvpn_new_client ;;
                2) _fm_openvpn_change_port ;;
                3) _fm_openvpn_toggle_multilogin ;;
                4) _fm_openvpn_add_port ;;
                5) _fm_openvpn_remove_port ;;
                6) _fm_openvpn_hosts_menu ;;
                7) _fm_openvpn_toggle_web ;;
                8) _fm_openvpn_toggle_authuserpass ;;
                9) _fm_openvpn_uninstall; return ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            echo -e "  ${C_YELLOW}OpenVPN is not installed.${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install OpenVPN"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_openvpn_install ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# --- 5. SOCKS / Websocket Proxy ----------------------------------------
# ss only reports the process name ("python3"), which every one of our
# python-based helpers shares (socks proxy, ws proxy, ovpn web server) —
# so port-name grepping is ambiguous here. Resolve the actual PID of the
# systemd unit first and match sockets owned by it.
_fm_unit_bound_ports() {
    local unit="$1"
    local pid; pid=$(systemctl show -p MainPID --value "$unit" 2>/dev/null)
    [[ -z "$pid" || "$pid" == "0" ]] && return
    ss -tlnp 2>/dev/null | grep -F "pid=${pid}," | awk '{print $4}' | awk -F: '{print $NF}' | sort -un | xargs
}

_fm_write_socksproxy_script() {
    {
    printf '%s\n' "#!/usr/bin/env python3"
    printf '%s\n' "$SOCKS_PROXY_SCRIPT_MARKER"
    } > "$SOCKS_PROXY_SCRIPT"
    cat >> "$SOCKS_PROXY_SCRIPT" <<'PYEOF'
# encoding: utf-8
#
# HTTP-Injector-style CONNECT proxy. If the client's first bytes look like
# an HTTP request, honors X-Real-Host/X-Split headers (falling back to
# this port's own default backend). A pure SSH/SSL client (no payload at
# all) is connected straight through to the default backend instead. The
# HTTP response code is configurable so the same script serves both a
# plain SOCKS-style proxy (200) and a websocket-upgrade proxy (101).
#
# Each listening port can have its OWN backend: argv[1] is a
# space-separated list of "port@host:port" entries.
import socket, threading, select, sys, os, errno

# Real client IP map. This proxy opens its OWN connection to the backend
# (sshd), so sshd only ever sees 127.0.0.1 and `who` reports that as the
# user's address — the real one is known HERE and nowhere else. Each live
# connection publishes it as a file named after the source port of the
# proxy->backend socket, which is exactly the peer port sshd sees, so the
# panel can join the two. tmpfs, wiped on startup: a port number is only
# meaningful while the connection using it is alive, and a crash must not
# leave a stale port pointing at the wrong customer.
REALIP_DIR = '/run/dahoom-realip'


def _realip_init():
    try:
        os.makedirs(REALIP_DIR, exist_ok=True)
        os.chmod(REALIP_DIR, 0o755)
        for name in os.listdir(REALIP_DIR):
            try:
                os.remove(os.path.join(REALIP_DIR, name))
            except OSError:
                pass
    except OSError:
        pass


IP = '0.0.0.0'
ENTRIES = []
for _tok in sys.argv[1].split():
    try:
        _port_str, _backend = _tok.split('@', 1)
        ENTRIES.append((int(_port_str), _backend))
    except Exception:
        pass
if not ENTRIES:
    ENTRIES = [(80, '127.0.0.1:22')]
RESP_CODE = sys.argv[2] if len(sys.argv) > 2 else '200'
BUFLEN = 8196 * 8
TIMEOUT = 60
RESPONSE = ("HTTP/1.1 " + RESP_CODE + " <font color=\"null\"></font>\r\n\r\n").encode()


class Server(threading.Thread):
    def __init__(self, host, port, default_host):
        threading.Thread.__init__(self)
        self.running = False
        self.host = host
        self.port = port
        self.default_host = default_host
        self.threads = []
        self.threadsLock = threading.Lock()

    def run(self):
        self.soc = socket.socket(socket.AF_INET)
        self.soc.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.soc.settimeout(2)
        self.soc.bind((self.host, self.port))
        self.soc.listen(0)
        self.running = True
        try:
            while self.running:
                try:
                    c, addr = self.soc.accept()
                    c.setblocking(1)
                except socket.timeout:
                    continue
                conn = ConnectionHandler(c, self, addr)
                conn.start()
                self.addConn(conn)
        finally:
            self.running = False
            self.soc.close()

    def addConn(self, conn):
        try:
            self.threadsLock.acquire()
            if self.running:
                self.threads.append(conn)
        finally:
            self.threadsLock.release()

    def removeConn(self, conn):
        try:
            self.threadsLock.acquire()
            self.threads.remove(conn)
        finally:
            self.threadsLock.release()


class ConnectionHandler(threading.Thread):
    def __init__(self, socClient, server, addr):
        threading.Thread.__init__(self)
        self.clientClosed = False
        self.targetClosed = True
        self.client = socClient
        self.client_buffer = b''
        self.server = server
        # Was discarded before this — the one place the customer's real
        # address exists at all.
        self.client_addr = addr
        self.realip_file = None

    def publish_realip(self):
        """Records real-client-ip under the source port this proxy uses
        toward the backend, so the panel can turn sshd's 127.0.0.1 back
        into the address the customer actually connected from."""
        try:
            ip = self.client_addr[0]
            port = self.target.getsockname()[1]
        except Exception:
            return
        if not ip:
            return
        path = os.path.join(REALIP_DIR, str(port))
        try:
            with open(path, 'w') as f:
                f.write(ip)
            self.realip_file = path
        except OSError:
            self.realip_file = None

    def drop_realip(self):
        if not self.realip_file:
            return
        try:
            os.remove(self.realip_file)
        except OSError as e:
            if e.errno != errno.ENOENT:
                pass
        self.realip_file = None

    def close(self):
        self.drop_realip()
        try:
            if not self.clientClosed:
                self.client.shutdown(socket.SHUT_RDWR)
                self.client.close()
        except Exception:
            pass
        finally:
            self.clientClosed = True
        try:
            if not self.targetClosed:
                self.target.shutdown(socket.SHUT_RDWR)
                self.target.close()
        except Exception:
            pass
        finally:
            self.targetClosed = True

    def isHttpRequest(self, buf):
        try:
            line = buf.split(b'\r\n', 1)[0]
            method, _, ver = line.rpartition(b' ')
            return bool(method) and ver.startswith(b'HTTP/')
        except Exception:
            return False

    def run(self):
        try:
            self.client.settimeout(3)
            try:
                self.client_buffer = self.client.recv(BUFLEN)
            except socket.timeout:
                self.client_buffer = b''
            self.client.settimeout(None)

            if not (self.client_buffer and self.isHttpRequest(self.client_buffer)):
                self.method_DIRECT(self.server.default_host)
                return

            hostPort = self.findHeader(self.client_buffer, 'X-Real-Host') or self.server.default_host
            split = self.findHeader(self.client_buffer, 'X-Split')
            if split:
                self.client.recv(BUFLEN)
            self.method_CONNECT(hostPort)
        except Exception:
            pass
        finally:
            self.close()
            self.server.removeConn(self)

    def findHeader(self, head, header):
        head = head.decode('iso-8859-1', 'ignore')
        aux = head.find(header + ': ')
        if aux == -1:
            return ''
        aux = head.find(':', aux)
        head = head[aux + 2:]
        aux = head.find('\r\n')
        if aux == -1:
            return ''
        return head[:aux]

    def connect_target(self, host):
        i = host.find(':')
        if i != -1:
            port = int(host[i + 1:])
            host = host[:i]
        else:
            port = 22
        (soc_family, soc_type, proto, _, address) = socket.getaddrinfo(host, port)[0]
        self.target = socket.socket(soc_family, soc_type, proto)
        self.targetClosed = False
        self.target.connect(address)
        self.publish_realip()

    def method_CONNECT(self, path):
        self.connect_target(path)
        self.client.sendall(RESPONSE)
        self.client_buffer = b''
        self.doCONNECT()

    def method_DIRECT(self, path):
        self.connect_target(path)
        if self.client_buffer:
            self.target.sendall(self.client_buffer)
        self.client_buffer = b''
        self.doCONNECT()

    def doCONNECT(self):
        socs = [self.client, self.target]
        count = 0
        error = False
        while True:
            count += 1
            (recv, _, err) = select.select(socs, [], socs, 3)
            if err:
                error = True
            if recv:
                for in_ in recv:
                    try:
                        data = in_.recv(BUFLEN)
                        if data:
                            if in_ is self.target:
                                self.client.send(data)
                            else:
                                while data:
                                    byte = self.target.send(data)
                                    data = data[byte:]
                            count = 0
                        else:
                            break
                    except Exception:
                        error = True
                        break
            if count == TIMEOUT:
                error = True
            if error:
                break


if __name__ == '__main__':
    _realip_init()
    servers = [Server(IP, p, h) for p, h in ENTRIES]
    for s in servers:
        s.start()
    for s in servers:
        s.join()
PYEOF
    chmod +x "$SOCKS_PROXY_SCRIPT"
}

# $SOCKS_MAP_FILE / $WS_MAP_FILE hold one "<port> <backend>" line per
# listening port — each port can point at a different backend.
_fm_socks_write_service() {
    local map="$1" execargs="" p b
    while read -r p b; do
        [[ -z "$p" ]] && continue
        execargs="${execargs} ${p}@${b}"
    done <<< "$map"
    execargs="${execargs# }"
    cat > "$SOCKS_PROXY_SERVICE" <<EOF
[Unit]
Description=DAHOOM SOCKS Proxy
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 $SOCKS_PROXY_SCRIPT "${execargs}"
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload
}

_fm_socks_restart_and_report() {
    local expect_ports="$1"
    systemctl restart firewallfalcon-socksproxy
    sleep 1
    if ! systemctl is-active --quiet firewallfalcon-socksproxy; then
        echo -e "\n${C_RED}❌ Failed to start. Last log lines:${C_RESET}"
        journalctl -u firewallfalcon-socksproxy -n 15 --no-pager 2>/dev/null
        return 1
    fi
    local bound; bound=$(_fm_unit_bound_ports firewallfalcon-socksproxy)
    local expected_sorted; expected_sorted=$(echo "$expect_ports" | xargs -n1 | sort -un | xargs)
    if [[ "$bound" == "$expected_sorted" ]]; then
        echo -e "\n${C_GREEN}✅ SOCKS Proxy confirmed listening on: ${bound}${C_RESET}"
    else
        echo -e "\n${C_YELLOW}⚠️ SOCKS Proxy active, but is actually bound to: ${bound:-unknown} (expected ${expected_sorted}).${C_RESET}"
    fi
}

_fm_socks_enable() {
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    read -r -p "👉 Public port for the SOCKS proxy: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    if ! systemctl is-active --quiet firewallfalcon-socksproxy 2>/dev/null; then
        check_and_free_ports "$pt" || { press_enter; return; }
    fi
    _fm_write_socksproxy_script
    mkdir -p "$CONN_MODES_DIR"
    echo "$pt $backend" > "$SOCKS_MAP_FILE"
    _fm_socks_write_service "$pt $backend"
    check_and_open_firewall_port "$pt" tcp
    systemctl enable firewallfalcon-socksproxy >/dev/null 2>&1
    _fm_socks_restart_and_report "$pt"
    press_enter
}

_fm_socks_add_port() {
    if ! systemctl is-active --quiet firewallfalcon-socksproxy 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ SOCKS Proxy isn't enabled yet — use \"Enable/Reconfigure\" first.${C_RESET}"
        press_enter; return
    fi
    read -r -p "👉 Port to add: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    if grep -qE "^${pt} " "$SOCKS_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ Already listening on that port.${C_RESET}"; press_enter; return
    fi
    check_and_free_ports "$pt" || { press_enter; return; }
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    echo "$pt $backend" >> "$SOCKS_MAP_FILE"
    _fm_socks_write_service "$(cat "$SOCKS_MAP_FILE")"
    check_and_open_firewall_port "$pt" tcp
    _fm_socks_restart_and_report "$(awk '{print $1}' "$SOCKS_MAP_FILE" | xargs)"
    press_enter
}

_fm_socks_remove_port() {
    read -r -p "👉 Port to remove: " pt
    if ! grep -qE "^${pt} " "$SOCKS_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ Not listening on that port.${C_RESET}"; press_enter; return
    fi
    grep -vE "^${pt} " "$SOCKS_MAP_FILE" > "${SOCKS_MAP_FILE}.tmp" 2>/dev/null
    mv "${SOCKS_MAP_FILE}.tmp" "$SOCKS_MAP_FILE"
    if [[ ! -s "$SOCKS_MAP_FILE" ]]; then
        echo -e "${C_YELLOW}⚠️ That would leave SOCKS Proxy with no ports — disabling it entirely instead.${C_RESET}"
        _fm_socks_disable
        return
    fi
    _fm_socks_write_service "$(cat "$SOCKS_MAP_FILE")"
    _fm_socks_restart_and_report "$(awk '{print $1}' "$SOCKS_MAP_FILE" | xargs)"
    press_enter
}

_fm_socks_change_port_backend() {
    read -r -p "👉 Which port do you want to change the backend for?: " pt
    if ! grep -qE "^${pt} " "$SOCKS_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ Not listening on that port.${C_RESET}"; press_enter; return
    fi
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    grep -vE "^${pt} " "$SOCKS_MAP_FILE" > "${SOCKS_MAP_FILE}.tmp"
    echo "$pt $backend" >> "${SOCKS_MAP_FILE}.tmp"
    mv "${SOCKS_MAP_FILE}.tmp" "$SOCKS_MAP_FILE"
    _fm_socks_write_service "$(cat "$SOCKS_MAP_FILE")"
    _fm_socks_restart_and_report "$(awk '{print $1}' "$SOCKS_MAP_FILE" | xargs)"
    press_enter
}

_fm_socks_disable() {
    systemctl stop firewallfalcon-socksproxy 2>/dev/null
    systemctl disable firewallfalcon-socksproxy 2>/dev/null
    rm -f "$SOCKS_PROXY_SERVICE" "$SOCKS_MAP_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}✅ SOCKS Proxy disabled.${C_RESET}"
    press_enter
}

_fm_ws_write_service() {
    local map="$1" execargs="" p b
    while read -r p b; do
        [[ -z "$p" ]] && continue
        execargs="${execargs} ${p}@${b}"
    done <<< "$map"
    execargs="${execargs# }"
    cat > "$WS_PROXY_SERVICE" <<EOF
[Unit]
Description=DAHOOM Websocket Proxy
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 $SOCKS_PROXY_SCRIPT "${execargs}" 101
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload
}

_fm_ws_restart_and_report() {
