}

_fm_ws_remove_port() {
    read -r -p "👉 Port to remove: " pt
    if ! grep -qE "^${pt} " "$WS_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ Not listening on that port.${C_RESET}"; press_enter; return
    fi
    grep -vE "^${pt} " "$WS_MAP_FILE" > "${WS_MAP_FILE}.tmp" 2>/dev/null
    mv "${WS_MAP_FILE}.tmp" "$WS_MAP_FILE"
    if [[ ! -s "$WS_MAP_FILE" ]]; then
        echo -e "${C_YELLOW}⚠️ That would leave Websocket Proxy with no ports — disabling it entirely instead.${C_RESET}"
        _fm_ws_disable
        return
    fi
    _fm_ws_write_service "$(cat "$WS_MAP_FILE")"
    _fm_ws_restart_and_report "$(awk '{print $1}' "$WS_MAP_FILE" | xargs)"
    press_enter
}

_fm_ws_change_port_backend() {
    read -r -p "👉 Which port do you want to change the backend for?: " pt
    if ! grep -qE "^${pt} " "$WS_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ Not listening on that port.${C_RESET}"; press_enter; return
    fi
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    grep -vE "^${pt} " "$WS_MAP_FILE" > "${WS_MAP_FILE}.tmp"
    echo "$pt $backend" >> "${WS_MAP_FILE}.tmp"
    mv "${WS_MAP_FILE}.tmp" "$WS_MAP_FILE"
    _fm_ws_write_service "$(cat "$WS_MAP_FILE")"
    _fm_ws_restart_and_report "$(awk '{print $1}' "$WS_MAP_FILE" | xargs)"
    press_enter
}

_fm_ws_disable() {
    systemctl stop firewallfalcon-wsproxy 2>/dev/null
    systemctl disable firewallfalcon-wsproxy 2>/dev/null
    rm -f "$WS_PROXY_SERVICE" "$WS_MAP_FILE"
    systemctl daemon-reload
    echo -e "${C_GREEN}✅ Websocket Proxy disabled.${C_RESET}"
    press_enter
}

# Pretty "port→backend, port→backend" summary for the status screen.
# NOTE: "< file 2>/dev/null" does NOT suppress a missing-file error — bash
# opens the redirects left to right, so the failed "<" is reported before
# "2>/dev/null" ever takes effect. Guard existence first instead.
_fm_socks_map_summary() {
    local file="$1" out="" p b
    [[ -f "$file" ]] || { echo ""; return; }
    while read -r p b; do
        [[ -z "$p" ]] && continue
        out="${out}, ${p}→${b}"
    done < "$file"
    echo "${out#, }"
}

socks_proxy_menu() {
    while true; do
        clear; show_banner
        menu_section "SOCKS / WEBSOCKET PROXY" "$C_TITLE"
        echo
        local socks_active=0 ws_active=0 s_map w_map s_status_str w_status_str
        systemctl is-active --quiet firewallfalcon-socksproxy 2>/dev/null && socks_active=1
        systemctl is-active --quiet firewallfalcon-wsproxy 2>/dev/null && ws_active=1
        s_map=$(_fm_socks_map_summary "$SOCKS_MAP_FILE")
        w_map=$(_fm_socks_map_summary "$WS_MAP_FILE")
        [[ $socks_active == 1 ]] && s_status_str="${C_GREEN}Active${C_RESET}" || s_status_str="${C_RED}Inactive${C_RESET}"
        [[ $ws_active == 1 ]] && w_status_str="${C_GREEN}Active${C_RESET}" || w_status_str="${C_RED}Inactive${C_RESET}"
        echo -e "  ${C_CYAN}SOCKS Proxy:${C_RESET} $s_status_str   ${C_CYAN}${s_map:-no ports}${C_RESET}"
        echo -e "  ${C_CYAN}Websocket:${C_RESET}   $w_status_str   ${C_CYAN}${w_map:-no ports}${C_RESET}"
        echo

        # Only show Enable when off, and only show Add/Remove/Change/Disable
        # once actually on — instead of listing all of them all the time
        # regardless of state (which is what made "Enable"/"Disable" read as
        # redundant clutter once you're already managing ports via Add/Remove).
        local -a labels=() funcs=()
        if [[ $socks_active == 1 ]]; then
            labels+=("Add a Port (SOCKS)"); funcs+=(_fm_socks_add_port)
            labels+=("Remove a Port (SOCKS)"); funcs+=(_fm_socks_remove_port)
            labels+=("Change Backend for a Port (SOCKS)"); funcs+=(_fm_socks_change_port_backend)
            labels+=("Disable SOCKS Proxy"); funcs+=(_fm_socks_disable)
        else
            labels+=("Enable SOCKS Proxy"); funcs+=(_fm_socks_enable)
        fi
        if [[ $ws_active == 1 ]]; then
            labels+=("Add a Port (Websocket)"); funcs+=(_fm_ws_add_port)
            labels+=("Remove a Port (Websocket)"); funcs+=(_fm_ws_remove_port)
            labels+=("Change Backend for a Port (Websocket)"); funcs+=(_fm_ws_change_port_backend)
            labels+=("Disable Websocket Proxy"); funcs+=(_fm_ws_disable)
        else
            labels+=("Enable Websocket Proxy"); funcs+=(_fm_ws_enable)
        fi

        local i
        for ((i = 0; i < ${#labels[@]}; i++)); do
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[$((i + 1))]" "${labels[$i]}"
        done
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
        if [[ "$op" == "0" ]]; then
            return
        elif [[ "$op" =~ ^[0-9]+$ ]] && (( op >= 1 && op <= ${#labels[@]} )); then
            "${funcs[$((op - 1))]}"
        else
            invalid_option
        fi
    done
}

# --- 6. SSL Tunnel (stunnel) --------------------------------------------
# One [service] block per port, each with its OWN backend — read from
# $STUNNEL_MAP_FILE ("<port> <backend>" per line), same design as the
# SOCKS/Websocket proxies.
_fm_stunnel_write_conf() {
    local map="$1" p b
    {
        echo "pid = /run/stunnel4.pid"
        echo "cert = /etc/stunnel/stunnel.pem"
        echo "client = no"
        echo "socket = a:SO_REUSEADDR=1"
        echo "socket = l:TCP_NODELAY=1"
        echo "socket = r:TCP_NODELAY=1"
        while read -r p b; do
            [[ -z "$p" ]] && continue
            printf '\n[dahoom-ssl-%s]\nconnect = %s\naccept = %s\n' "$p" "$b" "$p"
        done <<< "$map"
    } > /etc/stunnel/stunnel.conf
}

_fm_stunnel_restart_and_report() {
    local expect_ports="$1"
    systemctl restart stunnel4
    sleep 1
    if ! { systemctl is-active --quiet stunnel4 2>/dev/null || pgrep -x stunnel4 >/dev/null 2>&1; }; then
        echo -e "\n${C_RED}❌ Failed to start. Last log lines:${C_RESET}"
        journalctl -u stunnel4 -n 15 --no-pager 2>/dev/null
        return 1
    fi
    local bound; bound=$(ss -tlnp 2>/dev/null | grep stunnel | awk '{print $4}' | awk -F: '{print $NF}' | sort -un | xargs)
    local expected_sorted; expected_sorted=$(echo "$expect_ports" | xargs -n1 | sort -un | xargs)
    if [[ "$bound" == "$expected_sorted" ]]; then
        echo -e "\n${C_GREEN}✅ SSL Tunnel confirmed listening on: ${bound}${C_RESET}"
    else
        echo -e "\n${C_YELLOW}⚠️ SSL Tunnel active, but is actually bound to: ${bound:-unknown} (expected ${expected_sorted}).${C_RESET}"
    fi
}

_fm_stunnel_install() {
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    read -r -p "👉 Public port for SSL Tunnel: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    check_and_free_ports "$pt" || { press_enter; return; }

    echo -e "\n${C_BLUE}📦 Installing stunnel...${C_RESET}"
    ff_pkg_install stunnel4 || { echo -e "${C_RED}❌ Failed to install stunnel.${C_RESET}"; press_enter; return; }

    mkdir -p /etc/stunnel "$CONN_MODES_DIR"
    echo "$pt $backend" > "$STUNNEL_MAP_FILE"
    _fm_stunnel_write_conf "$pt $backend"

    if [[ ! -f /etc/stunnel/stunnel.pem ]]; then
        echo -e "${C_BLUE}🔏 Generating a self-signed TLS certificate...${C_RESET}"
        openssl req -new -x509 -days 3650 -nodes \
            -subj "/CN=$(hostname -f 2>/dev/null || echo dahoom)" \
            -out /etc/stunnel/stunnel.pem -keyout /etc/stunnel/stunnel.pem 2>/dev/null
    fi

    if grep -q '^ENABLED=' /etc/default/stunnel4 2>/dev/null; then
        sed -i 's/ENABLED=0/ENABLED=1/' /etc/default/stunnel4
    else
        echo 'ENABLED=1' >> /etc/default/stunnel4
    fi
    systemctl enable stunnel4 >/dev/null 2>&1
    check_and_open_firewall_port "$pt" tcp
    _fm_stunnel_restart_and_report "$pt"
    press_enter
}

_fm_stunnel_add_port() {
    read -r -p "👉 Port to add: " pt
    if [[ ! "$pt" =~ ^[0-9]+$ ]]; then echo -e "${C_RED}❌ Invalid port.${C_RESET}"; press_enter; return; fi
    if grep -qE "^${pt} " "$STUNNEL_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ SSL Tunnel is already listening on that port.${C_RESET}"; press_enter; return
    fi
    check_and_free_ports "$pt" || { press_enter; return; }
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    echo "$pt $backend" >> "$STUNNEL_MAP_FILE"
    _fm_stunnel_write_conf "$(cat "$STUNNEL_MAP_FILE")"
    check_and_open_firewall_port "$pt" tcp
    _fm_stunnel_restart_and_report "$(awk '{print $1}' "$STUNNEL_MAP_FILE" | xargs)"
    press_enter
}

_fm_stunnel_remove_port() {
    read -r -p "👉 Port to remove: " pt
    if ! grep -qE "^${pt} " "$STUNNEL_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ SSL Tunnel isn't listening on that port.${C_RESET}"; press_enter; return
    fi
    grep -vE "^${pt} " "$STUNNEL_MAP_FILE" > "${STUNNEL_MAP_FILE}.tmp" 2>/dev/null
    mv "${STUNNEL_MAP_FILE}.tmp" "$STUNNEL_MAP_FILE"
    if [[ ! -s "$STUNNEL_MAP_FILE" ]]; then
        echo -e "${C_YELLOW}⚠️ That would leave SSL Tunnel with no ports — removing it entirely instead.${C_RESET}"
        _fm_stunnel_uninstall
        return
    fi
    _fm_stunnel_write_conf "$(cat "$STUNNEL_MAP_FILE")"
    _fm_stunnel_restart_and_report "$(awk '{print $1}' "$STUNNEL_MAP_FILE" | xargs)"
    press_enter
}

_fm_stunnel_change_port_backend() {
    read -r -p "👉 Which port do you want to change the backend for?: " pt
    if ! grep -qE "^${pt} " "$STUNNEL_MAP_FILE" 2>/dev/null; then
        echo -e "${C_YELLOW}⚠️ SSL Tunnel isn't listening on that port.${C_RESET}"; press_enter; return
    fi
    local backend; backend=$(_fm_socks_backend_choice) || { press_enter; return; }
    grep -vE "^${pt} " "$STUNNEL_MAP_FILE" > "${STUNNEL_MAP_FILE}.tmp"
    echo "$pt $backend" >> "${STUNNEL_MAP_FILE}.tmp"
    mv "${STUNNEL_MAP_FILE}.tmp" "$STUNNEL_MAP_FILE"
    _fm_stunnel_write_conf "$(cat "$STUNNEL_MAP_FILE")"
    _fm_stunnel_restart_and_report "$(awk '{print $1}' "$STUNNEL_MAP_FILE" | xargs)"
    press_enter
}

_fm_stunnel_uninstall() {
    read -r -p "👉 Are you sure you want to remove SSL Tunnel? (y/n): " c
    [[ "$c" == "y" || "$c" == "Y" ]] || { press_enter; return; }
    systemctl stop stunnel4 2>/dev/null
    systemctl disable stunnel4 2>/dev/null
    ff_pkg_purge stunnel4 2>/dev/null
    rm -f /etc/stunnel/stunnel.conf /etc/stunnel/stunnel.pem /etc/default/stunnel4 "$STUNNEL_MAP_FILE"
    echo -e "${C_GREEN}✅ SSL Tunnel removed.${C_RESET}"
    press_enter
}

ssl_tunnel_menu() {
    while true; do
        clear; show_banner
        menu_section "SSL TUNNEL (stunnel)" "$C_TITLE"
        echo
        if [[ -f /etc/stunnel/stunnel.conf ]]; then
            local status_str map_summary
            systemctl is-active --quiet stunnel4 2>/dev/null && status_str="${C_GREEN}Active${C_RESET}" || status_str="${C_RED}Inactive${C_RESET}"
            map_summary=$(_fm_socks_map_summary "$STUNNEL_MAP_FILE")
            echo -e "  ${C_CYAN}Status:${C_RESET} ${status_str}   ${C_CYAN}${map_summary:-no ports}${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Add a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Remove a Port"
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Change Backend for a Port"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[4]" "Uninstall SSL Tunnel"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_stunnel_add_port ;;
                2) _fm_stunnel_remove_port ;;
                3) _fm_stunnel_change_port_backend ;;
                4) _fm_stunnel_uninstall; return ;;
                0) return ;;
                *) invalid_option ;;
            esac
        else
            echo -e "  ${C_YELLOW}SSL Tunnel is not installed.${C_RESET}"
            echo
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install SSL Tunnel"
            printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
            echo
            if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
            case "$op" in
                1) _fm_stunnel_install ;;
                0) return ;;
                *) invalid_option ;;
            esac
        fi
    done
}

# --- 7. SlowDNS (DNSTT) ---------------------------------------------------
# Port of SSHPLUS's own "MENU SLOWDNS MANAGER V3.0" (see the _fm_slowdns_*
# helpers above for the underlying mechanism). Two differences from
# SSHPLUS's original 12-option list, both by explicit request: added a
# V2Ray backend variant (matching the one the old DNSTT feature already
# offered), and dropped "Remove Script" — it had no separate target in
# DAHOOM anyway (no standalone launcher binary the way SSHPLUS's
# /bin/slowdns is; this whole thing lives in menu.sh), so it was just
# dead weight duplicating "Remove SlowDNS".
slowdns_menu() {
    while true; do
        clear; show_banner
        menu_section "SLOWDNS (DNSTT)" "$C_TITLE"
        echo
        if _fm_slowdns_any_installed; then
            echo -e "  ${C_CYAN}Installed instances${C_RESET} ${C_DIM}(each on its own port — any number can run together)${C_RESET}"
            _fm_slowdns_show_all_info
        else
            echo -e "  ${C_YELLOW}SlowDNS is not installed.${C_RESET}"
        fi
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Install SlowDNS SSH"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Install SlowDNS SSL"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Install SlowDNS DROP"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Install SlowDNS SOCKS"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Install SlowDNS OVPN"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "Install SlowDNS V2Ray"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "View Info"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[8]" "Start an Instance"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[9]" "Restart an Instance"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[10]" "Stop an Instance"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[11]" "Remove an Instance"
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" op; then return; fi
        case "$op" in
            1) _fm_slowdns_install_ssh ;;
            2) _fm_slowdns_install_ssl ;;
            3) _fm_slowdns_install_drop ;;
            4) _fm_slowdns_install_socks ;;
            5) _fm_slowdns_install_ovpn ;;
            6) _fm_slowdns_install_v2ray ;;
            7) clear; show_banner; _fm_slowdns_show_all_info; press_enter ;;
            8) _fm_slowdns_start_picked ;;
            9) _fm_slowdns_restart_picked ;;
            10) _fm_slowdns_stop_picked ;;
            11) _fm_slowdns_remove_picked ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

# --- Hub: Connection Modes ----------------------------------------------
connection_modes_menu() {
    while true; do
        clear; show_banner
        menu_section "CONNECTION MODES" "$C_TITLE"
        echo
        local st_ssh st_squid st_drop st_ovpn st_socks st_ssl st_dns
        st_ssh="${C_GREEN}◉${C_RESET}"
        systemctl is-active --quiet firewallfalcon-sqfilter 2>/dev/null && st_squid="${C_GREEN}◉${C_RESET}" || st_squid="${C_RED}○${C_RESET}"
        systemctl is-active --quiet "$_fm_dropbear_unit_name" 2>/dev/null && st_drop="${C_GREEN}◉${C_RESET}" || st_drop="${C_RED}○${C_RESET}"
        [[ -f "$(_fm_openvpn_conf_dir)/server.conf" ]] && st_ovpn="${C_GREEN}◉${C_RESET}" || st_ovpn="${C_RED}○${C_RESET}"
        if systemctl is-active --quiet firewallfalcon-socksproxy 2>/dev/null || systemctl is-active --quiet firewallfalcon-wsproxy 2>/dev/null; then
            st_socks="${C_GREEN}◉${C_RESET}"
        else
            st_socks="${C_RED}○${C_RESET}"
        fi
        [[ -f /etc/stunnel/stunnel.conf ]] && st_ssl="${C_GREEN}◉${C_RESET}" || st_ssl="${C_RED}○${C_RESET}"
        _fm_slowdns_any_active && st_dns="${C_GREEN}◉${C_RESET}" || st_dns="${C_RED}○${C_RESET}"

        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[1]" "OpenSSH" "$st_ssh"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[2]" "Squid Proxy (DPI-Bypass)" "$st_squid"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[3]" "Dropbear" "$st_drop"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[4]" "OpenVPN" "$st_ovpn"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[5]" "SOCKS / Websocket Proxy" "$st_socks"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[6]" "SSL Tunnel (stunnel)" "$st_ssl"
        printf "  ${C_CHOICE}%-4s${C_RESET} %-30s %s\n" "[7]" "SlowDNS (DNSTT)" "$st_dns"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" cm; then return; fi
        case "$cm" in
            1) connection_openssh_menu ;;
            2) squid_proxy_menu ;;
            3) dropbear_menu ;;
            4) openvpn_menu ;;
            5) socks_proxy_menu ;;
            6) ssl_tunnel_menu ;;
            7) slowdns_menu ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

auto_healing_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "AUTO-HEALING SERVICE GUARD" "$C_TITLE"
        echo
        local status="Disabled"
        if (crontab -l 2>/dev/null | grep -q "_run_auto_healing"); then
            status="${C_GREEN}Active (Automated Background Self-Healing)${C_RESET}"
        else
            status="${C_RED}Disabled${C_RESET}"
        fi

        echo -e "  ${C_CYAN}Guard Status:${C_RESET} $status"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Enable Auto-Healing Guard & Run Instant Health Check"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Disable Auto-Healing Guard"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" ah_act; then
            return
        fi
        case "$ah_act" in
            1)
                if _fm_ensure_crontab_available; then
                    (crontab -l 2>/dev/null | grep -v "_run_auto_healing") | crontab -
                    (crontab -l 2>/dev/null; echo "*/2 * * * * bash /usr/local/bin/dahoom _run_auto_healing &>/dev/null") | crontab -
                    if crontab -l 2>/dev/null | grep -q "_run_auto_healing"; then
                        echo -e "\n${C_GREEN}✅ Automated Auto-Healing Guard enabled (runs every 2 mins).${C_RESET}"
                    else
                        echo -e "\n${C_RED}❌ Could not enable the guard — the crontab entry failed to save.${C_RESET}"
                    fi
                else
                    echo -e "\n${C_RED}❌ Could not install/find 'cron' on this system — the guard needs it to run automatically.${C_RESET}"
                fi
                echo -e "\n${C_BLUE}Running instant health check...${C_RESET}"
                run_auto_healing_check
                echo -e "${C_GREEN}✅ Health check completed.${C_RESET}"
                press_enter
                ;;
            2)
                (crontab -l 2>/dev/null | grep -v "_run_auto_healing") | crontab -
                # A health check killed mid-run (Ctrl+C, SSH drop, OOM) can
                # leave this lock file behind — with nothing left to remove
                # it, the guard would silently stop healing forever even
                # after being re-enabled. Disabling is the natural place to
                # also clear it, since the guard is fully stopped anyway.
                rm -f /tmp/.ff_auto_healing.lock 2>/dev/null
                echo -e "\n${C_GREEN}✅ Auto-Healing Guard disabled.${C_RESET}"
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

# ── VLESS / REALITY PROTOCOL MODULE ───────────────────────────────────
_ensure_v2ray_manager() {
    mkdir -p /etc/firewallfalcon/panel /usr/local/bin /etc/firewallfalcon
    _fm_panel_file v2ray_manager.py /etc/firewallfalcon/panel/v2ray_manager.py 2>/dev/null
    cp -f /etc/firewallfalcon/panel/v2ray_manager.py /usr/local/bin/v2ray_manager.py 2>/dev/null
    cp -f /etc/firewallfalcon/panel/v2ray_manager.py /etc/firewallfalcon/v2ray_manager.py 2>/dev/null
    chmod +x /etc/firewallfalcon/panel/v2ray_manager.py /usr/local/bin/v2ray_manager.py 2>/dev/null || true
}

install_vless_reality() {
    echo -e "\n${C_BLUE}Installing Xray core and configuring V2Ray services...${C_RESET}"
    mkdir -p /etc/xray /usr/local/etc/xray /var/log/xray /etc/firewallfalcon/panel /usr/local/bin 2>/dev/null
    chmod -R 777 /var/log/xray 2>/dev/null || true
    touch /var/log/xray/access.log /var/log/xray/error.log 2>/dev/null && chmod 666 /var/log/xray/*.log 2>/dev/null || true
    
    if ! command -v xray &>/dev/null; then
        bash -c "$(curl -L https://github.com/XTLS/Xray-install/raw/main/install-release.sh)" @ install -u root &>/dev/null
    fi
    _ensure_v2ray_manager
    
    # Generate authentic Xray Reality Keypair directly from installed xray binary
    if command -v xray &>/dev/null; then
        local key_out real_priv real_pub
        key_out=$(xray x25519 2>/dev/null)
        real_priv=$(echo "$key_out" | grep -iE "private *key:" | head -n1 | awk '{print $NF}' | tr -d '\r\n ')
        real_pub=$(echo "$key_out" | grep -iE "public *key:|password:" | head -n1 | awk '{print $NF}' | tr -d '\r\n ')
        if [[ -n "$real_priv" && -n "$real_pub" && ${#real_priv} -ge 43 ]]; then
            python3 -c "
import sys, json, os
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager
    inb = v2ray_manager.read_v2ray_inbounds()
    inb.setdefault('vless_reality', {})['privateKey'] = '$real_priv'
    inb['vless_reality']['publicKey'] = '$real_pub'
    v2ray_manager.write_v2ray_inbounds(inb)
except Exception:
    pass
" 2>/dev/null
        fi
    fi

    # Build and deploy configuration
    python3 -c "import sys; sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin']); import v2ray_manager; v2ray_manager.apply_xray_config_safe()" 2>/dev/null
    
    # Ensure systemd service file has correct root user and ExecStart
    cat > /etc/systemd/system/xray.service <<'EOF'
[Unit]
Description=Xray Service
Documentation=https://github.com/xtls
After=network.target nss-lookup.target

[Service]
User=root
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
NoNewPrivileges=true
ExecStart=/usr/local/bin/xray run -config /usr/local/etc/xray/config.json
Restart=on-failure
RestartSec=3s
LimitNPROC=10000
LimitNOFILE=1000000

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload &>/dev/null || true
    systemctl reset-failed xray &>/dev/null || true
    systemctl enable xray &>/dev/null || true
    systemctl restart xray 2>/dev/null || true
    sleep 1.5

    if systemctl is-active --quiet xray 2>/dev/null; then
        echo -e "${C_GREEN}✅ Xray core installed and running actively!${C_RESET}"
    else
        systemctl reset-failed xray 2>/dev/null || true
        systemctl start xray 2>/dev/null || true
        sleep 1.5
        if systemctl is-active --quiet xray 2>/dev/null; then
            echo -e "${C_GREEN}✅ Xray core started successfully!${C_RESET}"
        else
            echo -e "${C_RED}❌ Xray core failed to start. Diagnostics:${C_RESET}"
            xray -test -config /usr/local/etc/xray/config.json 2>/dev/null || xray -test -config /etc/xray/config.json 2>/dev/null || true
            journalctl -u xray -n 8 --no-pager 2>/dev/null || true
        fi
    fi
}

reinstall_vless_reality() {
    echo -e "\n${C_BLUE}Safely reinstalling & repairing Xray core binaries and configs...${C_RESET}"
    systemctl stop xray &>/dev/null || true
    systemctl reset-failed xray &>/dev/null || true
    bash -c "$(curl -L https://github.com/XTLS/Xray-install/raw/main/install-release.sh)" @ install -u root &>/dev/null
    mkdir -p /etc/xray /usr/local/etc/xray /var/log/xray 2>/dev/null
    chmod -R 777 /var/log/xray 2>/dev/null || true
    touch /var/log/xray/access.log /var/log/xray/error.log 2>/dev/null && chmod 666 /var/log/xray/*.log 2>/dev/null || true
    _ensure_v2ray_manager
    
    if command -v xray &>/dev/null; then
        local key_out real_priv real_pub
        key_out=$(xray x25519 2>/dev/null)
        real_priv=$(echo "$key_out" | grep -iE "private *key:" | head -n1 | awk '{print $NF}' | tr -d '\r\n ')
        real_pub=$(echo "$key_out" | grep -iE "public *key:|password:" | head -n1 | awk '{print $NF}' | tr -d '\r\n ')
        if [[ -n "$real_priv" && -n "$real_pub" && ${#real_priv} -ge 43 ]]; then
            python3 -c "
import sys, json, os
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager
    inb = v2ray_manager.read_v2ray_inbounds()
    inb.setdefault('vless_reality', {})['privateKey'] = '$real_priv'
    inb['vless_reality']['publicKey'] = '$real_pub'
    v2ray_manager.write_v2ray_inbounds(inb)
except Exception:
    pass
" 2>/dev/null
        fi
    fi

    python3 -c "import sys; sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin']); import v2ray_manager; v2ray_manager.apply_xray_config_safe()" 2>/dev/null
    
    cat > /etc/systemd/system/xray.service <<'EOF'
[Unit]
Description=Xray Service
Documentation=https://github.com/xtls
After=network.target nss-lookup.target

[Service]
User=root
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE
NoNewPrivileges=true
ExecStart=/usr/local/bin/xray run -config /usr/local/etc/xray/config.json
Restart=on-failure
RestartSec=3s
LimitNPROC=10000
LimitNOFILE=1000000

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload &>/dev/null || true
    systemctl reset-failed xray &>/dev/null || true
    systemctl enable xray &>/dev/null || true
    systemctl restart xray 2>/dev/null || true
    sleep 1.5

    if systemctl is-active --quiet xray 2>/dev/null; then
        echo -e "${C_GREEN}✅ Xray core reinstalled and running successfully!${C_RESET}"
    else
        systemctl reset-failed xray 2>/dev/null || true
        systemctl start xray 2>/dev/null || true
        sleep 1.5
        if systemctl is-active --quiet xray 2>/dev/null; then
            echo -e "${C_GREEN}✅ Xray core started successfully!${C_RESET}"
        else
            echo -e "${C_RED}❌ Xray service failed to start after reinstall.${C_RESET}"
            xray -test -config /usr/local/etc/xray/config.json 2>/dev/null || xray -test -config /etc/xray/config.json 2>/dev/null || true
            journalctl -u xray -n 8 --no-pager 2>/dev/null || true
        fi
    fi
}

uninstall_vless_reality() {
    local u_conf="y"
    if [[ "$UNINSTALL_MODE" != "silent" ]]; then
        echo -e "\n${C_WARN}Are you sure you want to completely uninstall Xray core? (y/n) [n]: ${C_RESET}"
        read -r -p "> " u_conf
    fi
    if [[ "${u_conf,,}" == "y" ]]; then
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "\n${C_BLUE}Stopping and removing Xray core...${C_RESET}"
        fi
        systemctl stop xray &>/dev/null || true
        systemctl disable xray &>/dev/null || true
        if command -v xray &>/dev/null; then
            bash -c "$(curl -L https://github.com/XTLS/Xray-install/raw/main/install-release.sh)" @ remove &>/dev/null || rm -f /usr/local/bin/xray
        fi
        if [[ "$UNINSTALL_MODE" != "silent" ]]; then
            echo -e "${C_GREEN}✅ Xray core uninstalled successfully.${C_RESET}"
        fi
    else
        echo -e "\n${C_YELLOW}❌ Uninstall cancelled.${C_RESET}"
    fi
}

view_xray_status_logs() {
    clear; show_banner
    echo
    menu_section "XRAY CORE STATUS & LOGS" "$C_TITLE"
    echo
    if systemctl is-active --quiet xray 2>/dev/null; then
        echo -e "  ${C_CYAN}Service Status:${C_RESET} ${C_GREEN}Active (Running)${C_RESET}"
    elif command -v xray &>/dev/null; then
        echo -e "  ${C_CYAN}Service Status:${C_RESET} ${C_YELLOW}Stopped / Inactive${C_RESET}"
    else
        echo -e "  ${C_CYAN}Service Status:${C_RESET} ${C_RED}Not Installed${C_RESET}"
    fi
    echo -e "\n${C_BLUE}--- Configuration Test ---${C_RESET}"
    if command -v xray &>/dev/null && [[ -f /etc/xray/config.json ]]; then
        xray -test -config /etc/xray/config.json 2>&1 | head -n 5
    else
        echo "Xray binary or config missing."
    fi
    echo -e "\n${C_BLUE}--- Recent Xray Journal Logs ---${C_RESET}"
    journalctl -u xray -n 12 --no-pager 2>/dev/null || echo "No journal logs available."
    echo
    press_enter
}

_select_v2ray_user_interface() {
    local title="${1:-Select V2Ray User}"
    clear; show_banner
    echo
    menu_section "$title" "$C_TITLE"
    echo
    SELECTED_V2RAY_USER=""
    _ensure_v2ray_manager
    local -a v2_users=()
    mapfile -t v2_users < <(python3 -c "
import sys
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager
    for u in v2ray_manager.read_v2ray_users():
        if u.get('username'):
            print(u['username'])
except Exception as e:
    pass
")
    
    if [ ${#v2_users[@]} -eq 0 ]; then
        echo -e "${C_YELLOW}ℹ️ No V2Ray users found in database.${C_RESET}"
        echo -e "${C_CYAN}💡 Tip: Use option [28] to import existing SSH users into V2Ray.${C_RESET}\n"
        press_enter
        SELECTED_V2RAY_USER="NO_USERS"
        return
    fi
    echo -e "Please select a V2Ray user:\n"
    for i in "${!v2_users[@]}"; do
        printf "  ${C_CHOICE}[%2d]${C_RESET} %s\n" "$((i+1))" "${v2_users[$i]}"
    done
    echo -e "\n  ${C_DANGER} [ 0]${C_RESET} Cancel"
    echo
    local choice
    while true; do
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Enter number or username (0 to cancel): "${C_RESET})" choice; then
            SELECTED_V2RAY_USER=""
            return
        fi
        choice=$(echo "$choice" | xargs 2>/dev/null || echo "$choice")
        if [[ -z "$choice" || "$choice" == "0" || "${choice,,}" == "cancel" || "${choice,,}" == "q" ]]; then
            SELECTED_V2RAY_USER=""
            return
        fi
        if [[ "$choice" =~ ^[0-9]+$ ]] && [ "$choice" -ge 1 ] && [ "$choice" -le "${#v2_users[@]}" ]; then
            SELECTED_V2RAY_USER="${v2_users[$((choice-1))]}"
            return
        else
            local found=""
            for u in "${v2_users[@]}"; do
                if [[ "$u" == "$choice" ]]; then found="$u"; break; fi
            done
            if [[ -n "$found" ]]; then
                SELECTED_V2RAY_USER="$found"
                return
            else
                echo -e "${C_RED}❌ Invalid selection. Please check and try again.${C_RESET}"
            fi
        fi
    done
}

v2ray_create_user_cli() {
    clear; show_banner
    echo
    menu_section "CREATE V2RAY USER" "$C_TITLE"
    echo
    read -p "$(echo -e "${C_PROMPT}> Username (0 to cancel): ${C_RESET}")" v_un
    v_un=$(echo "$v_un" | xargs 2>/dev/null || echo "$v_un")
    [[ -z "$v_un" || "$v_un" == "0" || "${v_un,,}" == "cancel" || "${v_un,,}" == "q" ]] && return
    
    read -p "$(echo -e "${C_PROMPT}> Duration in days [30]: ${C_RESET}")" v_days
    v_days=${v_days:-30}
    
    read -p "$(echo -e "${C_PROMPT}> Bandwidth Quota in GB (0 for unlimited) [0]: ${C_RESET}")" v_bw
    v_bw=${v_bw:-0}

    read -p "$(echo -e "${C_PROMPT}> Max Connections (Devices) [2]: ${C_RESET}")" v_conn
    v_conn=${v_conn:-2}

    echo -e "\n${C_BLUE}Creating user in V2Ray engine...${C_RESET}"
    _ensure_v2ray_manager
    python3 -c "
import sys
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager
    u = v2ray_manager.create_v2ray_user('$v_un', days=$v_days, bandwidth_gb=$v_bw, max_conn=$v_conn)
    print(f'${C_GREEN}✅ Created UUID: ${C_YELLOW}{u[\"uuid\"]}${C_RESET}')
    print(f'${C_GREEN}📡 Sub Token: ${C_YELLOW}{u[\"sub_token\"]}${C_RESET}')
except Exception as e:
    print(f'${C_RED}❌ Error creating V2Ray user: {e}${C_RESET}')
"
    echo
    press_enter
}

v2ray_list_users_cli() {
    clear; show_banner
    echo
    menu_section "V2RAY USERS LIST" "$C_TITLE"
    echo
    _ensure_v2ray_manager
    python3 -c "
import sys
sys.path.extend(['/etc/firewallfalcon/panel', '/etc/firewallfalcon', '/usr/local/bin'])
try:
    import v2ray_manager
    users = v2ray_manager.read_v2ray_users()
    print(f'Total V2Ray Users: {len(users)}\n')
    if not users:
        print('No V2Ray users registered yet. Tip: Run option [28] to import SSH users.')
    for u in users:
        st = '🟢 Active' if u.get('is_active') else '🔴 Inactive'
