        print(f\"- {u['username']:<15} | {st:<10} | Exp: {u.get('expire_date',''):<12} | BW: {bw:<10} | Protos: {','.join(u.get('protocols',[]))}\")
except Exception as e:
    print(f'${C_RED}❌ Error reading V2Ray users: {e}${C_RESET}')
"
    echo
    press_enter
}

