            _fm_bot_admin_reply_target_clear
            _fm_bot_admin_bcast_wait_set
            send_telegram_msg "📢 <b>إعلان جديد</b>%0A%0Aاكتب نص الإعلان الآن في رسالة واحدة، وسأعرضه عليك مع عدد المستلمين قبل الإرسال.%0A%0Aللإلغاء: /cancel_broadcast"
            ;;
        /cancel_broadcast|/الغاء_الاعلان)
            _fm_bot_admin_bcast_wait_clear
            rm -f "$BOT_BROADCAST_DRAFT" 2>/dev/null
            send_telegram_msg "✅ أُلغي الإعلان ولم يُرسل لأحد."
            ;;
        /reply|/رد)
            # /reply <chat_id> <text> — the explicit form. Tapping "رد"
            # under a forwarded message is the usual one.
            local rp_target rp_text
            rp_target=$(awk '{print $1}' <<< "$rest")
            rp_text="${rest#* }"
            [[ "$rp_text" == "$rest" ]] && rp_text=""
            if [[ -z "$rp_target" || -z "$rp_text" ]]; then
                send_telegram_msg "❌ الاستخدام: <code>/reply TELEGRAM_ID نص الرد</code>"
                return
            fi
            if ! _fm_bot_admin_reply_deliver "$rp_target" "$rp_text"; then
                send_telegram_msg "❌ تعذّر إرسال الرد إلى ${rp_target}."
            fi
            ;;
        /cancel_reply|/الغاء_الرد)
            _fm_bot_admin_reply_target_clear
            send_telegram_msg "✅ أُلغي وضع الرد. رسائلك التالية لن تُرسل لأحد."
            ;;
        /pending)
            local pd_lines; pd_lines=$(_fm_bot_order_list_pending)
            if [[ -z "$pd_lines" ]]; then send_telegram_msg "ℹ️ لا توجد طلبات معلّقة."; return; fi
            local pd_msg="🛒 <b>الطلبات المعلّقة</b>%0A" pd_id pd_tg pd_hwid pd_amt pd_coupon pd_status pd_ts
            # One approve/reject row per order, capped so a long backlog
            # can't build a keyboard Telegram refuses to render.
            local pd_rows="" pd_n=0
            while IFS=: read -r pd_id pd_tg pd_hwid pd_amt pd_coupon pd_status pd_ts; do
                [[ -z "$pd_id" ]] && continue
                pd_msg+="%0A#${pd_id} — ${pd_tg} — ${pd_hwid} — ${pd_amt} ريال"
                if [[ $pd_n -lt 10 ]]; then
                    [[ -n "$pd_rows" ]] && pd_rows+=","
                    pd_rows+="[{\"text\":\"✅ قبول #${pd_id}\",\"callback_data\":\"ao:${pd_id}\"},{\"text\":\"❌ رفض #${pd_id}\",\"callback_data\":\"ro:${pd_id}\"}]"
                    pd_n=$((pd_n+1))
                fi
            done <<< "$pd_lines"
            if [[ -n "$pd_rows" ]]; then
                send_telegram_msg_kb "$pd_msg" "{\"inline_keyboard\":[${pd_rows}]}"
            else
                send_telegram_msg "$pd_msg"
            fi
            ;;
        /approve) _fm_bot_admin_approve_order "$rest" ;;
        /reject)
            local rj_id rj_reason; rj_id=$(awk '{print $1}' <<< "$rest"); rj_reason="${rest#* }"
            [[ "$rj_reason" == "$rest" ]] && rj_reason=""
            _fm_bot_admin_reject_order "$rj_id" "$rj_reason"
            ;;
        /salesstats) _fm_bot_admin_stats ;;
        /npvt)
            # Answers "why did my customer get the file unchanged?"
            # without anyone having to read a log: it checks the two
            # things that can stop personalisation working, then reports
            # on every stored file that is an NPV config.
            local nv_msg="🧪 <b>فحص ملفات NPV Tunnel</b>%0A"
            if command -v python3 >/dev/null 2>&1; then
                nv_msg+="%0A✅ python3 متاح"
            else
                nv_msg+="%0A❌ python3 غير مثبّت — لا يمكن تخصيص أي ملف"
            fi
            local nv_codec nv_codec_s
            if nv_codec=$(_fm_bot_npvt_codec); then
                nv_msg+="%0A✅ مُحوِّل الآيفون (npvt) موجود"
            else
                nv_msg+="%0A❌ المُحوِّل npvt_edit.py مفقود — حدّث الأداة من القائمة"
            fi
            if nv_codec_s=$(_fm_bot_npvs_codec); then
                nv_msg+="%0A✅ مُحوِّل الأندرويد (npvs) موجود"
            else
                nv_msg+="%0A❌ المُحوِّل npvs_edit.py مفقود — حدّث الأداة من القائمة"
            fi
            # الأندرويد وحده يحتاج مكتبة الختم؛ الآيفون لا يحتاجها إطلاقًا
            if _fm_bot_npvs_crypto_ok; then
                nv_msg+="%0A✅ مكتبة cryptography مثبّتة (لازمة لملفات الأندرويد)"
            else
                nv_msg+="%0A⚠️ مكتبة cryptography غير مثبّتة — ستُثبَّت تلقائيًا عند أول ملف أندرويد"
            fi
            # nv_info starts empty: when a codec is missing it is never
            # assigned, and the branches below still read it.
            local nv_app nv_type nv_path nv_any=0 nv_info="" nv_kind nv_use
            while IFS= read -r nv_app; do
                [[ -z "$nv_app" ]] && continue
                while IFS= read -r nv_type; do
                    [[ -z "$nv_type" ]] && continue
                    nv_path=$(_fm_bot_appfile_path "$nv_app" "$nv_type")
                    if _fm_bot_npvs_is_file "$nv_path"; then
                        nv_kind="أندرويد"; nv_use="$nv_codec_s"
                    elif _fm_bot_npvt_is_file "$nv_path"; then
                        nv_kind="آيفون"; nv_use="$nv_codec"
                    else
                        continue
                    fi
                    nv_any=1
                    # ملف الأندرويد مقفول بالختم نفسه لا بحقل داخلي، فما
                    # يهمّ فيه أن يُقرأ أصلًا: ملف recipients مختوم مسبقًا
                    # لا يمكن تخصيصه لأحد.
                    if [[ "$nv_kind" == "أندرويد" ]]; then
                        nv_info=""
                        if [[ -n "$nv_use" ]] && nv_info=$(python3 "$nv_use" check "$nv_path" 2>&1) \
                           && [[ "$nv_info" == *'"editable": true'* ]]; then
                            nv_msg+="%0A✅ <b>${nv_app}</b> — ${nv_type} (أندرويد): جاهز"
                        elif [[ "$nv_info" == *'recipients'* ]]; then
                            nv_msg+="%0A❌ <b>${nv_app}</b> — ${nv_type} (أندرويد): الملف مختوم لجهاز واحد — ارفع نسخة appKey"
                        else
                            nv_msg+="%0A❌ <b>${nv_app}</b> — ${nv_type} (أندرويد): تعذّر فحصه"
                        fi
                        continue
                    fi
                    nv_info=""
                    if [[ -n "$nv_use" ]] && nv_info=$(python3 "$nv_use" check "$nv_path" 2>&1); then
                        if [[ "$nv_info" == *'"editable": true'* && "$nv_info" == *'"locked": true'* ]]; then
                            nv_msg+="%0A✅ <b>${nv_app}</b> — ${nv_type} (آيفون): جاهز (مخصّص ومقفول)"
                        elif [[ "$nv_info" == *'"locked": false'* ]]; then
                            nv_msg+="%0A⚠️ <b>${nv_app}</b> — ${nv_type} (آيفون): قفل الجهاز مطفأ داخل الملف"
                        else
                            nv_msg+="%0A⚠️ <b>${nv_app}</b> — ${nv_type} (آيفون): تنقصه الحقول المتوقّعة"
                        fi
                    else
                        nv_msg+="%0A❌ <b>${nv_app}</b> — ${nv_type} (آيفون): تعذّر فحصه"
                    fi
                done <<< "$(_fm_bot_appfile_types_list "$nv_app")"
            done <<< "$(_fm_bot_appfile_apps_list)"
            [[ $nv_any -eq 0 ]] && nv_msg+="%0A%0Aℹ️ لا يوجد أي ملف NPV مرفوع. الملفات الأخرى تُرسل كما هي — وهذا سلوكها الصحيح."
            send_telegram_msg "$nv_msg"
            ;;
        /listfiles)
            local apps app types type lf_msg="📁 <b>ملفات تطبيقات الاتصال</b>%0A" lf_any=0
            while IFS= read -r app; do
                [[ -z "$app" ]] && continue
                lf_any=1
                lf_msg+="%0A<b>${app}</b>:"
                while IFS= read -r type; do
                    [[ -z "$type" ]] && continue
                    lf_msg+=" ${type}"
                done < <(_fm_bot_appfile_types_list "$app")
            done < <(_fm_bot_appfile_apps_list)
            [[ "$lf_any" -eq 0 ]] && lf_msg+="%0A(لا يوجد شيء بعد — أرسل مستندًا مع التعليق <code>/addfile AppName FileType</code> لإضافة واحد)"
            send_telegram_msg "$lf_msg"
            ;;
        /delfile)
            local df_app df_type
            df_app=$(awk '{print $1}' <<< "$rest"); df_type=$(awk '{print $2}' <<< "$rest")
            if [[ -z "$df_app" || -z "$df_type" ]]; then
                send_telegram_msg "❌ الاستخدام: <code>/delfile AppName FileType</code> — راجع <code>/listfiles</code> للأسماء الدقيقة."
                return
            fi
            _fm_bot_appfile_del "$df_app" "$df_type"
            send_telegram_msg "✅ تمت إزالة ${df_app} — ${df_type}."
            ;;
        /listguides)
            local ag_app lg_msg="📸 <b>صور شرح HWID</b>%0A" lg_any=0 lg_n
            while IFS= read -r ag_app; do
                [[ -z "$ag_app" ]] && continue
                lg_n=$(_fm_bot_hwid_guide_count "$ag_app")
                [[ "$lg_n" -gt 0 ]] || continue
                lg_any=1
                lg_msg+="%0A${ag_app} — ${lg_n} صورة"
            done < <(_fm_bot_appfile_apps_list)
            [[ "$lg_any" -eq 0 ]] && lg_msg+="%0A(لا توجد صور بعد — أرسل صورة مع التعليق <code>/addguide AppName</code>، وكرّرها لإضافة عدة صور لنفس التطبيق)"
            send_telegram_msg "$lg_msg"
            ;;
        /delguide)
            if [[ -z "$rest" ]]; then
                send_telegram_msg "❌ الاستخدام: <code>/delguide AppName</code> لحذف كل الصور، أو <code>/delguide AppName 2</code> لحذف صورة واحدة بترتيبها."
                return
            fi
            # A trailing number targets one image; a bare app name (which
            # may itself contain spaces) still clears all of them.
            local dg_app="$rest" dg_n=""
            if [[ "$rest" =~ ^(.+)[[:space:]]+([0-9]+)$ ]]; then
                dg_app="${BASH_REMATCH[1]}"; dg_n="${BASH_REMATCH[2]}"
            fi
            if [[ -n "$dg_n" ]]; then
                if _fm_bot_hwid_guide_del_one "$dg_app" "$dg_n"; then
                    send_telegram_msg "✅ حُذفت صورة الشرح رقم ${dg_n} لتطبيق ${dg_app}. المتبقي: $(_fm_bot_hwid_guide_count "$dg_app") صورة."
                else
                    send_telegram_msg "❌ لا توجد صورة رقم ${dg_n} لتطبيق ${dg_app}."
                fi
            else
                _fm_bot_hwid_guide_del "$dg_app"
                send_telegram_msg "✅ حُذفت كل صور الشرح لتطبيق ${dg_app}."
            fi
            ;;
        /setnote|/setfilenote)
            # "AppName | the explanation" — a pipe, not a space, because
            # an app name may itself contain spaces and the text almost
            # always does. Omitting the text clears the note.
            local sn_kind="hwid" sn_label="شرح HWID"
            [[ "$cmd" == "/setfilenote" ]] && { sn_kind="file"; sn_label="شرح إضافة الملف"; }
            if [[ -z "$rest" ]]; then
                send_telegram_msg "❌ الاستخدام: <code>${cmd} AppName | نص الشرح</code>%0Aولحذف الشرح: <code>${cmd} AppName |</code>"
                return
            fi
            local sn_app sn_text
            if [[ "$rest" == *"|"* ]]; then
                sn_app="${rest%%|*}"; sn_text="${rest#*|}"
            else
                sn_app="$rest"; sn_text=""
            fi
            sn_app="${sn_app#"${sn_app%%[![:space:]]*}"}"; sn_app="${sn_app%"${sn_app##*[![:space:]]}"}"
            sn_text="${sn_text#"${sn_text%%[![:space:]]*}"}"; sn_text="${sn_text%"${sn_text##*[![:space:]]}"}"
            if [[ -z "$sn_app" ]]; then
                send_telegram_msg "❌ اكتب اسم التطبيق قبل العلامة |."
                return
            fi
            if _fm_bot_guide_note_set "$sn_kind" "$sn_app" "$sn_text"; then
                if [[ -n "$sn_text" ]]; then
                    send_telegram_msg "✅ حُفظ ${sn_label} لتطبيق ${sn_app} (${#sn_text} حرفًا). سيُرسل مع الصور تلقائيًا."
                else
                    send_telegram_msg "✅ حُذف ${sn_label} لتطبيق ${sn_app}."
                fi
            else
                send_telegram_msg "❌ تعذّر حفظ الشرح لتطبيق ${sn_app}."
            fi
            ;;
        /listfileguides)
            local fg_app fgl_msg="📖 <b>صور شرح طريقة إضافة الملف</b>%0A" fgl_any=0 fgl_n
            while IFS= read -r fg_app; do
                [[ -z "$fg_app" ]] && continue
                fgl_n=$(_fm_bot_file_guide_count "$fg_app")
                [[ "$fgl_n" -gt 0 ]] || continue
                fgl_any=1
                fgl_msg+="%0A${fg_app} — ${fgl_n} صورة"
            done < <(_fm_bot_appfile_apps_list)
            [[ "$fgl_any" -eq 0 ]] && fgl_msg+="%0A(لا توجد صور بعد — أرسل صورة مع التعليق <code>/addfileguide AppName</code>، وكرّرها لإضافة عدة صور لنفس التطبيق)"
            send_telegram_msg "$fgl_msg"
            ;;
        /delfileguide)
            if [[ -z "$rest" ]]; then
                send_telegram_msg "❌ الاستخدام: <code>/delfileguide AppName</code> لحذف كل الصور، أو <code>/delfileguide AppName 2</code> لحذف صورة واحدة بترتيبها."
                return
            fi
            local dfg_app="$rest" dfg_n=""
            if [[ "$rest" =~ ^(.+)[[:space:]]+([0-9]+)$ ]]; then
                dfg_app="${BASH_REMATCH[1]}"; dfg_n="${BASH_REMATCH[2]}"
            fi
            if [[ -n "$dfg_n" ]]; then
                if _fm_bot_file_guide_del_one "$dfg_app" "$dfg_n"; then
                    send_telegram_msg "✅ حُذفت صورة الشرح رقم ${dfg_n} لتطبيق ${dfg_app}. المتبقي: $(_fm_bot_file_guide_count "$dfg_app") صورة."
                else
                    send_telegram_msg "❌ لا توجد صورة رقم ${dfg_n} لتطبيق ${dfg_app}."
                fi
            else
                _fm_bot_file_guide_del "$dfg_app"
                send_telegram_msg "✅ حُذفت كل صور شرح الملف لتطبيق ${dfg_app}."
            fi
            ;;
        /help|/start)
            _fm_admin_send_menu "🤖 <b>أوامر بوت DAHOOM</b>%0A/status - حالة السيرفر والخدمات%0A/users - عدد المستخدمين%0A/backup - نسخة احتياطية الآن%0A%0A<b>إنشاء حساب لمشترك بنفسك</b>%0A/customer — يحوّل هذه المحادثة لواجهة العميل (كل الحدود مرفوعة: الرصيد والتجارب والتجديد وتغيير الجهاز)%0A/admin — العودة لأوامر الأدمن%0A%0A<b>بوت المبيعات</b>%0A/plans - عرض إعدادات التجربة/الاشتراك%0A/set_trial_hours,_bw,_devices,_max N%0A/set_monthly_days,_bw,_devices N — خطة الشهر%0A/set_monthly2_days,_bw,_devices N — خطة الشهرين%0A/set_price N — /set_price2 N — /set_payment_info TEXT%0A/set_hwid_len N — طول معرّف الجهاز للتطبيقات العادية (0 = بلا فحص)%0A/set_expire_delete_days N — حذف الحساب المنتهي بعد N أيام (0 = لا يُحذف)%0A/addcredit ID AMOUNT%0A/add_trials ID COUNT — تجارب إضافية هذا الشهر%0A/add_hwid_changes ID COUNT — مرات تغيير جهاز إضافية (يقبل رقمًا سالبًا للسحب)%0A/coupon_add, /coupon_del, /coupon_list%0A/ban, /unban ID%0A/pending — /approve ID — /reject ID [السبب]%0A/acct ACCOUNT أو TELEGRAM_ID — بطاقة الاشتراك الكاملة%0A%0A<b>الإعلانات والدعم</b>%0A<code>/broadcast نص الإعلان</code> — يصل لكل المستخدمين (معاينة وتأكيد أولًا)%0A<code>/reply TELEGRAM_ID نص الرد</code> — رد على عميل%0Aأو اضغط «↩️ رد على العميل» تحت رسالته ثم اكتب ردّك مباشرة%0A/cancel_reply — إلغاء وضع الرد%0A/cancel ACCOUNT — إيقاف اشتراك — /uncancel ACCOUNT لإعادته%0A/salesstats%0A/npvt — فحص ملفات NPV Tunnel وسبب أي فشل تخصيص%0A%0A<b>الإحالة</b>%0A/add_referral_tier paid|signup THRESHOLD REWARD%0A/del_referral_tier paid|signup THRESHOLD%0A/list_referral_tiers%0A%0A<b>ملفات التطبيقات</b>%0Aأرسل مستندًا مع التعليق <code>/addfile AppName FileType</code> لإضافة واحد%0A/listfiles — /delfile AppName FileType%0A%0A<b>صور شرح HWID</b>%0Aأرسل صورة مع التعليق <code>/addguide AppName</code> — كرّرها لعدة صور لنفس التطبيق%0A/listguides — /delguide AppName [رقم الصورة]%0A<code>/setnote AppName | نص الشرح</code> — شرح كتابي يُرسل مع الصور (بلا نص = حذف)%0A%0A<b>صور شرح إضافة الملف داخل التطبيق</b>%0Aأرسل صورة مع التعليق <code>/addfileguide AppName</code> — كرّرها لعدة صور%0A/listfileguides — /delfileguide AppName [رقم الصورة]%0A<code>/setfilenote AppName | نص الشرح</code> — شرح كتابي يُرسل مع الصور (بلا نص = حذف)%0A%0A/help - هذه الرسالة"
            ;;
        *)
            _fm_admin_send_menu "❓ أمر غير معروف. استخدم الأزرار بالأسفل، أو أرسل /help لعرض كل الأوامر."
            ;;
    esac
}

# ── Reseller Telegram bot: read-only self-service (status + own user
# counts). Deliberately scoped away from remote user creation or credit
# spending — that logic (validation, credit deduction, ownership checks)
# lives in panel.py, and re-implementing it here in bash would risk
# drifting out of sync with it and corrupting the shared users.db /
# resellers.db. A reseller links their own chat once with a short-lived
# code the admin generates for them; after that they can query their own
# account and users, nothing more.
RESELLERS_DB="/etc/firewallfalcon/resellers.db"
RESELLER_TG_MAP="/etc/firewallfalcon/.reseller_telegram.map"
RESELLER_LINK_PENDING="/etc/firewallfalcon/.reseller_link_pending"

_fm_reseller_lookup_by_chat() {
    local chat_id="$1"
    [[ -s "$RESELLER_TG_MAP" ]] || return 1
    awk -F: -v c="$chat_id" '$1==c{print $2; f=1} END{exit !f}' "$RESELLER_TG_MAP"
}

# Generates a 6-digit, 10-minute code for one reseller and stores it
# pending. Any previous unclaimed code for the same reseller is dropped
# first so only the newest one is ever valid.
_fm_reseller_generate_link_code() {
    local reseller_user="$1"
    local code; code=$(( (RANDOM * 32768 + RANDOM) % 900000 + 100000 ))
    local expiry; expiry=$(( $(date +%s) + 600 ))
    mkdir -p "$(dirname "$RESELLER_LINK_PENDING")" 2>/dev/null
    if [[ -f "$RESELLER_LINK_PENDING" ]]; then
        grep -v ":${reseller_user}:" "$RESELLER_LINK_PENDING" > "${RESELLER_LINK_PENDING}.tmp" 2>/dev/null
        mv -f "${RESELLER_LINK_PENDING}.tmp" "$RESELLER_LINK_PENDING" 2>/dev/null
    fi
    echo "${code}:${reseller_user}:${expiry}" >> "$RESELLER_LINK_PENDING"
    echo "$code"
}

# Consumes a code if valid+unexpired, binds the sending chat_id to that
# reseller, and echoes the reseller username back (empty on failure).
_fm_reseller_consume_link_code() {
    local code="$1" chat_id="$2"
    [[ -s "$RESELLER_LINK_PENDING" ]] || return 1
    local now; now=$(date +%s)
    local c u e reseller_user=""
    while IFS=: read -r c u e; do
        [[ "$c" == "$code" ]] || continue
        [[ "$e" =~ ^[0-9]+$ && "$e" -ge "$now" ]] || continue
        reseller_user="$u"
        break
    done < "$RESELLER_LINK_PENDING"
    [[ -n "$reseller_user" ]] || return 1

    grep -v "^${code}:" "$RESELLER_LINK_PENDING" > "${RESELLER_LINK_PENDING}.tmp" 2>/dev/null
    mv -f "${RESELLER_LINK_PENDING}.tmp" "$RESELLER_LINK_PENDING" 2>/dev/null
    mkdir -p "$(dirname "$RESELLER_TG_MAP")" 2>/dev/null
    if [[ -f "$RESELLER_TG_MAP" ]]; then
        grep -v "^${chat_id}:" "$RESELLER_TG_MAP" > "${RESELLER_TG_MAP}.tmp" 2>/dev/null
        mv -f "${RESELLER_TG_MAP}.tmp" "$RESELLER_TG_MAP" 2>/dev/null
    fi
    echo "${chat_id}:${reseller_user}" >> "$RESELLER_TG_MAP"
    echo "$reseller_user"
}

_fm_reseller_handle_command() {
    local chat_id="$1" reseller_user="$2" text="$3"
    local cmd="${text%% *}"
    case "$cmd" in
        /mystatus)
            local line=""
            [[ -s "$RESELLERS_DB" ]] && line=$(awk -F: -v u="$reseller_user" '$1==u{print; exit}' "$RESELLERS_DB")
            if [[ -z "$line" ]]; then
                send_telegram_msg_to "$chat_id" "❌ Your reseller account was not found."
                return
            fi
            local ru rp rexp rmax renabled rtype rcredits _rest
            IFS=: read -r ru rp rexp rmax renabled rtype rcredits _rest <<< "$line"
            local enabled_str="No"; [[ "$renabled" == "1" ]] && enabled_str="Yes"
            send_telegram_msg_to "$chat_id" "🧾 <b>Reseller Status</b>%0AAccount: ${ru}%0AEnabled: ${enabled_str}%0AExpires: ${rexp}%0AMax Users: ${rmax}%0ACredits: ${rcredits:-0}"
            ;;
        /myusers)
            local total=0 active=0 locked=0 expired=0 now_ts
            now_ts=$(date +%s)
            if [[ -s "$DB_FILE" && -r /etc/shadow ]]; then
                local -A s_locked=()
                local su sh_h sr u p exp lim bw dbw atype owner e_ts
                while IFS=: read -r su sh_h sr; do
                    [[ -n "$su" && "${sh_h:0:1}" == "!" ]] && s_locked["$su"]=1
                done < /etc/shadow
                while IFS=: read -r u p exp lim bw dbw atype owner; do
                    [[ -z "$u" ]] && continue
                    [[ "$owner" == "$reseller_user" ]] || continue
                    (( total++ ))
                    e_ts=0
                    [[ -n "$exp" && "$exp" != "Never" ]] && e_ts=$(date -d "$exp" +%s 2>/dev/null || echo 0)
                    if [[ -n "${s_locked[$u]+x}" ]]; then
                        (( locked++ ))
                    elif (( e_ts > 0 && e_ts < now_ts )); then
                        (( expired++ ))
                    else
                        (( active++ ))
                    fi
                done < "$DB_FILE"
            fi
            send_telegram_msg_to "$chat_id" "👥 <b>Your Users</b>%0ATotal: ${total}%0AActive: ${active}%0ALocked: ${locked}%0AExpired: ${expired}"
            ;;
        /help|/start)
            send_telegram_msg_to "$chat_id" "🤝 <b>Reseller Bot</b>%0A/mystatus - Your account &amp; credits%0A/myusers - Your users summary%0A/help - This message"
            ;;
        *)
            send_telegram_msg_to "$chat_id" "❓ Unknown command. Send /help for the list of commands."
            ;;
    esac
}

# ── Sales Bot: public trial + paid-subscription engine ─────────────────
# Anyone who messages the bot and is neither the admin nor a linked
# reseller lands here. Two plans: a free HWID trial (rate-limited per
# Telegram user AND per device — switching Telegram accounts doesn't buy
# a device more trials) and a paid monthly HWID subscription. Payment is
# manual (bank transfer / STC Pay, confirmed by the admin from their own
# chat) since there's no merchant/payment-gateway account to integrate
# against. Every setting here — trial length/quota, monthly price/quota,
# payment instructions — is admin-editable at any time via bot command or
# the web panel, and takes effect on the very next command; nothing here
# is baked in at install time.
#
# Every account this issues goes through the exact same account-creation
# path as the interactive menu (_fm_create_system_user, users.db,
# _fm_set_login_mode), so a bot-issued account is a completely ordinary
# managed HWID account afterward — visible in "Manage Accounts", backed
# up, editable — just tagged with owner="tg:<telegram_id>" so /myaccount
# and the web panel can trace it back to whoever bought it.
BOT_PLANS_CONF="/etc/firewallfalcon/bot_plans.conf"
BOT_TRIAL_LOG="/etc/firewallfalcon/bot_trial_log.db"
BOT_WALLETS_DB="/etc/firewallfalcon/bot_wallets.db"
BOT_COUPONS_DB="/etc/firewallfalcon/bot_coupons.db"
BOT_BANS_DB="/etc/firewallfalcon/bot_bans.db"
BOT_ORDERS_DB="/etc/firewallfalcon/bot_orders.db"
BOT_ORDER_SEQ_FILE="/etc/firewallfalcon/.bot_order_seq"
BOT_TRIAL_BONUS_DB="/etc/firewallfalcon/bot_trial_bonus.db"
BOT_HWID_CHANGE_USED_DB="/etc/firewallfalcon/bot_hwid_change_used.db"
BOT_HWID_CHANGE_BONUS_DB="/etc/firewallfalcon/bot_hwid_change_bonus.db"
BOT_HWID_CHANGE_STATE_DB="/etc/firewallfalcon/bot_hwid_change_state.db"
BOT_HWID_CHANGE_DEFAULT_MAX=3
BOT_REFERRALS_DB="/etc/firewallfalcon/bot_referrals.db"
BOT_REFERRAL_PAID_DB="/etc/firewallfalcon/bot_referral_paid.db"
BOT_REFERRAL_TIERS_CONF="/etc/firewallfalcon/bot_referral_tiers.conf"
BOT_REFERRAL_REWARDED_DB="/etc/firewallfalcon/bot_referral_rewarded.db"
BOT_APP_FILES_DIR="/etc/firewallfalcon/bot_app_files"
BOT_APP_FILES_META="/etc/firewallfalcon/bot_app_files.db"
BOT_APP_HWID_GUIDE_DIR="/etc/firewallfalcon/bot_app_hwid_guides"
BOT_APP_FILE_GUIDE_DIR="/etc/firewallfalcon/bot_app_file_guides"
# The written explanation that goes out WITH each gallery — one text per
# app, per gallery. Its own directory, not a file beside the image
# folders: the gallery listings enumerate their directory and treat
# every entry as an app, so a note stored in there would appear as a
# phantom app named after the note.
BOT_APP_HWID_NOTE_DIR="/etc/firewallfalcon/bot_app_hwid_notes"
BOT_APP_FILE_NOTE_DIR="/etc/firewallfalcon/bot_app_file_notes"
# Telegram rejects a photo/album whose caption exceeds 1024 characters —
# the whole send fails, images and all. Past this the note goes out as
# its own message instead, so a long explanation can never cost the
# customer the pictures.
BOT_GUIDE_CAPTION_MAX=1000
# Which platform(s) each app is for (android/ios/both — untagged apps
# default to "both" so this feature is a no-op until an admin uses it).
BOT_APP_PLATFORM_DB="/etc/firewallfalcon/bot_app_platform.db"
# The "which server?" step shown right after tapping trial/subscribe.
# Each region either continues the flow in this bot ("internal") or
# hands the customer a link to a different bot ("redirect").
BOT_SERVER_REGIONS_CONF="/etc/firewallfalcon/bot_regions.db"
# Country + SIM/carrier-type step, shown after the app itself is picked
# (region above and country here are two deliberately separate steps —
# region is "which server", country is "which SIM operator's config").
# Countries are a flat admin-managed list; each SIM type belongs to
# exactly one country and only appears once that country is picked. See
# the "Country + SIM type selection" section further down for how these
# feed into the existing per-app file library without changing it.
BOT_COUNTRIES_CONF="/etc/firewallfalcon/bot_countries.db"
BOT_SIMTYPES_CONF="/etc/firewallfalcon/bot_simtypes.db"
# File type step, shown right after SIM type (or right after country, for
# a country with no SIM types) — lets more than one file be attached to
# the exact same (country, SIM type) pair, e.g. "مباشر"/"Direct" vs
# "SNI" variants of the same operator config. Keyed by the composite
# prefix _fm_bot_country_simtype_key already produces, not by raw
# country/SIM-type fields — see the section comment further down.
BOT_FILETYPES_CONF="/etc/firewallfalcon/bot_filetypes.db"
BOT_PENDING_DB="/etc/firewallfalcon/bot_pending.db"
# Per-chat back-navigation stack — see _fm_bot_goto / _fm_bot_nav_* below.
BOT_NAV_DB="/etc/firewallfalcon/bot_nav.db"
BOT_LANG_DB="/etc/firewallfalcon/bot_lang.db"

# Minimal HTML-escape for strings a stranger typed (appeal messages, ban
# reasons) before they're embedded in an HTML-mode Telegram message —
# Telegram silently drops a message with unbalanced/invalid HTML, and
# send_telegram_msg fires in the background with no error surfaced, so an
# unescaped '<' from a customer would make their own report vanish.
_fm_html_escape() {
    local s="$1"
    # The backslashes are load-bearing. Since bash 5.2 an unescaped "&"
    # in a ${var//pat/repl} replacement means "the text that matched",
    # so "${s//</&lt;}" silently produced "<lt;" — i.e. "<" and ">" were
    # never actually escaped at all, and any customer message containing
    # one made Telegram reject the whole send, so the admin simply never
    # received it. ("&" survived only by coincidence: & expanding to the
    # matched "&" happens to rebuild "&amp;".)
    s="${s//&/\&amp;}"
    s="${s//</\&lt;}"
    s="${s//>/\&gt;}"
    printf '%s' "$s"
}

_fm_bot_ensure_plans_conf() {
    if [[ ! -f "$BOT_PLANS_CONF" ]]; then
        mkdir -p "$(dirname "$BOT_PLANS_CONF")" 2>/dev/null
        cat > "$BOT_PLANS_CONF" << 'EOF'
TRIAL_MAX_USES="2"
TRIAL_HOURS="1"
TRIAL_BW_GB="0"
TRIAL_DEVICES="1"
MONTHLY_DAYS="30"
MONTHLY_BW_GB="0"
MONTHLY_DEVICES="1"
MONTHLY_PRICE_SAR="15"
MONTHLY2_DAYS="60"
MONTHLY2_BW_GB="0"
MONTHLY2_DEVICES="1"
MONTHLY2_PRICE_SAR="28"
HWID_LEN="32"
EXPIRED_DELETE_DAYS="3"
PAYMENT_INFO="Contact the admin for payment details."
EOF
        return 0
    fi
    # Upgrade path for an install from before the 2-month plan existed:
    # this file exists already but has no MONTHLY2_* keys yet. Add them
    # once, scaled off whatever the existing monthly plan is set to, so
    # _fm_bot_get_plan never returns an empty string for the second tier
    # (which would break every days/price calculation using it). Parsed
    # directly with grep rather than via _fm_bot_get_plan, which itself
    # calls this function — that would recurse.
    grep -q '^MONTHLY2_DAYS=' "$BOT_PLANS_CONF" 2>/dev/null && return 0
    local raw m_days m_bw m_dev m_price
    raw=$(grep '^MONTHLY_DAYS=' "$BOT_PLANS_CONF" 2>/dev/null | tail -1); m_days="${raw#*=\"}"; m_days="${m_days%\"}"
    [[ "$m_days" =~ ^[0-9]+$ ]] || m_days=30
    raw=$(grep '^MONTHLY_BW_GB=' "$BOT_PLANS_CONF" 2>/dev/null | tail -1); m_bw="${raw#*=\"}"; m_bw="${m_bw%\"}"
    [[ "$m_bw" =~ ^[0-9]+$ ]] || m_bw=0
    raw=$(grep '^MONTHLY_DEVICES=' "$BOT_PLANS_CONF" 2>/dev/null | tail -1); m_dev="${raw#*=\"}"; m_dev="${m_dev%\"}"
    [[ "$m_dev" =~ ^[0-9]+$ ]] || m_dev=1
    raw=$(grep '^MONTHLY_PRICE_SAR=' "$BOT_PLANS_CONF" 2>/dev/null | tail -1); m_price="${raw#*=\"}"; m_price="${m_price%\"}"
    [[ "$m_price" =~ ^[0-9]+(\.[0-9]+)?$ ]] || m_price=15
    {
        printf 'MONTHLY2_DAYS="%s"\n' "$((m_days * 2))"
        printf 'MONTHLY2_BW_GB="%s"\n' "$m_bw"
        printf 'MONTHLY2_DEVICES="%s"\n' "$m_dev"
        printf 'MONTHLY2_PRICE_SAR="%s"\n' "$(awk -v p="$m_price" 'BEGIN{printf "%g", p*2}')"
    } >> "$BOT_PLANS_CONF"
}

# Prints one plan value on stdout. Deliberately does NOT `source` the
# file — PAYMENT_INFO is free text the admin types into a Telegram
# message (e.g. "/set_payment_info $(whatever)"), and sourcing a file
# with an unescaped $(...) or backtick in it executes it as a shell
# command. Confirmed with a live test before shipping this. Parses the
# KEY="VALUE" line as plain text instead and reverses the escaping
# _fm_bot_set_plan applies on write. Re-reads on every call (cheap — a
# handful of lines) so a setting changed a second ago (bot command or
# web panel) is always picked up immediately.
_fm_bot_plan_read_raw() {
    local key="$1" line val vlen
    line=$(grep "^${key}=" "$BOT_PLANS_CONF" 2>/dev/null | tail -1)
    [[ -n "$line" ]] || return 0
    val="${line#*=}"
    vlen=${#val}
    if [[ "$vlen" -ge 2 && "${val:0:1}" == '"' && "${val:vlen-1:1}" == '"' ]]; then
        val="${val:1:vlen-2}"
    fi
    val="${val//\\\"/\"}"
    val="${val//\\\\/\\}"
    printf '%s' "$val"
}

# Composite key for one plan setting overridden on one node — the same
# "fold the node onto an existing key, empty node reproduces the old key
# byte for byte" shape as _fm_bot_node_country_simtype_key. node="" is
# the global setting, which is what every caller that knows nothing
# about nodes (and every install with no nodes registered at all) keeps
# reading and writing exactly as before. Anything outside [A-Za-z0-9_]
# becomes "_" and the result is uppercased, so a node slug — which may
# legitimately carry a space, dot or dash — still yields a plain
# KEY="VALUE" line like every other line in the file. Exact mirror of
# bot_plan_node_key in panel.py.
_fm_bot_plan_node_key() {
    local node="$1" key="$2" slug
    [[ -n "$node" ]] || { printf '%s' "$key"; return 0; }
    slug="${node//[^A-Za-z0-9_]/_}"
    printf 'NODE_%s__%s' "${slug^^}" "$key"
}

# Comma-separated slugs of the registered nodes that carry at least one
# plan override — purely informational, for the /plans summary. Walks the
# node registry rather than the plan file's own NODE_* lines so what it
# prints is always a slug the admin recognises, and so leftovers from a
# deleted node never show up as a phantom server.
_fm_bot_plan_override_nodes() {
    local db="${BOT_NODES_CONF:-/etc/firewallfalcon/bot_nodes.db}" slug rest out=""
    [[ -f "$db" && -f "$BOT_PLANS_CONF" ]] || return 0
    while IFS=: read -r slug rest; do
        [[ -n "$slug" ]] || continue
        grep -q "^$(_fm_bot_plan_node_key "$slug" "")" "$BOT_PLANS_CONF" 2>/dev/null && out+="${slug}، "
    done < "$db"
    printf '%s' "${out%، }"
}

# With a node slug as the second argument, that node's own override
# wins when it has one and the global value is used otherwise — so a
# node the admin never customised behaves exactly like the global plan,
# with no per-node setup required to keep working. An override stored
# as an empty string counts as absent, which is what makes "clear the
# field to go back to the global value" work from the panel.
_fm_bot_get_plan() {
    _fm_bot_ensure_plans_conf
    local key="$1" node="${2:-}" val
    if [[ -n "$node" ]]; then
        val=$(_fm_bot_plan_read_raw "$(_fm_bot_plan_node_key "$node" "$key")")
        [[ -n "$val" ]] && { printf '%s' "$val"; return 0; }
    fi
    _fm_bot_plan_read_raw "$key"
}

# Backslash-escapes '\' and '"' (and flattens embedded newlines, which
# the one-line KEY="VALUE" format can't represent) before writing, so the
# file stays plain, safely-parseable text no matter what the admin types
# — no character sequence can break the format or, since it's never
# sourced, execute anything.
_fm_bot_set_plan() {
    local key="$1" val="$2" node="${3:-}" esc
    _fm_bot_ensure_plans_conf
    [[ -n "$node" ]] && key=$(_fm_bot_plan_node_key "$node" "$key")
    esc="${val//\\/\\\\}"
    esc="${esc//\"/\\\"}"
    esc="${esc//$'\n'/ }"
    if [[ -f "$BOT_PLANS_CONF" ]]; then
        grep -v "^${key}=" "$BOT_PLANS_CONF" > "${BOT_PLANS_CONF}.tmp" 2>/dev/null
        mv -f "${BOT_PLANS_CONF}.tmp" "$BOT_PLANS_CONF"
    fi
    # Clearing a node override removes the line rather than writing it
    # empty: _fm_bot_get_plan already treats an empty override as absent,
    # so keeping it would only leave dead lines behind for every node the
    # admin ever opened and then reset. A global key is never dropped
    # this way — an empty global value is a real (if unusual) setting.
    [[ -n "$node" && -z "$val" ]] && return 0
    printf '%s="%s"\n' "$key" "$esc" >> "$BOT_PLANS_CONF"
}

# ── Server regions ("which server?" step right after trial/subscribe) ──
# One row per admin-configured region: slug:name_ar:name_en:mode:url:enabled.
# mode is "internal" (continue the flow in this bot) or "redirect" (hand
# the customer a link to a different bot and stop). Seeded with two
# regions the first time this is read so the feature works out of the
# box; the admin edits/adds/removes from the panel afterward. The
# redirect URL is a placeholder until the admin sets the real one —
# same pattern as PAYMENT_INFO's placeholder text above.
_fm_bot_ensure_regions_conf() {
    [[ -f "$BOT_SERVER_REGIONS_CONF" ]] && return 0
    mkdir -p "$(dirname "$BOT_SERVER_REGIONS_CONF")" 2>/dev/null
    cat > "$BOT_SERVER_REGIONS_CONF" << 'EOF'
saudi:السعودي:Saudi:redirect:1:https://t.me/YourOtherBotUsername
germany:ألمانيا:Germany:internal:1:
EOF
}

# All configured regions, enabled or not — used by the panel/admin tools.
# Rows are slug:name_ar:name_en:mode:enabled:url — url is deliberately
# the LAST field (not 5th) because it routinely contains "://" itself;
# with url last, awk's -F: and bash's `read` both still land on the
# right field for everything before it, and url just soaks up whatever
# colons remain instead of shifting every later field.
_fm_bot_regions_list_all() {
    _fm_bot_ensure_regions_conf
    cat "$BOT_SERVER_REGIONS_CONF" 2>/dev/null
}

# Only the ones a customer should be offered, in the order configured.
_fm_bot_regions_list_enabled() {
    _fm_bot_regions_list_all | awk -F: '$5=="1"'
}

_fm_bot_region_get() {
    local slug="$1"
    _fm_bot_regions_list_all | awk -F: -v s="$slug" '$1==s{print; exit}'
}

_fm_bot_region_name() {
    local slug="$1" lang="$2" line
    line=$(_fm_bot_region_get "$slug") || return 1
    [[ -n "$line" ]] || return 1
    IFS=: read -r _s r_ar r_en _mode _enabled _url <<< "$line"
    [[ "$lang" == "en" ]] && printf '%s' "$r_en" || printf '%s' "$r_ar"
}

# Adds a region, or replaces one with the same slug (upsert) — the panel
# always sends the slug it already has for an edit, or a freshly slugged
# one for a new region. Colons are stripped from the name fields (the
# storage format is colon-delimited and names have no reason to carry
# one); the url is left untouched since it's the last field.
_fm_bot_region_upsert() {
    local slug name_ar name_en mode url enabled
    slug=$(_fm_bot_sanitize_slug "$1")
    name_ar="${2//:/}" name_en="${3//:/}" mode="$4" url="$5"
    enabled="$6"
    [[ -n "$slug" ]] || return 1
    # "node" (new): this region IS a registered VPN node (see
    # bot_nodes.db/_fm_bot_node_get) — the customer's pick sticks for
    # the rest of the flow (_fm_bot_node_selected_set) instead of either
    # ending the conversation (redirect) or doing nothing (internal).
    case "$mode" in redirect|node) ;; *) mode="internal" ;; esac
    [[ "$mode" == "redirect" ]] || url=""
    _fm_bot_ensure_regions_conf
    grep -v "^${slug}:" "$BOT_SERVER_REGIONS_CONF" > "${BOT_SERVER_REGIONS_CONF}.tmp" 2>/dev/null
    mv -f "${BOT_SERVER_REGIONS_CONF}.tmp" "$BOT_SERVER_REGIONS_CONF"
    echo "${slug}:${name_ar}:${name_en}:${mode}:${enabled}:${url}" >> "$BOT_SERVER_REGIONS_CONF"
    printf '%s' "$slug"
}

_fm_bot_region_delete() {
    local slug="$1"
    _fm_bot_ensure_regions_conf
    grep -v "^${slug}:" "$BOT_SERVER_REGIONS_CONF" > "${BOT_SERVER_REGIONS_CONF}.tmp" 2>/dev/null
    mv -f "${BOT_SERVER_REGIONS_CONF}.tmp" "$BOT_SERVER_REGIONS_CONF"
}

# Maps a tapped button's text back to a region, checking both languages
# (same reasoning as _fm_bot_button_action — a tap can arrive a beat
# after a language switch, or from a stale cached keyboard).
_fm_bot_region_find_by_text() {
    local text="$1" lg line
    for lg in ar en; do
        while IFS= read -r line; do
            [[ -z "$line" ]] && continue
            local s n_ar n_en
            IFS=: read -r s n_ar n_en _rest <<< "$line"
            local n="$n_ar"; [[ "$lg" == "en" ]] && n="$n_en"
            [[ "$n" == "$text" ]] && { printf '%s' "$s"; return 0; }
        done <<< "$(_fm_bot_regions_list_enabled)"
    done
    return 1
}

# The button captions for the region step, in display order. Both the
# keyboard and the inline-callback resolver read this one list, so a tap
# can never be matched against a different order than what was shown.
_fm_bot_region_names() {
    local lang="${1:-ar}" names="" line
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        local s n_ar n_en
        IFS=: read -r s n_ar n_en _rest <<< "$line"
        local n="$n_ar"; [[ "$lang" == "en" ]] && n="$n_en"
        [[ -n "$n" ]] && names+="${n}"$'\n'
    done <<< "$(_fm_bot_regions_list_enabled)"
    printf '%s' "$names"
}

_fm_bot_send_region_list() {
    local chat_id="$1" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names=$(_fm_bot_region_names "$lang")
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg REGION_PROMPT "$lang")" "$names"
}

# ── Country + SIM/carrier-type selection (after the app is picked) ─────
# Two admin-managed lists, both read-only from this side — exactly like
# Server Regions above, the actual add/edit/delete happens from the
# panel (bot_country_upsert/bot_country_delete/bot_simtype_add/
# bot_simtype_delete in panel.py), writing the same shared files these
# functions read.
#
# Country: slug:name_ar:name_en:enabled — a flat global list, same shape
# as a region minus the internal/redirect distinction.
#
# SIM type: country_slug:name — a simple string per country (no ar/en:
# it's a technical label like "STC"/"Mobily", the same convention as an
# app's file-type name, not a translated UI string). Only the types
# belonging to whichever country the customer just picked are ever
# shown.
#
# Crucially, neither of these touches the existing per-app file library
# at all: _fm_bot_country_simtype_key below folds a (country, simtype)
# pick into the exact same "type" string _fm_bot_appfile_* already keys
# files by, so every uploaded file, every order, and every render/deliver
# path keeps working completely unchanged — this is a new front door
# onto the same room, not a new room.
# ── Only what the chosen app actually has ─────────────────────────────
# Countries, SIM types and file types are admin-managed lists shared by
# every app, while a file exists per (app, type) pair. Offering a
# customer a choice their app has no file for is a dead end they discover
# only after paying — and the file-type list was the worst of it: its
# rows are keyed by country_simtype alone, with no app in the key, so
# every label ever registered for a SIM pair showed up under every app.
#
# So each list is filtered against the types that app actually has in its
# own directory. That directory is the same place the file is fetched
# from at delivery, which makes it the one source that cannot disagree
# with what the customer ends up receiving.
_fm_bot_appfile_has_prefix() {
    local app="$1" key="$2" t
    [[ -n "$app" && -n "$key" ]] || return 1
    while IFS= read -r t; do
        [[ -z "$t" ]] && continue
        [[ "$t" == "$key" || "$t" == "${key}_"* ]] && return 0
    done <<< "$(_fm_bot_appfile_types_list "$app")"
    return 1
}

_fm_bot_appfile_has_type() {
    local app="$1" key="$2"
    [[ -n "$app" && -n "$key" ]] || return 1
    [[ -f "$(_fm_bot_appfile_path "$app" "$key")" ]]
}

_fm_bot_ensure_countries_conf() {
    [[ -f "$BOT_COUNTRIES_CONF" ]] && return 0
    mkdir -p "$(dirname "$BOT_COUNTRIES_CONF")" 2>/dev/null
    cat > "$BOT_COUNTRIES_CONF" << 'EOF'
saudi:السعودية:Saudi Arabia:1
egypt:مصر:Egypt:1
EOF
}

_fm_bot_countries_list_all() {
    _fm_bot_ensure_countries_conf
    cat "$BOT_COUNTRIES_CONF" 2>/dev/null
}

_fm_bot_countries_list_enabled() {
    _fm_bot_countries_list_all | awk -F: '$4=="1"'
}

# The enabled countries this app has at least one file under. An empty
# app means "don't filter", which keeps every older caller unchanged.
# node (new, optional, trailing so every pre-existing caller that omits
# it is unaffected): filters by what THAT node's customer would actually
# get delivered, same reasoning as the app filter above — offering a
# country with only another node's file is a dead end discovered after
# the customer already picked it.
_fm_bot_countries_list_for_app() {
    local app="${1:-}" node="${2:-}" line slug
    if [[ -z "$app" ]]; then _fm_bot_countries_list_enabled; return 0; fi
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        slug="${line%%:*}"
        _fm_bot_appfile_has_prefix "$app" "$(_fm_bot_node_country_simtype_key "$node" "$slug" "")" \
            && printf '%s\n' "$line"
    done <<< "$(_fm_bot_countries_list_enabled)"
}

_fm_bot_country_get() {
    local slug="$1"
    _fm_bot_countries_list_all | awk -F: -v s="$slug" '$1==s{print; exit}'
}

_fm_bot_country_name() {
    local slug="$1" lang="$2" line
    line=$(_fm_bot_country_get "$slug") || return 1
    [[ -n "$line" ]] || return 1
    IFS=: read -r _s c_ar c_en _enabled <<< "$line"
    [[ "$lang" == "en" ]] && printf '%s' "$c_en" || printf '%s' "$c_ar"
}

# Same idea as _fm_bot_region_names, for the country step.
_fm_bot_country_names() {
    local lang="${1:-ar}" app="${2:-}" node="${3:-}" names="" line
    while IFS= read -r line; do
        [[ -z "$line" ]] && continue
        local s n_ar n_en
        IFS=: read -r s n_ar n_en _enabled <<< "$line"
        local n="$n_ar"; [[ "$lang" == "en" ]] && n="$n_en"
        [[ -n "$n" ]] && names+="${n}"$'\n'
    done <<< "$(_fm_bot_countries_list_for_app "$app" "$node")"
    printf '%s' "$names"
}

_fm_bot_send_country_list() {
    local chat_id="$1" app="${2:-}" node="${3:-}" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names=$(_fm_bot_country_names "$lang" "$app" "$node")
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg COUNTRY_PROMPT "$lang")" "$names"
}

# Maps a tapped button's text back to a country slug, checking both
# languages (same reasoning as _fm_bot_region_find_by_text).
_fm_bot_country_find_by_text() {
    local text="$1" app="${2:-}" node="${3:-}" lg line
    for lg in ar en; do
        while IFS= read -r line; do
            [[ -z "$line" ]] && continue
            local s n_ar n_en
            IFS=: read -r s n_ar n_en _enabled <<< "$line"
            local n="$n_ar"; [[ "$lg" == "en" ]] && n="$n_en"
            [[ "$n" == "$text" ]] && { printf '%s' "$s"; return 0; }
        done <<< "$(_fm_bot_countries_list_for_app "$app" "$node")"
    done
    return 1
}

_fm_bot_simtypes_list_for_country() {
    local country="$1" app="${2:-}" node="${3:-}" name
    [[ -f "$BOT_SIMTYPES_CONF" ]] || return 0
    while IFS= read -r name; do
        [[ -z "$name" ]] && continue
        if [[ -z "$app" ]] || _fm_bot_appfile_has_prefix "$app" "$(_fm_bot_node_country_simtype_key "$node" "$country" "$name")"; then
            printf '%s\n' "$name"
        fi
    done <<< "$(awk -F: -v c="$country" '$1==c{print $2}' "$BOT_SIMTYPES_CONF")"
}

_fm_bot_send_simtype_list() {
    local chat_id="$1" country="$2" app="${3:-}" node="${4:-}" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names=$(_fm_bot_simtypes_list_for_country "$country" "$app" "$node")
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg SIMTYPE_PROMPT "$lang")" "$names"
}

_fm_bot_simtype_find_by_text() {
    local country="$1" text="$2" app="${3:-}" node="${4:-}"
    _fm_bot_simtypes_list_for_country "$country" "$app" "$node" | grep -Fx "$text"
}

# Folds a (country, simtype) pick into a single string usable exactly
# where _fm_bot_appfile_* already expects a "type" — see the section
# comment above.
_fm_bot_country_simtype_key() {
    local country="$1" simtype="$2"
    if [[ -z "$simtype" ]]; then
        printf '%s' "$(_fm_bot_sanitize_slug "$country")"
    else
        printf '%s_%s' "$(_fm_bot_sanitize_slug "$country")" "$(_fm_bot_sanitize_slug "$simtype")"
    fi
}

# One level ABOVE _fm_bot_country_simtype_key: folds which VPN node the
# customer picked (see _fm_bot_node_selected_get) into the same
# composite-key trick, so a file uploaded for Germany and one uploaded
# for Saudi under the identical (app, country, SIM-type, file-type)
# resolve to two different stored files instead of colliding — the
# exact bash mirror of bot_node_country_simtype_key in panel.py.
# node="" (no node selected — a single-box deployment, or a customer
# who never picked a node-mode region) reproduces
# _fm_bot_country_simtype_key's own output exactly, so every file and
# every flow that predates this feature keeps resolving unchanged.
_fm_bot_node_country_simtype_key() {
    local node="$1" country="$2" simtype="$3" prefix
    prefix=$(_fm_bot_country_simtype_key "$country" "$simtype")
    if [[ -z "$node" ]]; then
        printf '%s' "$prefix"
    else
        printf '%s_%s' "$(_fm_bot_sanitize_slug "$node")" "$prefix"
    fi
}

# File type: one more optional step layered on top of the (country, SIM
# type) pair above, letting the admin attach more than one file to the
# exact same pair (e.g. two config variants for the same operator). Rows
# are "prefix:name" where prefix is exactly whatever
# _fm_bot_country_simtype_key already produced for that pair — not raw
# country/simtype fields — so this never needs to know about countries or
# SIM types itself, and nothing here changes if either of those change
# shape later. A pair with no file types configured skips this question
# entirely, exactly like a country with no SIM types skips that one.
_fm_bot_filetypes_list_for_prefix() {
    local prefix="$1" app="${2:-}" name
    [[ -f "$BOT_FILETYPES_CONF" ]] || return 0
    while IFS= read -r name; do
        [[ -z "$name" ]] && continue
        # These rows carry no app of their own, so without this check a
        # label uploaded for one app is offered under every other.
        if [[ -z "$app" ]] || _fm_bot_appfile_has_type "$app" "$(_fm_bot_filetype_key "$prefix" "$name")"; then
            printf '%s\n' "$name"
        fi
    done <<< "$(awk -F: -v p="$prefix" '$1==p{print $2}' "$BOT_FILETYPES_CONF")"
}

_fm_bot_send_filetype_list() {
    local chat_id="$1" prefix="$2" app="${3:-}" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names=$(_fm_bot_filetypes_list_for_prefix "$prefix" "$app")
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg FILETYPE_PROMPT "$lang")" "$names" 1
}

_fm_bot_filetype_find_by_text() {
    local prefix="$1" text="$2" app="${3:-}"
    _fm_bot_filetypes_list_for_prefix "$prefix" "$app" | grep -Fx "$text"
}

# Folds a chosen file type onto the (country, SIM type) prefix — same
# "single type string" trick as _fm_bot_country_simtype_key, just one
# level deeper, so every existing appfile/order/render/deliver path keeps
# working unchanged.
_fm_bot_filetype_key() {
    local prefix="$1" filetype="$2"
    if [[ -z "$filetype" ]]; then
        printf '%s' "$prefix"
    else
        printf '%s_%s' "$prefix" "$(_fm_bot_sanitize_slug "$filetype")"
    fi
}

# Shared by both places a (country, SIM type) prefix becomes final: right
# after SIM type is picked, and right after country when that country has
# no SIM types at all. Either asks the file-type question (if the admin
# configured more than one file for this exact prefix) or, same as
# before this feature existed, goes straight to delivery.
_fm_bot_on_country_simtype_prefix_ready() {
    local chat_id="$1" flow="$2" app="$3" prefix="$4"
    if [[ -n "$(_fm_bot_filetypes_list_for_prefix "$prefix" "$app")" ]]; then
        _fm_bot_goto "$chat_id" "${flow}_filetype:${app}:${prefix}"
        _fm_bot_send_filetype_list "$chat_id" "$prefix" "$app"
    else
        _fm_bot_on_apptype_chosen "$chat_id" "$flow" "$app" "$prefix"
    fi
}

_fm_bot_send_device_list() {
    local chat_id="$1" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names="$(_fm_bot_btn_android "$lang")"$'\n'"$(_fm_bot_btn_iphone "$lang")"
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg DEVICE_PROMPT "$lang")" "$names"
}

_fm_bot_btn_android() { _fm_bot_msg BTN_ANDROID "$1"; }
_fm_bot_btn_iphone()  { _fm_bot_msg BTN_IPHONE "$1"; }

# Maps a tapped device button back to "android"/"ios", checking both
# languages, same reasoning as _fm_bot_region_find_by_text.
_fm_bot_device_find_by_text() {
    local text="$1" lg
    for lg in ar en; do
        [[ "$text" == "$(_fm_bot_btn_android "$lg")" ]] && { printf 'android'; return 0; }
        [[ "$text" == "$(_fm_bot_btn_iphone "$lg")" ]] && { printf 'ios'; return 0; }
    done
    return 1
}

# ── Subscription duration: 1 month vs 2 months ──────────────────────────
# Asked right after "Subscribe" is tapped, before region/device/app even
# start — the picked tier then rides along as part of the flow name
# itself ("subscribe1"/"subscribe2") through every step after this one,
# same trick "trial"/"changehwid" already use. See _fm_bot_cmd_subscribe
# for how the tier selects which MONTHLY*/MONTHLY2* plan settings apply.
_fm_bot_btn_month1() { _fm_bot_msg BTN_MONTH1 "$1"; }
_fm_bot_btn_month2() { _fm_bot_msg BTN_MONTH2 "$1"; }

_fm_bot_send_duration_list() {
    local chat_id="$1" lang; lang=$(_fm_bot_lang_get "$chat_id")
    local names; names="$(_fm_bot_btn_month1 "$lang")"$'\n'"$(_fm_bot_btn_month2 "$lang")"
    _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg SUBSCRIBE_DURATION_PROMPT "$lang")" "$names"
}

# Maps a tapped duration button back to "1"/"2", checking both languages,
# same reasoning as _fm_bot_device_find_by_text.
_fm_bot_duration_find_by_text() {
    local text="$1" lg
    for lg in ar en; do
        [[ "$text" == "$(_fm_bot_btn_month1 "$lg")" ]] && { printf '1'; return 0; }
        [[ "$text" == "$(_fm_bot_btn_month2 "$lg")" ]] && { printf '2'; return 0; }
    done
    return 1
}

# ── Which platform(s) each app is meant for ─────────────────────────────
# One row per app: app:platform. An app with no row (or an unrecognized
# value) is "both" — so this whole feature is a no-op until an admin
# actually tags an app, and every app already uploaded before this
# feature existed keeps showing up for every device.
_fm_bot_appfile_platform_get() {
    local app="$1" p
    [[ -f "$BOT_APP_PLATFORM_DB" ]] || { echo "both"; return; }
    p=$(awk -F: -v a="$app" '$1==a{print $2; f=1} END{if(!f) print ""}' "$BOT_APP_PLATFORM_DB")
    case "$p" in android|ios) printf '%s' "$p" ;; *) printf 'both' ;; esac
}

_fm_bot_appfile_platform_set() {
    local app="$1" platform="$2"
    case "$platform" in android|ios|both) : ;; *) return 1 ;; esac
    mkdir -p "$(dirname "$BOT_APP_PLATFORM_DB")" 2>/dev/null
    touch "$BOT_APP_PLATFORM_DB"
    grep -v "^${app}:" "$BOT_APP_PLATFORM_DB" > "${BOT_APP_PLATFORM_DB}.tmp" 2>/dev/null
    mv -f "${BOT_APP_PLATFORM_DB}.tmp" "$BOT_APP_PLATFORM_DB"
    echo "${app}:${platform}" >> "$BOT_APP_PLATFORM_DB"
}

# Same list as _fm_bot_appfile_apps_list, filtered to apps tagged for
# this device (or tagged "both", or untagged at all).
_fm_bot_appfile_apps_list_for_platform() {
    local platform="$1" app app_p
    while IFS= read -r app; do
        [[ -z "$app" ]] && continue
        app_p=$(_fm_bot_appfile_platform_get "$app")
        [[ "$app_p" == "both" || "$app_p" == "$platform" ]] && printf '%s\n' "$app"
    done <<< "$(_fm_bot_appfile_apps_list)"
}


# ── Editable sales-bot messages ─────────────────────────────────────────
# Every string the sales bot sends — customer-facing (bilingual) or an
# admin notification the sales bot itself generates (Arabic-only) — has a
# key here. An admin can override any of them from the panel's "بوت
# المبيعات - رسائل" tab; anything not overridden falls back to the literal
# text below, so shipping this changes nothing on its own.
#
# Storage mirrors _fm_bot_get_plan/_fm_bot_set_plan (KEY_AR="..."/
# KEY_EN="..." lines, same quote/backslash escaping) but is intentionally
# a separate file/function pair — plans are a handful of settings sourced
# by key name; messages are a much larger catalog read only by
# _fm_bot_msg, and every value already carries the project's %0A
# newline-encoding convention rather than real newlines (see
# send_telegram_msg_to's comment on why this is never `source`d or passed
# through printf).
BOT_MESSAGES_CONF="/etc/firewallfalcon/bot_messages.conf"

_fm_bot_ensure_messages_conf() {
    [[ -f "$BOT_MESSAGES_CONF" ]] || { mkdir -p "$(dirname "$BOT_MESSAGES_CONF")" 2>/dev/null; touch "$BOT_MESSAGES_CONF"; }
}

# The literal default for one key/lang, before any {PLACEHOLDER}
# substitution. Admin-only keys (no EN variant is ever shown or used)
# still accept a $lang argument for a uniform call signature — they just
# ignore it and always return the Arabic text.
_fm_bot_msg_default() {
    local key="$1" lang="$2"
    case "$key" in
        BTN_TRIAL) [[ "$lang" == en ]] && echo "🎁 Free Trial" || echo "🎁 تجربة مجانية" ;;
        BTN_SUBSCRIBE) [[ "$lang" == en ]] && echo "💳 Subscribe" || echo "💳 اشتراك شهري" ;;
        BTN_BALANCE) [[ "$lang" == en ]] && echo "💰 My Balance" || echo "💰 رصيدي" ;;
        BTN_MYACCOUNT) [[ "$lang" == en ]] && echo "📱 My Accounts" || echo "📱 حساباتي" ;;
        BTN_REFERRAL) [[ "$lang" == en ]] && echo "🔗 Referral Link" || echo "🔗 رابط الإحالة" ;;
        BTN_SUPPORT) [[ "$lang" == en ]] && echo "☎️ Support" || echo "☎️ الدعم" ;;
        BTN_CANCEL) [[ "$lang" == en ]] && echo "❌ Cancel" || echo "❌ إلغاء" ;;
        BTN_HWID_YES) [[ "$lang" == en ]] && echo "✅ Yes, continue" || echo "✅ نعم، تابع" ;;
        BTN_HWID_NO) [[ "$lang" == en ]] && echo "✏️ No, send another" || echo "✏️ لا، أرسل غيره" ;;
        BTN_MAINMENU) [[ "$lang" == en ]] && echo "🔙 Main Menu" || echo "🔙 القائمة الرئيسية" ;;
        BTN_BACK) [[ "$lang" == en ]] && echo "↩️ Back" || echo "↩️ رجوع" ;;
        BTN_RESEND_FILE) [[ "$lang" == en ]] && echo "📄 Resend {USERNAME} file" || echo "📄 أعد إرسال ملف {USERNAME}" ;;
        BTN_LANGTOGGLE) [[ "$lang" == en ]] && echo "🌐 العربية" || echo "🌐 English" ;;
        WELCOME) [[ "$lang" == en ]] && echo "👋 <b>Welcome!</b>%0AMonthly plan: {PRICE} SAR%0A%0AUse the buttons below — no commands needed. (Typing /trial, /subscribe, etc. still works too.)" || echo "👋 <b>أهلًا بك!</b>%0Aالاشتراك الشهري: {PRICE} ريال%0A%0Aاستخدم الأزرار بالأسفل — بدون أي أوامر. (يمكنك أيضًا كتابة /trial أو /subscribe إن أردت.)" ;;
        APPLIST_PROMPT) [[ "$lang" == en ]] && echo "📁 Choose an app:" || echo "📁 اختر تطبيقًا:" ;;
        TYPELIST_PROMPT) [[ "$lang" == en ]] && echo "📁 <b>{APP}</b> — choose a file type:" || echo "📁 <b>{APP}</b> — اختر نوع الملف:" ;;
        INVALID_APP_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the app buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار التطبيقات، أو {MAINMENU_BTN} للإلغاء." ;;
        INVALID_TYPE_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the file-type buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار نوع الملف، أو {MAINMENU_BTN} للإلغاء." ;;
        FALLBACK_UNKNOWN) [[ "$lang" == en ]] && echo "❓ Not sure what you mean — use the buttons below, or send /help." || echo "❓ لم أفهم طلبك — استخدم الأزرار بالأسفل، أو أرسل /help." ;;
        BTN_ANDROID) [[ "$lang" == en ]] && echo "📱 Android" || echo "📱 أندرويد" ;;
        BTN_IPHONE) [[ "$lang" == en ]] && echo "🍏 iPhone" || echo "🍏 آيفون" ;;
        REGION_PROMPT) [[ "$lang" == en ]] && echo "🌍 Choose a server type:" || echo "🌍 اختر نوع السيرفر:" ;;
        INVALID_REGION_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the server-type buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار نوع السيرفر، أو {MAINMENU_BTN} للإلغاء." ;;
        REGION_REDIRECT) [[ "$lang" == en ]] && echo "🌍 For <b>{REGION}</b>, continue here through this bot:%0A{LINK}" || echo "🌍 لخدمة <b>{REGION}</b>، تابع من هنا عبر البوت التالي:%0A{LINK}" ;;
        DEVICE_PROMPT) [[ "$lang" == en ]] && echo "📱 Choose your device type:" || echo "📱 اختر نوع جهازك:" ;;
        INVALID_DEVICE_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the device-type buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد زرّي نوع الجهاز، أو {MAINMENU_BTN} للإلغاء." ;;
        COUNTRY_PROMPT) [[ "$lang" == en ]] && echo "🌐 Choose the country:" || echo "🌐 اختر الدولة:" ;;
        INVALID_COUNTRY_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the country buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار الدولة، أو {MAINMENU_BTN} للإلغاء." ;;
        SIMTYPE_PROMPT) [[ "$lang" == en ]] && echo "📶 Choose the SIM type:" || echo "📶 اختر نوع الشريحة:" ;;
        INVALID_SIMTYPE_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the SIM-type buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار نوع الشريحة، أو {MAINMENU_BTN} للإلغاء." ;;
        FILETYPE_PROMPT) [[ "$lang" == en ]] && echo "📄 Choose the file type:" || echo "📄 اختر نوع الملف:" ;;
        INVALID_FILETYPE_CHOICE) [[ "$lang" == en ]] && echo "❌ Please tap one of the file-type buttons, or {MAINMENU_BTN} to cancel." || echo "❌ اضغط أحد أزرار نوع الملف، أو {MAINMENU_BTN} للإلغاء." ;;
        INVALID_HWID) [[ "$lang" == en ]] && echo "❌ Invalid device ID — no spaces, ':' or '/', max 128 characters." || echo "❌ معرّف الجهاز غير صالح — بدون مسافات أو ':' أو '/'، وبحد أقصى 128 حرفًا." ;;
        INVALID_HWID_NPVS) [[ "$lang" == en ]] && echo "❌ That is not an NPV Tunnel device ID.%0AExpected: <b>44 characters</b> copied from inside the app (Device ID).%0AYou sent: <code>{HWID}</code>%0A%0ACopy it from the app and send it again, or tap «{MAINMENU_BTN}» to start over." || echo "❌ هذا ليس معرّف جهاز NPV Tunnel.%0Aالمطلوب: <b>44 حرفًا</b> تنسخها من داخل التطبيق (Device ID / معرّف الجهاز).%0Aالذي أرسلته: <code>{HWID}</code>%0A%0Aانسخه من التطبيق وأعد إرساله هنا، أو اضغط «{MAINMENU_BTN}» للبدء من جديد." ;;
        INVALID_HWID_NPVT) [[ "$lang" == en ]] && echo "❌ That is not an NPV Tunnel device ID.%0AThe app shows it in one of two shapes — send whichever yours displays:%0A• <b>64 characters</b> of 0-9 and a-f%0A• or a <b>UUID</b> like <code>95E6865B-1A1B-449A-A023-5D2A79AC8B1D</code>%0A%0AYou sent: <code>{HWID}</code>%0A%0ACopy it from the app exactly as shown (keep the dashes) and send it again, or tap «{MAINMENU_BTN}» to start over." || echo "❌ هذا ليس معرّف جهاز NPV Tunnel.%0Aالتطبيق يعرضه بإحدى صيغتين — أرسل الصيغة التي تظهر عندك:%0A• <b>64 خانة</b> من الأرقام والحروف a-f%0A• أو <b>UUID</b> مثل <code>95E6865B-1A1B-449A-A023-5D2A79AC8B1D</code>%0A%0Aالذي أرسلته: <code>{HWID}</code>%0A%0Aانسخه من التطبيق كما هو تمامًا (مع الشرطات) وأعد إرساله، أو اضغط «{MAINMENU_BTN}» للبدء من جديد." ;;
        INVALID_HWID_LEN) [[ "$lang" == en ]] && echo "❌ That device ID is not complete.%0AExpected: exactly <b>{LEN} characters</b> copied from inside the app.%0AYou sent: <code>{HWID}</code> — <b>{GOT}</b> characters.%0A%0ACopy the whole thing and send it again, or tap «{MAINMENU_BTN}» to start over." || echo "❌ معرّف الجهاز غير مكتمل.%0Aالمطلوب: <b>{LEN} محرفًا</b> بالضبط تنسخها من داخل التطبيق.%0Aالذي أرسلته: <code>{HWID}</code> — <b>{GOT}</b> محرفًا.%0A%0Aانسخه كاملًا وأعد إرساله، أو اضغط «{MAINMENU_BTN}» للبدء من جديد." ;;
        HWID_CONFIRM) [[ "$lang" == en ]] && echo "🔎 <b>Confirm your device ID</b>%0A%0AYour account will be created on this ID:%0A<code>{HWID}</code>%0A%0AMake sure it is your own device — once created, the file works on this device only.%0A%0AShall we continue?" || echo "🔎 <b>تأكيد معرّف الجهاز</b>%0A%0Aسيُنشأ حسابك على هذا المعرّف:%0A<code>{HWID}</code>%0A%0Aتأكّد أنه معرّف جهازك أنت — بعد الإنشاء يعمل الملف على هذا الجهاز وحده.%0A%0Aهل نتابع؟" ;;
        HWID_CONFIRM_RETRY) [[ "$lang" == en ]] && echo "✏️ No problem — send the correct device ID now." || echo "✏️ حسنًا — أرسل معرّف الجهاز الصحيح الآن." ;;
        FLOW_CANCELLED) [[ "$lang" == en ]] && echo "❌ Cancelled. No account was created and nothing was charged.%0AStart again whenever you like." || echo "❌ تم الإلغاء. لم يُنشأ أي حساب ولم يُخصم أي رصيد.%0Aتقدر تبدأ من جديد وقت ما تحب." ;;
        HWID_CONFIRM_LOST) [[ "$lang" == en ]] && echo "⚠️ That step has expired. Please send your device ID again." || echo "⚠️ انتهت صلاحية هذه الخطوة. أرسل معرّف الجهاز من جديد من فضلك." ;;
        PROVISION_FAILED) [[ "$lang" == en ]] && echo "❌ Failed to create the account. Try again or contact the admin." || echo "❌ فشل إنشاء الحساب. حاول مرة أخرى أو تواصل مع الأدمن." ;;
        MESSAGE_SENT_TO_ADMIN) [[ "$lang" == en ]] && echo "✅ Your message was sent to the admin." || echo "✅ تم إرسال رسالتك إلى الأدمن." ;;
        TRIAL_ASK_HWID) [[ "$lang" == en ]] && echo "📲 Send your device ID (HWID) now — it will be used as both your username and password." || echo "📲 أرسل معرّف جهازك (HWID) الآن — سيُستخدم كاسم مستخدم وكلمة مرور معًا." ;;
        TRIAL_CMD_USAGE) [[ "$lang" == en ]] && echo "✋ Send your device ID with the command, e.g. <code>/trial abc123device</code>." || echo "✋ أرسل معرّف جهازك (HWID) مع الأمر، مثال: <code>/trial abc123device</code>." ;;
        TRIAL_LIMIT_REACHED) [[ "$lang" == en ]] && echo "❌ You've already used your {MAX_USES} free trial(s) this month. Send <code>/subscribe {HWID}</code> to buy a monthly plan, or come back next month." || echo "❌ لقد استخدمت بالفعل {MAX_USES} من محاولات التجربة المجانية هذا الشهر. أرسل <code>/subscribe {HWID}</code> للاشتراك الشهري، أو عد الشهر القادم." ;;
        TRIAL_DEVICE_USED) [[ "$lang" == en ]] && echo "❌ This device has already used its free trial this month." || echo "❌ هذا الجهاز استخدم تجربته المجانية بالفعل هذا الشهر." ;;
        TRIAL_DEVICE_TAKEN) [[ "$lang" == en ]] && echo "❌ This device ID is already registered to a different account (or has an active paid subscription). Contact the admin if you believe this is a mistake." || echo "❌ معرّف الجهاز هذا مسجّل بالفعل لحساب آخر (أو لديه اشتراك مدفوع نشط). تواصل مع الأدمن إن كنت تعتقد أن هذا خطأ." ;;
        TRIAL_SUCCESS_NEW) [[ "$lang" == en ]] && echo "✅ <b>Trial Activated!</b>%0A%0A🆔 Device ID: <code>{HWID}</code>%0A(used as both username &amp; password)%0A⏳ Duration: {HOURS}h%0A📱 Devices: {DEVICES}%0A📊 Bandwidth: {BW}%0AExpires: {EXPIRE}" || echo "✅ <b>تم تفعيل التجربة!</b>%0A%0A🆔 معرّف الجهاز: <code>{HWID}</code>%0A(يُستخدم كاسم مستخدم وكلمة مرور معًا)%0A⏳ المدة: {HOURS} ساعة%0A📱 عدد الأجهزة: {DEVICES}%0A📊 الباندويث: {BW}%0Aينتهي في: {EXPIRE}" ;;
        TRIAL_SUCCESS_RENEWED) [[ "$lang" == en ]] && echo "🔄 <b>Trial Renewed!</b> (same device as before)%0A%0A🆔 Device ID: <code>{HWID}</code>%0A(used as both username &amp; password)%0A⏳ Duration: {HOURS}h%0A📱 Devices: {DEVICES}%0A📊 Bandwidth: {BW}%0AExpires: {EXPIRE}" || echo "🔄 <b>تم تجديد التجربة!</b> (نفس الجهاز السابق)%0A%0A🆔 معرّف الجهاز: <code>{HWID}</code>%0A(يُستخدم كاسم مستخدم وكلمة مرور معًا)%0A⏳ المدة: {HOURS} ساعة%0A📱 عدد الأجهزة: {DEVICES}%0A📊 الباندويث: {BW}%0Aينتهي في: {EXPIRE}" ;;
        TRIAL_ADMIN_NEW) echo "🆓 <b>تجربة جديدة</b>%0Aمن: <a href=\"tg://openmessage?user_id={CHAT_ID}\">{CHAT_ID}</a>%0Aالجهاز: {HWID}" ;;
        TRIAL_ADMIN_RENEWED) echo "🆓 <b>تم تجديد تجربة</b>%0Aمن: <a href=\"tg://openmessage?user_id={CHAT_ID}\">{CHAT_ID}</a>%0Aالجهاز: {HWID}" ;;
        BTN_MONTH1) [[ "$lang" == en ]] && echo "📅 1 Month" || echo "📅 شهر واحد" ;;
        BTN_MONTH2) [[ "$lang" == en ]] && echo "📅 2 Months" || echo "📅 شهرين" ;;
