        REFERRAL_MSG) [[ "$lang" == en ]] && echo "🔗 <b>Your Referral Link</b>%0A{LINK}%0A%0A👥 People you referred: {SIGNUPS}%0A💳 Of those, went monthly: {PAID}%0A%0AShare your link — when enough people join or subscribe through it, you earn wallet credit automatically." || echo "🔗 <b>رابط الإحالة الخاص بك</b>%0A{LINK}%0A%0A👥 عدد من قمت بإحالتهم: {SIGNUPS}%0A💳 منهم اشتركوا شهريًا: {PAID}%0A%0Aشارك رابطك — عندما يصل عدد كافٍ من المُحالين أو المشتركين، تحصل تلقائيًا على رصيد في محفظتك." ;;
        APPFILE_UNAVAILABLE) [[ "$lang" == en ]] && echo "❌ That file is no longer available." || echo "❌ هذا الملف لم يعد متوفرًا." ;;
        APPFILE_NONE_FOR_APP) [[ "$lang" == en ]] && echo "📭 There are no files available for <b>{APP}</b> right now.%0A%0APick another app from the list below." || echo "📭 لا توجد أي ملفات متاحة حاليًا لتطبيق <b>{APP}</b>.%0A%0Aاختر تطبيقًا آخر من القائمة بالأسفل." ;;
        APPFILE_CAPTION) [[ "$lang" == en ]] && echo "📁 {APP} — {TYPE}" || echo "📁 {APP} — {TYPE}" ;;
        HWID_GUIDE_CAPTION) [[ "$lang" == en ]] && echo "📸 Here's where to find your HWID in {APP}" || echo "📸 من هنا تجد HWID في تطبيق {APP}" ;;
        FILE_GUIDE_CAPTION) [[ "$lang" == en ]] && echo "📖 How to add the file inside {APP}" || echo "📖 طريقة إضافة الملف داخل تطبيق {APP}" ;;
        SUPPORT_ASK) [[ "$lang" == en ]] && echo "✍️ Type your message now — it goes straight to the admin." || echo "✍️ اكتب رسالتك الآن — ستصل مباشرة إلى الأدمن." ;;
        APPEAL_CMD_USAGE) [[ "$lang" == en ]] && echo "✋ Send a message after the command, e.g. <code>/appeal I have a question</code>." || echo "✋ أرسل رسالة بعد الأمر، مثال: <code>/appeal لدي سؤال</code>." ;;
        SUPPORT_ADMIN_FORWARD) echo "✉️ <b>رسالة من مستخدم البوت</b>%0Aمن: <a href=\"tg://openmessage?user_id={CHAT_ID}\">{CHAT_ID}</a>%0Aالرسالة: {TEXT}" ;;
        SUPPORT_REPLY_HEADER) [[ "$lang" == en ]] && echo "☎️ <b>Reply from support</b>" || echo "☎️ <b>رد من الدعم</b>" ;;
        SUPPORT_REPLY_SENT) echo "✅ وصل ردّك إلى <a href=\"tg://openmessage?user_id={CHAT_ID}\">{CHAT_ID}</a>." ;;
        BROADCAST_STARTED) echo "📢 <b>بدأ إرسال الإعلان</b>%0Aعدد المستلمين: {TOTAL}%0A%0Aالإرسال يجري في الخلفية — البوت يواصل خدمة العملاء أثناءه، وستصلك النتيجة عند انتهائه." ;;
        BROADCAST_DONE) echo "📢 <b>انتهى إرسال الإعلان</b>%0A✅ وصل: {SENT}%0A❌ لم يصل: {FAILED}%0A%0A(عادةً «لم يصل» تعني أن المستخدم حظر البوت أو حذف محادثته.)" ;;
        BAN_BLOCKED) [[ "$lang" == en ]] && echo "🚫 <b>You are banned from this bot.</b>%0ASend a message (or <code>/appeal your message</code>) to contact the admin." || echo "🚫 <b>أنت محظور من هذا البوت.</b>%0Aأرسل رسالة (أو استخدم <code>/appeal رسالتك</code>) للتواصل مع الأدمن." ;;
        BAN_APPEAL_ADMIN) echo "🚨 <b>استئناف حظر</b>%0Aمن: <a href=\"tg://openmessage?user_id={CHAT_ID}\">{CHAT_ID}</a>%0Aالرسالة: {TEXT}%0A%0Aلفك الحظر: <code>/unban {CHAT_ID}</code>" ;;
        *) echo "" ;;
    esac
}

