# One stored override line, KEY_LANG="value" — read without sourcing, for
# the same reason _fm_bot_get_plan avoids it (free text from an admin,
# possibly carrying "$(...)" or backticks).
_fm_bot_msg() {
    local key="$1" lang="$2"
    _fm_bot_ensure_messages_conf
    local line val vlen
    line=$(grep "^${key}_${lang^^}=" "$BOT_MESSAGES_CONF" 2>/dev/null | tail -1)
    if [[ -n "$line" ]]; then
        val="${line#*=}"
        vlen=${#val}
        if [[ "$vlen" -ge 2 && "${val:0:1}" == '"' && "${val:vlen-1:1}" == '"' ]]; then
            val="${val:1:vlen-2}"
        fi
        val="${val//\\\"/\"}"
        val="${val//\\\\/\\}"
        printf '%s' "$val"
        return
    fi
    _fm_bot_msg_default "$key" "$lang"
}

# _fm_bot_msg() plus {TOKEN}/value substitution pairs, e.g.:
#   _fm_bot_msg_fmt TRIAL_LIMIT_REACHED "$lang" MAX_USES "$max_uses" HWID "$hwid"
_fm_bot_msg_fmt() {
    local key="$1" lang="$2"; shift 2
    local msg; msg=$(_fm_bot_msg "$key" "$lang")
    while [[ $# -ge 2 ]]; do
        msg="${msg//\{$1\}/$2}"
        shift 2
    done
    printf '%s' "$msg"
}

# Stores an override. Real newlines (typed with Enter in the panel's
# textarea) become the project's %0A token rather than being stripped —
# unlike _fm_bot_set_plan's single-line settings, a message legitimately
# wants paragraph breaks.
_fm_bot_set_msg() {
    local key="$1" lang="$2" val="$3" esc
    _fm_bot_ensure_messages_conf
    val="${val//$'\r'/}"
    val="${val//$'\n'/%0A}"
    esc="${val//\\/\\\\}"
    esc="${esc//\"/\\\"}"
    local field="${key}_${lang^^}"
    grep -v "^${field}=" "$BOT_MESSAGES_CONF" > "${BOT_MESSAGES_CONF}.tmp" 2>/dev/null
    mv -f "${BOT_MESSAGES_CONF}.tmp" "$BOT_MESSAGES_CONF"
    printf '%s="%s"\n' "$field" "$esc" >> "$BOT_MESSAGES_CONF"
}

# Deletes an override so the key falls back to its default again.
_fm_bot_reset_msg() {
    local key="$1" lang="$2"
    _fm_bot_ensure_messages_conf
    grep -v "^${key}_${lang^^}=" "$BOT_MESSAGES_CONF" > "${BOT_MESSAGES_CONF}.tmp" 2>/dev/null
    mv -f "${BOT_MESSAGES_CONF}.tmp" "$BOT_MESSAGES_CONF"
}

# ── Wallets (SAR balance per Telegram user id) ──────────────────────────
_fm_bot_wallet_get() {
    local tg="$1"
    # The owner never pays himself: an unlimited balance here is what
    # lets the admin walk a customer's purchase through to the end
    # without inventing a fake top-up first. _fm_bot_wallet_add below
    # refuses to write for the same chat, so nothing is ever deducted
    # and no real balance row is created for the admin.
    _fm_bot_is_admin_chat "$tg" && { echo "${_FM_BOT_ADMIN_UNLIMITED:-999999}"; return; }
    [[ -f "$BOT_WALLETS_DB" ]] || { echo "0"; return; }
    awk -F: -v t="$tg" '$1==t{print $2; f=1} END{if(!f) print "0"}' "$BOT_WALLETS_DB"
}

_fm_bot_wallet_set() {
    local tg="$1" amount="$2"
    mkdir -p "$(dirname "$BOT_WALLETS_DB")" 2>/dev/null
    touch "$BOT_WALLETS_DB"
    _fm_db_replace_row "$BOT_WALLETS_DB" ":" 1 "$tg" "${tg}:${amount}"
}

# Adds (or, with a negative amount, subtracts from) a wallet — never lets
# it go below zero. Prints the new balance.
_fm_bot_wallet_add() {
    local tg="$1" delta="$2"
    _fm_bot_is_admin_chat "$tg" && { echo "${_FM_BOT_ADMIN_UNLIMITED:-999999}"; return; }
    local cur; cur=$(_fm_bot_wallet_get "$tg")
    local new; new=$(awk -v c="$cur" -v d="$delta" 'BEGIN{v=c+d; if(v<0)v=0; printf "%.2f", v}')
    _fm_bot_wallet_set "$tg" "$new"
    echo "$new"
}

# ── Coupons: code:type(pct|fixed):value:max_uses(0=unlimited):used:enabled(1/0) ──
# Codes are always normalized to uppercase on the way in and out, so
# lookups never need a case-insensitive match.
_fm_bot_coupon_get() {
    local code="${1^^}"
    [[ -f "$BOT_COUPONS_DB" ]] || return 1
    grep "^${code}:" "$BOT_COUPONS_DB" | tail -1
}

_fm_bot_coupon_add() {
    local code="${1^^}" type="$2" value="$3" max_uses="${4:-0}"
    mkdir -p "$(dirname "$BOT_COUPONS_DB")" 2>/dev/null
    touch "$BOT_COUPONS_DB"
    sed -i "/^${code}:/d" "$BOT_COUPONS_DB"
    echo "${code}:${type}:${value}:${max_uses}:0:1" >> "$BOT_COUPONS_DB"
}

_fm_bot_coupon_del() {
    local code="${1^^}"
    [[ -f "$BOT_COUPONS_DB" ]] && sed -i "/^${code}:/d" "$BOT_COUPONS_DB"
}

# Prints the discounted price for $2 with coupon $1 applied — unchanged
# price and a non-zero return if the coupon doesn't exist, is disabled,
# or has hit its use cap. Read-only: does NOT burn a use (see
# _fm_bot_coupon_increment_usage, called only once an order is actually
# approved/paid, so a customer previewing a code can't exhaust it).
_fm_bot_coupon_preview() {
    local code="${1^^}" price="$2"
    local line; line=$(_fm_bot_coupon_get "$code")
    [[ -n "$line" ]] || { echo "$price"; return 1; }
    local c_code c_type c_val c_max c_used c_en
    IFS=: read -r c_code c_type c_val c_max c_used c_en <<< "$line"
    [[ "$c_en" == "1" ]] || { echo "$price"; return 1; }
    if [[ "$c_max" =~ ^[0-9]+$ && "$c_max" -gt 0 && "$c_used" -ge "$c_max" ]]; then echo "$price"; return 1; fi
    if [[ "$c_type" == "pct" ]]; then
        awk -v p="$price" -v v="$c_val" 'BEGIN{r=p-(p*v/100); if(r<0)r=0; printf "%.2f", r}'
    else
        awk -v p="$price" -v v="$c_val" 'BEGIN{r=p-v; if(r<0)r=0; printf "%.2f", r}'
    fi
    return 0
}

_fm_bot_coupon_increment_usage() {
    local code="${1^^}"
    local line; line=$(_fm_bot_coupon_get "$code") || return 1
    [[ -n "$line" ]] || return 1
    local c_code c_type c_val c_max c_used c_en
    IFS=: read -r c_code c_type c_val c_max c_used c_en <<< "$line"
    sed -i "/^${c_code}:/d" "$BOT_COUPONS_DB"
    echo "${c_code}:${c_type}:${c_val}:${c_max}:$((c_used+1)):${c_en}" >> "$BOT_COUPONS_DB"
}

# ── Bans (per Telegram user id) ─────────────────────────────────────────
_fm_bot_is_banned() {
    local tg="$1"
    [[ -f "$BOT_BANS_DB" ]] || return 1
    grep -q "^${tg}:" "$BOT_BANS_DB"
}

_fm_bot_ban() {
    local tg="$1" reason="$2"
    mkdir -p "$(dirname "$BOT_BANS_DB")" 2>/dev/null
    touch "$BOT_BANS_DB"
    sed -i "/^${tg}:/d" "$BOT_BANS_DB"
    echo "${tg}:${reason}:$(date +%s)" >> "$BOT_BANS_DB"
}

_fm_bot_unban() {
    local tg="$1"
    [[ -f "$BOT_BANS_DB" ]] && sed -i "/^${tg}:/d" "$BOT_BANS_DB"
}

# ── Trial abuse tracking: telegram_id:hwid:timestamp per trial issued ──
# Both checks below are windowed to the current calendar month — that's
# the "resets every month" behavior: nothing needs to actively reset
# anything, the log just stops counting entries older than the 1st of
# this month, so everyone's quota (and every device's "already used"
# flag) naturally reopens on the 1st with zero migration/cron needed.
_fm_bot_current_month_start_epoch() {
    date -d "$(date +%Y-%m-01)" +%s
}

_fm_bot_trial_count_for_user() {
    local tg="$1"
    [[ -f "$BOT_TRIAL_LOG" ]] || { echo 0; return; }
    local ms; ms=$(_fm_bot_current_month_start_epoch)
    awk -F: -v t="$tg" -v ms="$ms" '$1==t && $3>=ms {n++} END{print n+0}' "$BOT_TRIAL_LOG"
}

# Admin-grantable bonus trials, additive on top of TRIAL_MAX_USES, per
# Telegram id, reset by the admin re-granting (not time-based — a bonus
# is a one-off gift, not a recurring quota).
_fm_bot_trial_bonus_get() {
    local tg="$1"
    [[ -f "$BOT_TRIAL_BONUS_DB" ]] || { echo 0; return; }
    awk -F: -v t="$tg" '$1==t{print $2; f=1} END{if(!f) print 0}' "$BOT_TRIAL_BONUS_DB"
}

_fm_bot_trial_bonus_add() {
    local tg="$1" delta="$2"
    local cur new
    cur=$(_fm_bot_trial_bonus_get "$tg")
    new=$((cur + delta))
    [[ "$new" -lt 0 ]] && new=0
    mkdir -p "$(dirname "$BOT_TRIAL_BONUS_DB")" 2>/dev/null
    touch "$BOT_TRIAL_BONUS_DB"
    sed -i "/^${tg}:/d" "$BOT_TRIAL_BONUS_DB"
    echo "${tg}:${new}" >> "$BOT_TRIAL_BONUS_DB"
    echo "$new"
}

# The effective cap for this user this month: the admin-wide default plus
# whatever bonus attempts were granted specifically to them.
_fm_bot_trial_max_for() {
    local tg="$1"
    _fm_bot_is_admin_chat "$tg" && { echo "${_FM_BOT_ADMIN_UNLIMITED:-999999}"; return; }
    echo $(( $(_fm_bot_get_plan TRIAL_MAX_USES) + $(_fm_bot_trial_bonus_get "$tg") ))
}

# ── "Change HWID" self-service: a customer can move their existing
# subscription to a new device by picking their app/file/server again and
# giving a new HWID — the old device is deleted outright and a fresh one
# takes its place with the exact same remaining plan (expiry, devices,
# bandwidth cap, trial-vs-paid type). Allowed BOT_HWID_CHANGE_DEFAULT_MAX
# times per Telegram id, lifetime (not monthly, unlike trials — this
# isn't a recurring perk, it's a limited safety valve), plus whatever the
# admin grants on top per user via BOT_HWID_CHANGE_BONUS_DB.
_fm_bot_hwidchange_used_get() {
    local tg="$1"
    [[ -f "$BOT_HWID_CHANGE_USED_DB" ]] || { echo 0; return; }
    awk -F: -v t="$tg" '$1==t{print $2; f=1} END{if(!f) print 0}' "$BOT_HWID_CHANGE_USED_DB"
}

_fm_bot_hwidchange_used_increment() {
    local tg="$1" cur new
    cur=$(_fm_bot_hwidchange_used_get "$tg")
    new=$((cur + 1))
    mkdir -p "$(dirname "$BOT_HWID_CHANGE_USED_DB")" 2>/dev/null
    touch "$BOT_HWID_CHANGE_USED_DB"
    sed -i "/^${tg}:/d" "$BOT_HWID_CHANGE_USED_DB"
    echo "${tg}:${new}" >> "$BOT_HWID_CHANGE_USED_DB"
    echo "$new"
}

_fm_bot_hwidchange_bonus_get() {
    local tg="$1"
    [[ -f "$BOT_HWID_CHANGE_BONUS_DB" ]] || { echo 0; return; }
    awk -F: -v t="$tg" '$1==t{print $2; f=1} END{if(!f) print 0}' "$BOT_HWID_CHANGE_BONUS_DB"
}

_fm_bot_hwidchange_bonus_add() {
    local tg="$1" delta="$2"
    local cur new
    cur=$(_fm_bot_hwidchange_bonus_get "$tg")
    new=$((cur + delta))
    [[ "$new" -lt 0 ]] && new=0
    mkdir -p "$(dirname "$BOT_HWID_CHANGE_BONUS_DB")" 2>/dev/null
    touch "$BOT_HWID_CHANGE_BONUS_DB"
    sed -i "/^${tg}:/d" "$BOT_HWID_CHANGE_BONUS_DB"
    echo "${tg}:${new}" >> "$BOT_HWID_CHANGE_BONUS_DB"
    echo "$new"
}

# The admin's own chat runs the customer flow on a customer's behalf
# (see the "customer mode" switch in the poll loop). Every limit the
# sales bot enforces exists to ration a paying stranger — none of it
# should ever stop the owner from issuing an account for someone who
# can't work the bot themselves. Bypassing at the source means every
# call site inherits it; there is no second place to remember.
_FM_BOT_ADMIN_UNLIMITED=999999

_fm_bot_is_admin_chat() {
    [[ -n "${CHAT_ID:-}" && "$1" == "$CHAT_ID" ]]
}

# "Customer mode": the admin's own chat temporarily behaves like a
# customer's, so the owner can walk a subscriber who cannot work the bot
# through trial/subscribe/renew/change-device himself and hand them the
# finished file. It has to be an explicit switch, not automatic: the
# admin chat is also where every /command lives, and a customer flow
# holding a pending step would otherwise swallow them.
BOT_ADMIN_CUSTMODE_DB="${BOT_ADMIN_CUSTMODE_DB:-/etc/firewallfalcon/bot_admin_custmode.db}"

_fm_bot_admin_custmode_on() {
    mkdir -p "$(dirname "$BOT_ADMIN_CUSTMODE_DB")" 2>/dev/null
    printf '1' > "$BOT_ADMIN_CUSTMODE_DB" 2>/dev/null
}

_fm_bot_admin_custmode_off() {
    rm -f "$BOT_ADMIN_CUSTMODE_DB" 2>/dev/null
}

_fm_bot_admin_custmode_is_on() {
    [[ -f "$BOT_ADMIN_CUSTMODE_DB" ]]
}

_fm_bot_hwidchange_max_for() {
    local tg="$1"
    _fm_bot_is_admin_chat "$tg" && { echo "${_FM_BOT_ADMIN_UNLIMITED:-999999}"; return; }
    echo $(( BOT_HWID_CHANGE_DEFAULT_MAX + $(_fm_bot_hwidchange_bonus_get "$tg") ))
}

_fm_bot_hwidchange_remaining() {
    local tg="$1" max used remaining
    max=$(_fm_bot_hwidchange_max_for "$tg")
    used=$(_fm_bot_hwidchange_used_get "$tg")
    remaining=$((max - used))
    [[ "$remaining" -lt 0 ]] && remaining=0
    echo "$remaining"
}

# The old HWID a customer is mid-way through replacing, kept between the
# "start" tap and however many app/file/server steps it takes them to
# reach the final "send the new HWID" prompt — the pending-state db only
# carries the flow name plus two small context fields (app, file type),
# not enough room for a whole extra HWID alongside those.
_fm_bot_hwidchange_state_set() {
    local tg="$1" old_hwid="$2"
    mkdir -p "$(dirname "$BOT_HWID_CHANGE_STATE_DB")" 2>/dev/null
    touch "$BOT_HWID_CHANGE_STATE_DB"
    sed -i "/^${tg}:/d" "$BOT_HWID_CHANGE_STATE_DB"
    echo "${tg}:${old_hwid}" >> "$BOT_HWID_CHANGE_STATE_DB"
}

_fm_bot_hwidchange_state_get() {
    local tg="$1"
    [[ -f "$BOT_HWID_CHANGE_STATE_DB" ]] || return 1
    awk -F: -v t="$tg" '$1==t{print $2; f=1} END{exit !f}' "$BOT_HWID_CHANGE_STATE_DB"
}

_fm_bot_hwidchange_state_clear() {
    local tg="$1"
    [[ -f "$BOT_HWID_CHANGE_STATE_DB" ]] && sed -i "/^${tg}:/d" "$BOT_HWID_CHANGE_STATE_DB"
}

# The most recently touched users.db row owned by this Telegram id, or
# nothing if they have no account at all. Reads with bash `read` rather
# than `awk -F:` because the owner field ("tg:<chat_id>") has a colon of
# its own — the same reason _fm_bot_provision_hwid_account reads existing
# rows this way instead of splitting on ":" naively.
_fm_bot_find_account_by_owner() {
    local owner="$1" u p exp lim bw dbw atype own found=""
    [[ -f "$DB_FILE" ]] || return 1
    while IFS=: read -r u p exp lim bw dbw atype own; do
        [[ "$own" == "$owner" ]] && found="${u}:${p}:${exp}:${lim}:${bw}:${dbw}:${atype}:${own}"
    done < "$DB_FILE"
    [[ -n "$found" ]] || return 1
    echo "$found"
}

# Same lookup, but prints EVERY account this owner has (one per line)
# instead of only the last match — needed wherever a customer might have
# more than one device and has to be asked which one they mean (renew,
# change-HWID), unlike the single-line helper above which is only ever
# used where "just grab the one they have" is the whole point.
_fm_bot_find_accounts_by_owner() {
    local owner="$1" u p exp lim bw dbw atype own found=1
    [[ -f "$DB_FILE" ]] || return 1
    while IFS=: read -r u p exp lim bw dbw atype own; do
        [[ "$own" == "$owner" ]] || continue
        echo "${u}:${p}:${exp}:${lim}:${bw}:${dbw}:${atype}:${own}"
        found=0
    done < "$DB_FILE"
    return $found
}

# True (exit 0) if this exact device has received a trial THIS MONTH,
# under any Telegram id — closes the "just message from a new Telegram
# account" loophole within the current window, since a device id is what
# actually costs bandwidth/a slot. Devices are free to trial again once a
# new month starts, exactly like the per-user counter above.
_fm_bot_trial_hwid_used() {
    local hwid="$1"
    [[ -f "$BOT_TRIAL_LOG" ]] || return 1
    local ms; ms=$(_fm_bot_current_month_start_epoch)
    awk -F: -v h="$hwid" -v ms="$ms" '$2==h && $3>=ms {f=1} END{exit !f}' "$BOT_TRIAL_LOG"
}

_fm_bot_trial_log_use() {
    local tg="$1" hwid="$2"
    mkdir -p "$(dirname "$BOT_TRIAL_LOG")" 2>/dev/null
    echo "${tg}:${hwid}:$(date +%s)" >> "$BOT_TRIAL_LOG"
}

# ── Referral program: "share the bot, earn wallet credit" ──────────────
# Every bot user gets a personal link (t.me/<bot>?start=ref_<their_id>).
# The FIRST person to share that link with someone new gets credit for
# them, forever — one referred person only ever counts for one referrer.
# Two independent, admin-configurable reward ladders (any number of
# tiers each, e.g. 10 → 10 SAR, 50 → 60 SAR, ...):
#   PAID   — counts referred people who actually went monthly at least
#            once (a trial alone doesn't count).
#   SIGNUP — counts every referred person who ever opened the bot, paid
#            or not.
# Each tier only ever pays out once per referrer, no matter how many
# times the threshold is re-crossed.
#
# BOT_REFERRALS_DB:      referred_chat_id:referrer_chat_id:timestamp  (one row per referred person, first touch wins)
# BOT_REFERRAL_PAID_DB:  referred_chat_id:referrer_chat_id            (one row the first time a referred person goes paid)
# BOT_REFERRAL_REWARDED_DB: referrer_chat_id:type:threshold           (marks a tier as already paid out)
# BOT_REFERRAL_TIERS_CONF: type:threshold:reward_sar                 (admin-defined ladder, type is PAID or SIGNUP)

_fm_bot_referral_get_referrer() {
    local referred="$1"
    [[ -f "$BOT_REFERRALS_DB" ]] || return 1
    awk -F: -v r="$referred" '$1==r{print $2; f=1} END{exit !f}' "$BOT_REFERRALS_DB"
}

# Registers $1 as referred by $2, unless $1 already has a referrer, is
# trying to refer itself, or $2 isn't a plausible Telegram chat id. Fires
# the SIGNUP reward check for the referrer on success. Silent no-op on
# any invalid input — this is called on every /start, valid or not.
_fm_bot_referral_register() {
    local referred="$1" referrer="$2"
    [[ "$referrer" =~ ^-?[0-9]+$ ]] || return 0
    [[ "$referred" == "$referrer" ]] && return 0
    if _fm_bot_referral_get_referrer "$referred" >/dev/null; then
        return 0
    fi
    mkdir -p "$(dirname "$BOT_REFERRALS_DB")" 2>/dev/null
    echo "${referred}:${referrer}:$(date +%s)" >> "$BOT_REFERRALS_DB"
    send_telegram_msg_to "$referrer" "$(_fm_bot_msg REFERRAL_NEW_SIGNUP "$(_fm_bot_lang_get "$referrer")")"
    _fm_bot_referral_check_and_reward "$referrer" "SIGNUP"
}

_fm_bot_referral_signup_count() {
    local referrer="$1"
    [[ -f "$BOT_REFERRALS_DB" ]] || { echo 0; return; }
    awk -F: -v r="$referrer" '$2==r{n++} END{print n+0}' "$BOT_REFERRALS_DB"
}

_fm_bot_referral_paid_count() {
    local referrer="$1"
    [[ -f "$BOT_REFERRAL_PAID_DB" ]] || { echo 0; return; }
    awk -F: -v r="$referrer" '$2==r{n++} END{print n+0}' "$BOT_REFERRAL_PAID_DB"
}

# Called once a referred person's subscription is actually paid (wallet
# purchase or admin-approved order) — NOT on trial. Counts them toward
# their referrer's PAID ladder exactly once, no matter how many times
# they resubscribe afterward.
_fm_bot_referral_on_paid_conversion() {
    local chat_id="$1"
    local referrer; referrer=$(_fm_bot_referral_get_referrer "$chat_id") || return 0
    [[ -n "$referrer" ]] || return 0
    if [[ -f "$BOT_REFERRAL_PAID_DB" ]] && awk -F: -v c="$chat_id" '$1==c{f=1} END{exit !f}' "$BOT_REFERRAL_PAID_DB"; then
        return 0
    fi
    mkdir -p "$(dirname "$BOT_REFERRAL_PAID_DB")" 2>/dev/null
    echo "${chat_id}:${referrer}" >> "$BOT_REFERRAL_PAID_DB"
    _fm_bot_referral_check_and_reward "$referrer" "PAID"
}

_fm_bot_referral_tier_add() {
    local type="${1^^}" threshold="$2" reward="$3"
    mkdir -p "$(dirname "$BOT_REFERRAL_TIERS_CONF")" 2>/dev/null
    touch "$BOT_REFERRAL_TIERS_CONF"
    grep -v "^${type}:${threshold}:" "$BOT_REFERRAL_TIERS_CONF" > "${BOT_REFERRAL_TIERS_CONF}.tmp" 2>/dev/null
    mv -f "${BOT_REFERRAL_TIERS_CONF}.tmp" "$BOT_REFERRAL_TIERS_CONF"
    echo "${type}:${threshold}:${reward}" >> "$BOT_REFERRAL_TIERS_CONF"
}

_fm_bot_referral_tier_del() {
    local type="${1^^}" threshold="$2"
    [[ -f "$BOT_REFERRAL_TIERS_CONF" ]] || return 0
    sed -i "/^${type}:${threshold}:/d" "$BOT_REFERRAL_TIERS_CONF"
}

# Prints "threshold:reward" lines for one ladder, sorted ascending.
_fm_bot_referral_tier_list() {
    local type="${1^^}"
    [[ -f "$BOT_REFERRAL_TIERS_CONF" ]] || return 0
    awk -F: -v t="$type" '$1==t{print $2":"$3}' "$BOT_REFERRAL_TIERS_CONF" | sort -t: -k1 -n
}

_fm_bot_referral_is_rewarded() {
    local referrer="$1" type="$2" threshold="$3"
    [[ -f "$BOT_REFERRAL_REWARDED_DB" ]] || return 1
    grep -qx "${referrer}:${type}:${threshold}" "$BOT_REFERRAL_REWARDED_DB" 2>/dev/null
}

# Walks every tier of $2 (PAID or SIGNUP) for referrer $1; whichever
# thresholds are now met and weren't already paid out get credited to the
# referrer's wallet, marked rewarded, and the referrer is notified.
_fm_bot_referral_check_and_reward() {
    local referrer="$1" type="${2^^}"
    local count
    if [[ "$type" == "PAID" ]]; then
        count=$(_fm_bot_referral_paid_count "$referrer")
    else
        count=$(_fm_bot_referral_signup_count "$referrer")
    fi
    local threshold reward
    while IFS=: read -r threshold reward; do
        [[ -z "$threshold" ]] && continue
        [[ "$count" -ge "$threshold" ]] || continue
        _fm_bot_referral_is_rewarded "$referrer" "$type" "$threshold" && continue
        mkdir -p "$(dirname "$BOT_REFERRAL_REWARDED_DB")" 2>/dev/null
        echo "${referrer}:${type}:${threshold}" >> "$BOT_REFERRAL_REWARDED_DB"
        local new_bal; new_bal=$(_fm_bot_wallet_add "$referrer" "$reward")
        local r_lang; r_lang=$(_fm_bot_lang_get "$referrer")
        local kind_key="REFERRAL_KIND_PAID"; [[ "$type" == "SIGNUP" ]] && kind_key="REFERRAL_KIND_SIGNUP"
        send_telegram_msg_to "$referrer" "$(_fm_bot_msg_fmt REFERRAL_REWARD "$r_lang" \
            THRESHOLD "$threshold" KIND "$(_fm_bot_msg "$kind_key" "$r_lang")" \
            REWARD "$reward" BALANCE "$new_bal")"
        local type_ar="مدفوعون"; [[ "$type" == "SIGNUP" ]] && type_ar="أي إحالة"
        send_telegram_msg "🏆 <b>تحقق مستوى إحالة</b>%0Aالمُحيل: <code>${referrer}</code>%0Aالنوع: ${type_ar} — ${threshold} ← ${reward} ريال"
    done < <(_fm_bot_referral_tier_list "$type")
}

# Lazily discovers and caches this bot's @username (needed to build
# t.me links) — one extra API call the first time only.
_fm_bot_username_cached() {
    local cache_file="/etc/firewallfalcon/.bot_username"
    [[ -s "$cache_file" ]] && { cat "$cache_file"; return; }
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" ]] || return 0
    local uname
    uname=$(curl -fsS --max-time 10 "https://api.telegram.org/bot${BOT_TOKEN}/getMe" 2>/dev/null | jq -r '.result.username // empty' 2>/dev/null)
    [[ -n "$uname" ]] && echo "$uname" > "$cache_file"
    printf '%s' "$uname"
}

_fm_bot_cmd_referral() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local uname; uname=$(_fm_bot_username_cached)
    local link; link=$(_fm_bot_msg REFERRAL_LINK_UNAVAILABLE "$lang")
    [[ -n "$uname" ]] && link="https://t.me/${uname}?start=ref_${chat_id}"
    local signups paid
    signups=$(_fm_bot_referral_signup_count "$chat_id")
    paid=$(_fm_bot_referral_paid_count "$chat_id")
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt REFERRAL_MSG "$lang" LINK "$link" SIGNUPS "$signups" PAID "$paid")"
}

# ── Connection-app config files (HTTP Custom, HTTP Injector, etc.) ──────
# The admin uploads one file per (app, file type) pair — as many as they
# want, e.g. app "HTTPCustom" with types "Global"/"STC"/"Mobily", or app
# "HTTPInjector" with its own types. A customer with a working account
# picks an app, then a type, and gets that exact file back with their own
# HWID/server IP filled in wherever the template uses a placeholder:
# {HWID} {USERNAME} {PASSWORD} {SERVER_IP} {EXPIRY}. A file with none of
# those placeholders (or a genuinely binary format, e.g. an encrypted
# .ehi blob) is just sent through unmodified — substitution never risks
# corrupting a binary file.
#
# Storage: $BOT_APP_FILES_DIR/<app>/<type> holds the raw uploaded bytes.
# BOT_APP_FILES_META remembers the original filename so the customer
# receives it named sensibly instead of by its internal slug:
#   app:type:original_filename

# Keeps app/type names usable both as directory/file components and as
# reply-keyboard button captions: letters, digits, spaces, '.', '_', '-'
# only, trimmed of surrounding whitespace.
_fm_bot_sanitize_slug() {
    local s="$1"
    # Strip only what's actually dangerous in a filesystem path
    # component: "/" (a directory separator) and control characters
    # (NUL, CR, LF, ...). Everything else is left alone — this used to
    # be an ASCII-only allow-list that silently deleted every non-Latin
    # character, which is exactly what broke Arabic app/type names (and
    # any longer name that happened to collapse into something else, or
    # nothing at all, once stripped).
    s="${s//\//}"
    s="${s//[[:cntrl:]]/}"
    # Trim leading/trailing whitespace without spawning a subshell.
    s="${s#"${s%%[![:space:]]*}"}"
    s="${s%"${s##*[![:space:]]}"}"
    # A name that's only "." or ".." after trimming means something else
    # entirely as a directory component — refuse it rather than guess.
    [[ "$s" == "." || "$s" == ".." ]] && s=""
    printf '%s' "$s"
}

_fm_bot_appfile_apps_list() {
    [[ -d "$BOT_APP_FILES_DIR" ]] || return 0
    find "$BOT_APP_FILES_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null | sort
}

_fm_bot_appfile_types_list() {
    local app="$1"
    [[ -d "$BOT_APP_FILES_DIR/$app" ]] || return 0
    find "$BOT_APP_FILES_DIR/$app" -mindepth 1 -maxdepth 1 -type f -printf '%f\n' 2>/dev/null | sort
}

_fm_bot_appfile_path() {
    printf '%s/%s/%s' "$BOT_APP_FILES_DIR" "$1" "$2"
}

_fm_bot_appfile_meta_get() {
    local app="$1" type="$2"
    [[ -f "$BOT_APP_FILES_META" ]] || return 0
    awk -F: -v a="$app" -v t="$type" '$1==a && $2==t {print $3; f=1} END{if(!f)print ""}' "$BOT_APP_FILES_META"
}

_fm_bot_appfile_meta_set() {
    local app="$1" type="$2" fname="$3"
    mkdir -p "$(dirname "$BOT_APP_FILES_META")" 2>/dev/null
    touch "$BOT_APP_FILES_META"
    grep -v "^${app}:${type}:" "$BOT_APP_FILES_META" > "${BOT_APP_FILES_META}.tmp" 2>/dev/null
    mv -f "${BOT_APP_FILES_META}.tmp" "$BOT_APP_FILES_META"
    echo "${app}:${type}:${fname}" >> "$BOT_APP_FILES_META"
}

# $3 = path to the source bytes on disk (already downloaded/uploaded
# somewhere temporary), $4 = the original filename to remember for
# delivery. Prints the final (sanitized) "app:type" on success.
_fm_bot_appfile_add() {
    local app type src_file orig_name
    app=$(_fm_bot_sanitize_slug "$1"); type=$(_fm_bot_sanitize_slug "$2")
    src_file="$3"; orig_name="$4"
    [[ -n "$app" && -n "$type" && -f "$src_file" ]] || return 1
    mkdir -p "$BOT_APP_FILES_DIR/${app}" 2>/dev/null
    cp -f "$src_file" "$(_fm_bot_appfile_path "$app" "$type")" || return 1
    [[ -n "$orig_name" ]] || orig_name="${app}_${type}"
    _fm_bot_appfile_meta_set "$app" "$type" "$orig_name"
    printf '%s:%s' "$app" "$type"
    return 0
}

_fm_bot_appfile_del() {
    local app="$1" type="$2"
    rm -f "$(_fm_bot_appfile_path "$app" "$type")" 2>/dev/null
    [[ -f "$BOT_APP_FILES_META" ]] && sed -i "/^${app}:${type}:/d" "$BOT_APP_FILES_META" 2>/dev/null
    rmdir "$BOT_APP_FILES_DIR/${app}" 2>/dev/null || true
}

# Builds the personalized file for $hwid from the ($app,$type) template
# and sends it to $chat_id as a Telegram document. Looks up $hwid's own
# expiry from users.db for the {EXPIRY} placeholder, if it has an account.
# ── NPV Tunnel: a config file built for one customer ──────────────────
# NPV Tunnel has no "log in with your device id" mode, so its customers
# cannot be handed one shared config the way HTTP Custom customers are.
# What it has instead is a lock section inside the config file itself:
# bind the file to a deviceIds value and it refuses to run anywhere else.
# So the bot rewrites three fields inside the admin's own uploaded file —
# the SSH username, the SSH password, and that device id — and ships a
# copy only that one phone can use.
#
# Nothing about this is configured anywhere: an .npvt file announces
# itself with its own magic bytes, so the admin keeps uploading files per
# country/SIM/file-type exactly as before, and every other kind of file
# keeps the behaviour it always had.
NPVT_DEVICES_DB="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
BOT_DELIVERY_DB="${BOT_DELIVERY_DB:-/etc/firewallfalcon/bot_delivery.db}"

_fm_bot_npvt_is_file() {
    local f="$1" head8
    [[ -f "$f" ]] || return 1
    # tr -d strips NUL bytes before bash sees them: the magic itself has
    # none, and a binary file that does would otherwise make bash print a
    # warning to the log on every single check.
    head8=$(head -c 8 "$f" 2>/dev/null | tr -d '\0')
    [[ "$head8" == NPVTSUB1* || "${head8:0:5}" == "NPVT1" ]]
}

# The codec ships inside the encrypted payload, which is extracted whole
# into $FM_SRC, so one re-pull restores it if the directory was wiped.
_fm_bot_npvt_codec() {
    local p="${FM_SRC:-/etc/firewallfalcon/.src}/npvt_edit.py"
    [[ -f "$p" ]] && { printf '%s' "$p"; return 0; }
    _fm_pull_src >/dev/null 2>&1 || return 1
    [[ -f "$p" ]] || return 1
    printf '%s' "$p"
}

# A device id NPV Tunnel hands out is 64 characters, and a Linux username
# has to fit in 32 — utmp truncates at that width and the session limiter
# counts sessions by process owner, so a name that long would quietly
# break the one control that stops account sharing. The lock lives in
# deviceIds, not in the username, so the account can simply be called
# something short instead.
#
# The number is rolled once and then remembered. That matters: the
# "same device means renew, not refuse" check finds an account by its
# name, so a freshly rolled number on every purchase would leave a
# returning customer with a second account beside the first — and twice
# the simultaneous sessions they paid for.
#
# Short ids are returned untouched, so HTTP Custom and everything else
# keeps using the device id as the username exactly as it always has and
# this layer stays entirely out of their way — including the default
# 32-character id those two apps hand out (_fm_bot_hwid_expected_len),
# which must clear this same ceiling untouched: _fm_create_system_user
# already falls back to a manual /etc/passwd entry for any id up to
# _fm_validate_hwid's 128-character cap, exactly as the admin panel's
# own manual "Device ID" account creation does — minting only exists
# for the two apps that genuinely need it (NPV Tunnel/NPVS below).
_FM_BOT_NAME_MAX=32

_fm_bot_account_name_for_device() {
    local device="$1"
    [[ -n "$device" ]] || return 1
    (( ${#device} <= ${_FM_BOT_NAME_MAX:-32} )) && { printf '%s' "$device"; return 0; }
    local db="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}" known
    if [[ -f "$db" ]]; then
        known=$(awk -F: -v d="$device" '$1==d{a=$2} END{print a}' "$db" 2>/dev/null)
        [[ -n "$known" ]] && { printf '%s' "$known"; return 0; }
    fi
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    local n candidate tries=0
    while (( tries < 60 )); do
        n=$(( (RANDOM * 32768 + RANDOM) % 90000 + 10000 ))
        candidate="dahoom${n}vip"
        if ! id "$candidate" &>/dev/null && ! grep -q ":${candidate}$" "$db" 2>/dev/null; then
            printf '%s:%s\n' "$device" "$candidate" >> "$db"
            printf '%s' "$candidate"
            return 0
        fi
        tries=$((tries+1))
    done
    return 1
}

# Read-only counterpart of _fm_bot_account_name_for_device: answers "does
# this device already belong to an account" without minting one, which is
# what an ownership check needs.
_fm_bot_account_lookup_device() {
    local device="$1" db="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
    [[ -n "$device" ]] || return 1
    (( ${#device} <= ${_FM_BOT_NAME_MAX:-32} )) && { printf '%s' "$device"; return 0; }
    [[ -f "$db" ]] || return 1
    local a; a=$(awk -F: -v d="$device" '$1==d{a=$2} END{print a}' "$db" 2>/dev/null)
    [[ -n "$a" ]] || return 1
    printf '%s' "$a"
}

# Always mints a new name for this device and remembers it alongside any
# it already has. One account maps to exactly one device; a device may
# carry several accounts, which is what buying more than one subscription
# from the same phone means.
_fm_bot_account_name_mint_for_device() {
    local device="$1" db="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
    [[ -n "$device" ]] || return 1
    (( ${#device} <= ${_FM_BOT_NAME_MAX:-32} )) && { printf '%s' "$device"; return 0; }
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    local n candidate tries=0
    while (( tries < 60 )); do
        n=$(( (RANDOM * 32768 + RANDOM) % 90000 + 10000 ))
        candidate="dahoom${n}vip"
        if ! id "$candidate" &>/dev/null && ! grep -q ":${candidate}\$" "$db" 2>/dev/null; then
            printf '%s:%s\n' "$device" "$candidate" >> "$db"
            printf '%s' "$candidate"
            return 0
        fi
        tries=$((tries+1))
    done
    return 1
}

_fm_bot_device_for_account() {
    local account="$1" db="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
    [[ -f "$db" ]] || return 1
    local d; d=$(awk -F: -v a="$account" '$2==a{print $1; exit}' "$db" 2>/dev/null)
    [[ -n "$d" ]] || return 1
    printf '%s' "$d"
}

# Points an existing account at a new phone. Used by "change device": the
# account keeps its name and everything attached to it, only the lock
# inside the delivered file moves.
_fm_bot_npvt_remap_device() {
    local account="$1" device="$2" db="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
    [[ -n "$account" && -n "$device" ]] || return 1
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    # Only this account's own row moves. Rows for other accounts already
    # on the new phone are left alone: a customer who bought twice from
    # one device legitimately has two, and dropping them would strand
    # those accounts with no device at all.
    _fm_db_replace_row "$db" ":" 2 "$account" "${device}:${account}"
}

# Builds the personalised copy. expiryDate is deliberately not among the
# fields written: the subscription's end date is enforced by the account
# on the server, and stamping it inside the file as well only creates a
# second place for it to be wrong. The field keeps whatever the admin's
# own file had.
#
# The two on-screen messages are free text
# the admin edits from the panel, so they travel to python in the
# environment rather than on the command line, where quoting Arabic with
# whatever punctuation the admin used would be a bug waiting to happen.
_fm_bot_npvt_build() {
    local src="$1" out="$2" account="$3" device="$4" expiry="$5" lang="${6:-ar}"
    _FM_BOT_NPVT_ERR=""
    local codec
    if ! codec=$(_fm_bot_npvt_codec); then
        _FM_BOT_NPVT_ERR="المُحوِّل npvt_edit.py غير موجود في ${FM_SRC:-/etc/firewallfalcon/.src}"
        return 1
    fi
    if ! command -v python3 >/dev/null 2>&1; then
        _FM_BOT_NPVT_ERR="python3 غير مثبّت"
        return 1
    fi
    local lock_msg srv_msg
    lock_msg=$(_fm_bot_msg_fmt NPVT_LOCK_MESSAGE "$lang" EXPIRE "$expiry")
    srv_msg=$(_fm_bot_msg_fmt NPVT_SERVER_MESSAGE "$lang" EXPIRE "$expiry")
    # Catalog text carries Telegram's %0A line breaks; a config file wants
    # real ones.
    lock_msg="${lock_msg//%0A/$'\n'}"
    srv_msg="${srv_msg//%0A/$'\n'}"
    local err
    err=$(NPVT_USER="$account" NPVT_DEVICE="$device" \
          NPVT_LOCKMSG="$lock_msg" NPVT_SRVMSG="$srv_msg" \
          python3 -c 'import json,os,sys; json.dump({"user":os.environ["NPVT_USER"],"password":os.environ["NPVT_USER"],"device_id":os.environ["NPVT_DEVICE"],"lock_message":os.environ["NPVT_LOCKMSG"],"server_message":os.environ["NPVT_SRVMSG"],"randomize_name":True}, sys.stdout)' 2>&1 \
          | python3 "$codec" build "$src" "$out" 2>&1)
    local rc=$?
    if [[ $rc -ne 0 || ! -s "$out" ]]; then
        _FM_BOT_NPVT_ERR="${err:-فشل التوليد (رمز $rc)}"
        return 1
    fi
    return 0
}

# ── NPV Tunnel, Android edition (.npvs) ───────────────────────────────
# The Android app dropped the "deviceIds" policy field the iPhone one
# uses and locks files properly instead: the config body is encrypted to
# the buyer's own public key, so a copy built for one phone cannot be
# opened on any other no matter what the app is asked to believe.
#
# That public key IS the device id the customer sends — 44 base64url
# characters. An id that is not a point on the P-256 curve produces a
# file nobody can open, which is why it is checked before an account is
# created rather than after (see _fm_bot_hwid_check_for_app).
#
# Sealing needs the python `cryptography` package. When it is missing the
# delivery falls back to the admin's own file exactly as an .npvt build
# failure does, and the admin is told why.
_fm_bot_npvs_is_file() {
    local f="$1" head5
    [[ -f "$f" ]] || return 1
    head5=$(head -c 5 "$f" 2>/dev/null)
    [[ "$head5" == $'NPVS\001' ]]
}

_fm_bot_npvs_codec() {
    local p="${FM_SRC:-/etc/firewallfalcon/.src}/npvs_edit.py"
    [[ -f "$p" ]] && { printf '%s' "$p"; return 0; }
    _fm_pull_src >/dev/null 2>&1 || return 1
    [[ -f "$p" ]] || return 1
    printf '%s' "$p"
}

# Is the sealing library actually there? Asked before every build and by
# /npvt, so a server missing it says so instead of quietly shipping
# unlocked files.
_fm_bot_npvs_crypto_ok() {
    command -v python3 >/dev/null 2>&1 || return 1
    python3 -c 'from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305' >/dev/null 2>&1
}

# Installs it if it isn't. apt first — a distro package needs no compiler
# and no network to PyPI — then pip as a fallback. Called once, lazily,
# the first time an .npvs file actually has to be built, so a server that
# never sells Android NPV configs never pays for it.
_fm_bot_npvs_crypto_install() {
    _fm_bot_npvs_crypto_ok && return 0
    if command -v apt-get >/dev/null 2>&1; then
        DEBIAN_FRONTEND=noninteractive apt-get install -y python3-cryptography >/dev/null 2>&1
        _fm_bot_npvs_crypto_ok && return 0
    fi
    if command -v pip3 >/dev/null 2>&1; then
        pip3 install --break-system-packages cryptography >/dev/null 2>&1 \
            || pip3 install cryptography >/dev/null 2>&1
    fi
    _fm_bot_npvs_crypto_ok
}

_fm_bot_npvs_build() {
    local src="$1" out="$2" account="$3" device="$4" lang="${5:-ar}"
    _FM_BOT_NPVT_ERR=""
    local codec
    if ! codec=$(_fm_bot_npvs_codec); then
        _FM_BOT_NPVT_ERR="المُحوِّل npvs_edit.py غير موجود في ${FM_SRC:-/etc/firewallfalcon/.src}"
        return 1
    fi
    if ! command -v python3 >/dev/null 2>&1; then
        _FM_BOT_NPVT_ERR="python3 غير مثبّت"
        return 1
    fi
    if ! _fm_bot_npvs_crypto_install; then
        _FM_BOT_NPVT_ERR="حزمة python3-cryptography غير مثبّتة وتعذّر تثبيتها"
        return 1
    fi
    local lock_msg srv_msg
    lock_msg=$(_fm_bot_msg NPVT_LOCK_MESSAGE "$lang")
    srv_msg=$(_fm_bot_msg NPVT_SERVER_MESSAGE "$lang")
    lock_msg="${lock_msg//%0A/$'\n'}"
    srv_msg="${srv_msg//%0A/$'\n'}"
    local err
    err=$(NPVS_USER="$account" NPVS_DEVICE="$device" \
          NPVS_LOCKMSG="$lock_msg" NPVS_SRVMSG="$srv_msg" \
          python3 -c 'import json,os,sys; json.dump({"user":os.environ["NPVS_USER"],"password":os.environ["NPVS_USER"],"device_id":os.environ["NPVS_DEVICE"],"lock_message":os.environ["NPVS_LOCKMSG"],"server_message":os.environ["NPVS_SRVMSG"],"randomize_name":True}, sys.stdout)' 2>&1 \
          | python3 "$codec" build "$src" "$out" 2>&1)
    local rc=$?
    if [[ $rc -ne 0 || ! -s "$out" ]]; then
        _FM_BOT_NPVT_ERR="${err:-فشل التوليد (رمز $rc)}"
        : > "$out" 2>/dev/null
        return 1
    fi
    return 0
}

# ── Is this device id usable for the file about to be sent? ───────────
# Answered from the file itself, not from a setting: whichever config the
# customer picked is opened and its magic decides which shape its id has
# to be. Anything else — HTTP Custom, an .ehi, a plain template — has
# never had a shape to check and still doesn't.
#
# Returns 0 usable, 1 wrong shape (with the reason key in
# _FM_BOT_HWID_ERR_KEY). Called BEFORE the account is created, because a
# file the buyer's phone cannot open is worse than no file at all: the
# account exists, the month is spent, and support has to unpick it.
_FM_BOT_HWID_ERR_KEY=""
_FM_BOT_HWID_ERR_LEN=""
_FM_BOT_HWID_ERR_GOT=""
_fm_bot_hwid_check_for_app() {
    local app="$1" type="$2" hwid="$3"
    _FM_BOT_HWID_ERR_KEY=""
    [[ -n "$app" && -n "$type" ]] || return 0
    local src; src=$(_fm_bot_appfile_path "$app" "$type")
    [[ -f "$src" ]] || return 0
    if _fm_bot_npvs_is_file "$src"; then
        local codec
        codec=$(_fm_bot_npvs_codec) || return 0   # can't check: don't block a sale
        command -v python3 >/dev/null 2>&1 || return 0
        if python3 "$codec" validate "$hwid" >/dev/null 2>&1; then
            return 0
        fi
        _FM_BOT_HWID_ERR_KEY="INVALID_HWID_NPVS"
        return 1
    fi
    if _fm_bot_npvt_is_file "$src"; then
        # The iPhone app hands out its device id in TWO shapes, and only
        # one of them was accepted here — so every customer whose app
        # showed the UUID form (95E6865B-1A1B-449A-A023-5D2A79AC8B1D)
        # was told their perfectly correct id was wrong, and could not
        # buy at all:
        #   • 64 hex characters, no separators
        #   • a UUID: 8-4-4-4-12 hex groups joined by "-"
        # Both are accepted verbatim — the codec writes deviceIds as an
        # opaque string, so nothing downstream cares which shape it is,
        # and normalising between them would risk handing the phone an
        # id it does not recognise. There is no curve to check either
        # against, so the shape is all there is, and it still catches
        # the customer who typed the app's name into the box.
        if [[ "$hwid" =~ ^[0-9a-fA-F]{64}$ ]] \
           || [[ "$hwid" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]]; then
            return 0
        fi
        _FM_BOT_HWID_ERR_KEY="INVALID_HWID_NPVT"
        return 1
    fi
    # Everything else — HTTP Custom, HTTP Injector, a plain template, an
    # .ehi — logs in as the device id, so the id has to be exactly as
    # wide as that app hands out.
    local want; want=$(_fm_bot_hwid_expected_len)
    if [[ "$want" != "0" ]]; then
        local LC_ALL=C.utf8 LANG=C.utf8   # count characters, not bytes
        if (( ${#hwid} != want )); then
            _FM_BOT_HWID_ERR_KEY="INVALID_HWID_LEN"
            _FM_BOT_HWID_ERR_LEN="$want"
            _FM_BOT_HWID_ERR_GOT="${#hwid}"
            return 1
        fi
    fi
    return 0
}

# ── The id the customer sent, held while they confirm it ──────────────
# It cannot live in the pending state itself: that is read with `read -r
# a:b:c`, so a fourth field would be swallowed by the third. A row of its
# own also keeps the whole reply — a subscribe answer may carry a coupon
# after the id, and losing that on the way through the confirmation would
# quietly charge full price.
BOT_HWID_PENDING_DB="${BOT_HWID_PENDING_DB:-/etc/firewallfalcon/bot_hwid_pending.db}"

_fm_bot_hwidpend_set() {
    local chat_id="$1" text="$2"
    local db="${BOT_HWID_PENDING_DB:-/etc/firewallfalcon/bot_hwid_pending.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    sed -i "/^${chat_id}\t/d" "$db" 2>/dev/null
    printf '%s\t%s\n' "$chat_id" "$text" >> "$db"
}

_fm_bot_hwidpend_get() {
    local chat_id="$1" db="${BOT_HWID_PENDING_DB:-/etc/firewallfalcon/bot_hwid_pending.db}"
    [[ -f "$db" ]] || return 1
    local row; row=$(awk -F'\t' -v c="$chat_id" '$1==c{print substr($0, index($0,"\t")+1); exit}' "$db" 2>/dev/null)
    [[ -n "$row" ]] || return 1
    printf '%s' "$row"
}

_fm_bot_hwidpend_clear() {
    local chat_id="$1" db="${BOT_HWID_PENDING_DB:-/etc/firewallfalcon/bot_hwid_pending.db}"
    [[ -f "$db" ]] || return 0
    sed -i "/^${chat_id}\t/d" "$db" 2>/dev/null
    return 0
}

# How many characters an ordinary app's device id has. HTTP Custom and
# HTTP Injector both hand out 32, and that id becomes the account name
# itself — so anything else is a copy-paste that lost or gained
# characters, and the account it would create could never log in. Set to
# 0 from the admin chat to switch the rule off for an app that differs.
_fm_bot_hwid_expected_len() {
    local n; n=$(_fm_bot_get_plan HWID_LEN 2>/dev/null)
    [[ "$n" =~ ^[0-9]+$ ]] || n=32
    printf '%s' "$n"
}

# The confirmation screen. Deliberately its own step rather than a line
# appended to the success message: an id typed one character wrong reads
# fine in a chat bubble, and by the time the file arrives the account
# exists and the month is spent.
_fm_bot_send_hwid_confirm() {
    local chat_id="$1" hwid="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    _fm_bot_send_choice "$chat_id" \
        "$(_fm_bot_msg_fmt HWID_CONFIRM "$lang" HWID "$(_fm_html_escape "$hwid")")" \
        "$(printf '%s\n%s' "$(_fm_bot_btn_hwid_yes "$lang")" "$(_fm_bot_btn_hwid_no "$lang")")" 1
}

# Everything a half-finished flow leaves behind, in one place, so cancel
# and "start over" cannot each forget a different piece of it.
_fm_bot_flow_reset() {
    local chat_id="$1"
    _fm_bot_pending_clear "$chat_id"
    _fm_bot_hwidpend_clear "$chat_id"
    _fm_bot_hwidchange_state_clear "$chat_id" 2>/dev/null || true
    _fm_bot_node_selected_clear "$chat_id" 2>/dev/null || true
}

# The three button flows all end the same way: take what the customer
# typed, keep the first word (a subscribe reply may carry a coupon after
# it), and refuse right here if it cannot work with the file they chose.
# Nothing has been created at this point — no account, no order, no
# wallet charge — so a refusal costs the customer only a retype.
_fm_bot_hwid_gate() {
    local chat_id="$1" app="$2" type="$3" text="$4"
    local first; first=$(awk '{print $1}' <<< "$text")
    [[ -n "$first" ]] || return 0
    _fm_bot_hwid_check_for_app "$app" "$type" "$first" && return 0
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt "$_FM_BOT_HWID_ERR_KEY" "$lang" \
        HWID "$(_fm_html_escape "$first")" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")" \
        LEN "${_FM_BOT_HWID_ERR_LEN:-}" GOT "${_FM_BOT_HWID_ERR_GOT:-}")"
    return 1
}

# ── Deleting accounts nobody renewed ──────────────────────────────────
# An expired account still exists: the Linux user, its password, its
# bandwidth counters, its device mapping. Left alone they pile up for
# years, and an old device id sitting in the mapping is what makes a
# returning customer's purchase behave strangely months later.
#
# So an account whose expiry passed and stayed passed for the grace
# period is deleted outright — user, password and every row that
# mentions it. The grace period is days, not hours, on purpose: someone
# who renews the morning after their subscription lapses must find their
# account still there.
EXPIRED_DELETE_STAMP="${EXPIRED_DELETE_STAMP:-/etc/firewallfalcon/.expired_sweep_stamp}"

_fm_bot_expired_grace_days() {
    local n; n=$(_fm_bot_get_plan EXPIRED_DELETE_DAYS 2>/dev/null)
    [[ "$n" =~ ^[0-9]+$ ]] || n=3
    printf '%s' "$n"
}

# Everything outside users.db that names this account. The system user,
# its bandwidth files and its login-mode row are handled by
# delete_firewallfalcon_user_accounts; these three are the bot's own.
_fm_bot_purge_account_records() {
    local acct="$1"
    [[ -n "$acct" ]] || return 0
    local ndb="${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}"
    [[ -f "$ndb" ]] && sed -i "/:${acct}\$/d" "$ndb" 2>/dev/null
    local ddb="${BOT_DELIVERY_DB:-/etc/firewallfalcon/bot_delivery.db}"
    if [[ -f "$ddb" ]]; then
        local dtmp; dtmp=$(mktemp)
        awk -F'\t' -v a="$acct" '$1!=a' "$ddb" > "$dtmp" 2>/dev/null && mv -f "$dtmp" "$ddb"
        rm -f "$dtmp" 2>/dev/null
    fi
    return 0
}

# Returns the accounts due for deletion, one per line, as
# "account<TAB>expiry<TAB>owner". Read-only: separating the decision from
# the deletion is what makes it testable without creating Linux users.
_fm_bot_expired_due_list() {
    local grace; grace=$(_fm_bot_expired_grace_days)
    [[ "$grace" != "0" ]] || return 0
    [[ -f "$DB_FILE" ]] || return 0
    local cutoff; cutoff=$(date -d "-${grace} days" +%Y-%m-%d 2>/dev/null) || return 0
    # String comparison is exact for YYYY-MM-DD, and it costs one `date`
    # call for the whole file instead of one per account. The bound is
    # inclusive: an account whose expiry date is exactly the cutoff has
    # been dead for the full grace period, which is the day it goes.
    awk -F: -v cut="$cutoff" '
        NF >= 3 && $1 != "" && $3 ~ /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/ && $3 <= cut {
            owner = ""
            if (NF >= 8) { owner = $8; for (i = 9; i <= NF; i++) owner = owner ":" $i }
            printf "%s\t%s\t%s\n", $1, $3, owner
        }' "$DB_FILE" 2>/dev/null
}

_fm_bot_expired_sweep() {
    local due; due=$(_fm_bot_expired_due_list)
    [[ -n "$due" ]] || return 0
    local grace; grace=$(_fm_bot_expired_grace_days)
    local acct exp owner listed="" count=0
    while IFS=$'\t' read -r acct exp owner; do
        [[ -n "$acct" ]] || continue
        # Told before it happens, not after: the message goes out while
        # the account still exists, so a customer who was about to renew
        # sees why their login stopped working instead of guessing.
        if [[ "$owner" == tg:* ]]; then
            local o_chat="${owner#tg:}" o_lang
            o_lang=$(_fm_bot_lang_get "$o_chat")
            send_telegram_msg_to "$o_chat" "$(_fm_bot_msg_fmt ACCOUNT_DELETED_EXPIRED "$o_lang" \
                USERNAME "$acct" EXPIRE "$exp" DAYS "$grace")"
        fi
        delete_firewallfalcon_user_accounts "$acct" >/dev/null 2>&1
        _fm_bot_purge_account_records "$acct"
        count=$((count+1))
        listed+="%0A• <code>${acct}</code> — ${exp}"
    done <<< "$due"
    if [[ "$count" -gt 0 ]]; then
        send_telegram_msg "$(_fm_bot_msg_fmt ACCOUNT_DELETED_ADMIN ar \
            COUNT "$count" LIST "$listed" DAYS "$grace")"
    fi
    return 0
}

# Once a day is plenty for something measured in days, and the stamp
# survives a restart — otherwise a bot that restarts often would sweep on
# every start and message the admin each time.
_fm_bot_expired_sweep_if_due() {
    local stamp="${EXPIRED_DELETE_STAMP:-/etc/firewallfalcon/.expired_sweep_stamp}"
    local today; today=$(date +%Y-%m-%d)
    local last=""
    [[ -f "$stamp" ]] && last=$(cat "$stamp" 2>/dev/null)
    [[ "$last" == "$today" ]] && return 0
    mkdir -p "$(dirname "$stamp")" 2>/dev/null
    printf '%s' "$today" > "$stamp" 2>/dev/null
    _fm_bot_expired_sweep
}

# ── What each account was last sent ───────────────────────────────────
# Enough to rebuild the exact same file on request, so a customer who
# lost theirs gets it back without being walked through the whole flow
# again. Tab separated: an app name is free text the admin typed and may
# well contain a colon.
_fm_bot_delivery_set() {
    local account="$1" app="$2" type="$3" device="$4"
    [[ -n "$account" ]] || return 0
    local db="${BOT_DELIVERY_DB:-/etc/firewallfalcon/bot_delivery.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    _fm_db_replace_row "$db" $'\t' 1 "$account" \
        "$(printf '%s\t%s\t%s\t%s' "$account" "$app" "$type" "$device")"
}

_fm_bot_delivery_get() {
    local account="$1" db="${BOT_DELIVERY_DB:-/etc/firewallfalcon/bot_delivery.db}"
    [[ -f "$db" ]] || return 1
    local row; row=$(awk -F'\t' -v a="$account" '$1==a{print; exit}' "$db" 2>/dev/null)
    [[ -n "$row" ]] || return 1
    printf '%s' "${row#*$'\t'}"
}

# "Send my file again". The account is named by the tapped button, so its
# owner is checked against the chat asking before anything is rebuilt —
# a hand-made callback payload must not be able to pull down somebody
# else's config.
_fm_bot_resend_file() {
    local chat_id="$1" account="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local row owner=""
    row=$(awk -F: -v u="$account" '$1==u{print; exit}' "$DB_FILE" 2>/dev/null)
    if [[ -n "$row" ]]; then
        local _u _p _e _l _b _d _t
        IFS=: read -r _u _p _e _l _b _d _t owner <<< "$row"
    fi
    if [[ "$owner" != "tg:${chat_id}" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RESEND_NOT_YOURS "$lang")"
        return 1
    fi
    local rec; rec=$(_fm_bot_delivery_get "$account")
    if [[ -z "$rec" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RESEND_NO_RECORD "$lang")"
        return 1
    fi
    local r_app r_type r_device
    IFS=$'\t' read -r r_app r_type r_device <<< "$rec"
    [[ -n "$r_device" ]] || r_device="$account"
    _fm_bot_appfile_render_and_send "$chat_id" "$r_app" "$r_type" "$r_device" "$account"
}

_fm_bot_appfile_render_and_send() {
    local chat_id="$1" app="$2" type="$3" hwid="$4" account_in="${5:-}"
    local src; src=$(_fm_bot_appfile_path "$app" "$type")
    if [[ ! -f "$src" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg APPFILE_UNAVAILABLE "$(_fm_bot_lang_get "$chat_id")")"
        return 1
    fi

    # $hwid is what the customer sent — for NPV Tunnel that is a 64
    # character device id, and the account underneath it carries a short
    # name instead (see _fm_bot_account_name_for_device). Everything that
    # reads users.db needs the account name; the file itself needs the
    # device id, to lock to that phone.
    # The caller passes the account whenever it knows it — it just
    # provisioned it, and one device can now carry several accounts, so
    # looking it up again by device would be a guess. Falling back to the
    # lookup keeps every older call site working unchanged.
    local account="$account_in"
    if [[ -z "$account" ]]; then
        account=$(_fm_bot_account_name_for_device "$hwid")
        [[ -n "$account" ]] || account="$hwid"
    fi

    # Which node (if any) actually holds this account — the durable
    # device→node mapping first (works long after the customer's sticky
    # region pick is gone, e.g. a later /resend or an admin-approved
    # order in a separate conversation turn), the per-chat sticky pick
    # as a fallback for the very first delivery in a flow, before that
    # mapping exists yet. Empty means "local", exactly as it always was.
    local node; node=$(_fm_bot_resolve_node_for_call "$hwid" "$chat_id")

    local exp_date="" server_ip=""
    if [[ -n "$node" ]]; then
        # This account lives on a remote VPN node, not here — this box's
        # own DB_FILE never has its row, so the expiry has to come from
        # the node itself, and {SERVER_IP} must be THAT node's own
        # address (this bot server runs no VPN service at all).
        local node_out; node_out=$(_fm_bot_node_api_call "$node" "GET" "/api/node/accounts/$(_fm_urlenc "$account")" "")
        if [[ $? -eq 0 ]]; then
            _fm_bot_node_call_split "$node_out"
            [[ "$NODE_CALL_STATUS" == "200" ]] && exp_date=$(_fm_json_get "$NODE_CALL_BODY" "expire_date")
        fi
        local node_row; node_row=$(_fm_bot_node_get "$node")
        if [[ -n "$node_row" ]]; then
            _fm_bot_node_fields "$node_row"
            server_ip=$(printf '%s' "$NODE_BASE_URL" | sed -E 's#^[a-zA-Z]+://##; s#[:/].*$##')
        fi
    else
        if [[ -f "$DB_FILE" ]]; then
            local db_line; db_line=$(awk -F: -v h="$account" '$1==h{print; exit}' "$DB_FILE")
            if [[ -n "$db_line" ]]; then
                local _u _p; IFS=: read -r _u _p exp_date _rest <<< "$db_line"
            fi
        fi
        server_ip=$(curl -s -4 --max-time 5 icanhazip.com 2>/dev/null)
    fi
    [[ -z "$server_ip" ]] && server_ip="YOUR_SERVER_IP"

    local out_file; out_file=$(mktemp)
    # An NPV Tunnel config is encrypted, so nothing can be substituted
    # into it as text — it has to be decoded, edited and re-encoded. When
    # that succeeds the customer gets a file locked to their own phone;
    # when it fails for any reason the original is sent unchanged, which
    # is exactly what they used to get before this existed.
    if _fm_bot_npvs_is_file "$src"; then
        # The Android edition: the whole config is re-sealed to this one
        # phone's public key, so a failure here is the same kind of
        # revenue leak an .npvt failure is and gets the same alert.
        if _fm_bot_npvs_build "$src" "$out_file" "$account" "$hwid" "$(_fm_bot_lang_get "$chat_id")" \
           && [[ -s "$out_file" ]]; then
            :
        else
            cp -f "$src" "$out_file"
            send_telegram_msg "$(_fm_bot_msg_fmt NPVT_BUILD_FAILED_ADMIN ar APP "$(_fm_html_escape "$app")" TYPE "$(_fm_html_escape "$type")" CHAT_ID "$chat_id" REASON "$(_fm_html_escape "${_FM_BOT_NPVT_ERR:-سبب غير معروف}")")"
        fi
    elif _fm_bot_npvt_is_file "$src"; then
        if _fm_bot_npvt_build "$src" "$out_file" "$account" "$hwid" "$exp_date" "$(_fm_bot_lang_get "$chat_id")" \
           && [[ -s "$out_file" ]]; then
            :
        else
            # Falling back to the stored file keeps the customer served,
            # but what they get is not bound to their device and can be
            # passed around freely. That is a silent revenue leak, so the
            # admin is told immediately with the reason rather than left
            # to work it out from a support message weeks later.
            cp -f "$src" "$out_file"
            send_telegram_msg "$(_fm_bot_msg_fmt NPVT_BUILD_FAILED_ADMIN ar APP "$(_fm_html_escape "$app")" TYPE "$(_fm_html_escape "$type")" CHAT_ID "$chat_id" REASON "$(_fm_html_escape "${_FM_BOT_NPVT_ERR:-سبب غير معروف}")")"
        fi
    # grep -I skips files it detects as binary (no match, exit 1) without
    # ever reading their bytes into a bash string — the only safe way to
    # tell "personalizable text template" from "opaque binary blob" (an
    # .ehi file, say) without an external `file` command dependency.
    elif grep -qI '' "$src" 2>/dev/null; then
        local content; content=$(cat "$src")
        # {HWID} is always what the customer actually typed. {USERNAME}/
        # {PASSWORD} are the real Linux account credentials instead —
        # identical to $hwid for a short id (the common case, unchanged
        # from before this distinction existed), but a DIFFERENT minted
        # short name for a long one (over _FM_BOT_NAME_MAX characters) —
        # substituting $hwid there for a minted account would hand the
        # customer a login that does not exist on the server at all.
        content="${content//\{HWID\}/$hwid}"
        content="${content//\{USERNAME\}/$account}"
        content="${content//\{PASSWORD\}/$account}"
        content="${content//\{SERVER_IP\}/$server_ip}"
        content="${content//\{EXPIRY\}/$exp_date}"
        printf '%s\n' "$content" > "$out_file"
    else
        cp -f "$src" "$out_file"
    fi

    _fm_bot_delivery_set "$account" "$app" "$type" "$hwid"

    local orig_name; orig_name=$(_fm_bot_appfile_meta_get "$app" "$type")
    if [[ -z "$orig_name" ]]; then
        # No stored name (an upload from before names were kept, or a
        # file placed by hand). Guess the extension from what the file
        # actually is — handing an NPV config a .txt name would leave the
        # customer with something their app refuses to open.
        orig_name="${app}_${type}"
        if _fm_bot_npvs_is_file "$src"; then orig_name+=".npvs"
        elif _fm_bot_npvt_is_file "$src"; then orig_name+=".npvt"
        else orig_name+=".txt"; fi
    fi
    # An NPV Tunnel/NPVS config is personalised per phone (the account is
    # baked into its encrypted body, and its in-app display name now gets
    # its own random tag — see _fm_bot_npvt_build/_fm_bot_npvs_build), so
    # two customers' Telegram documents genuinely need distinct names or
    # they'd stare at identical rows with no way to tell them apart. A
    # plain HWID-login template (HTTP Custom, HTTP Injector, …) is the
    # opposite: the exact same file works on every device — the app's own
    # HWID lock is what actually gates access — so renaming it here would
    # only add confusion for zero benefit. It goes out exactly as the
    # admin uploaded it.
    local send_name="$orig_name"
    if _fm_bot_npvs_is_file "$src" || _fm_bot_npvt_is_file "$src"; then
        local name_stem name_ext
        case "$orig_name" in
            *.*) name_stem="${orig_name%.*}"; name_ext=".${orig_name##*.}" ;;
            *)   name_stem="$orig_name"; name_ext="" ;;
        esac
        send_name="${name_stem}-${account}-$(date +%m%d%H%M%S)${name_ext}"
    fi
    local send_path; send_path="${out_file}_${send_name}"
    mv -f "$out_file" "$send_path"

    if [[ -f "$TELEGRAM_CONF" ]]; then
        local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
        source "$TELEGRAM_CONF" 2>/dev/null
        if [[ -n "$BOT_TOKEN" ]]; then
            curl -s -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendDocument" \
                -F "chat_id=${chat_id}" \
                -F "document=@${send_path};filename=${send_name}" \
                -F "caption=$(_fm_bot_msg_fmt APPFILE_CAPTION "$(_fm_bot_lang_get "$chat_id")" APP "$app" TYPE "$type")" >/dev/null 2>&1
        fi
    fi
    rm -f "$send_path"
    # The file now sits below the card, so the next screen has to be a
    # new message rather than an edit of one the customer has scrolled
    # past.
    _fm_bot_card_mark_dirty "$chat_id"

    # Right after the file itself, show how to actually use it inside the
    # app — a silent no-op if the admin hasn't uploaded any guide images
    # for this app.
    _fm_bot_send_file_guide "$chat_id" "$app"
}

# ── Per-app "where do I find my HWID" guide images ──────────────────────
# Every app shows its device id in a different place, and one screenshot
# often isn't enough to explain it — so each app gets its own ordered set
# of up to BOT_HWID_GUIDE_MAX images (Telegram: send a photo captioned
# "/addguide AppName", once per image; or the web panel, which can take
# several at once). They go out automatically as a single album right
# when the bot is about to ask for the customer's HWID — after they've
# already picked the app, so the pictures always match it.
BOT_HWID_GUIDE_MAX=10   # Telegram caps one media group at 10 items

# Legacy layout: exactly one image per app, stored at <guides>/<app>.
_fm_bot_hwid_guide_path() {
    printf '%s/%s' "$BOT_APP_HWID_GUIDE_DIR" "$1"
}

# Current layout: an ordered directory per app, <guides>/<app>.d/NN. The
# ".d" suffix is what lets both layouts sit on disk during migration — a
# plain file and a directory can't share one name.
_fm_bot_hwid_guide_dir() {
    printf '%s/%s.d' "$BOT_APP_HWID_GUIDE_DIR" "$1"
}

# Fold an install that predates multi-image support into the new layout,
# keeping its one existing screenshot as image #1. Runs on every read or
# write of this app's guides, and is a no-op once there's nothing to move.
_fm_bot_hwid_guide_migrate() {
    local app="$1" legacy dir
    legacy=$(_fm_bot_hwid_guide_path "$app")
    [[ -f "$legacy" ]] || return 0
    dir=$(_fm_bot_hwid_guide_dir "$app")
    mkdir -p "$dir" 2>/dev/null || return 1
    mv -f "$legacy" "${dir}/01" 2>/dev/null
}

# Full paths of this app's guide images, in the order the customer sees.
_fm_bot_hwid_guide_list() {
    local app="$1" dir
    _fm_bot_hwid_guide_migrate "$app"
    dir=$(_fm_bot_hwid_guide_dir "$app")
    [[ -d "$dir" ]] || return 0
    find "$dir" -mindepth 1 -maxdepth 1 -type f -printf '%p\n' 2>/dev/null | sort
}

_fm_bot_hwid_guide_count() {
    local n=0 line
    while IFS= read -r line; do [[ -n "$line" ]] && n=$((n+1)); done < <(_fm_bot_hwid_guide_list "$1")
    printf '%s' "$n"
}

# Append one more image. Prints "app:position" on success; rc 2 means the
# app is already at BOT_HWID_GUIDE_MAX.
_fm_bot_hwid_guide_add() {
    local app; app=$(_fm_bot_sanitize_slug "$1")
    local src_file="$2" dir last next idx
    [[ -n "$app" && -f "$src_file" ]] || return 1
    _fm_bot_hwid_guide_migrate "$app"
    dir=$(_fm_bot_hwid_guide_dir "$app")
    mkdir -p "$dir" 2>/dev/null || return 1
    [[ "$(_fm_bot_hwid_guide_count "$app")" -ge "$BOT_HWID_GUIDE_MAX" ]] && return 2
    # Numbered from the highest name in use rather than from the count, so
    # deleting image 2 of 3 can't make the next upload overwrite image 3.
    next=1
    last=$(find "$dir" -mindepth 1 -maxdepth 1 -type f -printf '%f\n' 2>/dev/null | sort | tail -n 1)
    [[ "$last" =~ ^[0-9]+$ ]] && next=$(( 10#$last + 1 ))
    printf -v idx '%02d' "$next"
    cp -f "$src_file" "${dir}/${idx}" || return 1
    printf '%s:%s' "$app" "$(_fm_bot_hwid_guide_count "$app")"
    return 0
}

# Every image this app has, in either layout.
_fm_bot_hwid_guide_del() {
    local app="$1"
    rm -f "$(_fm_bot_hwid_guide_path "$app")" 2>/dev/null
    rm -rf "$(_fm_bot_hwid_guide_dir "$app")" 2>/dev/null
}

# One image, addressed by its position in the list the customer is shown.
_fm_bot_hwid_guide_del_one() {
    local app="$1" n="$2" target
    [[ "$n" =~ ^[0-9]+$ ]] && (( n >= 1 )) || return 1
    target=$(_fm_bot_hwid_guide_list "$app" | sed -n "${n}p")
    [[ -n "$target" ]] || return 1
    rm -f "$target" 2>/dev/null
}

_fm_bot_hwid_guide_has() {
    [[ -n "$(_fm_bot_hwid_guide_list "$1" | head -n 1)" ]]
}

# Silent no-op if this app has no guide images — the feature is optional
# per app, not mandatory for every one the admin sets up.
# Shared by every per-app image-set feature (HWID guides, file-usage
# guides, and any future one): a single image goes out as an ordinary
# photo, two or more as one swipeable album with the caption on the
# first — split across several albums past Telegram's 10-item cap.
_fm_bot_send_image_set() {
    local chat_id="$1" caption="$2"; shift 2
    local -a imgs=("$@")
    (( ${#imgs[@]} > 0 )) || return 0
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" ]] || return 0

    if (( ${#imgs[@]} == 1 )); then
        curl -s -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendPhoto" \
            -F "chat_id=${chat_id}" \
            -F "photo=@${imgs[0]}" \
            -F "caption=${caption}" >/dev/null 2>&1
        return 0
    fi

    # Multipart fields carry text verbatim — unlike the -d form bodies the
    # rest of this file uses, %0A is NOT decoded — so the caption's
    # newlines are made real first, then escaped for the JSON media array.
    local cap_json="${caption//%0A/$'\n'}"
    cap_json="${cap_json//\\/\\\\}"
    cap_json="${cap_json//\"/\\\"}"
    cap_json="${cap_json//$'\r'/}"
    cap_json="${cap_json//$'\t'/\\t}"
    cap_json="${cap_json//$'\n'/\\n}"

    local i=0 j media_json item
    local -a curl_args
    while (( i < ${#imgs[@]} )); do
        curl_args=(-s -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMediaGroup" -F "chat_id=${chat_id}")
        media_json="["
        j=0
        while (( j < 10 && i < ${#imgs[@]} )); do
            item="{\"type\":\"photo\",\"media\":\"attach://g${j}\""
            (( i == 0 )) && item+=",\"caption\":\"${cap_json}\""
            item+="}"
            (( j > 0 )) && media_json+=","
            media_json+="$item"
            curl_args+=(-F "g${j}=@${imgs[$i]}")
            i=$((i+1)); j=$((j+1))
        done
        media_json+="]"
        curl_args+=(-F "media=${media_json}")
        curl "${curl_args[@]}" >/dev/null 2>&1
    done
}

# ── The written explanation that accompanies each gallery ─────────────
# Pictures alone give the admin no way to say "tap the three dots, then
# Import" in words, and some apps need the words more than the pictures.
# One note per (gallery, app); no note means the customer sees exactly
# what they saw before this existed.
_fm_bot_guide_note_dir() {
    [[ "$1" == "file" ]] && printf '%s' "$BOT_APP_FILE_NOTE_DIR" || printf '%s' "$BOT_APP_HWID_NOTE_DIR"
}

_fm_bot_guide_note_path() {
    local app; app=$(_fm_bot_sanitize_slug "$2")
    [[ -n "$app" ]] || return 1
    printf '%s/%s' "$(_fm_bot_guide_note_dir "$1")" "$app"
}

_fm_bot_guide_note_get() {
    local path; path=$(_fm_bot_guide_note_path "$1" "$2") || return 0
    [[ -f "$path" ]] || return 0
    cat "$path" 2>/dev/null
}

# Blank text deletes the note, so "cleared in the panel" and "never
# written" are the same state — there is no empty note that would send a
# stray blank line to customers.
_fm_bot_guide_note_set() {
    local kind="$1" app="$2" text="$3" path
    path=$(_fm_bot_guide_note_path "$kind" "$app") || return 1
    if [[ -z "${text//[[:space:]]/}" ]]; then
        rm -f "$path" 2>/dev/null
        return 0
    fi
    mkdir -p "$(dirname "$path")" 2>/dev/null || return 1
    printf '%s' "$text" > "${path}.tmp" 2>/dev/null || return 1
    mv -f "${path}.tmp" "$path" 2>/dev/null || { rm -f "${path}.tmp" 2>/dev/null; return 1; }
    return 0
}

# The note is free text the admin typed, so it may legitimately contain
# "&", "<" or "=" — characters that would corrupt an ordinary
# `-d "text=..."` body (curl sends it verbatim, so "&" would split the
# field) and, worse, make Telegram reject the whole message under
# parse_mode=HTML, leaving the customer with nothing. It therefore gets
# its own sender: HTML-escaped so the parser cannot choke on it, and
# passed through --data-urlencode so every byte survives intact.
# send_telegram_msg_to is left alone — every other caller feeds it
# %0A-encoded panel templates that this treatment would double-encode.
_fm_bot_send_note_to() {
    local target_chat="$1" text="$2"
    [[ -n "$text" ]] || return 0
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" && -n "$target_chat" ]] || return 0
    text="${text//&/\&amp;}"   # see _fm_html_escape: "&" unescaped here
    text="${text//</\&lt;}"    # means "the matched text", not a literal
    text="${text//>/\&gt;}"
    _fm_bot_card_mark_dirty "$target_chat" 2>/dev/null || true
    curl -s -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" \
        -d "chat_id=${target_chat}" \
        --data-urlencode "text=${text}" \
        -d "parse_mode=HTML" &>/dev/null &
}

# One delivery path for both galleries: the images (if any) plus the
# admin's written note (if any). The note rides along as the album's
# caption when it comfortably fits, and goes out as its own message when
# it does not — Telegram rejects the ENTIRE send when a caption passes
# 1024 characters, so a long explanation must never be attached to the
# pictures. An app with a note but no images still gets the note; an app
# with neither gets nothing at all, exactly as before.
_fm_bot_send_guide_set() {
    local chat_id="$1" kind="$2" app="$3" caption="$4"; shift 4
    local -a imgs=("$@")
    local note; note=$(_fm_bot_guide_note_get "$kind" "$app")

    if (( ${#imgs[@]} == 0 )); then
        [[ -n "$note" ]] && _fm_bot_send_note_to "$chat_id" "$note"
        return 0
    fi

    local combined="$caption"
    local send_note_separately=0
    if [[ -n "$note" ]]; then
        combined="${caption}%0A%0A${note}"
        if (( ${#combined} > BOT_GUIDE_CAPTION_MAX )); then
            combined="$caption"
            send_note_separately=1
        fi
    fi
    _fm_bot_send_image_set "$chat_id" "$combined" "${imgs[@]}"
    (( send_note_separately )) && _fm_bot_send_note_to "$chat_id" "$note"
    _fm_bot_card_mark_dirty "$chat_id"
    return 0
}

_fm_bot_send_hwid_guide() {
    local chat_id="$1" app="$2" line
    local -a imgs=()
    while IFS= read -r line; do [[ -n "$line" ]] && imgs+=("$line"); done < <(_fm_bot_hwid_guide_list "$app")
    local caption; caption=$(_fm_bot_msg_fmt HWID_GUIDE_CAPTION "$(_fm_bot_lang_get "$chat_id")" APP "$app")
    _fm_bot_send_guide_set "$chat_id" "hwid" "$app" "$caption" "${imgs[@]}"
}

# ── Per-app "how do I add this file inside the app" guide images ────────
# Same idea as the HWID guides above, but for the OTHER direction: once
# the config file has been delivered, these show the customer how to
# actually import/add it inside the app itself. Same ordered-directory
# layout, same BOT_HWID_GUIDE_MAX-style cap, same album delivery — just
# under its own directory so the two galleries never mix.
BOT_FILE_GUIDE_MAX=10   # Telegram caps one media group at 10 items

_fm_bot_file_guide_dir() {
    printf '%s/%s' "$BOT_APP_FILE_GUIDE_DIR" "$1"
}

_fm_bot_file_guide_list() {
    local dir; dir=$(_fm_bot_file_guide_dir "$1")
    [[ -d "$dir" ]] || return 0
    find "$dir" -mindepth 1 -maxdepth 1 -type f -printf '%p\n' 2>/dev/null | sort
}

_fm_bot_file_guide_count() {
    local n=0 line
    while IFS= read -r line; do [[ -n "$line" ]] && n=$((n+1)); done < <(_fm_bot_file_guide_list "$1")
    printf '%s' "$n"
}

# Prints "app:position" on success; rc 2 means the app is already at
# BOT_FILE_GUIDE_MAX.
_fm_bot_file_guide_add() {
    local app; app=$(_fm_bot_sanitize_slug "$1")
    local src_file="$2" dir last next idx
    [[ -n "$app" && -f "$src_file" ]] || return 1
    dir=$(_fm_bot_file_guide_dir "$app")
    mkdir -p "$dir" 2>/dev/null || return 1
    [[ "$(_fm_bot_file_guide_count "$app")" -ge "$BOT_FILE_GUIDE_MAX" ]] && return 2
    next=1
    last=$(find "$dir" -mindepth 1 -maxdepth 1 -type f -printf '%f\n' 2>/dev/null | sort | tail -n 1)
    [[ "$last" =~ ^[0-9]+$ ]] && next=$(( 10#$last + 1 ))
    printf -v idx '%02d' "$next"
    cp -f "$src_file" "${dir}/${idx}" || return 1
    printf '%s:%s' "$app" "$(_fm_bot_file_guide_count "$app")"
    return 0
}

_fm_bot_file_guide_del() {
    rm -rf "$(_fm_bot_file_guide_dir "$1")" 2>/dev/null
}

_fm_bot_file_guide_del_one() {
    local app="$1" n="$2" target
    [[ "$n" =~ ^[0-9]+$ ]] && (( n >= 1 )) || return 1
    target=$(_fm_bot_file_guide_list "$app" | sed -n "${n}p")
    [[ -n "$target" ]] || return 1
    rm -f "$target" 2>/dev/null
}

_fm_bot_file_guide_has() {
    [[ -n "$(_fm_bot_file_guide_list "$1" | head -n 1)" ]]
}

# Silent no-op if this app has no guide images. Called right after the
# config file itself is delivered (see _fm_bot_appfile_render_and_send),
# so the customer sees "here's your file" immediately followed by "here's
# how to use it" rather than the two arriving in an unpredictable order.
_fm_bot_send_file_guide() {
    local chat_id="$1" app="$2" line
    local -a imgs=()
    while IFS= read -r line; do [[ -n "$line" ]] && imgs+=("$line"); done < <(_fm_bot_file_guide_list "$app")
    local caption; caption=$(_fm_bot_msg_fmt FILE_GUIDE_CAPTION "$(_fm_bot_lang_get "$chat_id")" APP "$app")
    _fm_bot_send_guide_set "$chat_id" "file" "$app" "$caption" "${imgs[@]}"
}

# ── Pending manual-payment orders: order_id:telegram_id:hwid:amount:coupon:status:timestamp ──
_fm_bot_next_order_id() {
    local n=0
    [[ -f "$BOT_ORDER_SEQ_FILE" ]] && n=$(cat "$BOT_ORDER_SEQ_FILE" 2>/dev/null)
    [[ "$n" =~ ^[0-9]+$ ]] || n=0
    n=$((n+1))
    mkdir -p "$(dirname "$BOT_ORDER_SEQ_FILE")" 2>/dev/null
    echo "$n" > "$BOT_ORDER_SEQ_FILE"
    echo "$n"
}

# $5 (optional) = "app|type" the customer picked BEFORE being asked for
# their HWID, in the app-file-first flow — remembered on the order so
# _fm_bot_admin_approve_order can still deliver the right file once the
# order is actually approved (possibly hours later), not only right when
# a wallet purchase activates instantly.
# $6 (optional, default "1") = which duration tier ("1" or "2" months) —
# remembered the same way, so approval days later still provisions the
# tier the customer actually picked instead of always the 1-month plan.
_fm_bot_order_create() {
    local tg="$1" hwid="$2" amount="$3" coupon="$4" app_type="$5" tier="${6:-1}"
    mkdir -p "$(dirname "$BOT_ORDERS_DB")" 2>/dev/null
    local order_id; order_id=$(_fm_bot_next_order_id)
    echo "${order_id}:${tg}:${hwid}:${amount}:${coupon:--}:pending:$(date +%s):${app_type}:${tier}" >> "$BOT_ORDERS_DB"
    echo "$order_id"
}

_fm_bot_order_get() {
    local id="$1"
    [[ -f "$BOT_ORDERS_DB" ]] || return 1
    grep "^${id}:" "$BOT_ORDERS_DB" | tail -1
}

_fm_bot_order_set_status() {
    local id="$1" status="$2"
    local line; line=$(_fm_bot_order_get "$id") || return 1
    local o_id o_tg o_hwid o_amt o_coupon o_status o_ts o_apptype o_tier
    IFS=: read -r o_id o_tg o_hwid o_amt o_coupon o_status o_ts o_apptype o_tier <<< "$line"
    sed -i "/^${id}:/d" "$BOT_ORDERS_DB"
    echo "${o_id}:${o_tg}:${o_hwid}:${o_amt}:${o_coupon}:${status}:${o_ts}:${o_apptype}:${o_tier}" >> "$BOT_ORDERS_DB"
}

_fm_bot_order_list_pending() {
    [[ -f "$BOT_ORDERS_DB" ]] || return 0
    awk -F: '$6=="pending"' "$BOT_ORDERS_DB"
}

# ── Multi-server node dispatch: routes an account-affecting bot call to
# a registered remote VPN node instead of running it on this box, while a
# single-box deployment (no nodes registered — the default for every
# install today) resolves to "local" every time and nothing changes.
# See panel.py's read_bot_nodes/bot_node_get for the CONTROLLER-side
# registry this reads (same file, same row format: written by the admin
# panel, consumed here by the live bot). ────────────────────────────────
_fm_bot_node_get() {
    local slug="$1" db="${BOT_NODES_CONF:-/etc/firewallfalcon/bot_nodes.db}"
    [[ -n "$slug" && -f "$db" ]] || return 1
    local line; line=$(awk -F: -v s="$slug" '$1==s{print; exit}' "$db")
    [[ -n "$line" ]] || return 1
    printf '%s' "$line"
}

# Splits a node row (from _fm_bot_node_get) via bash `read`, which glues
# everything past the last named var onto it — base_url routinely
# contains "://" of its own, so it must stay last, exactly like a
# region's url. Sets NODE_SLUG/NODE_TOKEN/NODE_FINGERPRINT/NODE_BASE_URL.
_fm_bot_node_fields() {
    IFS=: read -r NODE_SLUG NODE_TOKEN NODE_FINGERPRINT NODE_BASE_URL <<< "$1"
}

# Per-chat sticky node pick — set once when a customer taps a "node" mode
# region (see _fm_bot_send_region_list's dispatch), read again at every
# later step of the SAME flow (device/app/country/HWID all happen after
# the region pick, so the choice has to survive several pending-state
# transitions) without widening the pending-state tuple itself. Same tiny
# flat-file shape as _fm_bot_lang_get/_fm_bot_lang_set.
_fm_bot_node_selected_get() {
    local chat_id="$1" db="${BOT_NODE_SELECTED_DB:-/etc/firewallfalcon/bot_node_selected.db}"
    [[ -f "$db" ]] || return 0
    awk -F: -v c="$chat_id" '$1==c{print $2; exit}' "$db"
}

_fm_bot_node_selected_set() {
    local chat_id="$1" slug="$2" db="${BOT_NODE_SELECTED_DB:-/etc/firewallfalcon/bot_node_selected.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db"
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    echo "${chat_id}:${slug}" >> "$db"
}

# Which phone the customer picked (android/ios). Remembered for the same
# reason the node pick is: the app/country/SIM-type/file-type steps that
# follow fill both slots of the pending-state tuple, so by the time we
# know whether a file actually exists the device is long gone from it —
# and sending someone back to "pick an app" needs it, or they would be
# shown apps their phone cannot use.
_fm_bot_device_selected_set() {
    local chat_id="$1" device="$2" db="${BOT_DEVICE_SELECTED_DB:-/etc/firewallfalcon/bot_device_selected.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db"
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    echo "${chat_id}:${device}" >> "$db"
}

_fm_bot_device_selected_get() {
    local chat_id="$1" db="${BOT_DEVICE_SELECTED_DB:-/etc/firewallfalcon/bot_device_selected.db}"
    [[ -f "$db" ]] || return 0
    awk -F: -v c="$chat_id" '$1==c{print $2; exit}' "$db" 2>/dev/null
}

_fm_bot_node_selected_clear() {
    local chat_id="$1" db="${BOT_NODE_SELECTED_DB:-/etc/firewallfalcon/bot_node_selected.db}"
    [[ -f "$db" ]] || return 0
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
}

# Durable owner/account -> node index. A renewal, HWID change, or
# /myaccount lookup has no region step of its own (it's not a first
# purchase), so it has to remember which node an EXISTING account lives
# on rather than asking the customer again. Row: account:node_slug:
# owner_tag — owner_tag last since it routinely contains its own colon
# (tg:<chat_id>), same convention as everywhere else in this file.
_fm_bot_node_accounts_get_by_account() {
    local account="$1" db="${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}"
    [[ -n "$account" && -f "$db" ]] || return 0
    awk -F: -v a="$account" '$1==a{print $2; exit}' "$db"
}

_fm_bot_node_accounts_set() {
    local account="$1" slug="$2" owner_tag="$3" db="${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}"
    [[ -n "$account" && -n "$slug" ]] || return 1
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db"
    _fm_db_replace_row "$db" ":" 1 "$account" "${account}:${slug}:${owner_tag}"
}

_fm_bot_node_accounts_rename() {
    local old_account="$1" new_account="$2" db="${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}"
    [[ -n "$old_account" && -n "$new_account" && -f "$db" ]] || return 0
    local line; line=$(awk -F: -v a="$old_account" '$1==a{print; exit}' "$db")
    [[ -n "$line" ]] || return 0
    local _a slug owner; IFS=: read -r _a slug owner <<< "$line"
    _fm_db_replace_row "$db" ":" 1 "$old_account" "${new_account}:${slug}:${owner}"
}

_fm_bot_node_accounts_list_for_owner() {
    local owner_tag="$1" db="${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}"
    [[ -n "$owner_tag" && -f "$db" ]] || return 0
    # وسم المالك نفسه يحمل نقطتين ("tg:123")، فيحتلّ الحقل الثالث وما
    # بعده. مقارنة $3 وحده كانت تقارن "tg" بـ"tg:123" فلا تُطابق أبدًا —
    # أي أن حسابات العُقد كانت غير مرئية تمامًا لكل ما يعتمد على هذه
    # الدالة (حساباتي، التجديد، تغيير الجهاز). نُعيد تركيب الوسم كاملًا.
    awk -F: -v o="$owner_tag" '{ owner=$3; for(i=4;i<=NF;i++) owner=owner ":" $i; if (owner==o) print $1 }' "$db"
}

# Device -> node cache (short ids only need the account index above,
# since the account name IS the device id; a long NPV Tunnel id needs
# this too, because the minted account name isn't derivable from the
# device string, and the mapping that WOULD tell us — NPVT_DEVICES_DB —
# lives on whichever node actually minted it, not on this controller).
# Row: device:node_slug:owner_tag.
_fm_bot_node_device_get() {
    local device="$1" db="${BOT_NODE_DEVICE_MAP_DB:-/etc/firewallfalcon/bot_node_device_map.db}"
    [[ -n "$device" && -f "$db" ]] || return 0
    awk -F: -v d="$device" '$1==d{print $2; exit}' "$db"
}

_fm_bot_node_device_owner_get() {
    local device="$1" db="${BOT_NODE_DEVICE_MAP_DB:-/etc/firewallfalcon/bot_node_device_map.db}"
    [[ -n "$device" && -f "$db" ]] || return 0
    awk -F: -v d="$device" '$1==d{ owner=$3; for(i=4;i<=NF;i++) owner=owner ":" $i; print owner; exit }' "$db"
}

_fm_bot_node_device_set() {
    local device="$1" slug="$2" owner_tag="$3" db="${BOT_NODE_DEVICE_MAP_DB:-/etc/firewallfalcon/bot_node_device_map.db}"
    [[ -n "$device" && -n "$slug" ]] || return 1
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db"
    _fm_db_replace_row "$db" ":" 1 "$device" "${device}:${slug}:${owner_tag}"
}

# Decides which node (slug) a specific device/chat's next call should
# route through, or prints nothing for "local" — the single-box default
# and what every call resolves to as long as bot_nodes.db stays empty.
# Priority: (1) this exact device already has a known home — a renewal
# or second purchase from the same phone must never move to a different
# node than its first purchase; (2) this chat's sticky pick from the
# region step, for a first-time creation; (3) local. A slug that no
# longer resolves to a registered node (deleted since it was recorded)
# falls back to local rather than erroring, since silently refusing
# service over a stale pointer would be worse than serving it locally.
_fm_bot_resolve_node_for_call() {
    local device="$1" chat_id="${2:-}"
    local slug acct
    # (1) What the customer JUST chose, when they were asked at all.
    #
    # This is deliberately ahead of the history below. The account index
    # used to win, and that quietly overruled the customer: a device that
    # already had a Germany account got Germany again no matter which
    # region was picked, because for any device id short enough to be an
    # account name (every HTTP Custom / Injector id) the index lookup
    # finds that same account and answers "Germany". Picking Saudi
    # changed nothing at all, with no error to show for it.
    #
    # This is only safe because the pick is set ONLY by the region step
    # of the current flow, and cleared both when a non-node region is
    # chosen and at the start of every flow — so "a pick exists" really
    # does mean "the customer chose it just now", and an operation with
    # no region step (renew, /myaccount) still falls through to the
    # history below and keeps landing where its account actually lives.
    if [[ -n "$chat_id" ]]; then
        slug=$(_fm_bot_node_selected_get "$chat_id")
        if [[ -n "$slug" ]]; then
            _fm_bot_node_get "$slug" >/dev/null && { printf '%s' "$slug"; return 0; }
            # The customer explicitly picked a region wired to a node, but
            # no node is registered under that slug. Creating locally here
            # is what silently turned the bot's own controller into a VPN
            # server nobody meant to sell from — and it left no trace
            # anywhere. Say so instead, loudly, and let the caller refuse.
            printf '!%s' "$slug"
            return 0
        fi
    fi
    # (2) Where this account ACTUALLY lives, when it already exists and
    # nothing was picked in this flow. This is what keeps a renewal or a
    # device change on its own node instead of rebuilding it on the
    # controller: the device->node cache can be missing a row (it is only
    # written on a successful create), so the durable account index is
    # tried first of the two.
    if [[ -n "$device" ]]; then
        acct=$(_fm_bot_account_lookup_device "$device" 2>/dev/null) || acct=""
        if [[ -n "$acct" ]]; then
            slug=$(_fm_bot_node_accounts_get_by_account "$acct")
            if [[ -n "$slug" ]]; then
                _fm_bot_node_get "$slug" >/dev/null && { printf '%s' "$slug"; return 0; }
            fi
        fi
        slug=$(_fm_bot_node_device_get "$device")
        if [[ -n "$slug" ]]; then
            _fm_bot_node_get "$slug" >/dev/null && { printf '%s' "$slug"; return 0; }
        fi
    fi
    printf ''
}

_fm_json_str() { printf '%s' "$1" | jq -Rs .; }
_fm_json_get() { printf '%s' "$1" | jq -r --arg k "$2" '.[$k] // empty' 2>/dev/null; }

# Verifies a node's LIVE TLS certificate matches the fingerprint pinned
# at registration time — trust-on-first-use, the same model as an SSH
# host key — BEFORE trusting anything it says. Independent of the actual
# API call just below (which has to skip curl's own chain validation,
# since the cert is self-signed and there is no CA to validate against):
# a swapped/expired/wrong certificate is caught HERE, not silently
# accepted just because the handshake itself succeeded.
# A verified match is remembered for NODE_FP_CACHE_TTL seconds, keyed by
# host+port+expected fingerprint.
#
# Not an optimisation for its own sake: this check runs before EVERY node
# call, it spawns openssl and opens a TLS connection, and it is allowed
# up to 8 seconds. The bot handles messages one at a time, so on a slow
# or unreachable node that cost lands directly on the customer's wait —
# and any operation that makes two node calls paid it twice. Only a
# successful match is cached; a failure is always re-checked, so a node
# whose certificate really did change is never let through on a stale
# yes. Changing the fingerprint in the registry changes the key, so a
# re-registered node is re-verified immediately.
_fm_bot_node_verify_fingerprint() {
    local host="$1" port="$2" expected="$3"
    [[ -n "$expected" ]] || return 1
    local cache="${BOT_NODE_FP_CACHE:-/etc/firewallfalcon/.node_fp_cache}"
    local ttl="${NODE_FP_CACHE_TTL:-300}"
    local key="${host}:${port}:${expected,,}" now cached_at
    now=$(date +%s 2>/dev/null) || now=0
    if [[ -f "$cache" ]]; then
        cached_at=$(awk -F'\t' -v k="$key" '$1==k{print $2; exit}' "$cache" 2>/dev/null)
        if [[ "$cached_at" =~ ^[0-9]+$ ]] && (( now - cached_at < ttl )); then
            return 0
        fi
    fi
    local live
    live=$(echo | timeout 8 openssl s_client -connect "${host}:${port}" -servername "$host" 2>/dev/null \
        | openssl x509 -noout -fingerprint -sha256 2>/dev/null | awk -F= '{print $2}' | tr -d ':')
    [[ -n "$live" ]] || return 1
    [[ "${live,,}" == "${expected,,}" ]] || return 1
    mkdir -p "$(dirname "$cache")" 2>/dev/null
    _fm_db_replace_row "$cache" $'\t' 1 "$key" "${key}"$'\t'"${now}" 2>/dev/null
    return 0
}

# Low-level call to a registered node's /api/node/* surface. Prints
# "STATUS\nBODY" on stdout (status first line, response body is
# everything after) — NOT a global side-channel: every caller invokes
# this via command substitution (`out=$(_fm_bot_node_api_call ...)`),
# which runs the function in a subshell, so any plain global variable
# this function assigned would vanish the instant that subshell exits.
# Encoding the status INTO the captured stdout is the only form that
# actually survives back to the caller. Returns non-zero only for a
# transport-level failure (bad node, failed fingerprint check, curl
# couldn't connect at all) — a well-formed error response (409, 404,
# ...) still returns 0 with a status line, since that's not a transport
# failure, it's an answer (see panel.py's handle_node_route for what
# each endpoint's status codes mean).
# ── Circuit breaker: a node that just failed is not retried for
# NODE_DOWN_TTL seconds ────────────────────────────────────────────────
# The bot handles messages strictly one at a time, and a node call can
# burn its full openssl (8s) + curl (10s) budget before failing. So ONE
# unreachable node used to cost ~18 seconds on EVERY call that touched
# it — and several calls make two. With a backlog of waiting customers
# that compounds into the bot looking frozen for a very long time, while
# nothing anywhere says a node is unreachable.
#
# Failing fast changes none of the outcomes (the call was going to fail
# either way) — only how long everyone else waits for it to happen. The
# admin is told once per outage, not once per call.
_fm_bot_node_down_mark() {
    local slug="$1" reason="${2:-}"
    local db="${BOT_NODE_DOWN_DB:-/etc/firewallfalcon/.node_down}"
    local now; now=$(date +%s 2>/dev/null) || now=0
    local already; already=$(awk -F'\t' -v s="$slug" '$1==s{print $2; exit}' "$db" 2>/dev/null)
    mkdir -p "$(dirname "$db")" 2>/dev/null
    _fm_db_replace_row "$db" $'\t' 1 "$slug" "${slug}"$'\t'"${now}"$'\t'"${reason}" 2>/dev/null
    # Only the transition into "down" is worth an alert; repeating it for
    # every call during the outage would bury the admin's chat.
    if [[ ! "$already" =~ ^[0-9]+$ ]]; then
        _log_action "NODE_DOWN" "$slug" "reason=${reason}" "ERROR" "bot" 2>/dev/null
        send_telegram_msg "🚨 <b>عقدة لا تستجيب</b>%0Aالعقدة: <b>${slug}</b>%0Aالسبب: ${reason}%0A%0Aأُوقفت محاولات الاتصال بها مؤقتًا حتى لا تُبطئ البوت على بقية العملاء. ستُعاد المحاولة تلقائيًا." 2>/dev/null
    fi
}

_fm_bot_node_down_clear() {
    local slug="$1" db="${BOT_NODE_DOWN_DB:-/etc/firewallfalcon/.node_down}"
    [[ -f "$db" ]] || return 0
    grep -q "^${slug}"$'\t' "$db" 2>/dev/null || return 0
    _fm_db_replace_row "$db" $'\t' 1 "$slug" "" 2>/dev/null
    _log_action "NODE_UP" "$slug" "" "INFO" "bot" 2>/dev/null
    send_telegram_msg "✅ <b>عادت العقدة</b>: <b>${slug}</b>" 2>/dev/null
}

_fm_bot_node_is_down() {
    local slug="$1" db="${BOT_NODE_DOWN_DB:-/etc/firewallfalcon/.node_down}"
    local ttl="${NODE_DOWN_TTL:-60}"
    [[ -f "$db" ]] || return 1
    local at; at=$(awk -F'\t' -v s="$slug" '$1==s{print $2; exit}' "$db" 2>/dev/null)
    [[ "$at" =~ ^[0-9]+$ ]] || return 1
    local now; now=$(date +%s 2>/dev/null) || now=0
    (( now - at < ttl ))
}

_fm_bot_node_api_call() {
    local slug="$1" method="$2" path="$3" body="${4:-}"
    local row; row=$(_fm_bot_node_get "$slug") || return 1
    _fm_bot_node_fields "$row"
    [[ -n "$NODE_BASE_URL" ]] || return 1
    # Known-bad right now: fail immediately instead of making everyone
    # else wait out the timeouts again.
    _fm_bot_node_is_down "$slug" && return 4
    local host port
    host=$(printf '%s' "$NODE_BASE_URL" | sed -E 's#^[a-zA-Z]+://##; s#[:/].*$##')
    port=$(printf '%s' "$NODE_BASE_URL" | sed -nE 's#^[a-zA-Z]+://[^:/]+:([0-9]+).*$#\1#p')
    [[ -n "$host" ]] || return 1
    [[ -n "$port" ]] || port=44381
    if ! _fm_bot_node_verify_fingerprint "$host" "$port" "$NODE_FINGERPRINT"; then
        _fm_bot_node_down_mark "$slug" "فشل التحقق من بصمة الشهادة أو تعذّر الاتصال"
        return 2
    fi
    local resp status
    if ! resp=$(curl -sS -k --max-time 10 -X "$method" \
        -H "X-Node-Token: ${NODE_TOKEN}" -H "Content-Type: application/json" \
        ${body:+-d "$body"} -w '\n%{http_code}' \
        "${NODE_BASE_URL}${path}" 2>/dev/null); then
        _fm_bot_node_down_mark "$slug" "لم يصل أي رد من العقدة"
        return 3
    fi
    status="${resp##*$'\n'}"
    if [[ ! "$status" =~ ^[0-9]+$ ]]; then
        _fm_bot_node_down_mark "$slug" "رد غير مفهوم من العقدة"
        return 3
    fi
    # Any well-formed answer — including 404/409 — proves the node is
    # reachable and authenticating, so the outage (if any) is over.
    _fm_bot_node_down_clear "$slug"
    printf '%s\n%s' "$status" "${resp%$'\n'*}"
}

# Splits the "STATUS\nBODY" stdout of _fm_bot_node_api_call. Sets
# NODE_CALL_STATUS/NODE_CALL_BODY.
_fm_bot_node_call_split() {
    NODE_CALL_STATUS="${1%%$'\n'*}"
    NODE_CALL_BODY="${1#*$'\n'}"
}

# ── Account provisioning: the one place that turns a device id + plan
# limits into a real, working HWID SSH account ──────────────────────────
# Prints nothing; sets _FM_BOT_LAST_EXPIRE on success so callers can
# report the expiry without re-deriving it.
#
# A device id reused by its OWN owner (same tg:<chat_id> that created it)
# is not a conflict — someone reinstalling their app, refreshing their
# device id, or upgrading a trial into a paid month is completely normal.
# In that case this RENEWS the existing account in place (new expiry,
# devices, bandwidth cap — usage counter reset) instead of failing, so the
# same HWID just keeps working with no re-registration friction. Reused by
# a DIFFERENT owner is still rejected — that would mean silently handing
# someone else's account to a stranger. A paid ("web") account is also
# never silently downgraded by a trial request for the same device.
#
# Returns: 0 created, 1 device id belongs to someone else (or an orphaned
# system user with no matching owner we can verify), 2 system failure,
# 3 renewed (same owner, existing account extended in place).
_FM_BOT_LAST_EXPIRE=""
# Set by _fm_bot_cmd_trial/_fm_bot_cmd_subscribe on success, so the
# button-driven flow (which asks for an app/file-type BEFORE the HWID)
# knows which device to render the chosen config file for afterward.
_FM_BOT_LAST_HWID=""
_fm_bot_provision_hwid_account() {
    local device="$1" hours="$2" bw_gb="$3" devices="$4" owner_tag="$5" acct_type="$6" fresh="${7:-}"
    # The Linux account is named after the device id, except when that id
    # is too long to be a username — NPV Tunnel's are 64 characters — in
    # which case a short name is minted for it. Short ids come back
    # unchanged, so every other app behaves exactly as it did before.
    #
    # fresh=1 (a paid purchase) mints a brand new name instead of reusing
    # the device's last one, so buying a second month on the same phone
    # gives a second account rather than extending the first. It has no
    # effect on a short id, which *is* the username and cannot be
    # duplicated — and none on renewals either, since those come through
    # carrying an account name rather than a device id.
    local hwid
    if [[ "$fresh" == "1" ]]; then
        hwid=$(_fm_bot_account_name_mint_for_device "$device") || return 2
    else
        hwid=$(_fm_bot_account_name_for_device "$device") || return 2
    fi
    _FM_BOT_LAST_ACCOUNT="$hwid"

    local existing_line=""
    [[ -f "$DB_FILE" ]] && existing_line=$(awk -F: -v h="$hwid" '$1==h{print; exit}' "$DB_FILE")

    local expire_date
    if [[ "$hours" =~ ^[0-9]+$ && "$hours" -ge 24 ]]; then
        expire_date=$(date -d "+$((hours/24)) days" +%Y-%m-%d)
    else
        expire_date=$(date -d "+1 day" +%Y-%m-%d)
    fi

    if [[ -n "$existing_line" ]]; then
        # owner_tag is "tg:<chat_id>" — it has a colon of its own, so it
        # must be read the same way the rest of the bot reads this file
        # (bash `read`, which glues everything past the last named field
        # onto it) rather than with `awk -F:`, which would only capture
        # "tg" and silently drop the chat id.
        local ex_u ex_p ex_exp ex_lim ex_bw ex_dbw cur_type cur_owner
        IFS=: read -r ex_u ex_p ex_exp ex_lim ex_bw ex_dbw cur_type cur_owner <<< "$existing_line"
        if [[ "$cur_owner" != "$owner_tag" ]]; then
            return 1
        fi
        if [[ "$acct_type" == "trial" && "$cur_type" != "trial" ]]; then
            # Never let a free trial request quietly shrink someone's
            # already-paid subscription down to trial length.
            return 1
        fi
        chage -E "$expire_date" "$hwid" 2>/dev/null
        sed -i "/^${hwid}:/d" "$DB_FILE"
        echo "${hwid}:${hwid}:${expire_date}:${devices}:${bw_gb}:0:${acct_type}:${owner_tag}" >> "$DB_FILE"
        rm -f "$BANDWIDTH_DIR/${hwid}.usage" 2>/dev/null
        rm -rf "$BANDWIDTH_DIR/pidtrack/${hwid}" 2>/dev/null
        _fm_set_login_mode "$hwid" "hwid"
        _FM_BOT_LAST_EXPIRE="$expire_date"
        return 3
    fi

    if id "$hwid" &>/dev/null; then
        # A system user exists with no users.db row we can trace an owner
        # from (e.g. created outside the bot) — refuse rather than guess.
        return 1
    fi

    ensure_firewallfalcon_system_group
    if ! _fm_create_system_user "$hwid"; then
        return 2
    fi
    usermod -aG "$FF_USERS_GROUP" "$hwid" 2>/dev/null
    echo "${hwid}:${hwid}" | chpasswd
    chage -E "$expire_date" "$hwid"
    echo "${hwid}:${hwid}:${expire_date}:${devices}:${bw_gb}:0:${acct_type}:${owner_tag}" >> "$DB_FILE"
    _fm_set_login_mode "$hwid" "hwid"
    _FM_BOT_LAST_EXPIRE="$expire_date"
    return 0
}

# ── Local-or-remote dispatchers: drop-in replacements for the direct
# calls above, at every site that used to make them. Same arguments,
# same return codes, same globals set on success — with no node
# registered for this device/chat (bot_nodes.db empty or absent, the
# single-box default), each one falls straight through to the exact
# same local function with no other change, so an existing all-in-one
# install behaves byte-for-byte as it does today. ──────────────────────
_fm_bot_provision_hwid_account_dispatch() {
    local device="$1" hours="$2" bw_gb="$3" devices="$4" owner_tag="$5" acct_type="$6" fresh="${7:-}"
    local chat_id=""
    [[ "$owner_tag" == tg:* ]] && chat_id="${owner_tag#tg:}"
    local node; node=$(_fm_bot_resolve_node_for_call "$device" "$chat_id")
    if [[ "$node" == !* ]]; then
        # A node was meant to serve this, and none is registered under the
        # slug the customer picked. Refuse rather than build the account
        # here: this box is the bot's controller, and quietly creating a
        # customer on it is exactly the failure that went unnoticed until
        # customers were already living on the wrong server.
        _log_action "NODE_UNRESOLVED" "${device}" "region=${node#!} owner=${owner_tag}" "ERROR" "bot" 2>/dev/null
        send_telegram_msg "🚨 <b>عقدة غير مُسجَّلة</b>%0Aالمنطقة <b>${node#!}</b> مربوطة بعقدة، ولا توجد عقدة مسجَّلة بهذا الاسم.%0Aرُفض الطلب بدل إنشاء الحساب على سيرفر البوت.%0Aالجهاز: <code>${device}</code>" 2>/dev/null
        return 2
    fi
    if [[ -z "$node" ]]; then
        _fm_bot_provision_hwid_account "$device" "$hours" "$bw_gb" "$devices" "$owner_tag" "$acct_type" "$fresh"
        return $?
    fi
    local fresh_json="false"; [[ "$fresh" == "1" ]] && fresh_json="true"
    local body; body=$(printf '{"device":%s,"hours":%s,"bw_gb":%s,"devices":%s,"owner_tag":%s,"acct_type":%s,"fresh":%s}' \
        "$(_fm_json_str "$device")" "${hours:-0}" "${bw_gb:-0}" "${devices:-1}" \
        "$(_fm_json_str "$owner_tag")" "$(_fm_json_str "$acct_type")" "$fresh_json")
    local out; out=$(_fm_bot_node_api_call "$node" "POST" "/api/node/accounts" "$body")
    [[ $? -eq 0 ]] || return 2
    _fm_bot_node_call_split "$out"
    local resp="$NODE_CALL_BODY"
    case "$NODE_CALL_STATUS" in
        200)
            _FM_BOT_LAST_ACCOUNT=$(_fm_json_get "$resp" account)
            _FM_BOT_LAST_EXPIRE=$(_fm_json_get "$resp" expire_date)
            [[ -n "$_FM_BOT_LAST_ACCOUNT" ]] || return 2
            _fm_bot_node_accounts_set "$_FM_BOT_LAST_ACCOUNT" "$node" "$owner_tag"
            _fm_bot_node_device_set "$device" "$node" "$owner_tag"
            [[ "$(_fm_json_get "$resp" renewed)" == "true" ]] && return 3
            return 0
            ;;
        409) return 1 ;;
        *) return 2 ;;
    esac
}

# Wraps the ENTIRE "change HWID" operation for an EXISTING account —
# both branches _fm_bot_cmd_changehwid_finish used to run inline (short
# id: delete + recreate preserving expiry/limits; long id/NPV Tunnel:
# remap the device mapping only) — matching panel.py's single
# POST /api/node/accounts/<account>/hwid, which already implements both
# branches server-side. Returns 0 with _FM_BOT_LAST_ACCOUNT set to the
# resulting account name (same as old_account for a remap, a new name
# for a short-id swap), or 2 on failure.
_fm_bot_hwid_change_dispatch() {
    local old_account="$1" new_device="$2" old_line="$3"
    local db="${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}"
    local node; node=$(_fm_bot_node_accounts_get_by_account "$old_account")
    if [[ -n "$node" ]]; then
        local body; body=$(printf '{"device":%s}' "$(_fm_json_str "$new_device")")
        local out; out=$(_fm_bot_node_api_call "$node" "POST" "/api/node/accounts/$(_fm_urlenc "$old_account")/hwid" "$body")
        [[ $? -eq 0 ]] || return 2
        _fm_bot_node_call_split "$out"
        [[ "$NODE_CALL_STATUS" == "200" ]] || return 2
        local resp="$NODE_CALL_BODY"
        _FM_BOT_LAST_ACCOUNT=$(_fm_json_get "$resp" account)
        [[ -n "$_FM_BOT_LAST_ACCOUNT" ]] || return 2
        local owner; owner=$(awk -F: -v a="$old_account" '$1==a{ o=$3; for(i=4;i<=NF;i++) o=o ":" $i; print o; exit }' "$db" 2>/dev/null)
        [[ "$_FM_BOT_LAST_ACCOUNT" != "$old_account" ]] && _fm_bot_node_accounts_rename "$old_account" "$_FM_BOT_LAST_ACCOUNT"
        _fm_bot_node_device_set "$new_device" "$node" "$owner"
        return 0
    fi

    # Local. BOTH kinds of device id rebuild the account under a NEW
    # name now — a short id IS the name, an NPV Tunnel id gets a freshly
    # minted synthetic one.
    #
    # The NPV branch used to keep the old name and only repoint the
    # device mapping. That revoked nothing: the delivered file carries
    # "user" and "password" both set to the account name (see
    # _fm_bot_npvt_build), so an unchanged name means unchanged SSH
    # credentials — the OLD file kept authenticating against the server
    # forever. The device lock lives inside the file and is checked by
    # the app on the customer's phone, never by the server, so a customer
    # could collect one working file per device change. A new name is a
    # new password, and that is what actually kills the old session.
    local new_account
    if (( ${#new_device} > ${_FM_BOT_NAME_MAX:-32} )); then
        new_account=$(_fm_bot_account_name_mint_for_device "$new_device") || return 2
        [[ -n "$new_account" ]] || return 2
    else
        new_account="$new_device"
    fi
    local ou op oexp odev obw odbw oatype ownr
    IFS=: read -r ou op oexp odev obw odbw oatype ownr <<< "$old_line"
    # Changing device is NOT a new subscription: the account is rebuilt
    # under the new name, but everything the customer already had comes
    # with it — remaining days, GB quota, DAILY cap, device limit, and
    # above all the consumed-GB counter. Snapshot first, restore after.
    #
    # The old account is DISABLED, never deleted — userdel can fail
    # silently for reasons outside this project's control (busy home
    # dir, a session some distros still refuse to force through), and
    # when it does the code used to carry on regardless: the DB row and
    # bandwidth counters got wiped while the real system account kept
    # working untouched, right as a fresh one was created under a new
    # name — reported live as "the old account never disappears and a
    # second one exists alongside it." Locking + expiring cannot fail
    # that way (plain shadow attribute writes, independent of whether
    # the account is in use), so creating the new one next is now
    # unconditionally safe — nothing about the old account can block it.
    local snap; snap=$(mktemp -d 2>/dev/null) || return 2
    _fm_account_snapshot "$old_account" "$snap"

    _fm_disable_system_user "$old_account"
    [[ -f "$DB_FILE" ]] && sed -i "/^${old_account}:/d" "$DB_FILE" 2>/dev/null
    rm -f "$BANDWIDTH_DIR/${old_account}."* 2>/dev/null
    rm -rf "$BANDWIDTH_DIR/pidtrack/${old_account}" 2>/dev/null
    _fm_clear_login_mode "$old_account" 2>/dev/null

    ensure_firewallfalcon_system_group
    if ! _fm_create_system_user "$new_account"; then
        # The old account was only disabled, so undoing this is just
        # re-enabling it and putting its row back — nothing had to be
        # recreated from scratch, and nothing was ever actually lost.
        usermod -U "$old_account" 2>/dev/null
        chage -E "$oexp" "$old_account" 2>/dev/null
        _fm_account_restore "$snap" "$old_account"
        rm -rf "$snap" 2>/dev/null
        return 2
    fi
    usermod -aG "$FF_USERS_GROUP" "$new_account" 2>/dev/null
    echo "${new_account}:${new_account}" | chpasswd
    chage -E "$oexp" "$new_account" 2>/dev/null
    _fm_account_restore "$snap" "$new_account"
    rm -rf "$snap" 2>/dev/null
    _fm_set_login_mode "$new_account" "hwid"
    # The old NPV device mapping must go too, or the retired phone still
    # resolves to an account name that no longer serves it.
    if [[ "$new_account" != "$old_account" ]]; then
        _fm_db_replace_row "${NPVT_DEVICES_DB:-/etc/firewallfalcon/npvt_devices.db}" ":" 2 "$old_account" ""
    fi
    _FM_BOT_LAST_ACCOUNT="$new_account"
    return 0
}

_fm_urlenc() {
    local s="$1" out="" c i
    for (( i=0; i<${#s}; i++ )); do
        c="${s:i:1}"
        case "$c" in
            [a-zA-Z0-9.~_-]) out+="$c" ;;
            *) out+=$(printf '%%%02X' "'$c") ;;
        esac
    done
    printf '%s' "$out"
}

# Full status line for one account, in the exact users.db row shape
# (username:password:expire:conn_limit:bw:daily_bw:type:owner) so every
# existing `IFS=: read -r u p exp lim bw dbw t owner` call site keeps
# working whether the account is local or lives on a remote node.
_fm_bot_account_status_dispatch() {
    local account="$1"
    local node; node=$(_fm_bot_node_accounts_get_by_account "$account")
    if [[ -z "$node" ]]; then
        [[ -f "$DB_FILE" ]] && awk -F: -v h="$account" '$1==h{print; exit}' "$DB_FILE"
        return 0
    fi
    local out; out=$(_fm_bot_node_api_call "$node" "GET" "/api/node/accounts/$(_fm_urlenc "$account")" "")
    [[ $? -eq 0 ]] || return 1
    _fm_bot_node_call_split "$out"
    [[ "$NODE_CALL_STATUS" == "200" ]] || return 1
    local resp="$NODE_CALL_BODY"
    local u exp bw lim t owner
    u=$(_fm_json_get "$resp" account); exp=$(_fm_json_get "$resp" expire_date)
    bw=$(_fm_json_get "$resp" bandwidth_gb); lim=$(_fm_json_get "$resp" conn_limit)
    t=$(_fm_json_get "$resp" account_type); owner=$(_fm_json_get "$resp" owner)
    [[ -n "$u" ]] || return 1
    printf '%s:%s:%s:%s:%s:0:%s:%s\n' "$u" "$u" "$exp" "$lim" "$bw" "$t" "$owner"
}

# Every account line (users.db shape) owned by owner_tag, whether it
# lives on this box or a remote node — merges the local DB_FILE scan
# (today's exact behaviour, unchanged) with a lookup of every node this
# owner has an account recorded on via the durable index. With that
# index empty (no nodes ever registered), this is exactly "scan
# DB_FILE" — nothing new for a single-box deployment.
_fm_bot_accounts_for_owner_dispatch() {
    local owner_tag="$1"
    [[ -f "$DB_FILE" ]] && awk -F: -v o="$owner_tag" '
        NF==7 && $7==o { print; next }
        NF>=8 { owner=$8; for(i=9;i<=NF;i++) owner=owner ":" $i; if (owner==o) print }
    ' "$DB_FILE"
    local acct
    while IFS= read -r acct; do
        [[ -z "$acct" ]] && continue
        [[ -f "$DB_FILE" ]] && grep -q "^${acct}:" "$DB_FILE" && continue
        _fm_bot_account_status_dispatch "$acct"
    done < <(_fm_bot_node_accounts_list_for_owner "$owner_tag")
}

# Generic full teardown, local or remote — not wired to any call site
# yet in this release (the expired-account sweep stays node-local by
# design: it already runs on the box that owns the account, with no bot
# conversation involved), kept as a reusable primitive for whatever
# admin-initiated deletion needs it next.
_fm_bot_delete_account_dispatch() {
    local account="$1"
    local node; node=$(_fm_bot_node_accounts_get_by_account "$account")
    if [[ -z "$node" ]]; then
        delete_firewallfalcon_user_accounts "$account"
        return $?
    fi
    local out; out=$(_fm_bot_node_api_call "$node" "DELETE" "/api/node/accounts/$(_fm_urlenc "$account")" "")
    [[ $? -eq 0 ]] || return 2
    _fm_bot_node_call_split "$out"
    [[ "$NODE_CALL_STATUS" == "200" ]] || return 2
    sed -i "/^${account}:/d" "${BOT_NODE_ACCOUNTS_DB:-/etc/firewallfalcon/bot_node_accounts.db}" 2>/dev/null
    return 0
}

# The usage-status link has to point at wherever the account's traffic
# is actually measured — for a node-provisioned account that is the
# NODE itself (its own BW_LINK_PORT service, its own address baked
# into the URL), never this controller box, which runs no such service
# for that account at all. Prints the link on success; prints nothing
# and returns non-zero on failure, matching _fm_generate_bandwidth_link
# itself (never allowed to break the surrounding success message).
#
# READS the account's link, never re-issues it. Issuing rotates the
# token, and this is called more than once per operation — once for the
# customer's own success message, then again moments later to build the
# admin's subscription card (and again for every later /acct or
# /myaccount). Re-issuing meant the second call silently killed the link
# the customer had just been handed: their URL 404s forever while the
# panel shows a different token for the same account. That is exactly
# what it looked like — "the link is written wrong" — and it applied to
# node and local accounts alike.
#
# An account that has never had a link still gets one minted here (both
# sides fall through to issuing), so a brand-new or just-renamed account
# is unaffected.
_fm_bot_bandwidth_link_dispatch() {
    local account="$1"
    local node; node=$(_fm_bot_node_accounts_get_by_account "$account")
    if [[ -z "$node" ]]; then
        _fm_get_bandwidth_link "$account" 2>/dev/null && return 0
        _fm_generate_bandwidth_link "$account"
        return $?
    fi
    local out; out=$(_fm_bot_node_api_call "$node" "GET" "/api/node/accounts/$(_fm_urlenc "$account")/bandwidth-link" "")
    [[ $? -eq 0 ]] || return 1
    _fm_bot_node_call_split "$out"
    # A node still running a build from before the read/issue split knows
    # only the issuing POST. Falling back to it keeps the link working
    # there (with the old rotation behaviour) instead of showing none at
    # all, and it self-corrects the moment that node is updated.
    if [[ "$NODE_CALL_STATUS" == "404" || "$NODE_CALL_STATUS" == "405" ]]; then
        out=$(_fm_bot_node_api_call "$node" "POST" "/api/node/accounts/$(_fm_urlenc "$account")/bandwidth-link" "")
        [[ $? -eq 0 ]] || return 1
        _fm_bot_node_call_split "$out"
    fi
    [[ "$NODE_CALL_STATUS" == "200" ]] || return 1
    local link; link=$(_fm_json_get "$NODE_CALL_BODY" "link")
    [[ -n "$link" ]] || return 1
    printf '%s' "$link"
}

# ── Customer-facing commands: /trial, /subscribe, /balance, /myaccount,
# /appeal — reached only for a chat that is neither the admin nor a
# linked reseller (see the dispatch in _fm_telegram_poll_updates). ──────
_fm_bot_cmd_trial() {
    local chat_id="$1" hwid_in="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    if [[ -z "$hwid_in" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg TRIAL_CMD_USAGE "$lang")"
        return 1
    fi
    local hwid; hwid=$(_fm_validate_hwid "$hwid_in")
    if [[ -z "$hwid" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg INVALID_HWID "$lang")"
        return 1
    fi

    local max_uses used
    max_uses=$(_fm_bot_trial_max_for "$chat_id")
    used=$(_fm_bot_trial_count_for_user "$chat_id")
    if [[ "$used" -ge "$max_uses" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt TRIAL_LIMIT_REACHED "$lang" MAX_USES "$max_uses" HWID "$hwid")"
        return 1
    fi
    if _fm_bot_trial_hwid_used "$hwid"; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg TRIAL_DEVICE_USED "$lang")"
        return 1
    fi

    # Plan values follow the node this trial actually lands on, resolved
    # exactly the way the provisioning dispatch just below resolves it
    # (the device's own node first, then whatever the customer picked),
    # so what the success message promises is what the account is really
    # created with. No node registered anywhere = empty = the global
    # plan, i.e. unchanged behaviour.
    local node; node=$(_fm_bot_resolve_node_for_call "$hwid" "$chat_id")
    local hours bw devices
    hours=$(_fm_bot_get_plan TRIAL_HOURS "$node")
    bw=$(_fm_bot_get_plan TRIAL_BW_GB "$node")
    devices=$(_fm_bot_get_plan TRIAL_DEVICES "$node")

    _fm_bot_provision_hwid_account_dispatch "$hwid" "$hours" "$bw" "$devices" "tg:${chat_id}" "trial"
    local rc=$?
    if [[ $rc -eq 1 ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg TRIAL_DEVICE_TAKEN "$lang")"
        return 1
    elif [[ $rc -eq 2 ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg PROVISION_FAILED "$lang")"
        return 1
    fi

    _fm_bot_trial_log_use "$chat_id" "$hwid"
    echo "$TRIAL_CLEANUP_SCRIPT $hwid" | at now + ${hours} hours 2>/dev/null
    local bw_msg; if [[ "$lang" == "en" ]]; then bw_msg="Unlimited"; [[ "$bw" != "0" ]] && bw_msg="${bw} GB"; else bw_msg="غير محدود"; [[ "$bw" != "0" ]] && bw_msg="${bw} جيجابايت"; fi
    local success_key="TRIAL_SUCCESS_NEW"; [[ $rc -eq 3 ]] && success_key="TRIAL_SUCCESS_RENEWED"
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt "$success_key" "$lang" HWID "$hwid" HOURS "$hours" DEVICES "$devices" BW "$bw_msg" EXPIRE "$_FM_BOT_LAST_EXPIRE")"
    local admin_key="TRIAL_ADMIN_NEW"; [[ $rc -eq 3 ]] && admin_key="TRIAL_ADMIN_RENEWED"
    send_telegram_msg "$(_fm_bot_msg_fmt "$admin_key" ar CHAT_ID "$chat_id" HWID "$hwid")"
    _FM_BOT_LAST_HWID="$hwid"
    return 0
}

_fm_bot_cmd_subscribe() {
    local chat_id="$1" args="$2" chosen_app="$3" chosen_type="$4" tier="${5:-1}"
    [[ "$tier" == "2" ]] || tier="1"
    local price_key="MONTHLY_PRICE_SAR" days_key="MONTHLY_DAYS" bw_key="MONTHLY_BW_GB" devices_key="MONTHLY_DEVICES"
    if [[ "$tier" == "2" ]]; then
        price_key="MONTHLY2_PRICE_SAR"; days_key="MONTHLY2_DAYS"; bw_key="MONTHLY2_BW_GB"; devices_key="MONTHLY2_DEVICES"
    fi
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    # Priced on the node the customer is buying for. The device isn't
    # known yet at this point (the usage message below needs a price
    # too), so this starts from their picked node and is corrected once
    # the device is in hand, just under here.
    local node; node=$(_fm_bot_resolve_node_for_call "" "$chat_id")
    local price; price=$(_fm_bot_get_plan "$price_key" "$node")
    if [[ -z "$args" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt SUBSCRIBE_CMD_USAGE "$lang" PRICE "$price")"
        return 1
    fi
    local hwid_in coupon_in
    hwid_in=$(awk '{print $1}' <<< "$args")
    coupon_in=$(awk '{print $2}' <<< "$args")

    local hwid; hwid=$(_fm_validate_hwid "$hwid_in")
    if [[ -z "$hwid" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg INVALID_HWID "$lang")"
        return 1
    fi
    # Note: no "already registered" pre-check here on purpose — the same
    # device reused by its own owner (e.g. renewing, or upgrading a trial
    # to paid) is a normal renewal, handled by
    # _fm_bot_provision_hwid_account below. A device belonging to someone
    # else is still rejected there.

    # A device that already lives on a node renews there whatever the
    # customer has picked since (that is what the provisioning dispatch
    # does), so re-resolve now that the device is known and re-price if
    # that moved us to a different node — otherwise the wallet would be
    # charged one node's price for service on another.
    local dev_node; dev_node=$(_fm_bot_resolve_node_for_call "$hwid" "$chat_id")
    if [[ "$dev_node" != "$node" ]]; then
        node="$dev_node"
        price=$(_fm_bot_get_plan "$price_key" "$node")
    fi

    local final_price="$price" coupon_applied=""
    if [[ -n "$coupon_in" ]]; then
        local previewed
        if previewed=$(_fm_bot_coupon_preview "$coupon_in" "$price"); then
            final_price="$previewed"
            coupon_applied="${coupon_in^^}"
        else
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt SUBSCRIBE_COUPON_INVALID "$lang" COUPON "$(_fm_html_escape "$coupon_in")" PRICE "$price")"
        fi
    fi

    local balance days bw devices
    balance=$(_fm_bot_wallet_get "$chat_id")
    days=$(_fm_bot_get_plan "$days_key" "$node")
    bw=$(_fm_bot_get_plan "$bw_key" "$node")
    devices=$(_fm_bot_get_plan "$devices_key" "$node")

    local covers_it; covers_it=$(awk -v b="$balance" -v p="$final_price" 'BEGIN{print (b>=p)?1:0}')
    if [[ "$covers_it" == "1" ]]; then
        # fresh=1: كل شراء مدفوع يفتح حسابًا جديدًا على نفس الجهاز
        _fm_bot_provision_hwid_account_dispatch "$hwid" "$((days*24))" "$bw" "$devices" "tg:${chat_id}" "web" 1
        local rc=$?
        local acct="${_FM_BOT_LAST_ACCOUNT:-$hwid}"
        if [[ $rc -eq 1 ]]; then
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg SUBSCRIBE_DEVICE_TAKEN "$lang")"
            return 1
        elif [[ $rc -eq 2 ]]; then
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg PROVISION_FAILED "$lang")"
            return 1
        fi
        _fm_bot_wallet_add "$chat_id" "-${final_price}" >/dev/null
        [[ -n "$coupon_applied" ]] && _fm_bot_coupon_increment_usage "$coupon_applied"
        local bw_msg; if [[ "$lang" == "en" ]]; then bw_msg="Unlimited"; [[ "$bw" != "0" ]] && bw_msg="${bw} GB"; else bw_msg="غير محدود"; [[ "$bw" != "0" ]] && bw_msg="${bw} جيجابايت"; fi
        local success_key="SUBSCRIBE_SUCCESS_WALLET_NEW"; [[ $rc -eq 3 ]] && success_key="SUBSCRIBE_SUCCESS_WALLET_RENEWED"
        # The link is keyed by the account, not by whatever the customer
        # typed — for a minted account name those are different strings.
        local usage_link; usage_link=$(_fm_bot_bandwidth_link_dispatch "$acct" 2>/dev/null)
        # The account only differs from the raw device id when it was
        # actually minted (NPV Tunnel/NPVS) — a plain HTTP Custom/Injector
        # id is used as-is, so showing it twice under two different labels
        # would just repeat the same string back at the customer.
        local id_line=""; [[ "$acct" != "$hwid" ]] && id_line="🪪 ID: <code>${acct}</code>%0A"
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt "$success_key" "$lang" ID_LINE "$id_line" HWID "$hwid" DAYS "$days" DEVICES "$devices" BW "$bw_msg" PRICE "$final_price" BALANCE "$(_fm_bot_wallet_get "$chat_id")" EXPIRE "$_FM_BOT_LAST_EXPIRE" USAGE_LINK "$usage_link")"
        # A wallet purchase never passes through the admin's hands, so
        # without this the admin would have no record of the account at
        # all — the same card the approval reply shows.
        # Same rule as the approval path: the customer's own message has
        # already gone out above, so the card's node round trip can only
        # ever delay the admin's copy, never the customer's.
        send_telegram_msg "$(_fm_bot_msg_fmt SUBSCRIBE_ADMIN_WALLET ar CHAT_ID "$chat_id" HWID "$hwid" PRICE "$final_price")"
        send_telegram_msg "$(_fm_bot_admin_account_card "$acct" "$chat_id")"
        _fm_bot_referral_on_paid_conversion "$chat_id"
        _FM_BOT_LAST_HWID="$hwid"
        return 0
    fi

    local payment_info; payment_info=$(_fm_bot_get_plan PAYMENT_INFO "$node")
    # The wallet did not cover it, so this is a manual payment — and a
    # manual payment with no receipt in the admin's hands is just a free
    # subscription request. The button flow collects the receipt before
    # ever getting here; typing "/subscribe <device id>" skipped that
    # entirely and created a pending order out of nothing.
    if ! _fm_bot_receipt_has "$chat_id"; then
        send_telegram_msg_to "$chat_id" \
            "$(_fm_bot_msg_fmt SUBSCRIBE_RECEIPT_REQUIRED "$lang" PRICE "$final_price" PAYMENT_INFO "$payment_info")"
        if [[ -n "$chosen_app" && -n "$chosen_type" ]]; then
            # Inside the button flow the app/file-type are known, so the
            # customer is put straight back on the receipt step and their
            # next photo is accepted.
            _fm_bot_goto "$chat_id" "subscribe${tier}_receipt:${chosen_app}:${chosen_type}"
        else
            _fm_bot_send_main_menu "$chat_id"
        fi
        return 1
    fi
    local app_type_combo=""
    [[ -n "$chosen_app" && -n "$chosen_type" ]] && app_type_combo="${chosen_app}|${chosen_type}"
    local order_id; order_id=$(_fm_bot_order_create "$chat_id" "$hwid" "$final_price" "$coupon_applied" "$app_type_combo" "$tier")
    # One receipt buys one order — otherwise a single photo would let a
    # customer raise as many pending orders as they liked.
    _fm_bot_receipt_clear "$chat_id"
    local coupon_line=""; [[ -n "$coupon_applied" ]] && { if [[ "$lang" == "en" ]]; then coupon_line="%0ACoupon: ${coupon_applied}"; else coupon_line="%0Aالكوبون: ${coupon_applied}"; fi; }
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt SUBSCRIBE_ORDER_CREATED "$lang" ORDER_ID "$order_id" PRICE "$final_price" COUPON_LINE "$coupon_line" PAYMENT_INFO "$payment_info")"
    local coupon_line_admin=""; [[ -n "$coupon_applied" ]] && coupon_line_admin="%0Aالكوبون: ${coupon_applied}"
    send_telegram_msg_kb "$(_fm_bot_msg_fmt SUBSCRIBE_ADMIN_ORDER_PENDING ar ORDER_ID "$order_id" CHAT_ID "$chat_id" HWID "$hwid" PRICE "$final_price" COUPON_LINE "$coupon_line_admin")" \
        "$(_fm_admin_order_inline_json "$order_id")"
    return 2
}

# Entry point for the "Change HWID" button: bail out early (before
# touching the pending-state machine or asking anything) if this
# customer has no account to move, or has already spent every change
# they're allowed. If they own more than one device, ask which one first
# (see the "changehwid_pick" pending case); otherwise remember the single
# account about to be replaced and kick off the same
# region/device/app/type/HWID selection used by trial/subscribe.
_fm_bot_cmd_changehwid_start() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local owned; owned=$(_fm_bot_accounts_for_owner_dispatch "tg:${chat_id}")
    if [[ -z "$owned" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg CHANGE_HWID_NO_ACCOUNT "$lang")"
        return
    fi
    local remaining; remaining=$(_fm_bot_hwidchange_remaining "$chat_id")
    if [[ "$remaining" -le 0 ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt CHANGE_HWID_LIMIT_REACHED "$lang" MAX "$(_fm_bot_hwidchange_max_for "$chat_id")")"
        return
    fi
    if [[ "$(wc -l <<< "$owned")" -gt 1 ]]; then
        local hwids; hwids=$(awk -F: '{print $1}' <<< "$owned")
        _fm_bot_goto "$chat_id" "changehwid_pick"
        _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg CHANGE_HWID_PICK_HWID "$lang")" "$hwids"
        return
    fi
    local old_hwid; old_hwid=$(awk -F: '{print $1}' <<< "$owned")
    _fm_bot_hwidchange_state_set "$chat_id" "$old_hwid"
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt CHANGE_HWID_START "$lang" REMAINING "$remaining")"
    _fm_bot_start_flow "$chat_id" "changehwid"
}

# Entry point for "Renew Subscription": find every account this customer
# owns, skip straight to the duration picker if there's exactly one,
# otherwise ask which device to renew first (same "more than one owned
# device" pattern as Change HWID above). No app/file-type re-selection —
# see _fm_bot_cmd_subscribe, which already treats a same-owner/same-hwid
# purchase as a renewal rather than a fresh one.
_fm_bot_cmd_renew_start() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local owned; owned=$(_fm_bot_accounts_for_owner_dispatch "tg:${chat_id}")
    if [[ -z "$owned" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RENEW_NO_ACCOUNT "$lang")"
        return
    fi
    if [[ "$(wc -l <<< "$owned")" -gt 1 ]]; then
        local hwids; hwids=$(awk -F: '{print $1}' <<< "$owned")
        _fm_bot_goto "$chat_id" "renew_hwid_pick"
        _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg RENEW_PICK_HWID "$lang")" "$hwids"
        return
    fi
    local hwid; hwid=$(awk -F: '{print $1}' <<< "$owned")
    _fm_bot_goto "$chat_id" "renew_duration:${hwid}"
    _fm_bot_send_duration_list "$chat_id"
}

# Final step: a new HWID has been typed in. Delete the old account
# outright and recreate it under the new device id with exactly the same
# remaining expiry/devices/bandwidth/type it had — this is a device
# swap, not a fresh purchase, so nothing about the plan itself changes.
_fm_bot_cmd_changehwid_finish() {
    local chat_id="$1" hwid_in="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local old_hwid; old_hwid=$(_fm_bot_hwidchange_state_get "$chat_id")
    if [[ -z "$old_hwid" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg PROVISION_FAILED "$lang")"
        return 1
    fi
    local hwid; hwid=$(_fm_validate_hwid "$hwid_in")
    if [[ -z "$hwid" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg INVALID_HWID "$lang")"
        return 1
    fi
    if [[ "$hwid" == "$old_hwid" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt CHANGE_HWID_SAME_DEVICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
        return 1
    fi
    # A device id longer than a username is not itself an account name,
    # so asking the system whether such a user exists would always say no
    # and let a customer claim a phone that already belongs to somebody
    # else. Resolve it through the mapping first (read-only — checking
    # must never mint a name). Checked against both this box's own local
    # mapping (today's exact behaviour) and the device->node cache (a
    # device already claimed on a remote node, recorded there the first
    # time it was provisioned).
    local claim; claim=$(_fm_bot_account_lookup_device "$hwid" 2>/dev/null) || claim=""
    if [[ -n "$claim" ]] && id "$claim" &>/dev/null; then
        local existing_owner=""
        if [[ -f "$DB_FILE" ]]; then
            local dbrow; dbrow=$(awk -F: -v h="$claim" '$1==h{print; exit}' "$DB_FILE")
            if [[ -n "$dbrow" ]]; then
                local _u _p _e _l _b _d _t ex_own
                IFS=: read -r _u _p _e _l _b _d _t ex_own <<< "$dbrow"
                existing_owner="$ex_own"
            fi
        fi
        if [[ "$existing_owner" != "tg:${chat_id}" ]]; then
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg SUBSCRIBE_DEVICE_TAKEN "$lang")"
            return 1
        fi
    fi
    local remote_owner; remote_owner=$(_fm_bot_node_device_owner_get "$hwid")
    if [[ -n "$remote_owner" && "$remote_owner" != "tg:${chat_id}" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg SUBSCRIBE_DEVICE_TAKEN "$lang")"
        return 1
    fi

    local old_line; old_line=$(_fm_bot_account_status_dispatch "$old_hwid" 2>/dev/null)
    if [[ -z "$old_line" ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg PROVISION_FAILED "$lang")"
        _fm_bot_hwidchange_state_clear "$chat_id"
        return 1
    fi
    local ou op oexp odev obw odbw oatype ownr
    IFS=: read -r ou op oexp odev obw odbw oatype ownr <<< "$old_line"

    # Read the retired phone's real id BEFORE the rebuild drops its
    # mapping — afterwards there is nothing left to look it up from.
    local old_device_shown; old_device_shown=$(_fm_bot_device_for_account "$old_hwid" 2>/dev/null) || old_device_shown=""
    [[ -n "$old_device_shown" ]] || old_device_shown="$old_hwid"
    if ! _fm_bot_hwid_change_dispatch "$old_hwid" "$hwid" "$old_line"; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg PROVISION_FAILED "$lang")"
        _fm_bot_hwidchange_state_clear "$chat_id"
        return 1
    fi
    local new_used; new_used=$(_fm_bot_hwidchange_used_increment "$chat_id")
    _fm_bot_hwidchange_state_clear "$chat_id"
    # The NEW phone, not necessarily the account name: an NPV Tunnel
    # account keeps its own name (the messages below still quote it, so
    # nothing the customer reads changes) — a short-id account is
    # literally renamed to match, so _FM_BOT_LAST_ACCOUNT already IS the
    # right thing to show either way.
    _FM_BOT_LAST_HWID="$hwid"
    local usage_link; usage_link=$(_fm_bot_bandwidth_link_dispatch "$_FM_BOT_LAST_ACCOUNT" 2>/dev/null)
    local remaining; remaining=$(_fm_bot_hwidchange_remaining "$chat_id")
    # OLD_HWID/HWID are the customer's own device ids — what they typed
    # and recognise. ACCOUNT is the login name, which for an NPV Tunnel
    # account is a synthetic one they never chose. Putting the account
    # name in both device slots (what this used to do) printed the same
    # value twice under "old device"/"new device" and told the customer
    # nothing about what actually changed.
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt CHANGE_HWID_DONE "$lang" OLD_HWID "$old_device_shown" HWID "$hwid" ACCOUNT "$_FM_BOT_LAST_ACCOUNT" EXPIRE "$oexp" USAGE_LINK "$usage_link" REMAINING "$remaining")"
    # The device change mints a NEW account name and a new password, so
    # everything the admin previously wrote down about this customer is
    # stale the moment it completes — which makes this the single point
    # where the full card is worth most.
    send_telegram_msg "$(_fm_bot_msg_fmt CHANGE_HWID_ADMIN ar CHAT_ID "$chat_id" OLD_HWID "$old_hwid" HWID "$hwid")"
    send_telegram_msg "$(_fm_bot_admin_account_card "$_FM_BOT_LAST_ACCOUNT" "$chat_id")"
    return 0
}

_fm_bot_cmd_myaccount() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local owner_tag="tg:${chat_id}" found=0 msg rows=""
    msg=$(_fm_bot_msg MYACCOUNT_HEADER "$lang")
    # Merges local accounts with any this owner has on a remote node (see
    # _fm_bot_accounts_for_owner_dispatch) — with no node ever
    # registered, this is exactly the DB_FILE scan it replaces.
    local u p exp lim bw dbw atype owner
    while IFS=: read -r u p exp lim bw dbw atype owner; do
        [[ -z "$u" ]] && continue
        [[ "$owner" == "$owner_tag" ]] || continue
        found=1
        local bw_msg; if [[ "$lang" == "en" ]]; then bw_msg="Unlimited"; [[ "$bw" != "0" ]] && bw_msg="${bw} GB"; else bw_msg="غير محدود"; [[ "$bw" != "0" ]] && bw_msg="${bw} جيجابايت"; fi
        msg+=$(_fm_bot_msg_fmt MYACCOUNT_ROW "$lang" USERNAME "$u" EXPIRE "$exp" DEVICES "$lim" BW "$bw_msg")
        # Only an account we actually remember delivering a file for
        # can have one rebuilt, so no dead button is ever shown.
        if [[ -n "$(_fm_bot_delivery_get "$u")" ]]; then
            local rs_esc; rs_esc=$(_fm_bot_msg_fmt BTN_RESEND_FILE "$lang" USERNAME "$u")
            rs_esc="${rs_esc//\\/\\\\}"; rs_esc="${rs_esc//\"/\\\"}"
            [[ -n "$rows" ]] && rows+=","
            rows+="[{\"text\":\"${rs_esc}\",\"callback_data\":\"rs:${u}\"}]"
        fi
    done < <(_fm_bot_accounts_for_owner_dispatch "$owner_tag")
    if [[ "$found" -eq 0 ]]; then
        send_telegram_msg_to "$chat_id" "$(_fm_bot_msg MYACCOUNT_EMPTY "$lang")"
    elif [[ -n "$rows" ]]; then
        send_telegram_msg_to_kb "$chat_id" "$msg" "{\"inline_keyboard\":[${rows}]}"
    else
        send_telegram_msg_to "$chat_id" "$msg"
    fi
}

# ── Customer language (Arabic by default, English on request) ──────────
# Every customer-facing string in the bot goes through _fm_bot_t so a
# single per-chat preference (BOT_LANG_DB: chat_id:lang) controls it.
# Admin-side text (server status, sales-bot admin replies) is always
# Arabic outright — the admin is one person, not something to toggle.
_fm_bot_lang_get() {
    local chat_id="$1"
    [[ -f "$BOT_LANG_DB" ]] || { echo "ar"; return; }
    awk -F: -v c="$chat_id" '$1==c{print $2; f=1} END{if(!f) print "ar"}' "$BOT_LANG_DB"
}

_fm_bot_lang_set() {
    local chat_id="$1" lang="$2"
    mkdir -p "$(dirname "$BOT_LANG_DB")" 2>/dev/null
    touch "$BOT_LANG_DB"
    sed -i "/^${chat_id}:/d" "$BOT_LANG_DB" 2>/dev/null
    echo "${chat_id}:${lang}" >> "$BOT_LANG_DB"
}

# Every button caption, in both languages, one place — used both to build
# the keyboards below and to recognize a tap regardless of which language
# it was shown in (so a button pressed a beat before/after a language
# switch, or from a stale cached keyboard, still works).
# Each of these is just _fm_bot_msg for one key — kept as named functions
# since _fm_bot_button_action and the keyboard builders read much more
# clearly calling _fm_bot_btn_trial than _fm_bot_msg BTN_TRIAL everywhere.
_fm_bot_btn_trial()      { _fm_bot_msg BTN_TRIAL "$1"; }
_fm_bot_btn_subscribe()  { _fm_bot_msg BTN_SUBSCRIBE "$1"; }
_fm_bot_btn_balance()    { _fm_bot_msg BTN_BALANCE "$1"; }
_fm_bot_btn_myaccount()  { _fm_bot_msg BTN_MYACCOUNT "$1"; }
_fm_bot_btn_referral()   { _fm_bot_msg BTN_REFERRAL "$1"; }
_fm_bot_btn_support()    { _fm_bot_msg BTN_SUPPORT "$1"; }
_fm_bot_btn_mainmenu()   { _fm_bot_msg BTN_MAINMENU "$1"; }
_fm_bot_btn_back()       { _fm_bot_msg BTN_BACK "$1"; }
_fm_bot_btn_cancel()     { _fm_bot_msg BTN_CANCEL "$1"; }
_fm_bot_btn_hwid_yes()   { _fm_bot_msg BTN_HWID_YES "$1"; }
_fm_bot_btn_hwid_no()    { _fm_bot_msg BTN_HWID_NO "$1"; }
_fm_bot_btn_changehwid() { _fm_bot_msg BTN_CHANGE_HWID "$1"; }
_fm_bot_btn_renew()      { _fm_bot_msg BTN_RENEW "$1"; }
# Shows the OTHER language's name — tapping it switches to that language.
_fm_bot_btn_langtoggle() { _fm_bot_msg BTN_LANGTOGGLE "$1"; }

# Maps an incoming text to a normalized action key by checking it against
# both languages' captions — "" if it isn't a recognized menu button.
_fm_bot_button_action() {
    local text="$1" lg
    for lg in ar en; do
        [[ "$text" == "$(_fm_bot_btn_trial "$lg")" ]] && { echo "trial"; return; }
        [[ "$text" == "$(_fm_bot_btn_subscribe "$lg")" ]] && { echo "subscribe"; return; }
        [[ "$text" == "$(_fm_bot_btn_balance "$lg")" ]] && { echo "balance"; return; }
        [[ "$text" == "$(_fm_bot_btn_myaccount "$lg")" ]] && { echo "myaccount"; return; }
        [[ "$text" == "$(_fm_bot_btn_referral "$lg")" ]] && { echo "referral"; return; }
        [[ "$text" == "$(_fm_bot_btn_support "$lg")" ]] && { echo "support"; return; }
        [[ "$text" == "$(_fm_bot_btn_mainmenu "$lg")" ]] && { echo "mainmenu"; return; }
        [[ "$text" == "$(_fm_bot_btn_back "$lg")" ]] && { echo "back"; return; }
        [[ "$text" == "$(_fm_bot_btn_cancel "$lg")" ]] && { echo "cancel"; return; }
        [[ "$text" == "$(_fm_bot_btn_changehwid "$lg")" ]] && { echo "changehwid"; return; }
        [[ "$text" == "$(_fm_bot_btn_renew "$lg")" ]] && { echo "renew"; return; }
        [[ "$text" == "$(_fm_bot_btn_langtoggle "$lg")" ]] && { echo "langtoggle"; return; }
    done
    echo ""
}

# ── Interactive button UI: no slash commands needed ─────────────────────
# A persistent reply-keyboard (the buttons Telegram shows above the
# customer's own keyboard) replaces having to know/type /trial, /subscribe
# etc. Tapping a button sends its caption back as an ordinary text
# message — there is no separate "callback" mechanism involved, so this
# reuses the exact same getUpdates→text pipeline as every other message.
# Multi-step flows (send your HWID; pick an app; pick a file type) are
# tracked per chat in BOT_PENDING_DB so the NEXT plain-text message from
# that chat is interpreted as the answer to whatever was just asked,
# instead of a fresh command. Legacy typed commands (/trial HWID, etc.)
# keep working unchanged for anyone who prefers them — same handlers.

_fm_bot_pending_set() {
    local chat_id="$1" value="$2"
    mkdir -p "$(dirname "$BOT_PENDING_DB")" 2>/dev/null
    touch "$BOT_PENDING_DB"
    sed -i "/^${chat_id}:/d" "$BOT_PENDING_DB" 2>/dev/null
    echo "${chat_id}:${value}" >> "$BOT_PENDING_DB"
}

_fm_bot_pending_get() {
    local chat_id="$1"
    [[ -f "$BOT_PENDING_DB" ]] || return 0
    local line; line=$(grep "^${chat_id}:" "$BOT_PENDING_DB" 2>/dev/null | tail -1)
    [[ -n "$line" ]] || return 0
    printf '%s' "${line#*:}"
}

_fm_bot_pending_clear() {
    local chat_id="$1"
    [[ -f "$BOT_PENDING_DB" ]] && sed -i "/^${chat_id}:/d" "$BOT_PENDING_DB" 2>/dev/null
    # A cleared pending state always means "this flow is over" (finished,
    # cancelled, redirected), so the remembered path back through it is
    # meaningless too. Dropping it here keeps every existing and future
    # caller correct without each having to remember to do it itself.
    _fm_bot_nav_clear "$chat_id"
    # And the option lists with it: a finished flow's buttons are still
    # sitting on their old messages, and nothing they could resolve to
    # is an answer to anything any more.
    _fm_bot_opts_clear "$chat_id"
    return 0
}

# ── Back navigation ───────────────────────────────────────────────────
# Every step a customer is sent forward to remembers the step they came
# from, as one "chat_id:<pending state>" line appended to BOT_NAV_DB. The
# stack is per chat and strictly last-in-first-out, so "back" is simply
# "pop one entry and re-render it" — which works for any step, including
# ones added later, as long as the forward move went through
# _fm_bot_goto. One line per entry (rather than one packed line per chat)
# keeps this safe whatever characters an app/country/type name contains.
_FM_BOT_NAV_MAX=20

_fm_bot_nav_push() {
    local chat_id="$1" state="$2"
    [[ -n "$state" ]] || return 0
    mkdir -p "$(dirname "$BOT_NAV_DB")" 2>/dev/null
    touch "$BOT_NAV_DB" 2>/dev/null
    printf '%s:%s\n' "$chat_id" "$state" >> "$BOT_NAV_DB"
    # A customer who keeps re-entering flows without finishing them must
    # not be able to grow this file without bound.
    local depth; depth=$(grep -c "^${chat_id}:" "$BOT_NAV_DB" 2>/dev/null || echo 0)
    if [[ "$depth" -gt "${_FM_BOT_NAV_MAX:-20}" ]]; then
        local oldest; oldest=$(grep -n "^${chat_id}:" "$BOT_NAV_DB" 2>/dev/null | head -1)
        [[ -n "$oldest" ]] && sed -i "${oldest%%:*}d" "$BOT_NAV_DB" 2>/dev/null
    fi
    return 0
}

_fm_bot_nav_pop() {
    local chat_id="$1"
    [[ -f "$BOT_NAV_DB" ]] || return 0
    local last; last=$(grep -n "^${chat_id}:" "$BOT_NAV_DB" 2>/dev/null | tail -1)
    [[ -n "$last" ]] || return 0
    local lineno="${last%%:*}" state="${last#*:}"
    state="${state#*:}"
    sed -i "${lineno}d" "$BOT_NAV_DB" 2>/dev/null
    printf '%s' "$state"
}

# Is there a step behind this one the customer could actually land on?
# The raw stack is not the answer: a stack holding nothing but
# single-option steps has nowhere real to go back to.
_fm_bot_nav_has_real() {
    local chat_id="$1" st
    [[ -f "$BOT_NAV_DB" ]] || return 1
    while IFS= read -r st; do
        [[ -n "$st" ]] || continue
        [[ "$(_fm_bot_step_options_count "$st" "$chat_id")" == "1" ]] || return 0
    done <<< "$(sed -n "s/^${chat_id}://p" "$BOT_NAV_DB" 2>/dev/null)"
    return 1
}

_fm_bot_nav_has() {
    local chat_id="$1"
    [[ -f "$BOT_NAV_DB" ]] || return 1
    grep -q "^${chat_id}:" "$BOT_NAV_DB" 2>/dev/null
}

_fm_bot_nav_clear() {
    local chat_id="$1"
    [[ -f "$BOT_NAV_DB" ]] && sed -i "/^${chat_id}:/d" "$BOT_NAV_DB" 2>/dev/null
    return 0
}

# Moves the customer one step forward: remembers where they are right now
# so the back button can bring them straight back to it (with that step's
# own options), then sets the new step. Use this rather than
# _fm_bot_pending_set for every forward transition and back navigation
# then works for it automatically, future steps included.
_fm_bot_goto() {
    local chat_id="$1" next="$2" cur
    cur=$(_fm_bot_pending_get "$chat_id")
    [[ -n "$cur" ]] && _fm_bot_nav_push "$chat_id" "$cur"
    _fm_bot_pending_set "$chat_id" "$next"
}

# Keyboard for a step that expects typed input rather than a choice: just
# the navigation row, so back / main menu stay reachable while the
# customer types instead of leaving the previous step's options on screen.
# Inline, for the same reason as _fm_bot_send_choice: it rides along with
# the prompt itself and leaves the persistent bottom keyboard alone.
_fm_bot_nav_keyboard_json() {
    local lang="${1:-ar}" chat_id="${2:-}"
    _fm_bot_nav_inline_json "$lang" "$chat_id"
}

# The "type your device id" prompt for a flow, re-usable both when the
# flow first reaches it and when back navigation lands on it again.
_fm_bot_send_hwid_prompt() {
    local chat_id="$1" flow="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local kb; kb=$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")
    if [[ "$flow" == "changehwid" ]]; then
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg CHANGE_HWID_ASK_HWID "$lang")" "$kb"
    elif [[ "$flow" == subscribe* ]]; then
        local price_key="MONTHLY_PRICE_SAR"; [[ "$flow" == "subscribe2" ]] && price_key="MONTHLY2_PRICE_SAR"
        local node; node=$(_fm_bot_resolve_node_for_call "" "$chat_id")
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg_fmt SUBSCRIBE_ASK_HWID "$lang" PRICE "$(_fm_bot_get_plan "$price_key" "$node")")" "$kb"
    else
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg TRIAL_ASK_HWID "$lang")" "$kb"
    fi
}

# How many options a step would put on screen. -1 means the step is not a
# list at all (it wants typed input, or it is shown even with one option).
#
# It exists for the back button. A step with exactly one option is
# answered for the customer instead of being shown — which is right on
# the way forward, and wrong on the way back: going back to it just
# answers it again and returns them to the step they were trying to
# leave. From the customer's side the button is simply dead, and only on
# that one screen, which is exactly how it was reported.
_fm_bot_step_options_count() {
    local state="$1" a c1 c2 node
    IFS=: read -r a c1 c2 <<< "$state"
    node=$(_fm_bot_node_selected_get "${2:-}")
    local items=""
    case "$a" in
        trial_region|subscribe1_region|subscribe2_region|changehwid_region)
            items=$(_fm_bot_region_names ar) ;;
        trial_app|subscribe1_app|subscribe2_app|changehwid_app)
            items=$(_fm_bot_appfile_apps_list_for_platform "$c1") ;;
        trial_country|subscribe1_country|subscribe2_country|changehwid_country)
            items=$(_fm_bot_countries_list_for_app "$c1" "$node") ;;
        trial_simtype|subscribe1_simtype|subscribe2_simtype|changehwid_simtype)
            items=$(_fm_bot_simtypes_list_for_country "$c2" "$c1" "$node") ;;
        changehwid_pick|renew_hwid_pick)
            items=$(_fm_bot_accounts_for_owner_dispatch "tg:${2:-}" | awk -F: '{print $1}') ;;
        # The device and duration steps always have two; the file-type
        # step is deliberately shown even with one; everything else is
        # typed input. None of them can vanish under the customer.
        *) printf '%s' "-1"; return 0 ;;
    esac
    printf '%s' "$(grep -c . <<< "$items" 2>/dev/null || echo 0)"
}

# Re-sends the prompt and keyboard for an arbitrary pending state. This is
# what makes back navigation land on the real previous menu with its real
# options, instead of dumping the customer at the main menu.
_fm_bot_render_step() {
    local chat_id="$1" state="$2"
    local s_action s_ctx1 s_ctx2
    IFS=: read -r s_action s_ctx1 s_ctx2 <<< "$state"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    case "$s_action" in
        subscribe_duration|renew_duration)
            _fm_bot_send_duration_list "$chat_id" ;;
        trial_region|subscribe1_region|subscribe2_region|changehwid_region)
            _fm_bot_send_region_list "$chat_id" ;;
        trial_device|subscribe1_device|subscribe2_device|changehwid_device)
            _fm_bot_send_device_list "$chat_id" ;;
        trial_app|subscribe1_app|subscribe2_app|changehwid_app)
            _fm_bot_send_app_list "$chat_id" "$s_ctx1" ;;
        trial_country|subscribe1_country|subscribe2_country|changehwid_country)
            _fm_bot_send_country_list "$chat_id" "$s_ctx1" "$(_fm_bot_node_selected_get "$chat_id")" ;;
        trial_simtype|subscribe1_simtype|subscribe2_simtype|changehwid_simtype)
            _fm_bot_send_simtype_list "$chat_id" "$s_ctx2" "$s_ctx1" "$(_fm_bot_node_selected_get "$chat_id")" ;;
        trial_filetype|subscribe1_filetype|subscribe2_filetype|changehwid_filetype)
            _fm_bot_send_filetype_list "$chat_id" "$s_ctx2" "$s_ctx1" ;;
        changehwid_pick|renew_hwid_pick)
            local owned hwids msg_key="CHANGE_HWID_PICK_HWID"
            [[ "$s_action" == "renew_hwid_pick" ]] && msg_key="RENEW_PICK_HWID"
            owned=$(_fm_bot_accounts_for_owner_dispatch "tg:${chat_id}")
            hwids=$(awk -F: '{print $1}' <<< "$owned")
            _fm_bot_send_choice "$chat_id" "$(_fm_bot_msg "$msg_key" "$lang")" "$hwids" ;;
        support)
            _fm_bot_send_card "$chat_id" "$(_fm_bot_msg SUPPORT_ASK "$lang")" \
                "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")" ;;
        trial_hwidok|subscribe1_hwidok|subscribe2_hwidok|changehwid_hwidok)
            local rs_hw; rs_hw=$(_fm_bot_hwidpend_get "$chat_id") || rs_hw=""
            if [[ -n "$rs_hw" ]]; then
                _fm_bot_send_hwid_confirm "$chat_id" "$(awk '{print $1}' <<< "$rs_hw")"
            else
                _fm_bot_pending_set "$chat_id" "${s_action%_hwidok}_hwid:${s_ctx1}:${s_ctx2}"
                _fm_bot_send_hwid_prompt "$chat_id" "${s_action%_hwidok}"
            fi ;;
        subscribe1_receipt|subscribe2_receipt)
            local price_key="MONTHLY_PRICE_SAR"
            [[ "$s_action" == subscribe2_* ]] && price_key="MONTHLY2_PRICE_SAR"
            local rs_node; rs_node=$(_fm_bot_resolve_node_for_call "" "$chat_id")
            _fm_bot_send_card "$chat_id" \
                "$(_fm_bot_msg_fmt PAYMENT_REQUEST "$lang" PRICE "$(_fm_bot_get_plan "$price_key" "$rs_node")" PAYMENT_INFO "$(_fm_bot_get_plan PAYMENT_INFO "$rs_node")")" \
                "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")" ;;
        *)
            # Any other step (a plain "type your device id", or a future
            # step with no list of its own) still gets its prompt and the
            # navigation row, so the customer is never left stuck.
            _fm_bot_send_hwid_prompt "$chat_id" "${s_action%%_*}" ;;
    esac
}

# One button per row keeps this readable no matter how long an app/file
# name is. Always ends with a "cancel and go back" row, in $2's language.
_fm_bot_keyboard_json_from_list() {
    local items="$1" lang="${2:-ar}" chat_id="${3:-}" label esc rows="" first=1
    while IFS= read -r label; do
        [[ -z "$label" ]] && continue
        [[ $first -eq 0 ]] && rows+=","
        esc="${label//\\/\\\\}"; esc="${esc//\"/\\\"}"
        rows+="[{\"text\":\"${esc}\"}]"
        first=0
    done <<< "$items"
    # A back row appears only when a previous step is actually remembered
    # for this chat, so the first screen of a flow (and the main menu)
    # never offers a back button with nowhere to go. Callers that pass no
    # chat id keep the exact keyboard they always had.
    if [[ -n "$chat_id" ]] && _fm_bot_nav_has_real "$chat_id"; then
        [[ -n "$rows" ]] && rows+=","
        esc="$(_fm_bot_btn_back "$lang")"; esc="${esc//\\/\\\\}"; esc="${esc//\"/\\\"}"
        rows+="[{\"text\":\"${esc}\"}]"
    fi
    [[ -n "$rows" ]] && rows+=","
    rows+="[{\"text\":\"$(_fm_bot_btn_mainmenu "$lang")\"}]"
    printf '{"keyboard":[%s],"resize_keyboard":true}' "$rows"
}

_fm_bot_main_keyboard_json() {
    local lang="${1:-ar}"
    printf '{"keyboard":[["%s","%s"],["%s","%s"],["%s","%s"],["%s","%s"],["%s"]],"resize_keyboard":true,"is_persistent":true}' \
        "$(_fm_bot_btn_trial "$lang")" "$(_fm_bot_btn_subscribe "$lang")" \
        "$(_fm_bot_btn_balance "$lang")" "$(_fm_bot_btn_myaccount "$lang")" \
        "$(_fm_bot_btn_referral "$lang")" "$(_fm_bot_btn_support "$lang")" \
        "$(_fm_bot_btn_langtoggle "$lang")" "$(_fm_bot_btn_changehwid "$lang")" \
        "$(_fm_bot_btn_renew "$lang")"
}

# The same nine buttons as _fm_bot_main_keyboard_json, in the same order,
# as a plain list — this is what the inline copy and the tap resolver are
# both built from.
_fm_bot_main_menu_items() {
    local lang="${1:-ar}"
    printf '%s\n' \
        "$(_fm_bot_btn_trial "$lang")" "$(_fm_bot_btn_subscribe "$lang")" \
        "$(_fm_bot_btn_balance "$lang")" "$(_fm_bot_btn_myaccount "$lang")" \
        "$(_fm_bot_btn_referral "$lang")" "$(_fm_bot_btn_support "$lang")" \
        "$(_fm_bot_btn_langtoggle "$lang")" "$(_fm_bot_btn_changehwid "$lang")" \
        "$(_fm_bot_btn_renew "$lang")"
}

# Like send_telegram_msg_to, but attaches a reply-keyboard. reply_markup
# is raw JSON (braces, quotes) so it goes through --data-urlencode for
# proper percent-encoding, while the rest of the fields keep this file's
# existing convention (manually %0A-encoded, passed via -d as-is).
send_telegram_msg_to_kb() {
    local target_chat="$1" msg="$2" keyboard_json="$3"
    _fm_bot_card_mark_dirty "$target_chat" 2>/dev/null || true
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" && -n "$target_chat" ]] || return 0
    curl -s -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" \
        -d "chat_id=${target_chat}" \
        -d "text=${msg}" \
        -d "parse_mode=HTML" \
        --data-urlencode "reply_markup=${keyboard_json}" &>/dev/null &
}

# ── Inline (attached) buttons ─────────────────────────────────────────
# Telegram allows exactly one reply_markup per message, and the two kinds
# are not interchangeable: a reply keyboard replaces the customer's
# on-screen keyboard for the whole chat, while an inline keyboard sits
# attached under one specific message. Both were wanted at once, so a
# choice step sends the message carrying the reply keyboard and then
# immediately edits inline buttons onto that same message. If the edit
# fails for any reason — no jq, network blip, Telegram error — the
# message is already delivered with a fully working reply keyboard, so
# this layer can only ever add, never break an existing flow.
BOT_OPTS_DB="${BOT_OPTS_DB:-/etc/firewallfalcon/bot_opts.db}"

# An inline button's callback_data is capped at 64 *bytes*, which an
# Arabic caption exhausts in about twenty characters. So the button
# carries only its position ("o:3") and the captions shown next to it are
# remembered here — one line per option, replaced on every new choice —
# letting a tap be resolved back to the exact text the customer saw.
_fm_bot_opts_save() {
    local chat_id="$1" state="$2" items="$3" db="${BOT_OPTS_DB:-/etc/firewallfalcon/bot_opts.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    # A new id per list, so a button always resolves against the list it
    # was drawn with and never against whatever list came later.
    local lid; lid=$(awk -F'\t' -v c="$chat_id" '$1==c && $2+0>m{m=$2+0} END{print m+1}' "$db" 2>/dev/null)
    [[ "$lid" =~ ^[0-9]+$ ]] || lid=1
    local n=0 label
    while IFS= read -r label; do
        [[ -z "$label" ]] && continue
        n=$((n+1))
        printf '%s\t%s\t%s\t%s\t%s\n' "$chat_id" "$lid" "$state" "$n" "$label" >> "$db"
    done <<< "$items"
    # An empty list still gets its row, so a navigation-only step has an
    # id of its own to bind its back button to.
    (( n == 0 )) && printf '%s\t%s\t%s\t0\t\n' "$chat_id" "$lid" "$state" >> "$db"
    # Keep only the newest few lists per chat; the older ones can no
    # longer be valid and would grow this file without bound.
    # Deep enough for the longest flow there is (region, device, app,
    # country, SIM type, file type, device id, confirm) with room to
    # spare, so no step of a journey in progress is ever pruned out from
    # under the customer and reported as "no longer valid".
    local keep=$(( lid - ${_FM_BOT_OPTS_KEEP:-16} ))
    if (( keep > 0 )); then
        local tmp; tmp=$(mktemp)
        awk -F'\t' -v c="$chat_id" -v k="$keep" '!($1==c && $2+0<=k)' "$db" > "$tmp" 2>/dev/null
        mv -f "$tmp" "$db" 2>/dev/null
    fi
    printf '%s' "$lid"
}

_fm_bot_opts_get() {
    local chat_id="$1" lid="$2" idx="$3" db="${BOT_OPTS_DB:-/etc/firewallfalcon/bot_opts.db}"
    [[ -f "$db" ]] || return 1
    # Field 5 onwards, rejoined: a caption may itself contain tabs or
    # anything else the admin typed, so the remainder of the line is the
    # value rather than one field of it.
    local v; v=$(awk -F'\t' -v c="$chat_id" -v l="$lid" -v i="$idx" \
        '$1==c && $2==l && $4==i {out=$5; for(j=6;j<=NF;j++) out=out "\t" $j; print out; f=1; exit} END{exit !f}' \
        "$db" 2>/dev/null) || return 1
    printf '%s' "$v"
}

# Which step a list was drawn for. "@menu" marks the main menu, whose
# buttons are global commands and stay valid at any point in any flow.
_fm_bot_opts_state() {
    local chat_id="$1" lid="$2" db="${BOT_OPTS_DB:-/etc/firewallfalcon/bot_opts.db}"
    [[ -f "$db" ]] || return 1
    local v; v=$(awk -F'\t' -v c="$chat_id" -v l="$lid" '$1==c && $2==l {print $3; f=1; exit} END{exit !f}' "$db" 2>/dev/null) || return 1
    printf '%s' "$v"
}

_fm_bot_opts_clear() {
    local chat_id="$1" db="${BOT_OPTS_DB:-/etc/firewallfalcon/bot_opts.db}"
    [[ -f "$db" ]] || return 0
    local tmp; tmp=$(mktemp)
    awk -F'\t' -v c="$chat_id" '$1!=c' "$db" > "$tmp" 2>/dev/null
    mv -f "$tmp" "$db" 2>/dev/null
    return 0
}

# Is a tapped button still the customer's current screen? Inline buttons
# live on their message forever, so an abandoned step's options sit there
# waiting to be pressed — and pressing one used to feed its caption into
# whatever step the customer had since moved on to. That is how a file
# type ended up being read as a device id. A list is honoured only while
# the step that drew it is still the pending one; the main menu's own
# list is exempt, since those buttons are commands rather than answers to
# a question.
_fm_bot_opts_is_current() {
    local chat_id="$1" lid="$2" state
    state=$(_fm_bot_opts_state "$chat_id" "$lid") || return 1
    [[ "$state" == "@menu" ]] && return 0
    [[ "$state" == "$(_fm_bot_pending_get "$chat_id")" ]]
}

# Two buttons per row: wide enough for a country or app name, compact
# enough that a long list stays on one screen. The navigation row mirrors
# _fm_bot_keyboard_json_from_list exactly — back only when a previous
# step is actually remembered — so both keyboards on the same message
# always offer the identical set of choices.
_fm_bot_inline_keyboard_json() {
    local items="$1" lang="${2:-ar}" chat_id="${3:-}" no_nav="${4:-}" lid="${5:-0}" fixed_row="${6:-}" label esc rows="" row="" n=0 incol=0
    # Telegram gives every button in a row an equal share of the width and
    # silently cuts off whatever does not fit — a file type named
    # "Zain Social-DE (زين-المانيا)" came out as "...ain Social-DE". So the
    # longest caption decides the layout: two per row while they are all
    # short, one per row as soon as any of them isn't, which is never
    # truncated no matter how long it is.
    #
    # That guess is only needed for captions the admin typed and this
    # code has never seen. A caller whose captions are its own and are
    # known to fit passes the layout in instead — the main menu does,
    # because measuring it made nine buttons into nine full-width rows
    # that filled the whole screen, when the same nine sit two-up in the
    # bottom bar with room to spare.
    local per_row=2 longest=0
    local LC_ALL=C.utf8 LANG=C.utf8   # force codepoint-based ${#}, not byte-based
    while IFS= read -r label; do
        [[ -z "$label" ]] && continue
        (( ${#label} > longest )) && longest=${#label}
    done <<< "$items"
    (( longest > ${_FM_BOT_BTN_WIDE:-16} )) && per_row=1
    [[ "$fixed_row" =~ ^[1-9]$ ]] && per_row="$fixed_row"
    while IFS= read -r label; do
        [[ -z "$label" ]] && continue
        n=$((n+1))
        esc="${label//\\/\\\\}"; esc="${esc//\"/\\\"}"
        [[ $incol -gt 0 ]] && row+=","
        row+="{\"text\":\"${esc}\",\"callback_data\":\"o:${lid}:${n}\"}"
        incol=$((incol+1))
        if [[ $incol -ge $per_row ]]; then
            [[ -n "$rows" ]] && rows+=","
            rows+="[${row}]"; row=""; incol=0
        fi
    done <<< "$items"
    if [[ -n "$row" ]]; then
        [[ -n "$rows" ]] && rows+=","
        rows+="[${row}]"
    fi
    # The main menu itself passes no_nav: it is already the destination
    # both navigation buttons lead to.
    if [[ "$no_nav" != "1" ]]; then
        local navrow=""
        if [[ -n "$chat_id" ]] && _fm_bot_nav_has_real "$chat_id"; then
            esc="$(_fm_bot_btn_back "$lang")"; esc="${esc//\\/\\\\}"; esc="${esc//\"/\\\"}"
            navrow="{\"text\":\"${esc}\",\"callback_data\":\"nav:b:${lid}\"},"
        fi
        esc="$(_fm_bot_btn_mainmenu "$lang")"; esc="${esc//\\/\\\\}"; esc="${esc//\"/\\\"}"
        navrow+="{\"text\":\"${esc}\",\"callback_data\":\"nav:h\"}"
        [[ -n "$rows" ]] && rows+=","
        rows+="[${navrow}]"
        # Cancel gets a row to itself rather than a third seat beside the
        # other two: Telegram splits a row's width evenly and silently
        # crops what does not fit, and "main menu" is long enough that a
        # three-up row would clip all three captions.
        esc="$(_fm_bot_btn_cancel "$lang")"; esc="${esc//\\/\\\\}"; esc="${esc//\"/\\\"}"
        rows+=",[{\"text\":\"${esc}\",\"callback_data\":\"nav:c\"}]"
    fi
    printf '{"inline_keyboard":[%s]}' "$rows"
}

# Which language's bottom keyboard each chat has already been given. The
# bottom keyboard is a chat-level, persistent UI element rather than part
# of a message, so re-sending it on every message would waste the one
# reply_markup slot each message has for nothing. Recording it instead
# lets the main menu spend that slot on the inline copy.
BOT_KB_DB="${BOT_KB_DB:-/etc/firewallfalcon/bot_kb.db}"

_fm_bot_kb_is_current() {
    local chat_id="$1" lang="$2" db="${BOT_KB_DB:-/etc/firewallfalcon/bot_kb.db}"
    [[ -f "$db" ]] || return 1
    grep -qx "${chat_id}:${lang}" "$db" 2>/dev/null
}

_fm_bot_kb_mark() {
    local chat_id="$1" lang="$2" db="${BOT_KB_DB:-/etc/firewallfalcon/bot_kb.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    printf '%s:%s\n' "$chat_id" "$lang" >> "$db"
    return 0
}

# ── One card per customer ─────────────────────────────────────────────
# Sending a fresh message for every step left the chat as a ladder of
# dead screens, each still carrying its own buttons. Instead one message
# per customer is treated as "the screen" and edited in place as they
# move through a flow: the chat holds a single card that changes, no
# stacking, and no notification sound on every step since an edit is
# silent.
#
# Two things push that card away from the bottom — a file or guide image
# the bot sends, and anything the customer types. Both mark the card
# dirty, and the next render deletes it and sends a new one so the screen
# a customer is meant to be looking at is always the last thing in the
# chat. Telegram refuses to edit or delete a message older than about 48
# hours, so every failure path here simply falls back to sending a fresh
# card.
BOT_CARD_DB="${BOT_CARD_DB:-/etc/firewallfalcon/bot_card.db}"

_fm_bot_card_get() {
    local chat_id="$1" db="${BOT_CARD_DB:-/etc/firewallfalcon/bot_card.db}"
    [[ -f "$db" ]] || return 1
    local row; row=$(awk -F: -v c="$chat_id" '$1==c{print $2":"$3; f=1} END{exit !f}' "$db" 2>/dev/null) || return 1
    printf '%s' "$row"
}

_fm_bot_card_set() {
    local chat_id="$1" msg_id="$2" dirty="${3:-0}" db="${BOT_CARD_DB:-/etc/firewallfalcon/bot_card.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    [[ -n "$msg_id" ]] && printf '%s:%s:%s\n' "$chat_id" "$msg_id" "$dirty" >> "$db"
    return 0
}

_fm_bot_card_clear() {
    local chat_id="$1" db="${BOT_CARD_DB:-/etc/firewallfalcon/bot_card.db}"
    [[ -f "$db" ]] && sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    return 0
}

# "Something has been posted below the card" — so the next render must
# move it rather than edit it where it sits.
_fm_bot_card_mark_dirty() {
    local chat_id="$1" row mid
    row=$(_fm_bot_card_get "$chat_id") || return 0
    mid="${row%%:*}"
    [[ -n "$mid" ]] && _fm_bot_card_set "$chat_id" "$mid" 1
    return 0
}

# Which message a tap came from, and what to do about it.
#
# Inline buttons never go away: every card the customer has scrolled past
# still has live buttons on it. Tap one of those and the handler runs
# correctly — but the card it redraws is the *current* one, which may be
# a hundred messages further down. Nothing changes under their finger, so
# the button looks broken. It is the single reason "the main menu button
# does nothing" was true even though the main menu was being drawn every
# time.
#
# Tapping the live card is the ordinary case and keeps editing in place.
# Tapping an older one means the customer has scrolled back to it: that
# message and the card they left behind are both removed, and the next
# render starts a fresh card at the bottom of the chat, where they are.
_fm_bot_card_focus() {
    local chat_id="$1" msg_id="$2"
    [[ "$msg_id" =~ ^[0-9]+$ ]] || return 0
    local row cur=""
    row=$(_fm_bot_card_get "$chat_id") && cur="${row%%:*}"
    [[ "$cur" == "$msg_id" ]] && return 0
    [[ -n "$cur" ]] && _fm_bot_card_delete "$chat_id" "$cur"
    _fm_bot_card_delete "$chat_id" "$msg_id"
    _fm_bot_card_clear "$chat_id"
    return 0
}

_fm_bot_card_delete() {
    local chat_id="$1" msg_id="$2"
    [[ -n "$msg_id" ]] || return 0
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" ]] || return 0
    curl -s --max-time 8 --connect-timeout 5 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/deleteMessage" \
        -d "chat_id=${chat_id}" -d "message_id=${msg_id}" &>/dev/null &
    return 0
}

# Renders the customer's screen. Edits the existing card when it is still
# the last thing they can see, otherwise replaces it.
_fm_bot_send_card() {
    local chat_id="$1" text="$2" inline_json="$3"
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" && -n "$chat_id" ]] || return 0
    # A one-off notice (an invalid choice, a stale tap) rides on the card
    # itself rather than as another message underneath it.
    [[ -n "${_FM_BOT_CARD_NOTICE:-}" ]] && text="${_FM_BOT_CARD_NOTICE}%0A%0A${text}"

    local row="" mid="" dirty=0
    if row=$(_fm_bot_card_get "$chat_id"); then
        mid="${row%%:*}"; dirty="${row##*:}"
    fi

    if [[ -n "$mid" && "$dirty" != "1" ]] && command -v jq >/dev/null 2>&1; then
        local eresp ok
        eresp=$(curl -s --max-time 10 --connect-timeout 5 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/editMessageText" \
            -d "chat_id=${chat_id}" \
            -d "message_id=${mid}" \
            -d "text=${text}" \
            -d "parse_mode=HTML" \
            --data-urlencode "reply_markup=${inline_json}" 2>/dev/null)
        ok=$(printf '%s' "$eresp" | jq -r '.ok // false' 2>/dev/null)
        if [[ "$ok" == "true" ]]; then
            _fm_bot_card_set "$chat_id" "$mid" 0
            return 0
        fi
        # "message is not modified" means the screen is already exactly
        # this, which is a success as far as the customer is concerned.
        if printf '%s' "$eresp" | grep -q "message is not modified"; then
            _fm_bot_card_set "$chat_id" "$mid" 0
            return 0
        fi
    fi

    # Replace: the old card is either stale, unreachable, or gone.
    [[ -n "$mid" ]] && _fm_bot_card_delete "$chat_id" "$mid"
    local resp new_id=""
    resp=$(curl -s --max-time 10 --connect-timeout 5 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" \
        -d "chat_id=${chat_id}" \
        -d "text=${text}" \
        -d "parse_mode=HTML" \
        --data-urlencode "reply_markup=${inline_json}" 2>/dev/null)
    if command -v jq >/dev/null 2>&1; then
        new_id=$(printf '%s' "$resp" | jq -r '.result.message_id // empty' 2>/dev/null)
    fi
    if [[ "$new_id" =~ ^[0-9]+$ ]]; then
        _fm_bot_card_set "$chat_id" "$new_id" 0
    else
        # Without an id there is nothing to edit later; the next render
        # just sends again rather than editing a message we can't name.
        _fm_bot_card_clear "$chat_id"
    fi
    return 0
}

# Re-draws the customer's current screen with a one-line notice on top.
# Used wherever a choice was rejected: the question and its buttons come
# back with the reason attached, instead of an error message piling up
# underneath a card the customer has to scroll back to.
_fm_bot_card_notice() {
    local chat_id="$1" notice="$2"
    _FM_BOT_CARD_NOTICE="$notice"
    local cur; cur=$(_fm_bot_pending_get "$chat_id")
    if [[ -n "$cur" ]]; then
        _fm_bot_render_step "$chat_id" "$cur"
    else
        _fm_bot_send_main_menu "$chat_id"
    fi
    _FM_BOT_CARD_NOTICE=""
}

# The single entry point every "pick one of these" step goes through.
# The keyboard and the tap-resolution table are built from the one
# ordered list passed in, so a tapped inline button can never be matched
# against a different order than the one that was displayed.
#
# The inline keyboard is the message's own reply_markup, set at send time
# — never edited on afterwards. A step's buttons therefore appear with
# the message itself, with no second API call that could fail and leave
# the message bare. The bottom keyboard is left untouched here: it stays
# the persistent main menu (see _fm_bot_main_keyboard_json's
# is_persistent), so both are on screen at once during every flow — the
# step's own options attached under the message, the main actions always
# reachable underneath.
_fm_bot_send_choice() {
    local chat_id="$1" prompt="$2" items="$3" no_skip="${4:-}"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    # A question with exactly one possible answer is not a question. It
    # was still being drawn as a screen the customer had to look at and
    # tap through — one country, one SIM type — so it is answered for
    # them instead, by feeding that single option straight back into the
    # same handler a tap would have reached. Several such steps in a row
    # collapse naturally, one recursion per step, and the depth guard
    # below means a step that somehow led back to itself stops rather
    # than spinning.
    # no_skip: the file type is the product itself, not routing — the
    # customer is meant to see which file they are buying and confirm it,
    # so that one screen is drawn even when there is nothing to choose
    # between.
    local count; count=$(grep -c . <<< "$items" 2>/dev/null || echo 0)
    if [[ "$no_skip" != "1" && "$count" == "1" && "${_FM_BOT_SKIP_DEPTH:-0}" -lt 12 ]]; then
        local only; only=$(grep -m1 . <<< "$items")
        if [[ -n "$only" ]]; then
            _FM_BOT_SKIP_DEPTH=$(( ${_FM_BOT_SKIP_DEPTH:-0} + 1 ))
            _fm_bot_customer_handle_command "$chat_id" "$only" "" ""
            _FM_BOT_SKIP_DEPTH=$(( ${_FM_BOT_SKIP_DEPTH:-1} - 1 ))
            return 0
        fi
    fi
    local lid; lid=$(_fm_bot_opts_save "$chat_id" "$(_fm_bot_pending_get "$chat_id")" "$items")
    _fm_bot_send_card "$chat_id" "$prompt" \
        "$(_fm_bot_inline_keyboard_json "$items" "$lang" "$chat_id" "" "$lid")"
}

# Same thing for a step that expects typed input rather than a choice:
# just the navigation row, attached under the prompt.
_fm_bot_nav_inline_json() {
    local lang="${1:-ar}" chat_id="${2:-}"
    local lid; lid=$(_fm_bot_opts_save "$chat_id" "$(_fm_bot_pending_get "$chat_id")" "")
    _fm_bot_inline_keyboard_json "" "$lang" "$chat_id" "" "$lid"
}

# Turns a callback_data payload back into the button caption it stands
# for, so an inline tap can be handed to the ordinary text handler and
# every flow behaves identically whichever keyboard was used.
# Returns the caption a tapped button stands for. Exit codes matter:
# 0 = use it, 2 = the button belongs to a screen the customer has already
# left, 1 = the payload means nothing at all.
_fm_bot_callback_resolve() {
    local chat_id="$1" data="$2" lang
    lang=$(_fm_bot_lang_get "$chat_id")
    case "$data" in
        nav:h) _fm_bot_btn_mainmenu "$lang"; return 0 ;;
        # Never staleness-checked: "get me out of this" is a valid answer
        # to any screen, including one the customer has already left.
        nav:c) _fm_bot_btn_cancel "$lang"; return 0 ;;
        nav:b:*)
            local blid="${data#nav:b:}"
            [[ "$blid" =~ ^[0-9]+$ ]] || return 1
            _fm_bot_opts_is_current "$chat_id" "$blid" || return 2
            _fm_bot_btn_back "$lang"; return 0 ;;
        o:*:*)
            local rest="${data#o:}" lid idx
            lid="${rest%%:*}"; idx="${rest#*:}"
            [[ "$lid" =~ ^[0-9]+$ && "$idx" =~ ^[0-9]+$ ]] || return 1
            _fm_bot_opts_is_current "$chat_id" "$lid" || return 2
            _fm_bot_opts_get "$chat_id" "$lid" "$idx" ;;
        *) return 1 ;;
    esac
}

# A tap on a screen the customer has moved past: say so plainly and put
# them back on the step they are actually in, rather than silently
# feeding a stale answer into it.
_fm_bot_handle_stale_tap() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg STALE_CHOICE "$lang")"
    local cur; cur=$(_fm_bot_pending_get "$chat_id")
    if [[ -n "$cur" ]]; then
        _fm_bot_render_step "$chat_id" "$cur"
    else
        _fm_bot_send_main_menu "$chat_id"
    fi
}

_fm_bot_send_main_menu() {
    local chat_id="$1"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    # Before any node is picked this is simply the global price, which is
    # the only sensible headline anyway — the per-node price appears from
    # the moment the customer chooses a server.
    local mm_node; mm_node=$(_fm_bot_resolve_node_for_call "" "$chat_id")
    local price; price=$(_fm_bot_get_plan MONTHLY_PRICE_SAR "$mm_node")
    local msg; msg=$(_fm_bot_msg_fmt WELCOME "$lang" PRICE "$price")
    local items; items=$(_fm_bot_main_menu_items "$lang")
    local lid; lid=$(_fm_bot_opts_save "$chat_id" "@menu" "$items")
    # The bottom keyboard is persistent (is_persistent), so it only has to
    # be delivered once per chat and language — Telegram keeps showing it
    # from then on. That frees this message's single reply_markup slot for
    # the inline copy every time after, which is how the main menu ends up
    # with buttons attached under it *and* the bar underneath.
    if _fm_bot_kb_is_current "$chat_id" "$lang"; then
        _fm_bot_send_card "$chat_id" "$msg" \
            "$(_fm_bot_inline_keyboard_json "$items" "$lang" "$chat_id" 1 "$lid" 2)"
    else
        # The very first message a chat ever gets carries the bottom bar,
        # which cannot ride on an edited card — so it is a plain send,
        # and the card starts from the next screen.
        # Forgetting the old card here would leave it on screen with
        # live buttons and nothing tracking it, so it goes first.
        local ob_row ob_mid=""
        ob_row=$(_fm_bot_card_get "$chat_id") && ob_mid="${ob_row%%:*}"
        [[ -n "$ob_mid" ]] && _fm_bot_card_delete "$chat_id" "$ob_mid"
        _fm_bot_card_clear "$chat_id"
        send_telegram_msg_to_kb "$chat_id" "$msg" "$(_fm_bot_main_keyboard_json "$lang")"
        _fm_bot_kb_mark "$chat_id" "$lang"
    fi
}

_fm_bot_send_app_list() {
    local chat_id="$1" platform="${2:-}"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local msg; msg=$(_fm_bot_msg APPLIST_PROMPT "$lang")
    local apps; if [[ -n "$platform" ]]; then apps=$(_fm_bot_appfile_apps_list_for_platform "$platform"); else apps=$(_fm_bot_appfile_apps_list); fi
    _fm_bot_send_choice "$chat_id" "$msg" "$apps"
}

_fm_bot_send_type_list() {
    local chat_id="$1" app="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    local msg; msg=$(_fm_bot_msg_fmt TYPELIST_PROMPT "$lang" APP "$(_fm_html_escape "$app")")
    _fm_bot_send_choice "$chat_id" "$msg" "$(_fm_bot_appfile_types_list "$app")"
}

# Entry point for the trial/subscribe buttons: server region (if any are
# configured) comes first, then the device step, then app/file-type,
# then the HWID — see _fm_bot_start_device_or_hwid for how a step gets
# skipped when there's nothing to ask.
#
# Only a NEW purchase gets asked. Changing the device on an existing
# subscription is not a chance to move servers: the account already
# lives somewhere, its files and its remaining days are there, and the
# rebuild goes through _fm_bot_hwid_change_dispatch, which follows the
# account index — so whatever the customer answered here was thrown
# away and the account was rebuilt on its own node regardless. Asking a
# question whose answer is ignored is worse than not asking: a customer
# on Germany who picked Saudi believed they had moved. Renewal never
# had the step at all (_fm_bot_cmd_renew_start goes straight to the
# duration picker), which is the behaviour being matched here.
_fm_bot_start_flow() {
    local chat_id="$1" flow="$2"
    # Flows that inherit their node instead of asking for it.
    local ask_region=1
    case "$flow" in changehwid) ask_region=0 ;; esac
    # Every purchase decides its own node. Without this, a flow that has
    # no region step (none configured, only one region, or an inherited
    # flow like the one above) would inherit whatever the previous
    # purchase picked and build somewhere the customer never chose.
    _fm_bot_node_selected_clear "$chat_id" 2>/dev/null || true
    if [[ $ask_region -eq 1 ]] && [[ -n "$(_fm_bot_regions_list_enabled)" ]]; then
        _fm_bot_goto "$chat_id" "${flow}_region"
        _fm_bot_send_region_list "$chat_id"
        return
    fi
    _fm_bot_start_device_or_hwid "$chat_id" "$flow"
}

# Reached once the region step is done with (skipped, or an "internal"
# region was picked). Asks for a device next if there's anything to
# filter the app list by; otherwise falls straight back to asking for
# the HWID, exactly like the bot did before any of this existed.
_fm_bot_start_device_or_hwid() {
    local chat_id="$1" flow="$2"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    if [[ -n "$(_fm_bot_appfile_apps_list)" ]]; then
        _fm_bot_goto "$chat_id" "${flow}_device"
        _fm_bot_send_device_list "$chat_id"
        return
    fi
    _fm_bot_goto "$chat_id" "$flow"
    _fm_bot_send_hwid_prompt "$chat_id" "$flow"
}

# Reached once a concrete $ftype is known for the picked app — normally
# derived from the country+SIM-type pick (_fm_bot_country_simtype_key),
# or "" when no countries are configured yet, in which case delivery
# will just report the file as unavailable like any other unmatched
# app+type combo. This is the exact branching that used to live inline
# in the old flat "pick a file type" step; factored out here since it's
# now reached from two places (a country with no SIM types configured
# skips straight here, same as a SIM type actually picked).
_fm_bot_on_apptype_chosen() {
    local chat_id="$1" flow="$2" app="$3" ftype="$4"
    local lang; lang=$(_fm_bot_lang_get "$chat_id")
    # Every flow funnels through here on its way to "send me your device
    # ID" (or to the payment screen). An app can appear in the list with
    # no file behind it at all — its folder still exists because it has
    # guide images, or its only file was deleted, or the admin has not
    # uploaded one for this country/SIM-type yet — and the customer was
    # then walked all the way through paying and pasting an HWID before
    # being told the file does not exist. Stop at the last honest moment
    # instead, and put them back on the app list so they can pick
    # another one without starting over.
    if [[ ! -f "$(_fm_bot_appfile_path "$app" "$ftype")" ]]; then
        local device; device=$(_fm_bot_device_selected_get "$chat_id")
        _fm_bot_card_notice "$chat_id" \
            "$(_fm_bot_msg_fmt APPFILE_NONE_FOR_APP "$lang" APP "$(_fm_html_escape "$app")")"
        _fm_bot_goto "$chat_id" "${flow}_app:${device}"
        _fm_bot_send_app_list "$chat_id" "$device"
        return
    fi
    if [[ "$flow" == "changehwid" ]]; then
        _fm_bot_goto "$chat_id" "${flow}_hwid:${app}:${ftype}"
        _fm_bot_send_hwid_guide "$chat_id" "$app"
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg CHANGE_HWID_ASK_HWID "$lang")" \
            "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")"
    elif [[ "$flow" == subscribe* ]]; then
        local price_key="MONTHLY_PRICE_SAR"; [[ "$flow" == "subscribe2" ]] && price_key="MONTHLY2_PRICE_SAR"
        local node; node=$(_fm_bot_resolve_node_for_call "" "$chat_id")
        local price; price=$(_fm_bot_get_plan "$price_key" "$node")
        local balance; balance=$(_fm_bot_wallet_get "$chat_id")
        local covers_it; covers_it=$(awk -v b="$balance" -v p="$price" 'BEGIN{print (b>=p)?1:0}')
        if [[ "$covers_it" != "1" ]]; then
            # Wallet doesn't cover it, so money has to move first: show
            # the payment details and collect a receipt before asking
            # for the device ID. The gate deliberately uses the full
            # price — any coupon is only typed in with the HWID, one
            # step later, so it can't be known here.
            local payment_info; payment_info=$(_fm_bot_get_plan PAYMENT_INFO "$node")
            _fm_bot_goto "$chat_id" "${flow}_receipt:${app}:${ftype}"
            _fm_bot_send_card "$chat_id" "$(_fm_bot_msg_fmt PAYMENT_REQUEST "$lang" PRICE "$price" PAYMENT_INFO "$payment_info")" \
                "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")"
            return
        fi
        _fm_bot_goto "$chat_id" "${flow}_hwid:${app}:${ftype}"
        _fm_bot_send_hwid_guide "$chat_id" "$app"
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg_fmt SUBSCRIBE_ASK_HWID_COVERED "$lang" PRICE "$price" BALANCE "$balance")" \
            "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")"
    else
        _fm_bot_goto "$chat_id" "${flow}_hwid:${app}:${ftype}"
        _fm_bot_send_hwid_guide "$chat_id" "$app"
        _fm_bot_send_card "$chat_id" "$(_fm_bot_msg TRIAL_ASK_HWID "$lang")" \
            "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")"
    fi
}

_fm_bot_customer_handle_command() {
    # Telegram has no "list my users" call, so the only way an
    # announcement can ever reach anyone is if the bot writes down who
    # talks to it. Cheapest possible: one grep against a flat file.
    _fm_bot_known_chat_add "$1" 2>/dev/null || true
    # $3/$4 are set only by the poll loop, and only matter to the one step
    # that asks for a payment receipt: msg_id is what gets forwarded to the
    # admin, attach_kind ("photo"/"document"/"") says whether this message
    # carried an attachment at all.
    local chat_id="$1" text="$2" msg_id="${3:-}" attach_kind="${4:-}"
    local cmd="${text%% *}" rest="${text#* }"
    [[ "$rest" == "$text" ]] && rest=""
    local lang; lang=$(_fm_bot_lang_get "$chat_id")

    if _fm_bot_is_banned "$chat_id"; then
        local appeal_msg=""
        if [[ "$cmd" == "/appeal" ]]; then
            appeal_msg="$rest"
        elif [[ "${text:0:1}" != "/" ]]; then
            # No slash commands needed here either — anything a banned
            # user types is their appeal.
            appeal_msg="$text"
        fi
        if [[ -n "$appeal_msg" ]]; then
            send_telegram_msg "$(_fm_bot_msg_fmt BAN_APPEAL_ADMIN ar CHAT_ID "$chat_id" TEXT "$(_fm_html_escape "$appeal_msg")")"
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg MESSAGE_SENT_TO_ADMIN "$lang")"
        else
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg BAN_BLOCKED "$lang")"
        fi
        return
    fi

    # A photo/document with no text is only meaningful while the bot is
    # actually waiting for a payment receipt. Anywhere else it's a stray
    # attachment: stay quiet rather than answering it with the main menu.
    if [[ -z "$text" && -n "$attach_kind" ]]; then
        case "$(_fm_bot_pending_get "$chat_id")" in
            subscribe1_receipt*|subscribe2_receipt*) : ;;
            *) return ;;
        esac
    fi

    # "/start ref_<chat_id>" is how a referral link hands off — Telegram
    # passes everything after /start verbatim as the rest of the text.
    if [[ "$cmd" == "/start" && "$rest" =~ ^ref_(-?[0-9]+)$ ]]; then
        _fm_bot_referral_register "$chat_id" "${BASH_REMATCH[1]}"
    fi

    local action; action=$(_fm_bot_button_action "$text")
    case "$action" in
        mainmenu)
            _fm_bot_pending_clear "$chat_id"
            _fm_bot_hwidpend_clear "$chat_id"
            _fm_bot_node_selected_clear "$chat_id" 2>/dev/null || true
            _fm_bot_send_main_menu "$chat_id"
            return
            ;;
        cancel)
            # Says out loud what "main menu" only implies: nothing was
            # created and nothing was charged. Reachable from every step
            # of a flow, which is the whole point — a customer who has
            # second thoughts at the device-id screen should not have to
            # guess whether leaving costs them anything.
            _fm_bot_flow_reset "$chat_id"
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg FLOW_CANCELLED "$lang")"
            _fm_bot_send_main_menu "$chat_id"
            return
            ;;
        back)
            # Pop remembered steps until one is worth showing. A step
            # with a single option answers itself the moment it is drawn,
            # so stopping on it would bounce the customer straight back
            # to the screen they just left — the button would look dead.
            # Nothing remembered (the first screen of a flow, or the main
            # menu) means there is nowhere to go back to, so the main
            # menu is the honest answer — but the button isn't shown
            # there in the first place, see _fm_bot_keyboard_json_from_list.
            local prev="" hops=0
            while (( hops < 12 )); do
                prev=$(_fm_bot_nav_pop "$chat_id")
                [[ -z "$prev" ]] && break
                [[ "$(_fm_bot_step_options_count "$prev" "$chat_id")" == "1" ]] || break
                hops=$((hops+1))
            done
            if [[ -z "$prev" ]]; then
                _fm_bot_pending_clear "$chat_id"
                _fm_bot_send_main_menu "$chat_id"
                return
            fi
            _fm_bot_pending_set "$chat_id" "$prev"
            _fm_bot_render_step "$chat_id" "$prev"
            return
            ;;
        langtoggle)
            local new_lang="en"; [[ "$lang" == "en" ]] && new_lang="ar"
            _fm_bot_lang_set "$chat_id" "$new_lang"
            _fm_bot_pending_clear "$chat_id"
            _fm_bot_send_main_menu "$chat_id"
            return
            ;;
        trial)
            # First a server region (if any are configured), then a
            # device type (if there's anything to filter apps by),
            # then which app/file-type — and only then the HWID, so the
            # config file can be handed over the moment the account is
            # created, in the same breath. Each step is skipped when
            # there's nothing to ask (no regions configured, no app
            # files uploaded) so this degrades to the old direct-HWID
            # behavior on a fresh setup.
            _fm_bot_start_flow "$chat_id" "trial"
            return
            ;;
        subscribe)
            # Duration first (1 month vs 2 months) — the picked tier then
            # rides along as the flow name itself ("subscribe1"/
            # "subscribe2") through region/device/app/type/HWID, see the
            # "subscribe_duration" pending case below.
            _fm_bot_goto "$chat_id" "subscribe_duration"
            _fm_bot_send_duration_list "$chat_id"
            return
            ;;
        renew)
            _fm_bot_cmd_renew_start "$chat_id"
            return
            ;;
        balance)
            local bal; bal=$(_fm_bot_wallet_get "$chat_id")
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt BALANCE_MSG "$lang" BALANCE "$bal")"
            return
            ;;
        myaccount)
            _fm_bot_cmd_myaccount "$chat_id"
            return
            ;;
        referral)
            _fm_bot_cmd_referral "$chat_id"
            return
            ;;
        support)
            _fm_bot_goto "$chat_id" "support"
            _fm_bot_send_card "$chat_id" "$(_fm_bot_msg SUPPORT_ASK "$lang")" \
                "$(_fm_bot_nav_keyboard_json "$lang" "$chat_id")"
            return
            ;;
        changehwid)
            _fm_bot_cmd_changehwid_start "$chat_id"
            return
            ;;
    esac

    # A pending step (awaiting an HWID, a support message, an app/type
    # tap) takes priority over both the buttons above (already handled)
    # and the legacy slash-command parser below.
    local pending; pending=$(_fm_bot_pending_get "$chat_id")
    if [[ -n "$pending" ]]; then
        local p_action p_ctx1 p_ctx2
        IFS=: read -r p_action p_ctx1 p_ctx2 <<< "$pending"
        case "$p_action" in
            trial)
                _fm_bot_pending_clear "$chat_id"
                _fm_bot_cmd_trial "$chat_id" "$text"
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
            subscribe1|subscribe2)
                # Degenerate case only: no app files are configured at
                # all, so the region/device/app/type steps were all
                # skipped and this text IS the HWID directly. The tier
                # picked at the very first step is still carried in
                # p_action itself ("subscribe1"/"subscribe2").
                local tier="${p_action#subscribe}"
                _fm_bot_pending_clear "$chat_id"
                _fm_bot_cmd_subscribe "$chat_id" "$text" "" "" "$tier"
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
            changehwid)
                # Degenerate case only: no app files are configured at
                # all, so the region/device/app/type steps were all
                # skipped and this text IS the new HWID directly.
                _fm_bot_pending_clear "$chat_id"
                if _fm_bot_cmd_changehwid_finish "$chat_id" "$text"; then
                    # Nothing was chosen this time round, so the only
                    # thing to re-send is whatever was sent last.
                    local ch_rec; ch_rec=$(_fm_bot_delivery_get "$_FM_BOT_LAST_ACCOUNT" 2>/dev/null)
                    if [[ -n "$ch_rec" ]]; then
                        local ch_app ch_type _ch_dev
                        IFS=$'\t' read -r ch_app ch_type _ch_dev <<< "$ch_rec"
                        _fm_bot_appfile_render_and_send "$chat_id" "$ch_app" "$ch_type" "$_FM_BOT_LAST_HWID" "${_FM_BOT_LAST_ACCOUNT:-}"
                    fi
                fi
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
            subscribe_duration)
                local tier; tier=$(_fm_bot_duration_find_by_text "$text")
                if [[ -z "$tier" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_DURATION_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_start_flow "$chat_id" "subscribe${tier}"
                return
                ;;
            changehwid_pick)
                # More than one owned device was offered as buttons —
                # match the tap back against that same list, then
                # continue exactly like the single-account path.
                local owned hwids picked
                owned=$(_fm_bot_accounts_for_owner_dispatch "tg:${chat_id}")
                hwids=$(awk -F: '{print $1}' <<< "$owned")
                picked=$(grep -Fx "$text" <<< "$hwids")
                if [[ -z "$picked" ]]; then
                    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt INVALID_CHANGEHWID_PICK "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                local remaining; remaining=$(_fm_bot_hwidchange_remaining "$chat_id")
                _fm_bot_hwidchange_state_set "$chat_id" "$picked"
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt CHANGE_HWID_START "$lang" REMAINING "$remaining")"
                _fm_bot_start_flow "$chat_id" "changehwid"
                return
                ;;
            renew_hwid_pick)
                local owned hwids picked
                owned=$(_fm_bot_accounts_for_owner_dispatch "tg:${chat_id}")
                hwids=$(awk -F: '{print $1}' <<< "$owned")
                picked=$(grep -Fx "$text" <<< "$hwids")
                if [[ -z "$picked" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_RENEW_HWID_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_goto "$chat_id" "renew_duration:${picked}"
                _fm_bot_send_duration_list "$chat_id"
                return
                ;;
            renew_duration)
                # Renewal skips app/file-type selection entirely — the
                # config file was already delivered when the account was
                # first created, and _fm_bot_cmd_subscribe treats a
                # same-owner/same-hwid purchase as a renewal automatically.
                local hwid="$p_ctx1" tier
                tier=$(_fm_bot_duration_find_by_text "$text")
                if [[ -z "$tier" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_DURATION_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_pending_clear "$chat_id"
                _fm_bot_cmd_subscribe "$chat_id" "$hwid" "" "" "$tier"
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
            trial_region|subscribe1_region|subscribe2_region|changehwid_region)
                local flow="${p_action%_region}" slug
                slug=$(_fm_bot_region_find_by_text "$text")
                if [[ -z "$slug" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_REGION_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                local r_line r_mode r_url r_name
                r_line=$(_fm_bot_region_get "$slug")
                IFS=: read -r _r_slug _r_ar _r_en r_mode _r_enabled r_url <<< "$r_line"
                if [[ "$r_mode" == "redirect" ]]; then
                    r_name=$(_fm_bot_region_name "$slug" "$lang")
                    _fm_bot_pending_clear "$chat_id"
                    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt REGION_REDIRECT "$lang" REGION "$r_name" LINK "$r_url")"
                    _fm_bot_send_main_menu "$chat_id"
                    return
                fi
                # "node": remember this pick for every provisioning call
                # the rest of THIS flow makes (see _fm_bot_resolve_node_
                # for_call) — device/app/country/HWID all happen after
                # this step, so the pending-state tuple can't carry it
                # (both its slots are already spoken for by then).
                #
                # The else branch is not optional. Setting the pick only
                # for a node region left an EARLIER pick standing when
                # the customer then chose a non-node one, so picking
                # Saudi right after a Germany purchase silently built the
                # account on Germany — the customer's current choice
                # losing to their previous one. Whatever this step
                # decides is now the whole truth about which node this
                # flow uses.
                if [[ "$r_mode" == "node" ]]; then
                    _fm_bot_node_selected_set "$chat_id" "$slug"
                else
                    _fm_bot_node_selected_clear "$chat_id"
                fi
                _fm_bot_start_device_or_hwid "$chat_id" "$flow"
                return
                ;;
            trial_device|subscribe1_device|subscribe2_device|changehwid_device)
                local flow="${p_action%_device}" device
                device=$(_fm_bot_device_find_by_text "$text")
                if [[ -z "$device" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_DEVICE_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_device_selected_set "$chat_id" "$device"
                _fm_bot_goto "$chat_id" "${flow}_app:${device}"
                _fm_bot_send_app_list "$chat_id" "$device"
                return
                ;;
            trial_app|subscribe1_app|subscribe2_app|changehwid_app)
                local flow="${p_action%_app}" device="$p_ctx1" app node
                app=$(_fm_bot_appfile_apps_list_for_platform "$device" | grep -Fx "$text")
                if [[ -z "$app" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_APP_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                node=$(_fm_bot_node_selected_get "$chat_id")
                if [[ -n "$(_fm_bot_countries_list_for_app "$app" "$node")" ]]; then
                    _fm_bot_goto "$chat_id" "${flow}_country:${app}"
                    _fm_bot_send_country_list "$chat_id" "$app" "$node"
                else
                    # No countries configured yet for this node — nothing
                    # to ask, so skip straight to the tail of the chain
                    # with the node's own (possibly empty) prefix.
                    # Delivery will report the file as unavailable until
                    # the admin sets country/SIM-type up for this node,
                    # exactly like an app with no file types ever did
                    # before this feature existed.
                    _fm_bot_on_apptype_chosen "$chat_id" "$flow" "$app" "$(_fm_bot_node_country_simtype_key "$node" "" "")"
                fi
                return
                ;;
            trial_country|subscribe1_country|subscribe2_country|changehwid_country)
                local flow="${p_action%_country}" app="$p_ctx1" country node
                node=$(_fm_bot_node_selected_get "$chat_id")
                country=$(_fm_bot_country_find_by_text "$text" "$app" "$node")
                if [[ -z "$country" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_COUNTRY_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                if [[ -n "$(_fm_bot_simtypes_list_for_country "$country" "$app" "$node")" ]]; then
                    _fm_bot_goto "$chat_id" "${flow}_simtype:${app}:${country}"
                    _fm_bot_send_simtype_list "$chat_id" "$country" "$app" "$node"
                else
                    # This country has no SIM types configured for this
                    # node — nothing to ask there, so fold the country
                    # (and node) alone into the prefix and let the shared
                    # helper decide whether a file-type question is still
                    # needed for it.
                    _fm_bot_on_country_simtype_prefix_ready "$chat_id" "$flow" "$app" "$(_fm_bot_node_country_simtype_key "$node" "$country" "")"
                fi
                return
                ;;
            trial_simtype|subscribe1_simtype|subscribe2_simtype|changehwid_simtype)
                local flow="${p_action%_simtype}" app="$p_ctx1" country="$p_ctx2" simtype node
                node=$(_fm_bot_node_selected_get "$chat_id")
                simtype=$(_fm_bot_simtype_find_by_text "$country" "$text" "$app" "$node")
                if [[ -z "$simtype" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_SIMTYPE_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_on_country_simtype_prefix_ready "$chat_id" "$flow" "$app" "$(_fm_bot_node_country_simtype_key "$node" "$country" "$simtype")"
                return
                ;;
            trial_filetype|subscribe1_filetype|subscribe2_filetype|changehwid_filetype)
                local flow="${p_action%_filetype}" app="$p_ctx1" prefix="$p_ctx2" filetype
                filetype=$(_fm_bot_filetype_find_by_text "$prefix" "$text" "$app")
                if [[ -z "$filetype" ]]; then
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg_fmt INVALID_FILETYPE_CHOICE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                _fm_bot_on_apptype_chosen "$chat_id" "$flow" "$app" "$(_fm_bot_filetype_key "$prefix" "$filetype")"
                return
                ;;
            subscribe1_receipt|subscribe2_receipt)
                # Waiting for proof of a bank transfer. Only an actual
                # attachment counts — a typed reply just gets a nudge, so
                # a customer can't skip the step by sending "done".
                local flow="${p_action%_receipt}" app="$p_ctx1" ftype="$p_ctx2"
                if [[ -z "$attach_kind" ]]; then
                    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt RECEIPT_NUDGE "$lang" MAINMENU_BTN "$(_fm_bot_btn_mainmenu "$lang")")"
                    return
                fi
                # Context first, then the receipt itself, so the admin
                # reads who/what before the forwarded attachment lands.
                send_telegram_msg "$(_fm_bot_msg_fmt RECEIPT_ADMIN_CONTEXT ar CHAT_ID "$chat_id" APP "$app" TYPE "$ftype")"
                # If the image could not be delivered, the step does NOT
                # advance: telling the customer "receipt received" and
                # letting an order appear while the admin has no proof at
                # all is the one outcome worth failing loudly over. Both
                # sides are told, so neither is left guessing.
                if ! _fm_bot_forward_to_admin "$chat_id" "$msg_id"; then
                    send_telegram_msg "$(_fm_bot_msg_fmt RECEIPT_FORWARD_FAILED ar CHAT_ID "$chat_id")"
                    send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RECEIPT_RESEND "$lang")"
                    return
                fi
                _fm_bot_receipt_mark "$chat_id"
                _fm_bot_goto "$chat_id" "${flow}_hwid:${app}:${ftype}"
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RECEIPT_RECEIVED "$lang")"
                _fm_bot_send_hwid_guide "$chat_id" "$app"
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg RECEIPT_ASK_HWID "$lang")"
                return
                ;;
            trial_hwid|subscribe1_hwid|subscribe2_hwid|changehwid_hwid)
                # The id is checked while the step is still open, so a
                # bad one leaves the customer on the same card with the
                # same question rather than with an account, an order or
                # a spent device-change behind a file that cannot work.
                local hw_flow="${p_action%_hwid}" app="$p_ctx1" ftype="$p_ctx2"
                _fm_bot_hwid_gate "$chat_id" "$app" "$ftype" "$text" || return
                # Passing every check is still not consent: an id one
                # character wrong looks perfectly fine in a chat bubble,
                # so it is read back to the customer and nothing is
                # created until they say yes.
                _fm_bot_hwidpend_set "$chat_id" "$text"
                _fm_bot_goto "$chat_id" "${hw_flow}_hwidok:${app}:${ftype}"
                _fm_bot_send_hwid_confirm "$chat_id" "$(awk '{print $1}' <<< "$text")"
                return
                ;;
            trial_hwidok|subscribe1_hwidok|subscribe2_hwidok|changehwid_hwidok)
                local ok_flow="${p_action%_hwidok}" app="$p_ctx1" ftype="$p_ctx2"
                if [[ "$text" == "$(_fm_bot_btn_hwid_no ar)" || "$text" == "$(_fm_bot_btn_hwid_no en)" ]]; then
                    _fm_bot_hwidpend_clear "$chat_id"
                    _fm_bot_pending_set "$chat_id" "${ok_flow}_hwid:${app}:${ftype}"
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg HWID_CONFIRM_RETRY "$lang")"
                    return
                fi
                if [[ "$text" != "$(_fm_bot_btn_hwid_yes ar)" && "$text" != "$(_fm_bot_btn_hwid_yes en)" ]]; then
                    # They typed a different id instead of tapping either
                    # button. Take it as the correction it obviously is,
                    # rather than telling them to press "no" first.
                    _fm_bot_pending_set "$chat_id" "${ok_flow}_hwid:${app}:${ftype}"
                    _fm_bot_hwid_gate "$chat_id" "$app" "$ftype" "$text" || return
                    _fm_bot_hwidpend_set "$chat_id" "$text"
                    _fm_bot_pending_set "$chat_id" "${ok_flow}_hwidok:${app}:${ftype}"
                    _fm_bot_send_hwid_confirm "$chat_id" "$(awk '{print $1}' <<< "$text")"
                    return
                fi
                local hw_text; hw_text=$(_fm_bot_hwidpend_get "$chat_id") || hw_text=""
                if [[ -z "$hw_text" ]]; then
                    # The saved id is gone (a restart between the two
                    # taps). Ask again rather than guess — "yes" is not
                    # an id, and creating an account from it would be
                    # exactly the mistake this step exists to prevent.
                    _fm_bot_pending_set "$chat_id" "${ok_flow}_hwid:${app}:${ftype}"
                    _fm_bot_card_notice "$chat_id" "$(_fm_bot_msg HWID_CONFIRM_LOST "$lang")"
                    return
                fi
                _fm_bot_hwidpend_clear "$chat_id"
                _fm_bot_pending_clear "$chat_id"
                case "$ok_flow" in
                    trial)
                        if _fm_bot_cmd_trial "$chat_id" "$hw_text"; then
                            _fm_bot_appfile_render_and_send "$chat_id" "$app" "$ftype" "$_FM_BOT_LAST_HWID" "${_FM_BOT_LAST_ACCOUNT:-}"
                        fi
                        ;;
                    subscribe1|subscribe2)
                        # rc 0 = paid instantly from wallet, account
                        # exists right now — send the file. rc 2 = a
                        # manual-payment order was created instead; the
                        # account doesn't exist yet, so the file is
                        # delivered later, when the admin approves it
                        # (see _fm_bot_admin_approve_order, which reads
                        # the app/type stored on the order itself).
                        local tier="${ok_flow#subscribe}" sub_rc
                        _fm_bot_cmd_subscribe "$chat_id" "$hw_text" "$app" "$ftype" "$tier"
                        sub_rc=$?
                        if [[ $sub_rc -eq 0 ]]; then
                            _fm_bot_appfile_render_and_send "$chat_id" "$app" "$ftype" "$_FM_BOT_LAST_HWID" "${_FM_BOT_LAST_ACCOUNT:-}"
                        fi
                        ;;
                    changehwid)
                        if _fm_bot_cmd_changehwid_finish "$chat_id" "$hw_text"; then
                            _fm_bot_appfile_render_and_send "$chat_id" "$app" "$ftype" "$_FM_BOT_LAST_HWID" "${_FM_BOT_LAST_ACCOUNT:-}"
                        fi
                        ;;
                esac
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
            support)
                _fm_bot_pending_clear "$chat_id"
                send_telegram_msg_kb "$(_fm_bot_msg_fmt SUPPORT_ADMIN_FORWARD ar CHAT_ID "$chat_id" TEXT "$(_fm_html_escape "$text")")" \
                    "{\"inline_keyboard\":[[{\"text\":\"↩️ رد على العميل\",\"callback_data\":\"rp:${chat_id}\"}]]}"
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg MESSAGE_SENT_TO_ADMIN "$lang")"
                _fm_bot_send_main_menu "$chat_id"
                return
                ;;
        esac
    fi

    case "$cmd" in
        /start|/help) _fm_bot_send_main_menu "$chat_id" ;;
        /trial) _fm_bot_cmd_trial "$chat_id" "$rest" ;;
        /subscribe) _fm_bot_cmd_subscribe "$chat_id" "$rest" ;;
        /balance)
            local bal; bal=$(_fm_bot_wallet_get "$chat_id")
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg_fmt BALANCE_MSG "$lang" BALANCE "$bal")"
            ;;
        /myaccount) _fm_bot_cmd_myaccount "$chat_id" ;;
        /referral) _fm_bot_cmd_referral "$chat_id" ;;
        /appeal)
            if [[ -z "$rest" ]]; then
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg APPEAL_CMD_USAGE "$lang")"
            else
                send_telegram_msg_kb "$(_fm_bot_msg_fmt SUPPORT_ADMIN_FORWARD ar CHAT_ID "$chat_id" TEXT "$(_fm_html_escape "$rest")")" \
                    "{\"inline_keyboard\":[[{\"text\":\"↩️ رد على العميل\",\"callback_data\":\"rp:${chat_id}\"}]]}"
                send_telegram_msg_to "$chat_id" "$(_fm_bot_msg MESSAGE_SENT_TO_ADMIN "$lang")"
            fi
            ;;
        *)
            send_telegram_msg_to "$chat_id" "$(_fm_bot_msg FALLBACK_UNKNOWN "$lang")"
            _fm_bot_send_main_menu "$chat_id"
            ;;
    esac
}

# ── The full subscription card the ADMIN sees ─────────────────────────
# Approving an order used to answer with nothing but "order #N approved",
# which left the one person who might need to cancel, look up or support
# that subscription with no way to reach it — not the account name, not
# the customer's Telegram id, nothing. This gathers every fact about one
# account from the stores that already hold them and renders it once, so
# the approval reply, the wallet purchase and the /acct lookup all show
# the identical card.
#
# Every field degrades to a dash on its own rather than dropping the
# card: a missing usage counter or delivery record must never cost the
# admin the account name and the customer's id, which are the two things
# an incident actually needs.
_fm_bot_admin_account_card() {
    local account="$1" tg="$2"
    # Initialised, not just declared: an account that is not in DB_FILE
    # at all (already removed, or living only on a node) must still
    # render a card — under `set -u` a bare `local u` would abort the
    # whole reply instead, which is exactly when the admin most needs
    # the name and the customer id.
    local u="" p="" exp="" lim="" bw="" dbw="" atype="" owner="" row=""
    # Node accounts do not exist in this box's DB_FILE at all — they live
    # on the node — so reading DB_FILE directly left every field but the
    # name blank for exactly the accounts the admin is most likely to be
    # asked about. The dispatch returns the same users.db-shaped row for
    # both, fetching it over the node API when needed.
    # For a node account this is an HTTP round trip, bounded by its own
    # pieces (an 8s fingerprint probe plus a 10s call). That is why every
    # caller sends this card only AFTER the customer already has their
    # activation and file: the worst this can cost is the admin's own
    # copy arriving a few seconds late.
    row=$(_fm_bot_account_status_dispatch "$account" 2>/dev/null)
    # A node that is down, slow, or mid-migration must not blank the
    # card: fall back to whatever this box still knows. Stale beats
    # empty when the admin is looking at it because something is wrong.
    [[ -n "$row" ]] || row=$(awk -F: -v a="$account" '$1==a{print; exit}' "$DB_FILE" 2>/dev/null)
    if [[ -n "$row" ]]; then
        IFS=: read -r u p exp lim bw dbw atype owner <<< "$row"
    fi
    [[ -n "$u" ]] || u="$account"
    [[ -n "$tg" ]] || tg="${owner#tg:}"

    # Quota + what has actually been burned of it.
    local bw_line="غير محدود"
    if [[ -n "$bw" && "$bw" != "0" ]]; then
        local used_b=0 uf="${BANDWIDTH_DIR:-/etc/firewallfalcon/bandwidth}/${u}.usage"
        if [[ -f "$uf" ]]; then
            read -r used_b < "$uf" 2>/dev/null
            [[ "$used_b" =~ ^[0-9]+$ ]] || used_b=0
        fi
        local ug_i=$((used_b / 1073741824))
        local ug_f=$(( (used_b % 1073741824) * 100 / 1073741824 ))
        local rem_b=$(( ${bw%%.*} * 1073741824 - used_b )); (( rem_b < 0 )) && rem_b=0
        local rg_i=$((rem_b / 1073741824))
        local rg_f=$(( (rem_b % 1073741824) * 100 / 1073741824 ))
        bw_line=$(printf '%d.%02d من %s جيجا — متبقٍ %d.%02d' "$ug_i" "$ug_f" "$bw" "$rg_i" "$rg_f")
    fi

    # Days left, computed rather than trusted: an expiry already in the
    # past is the single most useful thing to see at a glance.
    local exp_line="—"
    if [[ -n "$exp" ]]; then
        exp_line="$exp"
        local e_s t_s
        e_s=$(date -d "$exp" +%s 2>/dev/null)
        t_s=$(date +%s 2>/dev/null)
        if [[ -n "$e_s" && -n "$t_s" ]]; then
            local d_left=$(( (e_s - t_s) / 86400 ))
            if (( d_left < 0 )); then exp_line+=" (⚠️ منتهٍ)"
            else exp_line+=" (باقٍ ${d_left} يوم)"; fi
        fi
    fi

    # Where the account physically lives, and what was delivered for it.
    local node; node=$(_fm_bot_node_accounts_get_by_account "$u" 2>/dev/null)
    [[ -n "$node" ]] || node="محلي (هذا السيرفر)"
    local dev; dev=$(_fm_bot_device_for_account "$u" 2>/dev/null)
    [[ -n "$dev" ]] || dev="$u"
    local d_app="—" d_type="—" drow=""
    drow=$(_fm_bot_delivery_get "$u" 2>/dev/null)
    if [[ -n "$drow" ]]; then
        IFS=$'\t' read -r d_app d_type _ <<< "$drow"
        [[ -n "$d_app" ]] || d_app="—"
        [[ -n "$d_type" ]] || d_type="—"
    fi
    local link; link=$(_fm_bot_bandwidth_link_dispatch "$u" 2>/dev/null)

    local msg="📋 <b>بطاقة الاشتراك</b>%0A"
    msg+="━━━━━━━━━━━━━━%0A"
    msg+="🪪 الحساب: <code>$(_fm_html_escape "$u")</code>%0A"
    msg+="🔑 كلمة المرور: <code>$(_fm_html_escape "${p:-—}")</code>%0A"
    msg+="👤 تيليجرام: <a href=\"tg://user?id=${tg}\">${tg}</a> — <code>${tg}</code>%0A"
    msg+="📱 الجهاز: <code>$(_fm_html_escape "$dev")</code>%0A"
    msg+="📦 التطبيق: $(_fm_html_escape "$d_app") — $(_fm_html_escape "$d_type")%0A"
    msg+="🌍 السيرفر: $(_fm_html_escape "$node")%0A"
    msg+="📅 ينتهي: ${exp_line}%0A"
    msg+="📊 الاستهلاك: ${bw_line}%0A"
    msg+="🔢 عدد الأجهزة: ${lim:-—}%0A"
    [[ -n "$link" ]] && msg+="🔗 <a href=\"${link}\">متابعة الاستهلاك</a>%0A"
    msg+="━━━━━━━━━━━━━━%0A"
    msg+="⚙️ إيقاف هذا الاشتراك: <code>/cancel ${u}</code>%0A"
    msg+="⚙️ حظر العميل نهائيًا: <code>/ban ${tg} السبب</code>%0A"
    msg+="⚙️ عرض البطاقة لاحقًا: <code>/acct ${u}</code>"
    printf '%s' "$msg"
}

# ── Who the bot can reach, and the announcement that reaches them ─────
# Telegram gives no "list my users" call, so an audience only exists if
# the bot keeps one. Every chat that talks to the customer side is
# recorded here — but the registry starts empty on an existing install,
# so the audience is the UNION of it and every store that already names
# a customer (subscribers, wallets, trials, orders). Without that union
# the first announcement after this ships would reach nobody who had
# already bought.
BOT_KNOWN_CHATS_DB="${BOT_KNOWN_CHATS_DB:-/etc/firewallfalcon/bot_known_chats.db}"
BOT_BROADCAST_DRAFT="${BOT_BROADCAST_DRAFT:-/etc/firewallfalcon/bot_broadcast_draft.txt}"

_fm_bot_known_chat_add() {
    local chat_id="$1" db="${BOT_KNOWN_CHATS_DB:-/etc/firewallfalcon/bot_known_chats.db}"
    [[ "$chat_id" =~ ^-?[0-9]+$ ]] || return 0
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    grep -qx "$chat_id" "$db" 2>/dev/null && return 0
    echo "$chat_id" >> "$db"
}

# Every numeric chat id the bot has any record of, once each. Banned
# customers are dropped: an announcement is marketing, and marketing to
# someone you have blocked is just noise that invites a report.
_fm_bot_all_chat_ids() {
    {
        [[ -f "${BOT_KNOWN_CHATS_DB:-/etc/firewallfalcon/bot_known_chats.db}" ]] && \
            cat "${BOT_KNOWN_CHATS_DB:-/etc/firewallfalcon/bot_known_chats.db}"
        # Subscribers: the account row is
        # user:pass:expiry:limit:bw:daily:type:tg:<id> — the owner tag is
        # "tg:<id>", so its colon makes it the last TWO fields.
        [[ -f "$DB_FILE" ]] && awk -F: '$8=="tg"{print $9}' "$DB_FILE"
        [[ -f "$BOT_WALLETS_DB" ]] && awk -F: '{print $1}' "$BOT_WALLETS_DB"
        [[ -f "$BOT_TRIAL_LOG" ]] && awk -F: '{print $1}' "$BOT_TRIAL_LOG"
        [[ -f "$BOT_ORDERS_DB" ]] && awk -F: '{print $2}' "$BOT_ORDERS_DB"
        [[ -f "$BOT_LANG_DB" ]] && awk -F: '{print $1}' "$BOT_LANG_DB"
    } 2>/dev/null | grep -E '^-?[0-9]+$' | sort -u | awk -F: -v bans="${BOT_BANS_DB:-/etc/firewallfalcon/bot_bans.db}" '
        # The ban list is read ONCE into memory, not re-grepped per chat.
        # The old loop shelled out to _fm_bot_is_banned for every single
        # id, so a thousand customers meant a thousand greps — over a
        # second of pure overhead, paid inside the poll loop every time
        # the audience was counted. Same rule as before: a row is a ban
        # if its FIRST colon-separated field is the chat id.
        BEGIN {
            while ((getline line < bans) > 0) {
                n = index(line, ":")
                if (n > 1) banned[substr(line, 1, n - 1)] = 1
            }
            close(bans)
        }
        !($0 in banned)
    '
}

# Sends the stored draft to everyone, then reports what actually
# happened. Runs detached (see the call site): a few hundred customers at
# Telegram's rate limit is a minute of work, and the poll loop must keep
# answering everyone else meanwhile. Every send is counted, so a customer
# who blocked the bot shows up as a number rather than silently vanishing.
# Hands the announcement to a DETACHED worker and returns at once.
#
# This used to send every message itself, inline, from inside the poll
# loop. The bot handles one thing at a time, so for the whole run it
# answered nobody: no getUpdates, no replies, nothing. With a thousand
# recipients that is minutes at best — and far worse in practice, since
# every customer who blocked the bot or never really started it makes
# Telegram sit on the connection until curl's own timeout fires. A few
# hundred of those and one announcement freezes the bot for the better
# part of an hour, while paying customers get no answer at all.
#
# Sending is not something anyone waits on, so it has no business
# holding the loop. The admin gets told it started, and told again with
# the totals when it finishes.
_fm_bot_broadcast_send() {
    local text="$1"
    [[ -n "$text" ]] || return 1
    [[ -f "$TELEGRAM_CONF" ]] || return 1
    local spool="${BOT_BROADCAST_SPOOL_DIR:-/etc/firewallfalcon/broadcast}"
    mkdir -p "$spool" 2>/dev/null || return 1
    local job="${spool}/$(date +%s)-$$.txt"
    printf '%s' "$text" > "$job" 2>/dev/null || return 1
    chmod 600 "$job" 2>/dev/null
    local total; total=$(_fm_bot_all_chat_ids | grep -c . 2>/dev/null) || total=0
    send_telegram_msg "$(_fm_bot_msg_fmt BROADCAST_STARTED ar TOTAL "$total")"
    # setsid + nohup so it survives the bot service being restarted
    # mid-run, and so nothing about it can block this caller.
    setsid nohup bash "${FM_SELF:-/usr/local/bin/dahoom}" _run_bot_broadcast "$job" \
        >/dev/null 2>&1 < /dev/null &
    disown 2>/dev/null || true
    return 0
}

# The detached worker. Runs outside the poll loop, so its pace is its
# own business.
_fm_bot_broadcast_worker() {
    local job="$1"
    [[ -f "$job" ]] || return 1
    local text; text=$(cat "$job" 2>/dev/null)
    [[ -n "$text" ]] || { rm -f "$job" 2>/dev/null; return 1; }
    local sent=0 failed=0 cid resp
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    [[ -f "$TELEGRAM_CONF" ]] || return 1
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" ]] || return 1
    while IFS= read -r cid; do
        [[ -n "$cid" ]] || continue
        # 8s, not 20: a chat that has not answered in 8 seconds is a
        # blocked or dead one, and waiting longer only slows the run for
        # everyone still to come.
        resp=$(curl -s --max-time 8 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" \
            -d "chat_id=${cid}" \
            --data-urlencode "text=${text}" \
            -d "parse_mode=HTML" \
            -d "disable_web_page_preview=true" 2>/dev/null)
        if [[ "$resp" == *'"ok":true'* ]]; then
            sent=$((sent+1))
        else
            failed=$((failed+1))
            # Being rate-limited is the one failure worth waiting out:
            # Telegram says exactly how long, and ignoring it makes every
            # remaining send fail too.
            if [[ "$resp" == *'"retry_after"'* ]]; then
                local wait_s; wait_s=$(sed -nE 's/.*"retry_after":([0-9]+).*/\1/p' <<< "$resp")
                [[ "$wait_s" =~ ^[0-9]+$ ]] && (( wait_s <= 60 )) && sleep "$wait_s"
            fi
        fi
        # Telegram caps bulk sending at ~30 messages/second; staying well
        # under it is what keeps the bot from being rate-limited into
        # dropping the rest of the run.
        sleep 0.05
    done < <(_fm_bot_all_chat_ids)
    rm -f "$job" 2>/dev/null
    send_telegram_msg "$(_fm_bot_msg_fmt BROADCAST_DONE ar SENT "$sent" FAILED "$failed")"
    _log_action "BOT_BROADCAST" "all" "sent=${sent} failed=${failed}" "INFO" "bot"
    return 0
}

# ── Two-way support: the admin's side of the conversation ─────────────
# A customer's message already reaches the admin. The reply did not
# exist at all, so every support thread ended with the customer waiting.
# The admin replies either by tapping "رد" under the forwarded message
# (which remembers who is being answered, so the next thing typed is the
# reply) or with an explicit /reply <id> <text>.
BOT_ADMIN_REPLY_TO_DB="${BOT_ADMIN_REPLY_TO_DB:-/etc/firewallfalcon/bot_admin_reply_to.txt}"
# "Waiting for the announcement text". The menu button cannot carry the
# text with it — the callback whitelist deliberately admits only
# argument-free commands — so tapping it arms this instead, and the next
# thing the admin types becomes the draft. Mutually exclusive with the
# reply target: two modes competing for the same plain message would
# make it a coin toss which one got it.
BOT_ADMIN_BCAST_WAIT="${BOT_ADMIN_BCAST_WAIT:-/etc/firewallfalcon/bot_admin_bcast_wait.flag}"

_fm_bot_admin_bcast_wait_set() {
    local f="${BOT_ADMIN_BCAST_WAIT:-/etc/firewallfalcon/bot_admin_bcast_wait.flag}"
    mkdir -p "$(dirname "$f")" 2>/dev/null
    : > "$f" 2>/dev/null
}
_fm_bot_admin_bcast_wait_is_on() {
    [[ -f "${BOT_ADMIN_BCAST_WAIT:-/etc/firewallfalcon/bot_admin_bcast_wait.flag}" ]]
}
_fm_bot_admin_bcast_wait_clear() {
    rm -f "${BOT_ADMIN_BCAST_WAIT:-/etc/firewallfalcon/bot_admin_bcast_wait.flag}" 2>/dev/null
    return 0
}

# Saves the text and shows it back with the real audience count and the
# two buttons. Shared by the typed command and the composed-by-button
# path so both confirm identically — an announcement is unrecallable.
_fm_bot_broadcast_preview() {
    local text="$1"
    [[ -n "$text" ]] || return 1
    mkdir -p "$(dirname "$BOT_BROADCAST_DRAFT")" 2>/dev/null
    printf '%s' "$text" > "$BOT_BROADCAST_DRAFT" 2>/dev/null
    local n; n=$(_fm_bot_all_chat_ids | grep -c .)
    send_telegram_msg_kb \
        "📢 <b>معاينة الإعلان</b>%0A━━━━━━━━━━━━━━%0A${text}%0A━━━━━━━━━━━━━━%0A%0Aسيصل إلى <b>${n}</b> مستخدمًا (المحظورون مستثنون).%0Aلا يمكن التراجع بعد الإرسال." \
        '{"inline_keyboard":[[{"text":"📢 إرسال للجميع","callback_data":"bc:go"},{"text":"❌ إلغاء","callback_data":"bc:no"}]]}'
    return 0
}

_fm_bot_admin_reply_target_set() {
    local target="$1" f="${BOT_ADMIN_REPLY_TO_DB:-/etc/firewallfalcon/bot_admin_reply_to.txt}"
    [[ "$target" =~ ^-?[0-9]+$ ]] || return 1
    mkdir -p "$(dirname "$f")" 2>/dev/null
    printf '%s' "$target" > "$f" 2>/dev/null
}

_fm_bot_admin_reply_target_get() {
    local f="${BOT_ADMIN_REPLY_TO_DB:-/etc/firewallfalcon/bot_admin_reply_to.txt}"
    [[ -f "$f" ]] || return 1
    local t; t=$(cat "$f" 2>/dev/null)
    [[ "$t" =~ ^-?[0-9]+$ ]] || return 1
    printf '%s' "$t"
}

_fm_bot_admin_reply_target_clear() {
    rm -f "${BOT_ADMIN_REPLY_TO_DB:-/etc/firewallfalcon/bot_admin_reply_to.txt}" 2>/dev/null
    return 0
}

# Delivers one admin reply to one customer, in that customer's language,
# wrapped so it is obviously an answer from support and not a system
# notice they should ignore.
_fm_bot_admin_reply_deliver() {
    local target="$1" text="$2"
    [[ "$target" =~ ^-?[0-9]+$ && -n "$text" ]] || return 1
    local lang; lang=$(_fm_bot_lang_get "$target")
    _fm_bot_send_note_to "$target" "$(_fm_bot_msg SUPPORT_REPLY_HEADER "$lang")"$'\n'"$text"
    send_telegram_msg "$(_fm_bot_msg_fmt SUPPORT_REPLY_SENT ar CHAT_ID "$target")"
    _log_action "BOT_SUPPORT_REPLY" "$target" "chars=${#text}" "INFO" "bot"
    return 0
}

# ── Admin-side order approval (called from /approve and /reject) ───────
_fm_bot_admin_approve_order() {
    local order_id="$1"
    if [[ -z "$order_id" ]]; then send_telegram_msg "❌ الاستخدام: <code>/approve ORDER_ID</code>"; return; fi
    local line; line=$(_fm_bot_order_get "$order_id")
    if [[ -z "$line" ]]; then send_telegram_msg "❌ الطلب #${order_id} غير موجود."; return; fi
    local o_id o_tg o_hwid o_amt o_coupon o_status o_ts o_apptype o_tier
    IFS=: read -r o_id o_tg o_hwid o_amt o_coupon o_status o_ts o_apptype o_tier <<< "$line"
    [[ "$o_tier" == "2" ]] || o_tier="1"
    if [[ "$o_status" != "pending" ]]; then send_telegram_msg "⚠️ الطلب #${order_id} حالته بالفعل: ${o_status}."; return; fi

    # Same node the account is about to be provisioned on (the dispatch
    # resolves it identically from the very same device and chat), so an
    # order approved by hand gets that node's duration/quota rather than
    # the global one the customer never saw.
    local o_node; o_node=$(_fm_bot_resolve_node_for_call "$o_hwid" "$o_tg")
    local days bw devices
    if [[ "$o_tier" == "2" ]]; then
        days=$(_fm_bot_get_plan MONTHLY2_DAYS "$o_node"); bw=$(_fm_bot_get_plan MONTHLY2_BW_GB "$o_node"); devices=$(_fm_bot_get_plan MONTHLY2_DEVICES "$o_node")
    else
        days=$(_fm_bot_get_plan MONTHLY_DAYS "$o_node"); bw=$(_fm_bot_get_plan MONTHLY_BW_GB "$o_node"); devices=$(_fm_bot_get_plan MONTHLY_DEVICES "$o_node")
    fi
    _fm_bot_provision_hwid_account_dispatch "$o_hwid" "$((days*24))" "$bw" "$devices" "tg:${o_tg}" "web" 1
    local prc=$?
    local o_acct="${_FM_BOT_LAST_ACCOUNT:-$o_hwid}"
    local o_lang; o_lang=$(_fm_bot_lang_get "$o_tg")
    if [[ $prc -eq 1 ]]; then
        _fm_bot_order_set_status "$order_id" "rejected"
        send_telegram_msg "❌ الجهاز ${o_hwid} يخص حسابًا آخر — تم رفض الطلب #${order_id} تلقائيًا."
        send_telegram_msg_to "$o_tg" "$(_fm_bot_msg_fmt SUBSCRIBE_ORDER_DEVICE_CONFLICT "$o_lang" ORDER_ID "$order_id")"
        return
    elif [[ $prc -eq 2 ]]; then
        send_telegram_msg "❌ فشل إنشاء الحساب للطلب #${order_id}."
        return
    fi
    [[ "$o_coupon" != "-" && -n "$o_coupon" ]] && _fm_bot_coupon_increment_usage "$o_coupon"
    _fm_bot_order_set_status "$order_id" "approved"
    _fm_bot_referral_on_paid_conversion "$o_tg"
    # Confirm to the admin immediately and WITHOUT the card. The card
    # reads the account's live state, which for a node account is an HTTP
    # round trip (fingerprint probe + API call): building it here put a
    # network call — and anything that could go wrong in it — directly
    # between the approval and the customer's own activation message and
    # config file. The customer's delivery must never wait on, or be
    # lost to, something that exists purely for the admin's convenience.
    send_telegram_msg "✅ تم قبول وتفعيل الطلب #${order_id}."
    local bw_msg; if [[ "$o_lang" == "en" ]]; then bw_msg="Unlimited"; [[ "$bw" != "0" ]] && bw_msg="${bw} GB"; else bw_msg="غير محدود"; [[ "$bw" != "0" ]] && bw_msg="${bw} جيجابايت"; fi
    local approved_key="SUBSCRIBE_ORDER_APPROVED_NEW"; [[ $prc -eq 3 ]] && approved_key="SUBSCRIBE_ORDER_APPROVED_RENEWED"
    local usage_link; usage_link=$(_fm_bot_bandwidth_link_dispatch "$o_acct" 2>/dev/null)
    # See the wallet-instant-pay path above: the ID line only earns its
    # place when the account was actually minted (differs from the raw
    # device id) — otherwise it is the same string as the line right
    # after it.
    local id_line=""; [[ "$o_acct" != "$o_hwid" ]] && id_line="🪪 ID: <code>${o_acct}</code>%0A"
    send_telegram_msg_to "$o_tg" "$(_fm_bot_msg_fmt "$approved_key" "$o_lang" ID_LINE "$id_line" HWID "$o_hwid" DAYS "$days" DEVICES "$devices" BW "$bw_msg" EXPIRE "$_FM_BOT_LAST_EXPIRE" USAGE_LINK "$usage_link")"
    # The customer picked their app/file-type BEFORE ever being asked for
    # an HWID (see the app-file-first button flow) — that choice rode
    # along on the order itself since approval can happen much later, so
    # deliver it now that the account actually exists.
    if [[ -n "$o_apptype" && "$o_apptype" == *"|"* ]]; then
        local oa_app="${o_apptype%%|*}" oa_type="${o_apptype#*|}"
        _fm_bot_appfile_render_and_send "$o_tg" "$oa_app" "$oa_type" "$o_hwid" "$o_acct"
    fi
    # Now that the customer has everything, the admin's full card — last
    # on purpose, so a slow or unreachable node delays only this.
    send_telegram_msg "$(_fm_bot_admin_account_card "$o_acct" "$o_tg")"
}

_fm_bot_admin_reject_order() {
    local order_id="$1" reason="$2"
    [[ -z "$reason" ]] && reason="لم يُذكر سبب"
    if [[ -z "$order_id" ]]; then send_telegram_msg "❌ الاستخدام: <code>/reject ORDER_ID [السبب]</code>"; return; fi
    local line; line=$(_fm_bot_order_get "$order_id")
    if [[ -z "$line" ]]; then send_telegram_msg "❌ الطلب #${order_id} غير موجود."; return; fi
    local o_id o_tg o_hwid o_amt o_coupon o_status o_ts
    IFS=: read -r o_id o_tg o_hwid o_amt o_coupon o_status o_ts <<< "$line"
    if [[ "$o_status" != "pending" ]]; then send_telegram_msg "⚠️ الطلب #${order_id} حالته بالفعل: ${o_status}."; return; fi
    _fm_bot_order_set_status "$order_id" "rejected"
    send_telegram_msg "✅ تم رفض الطلب #${order_id}."
    send_telegram_msg_to "$o_tg" "$(_fm_bot_msg_fmt SUBSCRIBE_ORDER_REJECTED "$(_fm_bot_lang_get "$o_tg")" ORDER_ID "$order_id" REASON "$(_fm_html_escape "$reason")")"
}

_fm_bot_admin_stats() {
    local trial_total=0 monthly_total=0 pending_count=0 wallets_total=0
    [[ -f "$BOT_TRIAL_LOG" ]] && trial_total=$(wc -l < "$BOT_TRIAL_LOG")
    [[ -f "$BOT_ORDERS_DB" ]] && monthly_total=$(awk -F: '$6=="approved"' "$BOT_ORDERS_DB" | wc -l)
    [[ -f "$BOT_ORDERS_DB" ]] && pending_count=$(awk -F: '$6=="pending"' "$BOT_ORDERS_DB" | wc -l)
    [[ -f "$BOT_WALLETS_DB" ]] && wallets_total=$(awk -F: '{s+=$2} END{printf "%.2f", s+0}' "$BOT_WALLETS_DB")
    send_telegram_msg "📈 <b>إحصائيات المبيعات</b>%0Aالتجارب المُصدرة: ${trial_total}%0Aالاشتراكات المفعّلة: ${monthly_total}%0Aالطلبات المعلّقة: ${pending_count}%0Aإجمالي أرصدة المحافظ: ${wallets_total} ريال"
}

# Downloads a Telegram-hosted file (by file_id, from an incoming message)
# to $3 on disk — two calls, as Telegram's Bot API requires: getFile to
# resolve the file_id into a path, then a plain GET of that path under
# the file-serving host. Used for admin document uploads (/addfile).
_fm_telegram_download_file() {
    local bot_token="$1" file_id="$2" dest="$3"
    local meta; meta=$(curl -fsS --max-time 10 --connect-timeout 5 "https://api.telegram.org/bot${bot_token}/getFile?file_id=${file_id}" 2>/dev/null)
    local file_path; file_path=$(echo "$meta" | jq -r '.result.file_path // empty' 2>/dev/null)
    [[ -n "$file_path" ]] || return 1
    curl -fsS --max-time 30 --connect-timeout 5 "https://api.telegram.org/file/bot${bot_token}/${file_path}" -o "$dest" 2>/dev/null
}

# Forward a customer's message (a payment-receipt photo or document) as-is
# into the admin's chat, so the admin sees the original attachment — and who
# it came from — rather than a re-uploaded copy. Used by the subscribe flow's
# proof-of-payment step.
# Moves one customer message (in practice: a payment receipt) into the
# admin chat. The result used to be thrown away entirely, so a failed
# forward was indistinguishable from a successful one — the customer was
# told "receipt received" and an order appeared, while the admin got the
# context line and no image at all. That is not rare: Telegram's
# "Forwarded Messages: Nobody" privacy setting makes forwardMessage fail
# outright for that customer, every single time, which is exactly what
# "sometimes it arrives and sometimes it doesn't" looks like from the
# admin's side.
#
# So the result is now read, and a refused forward falls back to
# copyMessage — which sends the same photo as a new message instead of a
# forward, and is unaffected by that setting. Returns non-zero only when
# BOTH fail, and the caller is expected to act on that rather than
# pretend the receipt arrived.
_fm_bot_forward_to_admin() {
    local from_chat="$1" msg_id="$2"
    [[ -f "$TELEGRAM_CONF" ]] || return 1
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" && -n "$CHAT_ID" && -n "$from_chat" && -n "$msg_id" ]] || return 1
    local resp
    resp=$(curl -s --max-time 10 --connect-timeout 5 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/forwardMessage" \
        -d "chat_id=${CHAT_ID}" \
        -d "from_chat_id=${from_chat}" \
        -d "message_id=${msg_id}" 2>/dev/null)
    [[ "$resp" == *'"ok":true'* ]] && return 0
    resp=$(curl -s --max-time 10 --connect-timeout 5 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/copyMessage" \
        -d "chat_id=${CHAT_ID}" \
        -d "from_chat_id=${from_chat}" \
        -d "message_id=${msg_id}" 2>/dev/null)
    [[ "$resp" == *'"ok":true'* ]] && return 0
    return 1
}

# ── Proof that a receipt actually reached the admin ───────────────────
# A paid order must never exist without one. The receipt step lives in
# the button flow, but the order is created deeper down in
# _fm_bot_cmd_subscribe — which is also reachable by typing
# "/subscribe <device id>" directly, and that path never asked for a
# receipt at all. Rather than bolt a second check onto each entry point,
# the ticket is written only when the image is confirmed delivered and
# spent when the order is created, so no route (existing or future) can
# produce a pending order the admin was never shown proof for.
BOT_RECEIPT_OK_DB="${BOT_RECEIPT_OK_DB:-/etc/firewallfalcon/bot_receipt_ok.db}"

_fm_bot_receipt_mark() {
    local chat_id="$1" db="${BOT_RECEIPT_OK_DB:-/etc/firewallfalcon/bot_receipt_ok.db}"
    mkdir -p "$(dirname "$db")" 2>/dev/null
    touch "$db" 2>/dev/null
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    echo "${chat_id}:$(date +%s)" >> "$db"
}

_fm_bot_receipt_has() {
    local chat_id="$1" db="${BOT_RECEIPT_OK_DB:-/etc/firewallfalcon/bot_receipt_ok.db}"
    [[ -f "$db" ]] || return 1
    grep -q "^${chat_id}:" "$db" 2>/dev/null
}

# One receipt buys exactly one order.
_fm_bot_receipt_clear() {
    local chat_id="$1" db="${BOT_RECEIPT_OK_DB:-/etc/firewallfalcon/bot_receipt_ok.db}"
    [[ -f "$db" ]] || return 0
    sed -i "/^${chat_id}:/d" "$db" 2>/dev/null
    return 0
}

# Told once an hour at most: a broken parser would otherwise turn every
# single poll into an alert.
_fm_bot_parse_fallback_notice() {
    local expected="$1" got="$2"
    local stamp="${BOT_PARSE_FALLBACK_STAMP:-/etc/firewallfalcon/.parse_fallback_stamp}"
    local now; now=$(date +%s 2>/dev/null) || now=0
    local last=0
    [[ -f "$stamp" ]] && read -r last < "$stamp" 2>/dev/null
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    _log_action "BOT_PARSE_FALLBACK" "poll" "expected=${expected} got=${got}" "WARNING" "bot" 2>/dev/null
    (( now - last < 3600 )) && return 0
    mkdir -p "$(dirname "$stamp")" 2>/dev/null
    printf '%s' "$now" > "$stamp" 2>/dev/null
    send_telegram_msg "⚠️ <b>تنبيه فنّي</b>%0Aتعذّر تحليل دفعة التحديثات بالطريقة السريعة (توقّع ${expected}، نتج ${got}).%0Aتحوّل البوت تلقائيًا للطريقة البطيئة — الخدمة مستمرة ولم تتوقّف.%0Aأرسل هذه الرسالة للمطوّر." 2>/dev/null
}

# ── Flood guard: one abuser must not be able to starve everyone else ──
# The bot handles updates strictly one at a time, and Telegram hands them
# over 100 at a time. So a single person hammering /start thousands of
# times fills every batch with their traffic, and paying customers simply
# never get a turn — the bot looks dead to everyone while being perfectly
# healthy. Nothing in the flow could notice, because every message looked
# individually normal.
#
# The counter is a plain per-chat file: count + window start. Well under
# the limit costs one read and one write; over it, the message is dropped
# before ANY work is done for it — no state read, no card render, no
# Telegram call, no node call.
BOT_FLOOD_DB_DIR="${BOT_FLOOD_DB_DIR:-/etc/firewallfalcon/.flood}"
BOT_FLOOD_MAX="${BOT_FLOOD_MAX:-20}"        # رسائل مسموحة
BOT_FLOOD_WINDOW="${BOT_FLOOD_WINDOW:-60}"  # خلال هذه الثواني
BOT_FLOOD_COOLDOWN="${BOT_FLOOD_COOLDOWN:-300}"
# دفعة واحدة بهذا الحجم = تخريب متعمَّد، فالحظر فوري بلا إنذار
BOT_FLOOD_BAN_BURST="${BOT_FLOOD_BAN_BURST:-60}"
# أو تكرار الإغراق هذا العدد من المرّات ⇒ حظر
BOT_FLOOD_BAN_STRIKES="${BOT_FLOOD_BAN_STRIKES:-3}"

# 0 = serve them, 1 = drop this update.
#
# Three levels, deliberately: slow them, then stop them, then ban them.
# A customer poking the menu too fast is not a saboteur, so the first
# level is a temporary cooldown and nothing else. Someone who comes back
# and does it again, or who fires a single huge burst, is not confused —
# they are attacking, and they get banned permanently and automatically.
# Row: window_start:count:blocked_until:strikes.
_fm_bot_flood_check() {
    local chat_id="$1" now="${2:-0}"
    [[ "$chat_id" =~ ^-?[0-9]+$ ]] || return 0
    _fm_bot_is_admin_chat "$chat_id" && return 0
    local f="${BOT_FLOOD_DB_DIR}/${chat_id//[^0-9-]/}"
    mkdir -p "$BOT_FLOOD_DB_DIR" 2>/dev/null
    local win=0 cnt=0 blocked_until=0 strikes=0
    if [[ -f "$f" ]]; then
        IFS=: read -r win cnt blocked_until strikes < "$f" 2>/dev/null
        [[ "$win" =~ ^[0-9]+$ ]] || win=0
        [[ "$cnt" =~ ^[0-9]+$ ]] || cnt=0
        [[ "$blocked_until" =~ ^[0-9]+$ ]] || blocked_until=0
        [[ "$strikes" =~ ^[0-9]+$ ]] || strikes=0
    fi
    if (( blocked_until > now )); then
        # Keep counting while they are blocked.
        #
        # The counter used to freeze the moment the cooldown started, so
        # the "single huge burst" ban threshold could never be reached —
        # the count stopped at one over the limit no matter how many
        # thousands followed. Someone still hammering the bot after being
        # told to stop is exactly who this is for, so their messages keep
        # counting and the ban does trigger.
        cnt=$((cnt + 1))
        if (( cnt >= BOT_FLOOD_BAN_BURST )) \
           && ! _fm_reseller_lookup_by_chat "$chat_id" >/dev/null 2>&1 \
           && ! _fm_bot_is_banned "$chat_id"; then
            _fm_bot_ban "$chat_id" "إغراق تلقائي (${cnt} رسالة متواصلة)"
            _log_action "BOT_FLOOD_BAN" "$chat_id" "burst=${cnt}" "WARNING" "bot" 2>/dev/null
            send_telegram_msg "🚫 <b>حُظر مُغرِق تلقائيًا</b>%0Aالمعرّف: <a href=\"tg://user?id=${chat_id}\">${chat_id}</a> — <code>${chat_id}</code>%0Aواصل الإرسال بعد تجاهله: ${cnt} رسالة.%0A%0Aلن تصل رسائله البوت بعد الآن.%0Aلفكّ الحظر: <code>/unban ${chat_id}</code>" 2>/dev/null
        fi
        printf '%s:%s:%s:%s' "$win" "$cnt" "$blocked_until" "$strikes" > "$f" 2>/dev/null
        return 1
    fi
    if (( now - win >= BOT_FLOOD_WINDOW )); then
        win=$now; cnt=0
    fi
    cnt=$((cnt + 1))
    if (( cnt > BOT_FLOOD_MAX )); then
        blocked_until=$((now + BOT_FLOOD_COOLDOWN))
        # A strike is counted once per offence, not once per message —
        # the burst that follows is the same offence continuing.
        (( cnt == BOT_FLOOD_MAX + 1 )) && strikes=$((strikes + 1))
        printf '%s:%s:%s:%s' "$win" "$cnt" "$blocked_until" "$strikes" > "$f" 2>/dev/null

        # Ban outright: either a single burst far past any human pace, or
        # a repeat offender. A linked reseller is never auto-banned — that
        # is a business relationship, and the admin decides it by hand.
        if (( cnt >= BOT_FLOOD_BAN_BURST || strikes >= BOT_FLOOD_BAN_STRIKES )) \
           && ! _fm_reseller_lookup_by_chat "$chat_id" >/dev/null 2>&1; then
            if ! _fm_bot_is_banned "$chat_id"; then
                _fm_bot_ban "$chat_id" "إغراق تلقائي (${cnt} رسالة خلال ${BOT_FLOOD_WINDOW}ث)"
                _log_action "BOT_FLOOD_BAN" "$chat_id" "count=${cnt} strikes=${strikes}" "WARNING" "bot" 2>/dev/null
                send_telegram_msg "🚫 <b>حُظر مُغرِق تلقائيًا</b>%0Aالمعرّف: <a href=\"tg://user?id=${chat_id}\">${chat_id}</a> — <code>${chat_id}</code>%0Aأرسل ${cnt} رسالة خلال ${BOT_FLOOD_WINDOW} ثانية (المخالفة رقم ${strikes}).%0A%0Aلن تصل رسائله البوت بعد الآن.%0Aلفكّ الحظر: <code>/unban ${chat_id}</code>" 2>/dev/null
            fi
            return 1
        fi

        # Once per cooldown, not once per message — an alert that fires
        # thousands of times is itself a flood.
        _log_action "BOT_FLOOD" "$chat_id" "count=${cnt} window=${BOT_FLOOD_WINDOW}s strikes=${strikes}" "WARNING" "bot" 2>/dev/null
        send_telegram_msg "🛡️ <b>إغراق من مستخدم</b>%0Aالمعرّف: <a href=\"tg://user?id=${chat_id}\">${chat_id}</a> — <code>${chat_id}</code>%0Aأرسل ${cnt} رسالة خلال ${BOT_FLOOD_WINDOW} ثانية (المخالفة ${strikes} من ${BOT_FLOOD_BAN_STRIKES}).%0A%0Aتم تجاهل رسائله ${BOT_FLOOD_COOLDOWN} ثانية. عند المخالفة ${BOT_FLOOD_BAN_STRIKES} يُحظر تلقائيًا.%0Aللحظر الآن: <code>/ban ${chat_id} إغراق</code>" 2>/dev/null
        return 1
    fi
    printf '%s:%s:%s:%s' "$win" "$cnt" "$blocked_until" "$strikes" > "$f" 2>/dev/null
    return 0
}

# ── Stall watchdog: the bot must never be able to die quietly again ───
# Everything above makes a given failure less likely. This makes ANY
# failure — including one nobody has thought of yet — visible and
# self-healing, which is the only guarantee worth giving after a night
# like the one that produced it.
#
# The poll loop stamps a heartbeat every time round. A separate tiny
# timer reads that stamp; if the service claims to be active but has not
# ticked in BOT_WATCHDOG_MAX seconds, it is wedged. The admin is told, in
# words, and the service is restarted. Nothing here depends on the bot
# process being healthy enough to notice its own problem — that is the
# whole point.
BOT_HEARTBEAT_FILE="${BOT_HEARTBEAT_FILE:-/run/dahoom-bot.heartbeat}"
BOT_WATCHDOG_MAX="${BOT_WATCHDOG_MAX:-300}"

_fm_bot_heartbeat_touch() {
    local f="${BOT_HEARTBEAT_FILE}"
    local d; d=$(dirname "$f")
    [[ -d "$d" && -w "$d" ]] || { f="/tmp/dahoom-bot.heartbeat"; }
    date +%s > "$f" 2>/dev/null || true
}

_fm_bot_watchdog_check() {
    systemctl is-active --quiet firewallfalcon-telegram-bot 2>/dev/null || return 0
    local f="${BOT_HEARTBEAT_FILE}"
    [[ -f "$f" ]] || f="/tmp/dahoom-bot.heartbeat"
    local hb=0 now
    [[ -f "$f" ]] && read -r hb < "$f" 2>/dev/null
    [[ "$hb" =~ ^[0-9]+$ ]] || hb=0
    now=$(date +%s 2>/dev/null) || return 0
    # No stamp yet (just installed/restarted): give it one full window
    # before judging it, and leave a stamp so the next run can.
    if (( hb == 0 )); then
        _fm_bot_heartbeat_touch
        return 0
    fi
    local age=$(( now - hb ))
    (( age > BOT_WATCHDOG_MAX )) || return 0

    _log_action "BOT_WATCHDOG_RESTART" "telegram-bot" "stalled=${age}s" "ERROR" "bot" 2>/dev/null
    send_telegram_msg "🩺 <b>الحارس أعاد تشغيل البوت</b>%0Aتوقّف عن الاستجابة ${age} ثانية وهو يبدو نشطًا.%0A%0Aأُعيد تشغيله تلقائيًا الآن — لا حاجة لأي إجراء منك.%0Aإن تكرّر هذا كثيرًا فأرسل لي: <code>journalctl -u firewallfalcon-telegram-bot -n 80</code>" 2>/dev/null
    _fm_bot_heartbeat_touch
    systemctl restart firewallfalcon-telegram-bot >/dev/null 2>&1 || true
    return 0
}

_fm_setup_bot_watchdog_timer() {
    local svc="/etc/systemd/system/firewallfalcon-bot-watchdog.service"
    local tmr="/etc/systemd/system/firewallfalcon-bot-watchdog.timer"
    cat > "$svc" << EOF
[Unit]
Description=DAHOOM bot stall watchdog

[Service]
Type=oneshot
ExecStart=/bin/bash /usr/local/bin/dahoom _run_bot_watchdog
EOF
    cat > "$tmr" << 'EOF'
[Unit]
Description=DAHOOM bot stall watchdog (every 2 minutes)

[Timer]
OnBootSec=3min
OnUnitActiveSec=2min
AccuracySec=15s

[Install]
WantedBy=timers.target
EOF
    systemctl daemon-reload &>/dev/null || true
    systemctl enable --now firewallfalcon-bot-watchdog.timer &>/dev/null || true
}

# Telegram refusing to hand over updates is the one failure that stops
# the bot dead while every other sign says it is fine. It must never be
# silent.
#
# But "never silent" is not "shout at the first hiccup". The first
# version of this alerted on ANY non-200, and curl reports 000 for a
# request that never got a reply at all — a dropped packet, a NAT that
# cut the held long-poll connection, a two-second DNS stumble. Those
# happen on any VPS, they heal on the very next iteration one second
# later, and nothing is actually wrong. Alerting on them told the owner
# "no customer message will arrive" while customer messages were
# arriving perfectly well: a false alarm that trains you to ignore the
# real one.
#
# So the alert now needs the failure to PERSIST. Consecutive failures
# are counted and the counter is cleared by any successful poll; the
# admin is told only once the run is long enough to mean something.
# Errors that cannot heal on their own (401 bad token, 409 second
# poller) still fire immediately — waiting on those helps nobody.
BOT_POLL_FAIL_FILE="${BOT_POLL_FAIL_FILE:-/etc/firewallfalcon/.poll_fail_count}"

_fm_bot_poll_fail_reset() {
    local f="${BOT_POLL_FAIL_FILE:-/etc/firewallfalcon/.poll_fail_count}"
    # Only touch the disk when there is actually something to clear —
    # this runs after every healthy poll, several times a minute.
    [[ -f "$f" ]] || return 0
    rm -f "$f" 2>/dev/null || true
    return 0
}

_fm_bot_poll_fail_bump() {
    local f="${BOT_POLL_FAIL_FILE:-/etc/firewallfalcon/.poll_fail_count}"
    local n=0
    [[ -f "$f" ]] && read -r n < "$f" 2>/dev/null
    [[ "$n" =~ ^[0-9]+$ ]] || n=0
    n=$(( n + 1 ))
    mkdir -p "$(dirname "$f")" 2>/dev/null
    printf '%s' "$n" > "$f" 2>/dev/null
    printf '%s' "$n"
}

_fm_bot_poll_error_notice() {
    local code="$1" body="$2"
    local fails; fails=$(_fm_bot_poll_fail_bump)
    [[ "$fails" =~ ^[0-9]+$ ]] || fails=1
    _log_action "BOT_POLL_HTTP_ERROR" "getUpdates" "code=${code} consecutive=${fails}" "ERROR" "bot" 2>/dev/null

    # Consecutive failures required before the owner is disturbed.
    # 000/no-reply is the noisy one: a single blip is meaningless, five
    # in a row is a real outage (each attempt holds the line for ~25s,
    # so five is minutes of genuinely not reaching Telegram).
    local need="${BOT_POLL_FAIL_NEED:-5}"
    case "$code" in
        401|409) need=1 ;;
        429|5??) need=3 ;;
    esac
    (( fails >= need )) || return 0

    local stamp="${BOT_POLL_ERR_STAMP:-/etc/firewallfalcon/.poll_err_stamp}"
    local now; now=$(date +%s 2>/dev/null) || now=0
    local last=0
    [[ -f "$stamp" ]] && read -r last < "$stamp" 2>/dev/null
    [[ "$last" =~ ^[0-9]+$ ]] || last=0
    # Throttled so a sustained outage does not itself become a flood.
    (( now - last < 600 )) && return 0
    mkdir -p "$(dirname "$stamp")" 2>/dev/null
    printf '%s' "$now" > "$stamp" 2>/dev/null

    local what hint=""
    case "$code" in
        000|"لا رد")
            what="تعذّر الاتصال بخوادم تيليجرام — لا رد إطلاقًا."
            hint="%0A%0A(السبب من جهة الشبكة أو الجدار الناري أو DNS على هذا السيرفر، لا من تيليجرام.)" ;;
        409)
            what="رد تيليجرام: <code>409</code>"
            hint="%0A%0A(409 = نسخة أخرى من البوت تسحب التحديثات في الوقت نفسه، أو webhook مضبوط.)" ;;
        429)
            what="رد تيليجرام: <code>429</code>"
            hint="%0A%0A(429 = تيليجرام يُقيّد البوت مؤقتًا لكثرة الطلبات. سيعود تلقائيًا.)" ;;
        401)
            what="رد تيليجرام: <code>401</code>"
            hint="%0A%0A(401 = رمز البوت غير صالح أو غُيّر.)" ;;
        *)
            what="رد تيليجرام: <code>${code}</code>" ;;
    esac
    local snippet="${body:0:200}"
    send_telegram_msg "⚠️ <b>البوت لا يستطيع سحب الرسائل</b>%0A${what}${hint}%0A%0Aفشلت <b>${fails}</b> محاولة متتالية.%0A%0A<code>$(_fm_html_escape "$snippet")</code>%0A%0A⛔ لن تصل أي رسالة من العملاء حتى يُحل هذا." 2>/dev/null
}

# ── One poller at a time, ever ─────────────────────────────────────────
# The bot is polled from TWO places: the long-poll systemd service, and a
# once-a-minute cron entry kept as a fallback for boxes without systemd.
# Nothing stopped them running together, and nothing stopped a cron run
# from starting while the previous one was still going. Under load each
# run takes longer than the minute before the next is launched, so they
# pile up — a live server was found with 112 of them at once and a load
# average of 88 on two cores. The box then thrashes so badly that the bot
# cannot answer anyone, which looks exactly like the bot "hanging" while
# every component is individually healthy.
#
# The lock makes the pile-up impossible: whoever holds it polls, everyone
# else exits immediately and cheaply. It fails OPEN — if flock is missing
# or the lock file cannot be created, the work still runs, because losing
# polling entirely is far worse than polling twice.
_fm_run_locked() {
    local name="$1"; shift
    command -v flock >/dev/null 2>&1 || { "$@"; return $?; }
    local dir="/run" lock
    [[ -d "$dir" && -w "$dir" ]] || dir="/tmp"
    lock="${dir}/dahoom-${name}.lock"
    # The redirection is attached to a SUBSHELL, never to `exec`.
    #
    # The first version opened the lock with `exec {fd}>"$lock" 2>/dev/null`.
    # `exec` with no command applies its redirections to the CURRENT shell,
    # permanently — so that 2>/dev/null did not quietly discard one error,
    # it sent the whole bot's stderr to /dev/null for the rest of its life.
    # Every warning, every failure, every `bash -x` trace: gone. The bot
    # went blind, and so did anyone trying to find out why it was
    # misbehaving; journalctl had nothing to show because there was
    # nothing left to log.
    #
    # `( flock -n 9 || exit 0; "$@" ) 9>"$lock"` keeps the file descriptor
    # inside the subshell, where it dies with it. Nothing can leak into
    # the parent — not the fd, not the redirection, not stderr.
    (
        flock -n 9 || exit 0
        "$@"
    ) 9>"$lock"
}

# Returns 0 = serve this chat, 1 = drop the message.
#
# FAILS OPEN by design: a guard whose job is to discard customer traffic
# must never discard it because the guard itself is missing or errored —
# that turns a protection into a silent, total outage. Only an explicit
# "you are flooding" (exit 1 from a working check) drops anything.
_fm_bot_flood_allows() {
    local who="$1" now="${2:-0}" rc
    [[ -n "$who" ]] || return 0
    declare -F _fm_bot_flood_check >/dev/null 2>&1 || return 0
    _fm_bot_flood_check "$who" "$now" && return 0
    rc=$?
    (( rc == 1 )) && return 1
    return 0
}

_fm_telegram_poll_updates() {
    [[ -f "$TELEGRAM_CONF" ]] || return 0
    local BOT_TOKEN CHAT_ID NOTIFY_ENABLED
    source "$TELEGRAM_CONF" 2>/dev/null
    [[ -n "$BOT_TOKEN" && -n "$CHAT_ID" ]] || return 0
    command -v jq >/dev/null 2>&1 || return 0

    # Housekeeping rides along with the poll rather than needing a cron
    # entry of its own, so it works the same whether the bot runs as the
    # long-lived service or the once-a-minute fallback. Its own stamp
    # keeps it to one run a day.
    _fm_bot_expired_sweep_if_due

    # Optional long-poll timeout in seconds (Telegram holds the connection
    # open until an update arrives or this elapses, instead of returning
    # instantly). The once-a-minute cron fallback calls this with no
    # argument (timeout=0, instant return); the persistent systemd service
    # (see _fm_telegram_bot_service_loop) calls it with ~25s so real
    # messages are seen in near real-time instead of up to 60s late.
    local poll_timeout="${1:-0}"
    [[ "$poll_timeout" =~ ^[0-9]+$ ]] || poll_timeout=0
    local curl_max_time=$((poll_timeout + 10))

    local offset_file="/etc/firewallfalcon/.telegram_update_offset"
    local offset=0
    [[ -f "$offset_file" ]] && offset=$(cat "$offset_file" 2>/dev/null)
    [[ "$offset" =~ ^[0-9]+$ ]] || offset=0

    local resp
    # Ask Telegram for ONLY the two kinds this bot acts on. Without
    # allowed_updates it also ships channel posts, edits, member
    # join/leave events and more — every one of them a full update this
    # loop has to fetch, parse and step over, for nothing.
    #
    # This used to be `curl -fsS`, whose -f turns ANY HTTP error into an
    # empty body and a non-zero exit — after which the next line returned
    # 0 and the whole poll ended in complete silence. So when Telegram
    # answered 409 (another getUpdates in flight) or 429 (rate limited),
    # the bot simply stopped serving anyone and said nothing at all: no
    # log line, no alert, offset frozen, service "active", CPU idle. The
    # single hardest failure to diagnose, produced by three characters.
    #
    # Now the status code is read explicitly and anything but 200 is
    # reported — with Telegram's own words for it.
    local http_code
    # 2>&1 on purpose: with -sS curl prints nothing to stderr on success,
    # but on failure it prints the actual reason ("Could not resolve
    # host", "Operation timed out", "Connection reset"). Without it the
    # alert can only say 000, which tells nobody anything.
    resp=$(curl -sS --max-time "$curl_max_time" -w '\n%{http_code}' \
        "https://api.telegram.org/bot${BOT_TOKEN}/getUpdates?offset=${offset}&timeout=${poll_timeout}&allowed_updates=%5B%22message%22%2C%22callback_query%22%5D" 2>&1)
    http_code="${resp##*$'\n'}"
    resp="${resp%$'\n'*}"
    if [[ "$http_code" != "200" ]]; then
        _fm_bot_poll_error_notice "${http_code:-لا رد}" "$resp"
        return 0
    fi
    # A healthy poll clears the streak, so only a SUSTAINED run of
    # failures can ever reach the alert threshold.
    _fm_bot_poll_fail_reset
    [[ -n "$resp" ]] || return 0

    # ONE jq for the whole batch, not thirteen per update.
    #
    # Every field used to be pulled with its own `echo "$resp" | jq ...`,
    # and each of those re-parsed the ENTIRE response from the start. So
    # a batch of N updates paid 13*N full parses of an N-update document
    # — quadratic in the batch size, in spawned processes AND in parsing.
    # A hundred queued messages meant 1300 jq processes before a single
    # customer had been answered, which on a small VPS is minutes of pure
    # overhead. Under real load the queue then grows faster than it
    # drains and the bot never catches up: it looks frozen, briefly
    # answers, and falls behind again.
    #
    # jq emits @tsv, which escapes \t \n \r and backslash inside the
    # values; `printf -v` with %b puts them back with no subprocess at
    # all. The tab SEPARATORS are then turned into 0x1f, because bash
    # treats tab as IFS whitespace and collapses runs of it — so an
    # empty field (a message with no caption, say) would silently
    # vanish and shift every later field left, handing the flow one
    # value where it expected another. 0x1f is not whitespace, so
    # empty fields survive. No real tab can be mistaken for a
    # separator: @tsv already turned those into the two characters \t.
    local -a _rows=()
    mapfile -t _rows < <(printf '%s' "$resp" | jq -r '
        .result[] | [
            (.update_id // "" | tostring),
            (.message.chat.id // "" | tostring),
            (.message.text // ""),
            (.message.message_id // "" | tostring),
            (.message.document.file_id // ""),
            (.message.document.file_name // ""),
            (.message.photo[-1].file_id // ""),
            (.message.caption // ""),
            (.callback_query.id // ""),
            (.callback_query.message.chat.id // "" | tostring),
            (.callback_query.data // ""),
            (.callback_query.message.message_id // "" | tostring),
            (.message.date // "" | tostring),
            (.message.chat.type // .callback_query.message.chat.type // "")
        ] | @tsv' 2>/dev/null | tr '\t' '\037')
    local count=${#_rows[@]}

    # A speed-up must never be able to silence the bot.
    #
    # If that one jq program ever fails — an older jq, a payload shape it
    # dislikes — it prints nothing, count is 0, and the bot would go on
    # polling forever while quietly handling no one. That failure mode is
    # worse than the slowness it replaced, so the row count is checked
    # against what the response actually holds, and any mismatch falls
    # back to the original field-by-field parsing: slower, but the bot
    # keeps serving customers while the admin is told what happened.
    local expected; expected=$(printf '%s' "$resp" | jq -r '.result | length' 2>/dev/null)
    [[ "$expected" =~ ^[0-9]+$ ]] || expected="$count"
    if (( count != expected )); then
        _fm_bot_parse_fallback_notice "$expected" "$count"
        _rows=()
        local _j
        for ((_j=0; _j<expected; _j++)); do
            _rows+=("$(printf '%s' "$resp" | jq -r --argjson i "$_j" '
                .result[$i] | [
                    (.update_id // "" | tostring),(.message.chat.id // "" | tostring),
                    (.message.text // ""),(.message.message_id // "" | tostring),
                    (.message.document.file_id // ""),(.message.document.file_name // ""),
                    (.message.photo[-1].file_id // ""),(.message.caption // ""),
                    (.callback_query.id // ""),(.callback_query.message.chat.id // "" | tostring),
                    (.callback_query.data // ""),(.callback_query.message.message_id // "" | tostring),
                    (.message.date // "" | tostring),
                    (.message.chat.type // .callback_query.message.chat.type // "")
                ] | @tsv' 2>/dev/null | tr '\t' '\037')")
        done
        count=${#_rows[@]}
    fi
    (( count > 0 )) || return 0

    local i update_id chat_id text doc_file_id doc_file_name photo_file_id caption msg_id max_update_id=-1
    local _text_e _caption_e _cbdata_e _cb_id _cb_chat _cb_msg _msg_date _chat_type
    local _admin_chat="${CHAT_ID:-}" _skipped_group=0
    local _now_ts; _now_ts=$(date +%s 2>/dev/null) || _now_ts=0
    local _stale_max="${BOT_STALE_UPDATE_SECS:-600}"
    local _skipped_stale=0 _skipped_flood=0
    # A backlog is Telegram handing over a big batch at once. Below that
    # the bot is keeping up and has no reason to discard anything.
    local _stale_active=0
    (( count >= ${BOT_STALE_MIN_BATCH:-25} )) && _stale_active=1
    for ((i=0; i<count; i++)); do
        IFS=$'\037' read -r update_id chat_id _text_e msg_id doc_file_id doc_file_name \
            photo_file_id _caption_e _cb_id _cb_chat _cbdata_e _cb_msg _msg_date _chat_type <<< "${_rows[$i]}"
        printf -v text '%b' "$_text_e"
        printf -v caption '%b' "$_caption_e"

        # This update is marked as consumed BEFORE it is handled, not
        # after the whole batch.
        #
        # The offset used to be written once, after the loop. That turned
        # any single update that hung or died into a permanent outage:
        # the offset never advanced, so Telegram redelivered the exact
        # same batch on the next poll — and again after a restart, and
        # after a reboot. The bot looked completely dead, restarting it
        # changed nothing, and nothing in the logs said which message was
        # doing it. Recovery meant clearing the offset file by hand.
        #
        # Writing it first inverts the failure: one bad update is skipped
        # and the bot keeps serving everyone else. Losing a single
        # message is a far smaller harm than wedging the whole bot on it
        # forever — and it can no longer take the service down with it.
        if [[ "$update_id" =~ ^[0-9]+$ ]]; then
            (( update_id > max_update_id )) && max_update_id=$update_id
            echo "$((update_id + 1))" > "$offset_file" 2>/dev/null
        fi

        # Groups and channels are not customers.
        #
        # The bot never looked at chat.type, so once it was added to a
        # group or channel EVERY message posted there arrived as an
        # update and was run through the full customer flow — pending
        # state, ban checks, card rendering, the lot. A busy community of
        # a few hundred people is then a firehose that one sequential bash
        # loop can never drain, and the customers messaging it privately
        # simply never get a turn. From the outside the bot looks frozen
        # while its offset keeps advancing, because it IS working — on
        # the wrong traffic entirely.
        #
        # A sales bot serves one customer at a time in a private chat.
        # The admin's own configured chat is honoured whatever its type,
        # since that one may legitimately be a group.
        if [[ -n "$_chat_type" && "$_chat_type" != "private" ]] \
           && [[ -z "$_admin_chat" || ( "$chat_id" != "$_admin_chat" && "$_cb_chat" != "$_admin_chat" ) ]]; then
            _skipped_group=$((_skipped_group + 1))
            continue
        fi

        # Stale updates are skipped ONLY while draining a real backlog.
        #
        # After a stall the queue can hold thousands of messages whose
        # senders left long ago; working through them in order keeps
        # everyone waiting NOW behind people who are no longer there.
        # That is worth skipping — but only then.
        #
        # The first version of this compared every message against the
        # server clock, unconditionally. That made the bot's ability to
        # answer anyone depend on the clock being right: a host running
        # ten minutes fast makes EVERY message look ancient, so all of
        # them are dropped while the offset marches on and every health
        # check says the bot is fine. A silent, total outage caused by a
        # clock. So now: nothing is skipped unless Telegram is actually
        # handing over a backlog (a large batch), and a timestamp in the
        # future — the signature of a skewed clock — never counts as old.
        # In normal traffic no message can be dropped here at all.
        if (( _stale_active )) && [[ "$_msg_date" =~ ^[0-9]+$ ]] && (( _now_ts > 0 )) \
           && (( _msg_date <= _now_ts )) \
           && (( _now_ts - _msg_date > _stale_max )); then
            _skipped_stale=$((_skipped_stale + 1))
            continue
        fi

        # A banned chat is dropped here, at the very top.
        #
        # The ban was already enforced deeper inside the flow, but only
        # AFTER the message had been parsed, its state read and its card
        # prepared. So a banned spammer still cost the bot real work on
        # every single message they sent — which is exactly the person
        # most likely to keep sending thousands. Now they cost one file
        # check and nothing else.
        if [[ -n "$chat_id" ]] && [[ "$chat_id" != "$_admin_chat" ]] \
           && _fm_bot_is_banned "$chat_id" 2>/dev/null; then
            _skipped_flood=$((_skipped_flood + 1))
            continue
        fi

        # Flood guard BEFORE any work: no state read, no card, no
        # Telegram call, no node call for a message being dropped.
        #
        # It FAILS OPEN on purpose. A guard whose job is to discard
        # customer traffic must never discard it because the guard itself
        # is missing or broken — that turns a protection into a total
        # outage, silently. Only an explicit "no" from a working check
        # drops a message; anything else serves the customer.
        if declare -F _fm_bot_flood_allows >/dev/null 2>&1 \
           && ! _fm_bot_flood_allows "$chat_id" "$_now_ts"; then
            _skipped_flood=$((_skipped_flood + 1))
            continue
        fi
        if declare -F _fm_bot_flood_allows >/dev/null 2>&1 \
           && ! _fm_bot_flood_allows "$_cb_chat" "$_now_ts"; then
            _skipped_flood=$((_skipped_flood + 1))
            continue
        fi

        # An inline button tap arrives as a callback_query, never as a
        # message, so it is picked off here before any of the message
        # handling below. Resolving it back to the caption the customer
        # actually saw and feeding that to the ordinary text handler is
        # deliberate: bans, pending state, back navigation and every
        # future step then behave identically whichever keyboard was
        # used, with no second copy of the flow logic to keep in sync.
        local cb_id="$_cb_id"
        if [[ -n "$cb_id" ]]; then
            local cb_chat cb_data cb_text cb_msg
            cb_chat="$_cb_chat"
            printf -v cb_data '%b' "$_cbdata_e"
            # Which message carried the button they pressed.
            cb_msg="$_cb_msg"
            # Clears the spinner Telegram shows on the tapped button; the
            # tap's real answer is the message the handler sends next.
            curl -s --max-time 5 --connect-timeout 3 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/answerCallbackQuery" \
                -d "callback_query_id=${cb_id}" &>/dev/null &
            # In customer mode the admin's taps are a customer's taps —
            # otherwise the keyboard he was just handed would do nothing.
            if [[ -n "$cb_chat" && "$cb_chat" == "$CHAT_ID" ]] && ! _fm_bot_admin_custmode_is_on; then
                _fm_admin_callback_dispatch "$cb_data" || true
            elif [[ -n "$cb_chat" ]]; then
                # Before anything is decided: make sure the answer will
                # land where the tap came from (see _fm_bot_card_focus).
                _fm_bot_card_focus "$cb_chat" "$cb_msg"
                # "Send my file again" names an account rather than a
                # menu option, so it is handled directly; the account's
                # owner is verified inside before anything is rebuilt.
                if [[ "$cb_data" == rs:* ]]; then
                    _fm_bot_resend_file "$cb_chat" "${cb_data#rs:}" || true
                else
                    local cb_rc
                    cb_text=$(_fm_bot_callback_resolve "$cb_chat" "$cb_data"); cb_rc=$?
                    if [[ $cb_rc -eq 2 ]]; then
                        _fm_bot_handle_stale_tap "$cb_chat"
                    elif [[ $cb_rc -eq 0 && -n "$cb_text" ]]; then
                        _fm_bot_customer_handle_command "$cb_chat" "$cb_text" "" ""
                    fi
                fi
            fi
            continue
        fi

        # Admin sends a document with caption "/addfile AppName FileType"
        # to add/replace one connection-app config file. Handled here,
        # before the text-only gate below, since a document message often
        # carries no .text at all (only .caption). The file type is the
        # LAST word of the caption and the app name is everything before
        # it — app names commonly contain spaces ("HTTP Custom", or an
        # Arabic phrase), and capturing both as single space-delimited
        # words silently dropped the actual type and mangled the app
        # name into just its first word.
        if [[ -n "$chat_id" && "$chat_id" == "$CHAT_ID" && -n "$doc_file_id" \
              && "$caption" =~ ^/addfile[[:space:]]+(.+)[[:space:]]+([^[:space:]]+)$ ]]; then
            local af_app="${BASH_REMATCH[1]}" af_type="${BASH_REMATCH[2]}"
            local tmp_dl; tmp_dl=$(mktemp)
            if _fm_telegram_download_file "$BOT_TOKEN" "$doc_file_id" "$tmp_dl"; then
                local added; added=$(_fm_bot_appfile_add "$af_app" "$af_type" "$tmp_dl" "$doc_file_name")
                if [[ -n "$added" ]]; then
                    send_telegram_msg "✅ تمت إضافة الملف: <b>${af_app}</b> — <b>${af_type}</b> (${doc_file_name:-بدون اسم})"
                else
                    send_telegram_msg "❌ تعذّر حفظ الملف — تحقق من اسم التطبيق ونوع الملف."
                fi
            else
                send_telegram_msg "❌ فشل تنزيل الملف من تيليجرام."
            fi
            rm -f "$tmp_dl"
            continue
        fi

        # Admin sends a photo with caption "/addguide AppName" to add one
        # more "where's my HWID" screenshot for that app. Repeat it to
        # build up the whole explanation, image by image.
        if [[ -n "$chat_id" && "$chat_id" == "$CHAT_ID" && -n "$photo_file_id" \
              && "$caption" =~ ^/addguide[[:space:]]+(.+)$ ]]; then
            # Everything after the command is the app name: app names may
            # contain spaces ("HTTP Custom"), and stopping at the first one
            # filed the image under a name no app actually had, so it never
            # reached a single customer.
            local ag_app="${BASH_REMATCH[1]}"
            local tmp_dl; tmp_dl=$(mktemp)
            if _fm_telegram_download_file "$BOT_TOKEN" "$photo_file_id" "$tmp_dl"; then
                local added ag_rc
                added=$(_fm_bot_hwid_guide_add "$ag_app" "$tmp_dl"); ag_rc=$?
                if [[ $ag_rc -eq 2 ]]; then
                    send_telegram_msg "❌ هذا التطبيق وصل للحد الأقصى (${BOT_HWID_GUIDE_MAX} صور). احذف واحدة أولًا: <code>/delguide AppName 1</code>"
                elif [[ -n "$added" ]]; then
                    send_telegram_msg "✅ أُضيفت صورة الشرح رقم <b>${added#*:}</b> لتطبيق: <b>${added%%:*}</b>.%0Aأرسل صورة أخرى بنفس التعليق لإضافة المزيد."
                else
                    send_telegram_msg "❌ تعذّر حفظ الصورة — تحقق من اسم التطبيق."
                fi
            else
                send_telegram_msg "❌ فشل تنزيل الصورة من تيليجرام."
            fi
            rm -f "$tmp_dl"
            continue
        fi

        # Admin sends a photo with caption "/addfileguide AppName" to add
        # one more "how do I add this file inside the app" screenshot —
        # sent to the customer right after the config file itself.
        if [[ -n "$chat_id" && "$chat_id" == "$CHAT_ID" && -n "$photo_file_id" \
              && "$caption" =~ ^/addfileguide[[:space:]]+(.+)$ ]]; then
            local afg_app="${BASH_REMATCH[1]}"
            local tmp_dl; tmp_dl=$(mktemp)
            if _fm_telegram_download_file "$BOT_TOKEN" "$photo_file_id" "$tmp_dl"; then
                local added afg_rc
                added=$(_fm_bot_file_guide_add "$afg_app" "$tmp_dl"); afg_rc=$?
                if [[ $afg_rc -eq 2 ]]; then
                    send_telegram_msg "❌ هذا التطبيق وصل للحد الأقصى (${BOT_FILE_GUIDE_MAX} صور). احذف واحدة أولًا: <code>/delfileguide AppName 1</code>"
                elif [[ -n "$added" ]]; then
                    send_telegram_msg "✅ أُضيفت صورة شرح رقم <b>${added#*:}</b> لتطبيق: <b>${added%%:*}</b>.%0Aأرسل صورة أخرى بنفس التعليق لإضافة المزيد."
                else
                    send_telegram_msg "❌ تعذّر حفظ الصورة — تحقق من اسم التطبيق."
                fi
            else
                send_telegram_msg "❌ فشل تنزيل الصورة من تيليجرام."
            fi
            rm -f "$tmp_dl"
            continue
        fi

        # A customer's payment receipt arrives as a photo or a document with
        # no .text at all, so an attachment counts as content too — but only
        # for the sales bot below. Admin and reseller commands are text-only.
        local attach_kind=""
        [[ -n "$photo_file_id" ]] && attach_kind="photo"
        [[ -n "$doc_file_id" ]] && attach_kind="document"
        [[ -n "$chat_id" ]] || continue
        [[ -n "$text" || -n "$attach_kind" ]] || continue

        if [[ "$chat_id" == "$CHAT_ID" ]]; then
            # /customer hands the admin the customer keyboard in his own
            # chat (every limit lifted — see _fm_bot_is_admin_chat);
            # /admin gives the command surface back. While the mode is
            # on, only that one word is intercepted, so a half-finished
            # flow can always be abandoned.
            if [[ "$text" == "/customer" || "$text" == "/عميل" ]]; then
                _fm_bot_admin_custmode_on
                send_telegram_msg "🧑‍💼 <b>وضع العميل مُفعَّل</b>%0A%0Aالبوت الآن يتعامل معك كعميل، وكل الحدود مرفوعة: الرصيد ومرات التجربة والتجديد وتغيير الجهاز بلا حد.%0Aأنشئ الحساب للمشترك ثم أرسل له الملف.%0A%0Aللعودة لأوامر الأدمن: /admin"
                _fm_bot_send_main_menu "$chat_id"
                continue
            fi
            if _fm_bot_admin_custmode_is_on; then
                if [[ "$text" == "/admin" || "$text" == "/ادمن" ]]; then
                    _fm_bot_admin_custmode_off
                    _fm_bot_pending_clear "$chat_id"
                    send_telegram_msg "🛠 <b>عدت لوضع الأدمن.</b>%0Aأرسل /help لعرض الأوامر."
                    continue
                fi
                _fm_bot_customer_handle_command "$chat_id" "$text" "$msg_id" "$attach_kind"
                continue
            fi
            # A reply target armed by the "رد" button turns the admin's
            # next plain message into that customer's reply. Anything
            # starting with "/" is still a command, so the admin is never
            # trapped in reply mode — /cancel_reply gets out explicitly.
            if [[ -n "$text" && "$text" != /* ]] && _fm_bot_admin_bcast_wait_is_on; then
                _fm_bot_admin_bcast_wait_clear
                _fm_bot_broadcast_preview "$text"
                continue
            fi
            if [[ -n "$text" && "$text" != /* ]]; then
                local rp_to
                if rp_to=$(_fm_bot_admin_reply_target_get); then
                    if _fm_bot_admin_reply_deliver "$rp_to" "$text"; then
                        _fm_bot_admin_reply_target_clear
                    else
                        send_telegram_msg "❌ تعذّر إيصال الرد إلى <code>${rp_to}</code>."
                    fi
                    continue
                fi
            fi
            [[ -n "$text" ]] && _fm_telegram_handle_command "$text"
            continue
        fi

        # Not the admin's chat. A /link code claims a reseller identity;
        # once linked, a reseller's own read-only commands take over.
        # Anyone else — any stranger who found the bot — hits the sales
        # bot (trial/subscribe/wallet/appeal; see
        # _fm_bot_customer_handle_command), which itself checks the ban
        # list first.
        if [[ "$text" =~ ^/link[[:space:]]+([0-9]{6})$ ]]; then
            local bound_user; bound_user=$(_fm_reseller_consume_link_code "${BASH_REMATCH[1]}" "$chat_id")
            if [[ -n "$bound_user" ]]; then
                send_telegram_msg_to "$chat_id" "✅ Linked to reseller account: <b>${bound_user}</b>. Send /help to see what you can do."
            else
                send_telegram_msg_to "$chat_id" "❌ Invalid or expired code."
            fi
            continue
        fi

        # Whatever the customer just sent is now the last thing in the
        # chat, so their screen has to move down to meet it.
        [[ -n "$text" || -n "$attach_kind" ]] && _fm_bot_card_mark_dirty "$chat_id"

        local linked_reseller; linked_reseller=$(_fm_reseller_lookup_by_chat "$chat_id")
        if [[ -n "$linked_reseller" ]]; then
            [[ -n "$text" ]] && _fm_reseller_handle_command "$chat_id" "$linked_reseller" "$text"
        else
            _fm_bot_customer_handle_command "$chat_id" "$text" "$msg_id" "$attach_kind"
        fi
    done

    if (( _skipped_stale > 0 || _skipped_flood > 0 || _skipped_group > 0 )); then
        _log_action "BOT_UPDATES_SKIPPED" "poll" "stale=${_skipped_stale} flood=${_skipped_flood} group=${_skipped_group}" "INFO" "bot" 2>/dev/null
    fi

    # Safety net only: each update above already advanced the offset as
    # it was picked up, so this just guarantees the file is not left
    # behind if the loop exited early for any other reason.
    (( max_update_id >= 0 )) && echo "$((max_update_id + 1))" > "$offset_file" 2>/dev/null
}

# Persistent long-poll loop, run as a systemd service (see
# setup_telegram_bot_service) so customer/admin messages are handled in
# near real-time instead of waiting for the once-a-minute cron tick.
# getUpdates blocks server-side for up to ~25s per call, so this loop is
# effectively an always-listening connection, not a busy poll.
_fm_telegram_bot_service_loop() {
    echo "DAHOOM Telegram bot service started (long-poll)."
    while true; do
        if [[ ! -f "$TELEGRAM_CONF" ]]; then
            sleep 10
            continue
        fi
        _fm_bot_heartbeat_touch
        _fm_run_locked telegram-poll _fm_telegram_poll_updates 25
        # Tiny guard so a persistent error (bad token, no network, no jq)
        # can't spin this into a hot loop hammering the Telegram API.
        sleep 1
    done
}

telegram_bot_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "TELEGRAM BOT & BACKUP" "$C_TITLE"
        echo
        local token="" chat="" enabled="false" backup_schedule="off" sales_enabled=""
        if [ -f "$TELEGRAM_CONF" ]; then
            source "$TELEGRAM_CONF" 2>/dev/null
            token="${BOT_TOKEN:-Not Configured}"
            chat="${CHAT_ID:-Not Configured}"
            enabled="${NOTIFY_ENABLED:-false}"
            backup_schedule="${BACKUP_SCHEDULE:-off}"
            # A server that already had Telegram configured before this
            # toggle existed was already relying on the sales-bot admin
            # tabs being visible in the web panel — an unset flag here
            # defaults to enabled instead of silently hiding a feature
            # someone is actively using. Only a server with no Telegram
            # config at all (a fresh install) starts hidden — see
            # sales_bot_enabled() in panel.py for the matching read.
            sales_enabled="${SALES_BOT_ENABLED:-true}"
        else
            sales_enabled="false"
        fi

        local status_str="${C_RED}Disabled${C_RESET}"
        [[ "$enabled" == "true" ]] && status_str="${C_GREEN}Active${C_RESET}"
        local sched_str="${C_YELLOW}Off${C_RESET}"
        case "$backup_schedule" in
            daily) sched_str="${C_GREEN}Daily (03:00)${C_RESET}" ;;
            weekly) sched_str="${C_GREEN}Weekly (Sunday 03:00)${C_RESET}" ;;
        esac
        local sales_status_str="${C_RED}Disabled${C_RESET}"
        [[ "$sales_enabled" == "true" ]] && sales_status_str="${C_GREEN}Enabled${C_RESET}"
        # Live truth, not a stored flag — this is the actual bot process
        # (long-poll service + the crontab job that drives it), separate
        # from NOTIFY_ENABLED above (which only mutes proactive *alerts*,
        # never stops the bot from answering customers/admin commands —
        # see send_telegram_msg_to's own comment on that distinction).
        local service_running_str="${C_RED}Stopped${C_RESET}"
        if [[ -f "$TELEGRAM_CONF" ]] && grep -q "^BOT_TOKEN=" "$TELEGRAM_CONF" 2>/dev/null \
           && systemctl is-active --quiet firewallfalcon-telegram-bot 2>/dev/null; then
            service_running_str="${C_GREEN}Running${C_RESET}"
        fi

        echo -e "  ${C_CYAN}Bot Status:${C_RESET}      $status_str"
        echo -e "  ${C_CYAN}Chat ID   :${C_RESET}      ${C_YELLOW}${chat}${C_RESET}"
        echo -e "  ${C_CYAN}Auto-Backup:${C_RESET}     $sched_str"
        echo -e "  ${C_CYAN}Sales Bot Panel:${C_RESET} $sales_status_str"
        echo -e "  ${C_CYAN}Bot Service:${C_RESET}     $service_running_str"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Configure Bot Token & Chat ID"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Send Test Message"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Backup & Send to Telegram Now"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Toggle Notifications (On/Off)"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[5]" "Schedule Automatic Backup"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[6]" "Link a Reseller to Telegram"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[7]" "Enable/Disable Sales Bot Admin Panel Tabs"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[8]" "Stop/Start This Bot Completely"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" tg_act; then
            return
        fi
        case "$tg_act" in
            1)
                read -r -p "$(echo -e "${C_BLUE}👉 Enter Telegram Bot Token: ${C_RESET}")" input_token
                read -r -p "$(echo -e "${C_BLUE}👉 Enter Telegram Admin Chat ID: ${C_RESET}")" input_chat
                if [[ -n "$input_token" && -n "$input_chat" ]]; then
                    mkdir -p "/etc/firewallfalcon" 2>/dev/null
                    cat <<EOF > "$TELEGRAM_CONF"
BOT_TOKEN="$input_token"
CHAT_ID="$input_chat"
NOTIFY_ENABLED="true"
AUTO_BACKUP_BEFORE_UPDATE="true"
EOF
                    echo -e "\n${C_GREEN}✅ Telegram Bot configured successfully!${C_RESET}"
                    send_telegram_msg "👑 <b>تم ربط بوت DAHOOM!</b>%0Aعنوان IP للسيرفر: $(curl -s -4 icanhazip.com 2>/dev/null)"
                    setup_telegram_bot_service
                    if _fm_ensure_crontab_available; then
                        (crontab -l 2>/dev/null | grep -v "_run_telegram_poll") | crontab -
                        (crontab -l 2>/dev/null; echo "* * * * * bash /usr/local/bin/dahoom _run_telegram_poll &>/dev/null") | crontab -
                        send_telegram_msg "🤖 أرسل /help لمعرفة ما يمكنني فعله."
                    fi
                fi
                press_enter
                ;;
            2)
                echo -e "\n${C_BLUE}Sending test message to Telegram...${C_RESET}"
                send_telegram_msg "🚀 <b>رسالة اختبار من DAHOOM</b>%0Aالوقت: $(date)"
                echo -e "${C_GREEN}✅ Test message sent! Check your Telegram chat.${C_RESET}"
                press_enter
                ;;
            3)
                echo -e "\n${C_BLUE}Creating backup and sending to Telegram...${C_RESET}"
                _fm_telegram_backup_now
                echo -e "${C_GREEN}✅ Backup created and sent to Telegram!${C_RESET}"
                press_enter
                ;;
            4)
                if [[ "$enabled" == "true" ]]; then
                    sed -i 's/NOTIFY_ENABLED="true"/NOTIFY_ENABLED="false"/' "$TELEGRAM_CONF" 2>/dev/null
                    echo -e "\n${C_YELLOW}Notifications disabled.${C_RESET}"
                else
                    sed -i 's/NOTIFY_ENABLED="false"/NOTIFY_ENABLED="true"/' "$TELEGRAM_CONF" 2>/dev/null
                    echo -e "\n${C_GREEN}✅ Notifications enabled.${C_RESET}"
                fi
                press_enter
                ;;
            5)
                if [[ ! -f "$TELEGRAM_CONF" ]]; then
                    echo -e "\n${C_RED}❌ Configure the Bot Token & Chat ID first (option 1).${C_RESET}"
                    press_enter
                    continue
                fi
                echo -e "\n${C_CYAN}Choose backup schedule:${C_RESET}"
                printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Daily (03:00)"
                printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Weekly (Sunday 03:00)"
                printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Off"
                if ! read -r -p "$(echo -e ${C_PROMPT}"👉 Select: "${C_RESET})" sched_choice; then
                    continue
                fi
                if ! _fm_ensure_crontab_available; then
                    echo -e "\n${C_RED}❌ Could not install/find 'cron' on this system.${C_RESET}"
                    press_enter
                    continue
                fi
                (crontab -l 2>/dev/null | grep -v "_run_telegram_backup") | crontab -
                sed -i '/^BACKUP_SCHEDULE=/d' "$TELEGRAM_CONF" 2>/dev/null
                case "$sched_choice" in
                    1)
                        (crontab -l 2>/dev/null; echo "0 3 * * * bash /usr/local/bin/dahoom _run_telegram_backup &>/dev/null") | crontab -
                        echo 'BACKUP_SCHEDULE="daily"' >> "$TELEGRAM_CONF"
                        echo -e "\n${C_GREEN}✅ Scheduled daily backup at 03:00.${C_RESET}"
                        ;;
                    2)
                        (crontab -l 2>/dev/null; echo "0 3 * * 0 bash /usr/local/bin/dahoom _run_telegram_backup &>/dev/null") | crontab -
                        echo 'BACKUP_SCHEDULE="weekly"' >> "$TELEGRAM_CONF"
                        echo -e "\n${C_GREEN}✅ Scheduled weekly backup (Sunday 03:00).${C_RESET}"
                        ;;
                    3)
                        echo -e "\n${C_YELLOW}Automatic backup schedule disabled.${C_RESET}"
                        ;;
                    *) invalid_option ;;
                esac
                press_enter
                ;;
            6)
                if [[ ! -f "$TELEGRAM_CONF" ]]; then
                    echo -e "\n${C_RED}❌ Configure the Bot Token & Chat ID first (option 1).${C_RESET}"
                    press_enter
                    continue
                fi
                read -r -p "$(echo -e "${C_BLUE}👉 Reseller username: ${C_RESET}")" rlink_user
                if [[ -z "$rlink_user" ]] || ! grep -q "^${rlink_user}:" "$RESELLERS_DB" 2>/dev/null; then
                    echo -e "\n${C_RED}❌ No reseller with that username was found.${C_RESET}"
                    press_enter
                    continue
                fi
                local rlink_code; rlink_code=$(_fm_reseller_generate_link_code "$rlink_user")
                echo -e "\n${C_GREEN}✅ Give this code to ${rlink_user} (valid 10 minutes):${C_RESET}"
                echo -e "   ${C_YELLOW}${rlink_code}${C_RESET}"
                echo -e "${C_GRAY}They send /link ${rlink_code} to this same bot to link their own chat.${C_RESET}"
                press_enter
                ;;
            7)
                if [[ ! -f "$TELEGRAM_CONF" ]]; then
                    echo -e "\n${C_RED}❌ Configure the Bot Token & Chat ID first (option 1).${C_RESET}"
                    press_enter
                    continue
                fi
                local new_sales_flag="true"
                [[ "$sales_enabled" == "true" ]] && new_sales_flag="false"
                if grep -q '^SALES_BOT_ENABLED=' "$TELEGRAM_CONF" 2>/dev/null; then
                    sed -i "s/^SALES_BOT_ENABLED=.*/SALES_BOT_ENABLED=\"${new_sales_flag}\"/" "$TELEGRAM_CONF"
                else
                    echo "SALES_BOT_ENABLED=\"${new_sales_flag}\"" >> "$TELEGRAM_CONF"
                fi
                if [[ "$new_sales_flag" == "true" ]]; then
                    echo -e "\n${C_GREEN}✅ Sales Bot admin panel tabs now appear in the web panel.${C_RESET}"
                else
                    echo -e "\n${C_YELLOW}Sales Bot admin panel tabs are now hidden in the web panel.${C_RESET}"
                fi
                press_enter
                ;;
            8)
                # Whether it's running right now is read live (systemctl),
                # never from a stored flag alone — so this always does the
                # right thing even if the service died on its own and
                # BOT_SERVICE_ENABLED never got updated to say so.
                local bot_running=false
                if [[ -f "$TELEGRAM_CONF" ]] && grep -q "^BOT_TOKEN=" "$TELEGRAM_CONF" 2>/dev/null \
                   && systemctl is-active --quiet firewallfalcon-telegram-bot 2>/dev/null; then
                    bot_running=true
                fi
                if ! $bot_running; then
                    if [[ ! -f "$TELEGRAM_CONF" ]] || ! grep -q "^BOT_TOKEN=" "$TELEGRAM_CONF" 2>/dev/null; then
                        echo -e "\n${C_RED}❌ Configure the Bot Token & Chat ID first (option 1).${C_RESET}"
                        press_enter
                        continue
                    fi
                    setup_telegram_bot_service
                    if _fm_ensure_crontab_available; then
                        (crontab -l 2>/dev/null | grep -v "_run_telegram_poll") | crontab -
                        (crontab -l 2>/dev/null; echo "* * * * * bash /usr/local/bin/dahoom _run_telegram_poll &>/dev/null") | crontab -
                    fi
                    if grep -q '^BOT_SERVICE_ENABLED=' "$TELEGRAM_CONF" 2>/dev/null; then
                        sed -i 's/^BOT_SERVICE_ENABLED=.*/BOT_SERVICE_ENABLED="true"/' "$TELEGRAM_CONF"
                    else
                        echo 'BOT_SERVICE_ENABLED="true"' >> "$TELEGRAM_CONF"
                    fi
                    echo -e "\n${C_GREEN}✅ The Telegram bot is running again — it will answer customers and admin commands as before.${C_RESET}"
                else
                    systemctl stop firewallfalcon-telegram-bot &>/dev/null || true
                    systemctl disable firewallfalcon-telegram-bot &>/dev/null || true
                    (crontab -l 2>/dev/null | grep -v "_run_telegram_poll") | crontab - 2>/dev/null
                    if grep -q '^BOT_SERVICE_ENABLED=' "$TELEGRAM_CONF" 2>/dev/null; then
                        sed -i 's/^BOT_SERVICE_ENABLED=.*/BOT_SERVICE_ENABLED="false"/' "$TELEGRAM_CONF"
                    else
                        echo 'BOT_SERVICE_ENABLED="false"' >> "$TELEGRAM_CONF"
                    fi
                    echo -e "\n${C_YELLOW}⏹ The Telegram bot has been stopped completely — it will not answer anyone until you start it again from here.${C_RESET}"
                fi
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

# ── ANTI-MULTILOGIN ENGINE HELPERS & MENU ──────────────────────────────
MULTILOGIN_CONF="/etc/firewallfalcon/multilogin.conf"

check_and_kill_multilogin() {
    [[ -s "$DB_FILE" ]] || return
    local lock_file="/tmp/.ff_multilogin.lock"
    [[ -f "$lock_file" ]] && return
    touch "$lock_file" 2>/dev/null

    refresh_ssh_session_cache

    while IFS=: read -r user pass expiry limit bandwidth_gb _extra; do
        [[ -z "$user" || -z "$limit" ]] && continue
        [[ "$limit" =~ ^[0-9]+$ && "$limit" -gt 0 ]] || continue

        local active_count="${SSH_SESSION_COUNTS[$user]:-0}"
        if [[ "$active_count" -gt "$limit" ]]; then
            local user_pids=()
            for pid in "${!SSH_SESSION_PIDS[@]}"; do
                if [[ "${SSH_SESSION_PIDS[$pid]}" == "$user" ]]; then
                    user_pids+=("$pid")
                fi
            done

            local excess=$((active_count - limit))
            if [[ ${#user_pids[@]} -gt 0 ]]; then
                for ((i=0; i<excess && i<${#user_pids[@]}; i++)); do
                    local kill_pid="${user_pids[$i]}"
                    kill -9 "$kill_pid" 2>/dev/null
                done
                _log_action "MULTILOGIN_KILLED" "$user" "killed=$excess active=$active_count limit=$limit"
                send_telegram_msg "⚠️ <b>Anti-MultiLogin Triggered</b>%0AUser: <b>$user</b>%0AKilled excess sessions ($active_count / $limit allowed)."
            fi
        fi
    done < "$DB_FILE"

    rm -f "$lock_file" 2>/dev/null
}

anti_multilogin_menu() {
    while true; do
        clear; show_banner
        echo
        menu_section "ANTI-MULTILOGIN ENGINE" "$C_TITLE"
        echo
        local status="Disabled"
        if (crontab -l 2>/dev/null | grep -q "_run_multilogin"); then
            status="${C_GREEN}Active (Automated Background Protection)${C_RESET}"
        else
            status="${C_RED}Disabled${C_RESET}"
        fi

        echo -e "  ${C_CYAN}Status:${C_RESET} $status"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Enable Automated Anti-MultiLogin Guard"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Disable Anti-MultiLogin Guard"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Run Instant Multi-Session Scan & Kill"
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        if ! read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" ml_act; then
            return
        fi
        case "$ml_act" in
            1)
                if _fm_ensure_crontab_available; then
                    (crontab -l 2>/dev/null | grep -v "_run_multilogin") | crontab -
                    (crontab -l 2>/dev/null; echo "* * * * * bash /usr/local/bin/dahoom _run_multilogin &>/dev/null") | crontab -
                    if crontab -l 2>/dev/null | grep -q "_run_multilogin"; then
                        echo -e "\n${C_GREEN}✅ Automated Anti-MultiLogin Guard enabled (runs every minute).${C_RESET}"
                    else
                        echo -e "\n${C_RED}❌ Could not enable the guard — the crontab entry failed to save.${C_RESET}"
                    fi
                else
                    echo -e "\n${C_RED}❌ Could not install/find 'cron' on this system — the guard needs it to run automatically.${C_RESET}"
                fi
                press_enter
                ;;
            2)
                (crontab -l 2>/dev/null | grep -v "_run_multilogin") | crontab -
                echo -e "\n${C_GREEN}✅ Anti-MultiLogin Guard disabled.${C_RESET}"
                press_enter
                ;;
            3)
                echo -e "\n${C_BLUE}Running instant multi-session scan...${C_RESET}"
                check_and_kill_multilogin
                echo -e "${C_GREEN}✅ Scan completed.${C_RESET}"
                press_enter
                ;;
            0) return ;;
            *) invalid_option ;;
        esac
    done
}

