auto_reboot_menu() {
    clear; show_banner
    echo
    menu_section "AUTO REBOOT" "$C_TITLE"
    echo
    local cur_cron; cur_cron=$(crontab -l 2>/dev/null | grep -i "reboot\|shutdown" | head -1)
    if [[ -n "$cur_cron" ]]; then
        echo -e "  ${C_CYAN}Schedule:${C_RESET} ${C_GREEN}Daily Midnight (00:00)${C_RESET}"
    else
        echo -e "  ${C_CYAN}Schedule:${C_RESET} ${C_RED}Disabled${C_RESET}"
    fi
    echo
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Daily Reboot (00:00)"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Disable Reboot"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Reboot Server Now"
    echo
    printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
    echo
    read -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" r_choice

    case $r_choice in
        1)
            if _fm_ensure_crontab_available; then
                # Remove existing to prevent duplicates
                (crontab -l 2>/dev/null | grep -v "systemctl reboot") | crontab -
                # Add new job
                (crontab -l 2>/dev/null; echo "0 0 * * * systemctl reboot") | crontab -
                if crontab -l 2>/dev/null | grep -q "systemctl reboot"; then
                    echo -e "\n${C_GREEN}✅ Auto-reboot scheduled for every day at 00:00.${C_RESET}"
                else
                    echo -e "\n${C_RED}❌ Could not schedule the reboot — the crontab entry failed to save.${C_RESET}"
                fi
            else
                echo -e "\n${C_RED}❌ Could not install/find 'cron' on this system — scheduling needs it.${C_RESET}"
            fi
            press_enter
            ;;
        2)
            (crontab -l 2>/dev/null | grep -v "systemctl reboot") | crontab -
            echo -e "\n${C_GREEN}✅ Auto-reboot disabled.${C_RESET}"
            press_enter
            ;;
        3)
            read -r -p "$(echo -e ${C_PROMPT}"⚠️  Reboot the server right now? This will drop all active connections. (y/n): "${C_RESET})" reboot_confirm
            if [[ "$reboot_confirm" == "y" || "$reboot_confirm" == "Y" ]]; then
                send_telegram_msg "🔄 <b>Manual Reboot</b>%0AThe server is rebooting now (triggered from the DAHOOM menu)."
                echo -e "\n${C_YELLOW}Rebooting now...${C_RESET}"
                sleep 1
                systemctl reboot
            else
                echo -e "\n${C_GRAY}Cancelled.${C_RESET}"
                press_enter
            fi
            ;;
        *) return ;;
    esac
}

# ── Auto-launch the menu on SSH login — opt-in, disabled by default
# (matching how similar tools ship it), since forcing a full-screen menu
# onto every root SSH session would break anyone who logs in to run a
# one-off command or an automation script. Separate hook file from the
# MOTD banner so the two toggle independently.
_FM_AUTOMENU_HOOK="/etc/profile.d/dahoom_automenu.sh"

_fm_write_auto_menu_hook() {
    mkdir -p /etc/profile.d 2>/dev/null
    cat > "$_FM_AUTOMENU_HOOK" << 'EOF'
# DAHOOM: auto-launch the menu on interactive root SSH logins.
if [[ $- == *i* ]] && [ -t 0 ] && [ -z "$DAHOOM_AUTOMENU_SHOWN" ] && [ "$(id -u)" = "0" ] && [ -x "/usr/local/bin/dahoom" ]; then
    export DAHOOM_AUTOMENU_SHOWN=1
    /usr/local/bin/dahoom
fi
EOF
    chmod +x "$_FM_AUTOMENU_HOOK" 2>/dev/null || true
}

auto_menu_on_login_menu() {
    clear; show_banner
    echo
    menu_section "AUTO-LAUNCH MENU ON LOGIN" "$C_TITLE"
    echo
    local status="${C_RED}Disabled${C_RESET}"
    [[ -f "$_FM_AUTOMENU_HOOK" ]] && status="${C_GREEN}Enabled${C_RESET}"
    echo -e "  ${C_CYAN}Status:${C_RESET} $status"
    echo -e "  ${C_GRAY}When enabled, this menu opens automatically every time you SSH in as${C_RESET}"
    echo -e "  ${C_GRAY}root — instead of a plain shell you'd type 'dahoom' from.${C_RESET}"
    echo
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Enable"
    printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Disable"
    echo
    printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
    echo
    read -r -p "$(echo -e ${C_PROMPT}"> Select an option: "${C_RESET})" am_act
    case "$am_act" in
        1)
            _fm_write_auto_menu_hook
            echo -e "\n${C_GREEN}✅ Enabled — the menu will open automatically on your next SSH login.${C_RESET}"
            press_enter
            ;;
        2)
            rm -f "$_FM_AUTOMENU_HOOK" 2>/dev/null
            echo -e "\n${C_YELLOW}Disabled.${C_RESET}"
            press_enter
            ;;
        0) return ;;
        *) invalid_option ;;
    esac
}

press_enter() {
    echo -e "\n  ${C_FRAME}────────────────────────────────────────────────────────${C_RESET}"
    echo -en "  ${C_CYAN}${C_BOLD}▸${C_RESET} ${C_GRAY}Press${C_RESET} ${C_CYAN}Enter${C_RESET} ${C_GRAY}to return${C_RESET} " && read -r || true
}
invalid_option() {
    echo -e "\n${C_RED}❌ Invalid option.${C_RESET}" && sleep 1
}

# --- Display-width helpers: emoji count as 2 columns, variation selectors as 0 ---
disp_width() {
    local s="$1" i c w=0
    for ((i=0; i<${#s}; i++)); do
        c="${s:i:1}"
        [[ "$c" == $'\xEF\xB8\x8F' ]] && continue
        # ASCII (<= 0x7F) = 1 column; any multibyte char (emoji etc.) = 2 columns
        if [[ "$c" < $'\x80' ]]; then
            w=$((w+1))
        else
            w=$((w+2))
        fi
    done
    echo "$w"
}

# Right-pad a string to exactly W display columns
pad_right() {
    local s="$1" w="$2" dw
    dw=$(disp_width "$s")
    if (( dw < w )); then
        printf '%s%*s' "$s" "$((w - dw))" ""
    else
        printf '%s' "$s"
    fi
}

# --- Clean centered section header for the main menu ---
menu_section() {
    local title="$1" color="$2" total=54 rule i
    local tlen=${#title}
    # ▌ TITLE ───────────  : accent bar, title, then a rule filling the remainder
    local used=$(( 2 + tlen + 1 ))
    local rlen=$(( total - used )); (( rlen < 2 )) && rlen=2
    rule=""
    for ((i=0; i<rlen; i++)); do rule+="─"; done
    echo -e "  ${color}${C_BOLD}▌${C_RESET} ${color}${C_BOLD}${title}${C_RESET} ${C_FRAME}${rule}${C_RESET}"
}

