get_update_branch() {
    if [ -f "/etc/firewallfalcon/channel" ]; then
        local ch; ch=$(cat "/etc/firewallfalcon/channel" 2>/dev/null | tr -d '[:space:]')
        if [[ "$ch" == "dev" || "$ch" == "beta2" || "$ch" == "main" ]]; then
            echo "$ch"
            return
        fi
    fi
    mkdir -p "/etc/firewallfalcon" 2>/dev/null
    echo "dev" > "/etc/firewallfalcon/channel" 2>/dev/null || true
    echo "dev"
}

# ── Update rollback: snapshot the currently-running binary + its version
# tag right before replacing it, so a bad update has a one-command way
# back instead of only a manual re-download/reinstall.
_FM_PREV_BINARY="/etc/firewallfalcon/.dahoom.prev"
_FM_PREV_VERSION="/etc/firewallfalcon/.version.prev"

# Whether a full data backup (users.db, bandwidth, bot_*.db, x-ui.db —
# everything _fm_build_backup_archive already knows how to tar up) is
# taken automatically right before a self-update replaces the binary.
# Defaults to on: an old TELEGRAM_CONF from before this setting existed
# simply won't set the variable at all when sourced, so the ":-true"
# fallback below is what actually keeps existing installs protected.
_fm_auto_backup_before_update_enabled() {
    local AUTO_BACKUP_BEFORE_UPDATE
    [[ -f "$TELEGRAM_CONF" ]] && source "$TELEGRAM_CONF" 2>/dev/null
    [[ "${AUTO_BACKUP_BEFORE_UPDATE:-true}" != "false" ]]
}

_fm_set_auto_backup_before_update() {
    local val="$1"  # "true" or "false"
    mkdir -p "$(dirname "$TELEGRAM_CONF")" 2>/dev/null
    touch "$TELEGRAM_CONF"
    if grep -q '^AUTO_BACKUP_BEFORE_UPDATE=' "$TELEGRAM_CONF" 2>/dev/null; then
        sed -i "s/^AUTO_BACKUP_BEFORE_UPDATE=.*/AUTO_BACKUP_BEFORE_UPDATE=\"${val}\"/" "$TELEGRAM_CONF"
    else
        echo "AUTO_BACKUP_BEFORE_UPDATE=\"${val}\"" >> "$TELEGRAM_CONF"
    fi
}

# Called right before _fm_snapshot_before_update replaces the running
# binary — a full archive of every data file (never touched by the
# update itself, but a safety net is a safety net) is sent to the admin
# exactly like the manual "Backup Now" button, then pruned to the 5 most
# recent so pre-update copies don't pile up forever.
_fm_backup_before_update_if_enabled() {
    _fm_auto_backup_before_update_enabled || return 0
    [[ -d "$DB_DIR" ]] || return 0
    local dest="/root/ff_backup_preupdate_$(date +%F-%H%M%S).tar.gz"
    _fm_build_backup_archive "$dest"
    [[ -s "$dest" ]] || return 0
    send_telegram_doc "$dest" "💾 نسخة احتياطية تلقائية قبل التحديث - $(date +%F)" 2>/dev/null
    local -a old_backups
    mapfile -t old_backups < <(ls -1t /root/ff_backup_preupdate_*.tar.gz 2>/dev/null | tail -n +6)
    (( ${#old_backups[@]} > 0 )) && rm -f "${old_backups[@]}"
}

_fm_snapshot_before_update() {
    [[ -f "/usr/local/bin/dahoom" ]] || return 0
    _fm_backup_before_update_if_enabled
    mkdir -p "/etc/firewallfalcon" 2>/dev/null
    cp -f "/usr/local/bin/dahoom" "$_FM_PREV_BINARY" 2>/dev/null
    [[ -f "$VERSION_FILE" ]] && cp -f "$VERSION_FILE" "$_FM_PREV_VERSION" 2>/dev/null
}

_fm_rollback_previous_version() {
    [[ -f "$_FM_PREV_BINARY" ]] || return 1
    cp -f "/usr/local/bin/dahoom" "/tmp/.dahoom_pre_rollback" 2>/dev/null
    cp -f "$_FM_PREV_BINARY" "/usr/local/bin/dahoom" && chmod +x "/usr/local/bin/dahoom"
    ln -sf "/usr/local/bin/dahoom" "/usr/bin/dahoom" 2>/dev/null || true
    [[ -f "$_FM_PREV_VERSION" ]] && cp -f "$_FM_PREV_VERSION" "$VERSION_FILE" 2>/dev/null
    return 0
}

trigger_standalone_update_page() {
    clear
    local cur_ver; cur_ver=$(get_current_version_tag)
    local cur_sha; cur_sha=$(get_installed_sha)
    local branch_name; branch_name=$(get_update_branch)
    local friendly_branch="Stable"
    [[ "$branch_name" == "beta2" ]] && friendly_branch="Beta"
    [[ "$branch_name" == "dev" ]] && friendly_branch="Development"

    # Always fetch fresh from API — do not rely on stale banner cache
    local api_json remote_sha
    api_json=$(curl -s --max-time 5 "$(_fm_gh_api)/branches/${branch_name}" 2>/dev/null)
    if [[ -n "$api_json" ]]; then
        remote_sha=$(echo "$api_json" | jq -r '.commit.sha' 2>/dev/null | cut -c1-7)
    fi
    # Fallback to banner cache only if API fails
    if [[ -z "$remote_sha" || "$remote_sha" == "null" || ${#remote_sha} -ne 7 ]]; then
        remote_sha="${BANNER_CACHE_REMOTE_VER##*4.6.0_}"
        remote_sha="${remote_sha##*dev_}"
        remote_sha="${remote_sha##*beta_}"
        remote_sha="${remote_sha:0:7}"
    fi
    # If still empty, treat as same (up to date)
    [[ -z "$remote_sha" || ${#remote_sha} -ne 7 ]] && remote_sha="$cur_sha"

    # Warm the banner cache with this fresh result
    local now_ts; now_ts=$(date +%s 2>/dev/null || echo 0)
    [[ ${#remote_sha} -eq 7 ]] && echo "$now_ts $remote_sha" > "$UPDATE_CACHE_FILE" 2>/dev/null

    local remote_ver="4.9.0_${remote_sha}"
    [[ "$branch_name" == "beta2" ]] && remote_ver="4.9.0_beta_${remote_sha}"
    [[ "$branch_name" == "dev" ]] && remote_ver="4.9.0_dev_${remote_sha}"

    # If update is available -> UPDATE IMMEDIATELY ON THE SPOT!
    if [[ -n "$cur_sha" && ${#cur_sha} -eq 7 && -n "$remote_sha" && ${#remote_sha} -eq 7 && "$cur_sha" != "$remote_sha" ]]; then
        echo
        menu_section "UPDATE MANAGER" "$C_TITLE"
        echo
        echo -e "  🚀 ${C_YELLOW}New update detected (${friendly_branch}):${C_RESET} ${C_GREEN}${remote_ver}${C_RESET} (Current: ${C_GRAY}${cur_ver}${C_RESET})"
        echo

        show_progress_bar "1/3 Downloading ${friendly_branch} update payload from GitHub..." 20 0.02
        local tmp_menu="/tmp/menu_update_$$"
        if _fm_pull_src && cp -f "$FM_SRC/menu.sh" "$tmp_menu" && [[ -s "$tmp_menu" ]]; then
            show_progress_bar "2/3 Verifying permissions & structure..." 15 0.02
            chmod +x "$tmp_menu"
            sed -i 's/\r$//' "$tmp_menu" 2>/dev/null || true
            mkdir -p "/etc/firewallfalcon" 2>/dev/null
            _fm_snapshot_before_update
            echo "$remote_sha" > "$VERSION_FILE"
            echo "$now_ts $remote_sha" > "$UPDATE_CACHE_FILE"
            mv "$tmp_menu" "/usr/local/bin/dahoom"
            chmod +x "/usr/local/bin/dahoom"
            ln -sf "/usr/local/bin/dahoom" "/usr/bin/dahoom" 2>/dev/null || true
            rm -f "/usr/local/bin/menu" "/usr/local/bin/fm" "/usr/bin/menu" "/usr/bin/fm" 2>/dev/null || true

            show_progress_bar "3/3 Finalizing update & reloading menu..." 15 0.02
            # The web panel (and sales-bot service) ship in the exact same
            # release as this CLI script — replacing only `dahoom` here
            # leaves an admin who has a panel installed running its old
            # panel.py/index.html forever, even though the CLI just told
            # them they're up to date. Redeploy both unconditionally;
            # update_panel.sh no-ops safely (after refreshing the CLI
            # binary again, harmlessly) when no panel is installed at all.
            bash "$FM_SRC/update_panel.sh" || true
            echo -e "  ${C_GREEN}✅ Updated successfully to version: ${remote_ver}${C_RESET}\n"
            sleep 0.8
            exec bash /usr/local/bin/dahoom
        else
            echo -e "  ${C_RED}❌ Download failed. Please verify internet connection.${C_RESET}\n"
            rm -f "$tmp_menu" 2>/dev/null
            press_enter
        fi
    else
        echo
        menu_section "UPDATE MANAGER" "$C_TITLE"
        echo
        echo -e "  ${C_CYAN}Installed Version:${C_RESET} ${C_YELLOW}${cur_ver}${C_RESET}"
        echo -e "  ${C_CYAN}Status           :${C_RESET} ${C_GREEN}✅ Up to date${C_RESET}"
        echo -e "  ${C_CYAN}Update Channel   :${C_RESET} ${C_CYAN}${friendly_branch} (${branch_name})${C_RESET}"
        echo
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[1]" "Reinstall / Force Repair (${branch_name})"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[2]" "Update Web Control Panel"
        printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[3]" "Switch Update Channel [Stable / Beta / Dev]"
        if [[ -f "$_FM_PREV_BINARY" ]]; then
            printf "  ${C_CHOICE}%-4s${C_RESET} %s\n" "[4]" "Rollback to Previous Version"
        fi
        echo
        printf "  ${C_DANGER}%-4s${C_RESET} %s\n" "[0]" "Return"
        echo
        read -r -p "$(echo -e ${C_PROMPT}"> Select an option [0]: "${C_RESET})" no_up_act
        no_up_act=${no_up_act:-0}
        if [[ "$no_up_act" == "1" ]]; then
            echo
            show_progress_bar "Re-downloading core binaries from GitHub (${branch_name})..." 20 0.02
            local tmp_menu="/tmp/menu_update_$$"
            _fm_pull_src && cp -f "$FM_SRC/menu.sh" "$tmp_menu"
            chmod +x "$tmp_menu"
            sed -i 's/\r$//' "$tmp_menu" 2>/dev/null || true
            mkdir -p "/etc/firewallfalcon" 2>/dev/null
            _fm_snapshot_before_update
            echo "$remote_sha" > "$VERSION_FILE"
            echo "$now_ts $remote_sha" > "$UPDATE_CACHE_FILE"
            mv "$tmp_menu" "/usr/local/bin/dahoom"
            chmod +x "/usr/local/bin/dahoom"
            ln -sf "/usr/local/bin/dahoom" "/usr/bin/dahoom" 2>/dev/null || true
            rm -f "/usr/local/bin/menu" "/usr/local/bin/fm" "/usr/bin/menu" "/usr/bin/fm" 2>/dev/null || true

            # Same reasoning as the auto-update branch above — a force
            # repair of the CLI binary alone would leave any installed
            # web panel on its old code; redeploy it too (safe no-op if
            # there's no panel service configured on this server).
            bash "$FM_SRC/update_panel.sh" || true
            echo -e "\n  ${C_GREEN}✅ Repaired successfully from ${branch_name}!${C_RESET}\n"
            sleep 1
            exec bash /usr/local/bin/dahoom
        elif [[ "$no_up_act" == "2" ]]; then
            echo
            show_progress_bar "Updating Web Control Panel from new_panel branch..." 20 0.02
            { _fm_pull_src && bash "$FM_SRC/update_panel.sh"; }
            press_enter
            trigger_standalone_update_page
        elif [[ "$no_up_act" == "3" ]]; then
            echo
            echo -e "  ${C_BOLD}Select Update Channel:${C_RESET}"
            echo -e "  ${C_GREEN}[1] Stable Channel (main)${C_RESET}"
            echo -e "  ${C_YELLOW}[2] Beta Channel (beta2)${C_RESET}"
            echo -e "  ${C_PURPLE}[3] Development Channel (dev - Bleeding Edge)${C_RESET}"
            echo -e "  ${C_DANGER}[0] Cancel${C_RESET}"
            echo
            read -r -p "$(echo -e ${C_PROMPT}"> Choose channel: "${C_RESET})" ch_sel
            case "$ch_sel" in
                1)
                    echo "main" > /etc/firewallfalcon/channel
                    echo -e "\n  ${C_GREEN}✅ Switched to Stable channel (main).${C_RESET}"
                    ;;
                2)
                    echo "beta2" > /etc/firewallfalcon/channel
                    echo -e "\n  ${C_YELLOW}🚀 Switched to Beta channel (beta2).${C_RESET}"
                    ;;
                3)
                    echo "dev" > /etc/firewallfalcon/channel
                    echo -e "\n  ${C_PURPLE}🧪 Switched to Development channel (dev).${C_RESET}"
                    ;;
                *)
                    echo -e "\n  ${C_GRAY}Cancelled.${C_RESET}"
                    ;;
            esac
            sleep 1
            trigger_standalone_update_page
        elif [[ "$no_up_act" == "4" && -f "$_FM_PREV_BINARY" ]]; then
            echo
            read -r -p "$(echo -e ${C_PROMPT}"⚠️  Roll back to the previous version now? (y/n): "${C_RESET})" rb_confirm
            if [[ "$rb_confirm" == "y" || "$rb_confirm" == "Y" ]]; then
                show_progress_bar "Rolling back to the previous version..." 15 0.02
                if _fm_rollback_previous_version; then
                    echo -e "\n  ${C_GREEN}✅ Rolled back successfully.${C_RESET}\n"
                    sleep 0.8
                    exec bash /usr/local/bin/dahoom
                else
                    echo -e "\n  ${C_RED}❌ Rollback failed — no previous version snapshot found.${C_RESET}\n"
                    press_enter
                fi
            else
                echo -e "\n  ${C_GRAY}Cancelled.${C_RESET}\n"
                press_enter
            fi
        fi
    fi
}

