# ── Colored, emoji-tagged 2-box-per-row menu grid ──────────────────────
_FM_MENU_ITEM_W=27   # visual columns for "[N] EMOJI Label" inside a box
_FM_MENU_BOX_W=31    # total box width incl. borders/padding

# $1=color $2=num $3=emoji $4=label -> one padded, closed content line
_fm_menu_item_line() {
    local LC_ALL=C.utf8 LANG=C.utf8   # force codepoint-based ${#}, not byte-based
    local color="$1" num="[$2]" emoji="$3" label="$4"
    local content="${num} ${emoji} ${label}"
    local vis=$(( ${#content} + 1 ))   # +1: the emoji prints 2 cols but is 1 real character
    local pad=$(( _FM_MENU_ITEM_W - vis ))
    (( pad < 0 )) && pad=0
    printf "  ${color}│${C_RESET} %s%*s ${color}│${C_RESET}\n" "$content" "$pad" ''
}

# $1=color $2=icon $3=title -> box top border + title row
_fm_menu_box_title() {
    local LC_ALL=C.utf8 LANG=C.utf8   # force codepoint-based ${#}, not byte-based
    local color="$1" icon="$2" title="$3"
    local content="${icon} ${title}"
    local vis=$(( ${#content} + 1 ))
    local rule_len=$(( _FM_MENU_ITEM_W - vis - 1 ))
    (( rule_len < 2 )) && rule_len=2
    local rule=""; local i
    for ((i=0; i<rule_len; i++)); do rule+="─"; done
    printf "  ${color}╭$(printf '─%.0s' $(seq 1 $((_FM_MENU_BOX_W-2))))╮${C_RESET}\n"
    printf "  ${color}│${C_RESET} ${C_BOLD}%s${C_RESET} ${color}%s${C_RESET} ${color}│${C_RESET}\n" "$content" "$rule"
}

_fm_menu_box_bottom() {
    local color="$1"
    printf "  ${color}╰$(printf '─%.0s' $(seq 1 $((_FM_MENU_BOX_W-2))))╯${C_RESET}\n"
}

# Full-width danger-zone row, matching the box-pair's total width above it.
# Border length is computed from the actual content so it can never drift
# out of sync with it.
_fm_menu_danger_row() {
    local LC_ALL=C.utf8 LANG=C.utf8
    local color="$C_DANGER" content
    content=" 💀 DANGER ZONE   [99] 💣 Uninstall      [0] 🚪 Exit"
    local vis=$(( ${#content} + 3 ))   # +3: three emoji, each 1 char but 2 visual cols
    # Full printed row width, matching two boxes + their own indents + the
    # paste gap between them: (box_border_width + indent) * 2 + 1 gap.
    local row_w=$(( (_FM_MENU_BOX_W + 2) * 2 + 1 ))
    local border_n=$(( row_w - 4 ))     # indent(2) + ╭/╰(1) + dashes + ╮/╯(1)
    local pad=$(( row_w - 6 - vis ))    # indent(2) + │(1) + sp(1) + content+pad + sp(1) + │(1)
    (( pad < 1 )) && pad=1
    printf "  ${color}╭$(printf '─%.0s' $(seq 1 $border_n))╮${C_RESET}\n"
    printf "  ${color}│${C_RESET} ${C_BOLD}${color}%s${C_RESET}%*s ${color}│${C_RESET}\n" "$content" "$pad" ''
    printf "  ${color}╰$(printf '─%.0s' $(seq 1 $border_n))╯${C_RESET}\n"
}

# Renders two boxes side by side. Box items passed as name-refs to arrays
# of "num|emoji|label" strings.
_fm_render_menu_box_pair() {
    local -n _b1_items=$1 _b2_items=$2
    local c1="$3" icon1="$4" title1="$5"
    local c2="$6" icon2="$7" title2="$8"

    local l1 l2
    l1=$(_fm_menu_box_title "$c1" "$icon1" "$title1")
    l2=$(_fm_menu_box_title "$c2" "$icon2" "$title2")
    paste -d' ' <(printf '%s\n' "$l1") <(printf '%s\n' "$l2")

    local max=${#_b1_items[@]}
    (( ${#_b2_items[@]} > max )) && max=${#_b2_items[@]}

    local i entry num emoji label line1 line2
    for ((i=0; i<max; i++)); do
        if (( i < ${#_b1_items[@]} )); then
            IFS='|' read -r num emoji label <<< "${_b1_items[$i]}"
            line1=$(_fm_menu_item_line "$c1" "$num" "$emoji" "$label")
        else
            line1=$(printf "  ${c1}│${C_RESET}%*s${c1}│${C_RESET}" $((_FM_MENU_ITEM_W+2)) '')
        fi
        if (( i < ${#_b2_items[@]} )); then
            IFS='|' read -r num emoji label <<< "${_b2_items[$i]}"
            line2=$(_fm_menu_item_line "$c2" "$num" "$emoji" "$label")
        else
            line2=$(printf "  ${c2}│${C_RESET}%*s${c2}│${C_RESET}" $((_FM_MENU_ITEM_W+2)) '')
        fi
        printf '%s %s\n' "$line1" "$line2"
    done

    local b1 b2
    b1=$(_fm_menu_box_bottom "$c1")
    b2=$(_fm_menu_box_bottom "$c2")
    paste -d' ' <(printf '%s\n' "$b1") <(printf '%s\n' "$b2")
}

