# EVERY cron-driven entry point runs under its own lock.
#
# These are launched by crontab on a fixed schedule — multilogin and the
# poller every minute, auto-healing every two. Nothing checked whether
# the previous run had finished. On a busy server a run takes longer than
# the gap before the next one starts, so they stack: a live box was found
# with 112 concurrent `dahoom` processes and a load average of 88 on two
# cores. Every component then looks healthy in isolation while the
# machine is too busy to answer anyone — which reads as "the bot is
# hanging" and sends you hunting in entirely the wrong place.
#
# One slow run must delay only itself. If the lock is held, the new run
# exits immediately having done nothing.
if [[ "$1" == "_run_bot_watchdog" ]]; then
    _fm_run_locked bot-watchdog _fm_bot_watchdog_check
    exit 0
fi

if [[ "$1" == "_run_multilogin" ]]; then
    _fm_run_locked multilogin check_and_kill_multilogin
    exit 0
fi

if [[ "$1" == "_run_auto_healing" ]]; then
    _fm_run_locked auto-healing run_auto_healing_check
    exit 0
fi

if [[ "$1" == "_run_telegram_backup" ]]; then
    _fm_run_locked telegram-backup _fm_scheduled_telegram_backup
    exit 0
fi

if [[ "$1" == "_run_telegram_poll" ]]; then
    # Fallback poller. Exits at once if the long-poll service (or an
    # earlier cron run) already holds the lock — see _fm_run_locked.
    _fm_run_locked telegram-poll _fm_telegram_poll_updates
    exit 0
fi

# Approving an order has to go through _fm_bot_admin_approve_order — that
# is the only path that resolves the customer's node, prices the order on
# that node's plan, and provisions THERE rather than on this box. The web
# panel has no node dispatch of its own (it is a per-box panel; the
# registry, the pinned certificates and the TLS calls all live here), so
# when an admin clicks Approve in the panel it delegates to this entry
# point instead of creating the account locally. Same code path as
# /approve in Telegram, so both buttons do exactly the same thing.
if [[ "$1" == "_run_bot_approve_order" ]]; then
    _fm_bot_admin_approve_order "${2:-}"
    exit 0
fi

if [[ "$1" == "_run_bot_reject_order" ]]; then
    _fm_bot_admin_reject_order "${2:-}" "${3:-}"
    exit 0
fi

if [[ "$1" == "_run_bot_broadcast" ]]; then
    _fm_bot_broadcast_worker "${2:-}"
    exit 0
fi

if [[ "$1" == "_run_telegram_bot_service" ]]; then
    _fm_telegram_bot_service_loop
    exit 0
fi

if [[ "$1" == "--install-setup" ]]; then
    initial_setup
    exit 0
fi

if [[ "$1" == "--uninstall" ]]; then
    require_interactive_terminal
    uninstall_script
    exit 0
fi

UPDATE_CACHE_FILE="/tmp/.ff_remote_ver_cache"
VERSION_FILE="/etc/firewallfalcon/.version"

get_installed_sha() {
    local sha=""
    if [[ -f "$VERSION_FILE" && -s "$VERSION_FILE" ]]; then
        sha=$(cat "$VERSION_FILE" 2>/dev/null | tr -d ' \r\n')
        sha="${sha##*beta_}"
        sha="${sha##*4.6.0_}"
        sha="${sha##*4.5.0_}"
        sha="${sha##*beta-}"
        sha="${sha:0:7}"
    fi
    if [[ -z "$sha" || ${#sha} -ne 7 ]]; then
        sha="2272381"
        mkdir -p "/etc/firewallfalcon" 2>/dev/null
        echo "$sha" > "$VERSION_FILE" 2>/dev/null
    fi
    echo "$sha"
}

get_current_version_tag() {
    local sha; sha=$(get_installed_sha)
    local branch_name; branch_name=$(get_update_branch)
    if [[ -n "$sha" ]]; then
        if [[ "$branch_name" == "dev" ]]; then
            echo "4.6.0_dev_${sha}"
        elif [[ "$branch_name" == "beta2" ]]; then
            echo "4.6.0_beta_${sha}"
        else
            echo "4.6.0_${sha}"
        fi
    else
        if [[ "$branch_name" == "dev" ]]; then
            echo "4.6.0_dev_installed"
        elif [[ "$branch_name" == "beta2" ]]; then
            echo "4.6.0_beta_installed"
        else
            echo "4.6.0_installed"
        fi
    fi
}

_check_remote_ver_bg() {
    local lock_file="/tmp/.ff_ver_check.lock"
    local now_ts; now_ts=$(date +%s 2>/dev/null || echo 0)
    local last_check=0
    if [[ -f "$UPDATE_CACHE_FILE" ]]; then
        read -r last_check _ < "$UPDATE_CACHE_FILE" 2>/dev/null
    fi

    if (( now_ts - last_check >= 60 )) && [[ ! -f "$lock_file" ]]; then
        touch "$lock_file" 2>/dev/null
        (
            local branch_name; branch_name=$(get_update_branch)
            local api_j c_sha
            api_j=$(curl -s --max-time 3 "$(_fm_gh_api)/branches/${branch_name}" 2>/dev/null)
            if [[ -n "$api_j" ]]; then
                c_sha=$(echo "$api_j" | jq -r '.commit.sha' 2>/dev/null | cut -c1-7)
                if [[ -n "$c_sha" && "$c_sha" != "null" && ${#c_sha} -eq 7 ]]; then
                    echo "$now_ts $c_sha" > "$UPDATE_CACHE_FILE"
                fi
            fi
            rm -f "$lock_file" 2>/dev/null
        ) &>/dev/null &
    fi
}

check_auto_update() {
    local branch_name; branch_name=$(get_update_branch)
    local cur_sha; cur_sha=$(get_installed_sha)
    local api_json remote_sha=""
    
    # Fast synchronous check on startup against default channel (max 2.5 seconds)
    api_json=$(curl -s --max-time 3 "$(_fm_gh_api)/branches/${branch_name}" 2>/dev/null)
    if [[ -n "$api_json" ]]; then
        remote_sha=$(echo "$api_json" | jq -r '.commit.sha' 2>/dev/null | cut -c1-7)
    fi
    
    if [[ -n "$remote_sha" && "$remote_sha" != "null" && ${#remote_sha} -eq 7 ]]; then
        local now_ts; now_ts=$(date +%s 2>/dev/null || echo 0)
        echo "$now_ts $remote_sha" > "$UPDATE_CACHE_FILE" 2>/dev/null
        
        if [[ -n "$cur_sha" && ${#cur_sha} -eq 7 && "$cur_sha" != "$remote_sha" ]]; then
            BANNER_CACHE_HAS_UPDATE=true
            BANNER_CACHE_REMOTE_VER="4.6.0_${remote_sha}"
            [[ "$branch_name" == "beta2" ]] && BANNER_CACHE_REMOTE_VER="4.6.0_beta_${remote_sha}"
            [[ "$branch_name" == "dev" ]] && BANNER_CACHE_REMOTE_VER="4.6.0_dev_${remote_sha}"
            
            local friendly_branch="Stable"
            [[ "$branch_name" == "beta2" ]] && friendly_branch="Beta"
            [[ "$branch_name" == "dev" ]] && friendly_branch="Development"
            
            clear
            echo
            echo -e "${C_PURPLE}  ╭───────────────────────────────────────────────────────────╮${C_RESET}"
            echo -e "${C_PURPLE}  │${C_RESET} ${C_YELLOW}${C_BOLD}🚀 NEW UPDATE AVAILABLE!${C_RESET}                                 ${C_PURPLE}│${C_RESET}"
            echo -e "${C_PURPLE}  │${C_RESET}                                                           ${C_PURPLE}│${C_RESET}"
            echo -e "${C_PURPLE}  │${C_RESET}  ${C_CYAN}Installed Version :${C_RESET} $(get_current_version_tag)"
            echo -e "${C_PURPLE}  │${C_RESET}  ${C_CYAN}Latest Version    :${C_RESET} ${C_GREEN}${BANNER_CACHE_REMOTE_VER}${C_RESET}"
            echo -e "${C_PURPLE}  │${C_RESET}  ${C_CYAN}Default Channel   :${C_RESET} ${C_CYAN}${friendly_branch} (${branch_name})${C_RESET}"
            echo -e "${C_PURPLE}  │${C_RESET}                                                           ${C_PURPLE}│${C_RESET}"
            echo -e "${C_PURPLE}  ╰───────────────────────────────────────────────────────────╯${C_RESET}"
            echo
            echo -e "  ${C_CYAN}Updating automatically...${C_RESET}"
            echo
            trigger_standalone_update_page
        fi
    else
        _check_remote_ver_bg
    fi
}

_fm_license_check
require_interactive_terminal
sync_runtime_components_if_needed
check_auto_update
main_menu
